CREATE TABLE app_private.user_account_operations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    idempotency_key uuid NOT NULL,
    target_user_id uuid NOT NULL,
    requested_by uuid NOT NULL,
    action text NOT NULL,
    status text DEFAULT 'PREPARED'::text NOT NULL,
    reason text NOT NULL,
    auth_id uuid,
    before_state jsonb DEFAULT '{}'::jsonb NOT NULL,
    auth_result jsonb DEFAULT '{}'::jsonb NOT NULL,
    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT user_account_operations_action_check CHECK ((action = ANY (ARRAY['DISABLE'::text, 'REACTIVATE'::text]))),
    CONSTRAINT user_account_operations_status_check CHECK ((status = ANY (ARRAY['PREPARED'::text, 'DB_APPLIED'::text, 'AUTH_RETRY'::text, 'COMPLETED'::text])))
);


--
-- Name: account_operation_response(app_private.user_account_operations); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.account_operation_response(p_operation app_private.user_account_operations) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'operationId', p_operation.id,
    'idempotencyKey', p_operation.idempotency_key,
    'targetUserId', p_operation.target_user_id,
    'requestedBy', p_operation.requested_by,
    'action', p_operation.action,
    'status', p_operation.status,
    'reason', p_operation.reason,
    'authId', p_operation.auth_id,
    'authResult', p_operation.auth_result,
    'revocationSummary',
      coalesce(p_operation.before_state -> 'revocationSummary', '{}'::jsonb)
      || jsonb_build_object(
        'businessRoleAssignments',
        coalesce(
          (p_operation.before_state ->> 'businessRoleAssignmentsRevoked')::integer,
          0
        )
      ),
    'lastError', p_operation.last_error,
    'createdAt', p_operation.created_at,
    'updatedAt', p_operation.updated_at,
    'completedAt', p_operation.completed_at
  );
$$;


--
-- Name: act_on_request(uuid, text, text, jsonb, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.act_on_request(p_request_id uuid, p_action text, p_comment text DEFAULT NULL::text, p_form_data jsonb DEFAULT NULL::jsonb, p_assignee_user_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions'
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_request public.request_instances%rowtype;
  v_subject public.workflow_subjects%rowtype;
  v_instance public.workflow_instances%rowtype;
  v_assignment public.workflow_step_assignments%rowtype;
  v_existing app_private.request_command_idempotency%rowtype;
  v_assignment_round uuid;
  v_block_key text;
  v_flow_mode text;
  v_completion_policy text;
  v_current_complete boolean := false;
  v_all_complete boolean := false;
  v_next_block_key text;
  v_result jsonb;
  v_payload_hash text;
  v_pending_count integer;
  v_approved_count integer;
  v_current_sort integer;
  v_pending_user_ids uuid[] := '{}'::uuid[];
  v_all_pending_user_ids uuid[] := '{}'::uuid[];
begin
  if v_actor is null then
    raise exception using errcode = 'P0001', message = 'REQUEST_ACTION_FORBIDDEN';
  end if;
  if not exists (
    select 1
    from public.users app_user
    where app_user.id = v_actor
      and coalesce(app_user.is_active, true)
      and coalesce(app_user.account_status, 'ACTIVE') = 'ACTIVE'
  ) then
    raise exception using errcode = 'P0001', message = 'REQUEST_ACTION_FORBIDDEN';
  end if;
  if p_action not in ('APPROVE', 'REJECT', 'RETURN', 'RESUBMIT', 'CANCEL', 'REASSIGN') then
    raise exception using errcode = 'P0001', message = 'REQUEST_ACTION_FORBIDDEN';
  end if;
  if nullif(trim(coalesce(p_idempotency_key, '')), '') is null then
    raise exception using errcode = 'P0001', message = 'REQUEST_IDEMPOTENCY_CONFLICT';
  end if;
  v_payload_hash := encode(digest(jsonb_build_object(
    'requestId', p_request_id, 'action', p_action, 'comment', p_comment,
    'formData', p_form_data, 'assigneeUserId', p_assignee_user_id,
    'expectedUpdatedAt', p_expected_updated_at
  )::text, 'sha256'), 'hex');
  insert into app_private.request_command_idempotency(
    actor_id, idempotency_key, command_name, request_id, payload_hash
  ) values (v_actor, p_idempotency_key, 'act_on_request', p_request_id, v_payload_hash)
  on conflict (actor_id, idempotency_key) do nothing;
  select * into v_existing
  from app_private.request_command_idempotency
  where actor_id = v_actor and idempotency_key = p_idempotency_key
  for update;
  if v_existing.command_name <> 'act_on_request' or v_existing.payload_hash <> v_payload_hash then
    raise exception using errcode = 'P0001', message = 'REQUEST_IDEMPOTENCY_CONFLICT';
  end if;
  if v_existing.result is not null then
    return v_existing.result;
  end if;

  -- Required lock order: request -> subject -> assignments.
  select * into v_request from public.request_instances
  where id = p_request_id for update;
  if not found then
    raise exception using errcode = 'P0001', message = 'REQUEST_NOT_FOUND_OR_FORBIDDEN';
  end if;
  if p_expected_updated_at is null or v_request.updated_at is distinct from p_expected_updated_at then
    raise exception using errcode = 'P0001', message = 'REQUEST_STALE_STATE';
  end if;
  select * into v_subject from public.workflow_subjects
  where id = v_request.workflow_subject_id for update;
  select * into v_instance from public.workflow_instances
  where id = v_request.workflow_instance_id for update;
  perform 1 from public.workflow_step_assignments assignment
  where assignment.workflow_subject_id = v_request.workflow_subject_id
  order by assignment.id
  for update;

  select v_request.approval_config_snapshot ->> 'flowMode',
         v_request.approval_config_snapshot ->> 'completionPolicy'
    into v_flow_mode, v_completion_policy;
  select assignment.* into v_assignment
  from public.workflow_step_assignments assignment
  where assignment.workflow_subject_id = v_request.workflow_subject_id
    and assignment.assignee_user_id = v_actor
    and assignment.status = 'PENDING'
  order by assignment.id
  limit 1;

  if not found and p_action = 'REASSIGN' and app_private.request_action_is_admin(v_actor) then
    select assignment.* into v_assignment
    from public.workflow_step_assignments assignment
    where assignment.workflow_subject_id = v_request.workflow_subject_id
      and assignment.status = 'PENDING'
    order by assignment.id
    limit 1;
  end if;

  if p_action = 'REASSIGN' and not found then
    raise exception using errcode = 'P0001', message = 'REQUEST_ASSIGNMENT_NOT_ACTIVE';
  end if;

  if p_action in ('APPROVE', 'REJECT', 'RETURN') and not found then
    raise exception using errcode = 'P0001', message = 'REQUEST_ASSIGNMENT_NOT_ACTIVE';
  end if;
  v_block_key := v_assignment.metadata ->> 'requestBlockKey';
  v_assignment_round := v_assignment.assignment_round_id;

  if p_action = 'APPROVE' then
    update public.workflow_step_assignments
    set status = 'APPROVED', acted_at = now(), action_comment = p_comment
    where id = v_assignment.id and status = 'PENDING';
    if not found then
      raise exception using errcode = 'P0001', message = 'REQUEST_ALREADY_PROCESSED';
    end if;

    select count(*) filter (where status = 'PENDING'),
           count(*) filter (where status = 'APPROVED')
      into v_pending_count, v_approved_count
    from public.workflow_step_assignments assignment
    where assignment.workflow_subject_id = v_request.workflow_subject_id
      and assignment.assignment_round_id = v_assignment_round
      and (
        v_flow_mode = 'PARALLEL'
        or assignment.metadata ->> 'requestBlockKey' = v_block_key
      );
    if v_completion_policy = 'ANY_ONE' and v_approved_count > 0 then
      perform app_private.close_request_pending_assignments(
        p_request_id, 'SKIPPED', v_assignment_round,
        case when v_flow_mode = 'PARALLEL' then null else v_block_key end,
        p_comment
      );
      v_pending_count := 0;
    end if;
    v_current_complete := v_pending_count = 0;

    select count(*) = 0 into v_all_complete
    from public.workflow_step_assignments assignment
    where assignment.workflow_subject_id = v_request.workflow_subject_id
      and assignment.assignment_round_id = v_assignment_round
      and assignment.status = 'PENDING';

    if v_flow_mode = 'PARALLEL' then
      if v_all_complete then
        update public.request_instances
        set status = 'APPROVED', completed_at = now(), updated_at = now()
        where id = p_request_id;
        update public.workflow_subjects set status = 'COMPLETED', updated_at = now()
        where id = v_subject.id;
        update public.workflow_instances set status = 'COMPLETED'::public.workflow_instance_status,
          updated_at = now() where id = v_instance.id;
      end if;
    elsif v_current_complete then
      select block.sort_order into v_current_sort
      from public.request_approval_blocks block
      where block.request_template_version_id = v_request.request_template_version_id
        and block.block_key = v_block_key;
      select block.block_key into v_next_block_key
      from public.request_approval_blocks block
      where block.request_template_version_id = v_request.request_template_version_id
        and block.sort_order > coalesce(v_current_sort, 0)
      order by block.sort_order, block.block_key
      limit 1;
      if v_next_block_key is null then
        update public.request_instances set status = 'APPROVED', completed_at = now(), updated_at = now()
        where id = p_request_id;
        update public.workflow_subjects set status = 'COMPLETED', updated_at = now()
        where id = v_subject.id;
        update public.workflow_instances set status = 'COMPLETED'::public.workflow_instance_status,
          updated_at = now() where id = v_instance.id;
      else
        perform app_private.activate_request_block(p_request_id, v_next_block_key, v_assignment_round, v_actor);
      end if;
    end if;
    insert into public.workflow_instance_logs(instance_id, node_id, action, acted_by, comment)
    values (v_instance.id, v_subject.current_node_id, 'APPROVED'::public.workflow_instance_action, v_actor, p_comment);

  elsif p_action = 'REJECT' then
    if nullif(trim(coalesce(p_comment, '')), '') is null then
      raise exception using errcode = 'P0001', message = 'REQUEST_ACTION_FORBIDDEN';
    end if;
    update public.workflow_step_assignments
    set status = 'REJECTED', acted_at = now(), action_comment = p_comment
    where id = v_assignment.id;
    perform app_private.close_request_pending_assignments(p_request_id, 'CANCELLED', null, null, p_comment);
    update public.request_instances set status = 'REJECTED', completed_at = now(), updated_at = now()
    where id = p_request_id;
    update public.workflow_subjects set status = 'REJECTED', updated_at = now() where id = v_subject.id;
    update public.workflow_instances set status = 'REJECTED'::public.workflow_instance_status, updated_at = now()
    where id = v_instance.id;
    insert into public.workflow_instance_logs(instance_id, node_id, action, acted_by, comment)
    values (v_instance.id, v_subject.current_node_id, 'REJECTED'::public.workflow_instance_action, v_actor, p_comment);

  elsif p_action = 'RETURN' then
    if nullif(trim(coalesce(p_comment, '')), '') is null then
      raise exception using errcode = 'P0001', message = 'REQUEST_ACTION_FORBIDDEN';
    end if;
    update public.workflow_step_assignments
    set status = 'RETURNED', acted_at = now(), action_comment = p_comment,
        metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('returnedBlockKey', v_block_key)
    where id = v_assignment.id;
    perform app_private.close_request_pending_assignments(
      p_request_id,
      'CANCELLED',
      v_assignment_round,
      case when v_flow_mode = 'PARALLEL' then null else v_block_key end,
      p_comment
    );
    update public.request_instances
    set status = 'RETURNED', approval_config_snapshot = coalesce(approval_config_snapshot, '{}'::jsonb)
      || jsonb_build_object('returnedBlockKey', v_block_key), updated_at = now()
    where id = p_request_id;
    update public.workflow_subjects set status = 'RETURNED', updated_at = now() where id = v_subject.id;
    update public.workflow_instances set status = 'RUNNING'::public.workflow_instance_status, updated_at = now()
    where id = v_instance.id;
    insert into public.workflow_instance_logs(instance_id, node_id, action, acted_by, comment)
    values (v_instance.id, v_subject.current_node_id, 'REVISION_REQUESTED'::public.workflow_instance_action, v_actor, p_comment);

  elsif p_action = 'RESUBMIT' then
    if v_request.created_by <> v_actor or v_request.status <> 'RETURNED' then
      raise exception using errcode = 'P0001', message = 'REQUEST_ACTION_FORBIDDEN';
    end if;
    v_block_key := v_request.approval_config_snapshot ->> 'returnedBlockKey';
    if v_block_key is null then
      raise exception using errcode = 'P0001', message = 'REQUEST_ACTION_FORBIDDEN';
    end if;
    v_assignment_round := gen_random_uuid();
    update public.request_instances
    set status = 'PENDING', form_data = coalesce(p_form_data, form_data),
        approval_config_snapshot = jsonb_set(
          approval_config_snapshot - 'returnedBlockKey',
          '{assignmentRoundId}', to_jsonb(v_assignment_round), true
        ), updated_at = now()
    where id = p_request_id;
    perform app_private.activate_request_block(p_request_id, v_block_key, v_assignment_round, v_actor);
    update public.workflow_subjects set status = 'RUNNING', updated_at = now() where id = v_subject.id;
    insert into public.workflow_instance_logs(instance_id, node_id, action, acted_by, comment)
    values (v_instance.id, v_subject.current_node_id, 'REOPENED'::public.workflow_instance_action, v_actor, p_comment);

  elsif p_action = 'CANCEL' then
    if not (v_request.created_by = v_actor or app_private.request_action_is_admin(v_actor))
       or v_request.status in ('APPROVED', 'REJECTED', 'CANCELLED') then
      raise exception using errcode = 'P0001', message = 'REQUEST_ACTION_FORBIDDEN';
    end if;
    perform app_private.close_request_pending_assignments(p_request_id, 'CANCELLED', null, null, p_comment);
    update public.request_instances set status = 'CANCELLED', completed_at = now(), updated_at = now()
    where id = p_request_id;
    update public.workflow_subjects set status = 'CANCELLED', updated_at = now() where id = v_subject.id;
    update public.workflow_instances set status = 'CANCELLED'::public.workflow_instance_status, updated_at = now()
    where id = v_instance.id;
    insert into public.workflow_instance_logs(instance_id, node_id, action, acted_by, comment)
    values (v_instance.id, v_subject.current_node_id, 'REJECTED'::public.workflow_instance_action, v_actor, p_comment);

  elsif p_action = 'REASSIGN' then
    if not app_private.request_action_is_admin(v_actor)
       or p_assignee_user_id is null
       or nullif(trim(coalesce(p_comment, '')), '') is null then
      raise exception using errcode = 'P0001', message = 'REQUEST_ACTION_FORBIDDEN';
    end if;
    if not exists (
      select 1 from public.users app_user
      where app_user.id = p_assignee_user_id
        and coalesce(app_user.is_active, true)
        and coalesce(app_user.account_status, 'ACTIVE') = 'ACTIVE'
    ) then
      raise exception using errcode = 'P0001', message = 'REQUEST_APPROVER_INACTIVE';
    end if;
    update public.workflow_step_assignments
    set status = 'CANCELLED', acted_at = now(), action_comment = p_comment
    where id = v_assignment.id;
    insert into public.workflow_step_assignments(
      workflow_subject_id, workflow_instance_id, node_id, instance_node_id,
      assignee_user_id, assigned_by, status, assigned_at, due_at, sla_hours,
      assignment_source, assignment_group_type, assignment_group_id,
      assignment_round_id, metadata
    ) values (
      v_assignment.workflow_subject_id, v_assignment.workflow_instance_id,
      v_assignment.node_id, v_assignment.instance_node_id, p_assignee_user_id,
      v_actor, 'PENDING', now(), v_assignment.due_at, v_assignment.sla_hours,
      v_assignment.assignment_source, v_assignment.assignment_group_type,
      v_assignment.assignment_group_id, v_assignment.assignment_round_id,
      coalesce(v_assignment.metadata, '{}'::jsonb) || jsonb_build_object('reassignedFrom', v_assignment.assignee_user_id)
    );
    select coalesce(array_agg(assignment.assignee_user_id order by assignment.id), '{}'::uuid[])
      into v_pending_user_ids
    from public.workflow_step_assignments assignment
    where assignment.workflow_subject_id = v_assignment.workflow_subject_id
      and assignment.assignment_round_id = v_assignment.assignment_round_id
      and assignment.metadata ->> 'requestBlockKey' = v_block_key
      and assignment.status = 'PENDING';
    select coalesce(array_agg(assignment.assignee_user_id order by assignment.id), '{}'::uuid[])
      into v_all_pending_user_ids
    from public.workflow_step_assignments assignment
    where assignment.workflow_subject_id = v_assignment.workflow_subject_id
      and assignment.assignment_round_id = v_assignment.assignment_round_id
      and assignment.status = 'PENDING';
    update public.workflow_subjects
    set current_assignee_user_id = v_all_pending_user_ids[1],
        current_assignee_user_ids = v_all_pending_user_ids,
        current_node_id = v_assignment.node_id,
        current_instance_node_id = v_assignment.instance_node_id,
        updated_at = now()
    where id = v_assignment.workflow_subject_id;
    update public.workflow_instances
    set current_node_id = v_assignment.node_id,
        current_instance_node_id = v_assignment.instance_node_id,
        step_assignees = coalesce(step_assignees, '{}'::jsonb)
          || jsonb_build_object(v_assignment.node_id::text, to_jsonb(v_pending_user_ids)),
        updated_at = now()
    where id = v_assignment.workflow_instance_id;
    update public.request_instances request_instance
    set approval_config_snapshot = jsonb_set(
      coalesce(request_instance.approval_config_snapshot, '{}'::jsonb),
      '{blocks}',
      coalesce((
        select jsonb_agg(
          case
            when block ->> 'key' = v_block_key
            then jsonb_set(block, '{resolvedUserIds}', to_jsonb(v_pending_user_ids), true)
            else block
          end
          order by block_order
        )
        from jsonb_array_elements(
          coalesce(request_instance.approval_config_snapshot -> 'blocks', '[]'::jsonb)
        ) with ordinality as block_items(block, block_order)
      ), '[]'::jsonb),
      true
    ), updated_at = now()
    where request_instance.id = p_request_id;
    perform app_private.project_workflow_register_participant(
      v_assignment.workflow_subject_id, v_assignment.workflow_instance_id,
      p_assignee_user_id, 'ASSIGNEE', 'request_reassign', v_block_key,
      v_assignment.node_id, v_assignment.instance_node_id, v_actor
    );
    insert into app_private.request_notification_outbox(
      event_key, request_id, recipient_user_id, event_type, payload
    ) values (
      'request:' || p_request_id::text || ':REASSIGN:' || p_assignee_user_id::text || ':' || now()::text,
      p_request_id, p_assignee_user_id, 'REQUEST_APPROVAL_REQUIRED',
      jsonb_build_object('requestId', p_request_id, 'requestCode', v_request.code,
        'blockKey', v_block_key, 'reassigned', true)
    ) on conflict (event_key) do nothing;
    insert into public.workflow_instance_logs(instance_id, node_id, action, acted_by, comment)
    values (
      v_assignment.workflow_instance_id,
      v_assignment.node_id,
      'REASSIGNED'::public.workflow_instance_action,
      v_actor,
      'REASSIGNED: ' || p_comment
    );
  end if;

  update public.request_instances set updated_at = now() where id = p_request_id;

  -- Keep notification delivery out of the transaction: every successful
  -- command records one creator-facing event for the asynchronous worker.
  insert into app_private.request_notification_outbox(
    event_key, request_id, recipient_user_id, event_type, payload
  ) values (
    'request:' || p_request_id::text || ':ACTION:' || p_action || ':' || p_idempotency_key,
    p_request_id, v_request.created_by, 'REQUEST_ACTION_APPLIED',
    jsonb_build_object('requestId', p_request_id, 'requestCode', v_request.code,
      'action', p_action, 'comment', p_comment)
  ) on conflict (event_key) do nothing;

  select * into v_request from public.request_instances where id = p_request_id;
  v_result := jsonb_build_object(
    'requestId', v_request.id,
    'requestCode', v_request.code,
    'status', v_request.status,
    'workflowInstanceId', v_request.workflow_instance_id,
    'workflowSubjectId', v_request.workflow_subject_id,
    'currentBlockKeys', app_private.request_action_current_blocks(p_request_id),
    'updatedAt', v_request.updated_at
  );
  update app_private.request_command_idempotency set result = v_result where id = v_existing.id;
  return v_result;
end;
$$;


--
-- Name: activate_request_block(uuid, text, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.activate_request_block(p_request_id uuid, p_block_key text, p_round_id uuid, p_actor_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request public.request_instances%rowtype;
  v_block record;
  v_version public.request_template_versions%rowtype;
  v_workflow_version public.workflow_template_versions%rowtype;
  v_node_id uuid;
  v_instance_node_id uuid;
  v_user_id uuid;
  v_user_ids uuid[] := '{}'::uuid[];
  v_due_at timestamptz;
begin
  select * into v_request
  from public.request_instances
  where id = p_request_id
  for update;
  if not found then
    raise exception using errcode = 'P0001', message = 'REQUEST_NOT_FOUND_OR_FORBIDDEN';
  end if;

  select * into v_version
  from public.request_template_versions
  where id = v_request.request_template_version_id;
  select * into v_workflow_version
  from public.workflow_template_versions
  where id = v_request.workflow_template_version_id;
  select block.*,
         snapshot_block -> 'resolvedUserIds' as resolved_user_ids
    into v_block
  from public.request_approval_blocks block
  left join lateral jsonb_array_elements(
    coalesce(v_request.approval_config_snapshot -> 'blocks', '[]'::jsonb)
  ) snapshot_block
    on snapshot_block ->> 'key' = block.block_key
  where block.request_template_version_id = v_request.request_template_version_id
    and block.block_key = p_block_key
  order by block.sort_order
  limit 1;
  if not found then
    raise exception using errcode = 'P0001', message = 'REQUEST_APPROVAL_BLOCK_NOT_FOUND';
  end if;

  select coalesce(array_agg(value::uuid order by value::uuid), '{}'::uuid[])
    into v_user_ids
  from jsonb_array_elements_text(coalesce(v_block.resolved_user_ids, '[]'::jsonb)) value;
  if cardinality(v_user_ids) = 0 then
    raise exception using errcode = 'P0001', message = 'REQUEST_APPROVER_REQUIRED';
  end if;

  select node.id into v_node_id
  from public.workflow_nodes node
  where node.template_id = v_workflow_version.template_id
    and node.type = 'APPROVAL'::public.workflow_node_type
    and node.config ->> 'requestBlockKey' = p_block_key
  order by node.position_x, node.id
  limit 1;
  select instance_node.id into v_instance_node_id
  from public.workflow_instance_nodes instance_node
  where instance_node.workflow_instance_id = v_request.workflow_instance_id
    and instance_node.template_node_id = v_node_id
  limit 1;

  if v_block.sla_hours is not null then
    v_due_at := now() + make_interval(hours => v_block.sla_hours::integer);
  end if;
  foreach v_user_id in array v_user_ids loop
    insert into public.workflow_step_assignments(
      workflow_subject_id, workflow_instance_id, node_id, instance_node_id,
      assignee_user_id, assigned_by, status, assigned_at, due_at, sla_hours,
      assignment_source, assignment_group_type, assignment_group_id,
      assignment_round_id, metadata
    ) values (
      v_request.workflow_subject_id, v_request.workflow_instance_id,
      v_node_id, v_instance_node_id, v_user_id, p_actor_id, 'PENDING', now(),
      v_due_at, v_block.sla_hours::integer, v_block.approver_source,
      'REQUEST_BLOCK', p_block_key, p_round_id,
      jsonb_build_object('requestId', p_request_id, 'requestBlockKey', p_block_key)
    );
    perform app_private.project_workflow_register_participant(
      v_request.workflow_subject_id, v_request.workflow_instance_id, v_user_id,
      'ASSIGNEE', 'request_block', p_block_key, v_node_id,
      v_instance_node_id, p_actor_id
    );
    insert into app_private.request_notification_outbox(
      event_key, request_id, recipient_user_id, event_type, payload
    ) values (
      'request:' || p_request_id::text || ':BLOCK:' || p_round_id::text || ':' || p_block_key || ':' || v_user_id::text,
      p_request_id, v_user_id, 'REQUEST_APPROVAL_REQUIRED',
      jsonb_build_object('requestId', p_request_id, 'requestCode', v_request.code,
        'blockKey', p_block_key)
    ) on conflict (event_key) do nothing;
  end loop;

  update public.workflow_instances
  set current_node_id = v_node_id,
      current_instance_node_id = v_instance_node_id,
      step_assignees = coalesce(step_assignees, '{}'::jsonb)
        || jsonb_build_object(v_node_id::text, to_jsonb(v_user_ids)),
      status = 'RUNNING'::public.workflow_instance_status,
      updated_at = now()
  where id = v_request.workflow_instance_id;

  update public.workflow_subjects
  set current_node_id = v_node_id,
      current_instance_node_id = v_instance_node_id,
      current_assignee_user_id = v_user_ids[1],
      current_assignee_user_ids = v_user_ids,
      status = 'RUNNING',
      updated_at = now()
  where id = v_request.workflow_subject_id;
end;
$$;


--
-- Name: adjust_hrm_staffing(uuid, uuid, text, uuid, integer, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.adjust_hrm_staffing(p_org_unit_id uuid, p_position_id uuid, p_level_code text, p_reports_to_slot_id uuid, p_target_count integer, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid;
  v_unit public.org_units%rowtype;
  v_position public.hrm_positions%rowtype;
  v_current_count integer := 0;
  v_occupied_count integer := 0;
  v_change_count integer := 0;
  v_requested_remove integer := 0;
  v_level_code text := nullif(trim(p_level_code), '');
  v_index integer;
  v_code text;
begin
  if not app_private.current_user_has_hrm_template_permission('hrm.staffing.manage') then
    raise exception using errcode = '42501', message = 'HRM_STAFFING_MANAGE_REQUIRED';
  end if;
  v_actor_id := public.current_app_user_id();
  if v_actor_id is null then
    raise exception using errcode = '42501', message = 'HRM_ACTIVE_ACTOR_REQUIRED';
  end if;
  if p_target_count is null or p_target_count < 0 then
    raise exception using errcode = '22023', message = 'HRM_STAFFING_TARGET_INVALID';
  end if;

  select * into v_unit
  from public.org_units
  where id = p_org_unit_id and is_active
  for update;
  if v_unit.id is null then
    raise exception using errcode = '22023', message = 'HRM_ACTIVE_ORG_UNIT_NOT_FOUND';
  end if;

  select * into v_position
  from public.hrm_positions
  where id = p_position_id and is_active
  for update;
  if v_position.id is null then
    raise exception using errcode = '22023', message = 'HRM_ACTIVE_POSITION_NOT_FOUND';
  end if;

  if v_level_code is not null and not exists (
    select 1 from public.hrm_position_levels level
    where level.code = v_level_code and level.is_active
  ) then
    raise exception using errcode = '22023', message = 'HRM_ACTIVE_LEVEL_NOT_FOUND';
  end if;

  if p_reports_to_slot_id is not null and not exists (
    select 1 from public.hrm_org_position_slots manager_slot
    where manager_slot.id = p_reports_to_slot_id
      and manager_slot.status = 'ACTIVE'
  ) then
    raise exception using errcode = '22023', message = 'HRM_ACTIVE_REPORTING_SLOT_NOT_FOUND';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      pg_catalog.concat_ws('|', p_org_unit_id::text, p_position_id::text,
        coalesce(v_level_code, ''), coalesce(p_reports_to_slot_id::text, '')),
      0
    )
  );

  select count(*)::integer,
         count(assignment.id)::integer
  into v_current_count, v_occupied_count
  from public.hrm_org_position_slots slot
  left join public.hrm_employee_slot_assignments assignment
    on assignment.slot_id = slot.id
   and assignment.status = 'ACTIVE'
   and assignment.assignment_type in ('PRIMARY', 'ACTING')
  where slot.source = 'workforce_plan'
    and slot.status = 'ACTIVE'
    and slot.org_unit_id = p_org_unit_id
    and slot.position_id = p_position_id
    and slot.level_code is not distinct from v_level_code
    and slot.reports_to_slot_id is not distinct from p_reports_to_slot_id;

  if p_target_count > v_current_count then
    for v_index in 1..(p_target_count - v_current_count) loop
      v_code := 'WF-' ||
        left(regexp_replace(upper(coalesce(v_unit.code, 'ORG')), '[^A-Z0-9]+', '', 'g'), 12) || '-' ||
        left(regexp_replace(upper(coalesce(v_position.code, 'POS')), '[^A-Z0-9]+', '', 'g'), 12) || '-' ||
        left(replace(gen_random_uuid()::text, '-', ''), 8);

      insert into public.hrm_org_position_slots (
        code, org_unit_id, position_id, level_code, reports_to_slot_id,
        slot_type, status, description, effective_from, sort_order, source,
        created_by, updated_by
      ) values (
        v_code, p_org_unit_id, p_position_id, v_level_code, p_reports_to_slot_id,
        'STANDARD', 'ACTIVE', nullif(trim(p_note), ''), current_date,
        v_current_count + v_index, 'workforce_plan', v_actor_id, v_actor_id
      );
      v_change_count := v_change_count + 1;
    end loop;
  elsif p_target_count < v_current_count then
    v_requested_remove := v_current_count - p_target_count;

    with vacant_candidates as (
      select slot.id
      from public.hrm_org_position_slots slot
      where slot.source = 'workforce_plan'
        and slot.status = 'ACTIVE'
        and slot.org_unit_id = p_org_unit_id
        and slot.position_id = p_position_id
        and slot.level_code is not distinct from v_level_code
        and slot.reports_to_slot_id is not distinct from p_reports_to_slot_id
        and slot.id is distinct from v_unit.manager_slot_id
        and not exists (
          select 1
          from public.hrm_employee_slot_assignments assignment
          where assignment.slot_id = slot.id
            and assignment.status = 'ACTIVE'
            and assignment.assignment_type in ('PRIMARY', 'ACTING')
        )
      order by slot.id
      for update skip locked
      limit v_requested_remove
    ), archived as (
      update public.hrm_org_position_slots slot
      set status = 'ARCHIVED',
          effective_to = greatest(slot.effective_from, current_date),
          description = concat_ws(E'\n', nullif(slot.description, ''), nullif(trim(p_note), '')),
          updated_by = v_actor_id,
          updated_at = now()
      where slot.id in (select candidate.id from vacant_candidates candidate)
      returning slot.id
    )
    select count(*)::integer into v_change_count from archived;

    if v_change_count <> v_requested_remove then
      raise exception using errcode = '55000', message = 'HRM_STAFFING_HAS_OCCUPIED_OR_MANAGER_SLOTS';
    end if;
  end if;

  insert into public.audit_trail (
    table_name, record_id, action, old_data, new_data, user_id, module,
    description, record_label, entity_type, changed_fields, change_count,
    impact_level, context
  ) values (
    'hrm_org_position_slots', p_org_unit_id::text, 'UPDATE',
    jsonb_build_object('planned_count', v_current_count, 'occupied_count', v_occupied_count),
    jsonb_build_object('planned_count', p_target_count,
      'occupied_count', least(v_occupied_count, p_target_count)),
    v_actor_id::text, 'HRM', 'Điều chỉnh định biên nhân sự',
    v_unit.name || ' — ' || v_position.name, 'HRM_WORKFORCE_STAFFING',
    array['planned_count'], v_change_count, 'high',
    jsonb_build_object('note', nullif(trim(p_note), ''), 'level_code', v_level_code,
      'reports_to_slot_id', p_reports_to_slot_id)
  );

  return jsonb_build_object(
    'org_unit_id', p_org_unit_id,
    'position_id', p_position_id,
    'level_code', v_level_code,
    'reports_to_slot_id', p_reports_to_slot_id,
    'planned_count', p_target_count,
    'occupied_count', least(v_occupied_count, p_target_count),
    'vacant_count', greatest(p_target_count - v_occupied_count, 0),
    'changed_count', v_change_count
  );
end;
$$;


--
-- Name: adjust_hrm_staffing(uuid, uuid, text, uuid, integer, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.adjust_hrm_staffing(p_org_unit_id uuid, p_position_id uuid, p_level_code text, p_reports_to_slot_id uuid, p_target_count integer, p_note text, p_source_reference text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_result jsonb;
begin
  perform app_private.assert_hrm_mutation_context(p_note, p_source_reference);
  v_result := app_private.adjust_hrm_staffing(
    p_org_unit_id, p_position_id, p_level_code, p_reports_to_slot_id,
    p_target_count, p_note
  );
  perform app_private.annotate_hrm_workforce_audit('HRM_WORKFORCE_STAFFING', p_source_reference);
  return v_result;
end;
$$;


--
-- Name: current_app_user_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_app_user_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select u.id
  from public.users u
  where (
      u.auth_id = (select auth.uid())
      or (
        u.auth_id is null
        and lower(u.email) = lower(coalesce((select auth.jwt() ->> 'email'), ''))
      )
    )
    and u.is_active
    and u.account_status = 'ACTIVE'
  order by case when u.auth_id = (select auth.uid()) then 0 else 1 end
  limit 1;
$$;


--
-- Name: ai_has_action(text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.ai_has_action(p_permission_code text, p_user_id uuid DEFAULT public.current_app_user_id()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_user_id is not null
    and p_permission_code like 'ai.%'
    and app_private.global_has_action(p_permission_code, 'AI', p_user_id);
$$;


--
-- Name: analytics_has_action(text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.analytics_has_action(p_permission_code text, p_user_id uuid DEFAULT public.current_app_user_id()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_user_id is not null
    and p_permission_code like 'analytics.%'
    and app_private.global_has_action(p_permission_code, 'ANALYTICS', p_user_id);
$$;


--
-- Name: annotate_hrm_workforce_audit(text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.annotate_hrm_workforce_audit(p_entity_type text, p_source_reference text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  update public.audit_trail
  set context = coalesce(context, '{}'::jsonb)
    || jsonb_build_object('source_reference', pg_catalog.btrim(p_source_reference))
  where xmin = pg_catalog.pg_current_xact_id()::text::xid
    and user_id = public.current_app_user_id()::text
    and entity_type = p_entity_type;
$$;


--
-- Name: ap_scope_can_mutate(text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.ap_scope_can_mutate(p_project_id text, p_construction_site_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    public.is_admin()
    or public.is_module_admin('DA')
    or app_private.company_procurement_can_manage()
    or app_private.project_user_has_permission(p_project_id, p_construction_site_id, 'edit')
    or app_private.project_user_has_permission(p_project_id, p_construction_site_id, 'submit')
    or app_private.project_user_has_permission(p_project_id, p_construction_site_id, 'approve')
    or app_private.project_user_has_permission(p_project_id, p_construction_site_id, 'confirm')
    or app_private.material_has_action(p_project_id, p_construction_site_id, 'project.material_direct_purchase.create', public.current_app_user_id())
    or app_private.material_has_action(p_project_id, p_construction_site_id, 'project.material_direct_purchase.edit', public.current_app_user_id())
    or app_private.material_has_action(p_project_id, p_construction_site_id, 'project.material_direct_purchase.delete', public.current_app_user_id())
    or app_private.material_has_action(p_project_id, p_construction_site_id, 'project.material_direct_purchase.record_ap', public.current_app_user_id())
    or app_private.material_has_action(p_project_id, p_construction_site_id, 'project.material_supplier_delivery.create', public.current_app_user_id())
    or app_private.material_has_action(p_project_id, p_construction_site_id, 'project.material_supplier_delivery.edit', public.current_app_user_id())
    or app_private.material_has_action(p_project_id, p_construction_site_id, 'project.material_supplier_delivery.delete', public.current_app_user_id())
    or app_private.material_has_action(p_project_id, p_construction_site_id, 'project.material_supplier_delivery.record', public.current_app_user_id())
    or app_private.material_has_action(p_project_id, p_construction_site_id, 'project.material_supplier_delivery.unrecord', public.current_app_user_id())
    or app_private.material_has_action(p_project_id, p_construction_site_id, 'project.material_supplier_delivery.reconcile', public.current_app_user_id()),
    false
  );
$$;


--
-- Name: ap_scope_can_view(text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.ap_scope_can_view(p_project_id text, p_construction_site_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    public.is_admin()
    or public.is_module_admin('DA')
    or app_private.company_procurement_can_manage()
    or app_private.project_doc_can_view(p_project_id, p_construction_site_id, null),
    false
  );
$$;


--
-- Name: apply_project_gantt_forecast_impl(uuid, text, text, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.apply_project_gantt_forecast_impl(p_request_id uuid, p_project_id text, p_construction_site_id text, p_revision jsonb, p_revision_tasks jsonb, p_task_changes jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid;
  v_site_id text := nullif(btrim(coalesce(p_construction_site_id, '')), '');
  v_replay jsonb;
  v_revision public.project_schedule_revisions%rowtype;
  v_task_ids text[];
  v_event_ids text[];
  v_result jsonb;
begin
  v_actor_user_id := app_private.assert_project_gantt_action(p_project_id, v_site_id, 'edit');
  if jsonb_typeof(coalesce(p_revision_tasks, 'null'::jsonb)) <> 'array'
    or jsonb_typeof(coalesce(p_task_changes, 'null'::jsonb)) <> 'array'
    or jsonb_array_length(p_task_changes) = 0 then
    raise exception 'GANTT_INVALID_PAYLOAD' using errcode = '22023';
  end if;
  v_replay := app_private.begin_project_gantt_command(
    v_actor_user_id, p_request_id, 'apply_project_gantt_forecast',
    md5(jsonb_build_object('projectId', p_project_id, 'constructionSiteId', v_site_id,
      'revision', p_revision, 'revisionTasks', p_revision_tasks,
      'taskChanges', p_task_changes)::text)
  );
  if v_replay is not null then return v_replay; end if;

  select array_agg(change ->> 'id' order by change ->> 'id') into v_task_ids
  from jsonb_array_elements(p_task_changes) change;
  select coalesce(array_agg(event_id order by event_id), '{}'::text[]) into v_event_ids
  from jsonb_array_elements_text(coalesce(p_revision -> 'source_delay_event_ids', '[]'::jsonb)) event_id;

  perform task.id from public.project_tasks task
  where task.id = any(v_task_ids) order by task.id for update;
  perform event.id from public.project_delay_events event
  where event.id = any(v_event_ids) order by event.id for update;

  if cardinality(v_task_ids) <> (select count(*) from public.project_tasks task
      where task.id = any(v_task_ids) and task.project_id = p_project_id
        and task.construction_site_id is not distinct from v_site_id)
    or exists (
      select 1 from jsonb_array_elements(p_task_changes) change
      join public.project_tasks task on task.id = change ->> 'id'
      where nullif(change ->> 'expected_row_version', '') is null
        or task.row_version <> (change ->> 'expected_row_version')::bigint
    ) then
    raise exception 'GANTT_STALE_VERSION' using errcode = '40001';
  end if;
  if cardinality(v_event_ids) <> (select count(*) from public.project_delay_events event
      where event.id = any(v_event_ids) and event.project_id = p_project_id
        and event.construction_site_id is not distinct from v_site_id
        and event.status in ('reported', 'accepted')) then
    raise exception 'GANTT_SCOPE_MISMATCH' using errcode = '23514';
  end if;

  insert into public.project_schedule_revisions (
    id, project_id, construction_site_id, reason, source_delay_event_ids,
    applied_by, applied_at
  ) values (
    coalesce(nullif(p_revision ->> 'id', ''), gen_random_uuid()::text),
    p_project_id, v_site_id, nullif(p_revision ->> 'reason', ''), v_event_ids,
    v_actor_user_id::text, now()
  ) returning * into v_revision;

  insert into public.project_schedule_revision_tasks (
    id, revision_id, task_id, task_name_snapshot, before_start, before_end,
    before_duration, after_start, after_end, after_duration, delta_days,
    was_critical, float_before
  )
  select coalesce(nullif(item ->> 'id', ''), gen_random_uuid()::text),
    v_revision.id, nullif(item ->> 'task_id', ''),
    coalesce(item ->> 'task_name_snapshot', ''), item ->> 'before_start',
    item ->> 'before_end', coalesce((item ->> 'before_duration')::integer, 0),
    item ->> 'after_start', item ->> 'after_end',
    coalesce((item ->> 'after_duration')::integer, 0),
    coalesce((item ->> 'delta_days')::integer, 0),
    coalesce((item ->> 'was_critical')::boolean, false),
    coalesce((item ->> 'float_before')::integer, 0)
  from jsonb_array_elements(p_revision_tasks) item;

  update public.project_tasks task
  set start_date = change ->> 'start_date',
      end_date = change ->> 'end_date',
      duration = (change ->> 'duration')::integer
  from jsonb_array_elements(p_task_changes) change
  where task.id = change ->> 'id';

  update public.project_delay_events event
  set status = 'applied', resolved_at = now()
  where event.id = any(v_event_ids);

  v_result := jsonb_build_object(
    'ok', true, 'requestId', p_request_id, 'replayed', false,
    'revision', to_jsonb(v_revision),
    'tasks', (select coalesce(jsonb_agg(to_jsonb(task) order by task.id), '[]'::jsonb)
      from public.project_tasks task where task.id = any(v_task_ids)),
    'delayEvents', (select coalesce(jsonb_agg(to_jsonb(event) order by event.id), '[]'::jsonb)
      from public.project_delay_events event where event.id = any(v_event_ids))
  );
  return app_private.finish_project_gantt_command(v_actor_user_id, p_request_id, v_result);
end;
$$;


--
-- Name: apply_user_permission_change_impl(uuid, text, jsonb, jsonb, text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.apply_user_permission_change_impl(p_user_id uuid, p_expected_fingerprint text, p_legacy_state jsonb, p_grants jsonb, p_reason text, p_warning_acceptances jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid;
  v_target public.users%rowtype;
  v_preview jsonb;
  v_before_fingerprint text;
  v_after_fingerprint text;
  v_legacy_before jsonb;
  v_legacy_after jsonb;
  v_direct_before jsonb;
  v_direct_after jsonb;
  v_decision jsonb;
  v_reason text := btrim(coalesce(p_reason, ''));
  v_previous_command_context text;
  v_changed boolean;
begin
  v_actor_user_id := app_private.assert_authorization_permission(
    'system.authorization.manage_grants'
  );

  select *
  into v_target
  from public.users
  where id = p_user_id
  for update;

  if v_target.id is null
    or not v_target.is_active
    or v_target.account_status <> 'ACTIVE'
    or v_target.role = 'ADMIN'::public.user_role
  then
    raise exception 'Active non-Admin target user required'
      using errcode = '23514';
  end if;

  v_before_fingerprint := app_private.user_permission_state_fingerprint(p_user_id);
  if p_expected_fingerprint is null
    or p_expected_fingerprint is distinct from v_before_fingerprint
  then
    raise exception 'Permission state changed after Preview'
      using errcode = '40001';
  end if;

  v_preview := app_private.preview_user_permission_change_impl(
    p_user_id,
    p_legacy_state,
    p_grants
  );
  v_legacy_before := v_preview -> 'legacyBefore';
  v_legacy_after := v_preview -> 'legacyAfter';
  v_direct_before := v_preview -> 'directBefore';
  v_direct_after := v_preview -> 'directAfter';
  v_decision := v_preview -> 'decision';
  v_changed := v_legacy_before is distinct from v_legacy_after
    or v_direct_before is distinct from v_direct_after;

  if v_changed and char_length(v_reason) < 10 then
    raise exception 'Unified permission change reason required'
      using errcode = '22023';
  end if;

  if v_changed and app_private.permission_hardening_flag('legacy_projection_enabled') then
    raise exception 'Legacy projection must be disabled before unified permission Save'
      using errcode = '55000';
  end if;

  if v_changed then
    perform app_private.replace_user_permission_grants_v2_impl(
      p_user_id,
      p_grants,
      v_reason,
      p_warning_acceptances
    );

    if v_legacy_before is distinct from v_legacy_after then
      v_previous_command_context := current_setting(
        'app.authorization_permission_command',
        true
      );
      perform set_config('app.authorization_permission_command', 'on', true);

      update public.users
      set allowed_modules = array(
            select value
            from jsonb_array_elements_text(v_legacy_after -> 'allowedModules') value
          ),
          allowed_sub_modules = v_legacy_after -> 'allowedSubModules',
          admin_modules = array(
            select value
            from jsonb_array_elements_text(v_legacy_after -> 'adminModules') value
          ),
          admin_sub_modules = v_legacy_after -> 'adminSubModules',
          updated_at = now()
      where id = p_user_id;

      perform set_config(
        'app.authorization_permission_command',
        coalesce(v_previous_command_context, ''),
        true
      );

      insert into public.permission_audit_events (
        actor_user_id,
        target_user_id,
        event_type,
        before_grants,
        after_grants,
        metadata
      ) values (
        v_actor_user_id,
        p_user_id,
        'unified_legacy_permissions_changed',
        v_legacy_before,
        v_legacy_after,
        jsonb_build_object(
          'reason', v_reason,
          'decision', v_decision
        )
      );
    end if;
  end if;

  v_after_fingerprint := app_private.permission_state_fingerprint_for_values(
    v_legacy_after,
    v_direct_after
  );

  return jsonb_build_object(
    'beforeFingerprint', v_before_fingerprint,
    'afterFingerprint', v_after_fingerprint,
    'decision', v_decision,
    'legacyBefore', v_legacy_before,
    'legacyAfter', v_legacy_after,
    'directAfter', v_direct_after
  );
end;
$$;


--
-- Name: approve_material_po_batch(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.approve_material_po_batch(p_delivery_batch_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := coalesce(p_actor_user_id, public.current_app_user_id());
  v_batch public.purchase_order_delivery_batches%rowtype;
  v_po public.purchase_orders%rowtype;
  v_result jsonb;
begin
  if public.current_app_user_id() is null or v_actor <> public.current_app_user_id() then
    raise exception 'Người thực hiện lệnh không hợp lệ.' using errcode = '42501';
  end if;

  select * into v_batch
  from public.purchase_order_delivery_batches
  where id = p_delivery_batch_id
  for update;
  if not found then
    raise exception 'Không tìm thấy đợt giao.' using errcode = '22023';
  end if;
  select * into v_po
  from public.purchase_orders
  where id = v_batch.purchase_order_id
  for update;

  if coalesce(v_po.source_mode, '') <> 'from_request'
     or coalesce(v_po.purchase_mode, '') <> 'multiple' then
    raise exception 'Chỉ duyệt từng đợt cho PO vật tư giao nhiều lần.' using errcode = '22023';
  end if;
  perform app_private.assert_project_permission_room_action(
    v_po.project_id, v_po.construction_site_id, 'material_po', 'approve', v_actor
  );
  if not public.is_admin() and v_batch.approval_assignee_user_id is distinct from v_actor then
    raise exception 'Chỉ người được giao duyệt đợt mới có thể duyệt.' using errcode = '42501';
  end if;

  if coalesce(v_batch.approval_status, 'draft') = 'approved'
     and v_batch.wms_transaction_id is not null then
    return app_private.ensure_material_po_batch_wms(v_batch.id, v_actor)
      || jsonb_build_object('approvalStatus', 'approved');
  end if;
  if coalesce(v_batch.approval_status, 'draft') not in ('pending_approval', 'approved')
     or (v_batch.wms_transaction_id is not null and v_batch.approval_status <> 'approved') then
    raise exception 'Chỉ duyệt đợt đang chờ duyệt hoặc khôi phục đợt đã duyệt thiếu WMS.'
      using errcode = '22023';
  end if;

  perform app_private.assert_material_po_batch_overage_reason(v_po.id, v_batch.id);
  v_result := app_private.ensure_material_po_batch_wms(v_batch.id, v_actor);

  update public.purchase_order_delivery_batches
  set approval_status = 'approved',
      approval_decided_by = coalesce(approval_decided_by, v_actor),
      approval_decided_at = coalesce(approval_decided_at, now()),
      approval_decision_note = null,
      updated_at = now()
  where id = v_batch.id;

  return v_result || jsonb_build_object('approvalStatus', 'approved');
end;
$$;


--
-- Name: approve_material_po_quality(uuid, text, uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.approve_material_po_quality(p_delivery_batch_id uuid, p_wms_transaction_id text, p_actor_user_id uuid, p_quality_result text, p_lines jsonb, p_attachments jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_po_id text;
  v_batch public.purchase_order_delivery_batches%rowtype;
  v_tx public.transactions%rowtype;
  v_line jsonb;
  v_delivery_line public.purchase_order_delivery_lines%rowtype;
  v_delivery_line_id uuid;
  v_item_id text;
  v_delivered_purchase_qty numeric;
  v_accepted_purchase_qty numeric;
  v_delivered_stock_qty numeric;
  v_accepted_stock_qty numeric;
  v_variance_reason text;
  v_seen_line_ids uuid[] := '{}'::uuid[];
  v_expected_line_count integer;
  v_wms_items jsonb := '[]'::jsonb;
  v_gross numeric := 0;
  v_combined_reason text;
  v_stock_factor numeric;
  v_stock_unit_price numeric;
begin
  if p_actor_user_id is null
     or public.current_app_user_id() is null
     or p_actor_user_id <> public.current_app_user_id() then
    raise exception 'Người thực hiện lệnh không hợp lệ.' using errcode = '42501';
  end if;
  if p_quality_result not in ('passed', 'partial', 'rejected') then
    raise exception 'Kết quả kiểm tra SL/CL không hợp lệ.' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_lines, '[]'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_attachments, '[]'::jsonb)) <> 'array' then
    raise exception 'Dữ liệu nhận hàng không hợp lệ.' using errcode = '22023';
  end if;

  select batch.purchase_order_id into v_po_id
  from public.purchase_order_delivery_batches batch
  where batch.id = p_delivery_batch_id;
  if not found then
    raise exception 'Không tìm thấy đợt giao.' using errcode = '22023';
  end if;

  perform 1 from public.purchase_orders where id = v_po_id for update;
  select * into v_batch
  from public.purchase_order_delivery_batches
  where id = p_delivery_batch_id
  for update;
  if v_batch.wms_transaction_id is distinct from p_wms_transaction_id
     or v_batch.status <> 'receiving' then
    raise exception 'Đợt giao không còn ở trạng thái chờ duyệt SL/CL.' using errcode = '22023';
  end if;

  select * into v_tx
  from public.transactions
  where id = p_wms_transaction_id
  for update;
  if not found
     or v_tx.source_type <> 'po_delivery_batch'
     or v_tx.source_id <> p_delivery_batch_id::text then
    raise exception 'WMS không liên kết đúng đợt giao.' using errcode = '22023';
  end if;
  if v_tx.status <> 'PENDING'::public.transaction_status then
    raise exception 'Phiếu WMS không còn chờ duyệt SL/CL.' using errcode = '22023';
  end if;
  if not app_private.current_user_can_receive_purchase_batch_v2(
    p_actor_user_id,
    v_tx.target_warehouse_id
  ) then
    raise exception 'Người dùng không có quyền duyệt SL/CL tại kho nhận.' using errcode = '42501';
  end if;

  select count(*) into v_expected_line_count
  from public.purchase_order_delivery_lines
  where delivery_batch_id = p_delivery_batch_id;
  if v_expected_line_count = 0
     or jsonb_array_length(p_lines) <> v_expected_line_count then
    raise exception 'Payload nhận hàng phải khớp 1-1 với dòng đợt giao.' using errcode = '22023';
  end if;

  for v_line in
    select value from jsonb_array_elements(p_lines) line(value)
  loop
    v_delivery_line_id := nullif(coalesce(
      v_line ->> 'deliveryLineId', v_line ->> 'delivery_line_id'
    ), '')::uuid;
    v_item_id := nullif(coalesce(v_line ->> 'itemId', v_line ->> 'item_id'), '');
    v_accepted_purchase_qty := coalesce(nullif(coalesce(
      v_line ->> 'acceptedPurchaseQty', v_line ->> 'accepted_purchase_qty'
    ), '')::numeric, 0);
    v_delivered_purchase_qty := coalesce(nullif(coalesce(
      v_line ->> 'deliveredPurchaseQty', v_line ->> 'delivered_purchase_qty'
    ), '')::numeric, v_accepted_purchase_qty);
    v_accepted_stock_qty := coalesce(nullif(coalesce(
      v_line ->> 'acceptedStockQty', v_line ->> 'accepted_stock_qty'
    ), '')::numeric, 0);
    v_delivered_stock_qty := coalesce(nullif(coalesce(
      v_line ->> 'deliveredStockQty', v_line ->> 'delivered_stock_qty'
    ), '')::numeric, v_accepted_stock_qty);
    v_variance_reason := nullif(trim(coalesce(
      v_line ->> 'varianceReason', v_line ->> 'variance_reason', ''
    )), '');

    if v_delivery_line_id is null or v_item_id is null then
      raise exception 'Dòng nhận hàng thiếu deliveryLineId hoặc itemId.' using errcode = '22023';
    end if;
    if v_delivery_line_id = any(v_seen_line_ids) then
      raise exception 'Dòng nhận hàng bị lặp.' using errcode = '22023';
    end if;
    if v_delivered_purchase_qty < 0
       or v_accepted_purchase_qty < 0
       or v_delivered_stock_qty < 0
       or v_accepted_stock_qty < 0 then
      raise exception 'Số lượng thực tế không được âm.' using errcode = '22023';
    end if;
    if v_accepted_purchase_qty > v_delivered_purchase_qty then
      raise exception 'Số chấp nhận không được lớn hơn số giao thực tế.' using errcode = '22023';
    end if;
    if v_accepted_stock_qty > v_delivered_stock_qty then
      raise exception 'Số nhập kho không được lớn hơn số giao theo đơn vị tồn kho.' using errcode = '22023';
    end if;

    select * into v_delivery_line
    from public.purchase_order_delivery_lines
    where id = v_delivery_line_id
      and delivery_batch_id = p_delivery_batch_id
    for update;
    if not found or v_delivery_line.item_id <> v_item_id then
      raise exception 'Dòng nhận hàng không thuộc đợt giao.' using errcode = '22023';
    end if;

    if (
      v_delivered_purchase_qty is distinct from coalesce(v_delivery_line.planned_qty, 0)
      or v_accepted_purchase_qty is distinct from v_delivered_purchase_qty
      or v_accepted_stock_qty is distinct from v_delivered_stock_qty
    ) and v_variance_reason is null then
      raise exception 'Phải nhập lý do khi số đặt, giao hoặc chấp nhận chênh lệch.' using errcode = '22023';
    end if;

    update public.purchase_order_delivery_lines
    set delivered_qty = v_delivered_purchase_qty,
        accepted_qty = v_accepted_purchase_qty,
        delivered_stock_qty = v_delivered_stock_qty,
        accepted_stock_qty = v_accepted_stock_qty,
        updated_at = now()
    where id = v_delivery_line.id;

    v_seen_line_ids := array_append(v_seen_line_ids, v_delivery_line.id);
    if v_variance_reason is not null then
      v_combined_reason := concat_ws('; ', v_combined_reason, v_variance_reason);
    end if;
    v_stock_factor := case
      when coalesce(v_delivery_line.planned_qty, 0) > 0
        and coalesce(v_delivery_line.stock_planned_qty, 0) > 0 then
          v_delivery_line.stock_planned_qty / v_delivery_line.planned_qty
      else 1
    end;
    v_stock_unit_price := case
      when v_stock_factor > 0 then coalesce(v_delivery_line.delivery_unit_price, 0) / v_stock_factor
      else coalesce(v_delivery_line.delivery_unit_price, 0)
    end;
    v_gross := v_gross
      + v_accepted_purchase_qty
      * coalesce(v_delivery_line.delivery_unit_price, 0)
      * (1 + coalesce(v_batch.vat_rate, 0) / 100);

    v_wms_items := v_wms_items || jsonb_build_array(jsonb_build_object(
      'itemId', v_delivery_line.item_id,
      'quantity', v_accepted_stock_qty,
      'orderedQty', coalesce(v_delivery_line.stock_planned_qty, v_delivery_line.planned_qty, 0),
      'deliveredStockQty', v_delivered_stock_qty,
      'price', v_stock_unit_price,
      'accountingQty', v_accepted_purchase_qty,
      'orderedPurchaseQty', v_delivery_line.planned_qty,
      'deliveredPurchaseQty', v_delivered_purchase_qty,
      'accountingUnit', coalesce(v_delivery_line.unit, v_delivery_line.stock_unit, ''),
      'accountingPrice', coalesce(v_delivery_line.delivery_unit_price, 0),
      'varianceQty', v_accepted_purchase_qty - coalesce(v_delivery_line.planned_qty, 0),
      'varianceReason', v_variance_reason,
      'purchaseOrderLineId', v_delivery_line.purchase_order_line_id,
      'purchaseOrderDeliveryBatchId', p_delivery_batch_id,
      'purchaseOrderDeliveryLineId', v_delivery_line.id,
      'fulfillmentMode', coalesce(v_batch.fulfillment_mode, 'RECEIVE_TO_STOCK')
    ));
  end loop;

  if coalesce(array_length(v_seen_line_ids, 1), 0) <> v_expected_line_count then
    raise exception 'Payload nhận hàng thiếu dòng đợt giao.' using errcode = '22023';
  end if;

  update public.transactions
  set items = v_wms_items,
      attachments = coalesce(p_attachments, '[]'::jsonb),
      status = 'APPROVED'::public.transaction_status,
      approver_id = p_actor_user_id,
      approved_at = now()
  where id = p_wms_transaction_id;

  update public.purchase_order_delivery_batches
  set status = 'quality_approved',
      quality_result = p_quality_result,
      variance_reason = v_combined_reason,
      quality_approved_by = p_actor_user_id,
      quality_approved_at = now(),
      accepted_gross_amount = round(v_gross, 2),
      updated_at = now()
  where id = p_delivery_batch_id;

  return app_private.purchase_receipt_command_result_v2(p_delivery_batch_id, false);
end;
$$;


--
-- Name: approve_purchase_package_and_prepare_single_batch_v2(text, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.approve_purchase_package_and_prepare_single_batch_v2(p_purchase_order_id text, p_actor_user_id uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_po public.purchase_orders%rowtype;
  v_existing_delivery public.purchase_order_delivery_batches%rowtype;
  v_previous_guard text;
  v_item jsonb;
  v_lines jsonb := '[]'::jsonb;
  v_line_id text;
  v_item_id text;
  v_purchase_qty numeric;
  v_purchase_unit text;
  v_stock_unit text;
  v_conversion_factor numeric;
  v_purchase_unit_price numeric;
  v_delivery_result jsonb;
begin
  if p_actor_user_id is null then
    raise exception 'Nguoi thuc hien lenh khong hop le.' using errcode = '42501';
  end if;
  if public.current_app_user_id() is null or p_actor_user_id <> public.current_app_user_id() then
    raise exception 'Nguoi thuc hien lenh khong hop le.' using errcode = '42501';
  end if;
  if p_idempotency_key is null then
    raise exception 'Idempotency key is required.' using errcode = '22023';
  end if;

  select * into v_po
  from public.purchase_orders
  where id = p_purchase_order_id
  for update;
  if not found then
    raise exception 'Khong tim thay Goi mua hang %.', p_purchase_order_id using errcode = '22023';
  end if;
  if coalesce(v_po.source_mode, '') <> 'from_request' then
    raise exception 'Chi duyet Goi mua hang V2 tao tu MR.' using errcode = '22023';
  end if;
  if coalesce(v_po.purchase_mode, 'single') not in ('single', 'multiple') then
    raise exception 'Purchase mode khong hop le: %', v_po.purchase_mode using errcode = '22023';
  end if;
  if coalesce(v_po.fulfillment_mode, '') not in ('RECEIVE_TO_STOCK', 'DIRECT_CONSUMPTION') then
    raise exception 'Goi mua hang thieu snapshot hinh thuc nhan hang.' using errcode = '22023';
  end if;
  if v_po.status not in ('sent', 'confirmed') then
    raise exception 'Chi duyet Goi mua hang dang cho duyet.' using errcode = '22023';
  end if;

  perform app_private.assert_project_permission_room_action(
    v_po.project_id,
    v_po.construction_site_id,
    'material_po',
    'approve',
    p_actor_user_id
  );

  if v_po.status <> 'confirmed' then
    v_previous_guard := current_setting('app.material_transition_context', true);
    perform set_config('app.material_transition_context', 'on', true);

    update public.purchase_orders
    set status = 'confirmed',
        ever_submitted = true,
        last_action_by = p_actor_user_id::text,
        last_action_at = now()
    where id = p_purchase_order_id
    returning * into v_po;

    perform set_config('app.material_transition_context', coalesce(v_previous_guard, ''), true);
  end if;

  if coalesce(v_po.purchase_mode, 'single') in ('single', 'multiple') then
    select * into v_existing_delivery
    from public.purchase_order_delivery_batches
    where purchase_order_id = p_purchase_order_id
      and idempotency_key = p_idempotency_key
    for update;

    if found then
      v_delivery_result := app_private.prepare_planned_purchase_delivery_batch_with_wms_qr_v2(
        v_existing_delivery.id,
        p_actor_user_id,
        p_idempotency_key
      );
    else
      select * into v_existing_delivery
      from public.purchase_order_delivery_batches
      where purchase_order_id = p_purchase_order_id
        and status <> 'cancelled'
      order by delivery_no, id
      limit 1
      for update;

      if found then
        v_delivery_result := app_private.prepare_planned_purchase_delivery_batch_with_wms_qr_v2(
          v_existing_delivery.id,
          p_actor_user_id,
          p_idempotency_key
        );
      end if;
    end if;
  end if;

  if coalesce(v_po.purchase_mode, 'single') = 'single' and v_delivery_result is null then
    for v_item in
      select value from jsonb_array_elements(coalesce(v_po.items, '[]'::jsonb)) as po_item(value)
    loop
      v_line_id := nullif(coalesce(v_item ->> 'lineId', v_item ->> 'itemId'), '');
      v_item_id := nullif(v_item ->> 'itemId', '');
      v_purchase_qty := coalesce(nullif(v_item ->> 'qty', '')::numeric, 0);
      v_purchase_unit := nullif(v_item ->> 'purchaseUnitSnapshot', '');
      v_stock_unit := nullif(coalesce(v_item ->> 'stockUnitSnapshot', v_item ->> 'unitSnapshot'), '');
      v_conversion_factor := coalesce(nullif(v_item ->> 'purchaseConversionFactor', '')::numeric, 0);
      v_purchase_unit_price := coalesce(nullif(v_item ->> 'unitPrice', '')::numeric, 0);

      if v_line_id is null or v_item_id is null then
        raise exception 'Dong Goi mua hang thieu PO line hoac vat tu.' using errcode = '22023';
      end if;
      if v_purchase_qty <= 0 then
        raise exception 'So luong Goi mua hang phai lon hon 0.' using errcode = '22023';
      end if;
      if v_purchase_unit is null or v_stock_unit is null or v_conversion_factor <= 0 then
        raise exception 'Goi mua hang thieu snapshot quy doi don vi.' using errcode = '22023';
      end if;
      if v_purchase_unit_price < 0 then
        raise exception 'Don gia Goi mua hang khong duoc am.' using errcode = '22023';
      end if;

      v_lines := v_lines || jsonb_build_array(jsonb_build_object(
        'purchaseOrderLineId', v_line_id,
        'itemId', v_item_id,
        'purchaseQty', v_purchase_qty,
        'purchaseUnit', v_purchase_unit,
        'stockQty', v_purchase_qty * v_conversion_factor,
        'stockUnit', v_stock_unit,
        'purchaseUnitPrice', v_purchase_unit_price,
        'stockUnitPrice', v_purchase_unit_price / v_conversion_factor
      ));
    end loop;

    v_delivery_result := app_private.create_delivery_batch_with_wms_qr_core_v2(
      v_po.id,
      p_idempotency_key,
      v_po.vendor_id,
      v_po.vendor_name,
      v_po.fulfillment_mode,
      coalesce(v_po.vat_rate, 0),
      v_po.target_warehouse_id,
      current_date,
      'Dot giao tu dong khi duyet Goi mua hang',
      p_actor_user_id,
      v_lines
    );
  end if;

  return jsonb_strip_nulls(jsonb_build_object(
    'purchaseOrderId', v_po.id,
    'status', 'confirmed',
    'purchaseMode', coalesce(v_po.purchase_mode, 'single'),
    'delivery', v_delivery_result
  ));
exception
  when others then
    perform set_config('app.material_transition_context', coalesce(v_previous_guard, ''), true);
    raise;
end;
$$;


--
-- Name: approve_receipt_quality_v2(uuid, text, uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.approve_receipt_quality_v2(p_delivery_batch_id uuid, p_wms_transaction_id text, p_actor_user_id uuid, p_quality_result text, p_lines jsonb, p_attachments jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_po_id text;
  v_po public.purchase_orders%rowtype;
  v_batch public.purchase_order_delivery_batches%rowtype;
  v_tx public.transactions%rowtype;
  v_line jsonb;
  v_delivery_line public.purchase_order_delivery_lines%rowtype;
  v_delivery_line_id uuid;
  v_item_id text;
  v_accepted_purchase_qty numeric;
  v_accepted_stock_qty numeric;
  v_expected_stock_qty numeric;
  v_stock_factor numeric;
  v_variance_reason text;
  v_seen_line_ids uuid[] := '{}'::uuid[];
  v_expected_line_count integer;
  v_wms_items jsonb := '[]'::jsonb;
  v_gross numeric := 0;
  v_combined_reason text;
  v_variance_qty numeric;
  v_stock_unit_price numeric;
begin
  if p_actor_user_id is null then
    raise exception 'Nguoi thuc hien lenh khong hop le.' using errcode = '42501';
  end if;
  if public.current_app_user_id() is null or p_actor_user_id <> public.current_app_user_id() then
    raise exception 'Nguoi thuc hien lenh khong hop le.' using errcode = '42501';
  end if;
  if p_quality_result not in ('passed', 'partial', 'rejected') then
    raise exception 'Ket qua kiem tra SL/CL khong hop le.' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_lines, '[]'::jsonb)) <> 'array' then
    raise exception 'Dong nhan hang khong hop le.' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_attachments, '[]'::jsonb)) <> 'array' then
    raise exception 'Dinh kem nhan hang khong hop le.' using errcode = '22023';
  end if;

  select purchase_order_id into v_po_id
  from public.purchase_order_delivery_batches
  where id = p_delivery_batch_id;
  if not found then
    raise exception 'Khong tim thay Dot giao %.', p_delivery_batch_id using errcode = '22023';
  end if;

  select * into v_po
  from public.purchase_orders
  where id = v_po_id
  for update;
  if not found then
    raise exception 'Khong tim thay Goi mua hang cua Dot giao %.', p_delivery_batch_id using errcode = '22023';
  end if;

  select * into v_batch
  from public.purchase_order_delivery_batches
  where id = p_delivery_batch_id
  for update;
  if not found then
    raise exception 'Khong tim thay Dot giao %.', p_delivery_batch_id using errcode = '22023';
  end if;
  if v_batch.wms_transaction_id is distinct from p_wms_transaction_id then
    raise exception 'WMS transaction khong khop Dot giao.' using errcode = '22023';
  end if;
  if v_batch.status <> 'receiving' then
    raise exception 'Dot giao da khoa hoac khong con cho duyet SL/CL.' using errcode = '22023';
  end if;

  select * into v_tx
  from public.transactions
  where id = p_wms_transaction_id
  for update;
  if not found then
    raise exception 'Khong tim thay WMS cua Dot giao.' using errcode = '22023';
  end if;
  if v_tx.source_type <> 'po_delivery_batch' or v_tx.source_id <> p_delivery_batch_id::text then
    raise exception 'WMS khong lien ket dung Dot giao.' using errcode = '22023';
  end if;
  if v_tx.status <> 'PENDING'::public.transaction_status then
    raise exception 'Phieu WMS da khoa va khong con cho duyet SL/CL.' using errcode = '22023';
  end if;
  if not app_private.current_user_can_receive_purchase_batch_v2(p_actor_user_id, v_tx.target_warehouse_id) then
    raise exception 'Nguoi dung khong co quyen duyet SL/CL tai kho nhan.' using errcode = '42501';
  end if;

  select count(*) into v_expected_line_count
  from public.purchase_order_delivery_lines
  where delivery_batch_id = p_delivery_batch_id;
  if v_expected_line_count = 0 or jsonb_array_length(p_lines) <> v_expected_line_count then
    raise exception 'Payload nhan hang phai khop 1-1 voi dong Dot giao.' using errcode = '22023';
  end if;

  for v_line in
    select value from jsonb_array_elements(p_lines) as line(value)
  loop
    v_delivery_line_id := nullif(coalesce(v_line ->> 'deliveryLineId', v_line ->> 'delivery_line_id'), '')::uuid;
    v_item_id := nullif(coalesce(v_line ->> 'itemId', v_line ->> 'item_id'), '');
    v_accepted_purchase_qty := coalesce(
      nullif(coalesce(v_line ->> 'acceptedPurchaseQty', v_line ->> 'accepted_purchase_qty'), '')::numeric,
      0
    );
    v_accepted_stock_qty := coalesce(
      nullif(coalesce(v_line ->> 'acceptedStockQty', v_line ->> 'accepted_stock_qty'), '')::numeric,
      0
    );
    v_variance_reason := nullif(trim(coalesce(v_line ->> 'varianceReason', v_line ->> 'variance_reason', '')), '');

    if v_delivery_line_id is null or v_item_id is null then
      raise exception 'Dong nhan hang thieu deliveryLineId hoac itemId.' using errcode = '22023';
    end if;
    if v_delivery_line_id = any(v_seen_line_ids) then
      raise exception 'Dong nhan hang bi lap.' using errcode = '22023';
    end if;
    if v_accepted_purchase_qty < 0 or v_accepted_stock_qty < 0 then
      raise exception 'So luong thuc nhan khong duoc am.' using errcode = '22023';
    end if;

    select * into v_delivery_line
    from public.purchase_order_delivery_lines
    where id = v_delivery_line_id
      and delivery_batch_id = p_delivery_batch_id
    for update;
    if not found then
      raise exception 'Dong nhan hang khong thuoc Dot giao.' using errcode = '22023';
    end if;
    if v_delivery_line.item_id <> v_item_id then
      raise exception 'Vat tu nhan hang khong khop dong Dot giao.' using errcode = '22023';
    end if;

    v_stock_factor := case
      when coalesce(v_delivery_line.planned_qty, 0) > 0
        and coalesce(v_delivery_line.stock_planned_qty, 0) > 0
        then v_delivery_line.stock_planned_qty / v_delivery_line.planned_qty
      else 1
    end;
    v_expected_stock_qty := round(v_accepted_purchase_qty * v_stock_factor, 6);
    if abs(v_expected_stock_qty - round(v_accepted_stock_qty, 6)) > 0.000001 then
      raise exception 'So luong ton kho thuc nhan khong khop snapshot quy doi.' using errcode = '22023';
    end if;
    if v_accepted_purchase_qty is distinct from coalesce(v_delivery_line.planned_qty, 0)
       and v_variance_reason is null then
      raise exception 'Phai nhap ly do khi so luong thuc nhan lech Dot giao.' using errcode = '22023';
    end if;

    update public.purchase_order_delivery_lines
    set accepted_qty = v_accepted_purchase_qty,
        accepted_stock_qty = v_accepted_stock_qty,
        updated_at = now()
    where id = v_delivery_line.id;

    v_seen_line_ids := array_append(v_seen_line_ids, v_delivery_line.id);
    v_variance_qty := v_accepted_purchase_qty - coalesce(v_delivery_line.planned_qty, 0);
    if v_variance_reason is not null then
      v_combined_reason := concat_ws('; ', v_combined_reason, v_variance_reason);
    end if;
    v_stock_unit_price := case
      when v_stock_factor > 0 then coalesce(v_delivery_line.delivery_unit_price, 0) / v_stock_factor
      else coalesce(v_delivery_line.delivery_unit_price, 0)
    end;
    v_gross := v_gross
      + v_accepted_purchase_qty
      * coalesce(v_delivery_line.delivery_unit_price, 0)
      * (1 + coalesce(v_batch.vat_rate, 0) / 100);

    v_wms_items := v_wms_items || jsonb_build_array(jsonb_build_object(
      'itemId', v_delivery_line.item_id,
      'quantity', v_accepted_stock_qty,
      'orderedQty', coalesce(v_delivery_line.stock_planned_qty, v_delivery_line.planned_qty, 0),
      'price', v_stock_unit_price,
      'accountingQty', v_accepted_purchase_qty,
      'accountingUnit', coalesce(v_delivery_line.unit, v_delivery_line.stock_unit, ''),
      'accountingPrice', coalesce(v_delivery_line.delivery_unit_price, 0),
      'varianceQty', v_variance_qty,
      'varianceReason', v_variance_reason,
      'purchaseOrderLineId', v_delivery_line.purchase_order_line_id,
      'purchaseOrderDeliveryBatchId', p_delivery_batch_id,
      'purchaseOrderDeliveryLineId', v_delivery_line.id,
      'fulfillmentMode', coalesce(v_batch.fulfillment_mode, 'RECEIVE_TO_STOCK')
    ));
  end loop;

  if coalesce(array_length(v_seen_line_ids, 1), 0) <> v_expected_line_count then
    raise exception 'Payload nhan hang thieu dong Dot giao.' using errcode = '22023';
  end if;

  update public.transactions
  set items = v_wms_items,
      attachments = coalesce(p_attachments, '[]'::jsonb),
      status = 'APPROVED'::public.transaction_status,
      approver_id = p_actor_user_id,
      approved_at = now()
  where id = p_wms_transaction_id;

  update public.purchase_order_delivery_batches
  set status = 'quality_approved',
      quality_result = p_quality_result,
      variance_reason = v_combined_reason,
      quality_approved_by = p_actor_user_id,
      quality_approved_at = now(),
      accepted_gross_amount = round(v_gross, 2),
      updated_at = now()
  where id = p_delivery_batch_id;

  return app_private.purchase_receipt_command_result_v2(p_delivery_batch_id, false);
end;
$$;


--
-- Name: assert_active_principal(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_active_principal(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_user_id is null or not exists (
    select 1
    from public.users u
    where u.id = p_user_id
      and u.is_active
      and u.account_status = 'ACTIVE'
  ) then
    raise exception 'Active application principal required'
      using errcode = '23514';
  end if;
end;
$$;


--
-- Name: assert_and_record_sod_warnings(jsonb, jsonb, text, uuid, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_and_record_sod_warnings(p_decision jsonb, p_acceptances jsonb, p_command_type text, p_command_id uuid, p_actor_user_id uuid, p_target_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_hard_denies jsonb := coalesce(p_decision -> 'hardDenies', '[]'::jsonb);
  v_warnings jsonb := coalesce(p_decision -> 'warnings', '[]'::jsonb);
  v_acceptances jsonb := coalesce(p_acceptances, '[]'::jsonb);
  v_warning jsonb;
  v_acceptance jsonb;
  v_owner_id uuid;
  v_expires_at timestamptz;
begin
  if p_actor_user_id is distinct from public.current_app_user_id()
    or not app_private.has_any_permission(
      public.current_app_user_id(),
      array[
        'system.authorization.manage_roles',
        'system.authorization.manage_grants'
      ],
      'global',
      '*'
    )
  then
    raise exception 'Authorization administration permission required'
      using errcode = '42501';
  end if;

  if jsonb_typeof(v_hard_denies) <> 'array'
    or jsonb_typeof(v_warnings) <> 'array'
    or jsonb_typeof(v_acceptances) <> 'array'
  then
    raise exception 'Invalid SoD decision or warning acceptances'
      using errcode = '22023';
  end if;

  if jsonb_array_length(v_hard_denies) > 0 then
    raise exception 'Authorization change violates a hard SoD rule'
      using errcode = '42501';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(v_acceptances) supplied
    group by
      supplied.value ->> 'ruleCode',
      supplied.value ->> 'scopeType',
      supplied.value ->> 'scopeId'
    having count(*) > 1
  ) then
    raise exception 'Duplicate SoD warning acknowledgement'
      using errcode = '22023';
  end if;

  for v_warning in
    select value
    from jsonb_array_elements(v_warnings)
  loop
    select value
    into v_acceptance
    from jsonb_array_elements(v_acceptances)
    where value ->> 'ruleCode' = v_warning ->> 'ruleCode'
      and value ->> 'scopeType' = v_warning ->> 'scopeType'
      and value ->> 'scopeId' = v_warning ->> 'scopeId'
    limit 1;

    if v_acceptance is null then
      raise exception 'SoD warning acknowledgement required'
        using errcode = '22023';
    end if;

    begin
      v_owner_id := nullif(v_acceptance ->> 'controlOwnerUserId', '')::uuid;
      v_expires_at := nullif(v_acceptance ->> 'expiresAt', '')::timestamptz;
    exception
      when invalid_text_representation or datetime_field_overflow then
        raise exception 'Invalid SoD warning control evidence'
          using errcode = '22023';
    end;

    if char_length(btrim(coalesce(v_acceptance ->> 'reason', ''))) < 10
      or char_length(btrim(coalesce(v_acceptance ->> 'compensatingControls', ''))) < 10
      or v_expires_at is null
      or v_expires_at <= now()
      or v_owner_id is null
      or v_owner_id = p_actor_user_id
      or v_owner_id = p_target_user_id
      or not exists (
        select 1
        from public.users owner_row
        where owner_row.id = v_owner_id
          and owner_row.is_active
          and owner_row.account_status = 'ACTIVE'
          and app_private.has_permission(
            owner_row.id,
            'system.authorization.audit',
            'global',
            '*'
          )
      )
    then
      raise exception 'Invalid SoD warning control evidence'
        using errcode = '22023';
    end if;

    insert into public.authorization_sod_warning_acceptances (
      rule_code,
      command_type,
      command_id,
      actor_user_id,
      target_user_id,
      scope_type,
      scope_id,
      reason,
      control_owner_user_id,
      compensating_controls,
      expires_at
    )
    values (
      v_warning ->> 'ruleCode',
      p_command_type,
      p_command_id,
      p_actor_user_id,
      p_target_user_id,
      v_warning ->> 'scopeType',
      v_warning ->> 'scopeId',
      btrim(v_acceptance ->> 'reason'),
      v_owner_id,
      btrim(v_acceptance ->> 'compensatingControls'),
      v_expires_at
    );
  end loop;

  if exists (
    select 1
    from jsonb_array_elements(v_acceptances) supplied
    where not exists (
      select 1
      from jsonb_array_elements(v_warnings) expected
      where expected ->> 'ruleCode' = supplied.value ->> 'ruleCode'
        and expected ->> 'scopeType' = supplied.value ->> 'scopeType'
        and expected ->> 'scopeId' = supplied.value ->> 'scopeId'
    )
  ) then
    raise exception 'Unexpected SoD warning acknowledgement'
      using errcode = '22023';
  end if;
end;
$$;


--
-- Name: assert_authorization_permission(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_authorization_permission(p_permission_code text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := public.current_app_user_id();
begin
  if v_actor_user_id is null
    or not app_private.has_permission(
      v_actor_user_id,
      p_permission_code,
      'global',
      '*'
    )
  then
    raise exception 'Authorization administration permission required'
      using errcode = '42501';
  end if;

  return v_actor_user_id;
end;
$$;


--
-- Name: hrm_import_batches; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hrm_import_batches (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source_file_path text NOT NULL,
    source_file_hash text NOT NULL,
    manifest jsonb DEFAULT '{}'::jsonb NOT NULL,
    status text DEFAULT 'UPLOADED'::text NOT NULL,
    total_rows integer DEFAULT 0 NOT NULL,
    valid_rows integer DEFAULT 0 NOT NULL,
    error_rows integer DEFAULT 0 NOT NULL,
    fingerprint text,
    applied_at timestamp with time zone,
    expires_at timestamp with time zone DEFAULT (now() + '30 days'::interval) NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT hrm_import_batches_manifest_check CHECK ((jsonb_typeof(manifest) = 'object'::text)),
    CONSTRAINT hrm_import_batches_status_check CHECK ((status = ANY (ARRAY['UPLOADED'::text, 'STAGED'::text, 'VALIDATED'::text, 'APPLIED'::text, 'FAILED'::text, 'CANCELLED'::text])))
);


--
-- Name: assert_hrm_import_owner(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_hrm_import_owner(p_batch_id uuid) RETURNS public.hrm_import_batches
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := public.current_app_user_id();
  v_batch public.hrm_import_batches%rowtype;
begin
  if not app_private.has_hrm_template_permission(v_actor_id, 'hrm.employee.import') then
    raise exception using errcode = '42501', message = 'HRM_EMPLOYEE_IMPORT_REQUIRED';
  end if;
  select batch.* into v_batch
  from public.hrm_import_batches batch
  where batch.id = p_batch_id and batch.created_by = v_actor_id;
  if not found then
    raise exception using errcode = 'P0002', message = 'HRM_IMPORT_BATCH_NOT_FOUND';
  end if;
  return v_batch;
end;
$$;


--
-- Name: assert_hrm_mutation_context(text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_hrm_mutation_context(p_reason text, p_source_reference text) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
begin
  if pg_catalog.length(pg_catalog.btrim(coalesce(p_reason, ''))) < 10 then
    raise exception using errcode = '22023', message = 'HRM_MUTATION_REASON_TOO_SHORT';
  end if;
  if pg_catalog.length(pg_catalog.btrim(coalesce(p_source_reference, ''))) = 0 then
    raise exception using errcode = '22023', message = 'HRM_MUTATION_SOURCE_REFERENCE_REQUIRED';
  end if;
end;
$$;


--
-- Name: assert_hrm_profile_section_access(uuid, text[]); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_hrm_profile_section_access(p_employee_id uuid, p_allowed_levels text[]) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_level text := app_private.hrm_employee_profile_access_level(p_employee_id);
begin
  if not (v_level = any(p_allowed_levels)) then
    raise exception using errcode = '42501', message = 'HRM_PROFILE_SECTION_ACCESS_DENIED';
  end if;
  return v_level;
end;
$$;


--
-- Name: assert_hrm_role_admin(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_hrm_role_admin() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := public.current_app_user_id();
begin
  if v_actor_user_id is null
    or not app_private.has_permission(
      v_actor_user_id,
      'system.authorization.manage_roles',
      'global',
      '*'
    )
    or not exists (
      select 1
      from public.users actor_row
      join public.principal_role_assignments assignment_row
        on assignment_row.principal_type = 'user'
       and assignment_row.principal_id = actor_row.id
       and assignment_row.status = 'ACTIVE'
       and assignment_row.starts_at <= now()
       and (assignment_row.expires_at is null or assignment_row.expires_at > now())
      join public.role_permission_templates template
        on template.id = assignment_row.role_template_id
       and template.code = 'SYSTEM_ADMIN'
       and template.is_active
      where actor_row.id = v_actor_user_id
        and actor_row.role = 'ADMIN'
        and actor_row.is_active
        and actor_row.account_status = 'ACTIVE'
    )
  then
    raise exception 'Active System Admin with role-management permission required'
      using errcode = '42501';
  end if;

  return v_actor_user_id;
end;
$$;


--
-- Name: assert_legacy_system_admin(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_legacy_system_admin(p_actor_user_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not exists (
    select 1
    from public.users u
    where u.id = p_actor_user_id
      and u.role = 'ADMIN'
      and u.is_active
      and u.account_status = 'ACTIVE'
  ) then
    raise exception 'Active System Admin required'
      using errcode = '42501';
  end if;
end;
$$;


--
-- Name: assert_material_po_batch_overage_reason(text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_material_po_batch_overage_reason(p_purchase_order_id text, p_delivery_batch_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if exists (
    with active_allocated as (
      select
        line.purchase_order_line_id,
        sum(coalesce(line.stock_planned_qty, line.planned_qty, 0)) as allocated_qty
      from public.purchase_order_delivery_batches batch
      join public.purchase_order_delivery_lines line on line.delivery_batch_id = batch.id
      where batch.purchase_order_id = p_purchase_order_id
        and batch.status <> 'cancelled'
        and (
          batch.id = p_delivery_batch_id
          or coalesce(batch.approval_status, 'draft') in ('pending_approval', 'approved')
        )
      group by line.purchase_order_line_id
    ), requested as (
      select
        coalesce(item.value ->> 'lineId', item.value ->> 'itemId') as line_id,
        coalesce(
          nullif(item.value ->> 'requestedQtySnapshot', '')::numeric,
          nullif(item.value ->> 'qty', '')::numeric,
          0
        ) as requested_qty
      from public.purchase_orders po
      cross join lateral jsonb_array_elements(coalesce(po.items, '[]'::jsonb)) item(value)
      where po.id = p_purchase_order_id
    )
    select 1
    from active_allocated allocated
    join requested on requested.line_id = allocated.purchase_order_line_id
    where allocated.allocated_qty > requested.requested_qty + 0.000001
  ) and not exists (
    select 1
    from public.purchase_order_delivery_batches batch
    where batch.purchase_order_id = p_purchase_order_id
      and batch.status <> 'cancelled'
      and (
        batch.id = p_delivery_batch_id
        or coalesce(batch.approval_status, 'draft') in ('pending_approval', 'approved')
      )
      and coalesce(trim(batch.variance_reason), '') <> ''
  ) then
    raise exception 'Tổng các đợt đang duyệt/đã duyệt vượt nhu cầu MR; phải nhập lý do.'
      using errcode = '22023';
  end if;
end;
$$;


--
-- Name: assert_material_request_room_recipients(text, uuid[], text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_material_request_room_recipients(p_request_id text, p_user_ids uuid[], p_action_code text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request public.requests%rowtype;
  v_user_id uuid;
begin
  select * into v_request from public.requests where id = p_request_id;
  if not found then raise exception 'material request not found: %', p_request_id; end if;
  if coalesce(array_length(p_user_ids, 1), 0) = 0 then
    raise exception 'Required workflow action has no active Room recipient' using errcode = '23514';
  end if;
  foreach v_user_id in array p_user_ids loop
    if not app_private.project_user_has_room_action(
      v_user_id, v_request.project_id, v_request.construction_site_id,
      'material_request', p_action_code
    ) or not app_private.project_user_has_room_action(
      v_user_id, v_request.project_id, v_request.construction_site_id,
      'material_request', 'view'
    ) then
      raise exception 'Người nhận không có đủ quyền view + % thuần trong Room Yêu cầu.', p_action_code
        using errcode = '42501';
    end if;
  end loop;
end;
$$;


--
-- Name: assert_multiple_delivery_batch_overage_reason_v1(text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_multiple_delivery_batch_overage_reason_v1(p_purchase_order_id text, p_delivery_batch_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_reason text;
begin
  select variance_reason into v_reason
  from public.purchase_order_delivery_batches
  where id = p_delivery_batch_id and purchase_order_id = p_purchase_order_id;

  if coalesce(trim(v_reason), '') <> '' then
    return;
  end if;

  if exists (
    with allocated as (
      select line.purchase_order_line_id, sum(coalesce(line.stock_planned_qty, 0)) as allocated_qty
      from public.purchase_order_delivery_batches batch
      join public.purchase_order_delivery_lines line on line.delivery_batch_id = batch.id
      where batch.purchase_order_id = p_purchase_order_id
        and batch.status <> 'cancelled'
      group by line.purchase_order_line_id
    ), requested as (
      select coalesce(item.value ->> 'lineId', item.value ->> 'itemId') as line_id,
        coalesce(nullif(item.value ->> 'requestedQtySnapshot', '')::numeric,
                 nullif(item.value ->> 'qty', '')::numeric, 0) as requested_qty
      from public.purchase_orders po
      cross join lateral jsonb_array_elements(coalesce(po.items, '[]'::jsonb)) item(value)
      where po.id = p_purchase_order_id
    )
    select 1
    from allocated
    join requested on requested.line_id = allocated.purchase_order_line_id
    where allocated.allocated_qty > requested.requested_qty + 0.000001
  ) then
    raise exception 'Đợt giao vượt nhu cầu MR; phải nhập lý do vượt nhu cầu.' using errcode = '22023';
  end if;
end;
$$;


--
-- Name: assert_project_gantt_action(text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_project_gantt_action(p_project_id text, p_construction_site_id text, p_action_code text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := public.current_app_user_id();
  v_site_id text := nullif(btrim(coalesce(p_construction_site_id, '')), '');
begin
  if v_actor_user_id is null then
    raise exception 'GANTT_PERMISSION_DENIED' using errcode = '42501';
  end if;

  if nullif(btrim(coalesce(p_project_id, '')), '') is null
    or not exists (
      select 1 from public.projects project
      where project.id = p_project_id
        and (
          v_site_id is null
          or project.construction_site_id::text = v_site_id
        )
    ) then
    raise exception 'GANTT_SCOPE_MISMATCH' using errcode = '23514';
  end if;

  if p_action_code not in ('view', 'edit', 'delete')
    or not app_private.project_actor_has_effective_room_action(
      v_actor_user_id, p_project_id, v_site_id, 'gantt', p_action_code
    ) then
    raise exception 'GANTT_PERMISSION_DENIED' using errcode = '42501';
  end if;

  return v_actor_user_id;
end;
$$;


--
-- Name: assert_project_permission_room_action(text, text, text, text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_project_permission_room_action(p_project_id text, p_construction_site_id text, p_room_code text, p_action_code text, p_user_id uuid DEFAULT public.current_app_user_id()) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_action_code text := p_action_code;
begin
  if p_user_id is null then
    raise exception 'Không xác định được người dùng đang thao tác.' using errcode = '42501';
  end if;

  if p_room_code = 'material_po'
    and p_action_code = 'submit'
    and current_setting('app.material_po_logistics_context', true) = 'confirm' then
    v_action_code := 'confirm';
  end if;

  if (
    p_room_code = 'material_po'
    and not app_private.project_actor_has_effective_room_action(
      p_user_id, p_project_id, p_construction_site_id, p_room_code, v_action_code
    )
  ) or (
    p_room_code <> 'material_po'
    and not app_private.project_user_has_room_action(
      p_user_id, p_project_id, p_construction_site_id, p_room_code, v_action_code
    )
  ) then
    raise exception 'Bạn chưa có quyền % trong Room % của dự án này.', v_action_code, p_room_code
      using errcode = '42501';
  end if;
end;
$$;


--
-- Name: assert_project_permission_room_admin(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_project_permission_room_admin() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := public.current_app_user_id();
begin
  if not exists (
    select 1
    from public.users u
    where u.id = v_actor_user_id
      and coalesce(u.is_active, true)
      and u.role = 'ADMIN'
  ) then
    raise exception 'Chỉ admin hệ thống được sửa Room phân quyền.'
      using errcode = '42501';
  end if;
  return v_actor_user_id;
end;
$$;


--
-- Name: assert_project_progress_action(uuid, text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_project_progress_action(p_actor_id uuid, p_project_id text, p_construction_site_id text, p_action_code text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_actor_id is null then
    raise exception 'Active application account required' using errcode = '42501';
  end if;

  if p_action_code not in ('view', 'edit', 'confirm') then
    raise exception 'Unsupported weekly_progress Room action: %', p_action_code
      using errcode = '22023';
  end if;

  if not app_private.project_actor_has_effective_room_action(
    p_actor_id,
    p_project_id,
    nullif(p_construction_site_id, ''),
    'weekly_progress',
    p_action_code
  ) or (
    p_action_code <> 'view'
    and not app_private.project_actor_has_effective_room_action(
      p_actor_id,
      p_project_id,
      nullif(p_construction_site_id, ''),
      'weekly_progress',
      'view'
    )
  ) then
    if p_action_code = 'edit' then
      raise exception 'Bạn không có quyền Sửa/Nhập liệu tiến độ.' using errcode = '42501';
    elsif p_action_code = 'confirm' then
      raise exception 'Bạn không có quyền Chốt/Mở chốt kỳ tiến độ.' using errcode = '42501';
    else
      raise exception 'Bạn không có quyền Xem tiến độ.' using errcode = '42501';
    end if;
  end if;
end;
$$;


--
-- Name: assert_project_progress_rows(text, text, text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_project_progress_rows(p_project_id text, p_construction_site_id text, p_period_type text, p_rows jsonb) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_site_id text := nullif(p_construction_site_id, '');
  v_row jsonb;
  v_task_id text;
begin
  if jsonb_typeof(coalesce(p_rows, 'null'::jsonb)) <> 'array'
    or jsonb_array_length(p_rows) = 0 then
    raise exception 'rows must be a non-empty JSON array' using errcode = '23514';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_rows) item(value)
    where jsonb_typeof(item.value) <> 'object'
  ) then
    raise exception 'every progress row must be a JSON object' using errcode = '23514';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_rows) item(value)
    cross join lateral jsonb_object_keys(item.value) item_key(key)
    where not (
      item_key.key = any(case when p_period_type = 'daily'
        then array[
          'taskId', 'progressPercent', 'quantityDone', 'dailyQuantityDone',
          'note', 'attachments', 'sourceDailyLogId'
        ]::text[]
        else array[
          'taskId', 'progressPercent', 'quantityDone', 'note', 'attachments'
        ]::text[]
      end)
    )
  ) then
    raise exception 'progress row contains an unsupported field for periodType %', p_period_type
      using errcode = '23514';
  end if;

  if exists (
    select item.value ->> 'taskId'
    from jsonb_array_elements(p_rows) item(value)
    group by item.value ->> 'taskId'
    having count(*) > 1
  ) then
    raise exception 'rows must contain each taskId at most once' using errcode = '23514';
  end if;

  for v_row in select value from jsonb_array_elements(p_rows) loop
    v_task_id := nullif(btrim(coalesce(v_row ->> 'taskId', '')), '');
    if v_task_id is null or jsonb_typeof(v_row -> 'taskId') <> 'string' then
      raise exception 'every progress row requires a string taskId' using errcode = '23514';
    end if;

    if not (v_row ? 'progressPercent')
      or jsonb_typeof(v_row -> 'progressPercent') <> 'number'
      or (v_row ->> 'progressPercent')::numeric < 0 then
      raise exception 'progressPercent must be a non-negative number for task %', v_task_id
        using errcode = '23514';
    end if;

    if v_row ? 'quantityDone' and (
      jsonb_typeof(v_row -> 'quantityDone') <> 'number'
      or (v_row ->> 'quantityDone')::numeric < 0
    ) then
      raise exception 'quantityDone must be a non-negative number for task %', v_task_id
        using errcode = '23514';
    end if;

    if v_row ? 'dailyQuantityDone'
      and jsonb_typeof(v_row -> 'dailyQuantityDone') <> 'number' then
      raise exception 'dailyQuantityDone must be numeric for task %', v_task_id
        using errcode = '23514';
    end if;

    if v_row ? 'attachments'
      and jsonb_typeof(v_row -> 'attachments') <> 'array' then
      raise exception 'attachments must be a JSON array for task %', v_task_id
        using errcode = '23514';
    end if;

    if v_row ? 'note'
      and jsonb_typeof(v_row -> 'note') not in ('string', 'null') then
      raise exception 'note must be a string or null for task %', v_task_id
        using errcode = '23514';
    end if;

    if v_row ? 'sourceDailyLogId'
      and jsonb_typeof(v_row -> 'sourceDailyLogId') not in ('string', 'null') then
      raise exception 'sourceDailyLogId must be a string or null for task %', v_task_id
        using errcode = '23514';
    end if;

    if not exists (
      select 1
      from public.project_tasks task
      where task.id = v_task_id
        and task.project_id is not distinct from p_project_id
        and nullif(task.construction_site_id::text, '') is not distinct from v_site_id
    ) then
      raise exception 'Task % does not belong to the requested project/site scope', v_task_id
        using errcode = '23514';
    end if;

    if exists (
      select 1
      from public.project_tasks child
      where child.parent_id = v_task_id
    ) then
      raise exception 'Only leaf tasks may be submitted; task % is derived from children', v_task_id
        using errcode = '23514';
    end if;
  end loop;
end;
$$;


--
-- Name: assert_project_progress_scope_period(text, text, text, date); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_project_progress_scope_period(p_project_id text, p_construction_site_id text, p_period_type text, p_period_start date) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_project public.projects%rowtype;
  v_site_id text := nullif(btrim(coalesce(p_construction_site_id, '')), '');
begin
  if nullif(btrim(coalesce(p_project_id, '')), '') is null then
    raise exception 'projectId is required' using errcode = '23514';
  end if;

  if p_project_id <> btrim(p_project_id) then
    raise exception 'projectId must not contain surrounding whitespace'
      using errcode = '23514';
  end if;

  select project_row.* into v_project
  from public.projects project_row
  where project_row.id = btrim(p_project_id);

  if not found then
    raise exception 'Project scope does not exist: %', p_project_id using errcode = '23514';
  end if;

  if v_site_id is not null then
    if not exists (
      select 1
      from public.hrm_construction_sites site
      where site.id::text = v_site_id
    ) then
      raise exception 'Construction site scope does not exist: %', v_site_id
        using errcode = '23514';
    end if;

    if v_project.construction_site_id is null
      or v_project.construction_site_id::text <> v_site_id then
      raise exception 'Construction site does not belong to project scope'
        using errcode = '23514';
    end if;
  end if;

  if p_period_type is null or p_period_type not in ('daily', 'weekly') then
    raise exception 'periodType must be daily or weekly' using errcode = '23514';
  end if;

  if p_period_start is null then
    raise exception 'periodStart is required' using errcode = '23514';
  end if;

  if p_period_type = 'weekly' and extract(isodow from p_period_start) <> 1 then
    raise exception 'weekly periodStart must be a Monday' using errcode = '23514';
  end if;

  return app_private.project_progress_scope_key(v_project.id, v_site_id);
end;
$$;


--
-- Name: assert_project_progress_snapshot(jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_project_progress_snapshot(p_snapshot jsonb) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_key text;
begin
  if jsonb_typeof(coalesce(p_snapshot, 'null'::jsonb)) <> 'object' then
    raise exception 'snapshot must be a JSON object' using errcode = '23514';
  end if;

  if exists (
    select 1
    from jsonb_object_keys(p_snapshot) item(key)
    where not (item.key = any(array[
      'constructionProgressPercent', 'valueProgressPercent', 'progressMode',
      'suppliedValue', 'contractTotalValue', 'purchasedValue', 'issuedValue',
      'recognizedValue', 'ganttPercent', 'calculatedAt'
    ]::text[]))
  ) then
    raise exception 'snapshot contains an unsupported field' using errcode = '23514';
  end if;

  if not (p_snapshot ? 'constructionProgressPercent')
    or jsonb_typeof(p_snapshot -> 'constructionProgressPercent') <> 'number'
    or (p_snapshot ->> 'constructionProgressPercent')::numeric < 0 then
    raise exception 'snapshot.constructionProgressPercent must be a non-negative number'
      using errcode = '23514';
  end if;

  if not (p_snapshot ? 'valueProgressPercent')
    or jsonb_typeof(p_snapshot -> 'valueProgressPercent') <> 'number'
    or (p_snapshot ->> 'valueProgressPercent')::numeric < 0 then
    raise exception 'snapshot.valueProgressPercent must be a non-negative number'
      using errcode = '23514';
  end if;

  if nullif(btrim(coalesce(p_snapshot ->> 'progressMode', '')), '') is null
    or jsonb_typeof(p_snapshot -> 'progressMode') <> 'string' then
    raise exception 'snapshot.progressMode is required' using errcode = '23514';
  end if;

  foreach v_key in array array[
    'suppliedValue', 'contractTotalValue', 'purchasedValue', 'issuedValue',
    'recognizedValue', 'ganttPercent'
  ]::text[] loop
    if p_snapshot ? v_key and (
      jsonb_typeof(p_snapshot -> v_key) not in ('number', 'null')
      or (
        jsonb_typeof(p_snapshot -> v_key) = 'number'
        and (p_snapshot ->> v_key)::numeric < 0
      )
    ) then
      raise exception 'snapshot.% must be a non-negative number or null', v_key
        using errcode = '23514';
    end if;
  end loop;

  if p_snapshot ? 'calculatedAt'
    and jsonb_typeof(p_snapshot -> 'calculatedAt') not in ('string', 'null') then
    raise exception 'snapshot.calculatedAt must be an ISO timestamp string or null'
      using errcode = '23514';
  end if;
end;
$$;


--
-- Name: assert_project_room_audit_actions_unchanged(text, text, text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_project_room_audit_actions_unchanged(p_project_id text, p_construction_site_id text, p_room_code text, p_members jsonb) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if exists (
    (
      select member.project_staff_id, action.action_code
      from public.project_permission_room_members member
      join public.project_permission_room_member_actions action
        on action.room_member_id = member.id and action.is_active
      join app_private.project_permission_room_action_bindings binding
        on binding.room_code = member.room_code
        and binding.action_code = action.action_code
        and binding.enforcement_status = 'audit_only'
      where member.project_id = p_project_id
        and member.construction_site_id is not distinct from nullif(p_construction_site_id, '')
        and member.room_code = p_room_code
        and member.is_active
      except
      select item.project_staff_id, code.action_code
      from jsonb_to_recordset(coalesce(p_members, '[]'::jsonb))
        as item(project_staff_id uuid, action_codes jsonb)
      cross join lateral jsonb_array_elements_text(item.action_codes) as code(action_code)
      join app_private.project_permission_room_action_bindings binding
        on binding.room_code = p_room_code
        and binding.action_code = code.action_code
        and binding.enforcement_status = 'audit_only'
    )
    union all
    (
      select item.project_staff_id, code.action_code
      from jsonb_to_recordset(coalesce(p_members, '[]'::jsonb))
        as item(project_staff_id uuid, action_codes jsonb)
      cross join lateral jsonb_array_elements_text(item.action_codes) as code(action_code)
      join app_private.project_permission_room_action_bindings binding
        on binding.room_code = p_room_code
        and binding.action_code = code.action_code
        and binding.enforcement_status = 'audit_only'
      except
      select member.project_staff_id, action.action_code
      from public.project_permission_room_members member
      join public.project_permission_room_member_actions action
        on action.room_member_id = member.id and action.is_active
      join app_private.project_permission_room_action_bindings binding
        on binding.room_code = member.room_code
        and binding.action_code = action.action_code
        and binding.enforcement_status = 'audit_only'
      where member.project_id = p_project_id
        and member.construction_site_id is not distinct from nullif(p_construction_site_id, '')
        and member.room_code = p_room_code
        and member.is_active
    )
  ) then
    raise exception 'Action chưa áp dụng đầy đủ; không thể thay đổi cấu hình hiện tại.'
      using errcode = '42501';
  end if;
end;
$$;


--
-- Name: assert_quality_action(text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_quality_action(p_project_id text, p_construction_site_id text, p_action_code text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := public.current_app_user_id();
  v_site_id text := nullif(btrim(coalesce(p_construction_site_id, '')), '');
begin
  if v_actor_user_id is null then
    raise exception 'QUALITY_PERMISSION_DENIED' using errcode = '42501';
  end if;
  if nullif(btrim(coalesce(p_project_id, '')), '') is null
    or v_site_id is null
    or not exists (
      select 1 from public.projects project
      where project.id::text = p_project_id
        and project.construction_site_id::text = v_site_id
    ) then
    raise exception 'QUALITY_SCOPE_MISMATCH' using errcode = '23514';
  end if;
  if p_action_code not in ('view', 'edit', 'delete', 'submit', 'verify', 'approve')
    or not app_private.project_actor_has_effective_room_action(
      v_actor_user_id, p_project_id, v_site_id, 'quality', p_action_code
    ) then
    raise exception 'QUALITY_PERMISSION_DENIED' using errcode = '42501';
  end if;
  return v_actor_user_id;
end;
$$;


--
-- Name: assert_quality_recipient(uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_quality_recipient(p_user_id uuid, p_project_id text, p_construction_site_id text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_user_id is null
    or not app_private.project_actor_has_effective_room_action(
      p_user_id, p_project_id, p_construction_site_id, 'quality', 'approve'
    ) then
    raise exception 'QUALITY_RECIPIENT_INVALID' using errcode = '42501';
  end if;
end;
$$;


--
-- Name: assert_rollout_operator_continuity(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_rollout_operator_continuity(p_excluded_assignment_id uuid DEFAULT NULL::uuid, p_excluded_user_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not exists (
    select 1
    from public.users user_row
    join public.principal_role_assignments assignment_row
      on assignment_row.principal_type = 'user'
     and assignment_row.principal_id = user_row.id
     and assignment_row.status = 'ACTIVE'
     and assignment_row.starts_at <= now()
     and assignment_row.expires_at is null
    join public.role_permission_templates role_row
      on role_row.id = assignment_row.role_template_id
     and role_row.is_active
    join public.role_permission_template_items item
      on item.template_id = role_row.id
     and item.permission_code = 'system.authorization.manage_roles'
     and item.scope_type = 'global'
     and item.scope_id = '*'
    join public.permission_actions action_row
      on action_row.permission_code = item.permission_code
     and action_row.is_active
     and 'global' = any(action_row.scope_modes)
    where user_row.role = 'ADMIN'
      and user_row.is_active
      and user_row.account_status = 'ACTIVE'
      and assignment_row.scope_type = 'global'
      and assignment_row.scope_id = '*'
      and assignment_row.id is distinct from p_excluded_assignment_id
      and user_row.id is distinct from p_excluded_user_id
  ) then
    raise exception 'At least one durable rollout operator is required'
      using errcode = '55000';
  end if;
end;
$$;


--
-- Name: assert_subject_sod(text, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_subject_sod(p_rule_code text, p_actor_user_id uuid, p_creator_user_id uuid, p_submitter_user_id uuid, p_executor_user_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_rule public.authorization_sod_rules%rowtype;
begin
  if p_actor_user_id is null
    or p_actor_user_id is distinct from public.current_app_user_id()
  then
    raise exception 'Active workflow actor required' using errcode = '42501';
  end if;

  select * into v_rule
  from public.authorization_sod_rules
  where rule_code = p_rule_code
    and is_active
    and effect = 'DENY'
    and rule_type = 'SUBJECT_RELATION';

  if v_rule.rule_code is null then
    raise exception 'Unknown hard SoD rule' using errcode = '22023';
  end if;

  if p_rule_code = 'WORKFLOW_MAKER_CHECKER_FINAL_APPROVAL'
    and p_actor_user_id is not null
    and p_actor_user_id in (p_creator_user_id, p_submitter_user_id)
  then
    raise exception 'Maker-checker separation required' using errcode = '42501';
  end if;

  if p_rule_code = 'PAYMENT_EXECUTOR_FINAL_APPROVAL'
    and p_actor_user_id is not null
    and p_actor_user_id = p_executor_user_id
  then
    raise exception 'Payment executor cannot final-approve the same payment' using errcode = '42501';
  end if;
end;
$$;


--
-- Name: assert_unified_direct_grant_readiness(uuid, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assert_unified_direct_grant_readiness(p_user_id uuid, p_grants jsonb) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if exists (
    select 1
    from jsonb_to_recordset(coalesce(p_grants, '[]'::jsonb)) proposed(
      permission_code text,
      scope_type text,
      scope_id text,
      is_active boolean,
      expires_at timestamptz
    )
    join public.permission_actions action_row
      on action_row.permission_code = proposed.permission_code
     and action_row.is_active
    where coalesce(proposed.is_active, true)
      and action_row.grant_readiness not in ('enforced', 'verified')
      and not exists (
        select 1
        from public.user_permission_grants existing
        where existing.user_id = p_user_id
          and existing.permission_code = proposed.permission_code
          and existing.scope_type = coalesce(nullif(proposed.scope_type, ''), 'global')
          and existing.scope_id = coalesce(nullif(proposed.scope_id, ''), '*')
          and existing.expires_at is not distinct from proposed.expires_at
          and existing.is_active
          and (existing.expires_at is null or existing.expires_at > now())
      )
  ) then
    raise exception 'Direct permission action is not enforced or verified'
      using errcode = '42501';
  end if;
end;
$$;


--
-- Name: asset_has_action(text, text, text, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.asset_has_action(p_permission_code text, p_warehouse_id text DEFAULT NULL::text, p_department_id text DEFAULT NULL::text, p_assigned_user_id uuid DEFAULT NULL::uuid, p_user_id uuid DEFAULT public.current_app_user_id()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_permission_code like 'asset.%'
  and p_user_id is not null
  and (
    app_private.has_permission(p_user_id, p_permission_code, 'global', '*')
    or (
      p_warehouse_id is not null
      and app_private.has_permission(p_user_id, p_permission_code, 'warehouse', p_warehouse_id)
    )
    or (
      p_department_id is not null
      and app_private.has_permission(p_user_id, p_permission_code, 'department', p_department_id)
    )
    or (
      p_assigned_user_id = p_user_id
      and app_private.has_permission(p_user_id, p_permission_code, 'assigned', p_user_id::text)
    )
  );
$$;


--
-- Name: asset_has_any_action(text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.asset_has_any_action(p_permission_code text, p_user_id uuid DEFAULT public.current_app_user_id()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_permission_code like 'asset.%'
  and p_user_id is not null
  and exists (
    select 1
    from app_private.resolve_effective_permission_sources(
      p_user_id, p_permission_code, null, null, now()
    )
  );
$$;


--
-- Name: asset_record_has_action(text, text, text, text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.asset_record_has_action(p_permission_code text, p_asset_id text, p_department_id text DEFAULT NULL::text, p_assigned_user_id text DEFAULT NULL::text, p_user_id uuid DEFAULT public.current_app_user_id()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.assets asset_row
    where asset_row.id = p_asset_id
      and app_private.asset_has_action(
        p_permission_code,
        asset_row.warehouse_id,
        coalesce(nullif(p_department_id, ''), asset_row.managing_dept_id),
        app_private.uuid_or_null(coalesce(nullif(p_assigned_user_id, ''), asset_row.assigned_to_user_id)),
        p_user_id
      )
  );
$$;


--
-- Name: assign_business_role_impl(uuid, uuid, text, text, timestamp with time zone, timestamp with time zone, text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assign_business_role_impl(p_target_user_id uuid, p_role_template_id uuid, p_scope_type text, p_scope_id text, p_starts_at timestamp with time zone, p_expires_at timestamp with time zone, p_reason text, p_warning_acceptances jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid;
  v_target public.users%rowtype;
  v_role public.role_permission_templates%rowtype;
  v_scope_type text := coalesce(nullif(p_scope_type, ''), 'global');
  v_scope_id text := coalesce(nullif(p_scope_id, ''), '*');
  v_starts_at timestamptz := coalesce(p_starts_at, now());
  v_decision jsonb;
  v_assignment_id uuid := gen_random_uuid();
begin
  v_actor_user_id := app_private.assert_authorization_permission(
    'system.authorization.manage_roles'
  );

  select *
  into v_target
  from public.users
  where id = p_target_user_id
  for update;

  if v_target.id is null
    or not v_target.is_active
    or v_target.account_status <> 'ACTIVE'
  then
    raise exception 'Active target user required'
      using errcode = '23514';
  end if;

  select *
  into v_role
  from public.role_permission_templates
  where id = p_role_template_id
    and is_active
  for update;

  if v_role.id is null
    or char_length(btrim(coalesce(p_reason, ''))) < 10
  then
    raise exception 'Valid Business Role and assignment reason required'
      using errcode = '22023';
  end if;

  if v_role.code = 'SYSTEM_ADMIN' and v_target.role <> 'ADMIN' then
    raise exception 'System Admin role assignment must follow the governed profile identity command'
      using errcode = '55000';
  end if;

  if v_role.code <> 'SYSTEM_ADMIN'
    and exists (
      select 1
      from public.role_permission_template_items item
      where item.template_id = v_role.id
        and item.permission_code = 'system.settings.manage'
    )
  then
    raise exception 'System identity permissions are seed-controlled'
      using errcode = '42501';
  end if;

  if v_starts_at > now() then
    raise exception 'Future Business Role scheduling is not enabled in Phase 2'
      using errcode = '22023';
  end if;

  if p_expires_at is not null and p_expires_at <= v_starts_at then
    raise exception 'Business Role assignment expiry must follow its start time'
      using errcode = '22023';
  end if;

  update public.principal_role_assignments
  set status = 'EXPIRED',
      updated_at = now()
  where principal_type = 'user'
    and principal_id = p_target_user_id
    and role_template_id = p_role_template_id
    and scope_type = v_scope_type
    and scope_id = v_scope_id
    and status = 'ACTIVE'
    and expires_at is not null
    and expires_at <= now();

  if exists (
    select 1
    from public.principal_role_assignments assignment_row
    where assignment_row.principal_type = 'user'
      and assignment_row.principal_id = p_target_user_id
      and assignment_row.role_template_id = p_role_template_id
      and assignment_row.scope_type = v_scope_type
      and assignment_row.scope_id = v_scope_id
      and assignment_row.status = 'ACTIVE'
  ) then
    raise exception 'Active Business Role assignment already exists'
      using errcode = '23505';
  end if;

  v_decision := app_private.evaluate_business_role_assignment_impl(
    v_actor_user_id,
    p_target_user_id,
    p_role_template_id,
    v_scope_type,
    v_scope_id
  );

  perform app_private.assert_and_record_sod_warnings(
    v_decision,
    p_warning_acceptances,
    'ASSIGN_BUSINESS_ROLE',
    v_assignment_id,
    v_actor_user_id,
    p_target_user_id
  );

  insert into public.principal_role_assignments (
    id,
    principal_type,
    principal_id,
    role_template_id,
    scope_type,
    scope_id,
    starts_at,
    expires_at,
    status,
    assigned_by,
    assigned_reason
  )
  values (
    v_assignment_id,
    'user',
    p_target_user_id,
    p_role_template_id,
    v_scope_type,
    v_scope_id,
    v_starts_at,
    p_expires_at,
    'ACTIVE',
    v_actor_user_id,
    btrim(p_reason)
  );

  insert into public.permission_audit_events (
    actor_user_id,
    target_user_id,
    event_type,
    before_grants,
    after_grants,
    metadata
  )
  values (
    v_actor_user_id,
    p_target_user_id,
    'business_role_assigned',
    '[]'::jsonb,
    jsonb_build_array(jsonb_build_object(
      'assignmentId', v_assignment_id,
      'roleTemplateId', p_role_template_id,
      'scopeType', v_scope_type,
      'scopeId', v_scope_id,
      'startsAt', v_starts_at,
      'expiresAt', p_expires_at
    )),
    jsonb_build_object(
      'assignmentId', v_assignment_id,
      'roleTemplateId', p_role_template_id,
      'reason', btrim(p_reason),
      'decision', v_decision
    )
  );

  return v_assignment_id;
end;
$$;


--
-- Name: assign_hrm_employee_to_staffing(uuid, uuid, uuid, text, uuid, date, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assign_hrm_employee_to_staffing(p_employee_id uuid, p_org_unit_id uuid, p_position_id uuid, p_level_code text, p_reports_to_slot_id uuid, p_effective_from date, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid;
  v_employee public.employees%rowtype;
  v_unit public.org_units%rowtype;
  v_position public.hrm_positions%rowtype;
  v_slot public.hrm_org_position_slots%rowtype;
  v_assignment public.hrm_employee_slot_assignments%rowtype;
  v_old_assignment jsonb := '{}'::jsonb;
  v_level_code text := nullif(trim(p_level_code), '');
begin
  if not app_private.current_user_has_hrm_template_permission('hrm.staffing.assign') then
    raise exception using errcode = '42501', message = 'HRM_STAFFING_ASSIGN_REQUIRED';
  end if;
  v_actor_id := public.current_app_user_id();
  if v_actor_id is null then
    raise exception using errcode = '42501', message = 'HRM_ACTIVE_ACTOR_REQUIRED';
  end if;
  if p_effective_from is null or p_effective_from > current_date then
    raise exception using errcode = '22023', message = 'HRM_ASSIGNMENT_FUTURE_DATE_NOT_ALLOWED';
  end if;

  select * into v_employee
  from public.employees
  where id = p_employee_id and status = 'Đang làm việc'
  for update;
  if v_employee.id is null then
    raise exception using errcode = '22023', message = 'HRM_ACTIVE_EMPLOYEE_NOT_FOUND';
  end if;

  select * into v_unit
  from public.org_units
  where id = p_org_unit_id and is_active;
  if v_unit.id is null then
    raise exception using errcode = '22023', message = 'HRM_ACTIVE_ORG_UNIT_NOT_FOUND';
  end if;

  select * into v_position
  from public.hrm_positions
  where id = p_position_id and is_active;
  if v_position.id is null then
    raise exception using errcode = '22023', message = 'HRM_ACTIVE_POSITION_NOT_FOUND';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      pg_catalog.concat_ws('|', p_org_unit_id::text, p_position_id::text,
        coalesce(v_level_code, ''), coalesce(p_reports_to_slot_id::text, '')),
      0
    )
  );

  select slot.* into v_slot
  from public.hrm_org_position_slots slot
  where slot.source = 'workforce_plan'
    and slot.status = 'ACTIVE'
    and slot.org_unit_id = p_org_unit_id
    and slot.position_id = p_position_id
    and slot.level_code is not distinct from v_level_code
    and slot.reports_to_slot_id is not distinct from p_reports_to_slot_id
    and slot.effective_from <= p_effective_from
    and (slot.effective_to is null or slot.effective_to >= p_effective_from)
    and not exists (
      select 1
      from public.hrm_employee_slot_assignments occupant
      where occupant.slot_id = slot.id
        and occupant.status = 'ACTIVE'
        and occupant.assignment_type in ('PRIMARY', 'ACTING')
    )
  order by slot.id
  for update skip locked
  limit 1;
  if v_slot.id is null then
    raise exception using errcode = '55000', message = 'HRM_STAFFING_NO_VACANCY';
  end if;

  select coalesce(jsonb_agg(to_jsonb(active_assignment)), '[]'::jsonb)
  into v_old_assignment
  from public.hrm_employee_slot_assignments active_assignment
  where active_assignment.employee_id = p_employee_id
    and active_assignment.status = 'ACTIVE'
    and active_assignment.assignment_type = 'PRIMARY';

  update public.hrm_employee_slot_assignments
  set status = 'ENDED',
      effective_to = greatest(effective_from, p_effective_from),
      note = concat_ws(E'\n', nullif(note, ''), nullif(trim(p_note), '')),
      updated_by = v_actor_id,
      updated_at = now()
  where employee_id = p_employee_id
    and status = 'ACTIVE'
    and assignment_type = 'PRIMARY';

  insert into public.hrm_employee_slot_assignments (
    employee_id, slot_id, assignment_type, status, effective_from,
    note, source, created_by, updated_by
  ) values (
    p_employee_id, v_slot.id, 'PRIMARY', 'ACTIVE', p_effective_from,
    nullif(trim(p_note), ''), 'workforce_plan', v_actor_id, v_actor_id
  ) returning * into v_assignment;

  update public.employees
  set org_unit_id = p_org_unit_id,
      position_id = p_position_id,
      title = v_position.name,
      department_id = case when v_unit.type = 'department' then v_unit.id else null end,
      factory_id = case when v_unit.type = 'factory' then v_unit.id else null end,
      construction_site_id = case
        when v_unit.type = 'construction_site' then v_unit.linked_construction_site_id
        else null
      end,
      updated_at = now()
  where id = p_employee_id;

  insert into public.audit_trail (
    table_name, record_id, action, old_data, new_data, user_id, module,
    description, record_label, entity_type, changed_fields, change_count,
    impact_level, context
  ) values (
    'hrm_employee_slot_assignments', v_assignment.id::text, 'INSERT',
    jsonb_build_object('assignments', v_old_assignment,
      'org_unit_id', v_employee.org_unit_id, 'position_id', v_employee.position_id),
    jsonb_build_object('assignment', to_jsonb(v_assignment),
      'org_unit_id', p_org_unit_id, 'position_id', p_position_id),
    v_actor_id::text, 'HRM', 'Phân bổ hoặc chuyển vị trí nhân sự',
    v_employee.full_name, 'HRM_WORKFORCE_ASSIGNMENT',
    array['org_unit_id', 'position_id', 'slot_id'], 3, 'high',
    jsonb_build_object('note', nullif(trim(p_note), ''))
  );

  return jsonb_build_object(
    'employee_id', p_employee_id,
    'status', 'ASSIGNED',
    'assignment_id', v_assignment.id,
    'slot_id', v_slot.id,
    'org_unit_id', p_org_unit_id,
    'org_unit_name', v_unit.name,
    'position_id', p_position_id,
    'position_name', v_position.name,
    'level_code', v_level_code
  );
end;
$$;


--
-- Name: assign_hrm_employee_to_staffing(uuid, uuid, uuid, text, uuid, date, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assign_hrm_employee_to_staffing(p_employee_id uuid, p_org_unit_id uuid, p_position_id uuid, p_level_code text, p_reports_to_slot_id uuid, p_effective_from date, p_note text, p_source_reference text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_result jsonb;
begin
  perform app_private.assert_hrm_mutation_context(p_note, p_source_reference);
  v_result := app_private.assign_hrm_employee_to_staffing(
    p_employee_id, p_org_unit_id, p_position_id, p_level_code,
    p_reports_to_slot_id, p_effective_from, p_note
  );
  perform app_private.annotate_hrm_workforce_audit('HRM_WORKFORCE_ASSIGNMENT', p_source_reference);
  return v_result;
end;
$$;


--
-- Name: assign_safety_worker_to_site(uuid, timestamp with time zone, uuid, uuid, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.assign_safety_worker_to_site(p_membership_id uuid, p_started_at timestamp with time zone, p_subcontractor_id uuid DEFAULT NULL::uuid, p_team_id uuid DEFAULT NULL::uuid, p_assignment jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_membership public.safety_worker_site_memberships%rowtype;
  v_worker public.safety_worker_profiles%rowtype;
  v_existing_assignment uuid;
  v_assignment_id uuid;
begin
  if p_started_at is null or jsonb_typeof(coalesce(p_assignment, 'null'::jsonb)) <> 'object' then
    raise exception 'SAFETY_INVALID_RPC_PAYLOAD: start time and assignment object are required'
      using errcode = '22023';
  end if;

  select membership.*
  into v_membership
  from public.safety_worker_site_memberships membership
  where membership.id = p_membership_id;

  if v_membership.id is null
    or v_actor is null
    or not app_private.safety_workforce_can_manage(v_membership.project_id, v_membership.construction_site_id)
  then
    raise exception 'SAFETY_SCOPE_MISMATCH: actor cannot assign worker to target site'
      using errcode = '42501';
  end if;

  select worker.*
  into v_worker
  from public.safety_worker_profiles worker
  where worker.id = v_membership.worker_id
  for update;

  perform membership.id
  from public.safety_worker_site_memberships membership
  where membership.id = v_membership.id
  for update;

  perform app_private.safety_workforce_assert_subcontractor_team(
    v_membership.project_id,
    v_membership.construction_site_id,
    p_subcontractor_id,
    p_team_id,
    v_worker.worker_kind
  );

  select assignment.id
  into v_existing_assignment
  from public.safety_project_assignments assignment
  where assignment.worker_id = v_worker.id
    and assignment.assignment_status = 'active'
  limit 1;

  if v_existing_assignment is not null then
    raise exception 'SAFETY_WORKER_ACTIVE_ELSEWHERE: worker already has an active assignment'
      using errcode = '23505';
  end if;

  update public.safety_worker_site_memberships membership
  set status = 'active',
      default_subcontractor_id = case when v_worker.worker_kind = 'company_staff' then null else p_subcontractor_id end,
      default_team_id = case when v_worker.worker_kind = 'company_staff' then null else p_team_id end,
      last_left_at = null,
      updated_by = v_actor,
      updated_at = now()
  where membership.id = v_membership.id;

  insert into public.safety_project_assignments (
    worker_id, project_id, construction_site_id, membership_id,
    assignment_status, started_at, start_date,
    subcontractor_id, team_id, role_name, work_type,
    site_training_status, commitment_status, ppe_status, toolbox_status,
    eligibility_status, source, created_by
  ) values (
    v_worker.id,
    v_membership.project_id,
    v_membership.construction_site_id::text,
    v_membership.id,
    'active',
    p_started_at,
    (p_started_at at time zone 'Asia/Ho_Chi_Minh')::date,
    case when v_worker.worker_kind = 'company_staff' then null else p_subcontractor_id end,
    case when v_worker.worker_kind = 'company_staff' then null else p_team_id end,
    nullif(trim(p_assignment ->> 'roleName'), ''),
    nullif(trim(p_assignment ->> 'workType'), ''),
    'pending', 'pending', 'missing', 'pending',
    'missing_profile', 'manual', v_actor::text
  )
  returning id into v_assignment_id;

  insert into public.safety_audit_logs (
    actor_user_id, action, target_type, target_id, project_id, construction_site_id, metadata
  ) values (
    v_actor::text,
    'assignment.create',
    'safety_project_assignments',
    v_assignment_id,
    v_membership.project_id,
    v_membership.construction_site_id::text,
    jsonb_build_object('membershipId', v_membership.id, 'workerId', v_worker.id)
  );

  return app_private.safety_workforce_detail_for_membership(v_membership.id);
end;
$$;


--
-- Name: audit_hrm_profile_command(uuid, text, text, text, text, text[]); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.audit_hrm_profile_command(p_employee_id uuid, p_entity_type text, p_record_id text, p_action text, p_reason text, p_changed_fields text[]) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  insert into public.audit_trail(
    table_name, record_id, action, user_id, module, description,
    record_label, entity_type, changed_fields, change_count, impact_level, context
  ) values (
    p_entity_type, p_record_id,
    case when p_action in ('INSERT','UPDATE','DELETE') then p_action else 'UPDATE' end,
    public.current_app_user_id()::text,
    'HRM', 'Cập nhật hồ sơ nhân sự', p_employee_id::text, p_entity_type,
    p_changed_fields, cardinality(p_changed_fields),
    case when p_entity_type in ('HRM_IDENTITY_DOCUMENT','HRM_INSURANCE_PROFILE','HRM_DEPENDENT','HRM_EMPLOYMENT_EVENT') then 'high'
         when p_entity_type in ('HRM_TAX_PROFILE','HRM_BANK_ACCOUNT','HRM_CONTRACT') then 'critical'
         else 'normal' end,
    jsonb_build_object('employee_id', p_employee_id, 'reason', nullif(trim(p_reason), ''))
  );
$$;


--
-- Name: audit_supplier_ap_change(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.audit_supplier_ap_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_record_id text;
  v_description text;
begin
  v_record_id := case when tg_op = 'DELETE' then old.id::text else new.id::text end;
  v_description := case tg_table_name
    when 'supplier_delivery_statements' then 'Lưu vết đối soát HĐ NCC'
    when 'supplier_delivery_statement_lines' then 'Lưu vết dòng đối soát HĐ NCC'
    when 'supplier_payable_documents' then 'Lưu vết công nợ NCC'
    when 'supplier_payment_batches' then 'Lưu vết đợt thanh toán NCC'
    when 'supplier_payment_allocations' then 'Lưu vết phân bổ thanh toán NCC'
    when 'site_direct_purchases' then 'Lưu vết mua nóng công trường'
    when 'site_direct_purchase_lines' then 'Lưu vết dòng mua nóng công trường'
    when 'site_cash_settlement_batches' then 'Lưu vết hoàn ứng công trường'
    when 'site_cash_settlement_lines' then 'Lưu vết dòng hoàn ứng công trường'
    else 'Lưu vết chứng từ NCC'
  end;

  insert into public.audit_trail (
    table_name,
    record_id,
    action,
    old_data,
    new_data,
    user_id,
    user_name,
    module,
    description
  )
  values (
    tg_table_name,
    v_record_id,
    tg_op,
    case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) else '{}'::jsonb end,
    case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) else '{}'::jsonb end,
    public.current_app_user_id()::text,
    '',
    'TC',
    v_description
  );

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


--
-- Name: backfill_vehicle_booking_notification_context(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.backfill_vehicle_booking_notification_context() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_notification record;
  v_booking_text text;
  v_assignment_text text;
  v_recipient_text text;
  v_booking_id uuid;
  v_assignment_id uuid;
  v_recipient_user_id uuid;
  v_event_type text;
  v_context jsonb;
  v_purpose text;
  v_compact_purpose text;
  v_message text;
  v_updated bigint := 0;
begin
  for v_notification in
    select notification.id, notification.user_id, notification.source_id,
      notification.entity_id, notification.metadata
    from public.notifications notification
    where notification.category = 'vehicle_booking'
       or notification.source_type = 'vehicle_booking'
       or notification.entity_type = 'vehicle_booking'
  loop
    v_booking_id := null;
    v_assignment_id := null;
    v_recipient_user_id := null;
    v_context := null;

    v_booking_text := coalesce(
      nullif(v_notification.metadata ->> 'booking_id', ''),
      nullif(v_notification.metadata ->> 'bookingId', ''),
      nullif(v_notification.entity_id::text, ''),
      nullif(v_notification.source_id, '')
    );
    v_assignment_text := nullif(v_notification.metadata ->> 'assignment_id', '');
    v_recipient_text := nullif(v_notification.user_id, '');
    v_event_type := coalesce(
      nullif(v_notification.metadata ->> 'event_type', ''),
      nullif(v_notification.metadata ->> 'eventType', ''),
      'BOOKING_UPDATED'
    );

    if coalesce(v_booking_text, '')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      v_booking_id := v_booking_text::uuid;
    end if;
    if coalesce(v_assignment_text, '')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      v_assignment_id := v_assignment_text::uuid;
    end if;
    if coalesce(v_recipient_text, '')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      v_recipient_user_id := v_recipient_text::uuid;
    end if;

    if v_booking_id is null then
      continue;
    end if;

    v_context := app_private.build_vehicle_booking_notification_context(
      v_booking_id,
      v_assignment_id,
      v_recipient_user_id,
      v_event_type
    );
    if v_context is null then
      continue;
    end if;

    v_purpose := v_context ->> 'purpose';
    v_compact_purpose := case
      when char_length(v_purpose) > 80 then left(v_purpose, 80) || '…'
      else v_purpose
    end;
    v_message := concat(
      'Người đặt: ', v_context ->> 'requester_name',
      ' · Nội dung: ', v_compact_purpose,
      ' · Tài xế: ', v_context ->> 'driver_name',
      ' · ', v_context ->> 'pickup_location',
      ' → ', v_context ->> 'destination'
    );

    update public.notifications notification
    set metadata = coalesce(notification.metadata, '{}'::jsonb) || v_context,
        message = v_message,
        body = v_message
    where notification.id = v_notification.id;

    v_updated := v_updated + 1;
  end loop;

  return v_updated;
end;
$_$;


--
-- Name: begin_project_gantt_command(uuid, uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.begin_project_gantt_command(p_actor_user_id uuid, p_request_id uuid, p_command_name text, p_payload_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request app_private.project_gantt_command_requests%rowtype;
begin
  if p_request_id is null then
    raise exception 'GANTT_REQUEST_ID_REQUIRED' using errcode = '23514';
  end if;

  insert into app_private.project_gantt_command_requests (
    actor_user_id, request_id, command_name, payload_hash
  ) values (
    p_actor_user_id, p_request_id, p_command_name, p_payload_hash
  )
  on conflict (actor_user_id, request_id) do nothing;

  if found then
    return null;
  end if;

  select request.* into v_request
  from app_private.project_gantt_command_requests request
  where request.actor_user_id = p_actor_user_id
    and request.request_id = p_request_id
  for update;

  if v_request.command_name is distinct from p_command_name
    or v_request.payload_hash is distinct from p_payload_hash then
    raise exception 'GANTT_REQUEST_ID_REUSED' using errcode = '23514';
  end if;

  if v_request.result is null then
    raise exception 'GANTT_REQUEST_IN_PROGRESS' using errcode = '55000';
  end if;

  return v_request.result || jsonb_build_object('replayed', true);
end;
$$;


--
-- Name: begin_quality_command(uuid, uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.begin_quality_command(p_actor_user_id uuid, p_request_id uuid, p_command_name text, p_payload_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request app_private.quality_command_requests%rowtype;
begin
  if p_request_id is null then
    raise exception 'QUALITY_REQUEST_ID_REUSED: request id is required' using errcode = '23514';
  end if;
  insert into app_private.quality_command_requests (
    actor_user_id, request_id, command_name, payload_hash
  ) values (p_actor_user_id, p_request_id, p_command_name, p_payload_hash)
  on conflict (actor_user_id, request_id) do nothing;
  if found then return null; end if;

  select request.* into v_request
  from app_private.quality_command_requests request
  where request.actor_user_id = p_actor_user_id
    and request.request_id = p_request_id
  for update;
  if v_request.command_name is distinct from p_command_name
    or v_request.payload_hash is distinct from p_payload_hash then
    raise exception 'QUALITY_REQUEST_ID_REUSED' using errcode = '23514';
  end if;
  if v_request.result is null then
    raise exception 'QUALITY_REQUEST_ID_REUSED: request is still in progress' using errcode = '55000';
  end if;
  return v_request.result || jsonb_build_object('replayed', true);
end;
$$;


--
-- Name: build_vehicle_booking_notification_context(uuid, uuid, uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.build_vehicle_booking_notification_context(p_booking_id uuid, p_assignment_id uuid, p_recipient_user_id uuid, p_event_type text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_booking public.vehicle_bookings%rowtype;
  v_assignment public.vehicle_booking_assignments%rowtype;
  v_requester_name text;
  v_driver_name text;
begin
  select booking.* into v_booking
  from public.vehicle_bookings booking
  where booking.id = p_booking_id;

  if not found then
    return null;
  end if;

  if p_assignment_id is not null then
    select assignment.* into v_assignment
    from public.vehicle_booking_assignments assignment
    where assignment.booking_id = p_booking_id
      and assignment.id = p_assignment_id;
  end if;

  if v_assignment.id is null
     and p_event_type = 'BOOKING_REASSIGNED_OLD_OPERATOR'
     and p_recipient_user_id is not null then
    select assignment.* into v_assignment
    from public.vehicle_booking_assignments assignment
    where assignment.booking_id = p_booking_id
      and not assignment.is_active
      and assignment.operator_user_id = p_recipient_user_id
      and assignment.superseded_at is not null
    order by assignment.superseded_at desc, assignment.version desc
    limit 1;
  end if;

  if v_assignment.id is null then
    select assignment.* into v_assignment
    from public.vehicle_booking_assignments assignment
    where assignment.booking_id = p_booking_id
      and assignment.is_active
    order by assignment.version desc
    limit 1;
  end if;

  select coalesce(
    nullif(trim(employee.full_name), ''),
    nullif(trim(app_user.name), ''),
    'Chưa có thông tin'
  ) into v_requester_name
  from public.users app_user
  left join lateral (
    select employee_row.full_name
    from public.employees employee_row
    where employee_row.user_id = app_user.id
    order by
      case when employee_row.status = 'Đang làm việc' then 0 else 1 end,
      employee_row.updated_at desc,
      employee_row.id
    limit 1
  ) employee on true
  where app_user.id = v_booking.requester_user_id;

  v_requester_name := coalesce(v_requester_name, 'Chưa có thông tin');

  if v_assignment.id is not null then
    if nullif(trim(v_assignment.external_driver_name), '') is not null then
      v_driver_name := trim(v_assignment.external_driver_name);
    elsif v_assignment.operator_user_id is not null then
      select coalesce(
        nullif(trim(employee.full_name), ''),
        nullif(trim(app_user.name), '')
      ) into v_driver_name
      from public.users app_user
      left join lateral (
        select employee_row.full_name
        from public.employees employee_row
        where employee_row.user_id = app_user.id
        order by
          case when employee_row.status = 'Đang làm việc' then 0 else 1 end,
          employee_row.updated_at desc,
          employee_row.id
        limit 1
      ) employee on true
      where app_user.id = v_assignment.operator_user_id;
    end if;
  end if;

  return jsonb_build_object(
    'booking_id', v_booking.id,
    'booking_code', v_booking.booking_code,
    'event_type', coalesce(nullif(trim(p_event_type), ''), 'BOOKING_UPDATED'),
    'requester_name', v_requester_name,
    'purpose', coalesce(nullif(trim(v_booking.purpose), ''), 'Chưa có nội dung'),
    'driver_name', coalesce(nullif(trim(v_driver_name), ''), 'Chưa phân công'),
    'pickup_location', coalesce(nullif(trim(v_booking.pickup_location_text), ''), 'Chưa có thông tin'),
    'destination', coalesce(nullif(trim(v_booking.destination_text), ''), 'Chưa có thông tin')
  );
end;
$$;


--
-- Name: bump_project_task_gantt_version(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.bump_project_task_gantt_version() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  new.updated_at := now();
  new.row_version := old.row_version + 1;
  return new;
end;
$$;


--
-- Name: calculate_po_committed_amount(jsonb, numeric); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.calculate_po_committed_amount(p_items jsonb, p_total_amount numeric) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select coalesce(nullif(sum(
    coalesce(nullif(item->>'qty', '')::numeric, 0)
    * coalesce(nullif(item->>'unitPrice', '')::numeric, nullif(item->>'unit_price', '')::numeric, 0)
  ), 0), coalesce(p_total_amount, 0))
  from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) item;
$$;


--
-- Name: calculate_po_payable_amount(jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.calculate_po_payable_amount(p_items jsonb) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select coalesce(sum(
    greatest(
      0,
      coalesce(nullif(item->>'receivedQty', '')::numeric, nullif(item->>'received_qty', '')::numeric, 0)
      - coalesce(nullif(item->>'returnedQty', '')::numeric, nullif(item->>'returned_qty', '')::numeric, 0)
    )
    * coalesce(nullif(item->>'unitPrice', '')::numeric, nullif(item->>'unit_price', '')::numeric, 0)
  ), 0)
  from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) item;
$$;


--
-- Name: can_access_module(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.can_access_module(p_module text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.users u
    where u.id = public.current_app_user_id()
      and coalesce(u.is_active, false)
      and (
        u.role = 'ADMIN'
        or p_module = any(coalesce(u.allowed_modules, '{}'::text[]))
        or p_module = any(coalesce(u.admin_modules, '{}'::text[]))
        or coalesce(u.allowed_sub_modules, '{}'::jsonb) ? p_module
        or coalesce(u.admin_sub_modules, '{}'::jsonb) ? p_module
      )
  );
$$;


--
-- Name: can_act_on_subject_impl(text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.can_act_on_subject_impl(p_subject_type text, p_subject_id text, p_action text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := public.current_app_user_id();
  v_log public.daily_logs%rowtype;
  v_owner_id uuid;
  v_required_permission text;
  v_responsibilities text[];
begin
  if v_actor_user_id is null or not app_private.can_view_subject_impl(p_subject_type, p_subject_id) then
    return false;
  end if;

  if p_subject_type <> 'daily_log' then
    return false;
  end if;

  select * into v_log from public.daily_logs where id = p_subject_id;
  if not found then
    return false;
  end if;

  if p_action = 'view' then
    return true;
  end if;

  if p_action = 'submit' then
    select owner_user.id
    into v_owner_id
    from public.users owner_user
    where owner_user.id::text = coalesce(
      nullif(v_log.created_by_id, ''),
      nullif(v_log.submitted_by_id, ''),
      nullif(v_log.submitted_by, ''),
      nullif(v_log.created_by, '')
    )
    limit 1;

    return coalesce(v_log.status, 'draft') in ('draft', 'rejected')
      and (
        (
          v_owner_id = v_actor_user_id
          and app_private.daily_log_has_action(
            v_log.project_id::text,
            v_log.construction_site_id::text,
            'project.daily_log.submit',
            v_actor_user_id
          )
        )
        or (
          v_log.summary_source_type = 'member_contributions'
          and (
            app_private.daily_log_has_action(
              v_log.project_id::text,
              v_log.construction_site_id::text,
              'project.daily_log.summarize',
              v_actor_user_id
            )
            or app_private.daily_log_has_action(
              v_log.project_id::text,
              v_log.construction_site_id::text,
              'project.daily_log.submit',
              v_actor_user_id
            )
          )
        )
      );
  end if;

  if p_action = 'verify' then
    v_required_permission := 'project.daily_log.verify';
    v_responsibilities := array['current_verifier'];
  elsif p_action = 'approve' then
    v_required_permission := 'project.daily_log.approve';
    v_responsibilities := array['current_approver'];
  elsif p_action = 'return' then
    v_required_permission := 'project.daily_log.return';
    v_responsibilities := array['current_verifier', 'current_approver'];
  else
    return false;
  end if;

  return coalesce(v_log.status, 'draft') = 'submitted'
    and app_private.daily_log_has_action(
      v_log.project_id::text,
      v_log.construction_site_id::text,
      v_required_permission,
      v_actor_user_id
    )
    and app_private.daily_log_assignment_is_active(
      p_subject_id,
      v_actor_user_id,
      v_responsibilities,
      case when p_action = 'return' then null else v_required_permission end
    );
end;
$$;


