-- Name: site_direct_purchases; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.site_direct_purchases (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    code text NOT NULL,
    project_id text,
    construction_site_id text NOT NULL,
    supplier_id text,
    supplier_name_snapshot text NOT NULL,
    purchase_mode text NOT NULL,
    payment_source text NOT NULL,
    target_warehouse_id text,
    status text DEFAULT 'draft'::text NOT NULL,
    purchase_date date,
    invoice_number text,
    invoice_date date,
    gross_amount numeric(18,2) DEFAULT 0 NOT NULL,
    vat_amount numeric(18,2) DEFAULT 0 NOT NULL,
    total_amount numeric(18,2) DEFAULT 0 NOT NULL,
    po_id text,
    wms_transaction_id text,
    site_cash_settlement_id uuid,
    qr_token text,
    attachments jsonb DEFAULT '[]'::jsonb NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    note text,
    submitted_to_user_id text,
    submitted_to_name text,
    submitted_to_permission text,
