    CONSTRAINT site_direct_purchases_gross_amount_check CHECK ((gross_amount >= (0)::numeric)),
    CONSTRAINT site_direct_purchases_payment_source_check CHECK ((payment_source = ANY (ARRAY['site_cash'::text, 'company_bank'::text, 'staff_paid'::text, 'supplier_credit'::text]))),
    CONSTRAINT site_direct_purchases_purchase_mode_check CHECK ((purchase_mode = ANY (ARRAY['planned'::text, 'immediate'::text]))),
    CONSTRAINT site_direct_purchases_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'submitted'::text, 'approved_to_buy'::text, 'purchased'::text, 'received'::text, 'finance_review'::text, 'reconciled'::text, 'closed'::text, 'rejected'::text, 'cancelled'::text]))),
    CONSTRAINT site_direct_purchases_total_amount_check CHECK ((total_amount >= (0)::numeric)),
    CONSTRAINT site_direct_purchases_vat_amount_check CHECK ((vat_amount >= (0)::numeric))
);


--
-- Name: cancel_site_direct_purchase_payable_v1(uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.cancel_site_direct_purchase_payable_v1(p_direct_purchase_id uuid, p_reason text, p_next_status text) RETURNS public.site_direct_purchases
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_purchase public.site_direct_purchases%rowtype;
  v_actor_id uuid := auth.uid();
begin
  select * into v_purchase
  from public.site_direct_purchases
  where id = p_direct_purchase_id
  for update;

  if not found then
    raise exception 'Không tìm thấy phiếu mua nóng %. ', p_direct_purchase_id;
  end if;

  if not app_private.ap_scope_can_mutate(v_purchase.project_id, v_purchase.construction_site_id)
    or not app_private.material_flow_has_action_or_legacy(v_purchase.project_id, v_purchase.construction_site_id, 'project.material_direct_purchase.record_ap') then
    raise exception 'Bạn không có quyền hủy xác nhận công nợ phiếu mua nóng này.';
  end if;

  if v_purchase.status not in ('submitted', 'approved_to_buy', 'purchased', 'received', 'finance_review', 'reconciled') then
    raise exception 'Phiếu ở trạng thái % không thể từ chối hoặc bỏ xác nhận công nợ.', v_purchase.status;
  end if;

  if exists (
    select 1
    from public.supplier_payment_allocations allocation
    join public.supplier_payment_batches batch on batch.id = allocation.payment_batch_id
    join public.supplier_payable_documents payable on payable.id = allocation.payable_document_id
    where payable.source_type = 'site_direct_purchase'
      and payable.source_id = v_purchase.id::text
      and batch.status = 'paid'
  ) then
    raise exception 'Phiếu đã có thanh toán. Hãy Đảo thanh toán trước khi từ chối hoặc bỏ xác nhận công nợ.';
  end if;

  if v_purchase.site_cash_settlement_id is not null then
    raise exception 'Phiếu đã nằm trong quyết toán quỹ. Hãy đảo/quy hồi quyết toán trước.';
  end if;

  if v_purchase.wms_transaction_id is not null then
    raise exception 'Phiếu đã phát sinh WMS. Hãy hủy hoặc đảo phiếu kho trước.';
  end if;

  if exists (
    select 1
    from public.site_small_tool_records tool
    where tool.source_type = 'site_direct_purchase'
      and tool.source_id = v_purchase.id::text
      and tool.status <> 'stored'
  ) then
    raise exception 'CCDC đã được bàn giao hoặc sử dụng. Hãy thực hiện nghiệp vụ đảo CCDC trước.';
  end if;

  delete from public.site_small_tool_records tool
  where tool.source_type = 'site_direct_purchase'
    and tool.source_id = v_purchase.id::text
    and tool.status = 'stored';

  update public.supplier_payable_documents payable
  set
    status = 'cancelled',
    recognized_amount = 0,
    metadata = coalesce(payable.metadata, '{}'::jsonb) || jsonb_build_object(
      'cancelledAt', now(),
      'cancelledBy', v_actor_id,
      'cancellationReason', nullif(btrim(p_reason), '')
    ),
    updated_at = now()
  where payable.source_type = 'site_direct_purchase'
    and payable.source_id = v_purchase.id::text
    and payable.status not in ('cancelled', 'reversed');

  update public.site_direct_purchases purchase
  set
    status = p_next_status,
    note = concat_ws(E'\n', nullif(purchase.note, ''), case when nullif(btrim(p_reason), '') is null then null else 'Lý do: ' || btrim(p_reason) end),
    last_action_by = v_actor_id,
    last_action_at = now(),
    updated_at = now()
  where purchase.id = v_purchase.id
  returning * into v_purchase;

  return v_purchase;
end;
$$;


--
-- Name: cancel_unreceived_delivery_batch_v2(uuid, uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.cancel_unreceived_delivery_batch_v2(p_delivery_batch_id uuid, p_actor_user_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_batch public.purchase_order_delivery_batches%rowtype;
  v_po public.purchase_orders%rowtype;
  v_tx public.transactions%rowtype;
  v_batch_purchase_order_id text;
begin
  if p_actor_user_id is null then
    raise exception 'Nguoi thuc hien lenh khong hop le.' using errcode = '42501';
  end if;
  if public.current_app_user_id() is null or p_actor_user_id <> public.current_app_user_id() then
    raise exception 'Nguoi thuc hien lenh khong hop le.' using errcode = '42501';
  end if;
  if nullif(trim(coalesce(p_reason, '')), '') is null then
    raise exception 'Ly do huy Dot giao la bat buoc.' using errcode = '22023';
  end if;

  select purchase_order_id into v_batch_purchase_order_id
  from public.purchase_order_delivery_batches
  where id = p_delivery_batch_id;
  if not found then
    raise exception 'Khong tim thay Dot giao %.', p_delivery_batch_id using errcode = '22023';
  end if;

  select * into v_po
  from public.purchase_orders
  where id = v_batch_purchase_order_id
  for update;
  if not found then
    raise exception 'Khong tim thay Goi mua hang cua Dot giao %.', p_delivery_batch_id using errcode = '22023';
  end if;

  select * into v_batch
  from public.purchase_order_delivery_batches
  where id = p_delivery_batch_id
  for update;
  if not found then
    raise exception 'Khong tim thay Dot giao %.', p_delivery_batch_id using errcode = '22023';
  end if;
  if v_batch.status = 'quality_approved' then
    raise exception 'Dot da Duyet SL/CL va khong con duoc sua.';
  end if;
  if v_batch.status <> 'receiving' then
    raise exception 'Chi huy Dot giao chua nhan va dang cho WMS.' using errcode = '22023';
  end if;
  if nullif(v_batch.wms_transaction_id, '') is null then
    raise exception 'Dot giao chua co WMS de huy.' using errcode = '22023';
  end if;

  perform app_private.assert_project_permission_room_action(
    v_po.project_id,
    v_po.construction_site_id,
    'material_po',
    'submit',
    p_actor_user_id
  );

  select * into v_tx
  from public.transactions
  where id = v_batch.wms_transaction_id
  for update;
  if not found then
    raise exception 'Khong tim thay WMS cua Dot giao.' using errcode = '22023';
  end if;
  if v_tx.source_type <> 'po_delivery_batch' or v_tx.source_id <> p_delivery_batch_id::text then
    raise exception 'WMS khong lien ket dung Dot giao.' using errcode = '22023';
  end if;
  if v_tx.status <> 'PENDING'::public.transaction_status then
    raise exception 'Chi huy Dot giao khi WMS con o trang thai cho duyet.' using errcode = '22023';
  end if;

  update public.purchase_order_delivery_batches
  set status = 'cancelled',
      note = concat_ws(E'\n', nullif(note, ''), 'Huy Dot giao: ' || p_reason),
      updated_at = now()
  where id = p_delivery_batch_id;

  update public.transactions
  set status = 'CANCELLED'::public.transaction_status,
      note = concat_ws(E'\n', nullif(note, ''), 'Huy Dot giao: ' || p_reason),
      updated_by = p_actor_user_id
  where id = v_batch.wms_transaction_id;
end;
$$;


--
-- Name: canonicalize_vehicle_booking_notification(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.canonicalize_vehicle_booking_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_booking_id text;
  v_path text;
begin
  if new.source_type = 'vehicle_booking'
     or new.category = 'vehicle_booking'
     or new.entity_type = 'vehicle_booking' then
    v_booking_id := coalesce(
      nullif(new.source_id, ''),
      nullif(new.entity_id::text, ''),
      nullif(new.metadata ->> 'booking_id', ''),
      nullif(new.metadata ->> 'bookingId', '')
    );

    if v_booking_id is not null then
      v_path := '/booking/vehicle/my?booking=' || v_booking_id;
      new.link := v_path;
      new.action_url := v_path;
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: chat_conversation_can_manage(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.chat_conversation_can_manage(p_conversation_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(p_user_id is not null, false)
    and (
      exists (
        select 1
        from public.chat_conversations cc
        where cc.id = p_conversation_id
          and cc.created_by = p_user_id::text
          and cc.deleted_at is null
      )
      or exists (
        select 1
        from public.chat_members cm
        where cm.conversation_id = p_conversation_id
          and cm.user_id = p_user_id::text
          and cm.role in ('owner', 'admin')
          and cm.left_at is null
      )
    );
$$;


--
-- Name: chat_v2_can_manage(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.chat_v2_can_manage(p_conversation_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_user_id is not null and (
    public.is_admin()
    or exists (
      select 1
      from public.chat_v2_conversations c
      where c.id = p_conversation_id
        and c.created_by = p_user_id
        and c.deleted_at is null
    )
    or exists (
      select 1
      from public.chat_v2_participants p
      where p.conversation_id = p_conversation_id
        and p.user_id = p_user_id
        and p.role in ('owner', 'admin')
        and p.left_at is null
    )
  );
$$;


--
-- Name: chat_v2_has_app_access(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.chat_v2_has_app_access(p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_user_id is not null and exists (
    select 1
    from public.users u
    where u.id = p_user_id
      and coalesce(u.is_active, true)
      and (
        u.role::text = 'ADMIN'
        or u.allowed_modules is null
        or 'CHAT' = any(u.allowed_modules)
      )
  );
$$;


--
-- Name: chat_v2_is_participant(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.chat_v2_is_participant(p_conversation_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_user_id is not null and exists (
    select 1
    from public.chat_v2_participants p
    where p.conversation_id = p_conversation_id
      and p.user_id = p_user_id
      and p.left_at is null
  );
$$;


--
-- Name: chat_v2_messages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.chat_v2_messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    conversation_id uuid NOT NULL,
    sender_id uuid NOT NULL,
    body text DEFAULT ''::text NOT NULL,
    kind text DEFAULT 'text'::text NOT NULL,
    reply_to_message_id uuid,
    legacy_message_id uuid,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    edited_at timestamp with time zone,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chat_v2_messages_kind_check CHECK ((kind = ANY (ARRAY['text'::text, 'image'::text, 'file'::text, 'poll'::text, 'checklist'::text, 'quick_confirm'::text, 'system'::text])))
);

ALTER TABLE ONLY public.chat_v2_messages REPLICA IDENTITY FULL;


--
-- Name: chat_v2_latest_message(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.chat_v2_latest_message(p_conversation_id uuid) RETURNS public.chat_v2_messages
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select m
  from public.chat_v2_messages m
  where m.conversation_id = p_conversation_id
    and m.deleted_at is null
  order by m.created_at desc, m.id desc
  limit 1;
$$;


--
-- Name: chat_v2_message_preview(text, text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.chat_v2_message_preview(p_kind text, p_body text, p_metadata jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select left(
    coalesce(
      nullif(trim(p_body), ''),
      case coalesce(p_kind, 'text')
        when 'image' then 'Hình ảnh'
        when 'file' then 'Tệp đính kèm'
        when 'poll' then 'Bình chọn: ' || coalesce(nullif(trim(p_metadata->>'question'), ''), nullif(trim(p_metadata->>'title'), ''), 'Chưa có tiêu đề')
        when 'checklist' then 'Checklist: ' || coalesce(nullif(trim(p_metadata->>'title'), ''), 'Chưa có tiêu đề')
        when 'quick_confirm' then 'Xác nhận: ' || coalesce(nullif(trim(p_metadata->>'title'), ''), 'Chưa có tiêu đề')
        when 'system' then 'Cập nhật hệ thống'
        else 'Tin nhắn'
      end
    ),
    240
  );
$$;


--
-- Name: chat_v2_notify_message(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.chat_v2_notify_message() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_sender_name text;
  v_conversation_name text;
  v_title text;
  v_message text;
begin
  if new.kind = 'system' or new.deleted_at is not null or new.legacy_message_id is not null then
    return new;
  end if;

  select coalesce(u.name, u.email, 'Người dùng')
  into v_sender_name
  from public.users u
  where u.id = new.sender_id;

  select c.name
  into v_conversation_name
  from public.chat_v2_conversations c
  where c.id = new.conversation_id;

  v_title := coalesce(v_conversation_name, v_sender_name);
  v_message := case
    when nullif(trim(new.body), '') is not null then v_sender_name || ': ' || left(trim(new.body), 140)
    else v_sender_name || ' đã gửi tệp đính kèm'
  end;

  insert into public.notifications (
    user_id,
    type,
    category,
    title,
    message,
    icon,
    link,
    severity,
    source_type,
    source_id,
    priority,
    push_enabled,
    action_url,
    entity_type,
    entity_id,
    metadata
  )
  select
    p.user_id,
    'info',
    'chat',
    v_title,
    v_message,
    '💬',
    '/chat?conversation=' || new.conversation_id::text,
    'info',
    'chat_v2_message',
    new.id::text,
    'normal',
    true,
    '/#/chat?conversation=' || new.conversation_id::text,
    'chat_v2_message',
    new.id,
    jsonb_build_object(
      'conversationId', new.conversation_id,
      'messageId', new.id,
      'senderId', new.sender_id
    )
  from public.chat_v2_participants p
  where p.conversation_id = new.conversation_id
    and p.left_at is null
    and p.is_muted is false
    and p.user_id <> new.sender_id;

  return new;
end;
$$;


--
-- Name: chat_v2_storage_conversation_id(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.chat_v2_storage_conversation_id(p_name text) RETURNS uuid
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select case
    when split_part(coalesce(p_name, ''), '/', 1) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then split_part(p_name, '/', 1)::uuid
    else null
  end;
$_$;


--
-- Name: chat_v2_sync_participant_inbox(uuid, boolean, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.chat_v2_sync_participant_inbox(p_conversation_id uuid, p_increment_unread boolean DEFAULT false, p_sender_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_message public.chat_v2_messages%rowtype;
  v_preview text;
begin
  select *
  into v_message
  from app_private.chat_v2_latest_message(p_conversation_id);

  if v_message.id is null then
    update public.chat_v2_conversations
    set last_message_id = null,
        last_message_at = null,
        last_message_preview = null,
        last_message_sender_id = null,
        updated_at = now()
    where id = p_conversation_id;

    update public.chat_v2_participants
    set last_message_id = null,
        last_message_at = null,
        last_message_preview = null,
        last_message_sender_id = null,
        unread_count = 0,
        updated_at = now()
    where conversation_id = p_conversation_id;
    return;
  end if;

  v_preview := app_private.chat_v2_message_preview(v_message.kind, v_message.body, v_message.metadata);

  update public.chat_v2_conversations
  set last_message_id = v_message.id,
      last_message_at = v_message.created_at,
      last_message_preview = v_preview,
      last_message_sender_id = v_message.sender_id,
      updated_at = now()
  where id = p_conversation_id;

  update public.chat_v2_participants p
  set last_message_id = v_message.id,
      last_message_at = v_message.created_at,
      last_message_preview = v_preview,
      last_message_sender_id = v_message.sender_id,
      unread_count = case
        when p_increment_unread
          and p_sender_id is not null
          and p.user_id <> p_sender_id
          and p.left_at is null
          and coalesce(p.is_muted, false) is false
        then p.unread_count + 1
        when p.last_read_at is not null and p.last_read_at >= v_message.created_at then 0
        else p.unread_count
      end,
      updated_at = now()
  where p.conversation_id = p_conversation_id;
end;
$$;


--
-- Name: chat_v2_touch_conversation_message(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.chat_v2_touch_conversation_message() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    perform app_private.chat_v2_sync_participant_inbox(new.conversation_id, true, new.sender_id);
    return new;
  end if;

  if tg_op = 'UPDATE' then
    perform app_private.chat_v2_sync_participant_inbox(new.conversation_id, false, new.sender_id);
    return new;
  end if;

  if tg_op = 'DELETE' then
    perform app_private.chat_v2_sync_participant_inbox(old.conversation_id, false, old.sender_id);
    return old;
  end if;

  return coalesce(new, old);
end;
$$;


--
-- Name: chat_workspace_can_manage(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.chat_workspace_can_manage(p_workspace_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(p_user_id is not null, false)
    and (
      exists (
        select 1
        from public.chat_workspaces cw
        where cw.id = p_workspace_id
          and cw.created_by = p_user_id
          and cw.deleted_at is null
      )
      or exists (
        select 1
        from public.chat_workspace_members cwm
        where cwm.workspace_id = p_workspace_id
          and cwm.user_id = p_user_id
          and cwm.role in ('owner', 'admin')
          and cwm.left_at is null
      )
    );
$$;


--
-- Name: chat_workspace_is_member(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.chat_workspace_is_member(p_workspace_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(p_user_id is not null, false)
    and exists (
      select 1
      from public.chat_workspace_members cwm
      where cwm.workspace_id = p_workspace_id
        and cwm.user_id = p_user_id
        and cwm.left_at is null
    );
$$;


--
-- Name: claim_notification_outbox_batch(integer); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.claim_notification_outbox_batch(p_batch_size integer DEFAULT 10) RETURNS TABLE(id uuid, event_key text, recipient_user_id uuid, payload jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  RETURN QUERY
  WITH claimed AS (
    SELECT o.id
    FROM app_private.vehicle_booking_notification_outbox o
    WHERE o.status = 'PENDING'
      AND o.available_at <= now()
    ORDER BY o.created_at ASC
    LIMIT p_batch_size
    FOR UPDATE SKIP LOCKED
  )
  UPDATE app_private.vehicle_booking_notification_outbox o
  SET status = 'PROCESSING',
      locked_at = now(),
      attempt_count = o.attempt_count + 1,
      updated_at = now()
  FROM claimed c
  WHERE o.id = c.id
  RETURNING o.id, o.event_key, o.recipient_user_id, o.payload;
END;
$$;


--
-- Name: claim_request_notification_outbox(integer); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.claim_request_notification_outbox(p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 50);
  v_rows jsonb;
begin
  perform app_private.require_request_notification_worker();
  with candidates as (
    select outbox.id
    from app_private.request_notification_outbox outbox
    where outbox.status in ('PENDING', 'FAILED')
      and outbox.attempt_count < 10
      and outbox.available_at <= now()
    order by outbox.available_at, outbox.id
    limit v_limit
    for update skip locked
  ), claimed as (
    update app_private.request_notification_outbox outbox
    set status = 'PROCESSING', locked_at = now(), attempt_count = outbox.attempt_count + 1
    from candidates
    where outbox.id = candidates.id
    returning outbox.id, outbox.request_id, outbox.recipient_user_id, outbox.event_key,
      outbox.event_type, outbox.payload, outbox.attempt_count
  ) select coalesce(jsonb_agg(jsonb_build_object(
    'id', id, 'requestId', request_id, 'recipientUserId', recipient_user_id,
    'eventKey', event_key, 'eventType', event_type, 'payload', payload,
    'attemptCount', attempt_count
  )), '[]'::jsonb) into v_rows from claimed;
  return v_rows;
end;
$$;


--
-- Name: claim_vehicle_notification_outbox(integer); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.claim_vehicle_notification_outbox(p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 100);
  v_rows jsonb;
begin
  perform app_private.require_vehicle_notification_worker();

  update app_private.vehicle_booking_notification_outbox outbox
  set status = 'FAILED',
      locked_at = null,
      last_error = 'Stale PROCESSING lease recovered',
      available_at = now(),
      updated_at = now()
  where outbox.status = 'PROCESSING'
    and outbox.locked_at < now() - interval '15 minutes'
    and outbox.attempt_count < 10;

  with candidates as (
    select outbox.id
    from app_private.vehicle_booking_notification_outbox outbox
    where outbox.status in ('PENDING', 'FAILED')
      and outbox.attempt_count < 10
      and outbox.available_at <= now()
    order by outbox.available_at, outbox.id
    limit v_limit
    for update skip locked
  ), claimed as (
    update app_private.vehicle_booking_notification_outbox outbox
    set status = 'PROCESSING',
        locked_at = now(),
        attempt_count = outbox.attempt_count + 1,
        updated_at = now()
    from candidates
    where outbox.id = candidates.id
    returning outbox.id, outbox.event_key, outbox.event_type,
      outbox.recipient_user_id, outbox.payload, outbox.attempt_count
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', id,
    'eventKey', event_key,
    'eventType', event_type,
    'recipientUserId', recipient_user_id,
    'payload', payload,
    'attemptCount', attempt_count
  )), '[]'::jsonb)
  into v_rows
  from claimed;

  return v_rows;
end;
$$;


--
-- Name: classify_wms_business_event(text, text, text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.classify_wms_business_event(p_type text, p_source_type text, p_related_request_id text, p_items jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_type = 'TRANSFER' then 'warehouse_transfer'
    when p_type = 'LIQUIDATION' then 'warehouse_loss'
    when p_type = 'ADJUSTMENT' then 'inventory_adjustment'
    when p_type = 'IMPORT' and exists (
      select 1 from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) line
      where nullif(line->>'materialIssueReturnId', '') is not null
    ) then 'project_return_receipt'
    when p_type = 'IMPORT' and lower(coalesce(p_source_type, '')) = 'site_direct_purchase'
      then 'site_hot_purchase_receipt'
    when p_type = 'IMPORT' and (
      lower(coalesce(p_source_type, '')) in ('supplier_direct_delivery_note', 'supplier_contract')
      or exists (
        select 1 from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) line
        where nullif(line->>'supplierDirectDeliveryNoteId', '') is not null
      )
    ) then 'direct_supplier_receipt'
    when p_type = 'IMPORT' and (
      lower(coalesce(p_source_type, '')) in ('po_delivery_batch', 'po_receipt')
      or exists (
        select 1 from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) line
        where nullif(line->>'purchaseOrderLineId', '') is not null
      )
    ) and (
      p_related_request_id is not null
      or exists (
        select 1 from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) line
        where nullif(line->>'materialRequestId', '') is not null
           or nullif(line->>'requestLineId', '') is not null
      )
    ) then 'request_po_receipt'
    when p_type = 'IMPORT' and lower(coalesce(p_source_type, '')) in ('po_delivery_batch', 'po_receipt')
      then 'proactive_po_receipt'
    when p_type = 'EXPORT' and exists (
      select 1 from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) line
      where nullif(line->>'materialIssueOrderId', '') is not null
        and nullif(line->>'materialIssueReturnId', '') is null
    ) then 'construction_issue'
    when p_type = 'EXPORT' and (
      lower(coalesce(p_source_type, '')) in ('supplier_return', 'purchase_order_supplier_return')
      or exists (
        select 1 from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) line
        where nullif(line->>'supplierReturnId', '') is not null
      )
    ) then 'supplier_return'
    else null
  end;
$$;


--
-- Name: cleanup_expired_hrm_import_batches(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.cleanup_expired_hrm_import_batches() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_count integer;
begin
  delete from storage.objects object_row
  using public.hrm_import_batches batch
  where batch.expires_at < now()
    and object_row.bucket_id = 'hrm-private-imports'
    and object_row.name = batch.source_file_path;
  delete from public.hrm_import_batches where expires_at < now();
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


--
-- Name: close_daily_log_assignments(text, uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.close_daily_log_assignments(p_log_id text, p_actor_user_id uuid, p_close_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  with closed_assignments as (
    update public.app_assignments
    set status = 'closed',
        closed_at = now(),
        closed_by = p_actor_user_id,
        close_reason = p_close_reason,
        updated_at = now()
    where subject_type = 'daily_log'
      and subject_id = p_log_id
      and status = 'active'
    returning id
  )
  insert into public.app_assignment_events (assignment_id, event_type, actor_user_id, metadata)
  select id, 'closed', p_actor_user_id, jsonb_build_object('reason', p_close_reason)
  from closed_assignments;
end;
$$;


--
-- Name: close_project_progress_period_impl(text, text, text, date, jsonb, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.close_project_progress_period_impl(p_project_id text, p_construction_site_id text, p_period_type text, p_period_start date, p_rows jsonb, p_snapshot jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := public.current_app_user_id();
  v_site_id text := nullif(btrim(coalesce(p_construction_site_id, '')), '');
  v_scope_key text;
  v_before public.project_progress_period_states%rowtype;
  v_after public.project_progress_period_states%rowtype;
begin
  v_scope_key := app_private.assert_project_progress_scope_period(
    p_project_id, v_site_id, p_period_type, p_period_start
  );
  perform app_private.assert_project_progress_action(
    v_actor_id, p_project_id, v_site_id, 'confirm'
  );

  if p_rows is null then
    if p_snapshot is not null then
      raise exception 'snapshot is accepted only with a non-empty rows draft'
        using errcode = '23514';
    end if;
  elsif jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then
    raise exception 'close draft rows must be null or a non-empty JSON array'
      using errcode = '23514';
  end if;

  insert into public.project_progress_period_states (
    scope_key, project_id, construction_site_id, period_type, period_start
  ) values (
    v_scope_key, p_project_id, v_site_id, p_period_type, p_period_start
  ) on conflict (scope_key, period_type, period_start) do nothing;

  select state.* into v_before
  from public.project_progress_period_states state
  where state.scope_key = v_scope_key
    and state.period_type = p_period_type
    and state.period_start = p_period_start
  for update;

  if v_before.is_locked then
    raise exception 'Kỳ tiến độ đã được chốt.' using errcode = '23514';
  end if;

  if p_rows is not null then
    perform app_private.assert_project_progress_action(
      v_actor_id, p_project_id, v_site_id, 'edit'
    );
    perform app_private.assert_project_progress_rows(
      p_project_id, v_site_id, p_period_type, p_rows
    );
    perform app_private.assert_project_progress_snapshot(p_snapshot);
    perform app_private.write_project_progress_period_payload(
      v_actor_id, v_scope_key, p_project_id, v_site_id,
      p_period_type, p_period_start, p_rows, p_snapshot
    );
  end if;

  update public.project_progress_period_states state
  set is_locked = true,
      locked_by = v_actor_id,
      locked_at = now(),
      unlocked_by = null,
      unlocked_at = null,
      unlock_reason = null,
      updated_at = now()
  where state.id = v_before.id
  returning state.* into v_after;

  insert into public.permission_audit_events (
    actor_user_id, event_type, before_grants, after_grants, metadata
  ) values (
    v_actor_id,
    'weekly_progress_period_locked',
    jsonb_build_array(app_private.project_progress_period_state_json(v_before)),
    jsonb_build_array(app_private.project_progress_period_state_json(v_after)),
    jsonb_build_object(
      'scope_key', v_scope_key,
      'project_id', p_project_id,
      'construction_site_id', v_site_id,
      'period_type', p_period_type,
      'period_start', p_period_start,
      'event', 'locked',
      'occurred_at', v_after.locked_at,
      'draft_saved', p_rows is not null
    )
  );

  return app_private.project_progress_period_state_json(v_after);
end;
$$;


--
-- Name: close_purchase_package_short_v2(text, uuid, text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.close_purchase_package_short_v2(p_purchase_order_id text, p_actor_user_id uuid, p_reason text, p_lines jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_po public.purchase_orders%rowtype;
  v_line jsonb;
  v_purchase_order_line_id text;
  v_close_qty numeric;
  v_po_item jsonb;
  v_request_id text;
  v_request_line_id text;
  v_item_id text;
  v_ordered_qty numeric;
  v_received_qty numeric;
  v_returned_qty numeric;
  v_existing_closed_qty numeric;
  v_remaining_need numeric;
  v_total_closed_qty numeric := 0;
  v_previous_guard text;
begin
  if p_actor_user_id is null then
    raise exception 'Nguoi thuc hien lenh khong hop le.' using errcode = '42501';
  end if;
  if public.current_app_user_id() is null or p_actor_user_id <> public.current_app_user_id() then
    raise exception 'Nguoi thuc hien lenh khong hop le.' using errcode = '42501';
  end if;
  if nullif(trim(coalesce(p_reason, '')), '') is null then
    raise exception 'Ly do ket thuc thieu la bat buoc.' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_lines, '[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p_lines, '[]'::jsonb)) = 0 then
    raise exception 'Phai co it nhat mot dong can ket thuc thieu.' using errcode = '22023';
  end if;

  select * into v_po
  from public.purchase_orders
  where id = p_purchase_order_id
  for update;
  if not found then
    raise exception 'Khong tim thay Goi mua hang %.', p_purchase_order_id using errcode = '22023';
  end if;
  if coalesce(v_po.source_mode, '') <> 'from_request' or coalesce(v_po.purchase_mode, '') not in ('single', 'multiple') then
    raise exception 'Chi ket thuc thieu cho Goi mua hang V2 tao tu MR.' using errcode = '22023';
  end if;
  if v_po.status not in ('confirmed', 'in_transit', 'partial') then
    raise exception 'Chi ket thuc thieu cho Goi da duyet hoac dang giao.' using errcode = '22023';
  end if;

  perform app_private.assert_project_permission_room_action(
    v_po.project_id,
    v_po.construction_site_id,
    'material_po',
    'submit',
    p_actor_user_id
  );

  if exists (
    select 1
    from public.purchase_order_delivery_batches batch
    where batch.purchase_order_id = p_purchase_order_id
      and batch.status not in ('received', 'cancelled')
  ) then
    raise exception 'Goi mua hang con Dot giao mo, khong the ket thuc thieu.' using errcode = '22023';
  end if;

  for v_line in
    select value from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) as line(value)
  loop
    v_purchase_order_line_id := nullif(v_line ->> 'purchaseOrderLineId', '');
    v_close_qty := coalesce(nullif(v_line ->> 'closeQty', '')::numeric, 0);
    if v_purchase_order_line_id is null then
      raise exception 'Dong ket thuc thieu thieu PO line.' using errcode = '22023';
    end if;
    if v_close_qty <= 0 then
      raise exception 'So luong ket thuc thieu phai lon hon 0.' using errcode = '22023';
    end if;

    select item.value into v_po_item
    from jsonb_array_elements(coalesce(v_po.items, '[]'::jsonb)) as item(value)
    where coalesce(item.value ->> 'lineId', item.value ->> 'itemId') = v_purchase_order_line_id
    limit 1;
    if v_po_item is null then
      raise exception 'Khong tim thay dong Goi mua hang %.', v_purchase_order_line_id using errcode = '22023';
    end if;

    v_request_id := nullif(v_po_item ->> 'requestId', '');
    v_request_line_id := nullif(v_po_item ->> 'requestLineId', '');
    v_item_id := nullif(v_po_item ->> 'itemId', '');
    if v_request_id is null or v_request_line_id is null or v_item_id is null then
      raise exception 'Dong Goi mua hang thieu lien ket MR.' using errcode = '22023';
    end if;

    v_ordered_qty := coalesce(nullif(v_po_item ->> 'qty', '')::numeric, 0);
    v_received_qty := coalesce(nullif(v_po_item ->> 'receivedQty', '')::numeric, 0);
    v_returned_qty := coalesce(nullif(v_po_item ->> 'returnedQty', '')::numeric, 0);

    select coalesce(sum(closure.closed_qty), 0)
    into v_existing_closed_qty
    from public.material_request_line_need_closures closure
    where closure.material_request_id = v_request_id
      and closure.request_line_id = v_request_line_id
      and closure.status = 'active';

    v_remaining_need := greatest(0, v_ordered_qty - greatest(0, v_received_qty - v_returned_qty) - v_existing_closed_qty);
    if v_close_qty > v_remaining_need then
      raise exception 'So luong ket thuc thieu vuot nhu cau con lai cua dong %.', v_purchase_order_line_id using errcode = '22023';
    end if;

    insert into public.material_request_line_need_closures (
      project_id,
      construction_site_id,
      material_request_id,
      request_line_id,
      item_id,
      work_boq_item_id,
      material_budget_item_id,
      closed_qty,
      actual_received_qty_snapshot,
      reason,
      status,
      closed_by,
      closed_at
    ) values (
      v_po.project_id,
      v_po.construction_site_id,
      v_request_id,
      v_request_line_id,
      v_item_id,
      nullif(v_po_item ->> 'workBoqItemId', ''),
      nullif(v_po_item ->> 'materialBudgetItemId', ''),
      v_close_qty,
      greatest(0, v_received_qty - v_returned_qty),
      trim(p_reason),
      'active',
      p_actor_user_id,
      now()
    );

    v_total_closed_qty := v_total_closed_qty + v_close_qty;
  end loop;

  v_previous_guard := current_setting('app.material_transition_context', true);
  perform set_config('app.material_transition_context', 'on', true);

  update public.purchase_orders
  set closed_need_qty = coalesce(closed_need_qty, 0) + v_total_closed_qty,
      status = 'closed',
      last_action_by = p_actor_user_id::text,
      last_action_at = now()
  where id = p_purchase_order_id;

  perform set_config('app.material_transition_context', coalesce(v_previous_guard, ''), true);
exception
  when others then
    perform set_config('app.material_transition_context', coalesce(v_previous_guard, ''), true);
    raise;
end;
$$;


--
-- Name: close_request_pending_assignments(uuid, text, uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.close_request_pending_assignments(p_request_id uuid, p_status text, p_round_id uuid DEFAULT NULL::uuid, p_block_key text DEFAULT NULL::text, p_comment text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.workflow_step_assignments assignment
  set status = p_status,
      acted_at = now(),
      action_comment = coalesce(p_comment, action_comment)
  where assignment.workflow_subject_id = (
      select request_instance.workflow_subject_id
      from public.request_instances request_instance
      where request_instance.id = p_request_id
    )
    and assignment.status = 'PENDING'
    and (p_round_id is null or assignment.assignment_round_id = p_round_id)
    and (
      p_block_key is null
      or assignment.metadata ->> 'requestBlockKey' = p_block_key
    );
end;
$$;


--
-- Name: command_approve_vehicle_booking(uuid, uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_approve_vehicle_booking(p_actor_user_id uuid, p_booking_id uuid, p_approval_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_booking record;
  v_source text := 'MANAGER';
BEGIN
  SELECT * INTO v_booking FROM public.vehicle_bookings WHERE id = p_booking_id FOR UPDATE;

  IF v_booking IS NULL THEN
    RAISE EXCEPTION 'BOOKING_NOT_FOUND: Booking does not exist';
  END IF;

  IF v_booking.status != 'PENDING_APPROVAL' THEN
    RAISE EXCEPTION 'INVALID_STATUS_TRANSITION: Booking is not in PENDING_APPROVAL status';
  END IF;

  -- Kiểm tra vai trò Manager hoặc Dispatcher Override
  IF v_booking.manager_user_id_snapshot IS NOT NULL AND v_booking.manager_user_id_snapshot = p_actor_user_id THEN
    v_source := 'MANAGER';
  ELSIF app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.dispatch') THEN
    v_source := 'DISPATCH_OVERRIDE';
    IF p_approval_note IS NULL OR length(trim(p_approval_note)) = 0 THEN
      RAISE EXCEPTION 'APPROVAL_NOTE_REQUIRED: Dispatcher override requires approval note';
    END IF;
  ELSE
    RAISE EXCEPTION 'PERMISSION_DENIED: Only assigned manager or dispatcher can approve';
  END IF;

  UPDATE public.vehicle_bookings SET
    status = 'WAITING_DISPATCH',
    approved_by_user_id = p_actor_user_id,
    approved_at = now(),
    approval_source = v_source,
    approval_note = p_approval_note,
    manager_resolution_status = CASE WHEN v_source = 'DISPATCH_OVERRIDE' THEN 'OVERRIDDEN' ELSE 'NORMAL' END,
    updated_at = now()
  WHERE id = p_booking_id;

  RETURN jsonb_build_object('success', true, 'status', 'WAITING_DISPATCH', 'approval_source', v_source);
END;
$$;


--
-- Name: command_cancel_operator_unavailability(uuid, uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_cancel_operator_unavailability(p_actor_user_id uuid, p_unavailability_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_period public.operator_unavailability_periods%rowtype;
begin
  select * into v_period from public.operator_unavailability_periods
  where id = p_unavailability_id for update;
  if not found then raise exception using errcode = 'P0001', message = 'UNAVAILABILITY_NOT_FOUND'; end if;
  if p_actor_user_id is distinct from v_period.operator_user_id
     and not app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.dispatch')
     and not app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.manage_authorizations') then
    perform app_private.vehicle_raise_permission_denied('Operator or fleet administrator is required');
  end if;
  if nullif(trim(p_reason), '') is null then
    raise exception using errcode = 'P0001', message = 'CANCEL_REASON_REQUIRED';
  end if;
  delete from public.operator_unavailability_periods where id = p_unavailability_id;
  return jsonb_build_object('success', true, 'id', p_unavailability_id);
end;
$$;


--
-- Name: command_cancel_vehicle_booking(uuid, uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_cancel_vehicle_booking(p_actor_user_id uuid, p_booking_id uuid, p_cancel_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_booking public.vehicle_bookings%rowtype;
  v_assignment public.vehicle_booking_assignments%rowtype;
  v_is_dispatcher boolean := false;
  v_cutoff_minutes integer := 120;
  v_close_reason text;
begin
  select * into v_booking from public.vehicle_bookings where id = p_booking_id for update;
  if not found then
    raise exception using errcode = 'P0001', message = 'BOOKING_NOT_FOUND';
  end if;
  if v_booking.status in ('IN_PROGRESS', 'COMPLETED', 'CANCELLED') then
    raise exception using errcode = 'P0001', message = 'INVALID_STATUS_TRANSITION';
  end if;

  v_is_dispatcher := app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.dispatch');
  if v_booking.requester_user_id is distinct from p_actor_user_id and not v_is_dispatcher then
    perform app_private.vehicle_raise_permission_denied('Only requester or dispatcher can cancel');
  end if;

  select coalesce(settings.late_cancellation_cutoff_minutes, 120)
  into v_cutoff_minutes from public.fleet_system_settings settings where settings.id = 1;

  if v_is_dispatcher and v_booking.requester_user_id is distinct from p_actor_user_id then
    v_close_reason := 'CANCELLED_BY_DISPATCHER';
  elsif now() + make_interval(mins => v_cutoff_minutes) >= v_booking.requested_pickup_at then
    v_close_reason := 'LATE_CANCELLED';
  else
    v_close_reason := 'CANCELLED_BY_REQUESTER';
  end if;

  if v_close_reason in ('LATE_CANCELLED', 'CANCELLED_BY_DISPATCHER')
     and nullif(trim(p_cancel_reason), '') is null then
    raise exception using errcode = 'P0001', message = 'CANCEL_REASON_REQUIRED';
  end if;

  select * into v_assignment
  from public.vehicle_booking_assignments assignment
  where assignment.booking_id = p_booking_id and assignment.is_active
  for update;

  update public.vehicle_bookings
  set status = 'CANCELLED',
      close_reason = v_close_reason,
      close_note = nullif(trim(p_cancel_reason), ''),
      cancelled_by_user_id = p_actor_user_id,
      cancelled_at = now(),
      updated_at = now()
  where id = p_booking_id;

  if v_assignment.id is not null then
    update public.vehicle_booking_assignments
    set released_at = coalesce(released_at, now()), updated_at = now()
    where id = v_assignment.id;
    update public.fleet_vehicle_profiles
    set custody_status = 'AVAILABLE', current_custody_assignment_id = null, updated_at = now()
    where current_custody_assignment_id = v_assignment.id;
  end if;

  perform app_private.vehicle_record_audit(
    p_actor_user_id, p_booking_id, 'CANCELLED',
    jsonb_build_object('status', v_booking.status),
    jsonb_build_object('status', 'CANCELLED', 'close_reason', v_close_reason),
    'Hủy booking xe'
  );
  perform app_private.vehicle_enqueue_notification(
    p_booking_id, 'BOOKING_CANCELLED', v_booking.manager_user_id_snapshot,
    jsonb_build_object('booking_code', v_booking.booking_code, 'close_reason', v_close_reason)
  );
  perform app_private.vehicle_enqueue_notification(
    p_booking_id, 'BOOKING_CANCELLED', v_assignment.operator_user_id,
    jsonb_build_object('booking_code', v_booking.booking_code, 'close_reason', v_close_reason)
  );
  return jsonb_build_object('success', true, 'status', 'CANCELLED', 'close_reason', v_close_reason);
end;
$$;


--
-- Name: command_cancel_vehicle_unavailability(uuid, uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_cancel_vehicle_unavailability(p_actor_user_id uuid, p_unavailability_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.manage_fleet') then
    perform app_private.vehicle_raise_permission_denied('Fleet management permission is required');
  end if;
  if nullif(trim(p_reason), '') is null then
    raise exception using errcode = 'P0001', message = 'CANCEL_REASON_REQUIRED';
  end if;
  delete from public.vehicle_unavailability_periods where id = p_unavailability_id;
  if not found then raise exception using errcode = 'P0001', message = 'UNAVAILABILITY_NOT_FOUND'; end if;
  return jsonb_build_object('success', true, 'id', p_unavailability_id);
end;
$$;


--
-- Name: command_complete_external_transport(uuid, uuid, numeric, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_complete_external_transport(p_actor_user_id uuid, p_booking_id uuid, p_external_actual_cost numeric DEFAULT NULL::numeric, p_external_receipt_path text DEFAULT NULL::text, p_completion_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_booking public.vehicle_bookings%rowtype;
  v_assignment public.vehicle_booking_assignments%rowtype;
begin
  select * into v_booking from public.vehicle_bookings where id = p_booking_id for update;
  select * into v_assignment from public.vehicle_booking_assignments
  where booking_id = p_booking_id and is_active for update;

  if v_booking.id is null or v_assignment.id is null then
    raise exception using errcode = 'P0001', message = 'ASSIGNMENT_NOT_FOUND';
  end if;
  if v_booking.status <> 'ASSIGNED' or v_assignment.fulfillment_type <> 'EXTERNAL_TRANSPORT' then
    raise exception using errcode = 'P0001', message = 'INVALID_STATUS_TRANSITION';
  end if;
  if p_actor_user_id not in (v_booking.requester_user_id, coalesce(v_booking.trip_owner_user_id, v_booking.requester_user_id))
     and not app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.dispatch') then
    perform app_private.vehicle_raise_permission_denied('Requester, trip owner or dispatcher is required');
  end if;
  if p_external_actual_cost is not null and p_external_actual_cost < 0 then
    raise exception using errcode = 'P0001', message = 'INVALID_EXTERNAL_COST';
  end if;
  if p_external_receipt_path is not null
     and p_external_receipt_path not like p_booking_id::text || '/external/%' then
    raise exception using errcode = 'P0001', message = 'INVALID_EVIDENCE_PATH';
  end if;

  update public.vehicle_booking_assignments
  set external_actual_cost = p_external_actual_cost,
      external_receipt_path = nullif(trim(p_external_receipt_path), ''),
      assignment_note = concat_ws(E'\n', assignment_note, nullif(trim(p_completion_note), '')),
      released_at = now(),
      updated_at = now()
  where id = v_assignment.id;
  update public.vehicle_bookings set status = 'COMPLETED', updated_at = now() where id = p_booking_id;
  insert into public.vehicle_booking_feedback(booking_id, respondent_user_id, status)
  values (p_booking_id, v_booking.requester_user_id, 'PENDING')
  on conflict (booking_id) do nothing;

  perform app_private.vehicle_record_audit(
    p_actor_user_id, p_booking_id, 'EXTERNAL_TRANSPORT_COMPLETED',
    jsonb_build_object('status', v_booking.status),
    jsonb_build_object('status', 'COMPLETED', 'external_actual_cost', p_external_actual_cost),
    'Hoàn tất chuyến xe ngoài'
  );
  perform app_private.vehicle_enqueue_notification(
    p_booking_id, 'TRIP_COMPLETED', v_booking.requester_user_id,
    jsonb_build_object('booking_code', v_booking.booking_code)
  );
  return jsonb_build_object('success', true, 'status', 'COMPLETED');
end;
$$;


--
-- Name: command_confirm_vehicle_handover(uuid, uuid, text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_confirm_vehicle_handover(p_actor_user_id uuid, p_booking_id uuid, p_event_type text, p_note text DEFAULT NULL::text, p_override_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_booking public.vehicle_bookings%rowtype;
  v_assignment public.vehicle_booking_assignments%rowtype;
  v_handover_id uuid := gen_random_uuid();
  v_on_behalf boolean := false;
begin
  if p_event_type not in ('OUTBOUND_HANDOVER', 'RETURN_RECEIPT') then
    raise exception using errcode = 'P0001', message = 'INVALID_HANDOVER_EVENT';
  end if;

  select * into v_booking
  from public.vehicle_bookings booking
  where booking.id = p_booking_id
  for update;
  select * into v_assignment
  from public.vehicle_booking_assignments assignment
  where assignment.booking_id = p_booking_id and assignment.is_active
  for update;

  if v_booking.id is null or v_assignment.id is null then
    raise exception using errcode = 'P0001', message = 'ASSIGNMENT_NOT_FOUND';
  end if;
  if v_assignment.fulfillment_type <> 'INTERNAL_SELF_DRIVE' then
    raise exception using errcode = 'P0001', message = 'HANDOVER_NOT_APPLICABLE';
  end if;
  if p_event_type = 'OUTBOUND_HANDOVER' and v_booking.status <> 'ASSIGNED' then
    raise exception using errcode = 'P0001', message = 'INVALID_STATUS_TRANSITION';
  end if;
  if p_event_type = 'RETURN_RECEIPT' and v_booking.status <> 'COMPLETED' then
    raise exception using errcode = 'P0001', message = 'INVALID_STATUS_TRANSITION';
  end if;

  if v_assignment.handover_officer_user_id is distinct from p_actor_user_id then
    if not app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.dispatch') then
      perform app_private.vehicle_raise_permission_denied('Only the handover officer or dispatcher can confirm');
    end if;
    if nullif(trim(p_override_reason), '') is null then
      raise exception using errcode = 'P0001', message = 'OVERRIDE_REASON_REQUIRED';
    end if;
    v_on_behalf := true;
  end if;

  if p_event_type = 'RETURN_RECEIPT' and not exists (
    select 1 from public.vehicle_handover_logs log
    where log.assignment_id = v_assignment.id
      and log.event_type = 'OUTBOUND_HANDOVER'
  ) then
    raise exception using errcode = 'P0001', message = 'OUTBOUND_HANDOVER_REQUIRED';
  end if;

  insert into public.vehicle_handover_logs (
    id, booking_id, assignment_id, assignment_version_snapshot,
    vehicle_asset_id_snapshot, operator_user_id_snapshot, event_type,
    officer_user_id, confirmed_on_behalf, override_reason, note
  ) values (
    v_handover_id, p_booking_id, v_assignment.id, v_assignment.version,
    v_assignment.vehicle_asset_id, v_assignment.operator_user_id, p_event_type,
    p_actor_user_id, v_on_behalf, nullif(trim(p_override_reason), ''), p_note
  );

  if p_event_type = 'OUTBOUND_HANDOVER' then
    update public.fleet_vehicle_profiles
    set custody_status = 'IN_CUSTODY',
        current_custody_assignment_id = v_assignment.id,
        updated_at = now()
    where asset_id = v_assignment.vehicle_asset_id
      and (
        current_custody_assignment_id is null
        or current_custody_assignment_id = v_assignment.id
      );
    if not found then
      raise exception using errcode = 'P0001', message = 'VEHICLE_IN_CUSTODY';
    end if;
  else
    update public.fleet_vehicle_profiles
    set custody_status = 'AVAILABLE',
        current_custody_assignment_id = null,
        updated_at = now()
    where asset_id = v_assignment.vehicle_asset_id
      and current_custody_assignment_id = v_assignment.id;
    update public.vehicle_booking_assignments
    set released_at = coalesce(released_at, now()), updated_at = now()
    where id = v_assignment.id;
  end if;

  perform app_private.vehicle_record_audit(
    p_actor_user_id,
    p_booking_id,
    p_event_type,
    '{}'::jsonb,
    jsonb_build_object('assignment_id', v_assignment.id, 'confirmed_on_behalf', v_on_behalf),
    case when p_event_type = 'OUTBOUND_HANDOVER' then 'Bàn giao xe tự lái' else 'Nhận lại xe tự lái' end
  );

  return jsonb_build_object('success', true, 'handover_id', v_handover_id, 'event_type', p_event_type);
end;
$$;


--
-- Name: command_confirm_vehicle_return(uuid, uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_confirm_vehicle_return(p_actor_user_id uuid, p_booking_id uuid, p_note text DEFAULT NULL::text, p_override_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_result jsonb;
begin
  v_result := app_private.command_confirm_vehicle_handover(
    p_actor_user_id,
    p_booking_id,
    'RETURN_RECEIPT',
    p_note,
    p_override_reason
  );
  return v_result || jsonb_build_object('custody_status', 'AVAILABLE');
end;
$$;


--
-- Name: command_create_operator_unavailability(uuid, uuid, timestamp with time zone, timestamp with time zone, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_create_operator_unavailability(p_actor_user_id uuid, p_operator_user_id uuid, p_start_at timestamp with time zone, p_end_at timestamp with time zone, p_reason_code text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid := gen_random_uuid();
begin
  if p_actor_user_id is distinct from p_operator_user_id
     and not app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.dispatch')
     and not app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.manage_authorizations') then
    perform app_private.vehicle_raise_permission_denied('Operator or fleet administrator is required');
  end if;
  if p_end_at <= p_start_at then
    raise exception using errcode = 'P0001', message = 'INVALID_UNAVAILABILITY_RANGE';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('operator:' || p_operator_user_id::text, 0));
  if exists (
    select 1 from public.vehicle_booking_assignments assignment
    where assignment.operator_user_id = p_operator_user_id
      and assignment.is_active and assignment.released_at is null
      and assignment.scheduled_range && tstzrange(p_start_at, p_end_at, '[)')
  ) then
    raise exception using errcode = 'P0001', message = 'OPERATOR_TIME_CONFLICT';
  end if;

  insert into public.operator_unavailability_periods(
    id, operator_user_id, start_at, end_at, reason_code, note, created_by_user_id
  ) values (v_id, p_operator_user_id, p_start_at, p_end_at, p_reason_code, p_note, p_actor_user_id);
  return jsonb_build_object('success', true, 'id', v_id);
end;
$$;


--
-- Name: command_create_vehicle_booking(uuid, timestamp with time zone, timestamp with time zone, text, text, text, text, integer, text, jsonb, text, uuid, text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_create_vehicle_booking(p_actor_user_id uuid, p_requested_pickup_at timestamp with time zone, p_expected_return_at timestamp with time zone, p_trip_type text, p_pickup_location_text text, p_destination_text text, p_purpose text, p_passenger_count integer, p_requested_mode text, p_route_stops jsonb DEFAULT '[]'::jsonb, p_preferred_vehicle_asset_id text DEFAULT NULL::text, p_preferred_driver_user_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text, p_trip_owner_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_booking_id uuid := gen_random_uuid();
  v_booking_code text;
  v_seq integer;
  v_date_str text;
  v_manager_user_id uuid;
  v_emp_id uuid;
  v_dept_id uuid;
BEGIN
  SELECT nextval('public.vehicle_booking_code_seq') INTO v_seq;
  v_date_str := to_char(now() AT TIME ZONE 'Asia/Ho_Chi_Minh', 'YYMMDD');
  v_booking_code := 'CAR-' || v_date_str || '-' || lpad(v_seq::text, 4, '0');

  SELECT e.id, e.department_id INTO v_emp_id, v_dept_id
  FROM public.employees e
  WHERE e.user_id = p_actor_user_id
  LIMIT 1;

  INSERT INTO public.vehicle_bookings (
    id, booking_code, requester_user_id, trip_owner_user_id, requester_employee_id_snapshot,
    department_id_snapshot, requested_pickup_at, expected_return_at, trip_type, pickup_location_text,
    destination_text, route_stops, purpose, passenger_count, requested_mode, preferred_vehicle_asset_id,
    preferred_driver_user_id, note, status
  ) VALUES (
    v_booking_id, v_booking_code, p_actor_user_id, COALESCE(p_trip_owner_user_id, p_actor_user_id),
    v_emp_id, v_dept_id, p_requested_pickup_at, p_expected_return_at, p_trip_type, p_pickup_location_text,
    p_destination_text, p_route_stops, p_purpose, p_passenger_count, p_requested_mode, p_preferred_vehicle_asset_id,
    p_preferred_driver_user_id, p_note, 'DRAFT'
  );

  RETURN jsonb_build_object('success', true, 'id', v_booking_id, 'booking_code', v_booking_code);
END;
$$;


--
-- Name: command_create_vehicle_unavailability(uuid, text, timestamp with time zone, timestamp with time zone, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_create_vehicle_unavailability(p_actor_user_id uuid, p_vehicle_asset_id text, p_start_at timestamp with time zone, p_end_at timestamp with time zone, p_reason_code text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_id uuid := gen_random_uuid();
BEGIN
  IF NOT app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.manage_fleet') THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: User does not have permission to manage vehicle unavailability';
  END IF;

  -- Advisory lock chống race condition
  PERFORM pg_advisory_xact_lock(hashtextextended('vehicle:' || p_vehicle_asset_id, 0));

  -- Check overlap với active assignments
  IF EXISTS (
    SELECT 1 FROM public.vehicle_booking_assignments a
    WHERE a.vehicle_asset_id = p_vehicle_asset_id
      AND a.is_active = true
      AND a.released_at IS NULL
      AND tstzrange(a.reserved_start_at, a.reserved_end_at, '[)') && tstzrange(p_start_at, p_end_at, '[)')
  ) THEN
    RAISE EXCEPTION 'VEHICLE_TIME_CONFLICT: Vehicle is already assigned during this period';
  END IF;

  INSERT INTO public.vehicle_unavailability_periods (id, vehicle_asset_id, start_at, end_at, reason_code, note, created_by_user_id)
  VALUES (v_id, p_vehicle_asset_id, p_start_at, p_end_at, p_reason_code, p_note, p_actor_user_id);

  RETURN jsonb_build_object('success', true, 'id', v_id);
END;
$$;


--
-- Name: command_dispatch_vehicle_booking(uuid, uuid, text, text, uuid, uuid, boolean, text, text, text, text, text, text, numeric, text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_dispatch_vehicle_booking(p_actor_user_id uuid, p_booking_id uuid, p_fulfillment_type text, p_vehicle_asset_id text DEFAULT NULL::text, p_operator_user_id uuid DEFAULT NULL::uuid, p_handover_officer_user_id uuid DEFAULT NULL::uuid, p_allow_non_home_base_return boolean DEFAULT false, p_non_home_base_return_reason text DEFAULT NULL::text, p_external_service_type text DEFAULT NULL::text, p_external_provider_name text DEFAULT NULL::text, p_external_driver_name text DEFAULT NULL::text, p_external_driver_phone text DEFAULT NULL::text, p_external_vehicle_plate text DEFAULT NULL::text, p_external_estimated_cost numeric DEFAULT NULL::numeric, p_dispatch_reason_code text DEFAULT NULL::text, p_assignment_note text DEFAULT NULL::text, p_override_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_booking public.vehicle_bookings%rowtype;
  v_assignment_id uuid := gen_random_uuid();
  v_buffer_minutes integer := 0;
  v_keys text[] := array[]::text[];
  v_key text;
  v_operator_type text;
  v_home_base_id uuid;
begin
  if not app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.dispatch') then
    perform app_private.vehicle_raise_permission_denied('Dispatcher permission is required');
  end if;

  select * into v_booking
  from public.vehicle_bookings b
  where b.id = p_booking_id
  for update;

  if not found then
    raise exception using errcode = 'P0001', message = 'BOOKING_NOT_FOUND';
  end if;
  if v_booking.status not in ('PENDING_APPROVAL', 'WAITING_DISPATCH') then
    raise exception using errcode = 'P0001', message = 'INVALID_STATUS_TRANSITION';
  end if;
  if v_booking.status = 'PENDING_APPROVAL'
     and nullif(trim(p_override_reason), '') is null then
    raise exception using errcode = 'P0001', message = 'OVERRIDE_REASON_REQUIRED';
  end if;

  if p_vehicle_asset_id is not null then
    v_keys := array_append(v_keys, 'vehicle:' || p_vehicle_asset_id);
  end if;
  if p_operator_user_id is not null then
    v_keys := array_append(v_keys, 'operator:' || p_operator_user_id::text);
  end if;
  select coalesce(array_agg(resource_key order by resource_key), array[]::text[])
  into v_keys
  from unnest(v_keys) resource_key;
  foreach v_key in array v_keys loop
    perform pg_advisory_xact_lock(hashtextextended(v_key, 0));
  end loop;

  perform app_private.vehicle_validate_assignment(
    p_booking_id,
    p_fulfillment_type,
    p_vehicle_asset_id,
    p_operator_user_id,
    p_handover_officer_user_id,
    p_allow_non_home_base_return,
    p_non_home_base_return_reason,
    p_external_service_type
  );

  select coalesce(settings.booking_buffer_minutes, 0)
  into v_buffer_minutes
  from public.fleet_system_settings settings
  where settings.id = 1;

  if p_vehicle_asset_id is not null then
    select profile.home_base_id into v_home_base_id
    from public.fleet_vehicle_profiles profile
    where profile.asset_id = p_vehicle_asset_id;
  end if;

  v_operator_type := case p_fulfillment_type
    when 'INTERNAL_WITH_DRIVER' then 'PROFESSIONAL_DRIVER'
    when 'INTERNAL_SELF_DRIVE' then 'SELF_DRIVER'
    else null
  end;

  insert into public.vehicle_booking_assignments (
    id, booking_id, version, is_active, fulfillment_type,
    vehicle_asset_id, operator_user_id, operator_type,
    reserved_start_at, reserved_end_at, home_base_id_snapshot,
    handover_officer_user_id, allow_non_home_base_return,
    non_home_base_return_reason, external_service_type,
    external_provider_name, external_driver_name, external_driver_phone,
    external_vehicle_plate, external_estimated_cost, dispatch_reason_code,
    assigned_by_user_id, assignment_note
  ) values (
    v_assignment_id, p_booking_id, 1, true, p_fulfillment_type,
    p_vehicle_asset_id, p_operator_user_id, v_operator_type,
    v_booking.requested_pickup_at,
    v_booking.expected_return_at + make_interval(mins => coalesce(v_buffer_minutes, 0)),
    v_home_base_id, p_handover_officer_user_id,
    coalesce(p_allow_non_home_base_return, false), p_non_home_base_return_reason,
    p_external_service_type, p_external_provider_name, p_external_driver_name,
    p_external_driver_phone, p_external_vehicle_plate, p_external_estimated_cost,
    p_dispatch_reason_code, p_actor_user_id, p_assignment_note
  );

  if p_fulfillment_type <> 'EXTERNAL_TRANSPORT' then
    insert into public.vehicle_trip_logs (
      booking_id, assignment_id, assignment_version_snapshot,
      vehicle_asset_id_snapshot, operator_user_id_snapshot, trip_status
    ) values (
      p_booking_id, v_assignment_id, 1,
      p_vehicle_asset_id, p_operator_user_id, 'NOT_STARTED'
    );
  end if;

  update public.vehicle_bookings
  set status = 'ASSIGNED',
      approved_by_user_id = coalesce(approved_by_user_id, p_actor_user_id),
      approved_at = coalesce(approved_at, now()),
      approval_source = case when status = 'PENDING_APPROVAL' then 'DISPATCH_OVERRIDE' else approval_source end,
      approval_note = case when status = 'PENDING_APPROVAL' then trim(p_override_reason) else approval_note end,
      manager_resolution_status = case when status = 'PENDING_APPROVAL' then 'OVERRIDDEN' else manager_resolution_status end,
      updated_at = now()
  where id = p_booking_id;

  perform app_private.vehicle_record_audit(
    p_actor_user_id,
    p_booking_id,
    case when v_booking.status = 'PENDING_APPROVAL' then 'DISPATCH_OVERRIDE' else 'DISPATCHED' end,
    jsonb_build_object('status', v_booking.status),
    jsonb_build_object('status', 'ASSIGNED', 'assignment_id', v_assignment_id, 'fulfillment_type', p_fulfillment_type),
    'Điều phối booking xe'
  );
  perform app_private.vehicle_enqueue_notification(
    p_booking_id,
    'BOOKING_ASSIGNED',
    v_booking.requester_user_id,
    jsonb_build_object('booking_code', v_booking.booking_code, 'assignment_id', v_assignment_id)
  );
  perform app_private.vehicle_enqueue_notification(
    p_booking_id,
    'BOOKING_ASSIGNED',
    p_operator_user_id,
    jsonb_build_object('booking_code', v_booking.booking_code, 'assignment_id', v_assignment_id)
  );
  perform app_private.vehicle_enqueue_notification(
    p_booking_id,
    'HANDOVER_ASSIGNED',
    p_handover_officer_user_id,
    jsonb_build_object('booking_code', v_booking.booking_code, 'assignment_id', v_assignment_id)
  );

  return jsonb_build_object('success', true, 'assignment_id', v_assignment_id, 'status', 'ASSIGNED');
end;
$$;


--
-- Name: command_finish_vehicle_trip(uuid, uuid, numeric, text, numeric, numeric, numeric, boolean, text, text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_finish_vehicle_trip(p_actor_user_id uuid, p_booking_id uuid, p_end_odometer numeric, p_end_photo_path text, p_latitude numeric DEFAULT NULL::numeric, p_longitude numeric DEFAULT NULL::numeric, p_accuracy_m numeric DEFAULT NULL::numeric, p_location_capture_failed boolean DEFAULT false, p_location_failure_reason text DEFAULT NULL::text, p_vehicle_condition_end text DEFAULT 'NORMAL'::text, p_issue_note text DEFAULT NULL::text, p_override_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_booking public.vehicle_bookings%rowtype;
  v_assignment public.vehicle_booking_assignments%rowtype;
  v_trip public.vehicle_trip_logs%rowtype;
  v_distance numeric(12, 1);
  v_is_dispatcher boolean := false;
begin
  select * into v_booking from public.vehicle_bookings where id = p_booking_id for update;
  select * into v_assignment from public.vehicle_booking_assignments
  where booking_id = p_booking_id and is_active for update;
  select * into v_trip from public.vehicle_trip_logs where booking_id = p_booking_id for update;

  if v_booking.id is null or v_assignment.id is null or v_trip.id is null then
    raise exception using errcode = 'P0001', message = 'TRIP_LOG_NOT_FOUND';
  end if;
  if v_booking.status <> 'IN_PROGRESS' or v_trip.trip_status <> 'IN_PROGRESS' then
    raise exception using errcode = 'P0001', message = 'INVALID_STATUS_TRANSITION';
  end if;

  v_is_dispatcher := app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.dispatch');
  if v_assignment.operator_user_id is distinct from p_actor_user_id then
    if not v_is_dispatcher then
      perform app_private.vehicle_raise_permission_denied('Only assigned operator or dispatcher can finish');
    end if;
    if nullif(trim(p_override_reason), '') is null then
      raise exception using errcode = 'P0001', message = 'OVERRIDE_REASON_REQUIRED';
    end if;
  end if;

  if p_end_odometer is null then
    raise exception using errcode = 'P0001', message = 'ODOMETER_REQUIRED';
  end if;
  if p_end_odometer < v_trip.start_odometer then
    raise exception using errcode = 'P0001', message = 'INVALID_ODOMETER_RANGE';
  end if;
  perform app_private.vehicle_assert_evidence_path(p_booking_id, p_end_photo_path, 'trips');

  if coalesce(p_location_capture_failed, false) then
    if nullif(trim(p_location_failure_reason), '') is null then
      raise exception using errcode = 'P0001', message = 'LOCATION_FAILURE_REASON_REQUIRED';
    end if;
  elsif p_latitude is null or p_longitude is null then
    raise exception using errcode = 'P0001', message = 'LOCATION_REQUIRED';
  end if;
  if p_vehicle_condition_end not in ('NORMAL', 'ISSUE') then
    raise exception using errcode = 'P0001', message = 'INVALID_VEHICLE_CONDITION';
  end if;
  if p_vehicle_condition_end = 'ISSUE' and nullif(trim(p_issue_note), '') is null then
    raise exception using errcode = 'P0001', message = 'ISSUE_NOTE_REQUIRED';
  end if;

  v_distance := p_end_odometer - v_trip.start_odometer;

  update public.vehicle_trip_logs
  set trip_status = 'FINISHED',
      finished_by_user_id = p_actor_user_id,
      actual_return_at = now(),
      end_odometer = p_end_odometer,
      end_photo_path = trim(p_end_photo_path),
      end_latitude = p_latitude,
      end_longitude = p_longitude,
      end_accuracy_m = p_accuracy_m,
      end_location_capture_failed = coalesce(p_location_capture_failed, false),
      end_location_failure_reason = nullif(trim(p_location_failure_reason), ''),
      distance_km = v_distance,
      vehicle_condition_end = p_vehicle_condition_end,
      issue_note = nullif(trim(p_issue_note), ''),
      updated_at = now()
  where id = v_trip.id;

  update public.fleet_vehicle_profiles
  set current_odometer = greatest(current_odometer, p_end_odometer),
      updated_at = now()
  where asset_id = v_assignment.vehicle_asset_id;

  update public.vehicle_bookings
  set status = 'COMPLETED', updated_at = now()
  where id = p_booking_id;

  if v_assignment.fulfillment_type = 'INTERNAL_WITH_DRIVER' then
    update public.fleet_vehicle_profiles
    set custody_status = 'AVAILABLE', current_custody_assignment_id = null, updated_at = now()
    where asset_id = v_assignment.vehicle_asset_id
      and current_custody_assignment_id = v_assignment.id;
    update public.vehicle_booking_assignments
    set released_at = coalesce(released_at, now()), updated_at = now()
    where id = v_assignment.id;
  end if;

  insert into public.vehicle_booking_feedback(booking_id, respondent_user_id, status)
  values (p_booking_id, v_booking.requester_user_id, 'PENDING')
  on conflict (booking_id) do nothing;

  perform app_private.vehicle_record_audit(
    p_actor_user_id,
    p_booking_id,
    'TRIP_FINISHED',
    jsonb_build_object('status', v_booking.status),
    jsonb_build_object('status', 'COMPLETED', 'distance_km', v_distance),
    'Kết thúc chuyến xe'
  );
  perform app_private.vehicle_enqueue_notification(
    p_booking_id,
    'TRIP_COMPLETED',
    v_booking.requester_user_id,
    jsonb_build_object('booking_code', v_booking.booking_code, 'distance_km', v_distance)
  );
  perform app_private.vehicle_enqueue_notification(
    p_booking_id,
    'VEHICLE_RETURN_REQUIRED',
    case when v_assignment.fulfillment_type = 'INTERNAL_SELF_DRIVE'
      then v_assignment.handover_officer_user_id else null end,
    jsonb_build_object('booking_code', v_booking.booking_code)
  );

  return jsonb_build_object('success', true, 'status', 'COMPLETED', 'distance_km', v_distance);
end;
$$;


--
-- Name: command_mark_vehicle_booking_no_show(uuid, uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_mark_vehicle_booking_no_show(p_actor_user_id uuid, p_booking_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_booking public.vehicle_bookings%rowtype;
  v_assignment public.vehicle_booking_assignments%rowtype;
begin
  if nullif(trim(p_reason), '') is null then
    raise exception using errcode = 'P0001', message = 'NO_SHOW_REASON_REQUIRED';
  end if;
  select * into v_booking from public.vehicle_bookings where id = p_booking_id for update;
  select * into v_assignment from public.vehicle_booking_assignments
  where booking_id = p_booking_id and is_active for update;

  if v_booking.id is null or v_assignment.id is null then
    raise exception using errcode = 'P0001', message = 'ASSIGNMENT_NOT_FOUND';
  end if;
  if v_booking.status <> 'ASSIGNED' then
    raise exception using errcode = 'P0001', message = 'INVALID_STATUS_TRANSITION';
  end if;
  if v_assignment.operator_user_id is distinct from p_actor_user_id
     and not app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.dispatch') then
    perform app_private.vehicle_raise_permission_denied('Assigned operator or dispatcher is required');
  end if;

  update public.vehicle_bookings
  set status = 'CANCELLED', close_reason = 'NO_SHOW', close_note = trim(p_reason),
      cancelled_by_user_id = p_actor_user_id, cancelled_at = now(), updated_at = now()
  where id = p_booking_id;
  update public.vehicle_booking_assignments
  set released_at = coalesce(released_at, now()), updated_at = now()
  where id = v_assignment.id;
  update public.fleet_vehicle_profiles
  set custody_status = 'AVAILABLE', current_custody_assignment_id = null, updated_at = now()
  where current_custody_assignment_id = v_assignment.id;

  perform app_private.vehicle_record_audit(
    p_actor_user_id, p_booking_id, 'NO_SHOW',
    jsonb_build_object('status', v_booking.status),
    jsonb_build_object('status', 'CANCELLED', 'close_reason', 'NO_SHOW'),
    'Ghi nhận no-show booking xe'
  );
  perform app_private.vehicle_enqueue_notification(
    p_booking_id, 'BOOKING_NO_SHOW', v_booking.requester_user_id,
    jsonb_build_object('booking_code', v_booking.booking_code)
  );
  return jsonb_build_object('success', true, 'status', 'CANCELLED', 'close_reason', 'NO_SHOW');
end;
$$;


--
-- Name: command_reassign_vehicle_booking(uuid, uuid, text, text, text, uuid, uuid, boolean, text, text, text, text, text, text, numeric, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_reassign_vehicle_booking(p_actor_user_id uuid, p_booking_id uuid, p_reassign_reason text, p_fulfillment_type text, p_vehicle_asset_id text DEFAULT NULL::text, p_operator_user_id uuid DEFAULT NULL::uuid, p_handover_officer_user_id uuid DEFAULT NULL::uuid, p_allow_non_home_base_return boolean DEFAULT false, p_non_home_base_return_reason text DEFAULT NULL::text, p_external_service_type text DEFAULT NULL::text, p_external_provider_name text DEFAULT NULL::text, p_external_driver_name text DEFAULT NULL::text, p_external_driver_phone text DEFAULT NULL::text, p_external_vehicle_plate text DEFAULT NULL::text, p_external_estimated_cost numeric DEFAULT NULL::numeric, p_dispatch_reason_code text DEFAULT NULL::text, p_assignment_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_booking public.vehicle_bookings%rowtype;
  v_old_assignment public.vehicle_booking_assignments%rowtype;
  v_new_assignment_id uuid := gen_random_uuid();
  v_new_version integer;
  v_buffer_minutes integer := 0;
  v_operator_type text;
  v_home_base_id uuid;
  v_keys text[] := array[]::text[];
  v_key text;
begin
  if not app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.dispatch') then
    perform app_private.vehicle_raise_permission_denied('Dispatcher permission is required');
  end if;
  if nullif(trim(p_reassign_reason), '') is null then
    raise exception using errcode = 'P0001', message = 'REASSIGN_REASON_REQUIRED';
  end if;

  select * into v_booking
  from public.vehicle_bookings b
  where b.id = p_booking_id
  for update;
  if not found then
    raise exception using errcode = 'P0001', message = 'BOOKING_NOT_FOUND';
  end if;
  if v_booking.status <> 'ASSIGNED' then
    raise exception using errcode = 'P0001', message = 'INVALID_STATUS_TRANSITION';
  end if;

  select * into v_old_assignment
  from public.vehicle_booking_assignments assignment
  where assignment.booking_id = p_booking_id and assignment.is_active
  for update;
  if not found then
    raise exception using errcode = 'P0001', message = 'ASSIGNMENT_NOT_FOUND';
  end if;

  v_keys := array_remove(array[
    case when v_old_assignment.vehicle_asset_id is not null then 'vehicle:' || v_old_assignment.vehicle_asset_id end,
    case when v_old_assignment.operator_user_id is not null then 'operator:' || v_old_assignment.operator_user_id::text end,
    case when p_vehicle_asset_id is not null then 'vehicle:' || p_vehicle_asset_id end,
    case when p_operator_user_id is not null then 'operator:' || p_operator_user_id::text end
  ], null);
  select coalesce(array_agg(distinct resource_key order by resource_key), array[]::text[])
  into v_keys
  from unnest(v_keys) resource_key;
  foreach v_key in array v_keys loop
    perform pg_advisory_xact_lock(hashtextextended(v_key, 0));
  end loop;

  perform app_private.vehicle_validate_assignment(
    p_booking_id,
    p_fulfillment_type,
    p_vehicle_asset_id,
    p_operator_user_id,
    p_handover_officer_user_id,
    p_allow_non_home_base_return,
    p_non_home_base_return_reason,
    p_external_service_type
  );

  select coalesce(max(assignment.version), 0) + 1
  into v_new_version
  from public.vehicle_booking_assignments assignment
  where assignment.booking_id = p_booking_id;

  update public.vehicle_booking_assignments
  set is_active = false,
      released_at = coalesce(released_at, now()),
      superseded_at = now(),
      superseded_by_user_id = p_actor_user_id,
      supersede_reason = trim(p_reassign_reason),
      updated_at = now()
  where id = v_old_assignment.id;

  delete from public.vehicle_trip_logs
  where booking_id = p_booking_id
    and trip_status = 'NOT_STARTED';

  select coalesce(settings.booking_buffer_minutes, 0)
  into v_buffer_minutes
  from public.fleet_system_settings settings
  where settings.id = 1;

  if p_vehicle_asset_id is not null then
    select profile.home_base_id into v_home_base_id
    from public.fleet_vehicle_profiles profile
    where profile.asset_id = p_vehicle_asset_id;
  end if;

  v_operator_type := case p_fulfillment_type
    when 'INTERNAL_WITH_DRIVER' then 'PROFESSIONAL_DRIVER'
    when 'INTERNAL_SELF_DRIVE' then 'SELF_DRIVER'
    else null
  end;

  insert into public.vehicle_booking_assignments (
    id, booking_id, version, is_active, fulfillment_type,
    vehicle_asset_id, operator_user_id, operator_type,
    reserved_start_at, reserved_end_at, home_base_id_snapshot,
    handover_officer_user_id, allow_non_home_base_return,
    non_home_base_return_reason, external_service_type,
    external_provider_name, external_driver_name, external_driver_phone,
    external_vehicle_plate, external_estimated_cost, dispatch_reason_code,
    assigned_by_user_id, assignment_note
  ) values (
    v_new_assignment_id, p_booking_id, v_new_version, true, p_fulfillment_type,
    p_vehicle_asset_id, p_operator_user_id, v_operator_type,
    v_booking.requested_pickup_at,
    v_booking.expected_return_at + make_interval(mins => coalesce(v_buffer_minutes, 0)),
    v_home_base_id, p_handover_officer_user_id,
    coalesce(p_allow_non_home_base_return, false), p_non_home_base_return_reason,
    p_external_service_type, p_external_provider_name, p_external_driver_name,
    p_external_driver_phone, p_external_vehicle_plate, p_external_estimated_cost,
    p_dispatch_reason_code, p_actor_user_id, p_assignment_note
  );

  if p_fulfillment_type <> 'EXTERNAL_TRANSPORT' then
    insert into public.vehicle_trip_logs (
      booking_id, assignment_id, assignment_version_snapshot,
      vehicle_asset_id_snapshot, operator_user_id_snapshot, trip_status
    ) values (
      p_booking_id, v_new_assignment_id, v_new_version,
      p_vehicle_asset_id, p_operator_user_id, 'NOT_STARTED'
    );
  end if;

  perform app_private.vehicle_record_audit(
    p_actor_user_id,
    p_booking_id,
    'REASSIGNED',
    jsonb_build_object(
      'assignment_id', v_old_assignment.id,
      'vehicle_asset_id', v_old_assignment.vehicle_asset_id,
      'operator_user_id', v_old_assignment.operator_user_id
    ),
    jsonb_build_object(
      'assignment_id', v_new_assignment_id,
      'vehicle_asset_id', p_vehicle_asset_id,
      'operator_user_id', p_operator_user_id,
      'reason', trim(p_reassign_reason)
    ),
    'Đổi phương án điều phối xe'
  );
  perform app_private.vehicle_enqueue_notification(
    p_booking_id,
    'BOOKING_REASSIGNED',
    v_booking.requester_user_id,
    jsonb_build_object('booking_code', v_booking.booking_code, 'assignment_id', v_new_assignment_id)
  );
  perform app_private.vehicle_enqueue_notification(
    p_booking_id,
    'BOOKING_REASSIGNED_OLD_OPERATOR',
    v_old_assignment.operator_user_id,
    jsonb_build_object('booking_code', v_booking.booking_code)
  );
  perform app_private.vehicle_enqueue_notification(
    p_booking_id,
    'BOOKING_REASSIGNED_NEW_OPERATOR',
    p_operator_user_id,
    jsonb_build_object('booking_code', v_booking.booking_code, 'assignment_id', v_new_assignment_id)
  );

  return jsonb_build_object(
    'success', true,
    'assignment_id', v_new_assignment_id,
    'version', v_new_version,
    'status', 'ASSIGNED'
  );
end;
$$;


--
-- Name: command_reassign_vehicle_booking_manager(uuid, uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_reassign_vehicle_booking_manager(p_actor_user_id uuid, p_booking_id uuid, p_manager_user_id uuid, p_reason text, p_expected_updated_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_booking public.vehicle_bookings%rowtype;
  v_updated_at timestamptz;
begin
  if not app_private.vehicle_user_has_permission(
    p_actor_user_id,
    'booking.vehicle.admin'
  ) then
    perform app_private.vehicle_raise_permission_denied(
      'Booking administrator permission required'
    );
  end if;
  if nullif(trim(coalesce(p_reason, '')), '') is null then
    raise exception using errcode = '22023', message = 'REASSIGN_REASON_REQUIRED';
  end if;

  select booking.* into v_booking
  from public.vehicle_bookings booking
  where booking.id = p_booking_id
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'BOOKING_NOT_FOUND';
  end if;
  if v_booking.status <> 'PENDING_APPROVAL' then
    raise exception using errcode = 'P0001', message = 'INVALID_STATUS_TRANSITION';
  end if;
  if p_expected_updated_at is null
     or v_booking.updated_at is distinct from p_expected_updated_at then
    raise exception using errcode = '40001', message = 'VEHICLE_BOOKING_STALE_STATE';
  end if;
  if p_manager_user_id is null
     or p_manager_user_id = v_booking.requester_user_id then
    raise exception using errcode = '22023', message = 'VEHICLE_MANAGER_INVALID';
  end if;
  if not exists (
    select 1
    from public.users app_user
    where app_user.id = p_manager_user_id
      and coalesce(app_user.is_active, true)
      and coalesce(app_user.account_status, 'ACTIVE') = 'ACTIVE'
  ) then
    raise exception using errcode = '22023', message = 'VEHICLE_MANAGER_INVALID';
  end if;

  update public.vehicle_bookings
  set manager_user_id_snapshot = p_manager_user_id,
      manager_resolution_status = 'NORMAL',
      manager_approval_route = 'MANAGER',
      updated_at = now()
  where id = p_booking_id
  returning updated_at into v_updated_at;

  perform app_private.vehicle_record_audit(
    p_actor_user_id,
    p_booking_id,
    'MANAGER_REASSIGNED',
    jsonb_build_object(
      'manager_user_id_snapshot', v_booking.manager_user_id_snapshot
    ),
    jsonb_build_object(
      'manager_user_id_snapshot', p_manager_user_id,
      'reason', trim(p_reason)
    ),
    'Chuyển người duyệt booking: ' || trim(p_reason)
  );

  if v_booking.manager_user_id_snapshot is not null
     and v_booking.manager_user_id_snapshot <> p_manager_user_id then
    perform app_private.vehicle_enqueue_notification(
      p_booking_id,
      'BOOKING_MANAGER_REASSIGNED_AWAY',
      v_booking.manager_user_id_snapshot,
      jsonb_build_object('reason', trim(p_reason))
    );
  end if;
  perform app_private.vehicle_enqueue_notification(
    p_booking_id,
    'BOOKING_MANAGER_REASSIGNED',
    p_manager_user_id,
    jsonb_build_object('reason', trim(p_reason))
  );

  return jsonb_build_object(
    'success', true,
    'status', 'PENDING_APPROVAL',
    'manager_user_id', p_manager_user_id,
    'updated_at', v_updated_at
  );
end;
$$;


--
-- Name: command_record_vehicle_trip_checkpoint(uuid, uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_record_vehicle_trip_checkpoint(p_actor_user_id uuid, p_booking_id uuid, p_checkpoint_type text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_booking public.vehicle_bookings%rowtype;
  v_assignment public.vehicle_booking_assignments%rowtype;
begin
  select * into v_booking from public.vehicle_bookings where id = p_booking_id for update;
  select * into v_assignment from public.vehicle_booking_assignments
  where booking_id = p_booking_id and is_active for share;
  if v_booking.id is null or v_assignment.id is null then
    raise exception using errcode = 'P0001', message = 'ASSIGNMENT_NOT_FOUND';
  end if;
  if v_booking.status <> 'IN_PROGRESS' then
    raise exception using errcode = 'P0001', message = 'INVALID_STATUS_TRANSITION';
  end if;
  if v_assignment.operator_user_id is distinct from p_actor_user_id
     and not app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.dispatch') then
    perform app_private.vehicle_raise_permission_denied('Only assigned operator or dispatcher can record checkpoints');
  end if;

  if p_checkpoint_type = 'DEPARTED_HOME_BASE' then
    update public.vehicle_trip_logs
    set departed_home_base_at = coalesce(departed_home_base_at, now()), updated_at = now()
    where booking_id = p_booking_id and trip_status = 'IN_PROGRESS';
  elsif p_checkpoint_type = 'PICKED_UP_PASSENGER' then
    update public.vehicle_trip_logs
    set actual_pickup_at = coalesce(actual_pickup_at, now()), updated_at = now()
    where booking_id = p_booking_id and trip_status = 'IN_PROGRESS';
  else
    raise exception using errcode = 'P0001', message = 'INVALID_CHECKPOINT_TYPE';
  end if;

  return jsonb_build_object('success', true, 'checkpoint_type', p_checkpoint_type);
end;
$$;


--
-- Name: command_reject_vehicle_booking(uuid, uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_reject_vehicle_booking(p_actor_user_id uuid, p_booking_id uuid, p_reject_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_booking public.vehicle_bookings%rowtype;
begin
  if nullif(trim(p_reject_reason), '') is null then
    raise exception using errcode = 'P0001', message = 'REJECT_REASON_REQUIRED';
  end if;

  select * into v_booking
  from public.vehicle_bookings b
  where b.id = p_booking_id
  for update;

  if not found then
    raise exception using errcode = 'P0001', message = 'BOOKING_NOT_FOUND';
  end if;
  if v_booking.status <> 'PENDING_APPROVAL' then
    raise exception using errcode = 'P0001', message = 'INVALID_STATUS_TRANSITION';
  end if;
  if v_booking.manager_user_id_snapshot is distinct from p_actor_user_id
     and not app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.dispatch') then
    perform app_private.vehicle_raise_permission_denied('Only the snapshot manager or dispatcher can reject');
  end if;

  update public.vehicle_bookings
  set status = 'CANCELLED',
      close_reason = 'REJECTED_BY_MANAGER',
      close_note = trim(p_reject_reason),
      cancelled_by_user_id = p_actor_user_id,
      cancelled_at = now(),
      updated_at = now()
  where id = p_booking_id;

  perform app_private.vehicle_record_audit(
    p_actor_user_id,
    p_booking_id,
    'REJECTED',
    jsonb_build_object('status', v_booking.status),
    jsonb_build_object('status', 'CANCELLED', 'close_reason', 'REJECTED_BY_MANAGER'),
    'Từ chối booking xe'
  );
  perform app_private.vehicle_enqueue_notification(
    p_booking_id,
    'BOOKING_REJECTED',
    v_booking.requester_user_id,
    jsonb_build_object('booking_code', v_booking.booking_code)
  );

  return jsonb_build_object('success', true, 'status', 'CANCELLED', 'close_reason', 'REJECTED_BY_MANAGER');
end;
$$;


--
-- Name: command_replace_vehicle_booking_participants(uuid, uuid, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_replace_vehicle_booking_participants(p_actor_user_id uuid, p_booking_id uuid, p_participants jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_booking public.vehicle_bookings%rowtype;
  v_participant jsonb;
  v_count integer := 0;
begin
  select * into v_booking from public.vehicle_bookings where id = p_booking_id for update;
  if not found then raise exception using errcode = 'P0001', message = 'BOOKING_NOT_FOUND'; end if;
  if v_booking.status <> 'DRAFT' then
    raise exception using errcode = 'P0001', message = 'INVALID_STATUS_TRANSITION';
  end if;
  if v_booking.requester_user_id is distinct from p_actor_user_id
     and not app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.dispatch') then
    perform app_private.vehicle_raise_permission_denied('Requester or dispatcher is required');
  end if;
  if jsonb_typeof(coalesce(p_participants, '[]'::jsonb)) <> 'array' then
    raise exception using errcode = 'P0001', message = 'INVALID_PARTICIPANTS';
  end if;

  delete from public.vehicle_booking_participants where booking_id = p_booking_id;
  for v_participant in select value from jsonb_array_elements(coalesce(p_participants, '[]'::jsonb))
  loop
    if nullif(trim(v_participant ->> 'participantName'), '') is null then
      raise exception using errcode = 'P0001', message = 'PARTICIPANT_NAME_REQUIRED';
    end if;
    insert into public.vehicle_booking_participants(
      booking_id, user_id, employee_id, participant_name, is_external
    ) values (
      p_booking_id,
      nullif(v_participant ->> 'userId', '')::uuid,
      nullif(v_participant ->> 'employeeId', '')::uuid,
      trim(v_participant ->> 'participantName'),
      coalesce((v_participant ->> 'isExternal')::boolean, false)
    );
    v_count := v_count + 1;
  end loop;
  return jsonb_build_object('success', true, 'participant_count', v_count);
end;
$$;


--
-- Name: command_respond_to_vehicle_assignment(uuid, uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_respond_to_vehicle_assignment(p_actor_user_id uuid, p_booking_id uuid, p_response text, p_decline_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_assignment public.vehicle_booking_assignments%rowtype;
begin
  if p_response not in ('CONFIRMED', 'DECLINED') then
    raise exception using errcode = 'P0001', message = 'INVALID_ASSIGNMENT_RESPONSE';
  end if;
  if p_response = 'DECLINED' and nullif(trim(p_decline_reason), '') is null then
    raise exception using errcode = 'P0001', message = 'DECLINE_REASON_REQUIRED';
  end if;

  select * into v_assignment
  from public.vehicle_booking_assignments assignment
  where assignment.booking_id = p_booking_id and assignment.is_active
  for update;

  if not found then
    raise exception using errcode = 'P0001', message = 'ASSIGNMENT_NOT_FOUND';
  end if;
  if v_assignment.operator_user_id is distinct from p_actor_user_id then
    perform app_private.vehicle_raise_permission_denied('Only the assigned operator can respond');
  end if;
  if not exists (
    select 1 from public.vehicle_bookings booking
    where booking.id = p_booking_id and booking.status = 'ASSIGNED'
  ) then
    raise exception using errcode = 'P0001', message = 'INVALID_STATUS_TRANSITION';
  end if;

  update public.vehicle_booking_assignments
  set operator_confirmation_status = p_response,
      operator_confirmed_at = case when p_response = 'CONFIRMED' then now() else null end,
      operator_decline_reason = case when p_response = 'DECLINED' then trim(p_decline_reason) else null end,
      updated_at = now()
  where id = v_assignment.id;

  perform app_private.vehicle_record_audit(
    p_actor_user_id,
    p_booking_id,
    'ASSIGNMENT_' || p_response,
    jsonb_build_object('operator_confirmation_status', v_assignment.operator_confirmation_status),
    jsonb_build_object('operator_confirmation_status', p_response),
    'Phản hồi phân công chuyến xe'
  );

  if p_response = 'DECLINED' then
    insert into app_private.vehicle_booking_notification_outbox(event_key, recipient_user_id, payload)
    select
      'vehicle:' || p_booking_id::text || ':ASSIGNMENT_DECLINED:' || grant_row.user_id::text,
      grant_row.user_id,
      jsonb_build_object('booking_id', p_booking_id, 'event_type', 'ASSIGNMENT_DECLINED')
    from public.user_permission_grants grant_row
    where grant_row.permission_code in ('booking.vehicle.dispatch', 'booking.vehicle.admin')
      and grant_row.is_active
      and grant_row.revoked_at is null
      and (grant_row.expires_at is null or grant_row.expires_at > now())
    on conflict (event_key, recipient_user_id) do nothing;
  end if;

  return jsonb_build_object('success', true, 'response', p_response, 'requires_reassignment', p_response = 'DECLINED');
end;
$$;


--
-- Name: command_set_fleet_vehicle_asset_image(uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_set_fleet_vehicle_asset_image(p_actor_user_id uuid, p_asset_id text, p_image_url text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_actor_user_id is distinct from public.current_app_user_id() then
    perform app_private.vehicle_raise_permission_denied('Actor mismatch');
  end if;

  if not app_private.vehicle_user_has_permission(
    p_actor_user_id,
    'booking.vehicle.manage_fleet'
  ) then
    perform app_private.vehicle_raise_permission_denied(
      'Fleet management permission required'
    );
  end if;

  if not exists (
    select 1
    from public.assets asset
    where asset.id = p_asset_id
  ) then
    raise exception using errcode = 'P0002', message = 'ASSET_NOT_FOUND';
  end if;

  update public.assets asset
  set image_url = nullif(trim(p_image_url), ''),
      updated_at = now()
  where asset.id = p_asset_id;

  return jsonb_build_object(
    'success', true,
    'asset_id', p_asset_id,
    'image_url', nullif(trim(p_image_url), '')
  );
end;
$$;


--
-- Name: command_set_vehicle_booking_dispatchers(uuid, uuid[]); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_set_vehicle_booking_dispatchers(p_actor_user_id uuid, p_user_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_ids uuid[] := array(
    select distinct selected_user_id
    from unnest(coalesce(p_user_ids, '{}'::uuid[])) selected_user_id
    where selected_user_id is not null
    order by selected_user_id
  );
  v_before_user_ids uuid[];
  v_invalid_count integer;
begin
  if p_actor_user_id is distinct from public.current_app_user_id() then
    perform app_private.vehicle_raise_permission_denied('Actor mismatch');
  end if;

  if not app_private.vehicle_user_has_permission(
    p_actor_user_id,
    'booking.vehicle.admin'
  ) then
    perform app_private.vehicle_raise_permission_denied(
      'Booking administrator permission required'
    );
  end if;

  select coalesce(array_agg(grant_row.user_id order by grant_row.user_id), '{}'::uuid[])
  into v_before_user_ids
  from public.user_permission_grants grant_row
  where grant_row.permission_code = 'booking.vehicle.dispatch'
    and grant_row.scope_type = 'global'
    and grant_row.scope_id = '*'
    and grant_row.is_active
    and grant_row.revoked_at is null
    and (grant_row.expires_at is null or grant_row.expires_at > now());

  select count(*)::integer
  into v_invalid_count
  from unnest(v_user_ids) selected_user_id
  where not exists (
    select 1
    from public.users app_user
    join public.employees employee on employee.user_id = app_user.id
    where app_user.id = selected_user_id
      and app_user.is_active
      and app_user.account_status = 'ACTIVE'
      and app_user.role::text <> 'ADMIN'
      and employee.status = 'Đang làm việc'
  );

  if v_invalid_count > 0 then
    raise exception 'DISPATCHER_CANDIDATE_INVALID'
      using errcode = '22023';
  end if;

  update public.user_permission_grants grant_row
  set is_active = false,
      revoked_at = now(),
      revoked_by = p_actor_user_id,
      revoked_reason = 'Cập nhật danh sách nhân sự điều phối Booking',
      updated_at = now()
  where grant_row.permission_code = 'booking.vehicle.dispatch'
    and grant_row.scope_type = 'global'
    and grant_row.scope_id = '*'
    and grant_row.is_active
    and not (grant_row.user_id = any(v_user_ids));

  insert into public.user_permission_grants (
    user_id,
    permission_code,
    scope_type,
    scope_id,
    is_active,
    granted_by,
    granted_at,
    expires_at,
    revoked_at,
    revoked_by,
    revoked_reason,
    grant_reason,
    updated_at
  )
  select
    selected_user_id,
    'booking.vehicle.dispatch',
    'global',
    '*',
    true,
    p_actor_user_id,
    now(),
    null,
    null,
    null,
    null,
    'Được phân công điều phối Booking',
    now()
  from unnest(v_user_ids) selected_user_id
  on conflict (user_id, permission_code, scope_type, scope_id) do update
  set is_active = true,
      granted_by = excluded.granted_by,
      granted_at = excluded.granted_at,
      expires_at = null,
      revoked_at = null,
      revoked_by = null,
      revoked_reason = null,
      grant_reason = excluded.grant_reason,
      updated_at = now();

  insert into public.permission_audit_events (
    actor_user_id,
    target_user_id,
    event_type,
    before_grants,
    after_grants,
    metadata
  ) values (
    p_actor_user_id,
    null,
    'booking_dispatchers_replaced',
    to_jsonb(v_before_user_ids),
    to_jsonb(v_user_ids),
    jsonb_build_object(
      'permissionCode', 'booking.vehicle.dispatch',
      'scopeType', 'global',
      'scopeId', '*'
    )
  );

  return jsonb_build_object(
    'success', true,
    'dispatcherCount', cardinality(v_user_ids)
  );
end;
$$;


--
-- Name: command_start_vehicle_trip(uuid, uuid, numeric, text, numeric, numeric, numeric, boolean, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_start_vehicle_trip(p_actor_user_id uuid, p_booking_id uuid, p_start_odometer numeric, p_start_photo_path text, p_latitude numeric DEFAULT NULL::numeric, p_longitude numeric DEFAULT NULL::numeric, p_accuracy_m numeric DEFAULT NULL::numeric, p_location_capture_failed boolean DEFAULT false, p_location_failure_reason text DEFAULT NULL::text, p_override_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_booking public.vehicle_bookings%rowtype;
  v_assignment public.vehicle_booking_assignments%rowtype;
  v_vehicle public.fleet_vehicle_profiles%rowtype;
  v_is_dispatcher boolean := false;
  v_requires_handover boolean := true;
  v_used_override boolean := false;
begin
  select * into v_booking from public.vehicle_bookings where id = p_booking_id for update;
  select * into v_assignment from public.vehicle_booking_assignments
  where booking_id = p_booking_id and is_active for update;

  if v_booking.id is null or v_assignment.id is null then
    raise exception using errcode = 'P0001', message = 'ASSIGNMENT_NOT_FOUND';
  end if;
  if v_booking.status <> 'ASSIGNED' or v_assignment.fulfillment_type = 'EXTERNAL_TRANSPORT' then
    raise exception using errcode = 'P0001', message = 'INVALID_STATUS_TRANSITION';
  end if;

  v_is_dispatcher := app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.dispatch');
  if v_assignment.operator_user_id is distinct from p_actor_user_id then
    if not v_is_dispatcher then
      perform app_private.vehicle_raise_permission_denied('Only assigned operator or dispatcher can start');
    end if;
    if nullif(trim(p_override_reason), '') is null then
      raise exception using errcode = 'P0001', message = 'OVERRIDE_REASON_REQUIRED';
    end if;
    v_used_override := true;
  end if;

  if v_assignment.operator_confirmation_status = 'DECLINED' then
    if not v_is_dispatcher or nullif(trim(p_override_reason), '') is null then
      raise exception using errcode = 'P0001', message = 'ASSIGNMENT_DECLINED';
    end if;
    v_used_override := true;
  elsif v_assignment.operator_confirmation_status = 'PENDING'
        and v_assignment.operator_user_id = p_actor_user_id then
    update public.vehicle_booking_assignments
    set operator_confirmation_status = 'CONFIRMED',
        operator_confirmed_at = now(),
        updated_at = now()
    where id = v_assignment.id;
  end if;

  if p_start_odometer is null then
    raise exception using errcode = 'P0001', message = 'ODOMETER_REQUIRED';
  end if;
  perform app_private.vehicle_assert_evidence_path(p_booking_id, p_start_photo_path, 'trips');

  if coalesce(p_location_capture_failed, false) then
    if nullif(trim(p_location_failure_reason), '') is null then
      raise exception using errcode = 'P0001', message = 'LOCATION_FAILURE_REASON_REQUIRED';
    end if;
  elsif p_latitude is null or p_longitude is null then
    raise exception using errcode = 'P0001', message = 'LOCATION_REQUIRED';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('vehicle:' || v_assignment.vehicle_asset_id, 0));
  select * into v_vehicle
  from public.fleet_vehicle_profiles
  where asset_id = v_assignment.vehicle_asset_id
  for update;

  if not found or not v_vehicle.active or v_vehicle.availability_status <> 'AVAILABLE' then
    raise exception using errcode = 'P0001', message = 'VEHICLE_UNAVAILABLE';
  end if;
  if v_vehicle.current_custody_assignment_id is not null
     and v_vehicle.current_custody_assignment_id <> v_assignment.id then
    raise exception using errcode = 'P0001', message = 'VEHICLE_IN_CUSTODY';
  end if;

  if p_start_odometer < v_vehicle.current_odometer then
    if not v_is_dispatcher or nullif(trim(p_override_reason), '') is null then
      raise exception using errcode = 'P0001', message = 'INVALID_ODOMETER_RANGE';
    end if;
    v_used_override := true;
  end if;

  select coalesce(settings.require_handover_for_self_drive, true)
  into v_requires_handover
  from public.fleet_system_settings settings
  where settings.id = 1;

  if v_assignment.fulfillment_type = 'INTERNAL_SELF_DRIVE'
     and v_requires_handover
     and not exists (
       select 1 from public.vehicle_handover_logs log
       where log.assignment_id = v_assignment.id
         and log.event_type = 'OUTBOUND_HANDOVER'
     ) then
    if not v_is_dispatcher or nullif(trim(p_override_reason), '') is null then
      raise exception using errcode = 'P0001', message = 'HANDOVER_REQUIRED';
    end if;
    v_used_override := true;
  end if;

  update public.fleet_vehicle_profiles
  set custody_status = 'IN_CUSTODY',
      current_custody_assignment_id = v_assignment.id,
      updated_at = now()
  where asset_id = v_assignment.vehicle_asset_id;

  update public.vehicle_trip_logs
  set trip_status = 'IN_PROGRESS',
      started_by_user_id = p_actor_user_id,
      departed_home_base_at = now(),
      start_odometer = p_start_odometer,
      start_photo_path = trim(p_start_photo_path),
      start_latitude = p_latitude,
      start_longitude = p_longitude,
      start_accuracy_m = p_accuracy_m,
      start_location_capture_failed = coalesce(p_location_capture_failed, false),
      start_location_failure_reason = nullif(trim(p_location_failure_reason), ''),
      updated_at = now()
  where booking_id = p_booking_id and trip_status = 'NOT_STARTED';
  if not found then
    raise exception using errcode = 'P0001', message = 'TRIP_LOG_NOT_FOUND';
  end if;

  update public.vehicle_bookings
  set status = 'IN_PROGRESS', updated_at = now()
  where id = p_booking_id;

  perform app_private.vehicle_record_audit(
    p_actor_user_id,
    p_booking_id,
    case when v_used_override then 'TRIP_STARTED_OVERRIDE' else 'TRIP_STARTED' end,
    jsonb_build_object('status', v_booking.status),
    jsonb_build_object('status', 'IN_PROGRESS', 'start_odometer', p_start_odometer),
    'Bắt đầu chuyến xe'
  );
  return jsonb_build_object('success', true, 'status', 'IN_PROGRESS');
end;
$$;


--
-- Name: command_submit_vehicle_booking(uuid, uuid, boolean); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_submit_vehicle_booking(p_actor_user_id uuid, p_booking_id uuid, p_confirm_missing_manager_bypass boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_booking public.vehicle_bookings%rowtype;
  v_requires_manager boolean := true;
  v_manager_user_id uuid;
  v_dispatcher_count integer := 0;
  v_route text;
  v_status text;
begin
  select booking.* into v_booking
  from public.vehicle_bookings booking
  where booking.id = p_booking_id
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'BOOKING_NOT_FOUND';
  end if;
  if v_booking.requester_user_id is distinct from p_actor_user_id
     and not app_private.vehicle_user_has_permission(
       p_actor_user_id,
       'booking.vehicle.admin'
     ) then
    perform app_private.vehicle_raise_permission_denied('Only requester can submit booking');
  end if;
  if v_booking.status <> 'DRAFT' then
    raise exception using errcode = 'P0001', message = 'INVALID_STATUS_TRANSITION';
  end if;

  select coalesce(settings.require_direct_manager_approval, true)
  into v_requires_manager
  from public.fleet_system_settings settings
  where settings.id = 1;

  if coalesce(v_requires_manager, true) then
    v_manager_user_id := app_private.resolve_active_direct_manager(
      v_booking.requester_user_id
    );
  end if;

  if not coalesce(v_requires_manager, true) then
    v_route := 'CONFIG_DISABLED';
    v_status := 'WAITING_DISPATCH';
  elsif v_manager_user_id is not null then
    v_route := 'MANAGER';
    v_status := 'PENDING_APPROVAL';
  elsif not coalesce(p_confirm_missing_manager_bypass, false) then
    raise exception using
      errcode = '22023',
      message = 'VEHICLE_DIRECT_MANAGER_CONFIRMATION_REQUIRED';
  else
    v_route := 'MISSING_MANAGER_BYPASS';
    v_status := 'WAITING_DISPATCH';
  end if;

  if v_status = 'WAITING_DISPATCH' then
    v_dispatcher_count := app_private.vehicle_active_dispatcher_count();
    if v_dispatcher_count = 0 then
      raise exception using errcode = '22023', message = 'VEHICLE_DISPATCHER_MISSING';
    end if;
  end if;

  update public.vehicle_bookings
  set status = v_status,
      submitted_at = now(),
      manager_user_id_snapshot = case when v_route = 'MANAGER' then v_manager_user_id else null end,
      manager_resolution_status = case
        when v_route = 'MISSING_MANAGER_BYPASS' then 'MISSING'
        else 'NORMAL'
      end,
      manager_approval_route = v_route,
      manager_bypass_confirmed_by_user_id = case
        when v_route = 'MISSING_MANAGER_BYPASS' then p_actor_user_id
        else null
      end,
      manager_bypass_confirmed_at = case
        when v_route = 'MISSING_MANAGER_BYPASS' then now()
        else null
      end,
      updated_at = now()
  where id = p_booking_id;

  perform app_private.vehicle_record_audit(
    p_actor_user_id,
    p_booking_id,
    case
      when v_route = 'MANAGER' then 'BOOKING_SUBMITTED_MANAGER'
      when v_route = 'CONFIG_DISABLED' then 'BOOKING_SUBMITTED_CONFIG_DISABLED'
      else 'BOOKING_SUBMITTED_MANAGER_BYPASS'
    end,
    jsonb_build_object('status', 'DRAFT'),
    jsonb_build_object(
      'status', v_status,
      'manager_approval_route', v_route,
      'manager_user_id_snapshot', v_manager_user_id
    ),
    'Gửi yêu cầu đặt xe'
  );

  if v_route = 'MANAGER' then
    perform app_private.vehicle_enqueue_notification(
      p_booking_id,
      'BOOKING_SUBMITTED',
      v_manager_user_id,
      jsonb_build_object('booking_code', v_booking.booking_code)
    );
  else
    perform app_private.vehicle_enqueue_dispatcher_notifications(
      p_booking_id,
      'BOOKING_WAITING_DISPATCH',
      jsonb_build_object(
        'booking_code', v_booking.booking_code,
        'manager_approval_route', v_route
      )
    );
  end if;

  return jsonb_build_object(
    'success', true,
    'status', v_status,
    'manager_approval_route', v_route,
    'manager_user_id', v_manager_user_id,
    'dispatcher_count', v_dispatcher_count
  );
end;
$$;


--
-- Name: command_submit_vehicle_feedback(uuid, uuid, boolean, integer, text[], text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_submit_vehicle_feedback(p_actor_user_id uuid, p_booking_id uuid, p_is_issue boolean, p_rating integer DEFAULT NULL::integer, p_positive_tags text[] DEFAULT NULL::text[], p_issue_category text DEFAULT NULL::text, p_comment text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform app_private.vehicle_require_current_actor(p_actor_user_id);
  return app_private.command_submit_vehicle_feedback_phase3_impl(
    p_actor_user_id,
    p_booking_id,
    p_is_issue,
    p_rating,
    p_positive_tags,
    p_issue_category,
    p_comment
  );
end;
$$;


--
-- Name: command_submit_vehicle_feedback_phase3_impl(uuid, uuid, boolean, integer, text[], text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_submit_vehicle_feedback_phase3_impl(p_actor_user_id uuid, p_booking_id uuid, p_is_issue boolean, p_rating integer DEFAULT NULL::integer, p_positive_tags text[] DEFAULT NULL::text[], p_issue_category text DEFAULT NULL::text, p_comment text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_booking public.vehicle_bookings%rowtype;
  v_feedback public.vehicle_booking_feedback%rowtype;
  v_issue_id uuid;
begin
  if p_rating is null or p_rating not between 1 and 5 then
    raise exception using errcode = '22023', message = 'RATING_REQUIRED';
  end if;

  if exists (
    select 1
    from unnest(coalesce(p_positive_tags, array[]::text[])) tag
    where tag not in (
      'CLEAN_VEHICLE', 'COURTEOUS_DRIVER', 'ON_TIME', 'SAFE_DRIVING'
    )
  ) then
    raise exception using errcode = '22023', message = 'INVALID_POSITIVE_TAG';
  end if;

  if p_rating <= 3 and not p_is_issue then
    raise exception using errcode = '22023', message = 'LOW_RATING_REQUIRES_ISSUE';
  end if;

  if p_is_issue then
    if coalesce(p_issue_category, '') not in (
      'SAFETY', 'DRIVER_CONDUCT', 'VEHICLE_CONDITION',
      'SERVICE_DELAY', 'COST', 'OTHER'
    ) then
      raise exception using errcode = '22023', message = 'INVALID_ISSUE_CATEGORY';
    end if;
    if length(trim(coalesce(p_comment, ''))) not between 1 and 4000 then
      raise exception using errcode = '22023', message = 'ISSUE_COMMENT_INVALID';
    end if;
  end if;

  select * into v_booking
  from public.vehicle_bookings
  where id = p_booking_id
  for share;

  select * into v_feedback
  from public.vehicle_booking_feedback
  where booking_id = p_booking_id
  for update;

  if v_booking.id is null or v_feedback.id is null then
    raise exception using errcode = 'P0001', message = 'FEEDBACK_NOT_FOUND';
  end if;
  if v_booking.status <> 'COMPLETED' or v_feedback.status <> 'PENDING' then
    raise exception using errcode = 'P0001', message = 'INVALID_STATUS_TRANSITION';
  end if;
  if p_actor_user_id not in (
    v_booking.requester_user_id,
    coalesce(v_booking.trip_owner_user_id, v_booking.requester_user_id)
  ) then
    perform app_private.vehicle_raise_permission_denied(
      'Only requester or trip owner can submit feedback'
    );
  end if;

  if p_is_issue then
    insert into public.vehicle_booking_issues(
      booking_id, reporter_user_id, issue_category, comment
    ) values (
      p_booking_id, p_actor_user_id, p_issue_category, trim(p_comment)
    ) returning id into v_issue_id;

    update public.vehicle_booking_feedback
    set respondent_user_id = p_actor_user_id,
        status = 'ISSUE_REPORTED',
        rating = p_rating,
        positive_tags = coalesce(p_positive_tags, array[]::text[]),
        submitted_at = now(),
        updated_at = now()
    where id = v_feedback.id;

    perform app_private.vehicle_record_audit(
      p_actor_user_id,
      p_booking_id,
      'FEEDBACK_ISSUE_REPORTED',
      jsonb_build_object('status', v_feedback.status),
      jsonb_build_object(
        'status', 'ISSUE_REPORTED',
        'rating', p_rating,
        'issue_id', v_issue_id,
        'issue_category', p_issue_category
      ),
      'Ghi nhận phản ánh booking xe (nội dung đã ẩn)'
    );
  else
    update public.vehicle_booking_feedback
    set respondent_user_id = p_actor_user_id,
        status = 'CONFIRMED',
        rating = p_rating,
        positive_tags = coalesce(p_positive_tags, array[]::text[]),
        submitted_at = now(),
        updated_at = now()
    where id = v_feedback.id;

    perform app_private.vehicle_record_audit(
      p_actor_user_id,
      p_booking_id,
      'FEEDBACK_CONFIRMED',
      jsonb_build_object('status', v_feedback.status),
      jsonb_build_object('status', 'CONFIRMED', 'rating', p_rating),
      'Xác nhận dịch vụ chuyến xe'
    );
  end if;

  return jsonb_build_object(
    'success', true,
    'is_issue', p_is_issue,
    'issue_id', v_issue_id
  );
end;
$$;


--
-- Name: command_transition_vehicle_booking_issue(uuid, uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_transition_vehicle_booking_issue(p_actor_user_id uuid, p_issue_id uuid, p_target_status text, p_resolution_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform app_private.vehicle_require_current_actor(p_actor_user_id);
  return app_private.command_transition_vehicle_booking_issue_phase3_impl(
    p_actor_user_id,
    p_issue_id,
    p_target_status,
    p_resolution_note
  );
end;
$$;


--
-- Name: command_transition_vehicle_booking_issue_phase3_impl(uuid, uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_transition_vehicle_booking_issue_phase3_impl(p_actor_user_id uuid, p_issue_id uuid, p_target_status text, p_resolution_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_issue public.vehicle_booking_issues%rowtype;
  v_booking public.vehicle_bookings%rowtype;
begin
  if not app_private.vehicle_user_has_permission(
    p_actor_user_id,
    'booking.vehicle.resolve_sensitive_feedback'
  ) then
    perform app_private.vehicle_raise_permission_denied(
      'Sensitive feedback resolution permission required'
    );
  end if;

  select * into v_issue
  from public.vehicle_booking_issues
  where id = p_issue_id
  for update;

  if v_issue.id is null then
    raise exception using errcode = 'P0001', message = 'ISSUE_NOT_FOUND';
  end if;

  if v_issue.resolution_status in ('RESOLVED', 'DISMISSED')
     and v_issue.resolution_status = p_target_status then
    return jsonb_build_object(
      'success', true,
      'status', v_issue.resolution_status,
      'idempotent', true
    );
  end if;

  if not (
    (v_issue.resolution_status = 'PENDING' and p_target_status = 'IN_REVIEW')
    or (
      v_issue.resolution_status = 'IN_REVIEW'
      and p_target_status in ('RESOLVED', 'DISMISSED')
    )
  ) then
    raise exception using errcode = 'P0001', message = 'INVALID_ISSUE_TRANSITION';
  end if;

  if p_target_status in ('RESOLVED', 'DISMISSED')
     and length(trim(coalesce(p_resolution_note, ''))) not between 1 and 4000 then
    raise exception using errcode = '22023', message = 'RESOLUTION_NOTE_INVALID';
  end if;

  update public.vehicle_booking_issues
  set resolution_status = p_target_status,
      resolution_note = case
        when p_target_status in ('RESOLVED', 'DISMISSED')
        then trim(p_resolution_note)
        else resolution_note
      end,
      resolved_by_user_id = case
        when p_target_status in ('RESOLVED', 'DISMISSED')
        then p_actor_user_id
        else null
      end,
      resolved_at = case
        when p_target_status in ('RESOLVED', 'DISMISSED')
        then now()
        else null
      end,
      updated_at = now()
  where id = p_issue_id;

  if p_target_status in ('RESOLVED', 'DISMISSED') then
    update public.vehicle_booking_feedback
    set status = 'RESOLVED', updated_at = now()
    where booking_id = v_issue.booking_id;
  end if;

  select * into v_booking
  from public.vehicle_bookings
  where id = v_issue.booking_id;

  perform app_private.vehicle_record_audit(
    p_actor_user_id,
    v_issue.booking_id,
    'FEEDBACK_ISSUE_STATUS_CHANGED',
    jsonb_build_object('status', v_issue.resolution_status),
    jsonb_build_object(
      'status', p_target_status,
      'issue_id', v_issue.id,
      'issue_category', v_issue.issue_category
    ),
    'Cập nhật trạng thái phản ánh booking xe (nội dung đã ẩn)'
  );

  if p_target_status in ('RESOLVED', 'DISMISSED') then
    perform app_private.vehicle_enqueue_notification(
      v_issue.booking_id,
      'ISSUE_RESOLVED',
      v_issue.reporter_user_id,
      jsonb_build_object(
        'booking_code', v_booking.booking_code,
        'resolution_status', p_target_status
      )
    );
  end if;

  return jsonb_build_object(
    'success', true,
    'status', p_target_status,
    'idempotent', false
  );
end;
$$;


--
-- Name: command_update_fleet_system_settings(uuid, integer, integer, integer, integer, integer, numeric, integer, boolean, boolean, boolean); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_update_fleet_system_settings(p_actor_user_id uuid, p_booking_buffer_minutes integer, p_late_cancellation_cutoff_minutes integer, p_feedback_auto_close_hours integer, p_home_base_warning_radius_meters integer, p_on_time_tolerance_minutes integer, p_max_evidence_image_mb numeric, p_trip_reminder_minutes integer DEFAULT 60, p_require_handover_for_self_drive boolean DEFAULT true, p_allow_dispatch_approval_override boolean DEFAULT true, p_require_direct_manager_approval boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not app_private.vehicle_user_has_permission(
    p_actor_user_id,
    'booking.vehicle.admin'
  ) then
    perform app_private.vehicle_raise_permission_denied(
      'Booking administrator permission required'
    );
  end if;

  update public.fleet_system_settings
  set booking_buffer_minutes = p_booking_buffer_minutes,
      late_cancellation_cutoff_minutes = p_late_cancellation_cutoff_minutes,
      feedback_auto_close_hours = p_feedback_auto_close_hours,
      home_base_warning_radius_meters = p_home_base_warning_radius_meters,
      on_time_tolerance_minutes = p_on_time_tolerance_minutes,
      max_evidence_image_mb = p_max_evidence_image_mb,
      trip_reminder_minutes = p_trip_reminder_minutes,
      require_handover_for_self_drive = p_require_handover_for_self_drive,
      allow_dispatch_approval_override = p_allow_dispatch_approval_override,
      require_direct_manager_approval = p_require_direct_manager_approval,
      updated_at = now()
  where id = 1;

  return jsonb_build_object('success', true);
end;
$$;


--
-- Name: command_upsert_driver_authorization(uuid, uuid, uuid, text, text, text, date, text, text, date, text[], text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_upsert_driver_authorization(p_actor_user_id uuid, p_target_user_id uuid, p_employee_id uuid, p_authorization_type text, p_license_number text, p_license_class text, p_license_expiry date, p_license_front_photo_path text DEFAULT NULL::text, p_license_back_photo_path text DEFAULT NULL::text, p_health_check_expiry_date date DEFAULT NULL::date, p_allowed_vehicle_types text[] DEFAULT NULL::text[], p_status text DEFAULT 'ACTIVE'::text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.manage_authorizations') THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: User does not have permission to manage driver authorizations';
  END IF;

  INSERT INTO public.vehicle_driver_authorizations (
    user_id, employee_id, authorization_type, license_number, license_class,
    license_expiry, license_front_photo_path, license_back_photo_path,
    health_check_expiry_date, allowed_vehicle_types, status, approved_by_user_id, approved_at, note, updated_at
  ) VALUES (
    p_target_user_id, p_employee_id, p_authorization_type, p_license_number, p_license_class,
    p_license_expiry, p_license_front_photo_path, p_license_back_photo_path,
    p_health_check_expiry_date, p_allowed_vehicle_types, p_status, p_actor_user_id, now(), p_note, now()
  )
  ON CONFLICT (user_id, authorization_type) DO UPDATE SET
    employee_id = EXCLUDED.employee_id,
    license_number = EXCLUDED.license_number,
    license_class = EXCLUDED.license_class,
    license_expiry = EXCLUDED.license_expiry,
    license_front_photo_path = EXCLUDED.license_front_photo_path,
    license_back_photo_path = EXCLUDED.license_back_photo_path,
    health_check_expiry_date = EXCLUDED.health_check_expiry_date,
    allowed_vehicle_types = EXCLUDED.allowed_vehicle_types,
    status = EXCLUDED.status,
    approved_by_user_id = p_actor_user_id,
    approved_at = now(),
    note = EXCLUDED.note,
    updated_at = now();

  RETURN jsonb_build_object('success', true, 'target_user_id', p_target_user_id);
END;
$$;


--
-- Name: command_upsert_fleet_location(uuid, uuid, text, text, numeric, numeric, text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_upsert_fleet_location(p_actor_user_id uuid, p_location_id uuid, p_name text, p_address text DEFAULT NULL::text, p_latitude numeric DEFAULT NULL::numeric, p_longitude numeric DEFAULT NULL::numeric, p_source_type text DEFAULT 'CUSTOM'::text, p_source_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_id uuid := COALESCE(p_location_id, gen_random_uuid());
BEGIN
  IF NOT app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.manage_fleet') THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: User does not have permission to manage fleet locations';
  END IF;

  INSERT INTO public.fleet_locations (id, name, address, latitude, longitude, source_type, source_id, updated_at)
  VALUES (v_id, p_name, p_address, p_latitude, p_longitude, p_source_type, p_source_id, now())
  ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    address = EXCLUDED.address,
    latitude = EXCLUDED.latitude,
    longitude = EXCLUDED.longitude,
    source_type = EXCLUDED.source_type,
    source_id = EXCLUDED.source_id,
    updated_at = now();

  RETURN jsonb_build_object('success', true, 'id', v_id);
END;
$$;


--
-- Name: command_upsert_fleet_vehicle_profile(uuid, text, uuid, text, integer, text, boolean, text, date, text, date, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.command_upsert_fleet_vehicle_profile(p_actor_user_id uuid, p_asset_id text, p_home_base_id uuid, p_vehicle_type text, p_seat_count integer, p_availability_status text DEFAULT 'AVAILABLE'::text, p_allow_self_drive boolean DEFAULT false, p_inspection_certificate_number text DEFAULT NULL::text, p_inspection_expiry_date date DEFAULT NULL::date, p_inspection_photo_path text DEFAULT NULL::text, p_insurance_expiry_date date DEFAULT NULL::date, p_parking_spot_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.manage_fleet') THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: User does not have permission to manage fleet vehicles';
  END IF;

  INSERT INTO public.fleet_vehicle_profiles (
    asset_id, home_base_id, vehicle_type, seat_count, availability_status,
    allow_self_drive, inspection_certificate_number, inspection_expiry_date,
    inspection_photo_path, insurance_expiry_date, parking_spot_code, updated_at
  ) VALUES (
    p_asset_id, p_home_base_id, p_vehicle_type, p_seat_count, p_availability_status,
    p_allow_self_drive, p_inspection_certificate_number, p_inspection_expiry_date,
    p_inspection_photo_path, p_insurance_expiry_date, p_parking_spot_code, now()
  )
  ON CONFLICT (asset_id) DO UPDATE SET
    home_base_id = EXCLUDED.home_base_id,
    vehicle_type = EXCLUDED.vehicle_type,
    seat_count = EXCLUDED.seat_count,
    availability_status = EXCLUDED.availability_status,
    allow_self_drive = EXCLUDED.allow_self_drive,
    inspection_certificate_number = EXCLUDED.inspection_certificate_number,
    inspection_expiry_date = EXCLUDED.inspection_expiry_date,
    inspection_photo_path = EXCLUDED.inspection_photo_path,
    insurance_expiry_date = EXCLUDED.insurance_expiry_date,
    parking_spot_code = EXCLUDED.parking_spot_code,
    updated_at = now();

  RETURN jsonb_build_object('success', true, 'asset_id', p_asset_id);
END;
$$;


--
-- Name: company_procurement_can_manage(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.company_procurement_can_manage() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
