--
-- Name: create_daily_log_assignment(text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.create_daily_log_assignment(p_log_id text, p_actor_user_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_log public.daily_logs%rowtype;
  v_responsibility text;
  v_permission_code text;
  v_slot record;
  v_selected_user_id uuid;
  v_assignee_user_id uuid;
  v_scope_type text;
  v_scope_id text;
  v_assigned_reason text;
  v_metadata jsonb;
  v_assignment_id uuid;
begin
  select * into v_log from public.daily_logs where id = p_log_id for update;
  if not found then
    raise exception 'Không tìm thấy nhật ký công trường.' using errcode = 'P0002';
  end if;

  v_responsibility := case when coalesce(v_log.submitted_to_permission, '') = 'approve' then 'current_approver' else 'current_verifier' end;
  v_permission_code := case when v_responsibility = 'current_approver' then 'project.daily_log.approve' else 'project.daily_log.verify' end;

  select user_row.id
  into v_selected_user_id
  from public.users user_row
  where user_row.id::text = nullif(v_log.submitted_to_user_id, '');

  if v_selected_user_id is not null then
    if not app_private.daily_log_user_can_receive_assignment(
      v_log.project_id::text,
      v_log.construction_site_id::text,
      v_permission_code,
      v_selected_user_id
    ) then
      raise exception 'Người được chọn không còn quyền % trong Room Nhật ký công trường.', v_responsibility
        using errcode = '42501';
    end if;

    v_assignee_user_id := v_selected_user_id;
    v_scope_type := case when nullif(v_log.construction_site_id::text, '') is not null then 'construction_site' else 'project' end;
    v_scope_id := coalesce(nullif(v_log.construction_site_id::text, ''), nullif(v_log.project_id::text, ''));
    v_assigned_reason := 'selected_from_daily_log_room';
    v_metadata := jsonb_build_object('source', 'daily_log_room', 'selected_by', p_actor_user_id);
  else
    select * into v_slot
    from app_private.resolve_daily_log_responsibility(
      v_log.project_id::text,
      v_log.construction_site_id::text,
      v_responsibility,
      v_permission_code
    );

    if not found then
      raise exception 'Chưa chọn người chịu trách nhiệm % trong Room Nhật ký công trường.', v_responsibility
        using errcode = '42501',
              hint = 'Chọn người nhận trong Room Nhật ký công trường trước khi gửi.';
    end if;

    v_assignee_user_id := v_slot.assignee_user_id;
    v_scope_type := v_slot.scope_type;
    v_scope_id := v_slot.scope_id;
    v_assigned_reason := 'resolved_from_responsibility_slot';
    v_metadata := jsonb_build_object('responsibility_slot_id', v_slot.responsibility_slot_id);
  end if;

  with cancelled_assignments as (
    update public.app_assignments
    set status = 'cancelled', closed_at = now(), closed_by = p_actor_user_id,
        close_reason = 'reassigned', updated_at = now()
    where subject_type = 'daily_log' and subject_id = p_log_id and status = 'active'
    returning id
  )
  insert into public.app_assignment_events (assignment_id, event_type, actor_user_id, metadata)
  select id, 'cancelled', p_actor_user_id, jsonb_build_object('reason', 'reassigned')
  from cancelled_assignments;

  insert into public.app_assignments (
    subject_type, subject_id, workflow_step_id, principal_type, principal_id,
    responsibility, permission_code, scope_type, scope_id, status,
    assigned_by, assigned_reason, metadata
  ) values (
    'daily_log', p_log_id, v_responsibility, 'user', v_assignee_user_id,
    v_responsibility, v_permission_code, v_scope_type, v_scope_id, 'active',
    p_actor_user_id, v_assigned_reason, v_metadata
  ) returning id into v_assignment_id;

  insert into public.app_assignment_events (assignment_id, event_type, actor_user_id, metadata)
  values (v_assignment_id, 'assigned', p_actor_user_id, v_metadata);

  return v_assignment_id;
end;
$$;


--
-- Name: create_daily_log_revision_assignment(text, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.create_daily_log_revision_assignment(p_log_id text, p_owner_user_id uuid, p_actor_user_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_log public.daily_logs%rowtype;
  v_assignment_id uuid;
  v_scope_type text;
  v_scope_id text;
begin
  if p_owner_user_id is null then
    return null;
  end if;

  select *
  into v_log
  from public.daily_logs
  where id = p_log_id
  for update;

  if not found then
    return null;
  end if;

  v_scope_type := case when nullif(v_log.construction_site_id::text, '') is not null then 'construction_site' else 'project' end;
  v_scope_id := coalesce(nullif(v_log.construction_site_id::text, ''), nullif(v_log.project_id::text, ''));

  with cancelled_assignments as (
    update public.app_assignments
    set status = 'cancelled',
        closed_at = now(),
        closed_by = p_actor_user_id,
        close_reason = 'superseded_revision_owner',
        updated_at = now()
    where subject_type = 'daily_log'
      and subject_id = p_log_id
      and responsibility = 'revision_owner'
      and status = 'active'
    returning id
  )
  insert into public.app_assignment_events (assignment_id, event_type, actor_user_id, metadata)
  select id, 'cancelled', p_actor_user_id, jsonb_build_object('reason', 'superseded_revision_owner')
  from cancelled_assignments;

  insert into public.app_assignments (
    subject_type,
    subject_id,
    workflow_step_id,
    principal_type,
    principal_id,
    responsibility,
    permission_code,
    scope_type,
    scope_id,
    status,
    assigned_by,
    assigned_reason
  )
  values (
    'daily_log',
    p_log_id,
    'revision',
    'user',
    p_owner_user_id,
    'revision_owner',
    'project.daily_log.edit_own',
    v_scope_type,
    v_scope_id,
    'active',
    p_actor_user_id,
    'returned_to_owner'
  )
  returning id into v_assignment_id;

  insert into public.app_assignment_events (assignment_id, event_type, actor_user_id)
  values (v_assignment_id, 'assigned', p_actor_user_id);

  return v_assignment_id;
end;
$$;


--
-- Name: create_delivery_batch_with_wms_qr_core_v2(text, uuid, text, text, text, numeric, text, date, text, uuid, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.create_delivery_batch_with_wms_qr_core_v2(p_purchase_order_id text, p_idempotency_key uuid, p_supplier_id text, p_supplier_name text, p_fulfillment_mode text, p_vat_rate numeric, p_target_warehouse_id text, p_planned_delivery_date date, p_note text, p_actor_user_id uuid, p_lines jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_po public.purchase_orders%rowtype;
  v_existing public.purchase_order_delivery_batches%rowtype;
  v_batch_id uuid := gen_random_uuid();
  v_delivery_no integer;
  v_qr_token text := 'pod_' || replace(gen_random_uuid()::text, '-', '');
  v_tx_id text := 'tx-po-delivery-' || replace(gen_random_uuid()::text, '-', '');
  v_wms_items jsonb := '[]'::jsonb;
  v_delivery_lines jsonb := '[]'::jsonb;
  v_line jsonb;
  v_po_line jsonb;
  v_line_id uuid;
  v_line_key text;
  v_seen_line_keys text[] := '{}'::text[];
  v_purchase_order_line_id text;
  v_item_id text;
  v_purchase_qty numeric;
  v_stock_qty numeric;
  v_purchase_unit text;
  v_stock_unit text;
  v_purchase_unit_price numeric;
  v_stock_unit_price numeric;
begin
  if p_idempotency_key is null then
    raise exception 'Idempotency key is required.' using errcode = '22023';
  end if;
  if p_actor_user_id is null then
    raise exception 'Nguoi thuc hien lenh khong hop le.' using errcode = '42501';
  end if;
  if public.current_app_user_id() is null or p_actor_user_id <> public.current_app_user_id() then
    raise exception 'Nguoi thuc hien lenh khong hop le.' using errcode = '42501';
  end if;
  if p_fulfillment_mode not in ('RECEIVE_TO_STOCK', 'DIRECT_CONSUMPTION') then
    raise exception 'Fulfillment mode khong hop le: %', p_fulfillment_mode using errcode = '22023';
  end if;
  if coalesce(p_vat_rate, 0) < 0 then
    raise exception 'VAT khong duoc am.' using errcode = '22023';
  end if;
  if nullif(trim(coalesce(p_target_warehouse_id, '')), '') is null then
    raise exception 'Kho nhan hang la bat buoc.' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_lines, '[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p_lines, '[]'::jsonb)) = 0 then
    raise exception 'Dot giao phai co it nhat mot dong vat tu.' using errcode = '22023';
  end if;

  select * into v_po
  from public.purchase_orders
  where id = p_purchase_order_id
  for update;

  if not found then
    raise exception 'Khong tim thay Goi mua hang %.', p_purchase_order_id using errcode = '22023';
  end if;
  if v_po.status not in ('confirmed', 'in_transit', 'partial') then
    raise exception 'Chi tao Dot giao cho Goi da duyet hoac dang giao.' using errcode = '22023';
  end if;

  select * into v_existing
  from public.purchase_order_delivery_batches
  where purchase_order_id = p_purchase_order_id
    and idempotency_key = p_idempotency_key
  for update;
  if found then
    return app_private.purchase_delivery_command_result_v2(v_existing.id);
  end if;

  perform 1
  from public.purchase_order_delivery_batches
  where purchase_order_id = p_purchase_order_id
  order by id
  for update;

  select coalesce(max(delivery_no), 0) + 1
  into v_delivery_no
  from public.purchase_order_delivery_batches
  where purchase_order_id = p_purchase_order_id;

  insert into public.purchase_order_delivery_batches (
    id, purchase_order_id, project_id, construction_site_id, delivery_no,
    planned_delivery_date, status, fulfillment_batch_ids, note, created_by,
    supplier_id, supplier_name_snapshot, fulfillment_mode, vat_rate,
    qr_token, idempotency_key
  ) values (
    v_batch_id, v_po.id, v_po.project_id, v_po.construction_site_id, v_delivery_no,
    p_planned_delivery_date, 'waiting_delivery', '{}'::text[], nullif(p_note, ''), p_actor_user_id,
    nullif(p_supplier_id, ''), nullif(p_supplier_name, ''), p_fulfillment_mode, coalesce(p_vat_rate, 0),
    v_qr_token, p_idempotency_key
  );

  for v_line in
    select value from jsonb_array_elements(p_lines) as line(value)
  loop
    v_purchase_order_line_id := nullif(v_line ->> 'purchaseOrderLineId', '');
    v_item_id := nullif(v_line ->> 'itemId', '');
    v_purchase_qty := coalesce(nullif(v_line ->> 'purchaseQty', '')::numeric, 0);
    v_stock_qty := coalesce(nullif(v_line ->> 'stockQty', '')::numeric, 0);
    v_purchase_unit := coalesce(nullif(v_line ->> 'purchaseUnit', ''), 'DV mua');
    v_stock_unit := coalesce(nullif(v_line ->> 'stockUnit', ''), v_purchase_unit);
    v_purchase_unit_price := coalesce(nullif(v_line ->> 'purchaseUnitPrice', '')::numeric, 0);
    v_stock_unit_price := coalesce(nullif(v_line ->> 'stockUnitPrice', '')::numeric, 0);

    if v_purchase_order_line_id is null or v_item_id is null then
      raise exception 'Dong Dot giao thieu PO line hoac vat tu.' using errcode = '22023';
    end if;
    if v_purchase_qty <= 0 or v_stock_qty <= 0 then
      raise exception 'So luong Dot giao phai lon hon 0.' using errcode = '22023';
    end if;
    if v_purchase_unit_price < 0 or v_stock_unit_price < 0 then
      raise exception 'Don gia Dot giao khong duoc am.' using errcode = '22023';
    end if;

    select po_line.value into v_po_line
    from jsonb_array_elements(v_po.items) as po_line(value)
    where coalesce(po_line.value ->> 'lineId', po_line.value ->> 'itemId') = v_purchase_order_line_id
    limit 1;
    if v_po_line is null or coalesce(v_po_line ->> 'itemId', '') <> v_item_id then
      raise exception 'Dong Dot giao khong khop voi Goi mua hang.' using errcode = '22023';
    end if;

    v_line_key := v_purchase_order_line_id || ':' || v_item_id;
    if v_line_key = any(v_seen_line_keys) then
      raise exception 'Dong Dot giao bi lap trong lenh tao.' using errcode = '22023';
    end if;
    v_seen_line_keys := array_append(v_seen_line_keys, v_line_key);
    v_line_id := gen_random_uuid();

    v_delivery_lines := v_delivery_lines || jsonb_build_array(jsonb_build_object(
      'id', v_line_id,
      'purchaseOrderLineId', v_purchase_order_line_id,
      'itemId', v_item_id,
      'purchaseQty', v_purchase_qty,
      'purchaseUnit', v_purchase_unit,
      'stockQty', v_stock_qty,
      'stockUnit', v_stock_unit,
      'purchaseUnitPrice', v_purchase_unit_price
    ));

    v_wms_items := v_wms_items || jsonb_build_array(jsonb_build_object(
      'itemId', v_item_id,
      'quantity', v_stock_qty,
      'orderedQty', v_stock_qty,
      'price', v_stock_unit_price,
      'accountingQty', v_purchase_qty,
      'accountingUnit', v_purchase_unit,
      'accountingPrice', v_purchase_unit_price,
      'purchaseOrderLineId', v_purchase_order_line_id,
      'purchaseOrderDeliveryBatchId', v_batch_id,
      'purchaseOrderDeliveryLineId', v_line_id,
      'fulfillmentMode', p_fulfillment_mode
    ));
  end loop;

  insert into public.transactions (
    id, type, date, items, target_warehouse_id, supplier_id,
    requester_id, created_by, approver_id, status, note,
    business_partner_id, business_partner_name_snapshot, source_type, source_id
  ) values (
    v_tx_id, 'IMPORT'::public.transaction_type, now(), v_wms_items, p_target_warehouse_id, nullif(p_supplier_id, ''),
    p_actor_user_id, p_actor_user_id, p_actor_user_id, 'PENDING'::public.transaction_status,
    coalesce(v_po.po_number, v_po.id) || '-' || lpad(v_delivery_no::text, 2, '0') || ' dang giao',
    null, nullif(p_supplier_name, ''), 'po_delivery_batch', v_batch_id::text
  );

  for v_line in
    select value from jsonb_array_elements(v_delivery_lines) as line(value)
  loop
    insert into public.purchase_order_delivery_lines (
      id, delivery_batch_id, purchase_order_id, purchase_order_line_id, item_id,
      planned_qty, unit, delivery_unit_price, stock_planned_qty, stock_unit
    ) values (
      (v_line ->> 'id')::uuid, v_batch_id, v_po.id, v_line ->> 'purchaseOrderLineId', v_line ->> 'itemId',
      (v_line ->> 'purchaseQty')::numeric, v_line ->> 'purchaseUnit', (v_line ->> 'purchaseUnitPrice')::numeric,
      (v_line ->> 'stockQty')::numeric, v_line ->> 'stockUnit'
    );
  end loop;

  update public.purchase_order_delivery_batches
  set wms_transaction_id = v_tx_id,
      status = 'receiving',
      updated_at = now()
  where id = v_batch_id;

  return app_private.purchase_delivery_command_result_v2(v_batch_id);
exception
  when unique_violation then
    select * into v_existing
    from public.purchase_order_delivery_batches
    where purchase_order_id = p_purchase_order_id
      and idempotency_key = p_idempotency_key;
    if found then
      return app_private.purchase_delivery_command_result_v2(v_existing.id);
    end if;
    raise;
end;
$$;


--
-- Name: create_delivery_batch_with_wms_qr_v2(text, uuid, text, text, text, numeric, text, date, text, uuid, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.create_delivery_batch_with_wms_qr_v2(p_purchase_order_id text, p_idempotency_key uuid, p_supplier_id text, p_supplier_name text, p_fulfillment_mode text, p_vat_rate numeric, p_target_warehouse_id text, p_planned_delivery_date date, p_note text, p_actor_user_id uuid, p_lines jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_po public.purchase_orders%rowtype;
begin
  if p_actor_user_id is null then
    raise exception 'Nguoi thuc hien lenh khong hop le.' using errcode = '42501';
  end if;
  if public.current_app_user_id() is null or p_actor_user_id <> public.current_app_user_id() then
    raise exception 'Nguoi thuc hien lenh khong hop le.' using errcode = '42501';
  end if;

  select * into v_po
  from public.purchase_orders
  where id = p_purchase_order_id
  for update;
  if not found then
    raise exception 'Khong tim thay Goi mua hang %.', p_purchase_order_id using errcode = '22023';
  end if;

  perform app_private.assert_project_permission_room_action(
    v_po.project_id,
    v_po.construction_site_id,
    'material_po',
    'submit',
    p_actor_user_id
  );

  return app_private.create_delivery_batch_with_wms_qr_core_v2(
    p_purchase_order_id, p_idempotency_key, p_supplier_id, p_supplier_name,
    p_fulfillment_mode, p_vat_rate, p_target_warehouse_id,
    p_planned_delivery_date, p_note, p_actor_user_id, p_lines
  );
end;
$$;


--
-- Name: create_project(jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.create_project(p_project jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_project public.projects%rowtype;
  v_actor_user_id uuid := public.current_app_user_id();
  v_creator_user_id uuid := v_actor_user_id;
  v_created_by text := nullif(p_project->>'created_by', '');
begin
  if not app_private.can_manage_project_master(null, 'project.master.create') then
    raise exception 'Not allowed to create project'
      using errcode = '42501';
  end if;

  if nullif(p_project->>'name', '') is null then
    raise exception 'Project name is required'
      using errcode = '23502';
  end if;

  if v_created_by ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    v_creator_user_id := v_created_by::uuid;
  end if;

  insert into public.projects (
    code,
    name,
    description,
    client_name,
    project_type,
    project_group_id,
    project_type_id,
    project_sector_id,
    workflow_template_id,
    status,
    construction_site_id,
    manager_id,
    start_date,
    end_date,
    progress_calculation_mode,
    manual_progress_percent,
    created_by,
    source
  )
  values (
    coalesce(nullif(p_project->>'code', ''), 'PRJ-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 12))),
    nullif(p_project->>'name', ''),
    nullif(p_project->>'description', ''),
    nullif(p_project->>'client_name', ''),
    coalesce(nullif(p_project->>'project_type', ''), 'construction'),
    nullif(p_project->>'project_group_id', '')::uuid,
    nullif(p_project->>'project_type_id', '')::uuid,
    nullif(p_project->>'project_sector_id', '')::uuid,
    nullif(p_project->>'workflow_template_id', '')::uuid,
    coalesce(nullif(p_project->>'status', ''), 'planning'),
    nullif(p_project->>'construction_site_id', '')::uuid,
    nullif(p_project->>'manager_id', ''),
    nullif(p_project->>'start_date', '')::date,
    nullif(p_project->>'end_date', '')::date,
    coalesce(nullif(p_project->>'progress_calculation_mode', ''), 'gantt_weighted'),
    coalesce(nullif(p_project->>'manual_progress_percent', '')::numeric, 0),
    v_created_by,
    coalesce(nullif(p_project->>'source', ''), 'manual')
  )
  returning *
  into v_project;

  if v_creator_user_id is not null then
    insert into public.user_permission_grants (
      user_id,
      permission_code,
      scope_type,
      scope_id,
      is_active,
      granted_by,
      granted_at
    )
    select
      v_creator_user_id,
      permission_code,
      'project',
      v_project.id,
      true,
      v_actor_user_id,
      now()
    from unnest(array[
      'project.master.view',
      'project.master.edit',
      'project.org.view',
      'project.org.assign_staff',
      'project.org.grant_permissions'
    ]::text[]) permission_code
    on conflict (user_id, permission_code, scope_type, scope_id) do update
    set is_active = true,
        granted_by = excluded.granted_by,
        granted_at = excluded.granted_at,
        updated_at = now();
  end if;

  return to_jsonb(v_project);
end;
$_$;


--
-- Name: create_project_gantt_baseline_impl(uuid, text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.create_project_gantt_baseline_impl(p_request_id uuid, p_project_id text, p_construction_site_id text, p_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid;
  v_site_id text := nullif(btrim(coalesce(p_construction_site_id, '')), '');
  v_replay jsonb;
  v_baseline public.project_baselines%rowtype;
  v_result jsonb;
begin
  v_actor_user_id := app_private.assert_project_gantt_action(p_project_id, v_site_id, 'edit');
  if nullif(btrim(coalesce(p_name, '')), '') is null then
    raise exception 'GANTT_INVALID_PAYLOAD' using errcode = '22023';
  end if;
  v_replay := app_private.begin_project_gantt_command(
    v_actor_user_id, p_request_id, 'create_project_gantt_baseline',
    md5(jsonb_build_object('projectId', p_project_id,
      'constructionSiteId', v_site_id, 'name', btrim(p_name))::text)
  );
  if v_replay is not null then return v_replay; end if;

  insert into public.project_baselines (
    id, project_id, construction_site_id, name, locked_at, locked_by, tasks_snapshot
  )
  select gen_random_uuid()::text, p_project_id, v_site_id, btrim(p_name), now(),
    v_actor_user_id::text,
    coalesce(jsonb_agg(to_jsonb(task) order by task.sort_order, task.id), '[]'::jsonb)
  from public.project_tasks task
  where task.project_id = p_project_id
    and task.construction_site_id is not distinct from v_site_id
  returning * into v_baseline;

  v_result := jsonb_build_object(
    'ok', true, 'requestId', p_request_id, 'replayed', false,
    'baseline', to_jsonb(v_baseline)
  );
  return app_private.finish_project_gantt_command(v_actor_user_id, p_request_id, v_result);
end;
$$;


--
-- Name: create_quality_checklist_impl(uuid, text, text, jsonb, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.create_quality_checklist_impl(p_request_id uuid, p_project_id text, p_construction_site_id text, p_payload jsonb, p_submission_target jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_target uuid := nullif(p_submission_target ->> 'user_id', '')::uuid;
  v_replay jsonb;
  v_result jsonb;
  v_row public.quality_checklists%rowtype;
  v_target_name text;
begin
  v_actor := app_private.assert_quality_action(p_project_id, p_construction_site_id, 'edit');
  if jsonb_typeof(coalesce(p_payload, 'null'::jsonb)) <> 'object'
    or nullif(btrim(coalesce(p_payload ->> 'title', '')), '') is null then
    raise exception 'QUALITY_INVALID_TRANSITION: invalid payload' using errcode = '22023';
  end if;
  if v_target is not null then
    perform app_private.assert_quality_action(p_project_id, p_construction_site_id, 'submit');
    perform app_private.assert_quality_recipient(v_target, p_project_id, p_construction_site_id);
    select user_row.name into v_target_name from public.users user_row where user_row.id = v_target;
  end if;
  v_replay := app_private.begin_quality_command(v_actor, p_request_id,
    'create_quality_checklist', md5(jsonb_build_object(
      'projectId', p_project_id, 'constructionSiteId', p_construction_site_id,
      'payload', p_payload, 'submissionTarget', p_submission_target
    )::text));
  if v_replay is not null then return v_replay; end if;

  insert into public.quality_checklists (
    project_id, construction_site_id, task_id, contract_item_id, daily_log_id,
    template_id, work_type_id, code, title, template_code, template_name,
    template_version, standard_reference, work_description, work_location,
    work_date, work_supervisor, checklist_data, site_photos, attachments,
    conclusion, conclusion_result, conditions, inspector_name, inspector_sign_url,
    approver_name, approver_sign_url, inspection_result, total_criteria,
    passed_criteria, failed_criteria, current_attempt, note, drawing_url,
    drawing_markers, target_completion_date, signers_data, status, created_by,
    submitted_by, submitted_at, submitted_to_user_id, submitted_to_name,
    submitted_to_permission, submission_note, ever_submitted, last_action_by,
    last_action_at, created_at, updated_at
  ) values (
    p_project_id::uuid, p_construction_site_id::uuid,
    nullif(p_payload ->> 'task_id', '')::uuid,
    nullif(p_payload ->> 'contract_item_id', '')::uuid,
    nullif(p_payload ->> 'daily_log_id', '')::uuid,
    nullif(p_payload ->> 'template_id', '')::uuid,
    nullif(p_payload ->> 'work_type_id', '')::uuid,
    coalesce(nullif(btrim(p_payload ->> 'code'), ''),
      'QC-' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSMS')),
    btrim(p_payload ->> 'title'), nullif(p_payload ->> 'template_code', ''),
    nullif(p_payload ->> 'template_name', ''),
    nullif(p_payload ->> 'template_version', '')::integer,
    nullif(p_payload ->> 'standard_reference', ''),
    nullif(p_payload ->> 'work_description', ''),
    nullif(p_payload ->> 'work_location', ''),
    nullif(p_payload ->> 'work_date', '')::date,
    nullif(p_payload ->> 'work_supervisor', ''),
    coalesce(p_payload -> 'checklist_data', '[]'::jsonb),
    coalesce(p_payload -> 'site_photos', '[]'::jsonb),
    coalesce(p_payload -> 'attachments', '[]'::jsonb),
    nullif(p_payload ->> 'conclusion', ''),
    nullif(p_payload ->> 'conclusion_result', ''),
    nullif(p_payload ->> 'conditions', ''), nullif(p_payload ->> 'inspector_name', ''),
    nullif(p_payload ->> 'inspector_sign_url', ''), nullif(p_payload ->> 'approver_name', ''),
    nullif(p_payload ->> 'approver_sign_url', ''), nullif(p_payload ->> 'inspection_result', ''),
    coalesce((p_payload ->> 'total_criteria')::integer, 0),
    coalesce((p_payload ->> 'passed_criteria')::integer, 0),
    coalesce((p_payload ->> 'failed_criteria')::integer, 0),
    greatest(coalesce((p_payload ->> 'current_attempt')::integer, 1), 1),
    nullif(p_payload ->> 'note', ''), nullif(p_payload ->> 'drawing_url', ''),
    coalesce(p_payload -> 'drawing_markers', '[]'::jsonb),
    nullif(p_payload ->> 'target_completion_date', '')::date,
    coalesce(p_payload -> 'signers_data', '[]'::jsonb),
    case when v_target is null then 'draft' else 'submitted' end,
    v_actor::text,
    case when v_target is null then null else v_actor::text end,
    case when v_target is null then null else now() end,
    v_target::text, v_target_name,
    case when v_target is null then null else 'approve' end,
    nullif(p_submission_target ->> 'note', ''), v_target is not null,
    v_actor::text, now(), now(), now()
  ) returning * into v_row;

  if v_target is not null then
    insert into public.notifications (
      user_id, title, body, message, type, category, severity, module, link,
      source_type, source_id, construction_site_id, metadata
    ) values (
      v_target::text, 'Hồ sơ chất lượng ' || v_row.code || ' chờ duyệt',
      'Bạn được chọn phê duyệt hồ sơ chất lượng ' || v_row.title || '.',
      'Bạn được chọn phê duyệt hồ sơ chất lượng ' || v_row.title || '.',
      'info', 'quality', 'info', 'DA', '/da', 'quality_checklist', v_row.id::text,
      p_construction_site_id, jsonb_build_object(
        'projectId', p_project_id, 'constructionSiteId', p_construction_site_id,
        'submittedToUserId', v_target
      )
    );
  end if;

  insert into public.audit_trail (
    table_name, record_id, action, new_data, user_id, user_name,
    module, description, context
  ) values (
    'quality_checklists', v_row.id::text, 'INSERT', to_jsonb(v_row),
    v_actor::text, v_actor::text, 'quality',
    case when v_target is null then 'Tạo hồ sơ chất lượng'
      else 'Tạo và gửi duyệt hồ sơ chất lượng' end,
    jsonb_build_object('requestId', p_request_id, 'roomCode', 'quality')
  );

  v_result := jsonb_build_object('ok', true, 'requestId', p_request_id,
    'replayed', false, 'checklist', to_jsonb(v_row));
  return app_private.finish_quality_command(v_actor, p_request_id, v_result);
end;
$$;


--
-- Name: create_quality_inspection_attempt_impl(uuid, text, text, uuid, timestamp with time zone, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.create_quality_inspection_attempt_impl(p_request_id uuid, p_project_id text, p_construction_site_id text, p_checklist_id uuid, p_expected_updated_at timestamp with time zone, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_old public.quality_checklists%rowtype;
  v_row public.quality_checklists%rowtype;
  v_attempt public.quality_inspection_attempts%rowtype;
  v_replay jsonb;
  v_result jsonb;
begin
  v_actor := app_private.assert_quality_action(p_project_id, p_construction_site_id, 'edit');
  v_replay := app_private.begin_quality_command(v_actor, p_request_id,
    'create_quality_inspection_attempt', md5(jsonb_build_object(
      'projectId', p_project_id, 'constructionSiteId', p_construction_site_id,
      'checklistId', p_checklist_id, 'expectedUpdatedAt', p_expected_updated_at,
      'payload', p_payload
    )::text));
  if v_replay is not null then return v_replay; end if;
  select * into v_old from public.quality_checklists item
  where item.id = p_checklist_id for update;
  if not found or v_old.project_id::text is distinct from p_project_id
    or v_old.construction_site_id::text is distinct from p_construction_site_id then
    raise exception 'QUALITY_SCOPE_MISMATCH' using errcode = '23514';
  end if;
  if v_old.updated_at is distinct from p_expected_updated_at then
    raise exception 'QUALITY_STALE_VERSION' using errcode = '40001';
  end if;
  if v_old.status not in ('draft', 'returned')
    or coalesce(p_payload ->> 'result', '') not in ('PASSED', 'FAILED') then
    raise exception 'QUALITY_INVALID_TRANSITION' using errcode = '23514';
  end if;

  insert into public.quality_inspection_attempts (
    checklist_id, attempt_number, inspection_date, inspector_name,
    items_data, result, conclusion, signature_url, created_by
  ) values (
    p_checklist_id,
    coalesce((p_payload ->> 'attempt_number')::integer, v_old.current_attempt),
    coalesce(nullif(p_payload ->> 'inspection_date', '')::date, current_date),
    nullif(p_payload ->> 'inspector_name', ''),
    coalesce(p_payload -> 'items_data', '[]'::jsonb), p_payload ->> 'result',
    nullif(p_payload ->> 'conclusion', ''), nullif(p_payload ->> 'signature_url', ''),
    v_actor::text
  ) returning * into v_attempt;
  update public.quality_checklists item
  set current_attempt = greatest(item.current_attempt, v_attempt.attempt_number + 1),
      last_action_by = v_actor::text, last_action_at = now(), updated_at = now()
  where item.id = p_checklist_id
  returning * into v_row;

  insert into public.audit_trail (
    table_name, record_id, action, new_data, user_id, user_name,
    module, description, context
  ) values (
    'quality_inspection_attempts', v_attempt.id::text, 'INSERT', to_jsonb(v_attempt),
    v_actor::text, v_actor::text, 'quality', 'Tạo lần kiểm tra chất lượng',
    jsonb_build_object('requestId', p_request_id, 'roomCode', 'quality',
      'checklistId', p_checklist_id)
  );
  v_result := jsonb_build_object('ok', true, 'requestId', p_request_id,
    'replayed', false, 'checklist', to_jsonb(v_row), 'attempt', to_jsonb(v_attempt));
  return app_private.finish_quality_command(v_actor, p_request_id, v_result);
end;
$$;


--
-- Name: create_request_template_draft_from_published(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.create_request_template_draft_from_published(p_request_template_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_template public.request_templates%rowtype;
  v_published public.request_template_versions%rowtype;
  v_draft public.request_template_versions%rowtype;
  v_number integer;
begin
  if v_actor is null or not app_private.request_user_can_manage(v_actor) then
    raise exception using errcode = '42501', message = 'REQUEST_TEMPLATE_FORBIDDEN';
  end if;

  select * into v_template
  from public.request_templates
  where id = p_request_template_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'REQUEST_TEMPLATE_NOT_FOUND';
  end if;

  select * into v_published
  from public.request_template_versions
  where request_template_id = v_template.id
    and status = 'PUBLISHED'
  order by version_number desc
  limit 1;
  if not found then
    raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_PUBLISHED_REQUIRED';
  end if;

  select coalesce(max(version_number), 0) + 1 into v_number
  from public.request_template_versions
  where request_template_id = v_template.id;

  insert into public.request_template_versions(
    request_template_id, version_number, form_schema, usage_scope, flow_mode,
    completion_policy, request_sla_hours, print_config, notification_config,
    status, created_by
  ) values (
    v_template.id, v_number, v_published.form_schema, v_published.usage_scope,
    v_published.flow_mode, v_published.completion_policy, v_published.request_sla_hours,
    v_published.print_config, v_published.notification_config, 'DRAFT', v_actor
  ) returning * into v_draft;

  insert into public.request_approval_blocks(
    request_template_version_id, block_key, name, sort_order, approver_source,
    fixed_user_ids, minimum_dynamic_approvers, sla_hours, is_required
  )
  select v_draft.id, block_key, name, sort_order, approver_source,
    fixed_user_ids, minimum_dynamic_approvers, sla_hours, is_required
  from public.request_approval_blocks
  where request_template_version_id = v_published.id;

  insert into public.request_template_watchers(request_template_version_id, user_id)
  select v_draft.id, user_id
  from public.request_template_watchers
  where request_template_version_id = v_published.id
  on conflict do nothing;

  insert into public.request_print_templates(
    request_template_version_id, name, file_name, storage_path,
    validation_status, placeholder_schema
  )
  select v_draft.id, name, file_name, storage_path,
    validation_status, placeholder_schema
  from public.request_print_templates
  where request_template_version_id = v_published.id;

  update public.request_templates
  set lifecycle_status = 'DRAFT'
  where id = v_template.id
  returning * into v_template;

  return jsonb_build_object(
    'id', v_draft.request_template_id,
    'draftVersionId', v_draft.id,
    'status', v_draft.status,
    'versionNumber', v_draft.version_number,
    'updatedAt', v_template.updated_at,
    'payload', app_private.request_template_draft_payload(v_draft.id)
  );
end;
$$;


--
-- Name: create_safety_worker_profile_for_site(text, uuid, text, jsonb, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.create_safety_worker_profile_for_site(p_project_id text, p_construction_site_id uuid, p_worker_kind text, p_profile jsonb, p_subcontractor_id uuid DEFAULT NULL::uuid, p_team_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_worker public.safety_worker_profiles%rowtype;
  v_worker_by_code uuid;
  v_worker_by_identity uuid;
  v_membership public.safety_worker_site_memberships%rowtype;
  v_worker_code text := nullif(trim(p_profile ->> 'workerCode'), '');
  v_full_name text := nullif(trim(p_profile ->> 'fullName'), '');
  v_identity_type text := coalesce(nullif(trim(p_profile ->> 'identityType'), ''), 'cccd');
  v_identity_number text := nullif(trim(p_profile ->> 'identityNumber'), '');
  v_identity_normalized text;
begin
  perform app_private.safety_workforce_assert_scope(p_project_id, p_construction_site_id);
  if v_actor is null or not app_private.safety_workforce_can_manage(p_project_id, p_construction_site_id) then
    raise exception 'SAFETY_SCOPE_MISMATCH: actor cannot create worker at target site'
      using errcode = '42501';
  end if;
  if jsonb_typeof(coalesce(p_profile, 'null'::jsonb)) <> 'object' or v_full_name is null then
    raise exception 'SAFETY_INVALID_RPC_PAYLOAD: full name is required'
      using errcode = '22023';
  end if;
  if v_identity_type not in ('cccd', 'passport', 'other') then
    raise exception 'SAFETY_INVALID_RPC_PAYLOAD: invalid identity type'
      using errcode = '22023';
  end if;

  perform app_private.safety_workforce_assert_subcontractor_team(
    p_project_id,
    p_construction_site_id,
    p_subcontractor_id,
    p_team_id,
    p_worker_kind
  );

  v_identity_normalized := app_private.safety_workforce_normalize_identity(v_identity_number);

  if v_worker_code is not null then
    select worker.id
    into v_worker_by_code
    from public.safety_worker_profiles worker
    where lower(worker.worker_code) = lower(v_worker_code)
    limit 1;
  end if;

  if v_identity_normalized is not null then
    select worker.id
    into v_worker_by_identity
    from public.safety_worker_profiles worker
    where worker.identity_type = v_identity_type
      and worker.identity_number_normalized = v_identity_normalized
    limit 1;
  end if;

  if v_worker_by_code is not null
    and v_worker_by_identity is not null
    and v_worker_by_code <> v_worker_by_identity
  then
    raise exception 'SAFETY_INVALID_RPC_PAYLOAD: worker code and identity belong to different profiles'
      using errcode = '23505';
  end if;

  if coalesce(v_worker_by_code, v_worker_by_identity) is not null then
    select worker.*
    into v_worker
    from public.safety_worker_profiles worker
    where worker.id = coalesce(v_worker_by_code, v_worker_by_identity)
    for update;

    if v_worker.worker_kind is not null and v_worker.worker_kind <> p_worker_kind then
      raise exception 'SAFETY_INVALID_RPC_PAYLOAD: worker kind conflicts with existing profile'
        using errcode = '22023';
    end if;

    update public.safety_worker_profiles worker
    set worker_kind = coalesce(worker.worker_kind, p_worker_kind),
        updated_by = v_actor::text,
        updated_at = now()
    where worker.id = v_worker.id
    returning * into v_worker;
  else
    insert into public.safety_worker_profiles (
      worker_code,
      full_name,
      worker_kind,
      identity_type,
      identity_number,
      identity_issue_date,
      identity_issue_place,
      date_of_birth,
      permanent_address,
      phone,
      role_name,
      status,
      identity_attachments,
      created_by,
      updated_by
    ) values (
      coalesce(v_worker_code, 'SW-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10))),
      v_full_name,
      p_worker_kind,
      v_identity_type,
      v_identity_number,
      nullif(p_profile ->> 'identityIssueDate', '')::date,
      nullif(trim(p_profile ->> 'identityIssuePlace'), ''),
      nullif(p_profile ->> 'dateOfBirth', '')::date,
      nullif(trim(p_profile ->> 'permanentAddress'), ''),
      nullif(trim(p_profile ->> 'phone'), ''),
      nullif(trim(p_profile ->> 'roleName'), ''),
      'active',
      '[]'::jsonb,
      v_actor::text,
      v_actor::text
    )
    returning * into v_worker;
  end if;

  insert into public.safety_worker_site_memberships (
    worker_id,
    project_id,
    construction_site_id,
    default_subcontractor_id,
    default_team_id,
    status,
    source,
    created_by,
    updated_by
  ) values (
    v_worker.id,
    p_project_id,
    p_construction_site_id,
    case when p_worker_kind = 'company_staff' then null else p_subcontractor_id end,
    case when p_worker_kind = 'company_staff' then null else p_team_id end,
    'candidate',
    'manual',
    v_actor,
    v_actor
  )
  on conflict (worker_id, construction_site_id) do update
  set project_id = excluded.project_id,
      default_subcontractor_id = excluded.default_subcontractor_id,
      default_team_id = excluded.default_team_id,
      status = case
        when safety_worker_site_memberships.status = 'active' then 'active'
        else 'candidate'
      end,
      updated_by = excluded.updated_by,
      updated_at = now()
  returning * into v_membership;

  insert into public.safety_audit_logs (
    actor_user_id, action, target_type, target_id, project_id, construction_site_id, metadata
  ) values (
    v_actor::text,
    'worker.profile_for_site.create',
    'safety_worker_profiles',
    v_worker.id,
    p_project_id,
    p_construction_site_id::text,
    jsonb_build_object('membershipId', v_membership.id, 'workerKind', p_worker_kind)
  );

  return app_private.safety_workforce_detail_for_membership(v_membership.id);
end;
$$;


