--
-- Name: current_actor_hrm_visible_employee_ids(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.current_actor_hrm_visible_employee_ids(p_permission_code text) RETURNS TABLE(employee_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := public.current_app_user_id();
  v_has_global boolean := false;
  v_has_own boolean := false;
  v_has_direct_reports boolean := false;
begin
  if v_actor_user_id is null or p_permission_code not like 'hrm.%' then
    return;
  end if;

  v_has_global := app_private.has_governed_hrm_permission(
    v_actor_user_id, p_permission_code, 'global', '*'
  );
  if v_has_global then
    return query select employee.id from public.employees employee;
    return;
  end if;

  v_has_own := app_private.has_governed_hrm_permission(
    v_actor_user_id, p_permission_code, 'own', '*'
  );
  v_has_direct_reports := app_private.has_governed_hrm_permission(
    v_actor_user_id, p_permission_code, 'direct_reports', '*'
  );

  return query
  select employee.id
  from public.employees employee
  where (v_has_own and employee.user_id = v_actor_user_id)
     or (
       v_has_direct_reports
       and app_private.resolve_strict_direct_manager(employee.user_id) = v_actor_user_id
     );
end;
$$;


--
-- Name: current_user_can_receive_purchase_batch_v2(uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.current_user_can_receive_purchase_batch_v2(p_actor_user_id uuid, p_target_warehouse_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    public.is_admin()
    or public.is_module_admin('WMS')
    or app_private.current_user_is_global_wms_keeper()
    or app_private.current_user_is_wms_keeper_for(p_target_warehouse_id)
    or exists (
      select 1
      from public.users u
      where u.id = p_actor_user_id
        and u.is_active is not false
        and coalesce(u.account_status, 'ACTIVE') = 'ACTIVE'
        and u.role::text in ('ADMIN', 'WAREHOUSE_KEEPER', 'KEEPER')
        and (
          u.assigned_warehouse_id is null
          or u.assigned_warehouse_id = p_target_warehouse_id
        )
    ),
    false
  );
$$;


