--
-- Name: custom_material_storage_request_id(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.custom_material_storage_request_id(p_path text) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $_$
  select case
    when split_part(coalesce(p_path, ''), '/', 1) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then split_part(p_path, '/', 1)::uuid
    else null::uuid
  end;
$_$;


--
-- Name: daily_log_assignment_is_active(text, uuid, text[], text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.daily_log_assignment_is_active(p_log_id text, p_actor_user_id uuid, p_responsibilities text[], p_permission_code text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_actor_user_id is not null
    and exists (
      select 1
      from public.app_assignments assignment_row
      join public.users assignee on assignee.id = assignment_row.principal_id
      where assignment_row.subject_type = 'daily_log'
        and assignment_row.subject_id = p_log_id
        and assignment_row.principal_type = 'user'
        and assignment_row.principal_id = p_actor_user_id
        and assignment_row.status = 'active'
        and assignment_row.starts_at <= now()
        and (assignment_row.expires_at is null or assignment_row.expires_at > now())
        and coalesce(assignee.is_active, true)
        and assignment_row.responsibility = any(coalesce(p_responsibilities, '{}'::text[]))
        and (p_permission_code is null or assignment_row.permission_code = p_permission_code)
    );
$$;


--
-- Name: daily_log_can_delete(text, text, text, text, text, text, text, text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.daily_log_can_delete(p_project_id text, p_construction_site_id text, p_status text, p_summary_source_type text, p_created_by_id text, p_submitted_by_id text, p_submitted_by text, p_created_by text, p_user_id uuid DEFAULT public.current_app_user_id()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(p_status, 'draft') in ('draft', 'rejected')
    and (
      public.is_admin()
      or public.is_module_admin('DA')
      or (
        coalesce(p_summary_source_type, '') = 'member_contributions'
        and app_private.daily_log_has_action(
          p_project_id,
          p_construction_site_id,
          'project.daily_log.summarize',
          p_user_id
        )
      )
      or (
        coalesce(p_summary_source_type, '') <> 'member_contributions'
        and (
          app_private.daily_log_has_action(
            p_project_id,
            p_construction_site_id,
            'project.daily_log.delete_all',
            p_user_id
          )
          or (
            app_private.daily_log_is_owner(
              p_created_by_id,
              p_submitted_by_id,
              p_submitted_by,
              p_created_by,
              p_user_id
            )
            and app_private.daily_log_has_action(
              p_project_id,
              p_construction_site_id,
              'project.daily_log.delete_own',
              p_user_id
            )
          )
        )
      )
    );
$$;


