--
-- Name: daily_log_can_insert(text, text, text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.daily_log_can_insert(p_project_id text, p_construction_site_id text, p_summary_source_type text, p_user_id uuid DEFAULT public.current_app_user_id()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
