        p_user_id
      )
    else
      app_private.daily_log_has_action(
        p_project_id,
        p_construction_site_id,
        'project.daily_log.create',
        p_user_id
      )
  end;
$$;


--
-- Name: daily_log_can_select(text, text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.daily_log_can_select(p_project_id text, p_construction_site_id text, p_user_id uuid DEFAULT public.current_app_user_id()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app_private.daily_log_has_any_action(
    p_project_id,
    p_construction_site_id,
    array[
      'project.daily_log.view',
      'project.daily_log.create',
      'project.daily_log.edit_own',
      'project.daily_log.edit_all',
      'project.daily_log.delete_own',
      'project.daily_log.delete_all',
      'project.daily_log.submit',
      'project.daily_log.return',
      'project.daily_log.verify',
      'project.daily_log.approve',
      'project.daily_log.summarize'
    ],
    p_user_id
  );
$$;


--
-- Name: daily_log_contribution_can_submit(text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.daily_log_contribution_can_submit(p_project_id text, p_construction_site_id text, p_author_user_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.is_admin()
    or (
      p_author_user_id = public.current_app_user_id()::text
      and (
        app_private.project_user_has_permission(p_project_id, p_construction_site_id, 'submit')
        or app_private.project_user_has_permission(p_project_id, p_construction_site_id, 'edit')
        or not app_private.daily_log_scope_has_staff(p_project_id, p_construction_site_id)
      )
    );
$$;


--
-- Name: daily_log_contribution_can_update(text, text, text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.daily_log_contribution_can_update(p_project_id text, p_construction_site_id text, p_author_user_id text, p_status text, p_submitted_to_user_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.is_admin()
    or (
      p_author_user_id = public.current_app_user_id()::text
      and coalesce(p_status, 'draft') in ('draft', 'returned', 'submitted')
    )
    or (
      coalesce(p_status, 'draft') in ('submitted', 'included', 'returned')
      and (
        p_submitted_to_user_id = public.current_app_user_id()::text
        or app_private.project_user_has_permission(p_project_id, p_construction_site_id, 'verify')
        or app_private.project_user_has_permission(p_project_id, p_construction_site_id, 'approve')
      )
    )
    or (
      not app_private.daily_log_scope_has_staff(p_project_id, p_construction_site_id)
      and app_private.daily_log_contribution_can_view(p_project_id, p_construction_site_id, p_author_user_id, p_submitted_to_user_id)
    );
$$;


--
-- Name: daily_log_contribution_can_view(text, text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.daily_log_contribution_can_view(p_project_id text, p_construction_site_id text, p_author_user_id text, p_submitted_to_user_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.is_admin()
    or p_author_user_id = public.current_app_user_id()::text
    or p_submitted_to_user_id = public.current_app_user_id()::text
    or app_private.project_user_has_any_permission(p_project_id, p_construction_site_id)
    or not app_private.daily_log_scope_has_staff(p_project_id, p_construction_site_id);
$$;


--
-- Name: daily_log_contribution_transition_guard(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.daily_log_contribution_transition_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id text := public.current_app_user_id()::text;
  v_can_review boolean;
begin
  if public.is_admin() then
    return new;
  end if;

  v_can_review :=
    app_private.project_user_has_permission(old.project_id::text, old.construction_site_id::text, 'verify')
    or app_private.project_user_has_permission(old.project_id::text, old.construction_site_id::text, 'approve')
    or not app_private.daily_log_scope_has_staff(old.project_id::text, old.construction_site_id::text);

  if v_can_review then
    return new;
  end if;

  if old.author_user_id = v_user_id and old.status in ('draft', 'returned') and new.status in ('draft', 'submitted') then
    return new;
  end if;

  raise exception 'Báo cáo đã gửi/tổng hợp không thể chỉnh sửa trực tiếp.';
end;
$$;


--
-- Name: daily_log_has_action(text, text, text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.daily_log_has_action(p_project_id text, p_construction_site_id text, p_permission_code text, p_user_id uuid DEFAULT public.current_app_user_id()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case p_permission_code
    when 'project.daily_log.view' then app_private.project_actor_has_effective_room_action(
      p_user_id, p_project_id, p_construction_site_id, 'daily_log',
      'view'
    )
    when 'project.daily_log.create' then app_private.project_actor_has_effective_room_action(
      p_user_id, p_project_id, p_construction_site_id, 'daily_log',
      'edit'
    )
    when 'project.daily_log.edit_own' then app_private.project_actor_has_effective_room_action(
      p_user_id, p_project_id, p_construction_site_id, 'daily_log',
      'edit'
    )
    when 'project.daily_log.delete_own' then app_private.project_actor_has_effective_room_action(
      p_user_id, p_project_id, p_construction_site_id, 'daily_log',
      'delete'
    )
    when 'project.daily_log.submit' then app_private.project_actor_has_effective_room_action(
      p_user_id, p_project_id, p_construction_site_id, 'daily_log',
      'submit'
    )
    when 'project.daily_log.verify' then app_private.project_actor_has_effective_room_action(
      p_user_id, p_project_id, p_construction_site_id, 'daily_log',
      'verify'
    )
    when 'project.daily_log.summarize' then app_private.project_actor_has_effective_room_action(
      p_user_id, p_project_id, p_construction_site_id, 'daily_log',
      'verify'
    )
    when 'project.daily_log.approve' then app_private.project_actor_has_effective_room_action(
      p_user_id, p_project_id, p_construction_site_id, 'daily_log',
      'approve'
    )
    when 'project.daily_log.return' then
      app_private.project_actor_has_effective_room_action(
        p_user_id, p_project_id, p_construction_site_id, 'daily_log', 'verify'
      )
      or app_private.project_actor_has_effective_room_action(
        p_user_id, p_project_id, p_construction_site_id, 'daily_log', 'approve'
      )
      or (
        app_private.permission_hardening_flag('project_room_pbac_fallback_enabled')
        and exists (
          select 1
          from public.users actor
          where actor.id = p_user_id
            and coalesce(actor.is_active, true)
            and (
              actor.role = 'ADMIN'
              or exists (
                select 1
                from public.project_staff staff
                where staff.user_id = p_user_id::text
                  and staff.project_id = p_project_id
                  and staff.end_date is null
                  and (
                    nullif(p_construction_site_id, '') is null
                    or staff.construction_site_id is null
                    or staff.construction_site_id = p_construction_site_id
                  )
              )
            )
        )
        and app_private.project_has_permission_v2(
          p_project_id, p_construction_site_id, p_permission_code, p_user_id
        )
      )
    when 'project.daily_log.edit_all' then
      app_private.permission_hardening_flag('project_room_pbac_fallback_enabled')
      and exists (
        select 1
        from public.users actor
        where actor.id = p_user_id
          and coalesce(actor.is_active, true)
          and (
            actor.role = 'ADMIN'
            or exists (
              select 1
              from public.project_staff staff
              where staff.user_id = p_user_id::text
                and staff.project_id = p_project_id
                and staff.end_date is null
                and (
                  nullif(p_construction_site_id, '') is null
                  or staff.construction_site_id is null
                  or staff.construction_site_id = p_construction_site_id
                )
            )
          )
      )
      and app_private.project_has_permission_v2(
        p_project_id, p_construction_site_id, p_permission_code, p_user_id
      )
    when 'project.daily_log.delete_all' then
      app_private.permission_hardening_flag('project_room_pbac_fallback_enabled')
      and exists (
        select 1
        from public.users actor
        where actor.id = p_user_id
          and coalesce(actor.is_active, true)
          and (
            actor.role = 'ADMIN'
            or exists (
              select 1
              from public.project_staff staff
              where staff.user_id = p_user_id::text
                and staff.project_id = p_project_id
                and staff.end_date is null
                and (
                  nullif(p_construction_site_id, '') is null
                  or staff.construction_site_id is null
                  or staff.construction_site_id = p_construction_site_id
                )
            )
          )
      )
      and app_private.project_has_permission_v2(
        p_project_id, p_construction_site_id, p_permission_code, p_user_id
      )
    else false
  end;
$$;


--
-- Name: daily_log_has_any_action(text, text, text[], uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.daily_log_has_any_action(p_project_id text, p_construction_site_id text, p_permission_codes text[], p_user_id uuid DEFAULT public.current_app_user_id()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from unnest(coalesce(p_permission_codes, '{}'::text[])) as permission_code
    where app_private.daily_log_has_action(
      p_project_id,
      p_construction_site_id,
      permission_code,
      p_user_id
    )
  );
$$;


--
-- Name: daily_log_is_owner(text, text, text, text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.daily_log_is_owner(p_created_by_id text, p_submitted_by_id text, p_submitted_by text, p_created_by text, p_user_id uuid DEFAULT public.current_app_user_id()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_user_id is not null
    and p_user_id::text in (
      coalesce(p_created_by_id, ''),
      coalesce(p_submitted_by_id, ''),
      coalesce(p_submitted_by, ''),
      coalesce(p_created_by, '')
    );
$$;


--
-- Name: daily_log_scope_has_staff(text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.daily_log_scope_has_staff(p_project_id text, p_construction_site_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.project_staff ps
    where ps.end_date is null
      and (
        (p_project_id is not null and ps.project_id::text = p_project_id)
        or (p_construction_site_id is not null and ps.construction_site_id::text = p_construction_site_id)
      )
  );
$$;


--
-- Name: daily_log_step_touch(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.daily_log_step_touch() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.status = 'submitted' then
    new.ever_submitted := true;
    new.submitted_to_user_id := coalesce(new.submitted_to_user_id, new.requested_verifier_id);
    new.submitted_to_name := coalesce(new.submitted_to_name, new.requested_verifier_name);
    new.submitted_to_permission := coalesce(new.submitted_to_permission, 'verify');
  elsif new.status = 'rejected' then
    new.submitted_to_user_id := coalesce(new.created_by_id, new.submitted_by_id, new.submitted_by);
    new.submitted_to_name := null;
    new.submitted_to_permission := 'edit';
    new.submission_note := coalesce(new.rejection_reason, new.submission_note);
  elsif new.status = 'verified' then
    new.submitted_to_user_id := null;
    new.submitted_to_name := null;
    new.submitted_to_permission := null;
    new.submission_note := null;
  end if;

  return new;
end;
$$;


--
-- Name: daily_log_target_permission(text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.daily_log_target_permission(p_summary_source_type text, p_submitted_to_permission text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_summary_source_type = 'member_contributions'
      or p_submitted_to_permission = 'approve'
    then 'project.daily_log.approve'
    else 'project.daily_log.verify'
  end;
$$;


--
-- Name: daily_log_transition_context_enabled(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.daily_log_transition_context_enabled() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select current_setting('app.daily_log_transition_context', true) = 'on';
$$;


--
-- Name: daily_log_user_can_receive_assignment(text, text, text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.daily_log_user_can_receive_assignment(p_project_id text, p_construction_site_id text, p_permission_code text, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_user_id is not null
    and app_private.project_user_has_room_action(
      p_user_id,
      p_project_id,
      p_construction_site_id,
      'daily_log',
      case p_permission_code
        when 'project.daily_log.verify' then 'verify'
        when 'project.daily_log.approve' then 'approve'
        else null
      end
    );
$$;


--
-- Name: deactivate_permission_quick_template_impl(uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.deactivate_permission_quick_template_impl(p_template_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid;
  v_reason text := btrim(coalesce(p_reason, ''));
  v_before jsonb;
  v_after jsonb;
begin
  v_actor_user_id := app_private.assert_authorization_permission('system.authorization.manage_grants');

  if p_template_id is null then
    raise exception 'Quick template id required'
      using errcode = '22023';
  end if;

  if char_length(v_reason) < 10 then
    raise exception 'Quick template deactivation reason required'
      using errcode = '22023';
  end if;

  select jsonb_build_object(
    'id', template.id,
    'code', template.code,
    'name', template.name,
    'description', template.description,
    'isActive', template.is_active,
    'permissionCodes', coalesce(items.permission_codes, '[]'::jsonb)
  )
  into v_before
  from public.permission_quick_templates template
  left join lateral (
    select jsonb_agg(item.permission_code order by item.sort_order, item.permission_code) as permission_codes
    from public.permission_quick_template_items item
    where item.template_id = template.id
  ) items on true
  where template.id = p_template_id;

  if v_before is null then
    raise exception 'Quick template does not exist'
      using errcode = '23503';
  end if;

  update public.permission_quick_templates
  set is_active = false,
      updated_by = v_actor_user_id,
      updated_at = now()
  where id = p_template_id;

  v_after := jsonb_set(v_before, '{isActive}', 'false'::jsonb, true);

  insert into public.permission_audit_events (
    actor_user_id,
    event_type,
    before_grants,
    after_grants,
    metadata
  ) values (
    v_actor_user_id,
    'permission_quick_template_deactivated',
    v_before,
    v_after,
    jsonb_build_object(
      'reason', v_reason,
      'templateId', p_template_id
    )
  );
end;
$$;


--
-- Name: project_staff; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.project_staff (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    construction_site_id text,
    user_id text NOT NULL,
