    start_date date DEFAULT CURRENT_DATE,
    end_date date,
    note text,
    sort_order integer DEFAULT 0,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    project_id text
);


--
-- Name: TABLE project_staff; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.project_staff IS 'Phân bổ nhân sự dự án: ai ở vị trí gì tại công trường nào';


--
-- Name: deactivate_project_staff_scoped_grants(public.project_staff); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.deactivate_project_staff_scoped_grants(p_staff public.project_staff) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_target_user_id uuid;
  v_scope_type text := app_private.project_staff_scope_type(p_staff.construction_site_id);
  v_scope_id text := app_private.project_staff_scope_id(p_staff.project_id, p_staff.construction_site_id);
begin
  update public.project_staff_permissions
  set is_active = false
  where staff_id = p_staff.id
    and coalesce(is_active, true);

  if p_staff.user_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return;
  end if;

  v_target_user_id := p_staff.user_id::uuid;

  update public.user_permission_grants
  set is_active = false,
      updated_at = now()
  where user_id = v_target_user_id
    and permission_code like 'project.%'
    and scope_type = v_scope_type
    and scope_id = v_scope_id
    and coalesce(is_active, false);
end;
$_$;


--
-- Name: deactivate_request_template(uuid, timestamp with time zone); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.deactivate_request_template(p_request_template_id uuid, p_expected_updated_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_template public.request_templates%rowtype;
begin
  if v_actor is null or not app_private.request_user_can_manage(v_actor) then
    raise exception using errcode = '42501', message = 'REQUEST_TEMPLATE_FORBIDDEN';
  end if;
  if p_expected_updated_at is null then
    raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_EXPECTED_UPDATED_AT_REQUIRED';
  end if;
  select * into v_template from public.request_templates where id = p_request_template_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'REQUEST_TEMPLATE_NOT_FOUND'; end if;
  if v_template.updated_at <> p_expected_updated_at then
    raise exception using errcode = '40001', message = 'CONFLICT';
  end if;
  update public.request_templates set lifecycle_status = 'DEACTIVATED' where id = v_template.id;
  return app_private.request_template_summary(v_template.id);
end;
$$;


--
-- Name: decide_material_po_batch(uuid, text, text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.decide_material_po_batch(p_delivery_batch_id uuid, p_decision text, p_note text, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := coalesce(p_actor_user_id, public.current_app_user_id());
  v_batch public.purchase_order_delivery_batches%rowtype;
  v_po public.purchase_orders%rowtype;
begin
  if public.current_app_user_id() is null or v_actor <> public.current_app_user_id() then
    raise exception 'Người thực hiện lệnh không hợp lệ.' using errcode = '42501';
  end if;
  if p_decision not in ('revision_requested', 'rejected') then
    raise exception 'Quyết định duyệt không hợp lệ.' using errcode = '22023';
  end if;

  select * into v_batch
  from public.purchase_order_delivery_batches
  where id = p_delivery_batch_id
  for update;
  if not found then
    raise exception 'Không tìm thấy đợt giao.' using errcode = '22023';
  end if;
  select * into v_po from public.purchase_orders where id = v_batch.purchase_order_id;
  perform app_private.assert_project_permission_room_action(
    v_po.project_id, v_po.construction_site_id, 'material_po', 'approve', v_actor
  );
  if not public.is_admin() and v_batch.approval_assignee_user_id is distinct from v_actor then
    raise exception 'Chỉ người được giao duyệt đợt mới có thể trả lại hoặc từ chối.' using errcode = '42501';
  end if;

  if coalesce(v_batch.approval_status, 'draft') <> 'pending_approval'
     or v_batch.wms_transaction_id is not null then
    raise exception 'Chỉ xử lý đợt đang chờ duyệt.' using errcode = '22023';
  end if;

  update public.purchase_order_delivery_batches
  set approval_status = p_decision,
      approval_decided_by = v_actor,
      approval_decided_at = now(),
      approval_decision_note = nullif(trim(coalesce(p_note, '')), ''),
      updated_at = now()
  where id = v_batch.id;

  return jsonb_build_object(
    'deliveryBatchId', v_batch.id,
    'approvalStatus', p_decision
  );
end;
$$;


--
-- Name: delete_project_category(text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.delete_project_category(p_category_kind text, p_category_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_table text := app_private.project_category_table_name(p_category_kind);
  v_result jsonb;
begin
  if v_table is null then
    raise exception 'Invalid project category kind: %', p_category_kind
      using errcode = '22023';
  end if;

  if not app_private.can_manage_project_master(null, 'project.master.manage_categories') then
    raise exception 'Not allowed to delete project categories'
      using errcode = '42501';
  end if;

  execute format(
    'delete from public.%I where id = $1 returning to_jsonb(%I.*)',
    v_table,
    v_table
  )
  into v_result
  using p_category_id;

  if v_result is null then
    raise exception 'Project category not found: % %', p_category_kind, p_category_id
      using errcode = 'P0002';
  end if;

  return v_result;
end;
$_$;


--
-- Name: delete_project_gantt_task_tree_impl(uuid, text, text, text, bigint); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.delete_project_gantt_task_tree_impl(p_request_id uuid, p_project_id text, p_construction_site_id text, p_task_id text, p_expected_row_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid;
  v_site_id text := nullif(btrim(coalesce(p_construction_site_id, '')), '');
  v_payload_hash text;
  v_replay jsonb;
  v_result jsonb;
  v_task_ids text[];
  v_blockers jsonb;
begin
  v_actor_user_id := app_private.assert_project_gantt_action(p_project_id, v_site_id, 'delete');
  v_payload_hash := md5(jsonb_build_object(
    'projectId', p_project_id,
    'constructionSiteId', v_site_id,
    'taskId', p_task_id,
    'expectedRowVersion', p_expected_row_version
  )::text);
  v_replay := app_private.begin_project_gantt_command(
    v_actor_user_id, p_request_id, 'delete_project_gantt_task_tree', v_payload_hash
  );
  if v_replay is not null then return v_replay; end if;

  if not exists (
    select 1 from public.project_tasks task
    where task.id = p_task_id
      and task.project_id = p_project_id
      and task.construction_site_id is not distinct from v_site_id
  ) then
    if exists (select 1 from public.project_tasks task where task.id = p_task_id) then
      raise exception 'GANTT_SCOPE_MISMATCH' using errcode = '23514';
    end if;
    raise exception 'GANTT_TASK_NOT_FOUND' using errcode = 'P0002';
  end if;

  with recursive tree as (
    select task.id from public.project_tasks task where task.id = p_task_id
    union all
    select child.id from public.project_tasks child
    join tree parent on child.parent_id = parent.id
    where child.project_id = p_project_id
      and child.construction_site_id is not distinct from v_site_id
  )
  select array_agg(tree.id order by tree.id) into v_task_ids from tree;

  perform task.id
  from public.project_tasks task
  where task.id = any(v_task_ids)
  order by task.id
  for update;

  if not exists (
    select 1 from public.project_tasks task
    where task.id = p_task_id and task.row_version = p_expected_row_version
  ) then
    raise exception 'GANTT_STALE_VERSION' using errcode = '40001';
  end if;

  select jsonb_strip_nulls(jsonb_build_object(
    'completionRequests', nullif((select count(*) from public.project_task_completion_requests item where item.task_id = any(v_task_ids)), 0),
    'dailyProgress', nullif((select count(*) from public.project_daily_task_progress item where item.task_id = any(v_task_ids)), 0),
    'weeklyProgress', nullif((select count(*) from public.project_weekly_task_progress item where item.task_id = any(v_task_ids)), 0),
    'dailyLogVolumes', nullif((select count(*) from public.daily_log_volumes item where item.task_id = any(v_task_ids)), 0),
    'delayEvents', nullif((select count(*) from public.project_delay_events item where item.task_id = any(v_task_ids)), 0),
    'quantityAcceptances', nullif((select count(*) from public.quantity_acceptance_items item where item.task_id = any(v_task_ids)), 0)
  )) into v_blockers;

  if v_blockers <> '{}'::jsonb then
    insert into public.permission_audit_events (
      actor_user_id, event_type, before_grants, after_grants, metadata
    ) values (
      v_actor_user_id, 'gantt_delete_blocked', '[]'::jsonb, '[]'::jsonb,
      jsonb_build_object(
        'room_code', 'gantt', 'project_id', p_project_id,
        'construction_site_id', v_site_id, 'task_id', p_task_id,
        'task_ids', to_jsonb(v_task_ids), 'blockers', v_blockers
      )
    );

    v_result := jsonb_build_object(
      'ok', false,
      'requestId', p_request_id,
      'replayed', false,
      'errorCode', 'GANTT_DELETE_BLOCKED',
      'blockers', v_blockers
    );
    return app_private.finish_project_gantt_command(v_actor_user_id, p_request_id, v_result);
  end if;

  update public.project_tasks task
  set dependencies = coalesce((
    select jsonb_agg(dependency)
    from jsonb_array_elements(coalesce(task.dependencies, '[]'::jsonb)) dependency
    where not (dependency ->> 'taskId' = any(v_task_ids))
      and not (dependency ->> 'task_id' = any(v_task_ids))
  ), '[]'::jsonb)
  where task.project_id = p_project_id
    and task.construction_site_id is not distinct from v_site_id
    and not task.id = any(v_task_ids)
    and exists (
      select 1 from jsonb_array_elements(coalesce(task.dependencies, '[]'::jsonb)) dependency
      where dependency ->> 'taskId' = any(v_task_ids)
        or dependency ->> 'task_id' = any(v_task_ids)
    );

  delete from public.task_contract_items link where link.task_id = any(v_task_ids);
  delete from public.project_tasks task where task.id = any(v_task_ids);

  v_result := jsonb_build_object(
    'ok', true,
    'requestId', p_request_id,
    'replayed', false,
    'deletedTaskIds', to_jsonb(v_task_ids)
  );
  return app_private.finish_project_gantt_command(v_actor_user_id, p_request_id, v_result);
end;
$$;


--
-- Name: delete_quality_checklist_impl(uuid, text, text, uuid, timestamp with time zone); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.delete_quality_checklist_impl(p_request_id uuid, p_project_id text, p_construction_site_id text, p_checklist_id uuid, p_expected_updated_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_old public.quality_checklists%rowtype;
  v_replay jsonb;
  v_result jsonb;
begin
  v_actor := app_private.assert_quality_action(p_project_id, p_construction_site_id, 'delete');
  v_replay := app_private.begin_quality_command(v_actor, p_request_id,
    'delete_quality_checklist', md5(jsonb_build_object(
      'projectId', p_project_id, 'constructionSiteId', p_construction_site_id,
      'checklistId', p_checklist_id, 'expectedUpdatedAt', p_expected_updated_at
    )::text));
  if v_replay is not null then return v_replay; end if;
  select * into v_old from public.quality_checklists item
  where item.id = p_checklist_id for update;
  if not found or v_old.project_id::text is distinct from p_project_id
    or v_old.construction_site_id::text is distinct from p_construction_site_id then
    raise exception 'QUALITY_SCOPE_MISMATCH' using errcode = '23514';
  end if;
  if v_old.updated_at is distinct from p_expected_updated_at then
    raise exception 'QUALITY_STALE_VERSION' using errcode = '40001';
  end if;
  if v_old.status <> 'draft' then
    raise exception 'QUALITY_INVALID_TRANSITION' using errcode = '23514';
  end if;
  insert into public.audit_trail (
    table_name, record_id, action, old_data, user_id, user_name,
    module, description, context
  ) values (
    'quality_checklists', v_old.id::text, 'DELETE', to_jsonb(v_old),
    v_actor::text, v_actor::text, 'quality', 'Xóa hồ sơ chất lượng',
    jsonb_build_object('requestId', p_request_id, 'roomCode', 'quality')
  );
  delete from public.quality_checklists item where item.id = p_checklist_id;
  v_result := jsonb_build_object('ok', true, 'requestId', p_request_id,
    'replayed', false, 'checklist', null);
  return app_private.finish_quality_command(v_actor, p_request_id, v_result);
end;
$$;


--
-- Name: delete_work_group(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.delete_work_group(p_work_group_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_result jsonb;
begin
  if not app_private.can_manage_work_groups() then
    raise exception 'Not allowed to delete work groups'
      using errcode = '42501';
  end if;

  delete from public.work_groups
  where id = p_work_group_id
  returning to_jsonb(public.work_groups.*)
  into v_result;

  if v_result is null then
    raise exception 'Work group not found: %', p_work_group_id
      using errcode = 'P0002';
  end if;

  return v_result;
end;
$$;


--
-- Name: deliver_request_notification(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.deliver_request_notification(p_outbox_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_outbox app_private.request_notification_outbox%rowtype;
  v_notification_id uuid;
  v_request public.request_instances%rowtype;
  v_title text;
  v_message text;
begin
  perform app_private.require_request_notification_worker();

  select *
    into v_outbox
  from app_private.request_notification_outbox
  where id = p_outbox_id
  for update;

  if not found or v_outbox.status = 'DELIVERED' then
    return jsonb_build_object('delivered', false);
  end if;

  if v_outbox.status <> 'PROCESSING' then
    raise exception using errcode = 'P0001', message = 'REQUEST_NOTIFICATION_NOT_CLAIMED';
  end if;

  select *
    into v_request
  from public.request_instances
  where id = v_outbox.request_id;

  if not found then
    raise exception using errcode = 'P0001', message = 'REQUEST_NOTIFICATION_REQUEST_MISSING';
  end if;

  v_title := case v_outbox.event_type
    when 'REQUEST_SUBMITTED' then 'Đề xuất mới cần duyệt'
    when 'REQUEST_APPROVAL_REQUIRED' then 'Bạn có đề xuất cần duyệt'
    when 'REQUEST_REASSIGNED' then 'Đề xuất được chuyển người duyệt'
    when 'REQUEST_RETURNED' then 'Đề xuất đã được trả lại'
    when 'REQUEST_APPROVED' then 'Đề xuất đã được chấp thuận'
    when 'REQUEST_REJECTED' then 'Đề xuất đã bị từ chối'
    else 'Cập nhật đề xuất'
  end;

  v_message := coalesce(v_outbox.payload ->> 'requestCode', v_request.code)
    || ' · ' || coalesce(v_outbox.payload ->> 'title', v_request.title);

  insert into public.notifications (
    user_id,
    type,
    category,
    title,
    message,
    link,
    severity,
    source_type,
    source_id,
    priority,
    push_enabled,
    action_url,
    entity_type,
    entity_id,
    metadata
  )
  values (
    v_outbox.recipient_user_id,
    'info',
    'request',
    v_title,
    v_message,
    '/rq/' || v_outbox.request_id::text,
    'info',
    'request_instance',
    v_outbox.request_id::text,
    'normal',
    true,
    '/rq/' || v_outbox.request_id::text,
    'request_instance',
    v_outbox.request_id,
    jsonb_build_object(
      'requestInstanceId', v_outbox.request_id,
      'requestCode', v_request.code,
      'eventType', v_outbox.event_type,
      'eventKey', v_outbox.event_key
    )
  )
  returning id into v_notification_id;

  update app_private.request_notification_outbox
  set status = 'DELIVERED',
      delivered_at = now(),
      locked_at = null,
      last_error = null
  where id = v_outbox.id;

  return jsonb_build_object('delivered', true, 'notificationId', v_notification_id);
end;
$$;


--
-- Name: deliver_vehicle_notification(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.deliver_vehicle_notification(p_outbox_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_outbox app_private.vehicle_booking_notification_outbox%rowtype;
  v_notification_id uuid;
begin
  perform app_private.require_vehicle_notification_worker();

  select * into v_outbox
  from app_private.vehicle_booking_notification_outbox
  where id = p_outbox_id
  for update;

  if not found or v_outbox.status = 'DELIVERED' then
    return jsonb_build_object('delivered', false);
  end if;
  if v_outbox.status <> 'PROCESSING' then
    raise exception using errcode = 'P0001', message = 'VEHICLE_NOTIFICATION_NOT_CLAIMED';
  end if;

  v_notification_id := app_private.insert_vehicle_booking_notification(v_outbox.id);

  update app_private.vehicle_booking_notification_outbox
  set status = 'DELIVERED', delivered_at = now(), locked_at = null,
      last_error = null, updated_at = now()
  where id = v_outbox.id;

  return jsonb_build_object('delivered', true, 'notificationId', v_notification_id);
end;
$$;


--
-- Name: direct_permission_state_for_user(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.direct_permission_state_for_user(p_user_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'permissionCode', grant_row.permission_code,
        'scopeType', grant_row.scope_type,
        'scopeId', grant_row.scope_id,
        'expiresAt', grant_row.expires_at
      )
      order by grant_row.permission_code, grant_row.scope_type,
        grant_row.scope_id, grant_row.expires_at
    ),
    '[]'::jsonb
  )
  from public.user_permission_grants grant_row
  where grant_row.user_id = p_user_id
    and grant_row.is_active
    and (grant_row.expires_at is null or grant_row.expires_at > now());
$$;


--
-- Name: duplicate_request_template(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.duplicate_request_template(p_request_template_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_source_template public.request_templates%rowtype;
  v_source_version public.request_template_versions%rowtype;
  v_target_template public.request_templates%rowtype;
  v_target_version public.request_template_versions%rowtype;
  v_base_name text;
  v_copy_name text;
  v_suffix integer := 1;
begin
  if v_actor is null or not app_private.request_user_can_manage(v_actor) then
    raise exception using errcode = '42501', message = 'REQUEST_TEMPLATE_FORBIDDEN';
  end if;

  select * into v_source_template
  from public.request_templates
  where id = p_request_template_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'REQUEST_TEMPLATE_NOT_FOUND';
  end if;

  select * into v_source_version
  from public.request_template_versions version
  where version.request_template_id = v_source_template.id
  order by
    case version.status
      when 'DRAFT' then 1
      when 'PUBLISHED' then 2
      when 'SUPERSEDED' then 3
      else 4
    end,
    version.version_number desc
  limit 1;
  if not found then
    raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_VERSION_REQUIRED';
  end if;

  v_base_name := v_source_template.name || ' - Bản sao';
  perform pg_advisory_xact_lock(hashtextextended(lower(v_base_name), 0));
  v_copy_name := v_base_name;
  while exists (
    select 1
    from public.request_templates existing_template
    where lower(existing_template.name) = lower(v_copy_name)
  ) loop
    v_suffix := v_suffix + 1;
    v_copy_name := format('%s (%s)', v_base_name, v_suffix);
  end loop;

  insert into public.request_templates(
    name, description, lifecycle_status, current_version_id, created_by
  ) values (
    v_copy_name,
    coalesce(v_source_template.description, ''),
    'DRAFT',
    null,
    v_actor
  ) returning * into v_target_template;

  insert into public.request_template_versions(
    request_template_id, version_number, form_schema, usage_scope,
    flow_mode, completion_policy, request_sla_hours, print_config,
    notification_config, status, created_by
  ) values (
    v_target_template.id,
    1,
    v_source_version.form_schema,
    v_source_version.usage_scope,
    v_source_version.flow_mode,
    v_source_version.completion_policy,
    v_source_version.request_sla_hours,
    v_source_version.print_config,
    v_source_version.notification_config,
    'DRAFT',
    v_actor
  ) returning * into v_target_version;

  insert into public.request_approval_blocks(
    request_template_version_id, block_key, name, sort_order, approver_source,
    fixed_user_ids, minimum_dynamic_approvers, sla_hours, is_required
  )
  select v_target_version.id, block_key, name, sort_order, approver_source,
    fixed_user_ids, minimum_dynamic_approvers, sla_hours, is_required
  from public.request_approval_blocks
  where request_template_version_id = v_source_version.id;

  insert into public.request_template_watchers(request_template_version_id, user_id)
  select v_target_version.id, user_id
  from public.request_template_watchers
  where request_template_version_id = v_source_version.id
  on conflict do nothing;

  insert into public.request_print_templates(
    request_template_version_id, name, file_name, storage_path,
    validation_status, placeholder_schema
  )
  select v_target_version.id, name, file_name, storage_path,
    validation_status, placeholder_schema
  from public.request_print_templates
  where request_template_version_id = v_source_version.id;

  return jsonb_build_object(
    'id', v_target_template.id,
    'draftVersionId', v_target_version.id,
    'status', v_target_version.status,
    'versionNumber', v_target_version.version_number,
    'updatedAt', v_target_template.updated_at,
    'payload', app_private.request_template_draft_payload(v_target_version.id)
  );
end;
$$;


--
-- Name: emit_user_authorization_refresh(uuid, text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.emit_user_authorization_refresh(p_user_id uuid, p_event_type text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_event_id uuid;
begin
  if p_event_type not in (
    'APPLICATION_MEMBERSHIP_GRANTED',
    'APPLICATION_MEMBERSHIP_REVOKED'
  ) then
    raise exception 'Unsupported user authorization refresh event type'
      using errcode = '22023';
  end if;

  insert into public.user_authorization_refresh_events (
    user_id,
    event_type,
    metadata
  )
  values (
    p_user_id,
    p_event_type,
    coalesce(p_metadata, '{}'::jsonb)
  )
  returning id into v_event_id;

  return v_event_id;
end;
$$;


--
-- Name: hrm_attendance; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hrm_attendance (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    "employeeId" uuid NOT NULL,
    date text NOT NULL,
    status text DEFAULT 'present'::text NOT NULL,
    "checkIn" text,
    "checkOut" text,
    "overtimeHours" numeric DEFAULT 0,
    "constructionSiteId" text,
    note text,
    "checkInPhoto" text,
    "checkOutPhoto" text,
    "checkInLat" double precision,
    "checkInLng" double precision,
    "checkOutLat" double precision,
    "checkOutLng" double precision,
    "locationName" text,
    "locationType" text,
    "isOutOfRange" boolean DEFAULT false,
    "createdAt" timestamp with time zone DEFAULT now(),
    events jsonb DEFAULT '[]'::jsonb NOT NULL,
    "eventCount" integer DEFAULT 0 NOT NULL,
    "approvalStatus" text DEFAULT 'approved'::text NOT NULL,
    "approvedBy" text,
    "approvedAt" timestamp with time zone,
    "submittedToUserId" text,
    CONSTRAINT hrm_attendance_event_count_check CHECK (((jsonb_typeof(events) = 'array'::text) AND (jsonb_array_length(events) = "eventCount") AND (("eventCount" >= 0) AND ("eventCount" <= 6))))
);


--
-- Name: employee_camera_checkin_v1(text, uuid, text, text, double precision, double precision, text, text, text, integer, boolean, text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.employee_camera_checkin_v1(p_action text, p_employee_id uuid, p_work_date text, p_event_time text, p_lat double precision DEFAULT NULL::double precision, p_lng double precision DEFAULT NULL::double precision, p_location_type text DEFAULT NULL::text, p_location_id text DEFAULT NULL::text, p_location_name text DEFAULT NULL::text, p_distance_m integer DEFAULT NULL::integer, p_in_range boolean DEFAULT NULL::boolean, p_image_url text DEFAULT NULL::text, p_device_info jsonb DEFAULT '{}'::jsonb) RETURNS public.hrm_attendance
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app_private', 'pg_temp'
    AS $_$
declare
  v_row public.hrm_attendance;
  v_existing public.hrm_attendance;
  v_action text := lower(trim(coalesce(p_action, '')));
  v_app_user_id uuid := public.current_app_user_id();
  v_event jsonb;
  v_events jsonb;
  v_event_count integer;
  v_location_name text;
  v_location_note text;
  v_is_out_of_range boolean := coalesce(not p_in_range, false);
  v_check_in_is_earliest boolean := false;
  v_check_out_is_latest boolean := false;
begin
  if auth.uid() is null then
    raise exception 'Phiên đăng nhập Supabase không hợp lệ.'
      using errcode = '28000';
  end if;

  if v_app_user_id is null then
    raise exception 'Không tìm thấy tài khoản ứng dụng tương ứng.'
      using errcode = '28000';
  end if;

  if v_action not in ('check_in', 'check_out') then
    raise exception 'Hành động chấm công không hợp lệ: %', coalesce(p_action, '<null>')
      using errcode = '22023';
  end if;

  if p_employee_id is null then
    raise exception 'Thiếu employee_id.'
      using errcode = '22023';
  end if;

  if not app_private.has_governed_hrm_permission(v_app_user_id, 'hrm.attendance.edit') and not app_private.hrm_employee_is_current_user(p_employee_id::text) then
    raise exception 'Bạn không có quyền chấm công cho nhân viên này.'
      using errcode = '42501';
  end if;

  if nullif(trim(coalesce(p_work_date, '')), '') is null then
    raise exception 'Thiếu ngày chấm công.'
      using errcode = '22023';
  end if;

  if nullif(trim(coalesce(p_event_time, '')), '') is null then
    raise exception 'Thiếu giờ chấm công.'
      using errcode = '22023';
  end if;

  if p_event_time !~ '^\d{2}:\d{2}$' then
    raise exception 'Giờ chấm công phải có định dạng HH:mm.'
      using errcode = '22023';
  end if;

  if p_lat is not null and (p_lat < -90 or p_lat > 90) then
    raise exception 'Latitude không hợp lệ: %', p_lat
      using errcode = '22023';
  end if;

  if p_lng is not null and (p_lng < -180 or p_lng > 180) then
    raise exception 'Longitude không hợp lệ: %', p_lng
      using errcode = '22023';
  end if;

  if p_location_type is not null and p_location_type not in ('construction_site', 'office') then
    raise exception 'Loại địa điểm không hợp lệ: %', p_location_type
      using errcode = '22023';
  end if;

  v_location_name := app_private.hrm_location_name(p_location_type, p_location_id, p_location_name);

  if p_location_type is not null and p_location_id is not null and v_location_name is null then
    raise exception 'Không tìm thấy địa điểm chấm công.'
      using errcode = '22023';
  end if;

  v_location_note := concat_ws(
    ' | ',
    'event=' || v_action || ':' || p_event_time,
    case when p_distance_m is not null then 'distance=' || p_distance_m::text || 'm' end,
    case when p_in_range is not null then 'in_range=' || p_in_range::text end
  );

  v_event := jsonb_build_object(
    'action', v_action,
    'time', p_event_time,
    'recorded_at', now(),
    'source', 'camera',
    'lat', p_lat,
    'lng', p_lng,
    'location_type', p_location_type,
    'location_id', p_location_id,
    'location_name', v_location_name,
    'distance_m', p_distance_m,
    'in_range', p_in_range,
    'is_out_of_range', v_is_out_of_range,
    'image_url', p_image_url,
    'device_info', coalesce(p_device_info, '{}'::jsonb)
  );

  select *
  into v_existing
  from public.hrm_attendance
  where "employeeId" = p_employee_id
    and date = p_work_date
  for update;

  if v_existing.id is null then
    if v_action = 'check_out' then
      raise exception 'Chưa có check-in ngày %, không thể check-out.', p_work_date
        using errcode = '23514';
    end if;

    insert into public.hrm_attendance (
      id,
      "employeeId",
      date,
      status,
      "checkIn",
      "checkOut",
      "checkInPhoto",
      "checkOutPhoto",
      "checkInLat",
      "checkInLng",
      "checkOutLat",
      "checkOutLng",
      "constructionSiteId",
      "locationName",
      "locationType",
      "isOutOfRange",
      note,
      "events",
      "eventCount",
      "approvalStatus",
      "submittedToUserId",
      "createdAt"
    )
    values (
      gen_random_uuid(),
      p_employee_id,
      p_work_date,
      'present',
      p_event_time,
      null,
      p_image_url,
      null,
      p_lat,
      p_lng,
      null,
      null,
      case when p_location_type = 'construction_site' then p_location_id else null end,
      v_location_name,
      p_location_type,
      v_is_out_of_range,
      nullif(v_location_note, ''),
      jsonb_build_array(v_event),
      1,
      'approved',
      app_private.hrm_location_manager_id(p_location_type, p_location_id),
      now()
    )
    returning * into v_row;

    return v_row;
  end if;

  v_events := case
    when jsonb_typeof(coalesce(v_existing."events", '[]'::jsonb)) = 'array'
      then coalesce(v_existing."events", '[]'::jsonb)
    else '[]'::jsonb
  end;
  v_event_count := jsonb_array_length(v_events);

  if v_event_count >= 6 then
    raise exception 'Hệ thống chỉ ghi nhận tối đa 6 lần chấm công trong ngày.'
      using errcode = '23514';
  end if;

  v_check_in_is_earliest := v_action = 'check_in'
    and (v_existing."checkIn" is null or p_event_time < v_existing."checkIn");

  v_check_out_is_latest := v_action = 'check_out'
    and (v_existing."checkOut" is null or p_event_time > v_existing."checkOut");

  update public.hrm_attendance
    set status = case when status = 'absent' then 'present' else status end,
        "checkIn" = case
          when v_action = 'check_in' and ("checkIn" is null or p_event_time < "checkIn") then p_event_time
          else "checkIn"
        end,
        "checkOut" = case
          when v_action = 'check_out' and ("checkOut" is null or p_event_time > "checkOut") then p_event_time
          else "checkOut"
        end,
        "checkInPhoto" = case
          when v_check_in_is_earliest then p_image_url
          else "checkInPhoto"
        end,
        "checkOutPhoto" = case
          when v_check_out_is_latest then p_image_url
          else "checkOutPhoto"
        end,
        "checkInLat" = case
          when v_check_in_is_earliest then p_lat
          else "checkInLat"
        end,
        "checkInLng" = case
          when v_check_in_is_earliest then p_lng
          else "checkInLng"
        end,
        "checkOutLat" = case
          when v_check_out_is_latest then p_lat
          else "checkOutLat"
        end,
        "checkOutLng" = case
          when v_check_out_is_latest then p_lng
          else "checkOutLng"
        end,
        "constructionSiteId" = coalesce(case when p_location_type = 'construction_site' then p_location_id end, "constructionSiteId"),
        "locationName" = coalesce(v_location_name, "locationName"),
        "locationType" = coalesce(p_location_type, "locationType"),
        "isOutOfRange" = coalesce("isOutOfRange", false) or v_is_out_of_range,
        note = left(concat_ws(E'\n', nullif(note, ''), nullif(v_location_note, '')), 1000),
        "events" = v_events || jsonb_build_array(v_event),
        "eventCount" = v_event_count + 1,
        "submittedToUserId" = coalesce("submittedToUserId", app_private.hrm_location_manager_id(p_location_type, p_location_id))
  where id = v_existing.id
  returning * into v_row;

  return v_row;
end;
$_$;


--
-- Name: end_project_staff_assignment(uuid, date); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.end_project_staff_assignment(p_staff_id uuid, p_end_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_staff public.project_staff%rowtype;
  v_result public.project_staff%rowtype;
begin
  select *
  into v_staff
  from public.project_staff
  where id = p_staff_id;

  if v_staff.id is null then
    raise exception 'Project staff row does not exist: %', p_staff_id
      using errcode = 'P0002';
  end if;

  if not app_private.can_manage_project_staff_assignment(v_staff.project_id, v_staff.construction_site_id) then
    raise exception 'Not allowed to end this project staff assignment'
      using errcode = '42501';
  end if;

  update public.project_staff
  set end_date = coalesce(p_end_date, current_date),
      updated_at = now()
  where id = p_staff_id
  returning *
  into v_result;

  perform app_private.deactivate_project_staff_scoped_grants(v_result);

  insert into public.permission_audit_events (
    actor_user_id,
    target_user_id,
    event_type,
    metadata
  )
  values (
    public.current_app_user_id(),
    case when v_result.user_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then v_result.user_id::uuid else null end,
    'end_project_staff_assignment',
    jsonb_build_object(
      'staff_id', p_staff_id,
      'project_id', v_result.project_id,
      'construction_site_id', v_result.construction_site_id,
      'end_date', v_result.end_date
    )
  );

  return to_jsonb(v_result);
end;
$_$;


--
-- Name: end_safety_worker_assignment(uuid, timestamp with time zone, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.end_safety_worker_assignment(p_assignment_id uuid, p_ended_at timestamp with time zone, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_assignment public.safety_project_assignments%rowtype;
  v_membership public.safety_worker_site_memberships%rowtype;
  v_worker public.safety_worker_profiles%rowtype;
begin
  if p_ended_at is null or nullif(trim(p_reason), '') is null then
    raise exception 'SAFETY_INVALID_RPC_PAYLOAD: end time and reason are required'
      using errcode = '22023';
  end if;

  select assignment.*
  into v_assignment
  from public.safety_project_assignments assignment
  where assignment.id = p_assignment_id;

  select membership.*
  into v_membership
  from public.safety_worker_site_memberships membership
  where membership.id = v_assignment.membership_id;

  if v_assignment.id is null
    or v_assignment.assignment_status <> 'active'
    or v_membership.id is null
    or v_actor is null
    or not app_private.safety_workforce_can_manage(v_membership.project_id, v_membership.construction_site_id)
  then
    raise exception 'SAFETY_SCOPE_MISMATCH: assignment is not active or manageable'
      using errcode = '42501';
  end if;
  if p_ended_at < v_assignment.started_at then
    raise exception 'SAFETY_INVALID_RPC_PAYLOAD: end time precedes start time'
      using errcode = '22023';
  end if;

  select worker.*
  into v_worker
  from public.safety_worker_profiles worker
  where worker.id = v_assignment.worker_id
  for update;

  perform assignment.id
  from public.safety_project_assignments assignment
  where assignment.id = v_assignment.id
  for update;

  perform membership.id
  from public.safety_worker_site_memberships membership
  where membership.id = v_membership.id
  for update;

  update public.safety_project_assignments assignment
  set assignment_status = 'ended',
      ended_at = p_ended_at,
      end_date = (p_ended_at at time zone 'Asia/Ho_Chi_Minh')::date,
      ended_by = v_actor,
      ended_reason = trim(p_reason),
      updated_at = now()
  where assignment.id = v_assignment.id;

  update public.safety_cards card
  set status = 'revoked',
      revoked_reason = 'Assignment ended: ' || trim(p_reason),
      updated_at = now()
  where card.assignment_id = v_assignment.id
    and card.status = 'active';

  update public.safety_worker_site_memberships membership
  set status = 'inactive',
      last_left_at = p_ended_at,
      updated_by = v_actor,
      updated_at = now()
  where membership.id = v_membership.id;

  insert into public.safety_audit_logs (
    actor_user_id, action, target_type, target_id, project_id, construction_site_id, metadata
  ) values (
    v_actor::text,
    'assignment.end',
    'safety_project_assignments',
    v_assignment.id,
    v_membership.project_id,
    v_membership.construction_site_id::text,
    jsonb_build_object('membershipId', v_membership.id, 'reason', trim(p_reason))
  );

  return app_private.safety_workforce_detail_for_membership(v_membership.id);
end;
$$;


--
-- Name: enforce_boq_reconciliation_room_status(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.enforce_boq_reconciliation_room_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_action text;
begin
  if new.status is not distinct from old.status then return new; end if;
  v_action := case
    when new.status = 'submitted' then 'submit'
    when new.status = 'reviewed' then 'verify'
    when new.status = 'locked' then 'approve'
    else null
  end;
  if v_action is null then return new; end if;
  perform app_private.assert_project_permission_room_action(
    new.project_id::text, new.construction_site_id::text, 'boq_reconciliation', v_action
  );
  if new.status = 'submitted' then
    if nullif(new.submitted_to_user_id, '') is null then
      raise exception 'Vui lòng chọn người rà soát BOQ trong Room.' using errcode = '42501';
    end if;
    perform app_private.assert_project_permission_room_action(
      new.project_id::text, new.construction_site_id::text, 'boq_reconciliation', 'verify', new.submitted_to_user_id::uuid
    );
  end if;
  return new;
end;
$$;


