--
-- Name: enforce_daily_log_room_status(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.enforce_daily_log_room_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_action text;
  v_target_action text;
begin
  if new.status is not distinct from old.status
    and new.submitted_to_user_id is not distinct from old.submitted_to_user_id
    and new.submitted_to_permission is not distinct from old.submitted_to_permission then
    return new;
  end if;

  if new.status is not distinct from old.status and new.status = 'submitted' then
    v_action := 'submit';
    v_target_action := case when new.submitted_to_permission = 'approve' then 'approve' else 'verify' end;
  elsif new.status = 'submitted' then
    v_action := 'submit';
    v_target_action := case when new.submitted_to_permission = 'approve' then 'approve' else 'verify' end;
  elsif new.status = 'verified' then
    v_action := case when old.submitted_to_permission = 'approve' then 'approve' else 'verify' end;
  elsif new.status = 'rejected' then
    v_action := case when old.submitted_to_permission = 'approve' then 'approve' else 'verify' end;
  else
    return new;
  end if;

  perform app_private.assert_project_permission_room_action(
    new.project_id::text, new.construction_site_id::text, 'daily_log', v_action
  );

  if new.status = 'submitted' and nullif(new.submitted_to_user_id, '') is not null then
    perform app_private.assert_project_permission_room_action(
      new.project_id::text, new.construction_site_id::text, 'daily_log', v_target_action,
      new.submitted_to_user_id::uuid
    );
  end if;
  return new;
end;
$$;


--
-- Name: enforce_material_request_code_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.enforce_material_request_code_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
  if tg_op = 'UPDATE' then
    if old.code is distinct from new.code then
      raise exception 'Material request code is system-generated and cannot be edited.'
        using errcode = '23514';
    end if;
    return new;
  end if;

  -- Supabase upsert fires the INSERT trigger before resolving an existing id.
  if exists (
    select 1
    from public.requests r
    where r.id = new.id
      and r.code = new.code
  ) then
    return new;
  end if;

  if nullif(trim(coalesce(new.code, '')), '') is null then
    new.code := public.next_material_request_code_v1();
  end if;

  if new.code !~ '^MR-[0-9]{4}-[0-9]{4,}$' then
    raise exception 'Invalid material request code %. The system must issue MR-YYYY-0001 style codes.', new.code
      using errcode = '23514';
  end if;

  update app_private.material_request_code_registry registry
  set request_id = new.id::text
  where registry.code = new.code
    and registry.request_id is null;

  if not found then
    raise exception 'Material request code % was not issued or has already been used.', new.code
      using errcode = '23505';
  end if;

  return new;
end;
$_$;


--
-- Name: enforce_payment_certificate_room_status(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.enforce_payment_certificate_room_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_action text;
  v_target_action text;
begin
  if new.status is not distinct from old.status then return new; end if;
  v_action := case
    when new.status = 'submitted' then 'submit'
    when new.status in ('approved', 'returned', 'cancelled') then 'approve'
    when new.status = 'paid' then 'confirm'
    else null
  end;
  if v_action is null then return new; end if;
  perform app_private.assert_project_permission_room_action(
    new.project_id::text, new.construction_site_id::text, 'payment', v_action
  );
  if new.status in ('submitted', 'approved') and nullif(new.submitted_to_user_id, '') is not null then
    v_target_action := case when new.status = 'approved' then 'confirm' else 'approve' end;
    perform app_private.assert_project_permission_room_action(
      new.project_id::text, new.construction_site_id::text, 'payment', v_target_action, new.submitted_to_user_id::uuid
    );
  elsif new.status = 'submitted' then
    raise exception 'Vui lòng chọn người duyệt chứng từ thanh toán trong Room.' using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: enforce_purchase_order_archive_update(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.enforce_purchase_order_archive_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_old_payload jsonb;
  v_new_payload jsonb;
begin
  if old.archived_at is not null then
    raise exception 'PO đã lưu trữ không thể chỉnh sửa.';
  end if;

  if new.archived_at is null then
    return new;
  end if;

  if not app_private.project_po_can_archive_v1(
    old.id::text,
    old.project_id::text,
    old.construction_site_id::text,
    old.status::text,
    old.ever_submitted,
    old.received_transaction_ids,
    old.items
  ) then
    raise exception 'Chỉ lưu trữ PO nháp chưa gửi duyệt, hoặc PO đã hoàn trả đủ/không còn giao dịch kho dang dở.';
  end if;

  new.archived_at := coalesce(new.archived_at, now());
  new.archived_by := coalesce(new.archived_by, public.current_app_user_id());
  new.archive_reason := nullif(trim(coalesce(new.archive_reason, '')), '');

  v_old_payload := to_jsonb(old) - 'archived_at' - 'archived_by' - 'archive_reason';
  v_new_payload := to_jsonb(new) - 'archived_at' - 'archived_by' - 'archive_reason';

  if v_old_payload <> v_new_payload then
    raise exception 'Thao tác lưu trữ PO chỉ được cập nhật các trường lưu trữ.';
  end if;

  return new;
end;
$$;


--
-- Name: enforce_purchase_order_number_v2(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.enforce_purchase_order_number_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_base_number text;
begin
  if tg_op = 'UPDATE' then
    if old.po_number is distinct from new.po_number then
      raise exception 'Số PO được hệ thống tự sinh và không thể chỉnh sửa.'
        using errcode = '23514';
    end if;
    return new;
  end if;

  -- Supabase upsert executes the INSERT trigger before resolving an existing id.
  -- Allow that existing row to continue through its normal UPDATE path.
  if exists (
    select 1
    from public.purchase_orders po
    where po.id = new.id
      and po.po_number = new.po_number
  ) then
    return new;
  end if;

  if new.po_number !~ '^PO-[0-9]{3,}(-[0-9]{2})?$' then
    raise exception 'Số PO không hợp lệ. Hệ thống phải tự cấp số PO.'
      using errcode = '23514';
  end if;

  v_base_number := regexp_replace(new.po_number, '-[0-9]{2}$', '');

  if new.po_number = v_base_number then
    update app_private.purchase_order_number_registry registry
    set purchase_order_id = new.id::text
    where registry.po_number = new.po_number
      and registry.purchase_order_id is null;

    if not found then
      raise exception 'Số PO % chưa được cấp hoặc đã được sử dụng.', new.po_number
        using errcode = '23505';
    end if;
  else
    if not exists (
      select 1
      from app_private.purchase_order_number_registry registry
      where registry.po_number = v_base_number
    ) then
      raise exception 'Nhóm số PO % chưa được hệ thống cấp.', v_base_number
        using errcode = '23505';
    end if;

    insert into app_private.purchase_order_number_registry(po_number, purchase_order_id)
    values (new.po_number, new.id::text)
    on conflict (po_number) do nothing;

    if not found then
      raise exception 'Số PO % đã được sử dụng.', new.po_number
        using errcode = '23505';
    end if;
  end if;

  return new;
end;
$_$;


--
-- Name: enforce_quality_checklist_room_status(); Type: FUNCTION; Schema: app_private; Owner: -
