--
-- Name: enforce_request_approver_not_creator(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.enforce_request_approver_not_creator() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_creator_id uuid;
begin
  select request_instance.created_by
  into v_creator_id
  from public.request_instances request_instance
  where request_instance.workflow_subject_id = new.workflow_subject_id;

  if found and new.assignee_user_id = v_creator_id then
    raise exception using errcode = '22023', message = 'REQUEST_APPROVER_SELF_NOT_ALLOWED';
  end if;
  return new;
end;
$$;


--
-- Name: enforce_user_application_membership(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.enforce_user_application_membership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_target public.users%rowtype;
  v_application public.permission_applications%rowtype;
begin
  if new.status = 'REVOKED' then
    if new.revoked_by is null
      or nullif(btrim(coalesce(new.revoked_reason, '')), '') is null
      or char_length(btrim(new.revoked_reason)) < 5
      or new.revoked_at is null
    then
      raise exception 'Revoked membership requires revoked_by, revoked_reason, and revoked_at'
        using errcode = '23514';
    end if;
  elsif new.revoked_by is not null
    or new.revoked_reason is not null
    or new.revoked_at is not null
  then
    raise exception 'Active membership cannot contain revoke metadata'
      using errcode = '23514';
  end if;

  select * into v_target
  from public.users
  where id = new.user_id;

  if v_target.id is null
    or v_target.role is distinct from 'EMPLOYEE'
  then
    raise exception 'Membership rows require an EMPLOYEE target'
      using errcode = '23514';
  end if;

  if new.status = 'ACTIVE' then
    if not v_target.is_active
      or v_target.account_status <> 'ACTIVE'
    then
      raise exception 'Active membership requires an active target user'
        using errcode = '23514';
    end if;

    select * into v_application
    from public.permission_applications
    where code = new.application_code;

    if v_application.code is null
      or not v_application.is_active
      or not v_application.member_assignable
    then
      raise exception 'Active membership requires an active Member-assignable application'
        using errcode = '23514';
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: enforce_user_application_membership_role_transition(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.enforce_user_application_membership_role_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.role = 'EMPLOYEE'
    and new.role is distinct from 'EMPLOYEE'
    and exists (
      select 1
      from public.user_application_memberships membership_row
      where membership_row.user_id = new.id
        and membership_row.status = 'ACTIVE'
    )
  then
    raise exception 'An EMPLOYEE with active application memberships cannot change roles'
      using errcode = '23514';
  end if;

  if old.role is distinct from 'ADMIN'
    and new.role = 'ADMIN'
    and exists (
      select 1
      from public.user_application_memberships membership_row
      where membership_row.user_id = new.id
    )
  then
    raise exception 'An account with application membership history cannot become ADMIN'
      using errcode = '23514';
  end if;

  return new;
end;
$$;


--
-- Name: enforce_vehicle_dispatch_override_setting(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.enforce_vehicle_dispatch_override_setting() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_booking_status text;
  v_override_allowed boolean;
begin
  select booking.status
  into v_booking_status
  from public.vehicle_bookings booking
  where booking.id = new.booking_id;

  if v_booking_status = 'PENDING_APPROVAL' then
    select coalesce(settings.allow_dispatch_approval_override, true)
    into v_override_allowed
    from public.fleet_system_settings settings
    where settings.id = 1;

    if not coalesce(v_override_allowed, true) then
      raise exception using errcode = 'P0001', message = 'DISPATCH_APPROVAL_OVERRIDE_DISABLED';
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: ensure_feedback_watchers(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.ensure_feedback_watchers() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.feedback_watchers(feedback_id, user_id, created_by)
  values (new.id, new.created_by, new.created_by)
  on conflict (feedback_id, user_id) do nothing;

  if new.assigned_to is not null then
    insert into public.feedback_watchers(feedback_id, user_id, created_by)
    values (new.id, new.assigned_to, public.current_app_user_id())
    on conflict (feedback_id, user_id) do nothing;
  end if;

  return new;
end;
$$;


--
-- Name: ensure_material_po_batch_wms(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.ensure_material_po_batch_wms(p_delivery_batch_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_po_id text;
  v_po public.purchase_orders%rowtype;
  v_batch public.purchase_order_delivery_batches%rowtype;
  v_line public.purchase_order_delivery_lines%rowtype;
  v_tx public.transactions%rowtype;
  v_tx_id text := 'tx-po-delivery-' || replace(gen_random_uuid()::text, '-', '');
  v_qr_token text := 'pod_' || replace(gen_random_uuid()::text, '-', '');
  v_wms_items jsonb := '[]'::jsonb;
  v_stock_unit_price numeric;
  v_previous_guard text;
begin
  if p_actor_user_id is null then
    raise exception 'Người thực hiện lệnh không hợp lệ.' using errcode = '42501';
  end if;

  select batch.purchase_order_id
  into v_po_id
  from public.purchase_order_delivery_batches batch
  where batch.id = p_delivery_batch_id;
  if not found then
    raise exception 'Không tìm thấy đợt giao.' using errcode = '22023';
  end if;

  select * into v_po
  from public.purchase_orders po
  where po.id = v_po_id
  for update;

  select * into v_batch
  from public.purchase_order_delivery_batches batch
  where batch.id = p_delivery_batch_id
  for update;

  if public.current_app_user_id() is not null then
    if public.current_app_user_id() <> p_actor_user_id then
      raise exception 'Người thực hiện lệnh không hợp lệ.' using errcode = '42501';
    end if;
    perform app_private.assert_project_permission_room_action(
      v_po.project_id,
      v_po.construction_site_id,
      'material_po',
      'approve',
      p_actor_user_id
    );
  end if;

  if coalesce(v_po.source_mode, '') <> 'from_request' then
    raise exception 'Chỉ áp dụng cho PO vật tư tạo từ phiếu đề xuất.' using errcode = '22023';
  end if;
  if v_batch.supplier_id is not null
     and v_batch.supplier_id is distinct from v_po.vendor_id then
    raise exception 'Nhà cung cấp của đợt giao không khớp PO.' using errcode = '22023';
  end if;
  if coalesce(v_batch.vat_rate, v_po.vat_rate, 0) < 0
     or coalesce(v_batch.vat_rate, v_po.vat_rate, 0) > 100 then
    raise exception 'Thuế VAT phải trong khoảng 0 đến 100.' using errcode = '22023';
  end if;
  if v_batch.status in ('cancelled', 'received', 'received_short', 'received_over') then
    raise exception 'Đợt giao đã kết thúc, không thể tạo phiếu WMS.' using errcode = '22023';
  end if;
  if nullif(trim(coalesce(v_po.target_warehouse_id, '')), '') is null then
    raise exception 'PO thiếu kho nhận hàng.' using errcode = '22023';
  end if;

  if nullif(coalesce(v_batch.wms_transaction_id, ''), '') is not null then
    select * into v_tx
    from public.transactions tx
    where tx.id = v_batch.wms_transaction_id
    for update;
    if not found
       or v_tx.source_type <> 'po_delivery_batch'
       or v_tx.source_id <> v_batch.id::text then
      raise exception 'WMS hiện tại không liên kết đúng đợt giao.' using errcode = 'P0001';
    end if;

    update public.purchase_order_delivery_batches
    set qr_token = coalesce(qr_token, v_qr_token),
        idempotency_key = coalesce(idempotency_key, gen_random_uuid()),
        status = case
          when v_tx.status = 'PENDING'::public.transaction_status
            and status in ('planned', 'wms_pending', 'waiting_delivery') then 'receiving'
          else status
        end,
        updated_at = now()
    where id = v_batch.id
    returning * into v_batch;

    return jsonb_build_object(
      'deliveryBatchId', v_batch.id,
      'deliveryNo', v_batch.delivery_no,
      'deliveryCode', coalesce(v_po.po_number, v_po.id) || '-' || lpad(v_batch.delivery_no::text, 2, '0'),
      'wmsTransactionId', v_batch.wms_transaction_id,
      'qrToken', v_batch.qr_token
    );
  end if;

  for v_line in
    select *
    from public.purchase_order_delivery_lines line
    where line.delivery_batch_id = v_batch.id
    order by line.id
  loop
    if coalesce(v_line.planned_qty, 0) <= 0
       or coalesce(v_line.stock_planned_qty, 0) <= 0 then
      raise exception 'Số lượng của đợt giao phải lớn hơn 0.' using errcode = '22023';
    end if;
    if coalesce(v_line.delivery_unit_price, 0) < 0 then
      raise exception 'Đơn giá đợt giao không được âm.' using errcode = '22023';
    end if;
    if not exists (
      select 1
      from jsonb_array_elements(coalesce(v_po.items, '[]'::jsonb)) item(value)
      where coalesce(item.value ->> 'lineId', item.value ->> 'itemId') = v_line.purchase_order_line_id
        and item.value ->> 'itemId' = v_line.item_id
    ) then
      raise exception 'Dòng đợt giao không thuộc PO.' using errcode = '22023';
    end if;

    v_stock_unit_price := case
      when coalesce(v_line.stock_planned_qty, 0) > 0 then
        coalesce(v_line.delivery_unit_price, 0)
          * coalesce(v_line.planned_qty, 0)
          / v_line.stock_planned_qty
      else 0
    end;

    v_wms_items := v_wms_items || jsonb_build_array(jsonb_build_object(
      'itemId', v_line.item_id,
      'quantity', v_line.stock_planned_qty,
      'orderedQty', v_line.stock_planned_qty,
      'price', v_stock_unit_price,
      'accountingQty', v_line.planned_qty,
      'accountingUnit', coalesce(v_line.unit, v_line.stock_unit, ''),
      'accountingPrice', coalesce(v_line.delivery_unit_price, 0),
      'purchaseOrderLineId', v_line.purchase_order_line_id,
      'purchaseOrderDeliveryBatchId', v_batch.id,
      'purchaseOrderDeliveryLineId', v_line.id,
      'fulfillmentMode', coalesce(v_batch.fulfillment_mode, v_po.fulfillment_mode)
    ));
  end loop;

  if jsonb_array_length(v_wms_items) = 0 then
    raise exception 'Đợt giao phải có ít nhất một dòng vật tư.' using errcode = '22023';
  end if;

  insert into public.transactions (
    id, type, date, items, target_warehouse_id, supplier_id,
    requester_id, created_by, approver_id, status, note,
    business_partner_id, business_partner_name_snapshot, source_type, source_id
  ) values (
    v_tx_id,
    'IMPORT'::public.transaction_type,
    now(),
    v_wms_items,
    v_po.target_warehouse_id,
    nullif(coalesce(v_batch.supplier_id, v_po.vendor_id), ''),
    p_actor_user_id,
    p_actor_user_id,
    p_actor_user_id,
    'PENDING'::public.transaction_status,
    coalesce(v_po.po_number, v_po.id) || '-Đợt ' || v_batch.delivery_no || ' chờ nhận',
    null,
    nullif(coalesce(v_batch.supplier_name_snapshot, v_po.vendor_name), ''),
    'po_delivery_batch',
    v_batch.id::text
  );

  update public.purchase_order_delivery_batches
  set supplier_id = nullif(coalesce(supplier_id, v_po.vendor_id), ''),
      supplier_name_snapshot = nullif(coalesce(supplier_name_snapshot, v_po.vendor_name), ''),
      fulfillment_mode = coalesce(fulfillment_mode, v_po.fulfillment_mode),
      vat_rate = coalesce(vat_rate, v_po.vat_rate, 0),
      qr_token = coalesce(qr_token, v_qr_token),
      idempotency_key = coalesce(idempotency_key, gen_random_uuid()),
      wms_transaction_id = v_tx_id,
      status = 'receiving',
      updated_at = now()
  where id = v_batch.id
  returning * into v_batch;

  if v_po.status in ('draft', 'sent', 'returned', 'confirmed') then
    v_previous_guard := current_setting('app.material_transition_context', true);
    perform set_config('app.material_transition_context', 'on', true);
    update public.purchase_orders
    set status = 'in_transit',
        ever_submitted = true,
        last_action_by = p_actor_user_id::text,
        last_action_at = now()
    where id = v_po.id;
    perform set_config('app.material_transition_context', coalesce(v_previous_guard, ''), true);
  end if;

  return jsonb_build_object(
    'deliveryBatchId', v_batch.id,
    'deliveryNo', v_batch.delivery_no,
    'deliveryCode', coalesce(v_po.po_number, v_po.id) || '-' || lpad(v_batch.delivery_no::text, 2, '0'),
    'wmsTransactionId', v_batch.wms_transaction_id,
    'qrToken', v_batch.qr_token
  );
exception
  when others then
    perform set_config('app.material_transition_context', coalesce(v_previous_guard, ''), true);
    raise;
end;
$$;


--
-- Name: evaluate_authorization_change(uuid, uuid, text[], text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.evaluate_authorization_change(p_actor_user_id uuid, p_target_user_id uuid, p_proposed_permission_codes text[], p_scope_type text, p_scope_id text, p_change_mode text DEFAULT 'ADD'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_actor_user_id is null
    or p_actor_user_id is distinct from public.current_app_user_id()
    or not app_private.has_any_permission(
      public.current_app_user_id(),
      array['system.authorization.manage_roles','system.authorization.manage_grants'],
      'global', '*'
    )
  then
    raise exception 'Active authorization actor required' using errcode = '42501';
  end if;

  if p_change_mode not in ('ADD', 'REPLACE_DIRECT') then
    raise exception 'Unknown authorization change mode' using errcode = '22023';
  end if;

  return (
  with proposed as (
    select distinct code as permission_code
    from unnest(coalesce(p_proposed_permission_codes, '{}'::text[])) code
  ),
  current_codes as (
    select distinct source_row.permission_code
    from app_private.resolve_effective_permission_sources(
      p_target_user_id, null, p_scope_type, p_scope_id, now()
    ) source_row
    where p_change_mode <> 'REPLACE_DIRECT'
       or source_row.source_type <> 'DIRECT'
  ),
  resulting_codes as (
    select permission_code from current_codes
    union
    select permission_code from proposed
  ),
  self_grant_denies as (
    select jsonb_build_object(
      'ruleCode', rule_row.rule_code,
      'effect', rule_row.effect,
      'message', rule_row.description,
      'permissionCodes', jsonb_agg(action_row.permission_code order by action_row.permission_code),
      'scopeType', p_scope_type,
      'scopeId', p_scope_id
    ) finding
    from public.authorization_sod_rules rule_row
    join proposed proposed_row on true
    join public.permission_actions action_row
      on action_row.permission_code = proposed_row.permission_code
     and action_row.risk_level = 'sensitive'
    where rule_row.rule_code = 'AUTHZ_SENSITIVE_SELF_GRANT'
      and rule_row.is_active
      and p_actor_user_id = p_target_user_id
      and p_change_mode = 'ADD'
    group by rule_row.rule_code, rule_row.effect, rule_row.description
  ),
  pair_findings as (
    select
      rule_row.effect,
      jsonb_build_object(
        'ruleCode', rule_row.rule_code,
        'effect', rule_row.effect,
        'message', rule_row.description,
        'permissionCodes', jsonb_build_array(rule_row.left_permission_code, rule_row.right_permission_code),
        'scopeType', p_scope_type,
        'scopeId', p_scope_id
      ) finding
    from public.authorization_sod_rules rule_row
    where rule_row.is_active
      and rule_row.rule_type = 'PERMISSION_PAIR'
      and exists (select 1 from resulting_codes c where c.permission_code = rule_row.left_permission_code)
      and exists (select 1 from resulting_codes c where c.permission_code = rule_row.right_permission_code)
      and (
        exists (select 1 from proposed c where c.permission_code = rule_row.left_permission_code)
        or exists (select 1 from proposed c where c.permission_code = rule_row.right_permission_code)
      )
      and not (
        exists (select 1 from current_codes c where c.permission_code = rule_row.left_permission_code)
        and exists (select 1 from current_codes c where c.permission_code = rule_row.right_permission_code)
      )
  ),
  all_findings as (
    select 'DENY'::text as effect, finding from self_grant_denies
    union all
    select effect, finding from pair_findings
  )
  select jsonb_build_object(
    'hardDenies', coalesce(jsonb_agg(finding order by finding->>'ruleCode') filter (where effect = 'DENY'), '[]'::jsonb),
    'warnings', coalesce(jsonb_agg(finding order by finding->>'ruleCode') filter (where effect = 'WARN'), '[]'::jsonb)
  )
  from all_findings
  );
end;
$$;


--
-- Name: evaluate_authorization_change_set(uuid, uuid, jsonb, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.evaluate_authorization_change_set(p_actor_user_id uuid, p_target_user_id uuid, p_proposed_grants jsonb, p_change_mode text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_actor_user_id is null
    or p_actor_user_id is distinct from public.current_app_user_id()
    or not app_private.has_any_permission(
      public.current_app_user_id(),
      array['system.authorization.manage_roles','system.authorization.manage_grants'],
      'global', '*'
    )
  then
    raise exception 'Active authorization actor required' using errcode = '42501';
  end if;

  if p_change_mode not in ('ADD', 'REPLACE_DIRECT')
    or jsonb_typeof(coalesce(p_proposed_grants, '[]'::jsonb)) <> 'array'
  then
    raise exception 'Invalid authorization change set' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(coalesce(p_proposed_grants, '[]'::jsonb)) item(
      "permissionCode" text,
      "scopeType" text,
      "scopeId" text
    )
    left join public.permission_actions action_row
      on action_row.permission_code = item."permissionCode"
     and action_row.is_active
    where action_row.permission_code is null
       or coalesce(nullif(item."scopeType", ''), 'global') <> all(action_row.scope_modes)
       or (
         coalesce(nullif(item."scopeType", ''), 'global') = 'global'
         and coalesce(nullif(item."scopeId", ''), '*') <> '*'
       )
  ) then
    raise exception 'Authorization change set contains an invalid permission scope'
      using errcode = '23514';
  end if;

  return (
    with proposed as (
      select distinct
        item."permissionCode" as permission_code,
        coalesce(nullif(item."scopeType", ''), 'global') as scope_type,
        coalesce(nullif(item."scopeId", ''), '*') as scope_id
      from jsonb_to_recordset(coalesce(p_proposed_grants, '[]'::jsonb)) item(
        "permissionCode" text,
        "scopeType" text,
        "scopeId" text
      )
    ),
    current_points as (
      select distinct source_row.scope_type, source_row.scope_id
      from app_private.resolve_effective_permission_sources(
        p_target_user_id, null, null, null, now()
      ) source_row
    ),
    candidate_points as (
      select distinct proposed_row.scope_type, proposed_row.scope_id
      from proposed proposed_row
      union
      select distinct current_row.scope_type, current_row.scope_id
      from current_points current_row
      where exists (
        select 1
        from proposed proposed_row
        where app_private.scope_covers(
          proposed_row.scope_type,
          proposed_row.scope_id,
          current_row.scope_type,
          current_row.scope_id
        )
      )
    ),
    point_permissions as (
      select
        point_row.scope_type,
        point_row.scope_id,
        array_agg(distinct proposed_row.permission_code order by proposed_row.permission_code) as permission_codes
      from candidate_points point_row
      join proposed proposed_row
        on app_private.scope_covers(
          proposed_row.scope_type,
          proposed_row.scope_id,
          point_row.scope_type,
          point_row.scope_id
        )
      group by point_row.scope_type, point_row.scope_id
    ),
    decisions as (
      select
        point_row.scope_type,
        point_row.scope_id,
        app_private.evaluate_authorization_change(
          p_actor_user_id,
          p_target_user_id,
          point_row.permission_codes,
          point_row.scope_type,
          point_row.scope_id,
          p_change_mode
        ) as decision
      from point_permissions point_row
    ),
    findings as (
      select 'DENY'::text as effect, finding.value as finding
      from decisions decision_row
      cross join lateral jsonb_array_elements(decision_row.decision -> 'hardDenies') finding
      union all
      select 'WARN'::text as effect, finding.value as finding
      from decisions decision_row
      cross join lateral jsonb_array_elements(decision_row.decision -> 'warnings') finding
    ),
    deduplicated as (
      select distinct on (
        finding_row.effect,
        finding_row.finding ->> 'ruleCode',
        finding_row.finding ->> 'scopeType',
        finding_row.finding ->> 'scopeId'
      )
        finding_row.effect,
        finding_row.finding
      from findings finding_row
      order by
        finding_row.effect,
        finding_row.finding ->> 'ruleCode',
        finding_row.finding ->> 'scopeType',
        finding_row.finding ->> 'scopeId'
    ),
    unsuppressed as (
      select candidate.effect, candidate.finding
      from deduplicated candidate
      where not exists (
        select 1
        from deduplicated broader
        where broader.effect = candidate.effect
          and broader.finding ->> 'ruleCode' = candidate.finding ->> 'ruleCode'
          and broader.finding is distinct from candidate.finding
          and (
            (
              broader.finding ->> 'scopeType' = 'global'
              and broader.finding ->> 'scopeId' = '*'
            )
            or (
              broader.finding ->> 'scopeType' = candidate.finding ->> 'scopeType'
              and broader.finding ->> 'scopeId' = '*'
              and candidate.finding ->> 'scopeId' <> '*'
            )
          )
      )
    )
    select jsonb_build_object(
      'hardDenies', coalesce(
        jsonb_agg(finding order by finding ->> 'ruleCode', finding ->> 'scopeType', finding ->> 'scopeId')
          filter (where effect = 'DENY'),
        '[]'::jsonb
      ),
      'warnings', coalesce(
        jsonb_agg(finding order by finding ->> 'ruleCode', finding ->> 'scopeType', finding ->> 'scopeId')
          filter (where effect = 'WARN'),
        '[]'::jsonb
      )
    )
    from unsuppressed
  );
end;
$$;


--
-- Name: evaluate_business_role_assignment_impl(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.evaluate_business_role_assignment_impl(p_actor_user_id uuid, p_target_user_id uuid, p_role_template_id uuid, p_scope_type text, p_scope_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_scope_type text := coalesce(nullif(p_scope_type, ''), 'global');
  v_scope_id text := coalesce(nullif(p_scope_id, ''), '*');
  v_proposed jsonb := '[]'::jsonb;
begin
  if p_actor_user_id is null
    or p_actor_user_id is distinct from public.current_app_user_id()
    or not app_private.has_permission(
      p_actor_user_id,
      'system.authorization.manage_roles',
      'global',
      '*'
    )
  then
    raise exception 'Authorization administration permission required'
      using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.users target_row
    where target_row.id = p_target_user_id
      and target_row.is_active
      and target_row.account_status = 'ACTIVE'
  ) then
    raise exception 'Active target user required'
      using errcode = '23514';
  end if;

  if not exists (
    select 1
    from public.role_permission_templates role_row
    where role_row.id = p_role_template_id
      and role_row.is_active
  ) then
    raise exception 'Valid Business Role required'
      using errcode = '23514';
  end if;

  if v_scope_type not in (
      'global','own','assigned','project','construction_site','warehouse','department'
    )
    or (v_scope_type = 'global' and v_scope_id <> '*')
    or (v_scope_type <> 'global' and btrim(v_scope_id) = '')
    or exists (
      select 1
      from public.role_permission_template_items item
      join public.permission_actions action_row
        on action_row.permission_code = item.permission_code
       and action_row.is_active
      where item.template_id = p_role_template_id
        and (
          (
            v_scope_type <> 'global'
            and item.scope_type <> 'global'
            and (
              item.scope_type <> v_scope_type
              or (
                v_scope_id <> '*'
                and item.scope_id <> '*'
                and item.scope_id <> v_scope_id
              )
            )
          )
          or not (
            case
              when v_scope_type <> 'global' then v_scope_type
              else item.scope_type
            end = any(action_row.scope_modes)
          )
        )
    )
  then
    raise exception 'Business Role does not support the requested assignment scope'
      using errcode = '23514';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'permissionCode', proposed.permission_code,
        'scopeType', proposed.scope_type,
        'scopeId', proposed.scope_id
      )
      order by proposed.permission_code, proposed.scope_type, proposed.scope_id
    ),
    '[]'::jsonb
  )
  into v_proposed
  from (
    select distinct
      item.permission_code,
      case
        when v_scope_type = 'global' then item.scope_type
        when item.scope_type = 'global' then v_scope_type
        else item.scope_type
      end as scope_type,
      case
        when v_scope_type = 'global' then item.scope_id
        when item.scope_type = 'global' then v_scope_id
        when v_scope_id = '*' then item.scope_id
        when item.scope_id = '*' then v_scope_id
        else v_scope_id
      end as scope_id
    from public.role_permission_template_items item
    where item.template_id = p_role_template_id
  ) proposed;

  return app_private.evaluate_authorization_change_set(
    p_actor_user_id,
    p_target_user_id,
    v_proposed,
    'ADD'
  );
end;
$$;


--
-- Name: evaluate_direct_grant_replacement_impl(uuid, uuid, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.evaluate_direct_grant_replacement_impl(p_actor_user_id uuid, p_target_user_id uuid, p_grants jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_grants jsonb := coalesce(p_grants, '[]'::jsonb);
  v_proposed jsonb := '[]'::jsonb;
begin
  if p_actor_user_id is null
    or p_actor_user_id is distinct from public.current_app_user_id()
    or not app_private.has_permission(
      p_actor_user_id,
      'system.authorization.manage_grants',
      'global',
      '*'
    )
  then
    raise exception 'Authorization administration permission required'
      using errcode = '42501';
  end if;

  if jsonb_typeof(v_grants) <> 'array' then
    raise exception 'Permission grants payload must be an array'
      using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.users target_row
    where target_row.id = p_target_user_id
      and target_row.is_active
      and target_row.account_status = 'ACTIVE'
  ) then
    raise exception 'Active target user required'
      using errcode = '23514';
  end if;

  if exists (
    select 1
    from (
      select
        grant_row.permission_code,
        coalesce(nullif(grant_row.scope_type, ''), 'global') as scope_type,
        coalesce(nullif(grant_row.scope_id, ''), '*') as scope_id,
        count(*) as row_count
      from jsonb_to_recordset(v_grants) grant_row(
        permission_code text,
        scope_type text,
        scope_id text,
        is_active boolean,
        expires_at timestamptz
      )
      where coalesce(grant_row.is_active, true)
      group by 1, 2, 3
      having count(*) > 1
    ) duplicate_row
  ) then
    raise exception 'Duplicate direct permission grant key'
      using errcode = '23505';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(v_grants) grant_row(
      permission_code text,
      scope_type text,
      scope_id text,
      is_active boolean,
      expires_at timestamptz
    )
    left join public.permission_actions action_row
      on action_row.permission_code = grant_row.permission_code
     and action_row.is_active
    where coalesce(grant_row.is_active, true)
      and (
        action_row.permission_code is null
        or coalesce(nullif(grant_row.scope_type, ''), 'global') <> all(action_row.scope_modes)
        or (
          coalesce(nullif(grant_row.scope_type, ''), 'global') = 'global'
          and coalesce(nullif(grant_row.scope_id, ''), '*') <> '*'
        )
        or (
          coalesce(nullif(grant_row.scope_type, ''), 'global') <> 'global'
          and btrim(coalesce(grant_row.scope_id, '')) = ''
        )
        or (
          action_row.direct_grant_requires_expiry
          and (
            grant_row.expires_at is null
            or grant_row.expires_at <= now()
          )
        )
      )
  ) then
    raise exception 'Invalid direct permission grant'
      using errcode = '23514';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(v_grants) grant_row(
      permission_code text,
      is_active boolean
    )
    where coalesce(grant_row.is_active, true)
      and grant_row.permission_code = 'system.settings.manage'
  ) then
    raise exception 'System identity permissions cannot be granted directly'
      using errcode = '42501';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(v_grants) grant_row(
      permission_code text,
      scope_type text,
      scope_id text,
      is_active boolean,
      expires_at timestamptz
    )
    join public.permission_actions action_row
      on action_row.permission_code = grant_row.permission_code
     and action_row.is_active
    where p_target_user_id = p_actor_user_id
      and coalesce(grant_row.is_active, true)
      and action_row.risk_level = 'sensitive'
      and not exists (
        select 1
        from public.user_permission_grants existing
        where existing.user_id = p_target_user_id
          and existing.permission_code = grant_row.permission_code
          and existing.scope_type = coalesce(
            nullif(grant_row.scope_type, ''),
            'global'
          )
          and existing.scope_id = coalesce(nullif(grant_row.scope_id, ''), '*')
          and existing.is_active
          and existing.expires_at is not distinct from grant_row.expires_at
      )
  ) then
    raise exception 'Sensitive self-grant is not allowed'
      using errcode = '42501';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'permissionCode', normalized.permission_code,
        'scopeType', normalized.scope_type,
        'scopeId', normalized.scope_id
      )
      order by normalized.permission_code, normalized.scope_type, normalized.scope_id
    ),
    '[]'::jsonb
  )
  into v_proposed
  from (
    select distinct
      grant_row.permission_code,
      coalesce(nullif(grant_row.scope_type, ''), 'global') as scope_type,
      coalesce(nullif(grant_row.scope_id, ''), '*') as scope_id
    from jsonb_to_recordset(v_grants) grant_row(
      permission_code text,
      scope_type text,
      scope_id text,
      is_active boolean,
      expires_at timestamptz
    )
    where coalesce(grant_row.is_active, true)
  ) normalized;

  return app_private.evaluate_authorization_change_set(
    p_actor_user_id,
    p_target_user_id,
    v_proposed,
    'REPLACE_DIRECT'
  );
end;
$$;


--
-- Name: expense_has_action(text, uuid, text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.expense_has_action(p_permission_code text, p_owner_user_id uuid DEFAULT NULL::uuid, p_department_id text DEFAULT NULL::text, p_user_id uuid DEFAULT public.current_app_user_id()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_permission_code like 'expense.%'
  and p_user_id is not null
  and (
    app_private.has_permission(p_user_id, p_permission_code, 'global', '*')
    or (
      p_owner_user_id = p_user_id
      and app_private.has_permission(p_user_id, p_permission_code, 'own', p_user_id::text)
    )
    or (
      p_department_id is not null
      and app_private.has_permission(p_user_id, p_permission_code, 'department', p_department_id)
    )
    or public.is_module_admin('EX')
  );
$$;


--
-- Name: expense_record_is_owner(text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.expense_record_is_owner(p_created_by text, p_user_id uuid DEFAULT public.current_app_user_id()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_user_id is not null
    and nullif(btrim(coalesce(p_created_by, '')), '') is not null
    and exists (
      select 1
      from public.users u
      where u.id = p_user_id
        and coalesce(u.is_active, true)
        and lower(btrim(coalesce(p_created_by, ''))) in (
          lower(u.id::text),
          lower(u.name),
          lower(u.email),
          lower(u.username)
        )
    );
$$;


--
-- Name: export_vehicle_booking_analytics_phase3_impl(timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.export_vehicle_booking_analytics_phase3_impl(p_from_at timestamp with time zone, p_to_at timestamp with time zone, p_department_id uuid DEFAULT NULL::uuid) RETURNS TABLE(booking_id uuid, booking_code text, department_id uuid, department_name text, requested_pickup_at timestamp with time zone, actual_pickup_at timestamp with time zone, actual_return_at timestamp with time zone, fulfillment_type text, vehicle_code text, vehicle_name text, distance_km numeric, external_actual_cost numeric, status text, close_reason text, is_on_time boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_from_at is null or p_to_at is null or p_to_at <= p_from_at then
    raise exception using errcode = '22023', message = 'INVALID_REPORTING_PERIOD';
  end if;

  perform app_private.vehicle_require_report_scope(
    public.current_app_user_id(),
    p_department_id
  );

  return query
  select
    b.id,
    b.booking_code,
    b.department_id_snapshot,
    coalesce(org.name, 'Chưa xác định'),
    b.requested_pickup_at,
    t.actual_pickup_at,
    t.actual_return_at,
    a.fulfillment_type,
    coalesce(asset.code, t.vehicle_asset_id_snapshot),
    coalesce(asset.name, t.vehicle_asset_id_snapshot),
    t.distance_km,
    a.external_actual_cost,
    b.status,
    b.close_reason,
    case
      when a.fulfillment_type in ('INTERNAL_WITH_DRIVER', 'INTERNAL_SELF_DRIVE')
        and t.actual_pickup_at is not null
      then t.actual_pickup_at <= b.requested_pickup_at
        + make_interval(mins => settings.on_time_tolerance_minutes)
      else null
    end
  from public.vehicle_bookings b
  left join public.vehicle_booking_assignments a
    on a.booking_id = b.id and a.is_active
  left join public.vehicle_trip_logs t on t.booking_id = b.id
  left join public.assets asset on asset.id = t.vehicle_asset_id_snapshot
  left join public.org_units org on org.id = b.department_id_snapshot
  cross join public.fleet_system_settings settings
  where settings.id = 1
    and b.requested_pickup_at >= p_from_at
    and b.requested_pickup_at < p_to_at
    and b.status <> 'DRAFT'
    and (p_department_id is null or b.department_id_snapshot = p_department_id)
  order by b.requested_pickup_at, b.booking_code;
end;
$$;


--
-- Name: fail_request_notification_outbox(uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.fail_request_notification_outbox(p_outbox_id uuid, p_error_message text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_attempt integer;
begin
  perform app_private.require_request_notification_worker();
  select attempt_count into v_attempt from app_private.request_notification_outbox where id = p_outbox_id for update;
  if not found then return; end if;
  update app_private.request_notification_outbox
  set status = 'FAILED', locked_at = null, last_error = left(coalesce(p_error_message, 'Delivery failed'), 500),
    available_at = case when v_attempt >= 10 then now() + interval '100 years'
      else now() + make_interval(secs => least(3600, 60 * power(2, greatest(v_attempt - 1, 0)))::integer) end
  where id = p_outbox_id;
end;
$$;


--
-- Name: fail_vehicle_notification_outbox(uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.fail_vehicle_notification_outbox(p_outbox_id uuid, p_error_message text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_attempt_count integer;
begin
  perform app_private.require_vehicle_notification_worker();
  select attempt_count into v_attempt_count
  from app_private.vehicle_booking_notification_outbox
  where id = p_outbox_id
  for update;
  if not found then return; end if;

  update app_private.vehicle_booking_notification_outbox
  set status = 'FAILED',
      locked_at = null,
      last_error = left(coalesce(p_error_message, 'Delivery failed'), 500),
      available_at = case
        when v_attempt_count >= 10 then now() + interval '100 years'
        else now() + make_interval(
          secs => least(3600, 60 * power(2, greatest(v_attempt_count - 1, 0)))::integer
        )
      end,
      updated_at = now()
  where id = p_outbox_id;
end;
$$;


--
-- Name: feedback_can_manage(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.feedback_can_manage() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.is_admin() or public.is_module_admin('FEEDBACK');
$$;


--
-- Name: feedback_item_can_select(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.feedback_item_can_select(p_feedback_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.feedback_items fi
    where fi.id = p_feedback_id
      and (
        app_private.feedback_can_manage()
        or fi.created_by = public.current_app_user_id()
        or fi.assigned_to = public.current_app_user_id()
        or fi.visibility = 'public'
        or exists (
          select 1
          from public.feedback_watchers fw
          where fw.feedback_id = fi.id
            and fw.user_id = public.current_app_user_id()
        )
      )
  );
$$;


--
-- Name: finalize_purchase_receipt_v2(uuid, text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.finalize_purchase_receipt_v2(p_delivery_batch_id uuid, p_wms_transaction_id text, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_po_id text;
  v_po public.purchase_orders%rowtype;
  v_batch public.purchase_order_delivery_batches%rowtype;
  v_tx public.transactions%rowtype;
  v_item jsonb;
  v_item_id text;
  v_qty numeric;
  v_planned_purchase_qty numeric;
  v_accepted_purchase_qty numeric;
  v_delivery_status text;
  v_next_items jsonb;
  v_is_delivered boolean;
  v_already_recorded boolean;
  v_previous_guard text;
begin
  if p_actor_user_id is null then
    raise exception 'Nguoi thuc hien lenh khong hop le.' using errcode = '42501';
  end if;
  if public.current_app_user_id() is null or p_actor_user_id <> public.current_app_user_id() then
    raise exception 'Nguoi thuc hien lenh khong hop le.' using errcode = '42501';
  end if;

  select purchase_order_id into v_po_id
  from public.purchase_order_delivery_batches
  where id = p_delivery_batch_id;
  if not found then
    raise exception 'Khong tim thay Dot giao %.', p_delivery_batch_id using errcode = '22023';
  end if;

  select * into v_po
  from public.purchase_orders
  where id = v_po_id
  for update;
  if not found then
    raise exception 'Khong tim thay Goi mua hang cua Dot giao %.', p_delivery_batch_id using errcode = '22023';
  end if;

  select * into v_batch
  from public.purchase_order_delivery_batches
  where id = p_delivery_batch_id
  for update;
  if not found then
    raise exception 'Khong tim thay Dot giao %.', p_delivery_batch_id using errcode = '22023';
  end if;
  if v_batch.wms_transaction_id is distinct from p_wms_transaction_id then
    raise exception 'WMS transaction khong khop Dot giao.' using errcode = '22023';
  end if;

  select * into v_tx
  from public.transactions
  where id = p_wms_transaction_id
  for update;
  if not found then
    raise exception 'Khong tim thay WMS cua Dot giao.' using errcode = '22023';
  end if;
  if v_tx.source_type <> 'po_delivery_batch' or v_tx.source_id <> p_delivery_batch_id::text then
    raise exception 'WMS khong lien ket dung Dot giao.' using errcode = '22023';
  end if;
  if not app_private.current_user_can_receive_purchase_batch_v2(p_actor_user_id, v_tx.target_warehouse_id) then
    raise exception 'Nguoi dung khong co quyen xac nhan nhan hang tai kho nhan.' using errcode = '42501';
  end if;

  if v_batch.status in ('received', 'received_short', 'received_over')
     and v_tx.status = 'COMPLETED'::public.transaction_status then
    return app_private.purchase_receipt_command_result_v2(p_delivery_batch_id, true);
  end if;
  if v_batch.status in ('received', 'received_short', 'received_over')
     or v_tx.status = 'COMPLETED'::public.transaction_status then
    raise exception 'Anomaly: Dot giao va WMS khong dong bo trang thai finalize.' using errcode = 'P0001';
  end if;
  if v_batch.status <> 'quality_approved' or v_tx.status <> 'APPROVED'::public.transaction_status then
    raise exception 'Chi finalize Dot da duyet SL/CL va WMS APPROVED.' using errcode = '22023';
  end if;

  perform 1
  from public.purchase_order_delivery_lines
  where delivery_batch_id = p_delivery_batch_id
  order by id
  for update;

  perform 1
  from public.items item
  where item.id in (
    select distinct line.value ->> 'itemId'
    from jsonb_array_elements(coalesce(v_tx.items, '[]'::jsonb)) line(value)
    where nullif(line.value ->> 'itemId', '') is not null
  )
  order by item.id
  for update;

  if coalesce(v_batch.fulfillment_mode, 'RECEIVE_TO_STOCK') = 'RECEIVE_TO_STOCK' then
    for v_item in
      select value from jsonb_array_elements(coalesce(v_tx.items, '[]'::jsonb)) as item(value)
    loop
      v_item_id := nullif(v_item ->> 'itemId', '');
      v_qty := coalesce(nullif(v_item ->> 'quantity', '')::numeric, 0);
      if v_item_id is null or v_qty < 0 then
        raise exception 'WMS item nhan hang khong hop le.' using errcode = '22023';
      end if;
      if v_qty > 0 then
        perform public.apply_stock_change(v_item_id, v_tx.target_warehouse_id, v_qty);
      end if;
    end loop;
  elsif coalesce(v_batch.fulfillment_mode, '') <> 'DIRECT_CONSUMPTION' then
    raise exception 'Fulfillment mode khong hop le: %', v_batch.fulfillment_mode using errcode = '22023';
  end if;

  update public.transactions
  set status = 'COMPLETED'::public.transaction_status,
      approver_id = p_actor_user_id,
      approved_at = coalesce(approved_at, now())
  where id = p_wms_transaction_id
  returning * into v_tx;

  select
    coalesce(sum(coalesce(planned_qty, 0)), 0),
    coalesce(sum(coalesce(accepted_qty, 0)), 0)
  into v_planned_purchase_qty, v_accepted_purchase_qty
  from public.purchase_order_delivery_lines
  where delivery_batch_id = p_delivery_batch_id;

  v_delivery_status := case
    when v_accepted_purchase_qty > v_planned_purchase_qty then 'received_over'
    when v_accepted_purchase_qty < v_planned_purchase_qty then 'received_short'
    else 'received'
  end;

  update public.purchase_order_delivery_batches
  set status = v_delivery_status,
      received_by = p_actor_user_id,
      received_at = now(),
      updated_at = now()
  where id = p_delivery_batch_id
  returning * into v_batch;

  select exists (
    select 1
    from jsonb_array_elements_text(coalesce(v_po.received_transaction_ids, '[]'::jsonb)) existing(id)
    where existing.id = v_tx.id
  ) into v_already_recorded;

  with receipt_by_line as (
    select
      purchase_order_line_id,
      sum(coalesce(accepted_qty, 0)) as accepted_purchase_qty
    from public.purchase_order_delivery_lines
    where delivery_batch_id = p_delivery_batch_id
    group by purchase_order_line_id
  ),
  item_rows as (
    select
      item.value as item,
      item.ordinality,
      coalesce(item.value ->> 'lineId', item.value ->> 'line_id', item.value ->> 'itemId', item.value ->> 'item_id') as line_key,
      coalesce(nullif(item.value ->> 'receivedQty', '')::numeric, 0) as current_received_qty
    from jsonb_array_elements(coalesce(v_po.items, '[]'::jsonb)) with ordinality item(value, ordinality)
  ),
  next_rows as (
    select
      case
        when coalesce(r.accepted_purchase_qty, 0) > 0 then
          jsonb_set(
            ir.item,
            '{receivedQty}',
            to_jsonb(ir.current_received_qty + coalesce(r.accepted_purchase_qty, 0)),
            true
          )
        else ir.item
      end as item,
      ir.ordinality
    from item_rows ir
    left join receipt_by_line r on r.purchase_order_line_id = ir.line_key
  )
  select coalesce(jsonb_agg(item order by ordinality), '[]'::jsonb)
  into v_next_items
  from next_rows;

  select coalesce(bool_and(
    coalesce(nullif(item.value ->> 'receivedQty', '')::numeric, 0)
      >= coalesce(nullif(item.value ->> 'qty', '')::numeric, 0)
  ), false)
  into v_is_delivered
  from jsonb_array_elements(coalesce(v_next_items, '[]'::jsonb)) item(value);

  v_previous_guard := current_setting('app.material_transition_context', true);
  perform set_config('app.material_transition_context', 'on', true);

  update public.purchase_orders
  set items = v_next_items,
      status = case when v_is_delivered then 'delivered' else 'partial' end,
      actual_delivery_date = case when v_is_delivered then current_date::text else actual_delivery_date end,
      received_transaction_ids = case
        when v_already_recorded then coalesce(received_transaction_ids, '[]'::jsonb)
        else coalesce(received_transaction_ids, '[]'::jsonb) || jsonb_build_array(v_tx.id)
      end
  where id = v_po.id;

  perform set_config('app.material_transition_context', coalesce(v_previous_guard, ''), true);

  update public.material_request_fulfillment_lines mfl
  set received_qty = coalesce(line.accepted_stock_qty, line.accepted_qty, 0),
      variance_reason = coalesce(v_batch.variance_reason, mfl.variance_reason),
      updated_at = now()
  from public.purchase_order_delivery_lines line
  where mfl.po_delivery_line_id = line.id
    and line.delivery_batch_id = p_delivery_batch_id;

  update public.material_request_fulfillment_batches
  set status = 'received',
      received_by = p_actor_user_id,
      received_at = now(),
      updated_at = now()
  where po_delivery_batch_id = p_delivery_batch_id
    and status = 'issued';

  return app_private.purchase_receipt_command_result_v2(p_delivery_batch_id, false);
exception
  when others then
    perform set_config('app.material_transition_context', coalesce(v_previous_guard, ''), true);
    raise;
end;
$$;


--
-- Name: finish_project_gantt_command(uuid, uuid, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.finish_project_gantt_command(p_actor_user_id uuid, p_request_id uuid, p_result jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update app_private.project_gantt_command_requests request
  set result = p_result, completed_at = now()
  where request.actor_user_id = p_actor_user_id
    and request.request_id = p_request_id;
  return p_result;
end;
$$;


