--
-- Name: get_daily_log_assignment_context(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_daily_log_assignment_context(p_log_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'assignmentId', assignment_row.id,
    'userId', assignment_row.principal_id,
    'name', coalesce(assignee.name, assignee.username, assignee.email, assignee.id::text),
    'responsibility', assignment_row.responsibility,
    'permissionCode', assignment_row.permission_code,
    'status', assignment_row.status,
    'startsAt', assignment_row.starts_at,
    'expiresAt', assignment_row.expires_at
  )
  from public.app_assignments assignment_row
  join public.users assignee on assignee.id = assignment_row.principal_id
  where assignment_row.subject_type = 'daily_log'
    and assignment_row.subject_id = p_log_id
    and assignment_row.status = 'active'
    and assignment_row.starts_at <= now()
    and (assignment_row.expires_at is null or assignment_row.expires_at > now())
    and app_private.can_view_subject_impl('daily_log', p_log_id)
  order by assignment_row.created_at desc
  limit 1;
$$;


--
-- Name: get_daily_log_responsibility_target(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_daily_log_responsibility_target(p_log_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_log public.daily_logs%rowtype;
  v_responsibility text;
  v_permission_code text;
  v_slot record;
  v_actor_user_id uuid := public.current_app_user_id();
  v_assignee_name text;
begin
  if not app_private.can_act_on_subject_impl('daily_log', p_log_id, 'submit') then
    raise exception 'Bạn không có quyền gửi nhật ký này.' using errcode = '42501';
  end if;

  select * into v_log from public.daily_logs where id = p_log_id;
  v_responsibility := case when coalesce(v_log.submitted_to_permission, '') = 'approve' then 'current_approver' else 'current_verifier' end;
  v_permission_code := case when v_responsibility = 'current_approver' then 'project.daily_log.approve' else 'project.daily_log.verify' end;

  select * into v_slot
  from app_private.resolve_daily_log_responsibility(
    v_log.project_id::text,
    v_log.construction_site_id::text,
    v_responsibility,
    v_permission_code
  );

  if not found then
    raise exception 'Chưa cấu hình người chịu trách nhiệm % cho phạm vi nhật ký này.', v_responsibility
      using errcode = '42501';
  end if;

  select coalesce(name, username, email, id::text)
  into v_assignee_name
  from public.users
  where id = v_slot.assignee_user_id;

  return jsonb_build_object(
    'userId', v_slot.assignee_user_id,
    'name', v_assignee_name,
    'responsibility', v_responsibility,
    'permissionCode', v_permission_code,
    'scopeType', v_slot.scope_type,
    'scopeId', v_slot.scope_id,
    'resolvedBy', 'responsibility_slot',
    'requestedBy', v_actor_user_id
  );
end;
$$;


--
-- Name: get_effective_permission_sources_authorized(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_effective_permission_sources_authorized(p_target_user_id uuid DEFAULT public.current_app_user_id()) RETURNS TABLE(permission_code text, source_type text, source_id text, source_code text, source_label text, scope_type text, scope_id text, starts_at timestamp with time zone, expires_at timestamp with time zone, risk_level text, is_business_approval boolean, metadata jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := public.current_app_user_id();
begin
  if v_actor_user_id is null then
    raise exception 'Active application account required' using errcode = '42501';
  end if;

  if p_target_user_id <> v_actor_user_id
    and not app_private.has_any_permission(
      v_actor_user_id,
      array[
        'system.authorization.view',
        'system.authorization.audit',
        'system.authorization.manage_roles',
        'system.authorization.manage_grants'
      ],
      'global',
      '*'
    )
  then
    raise exception 'Not allowed to view authorization sources' using errcode = '42501';
  end if;

  return query
  select source_row.*
  from app_private.resolve_effective_permission_sources(
    p_target_user_id,
    null,
    null,
    null,
    now()
  ) source_row
  where not (
      source_row.permission_code like 'hrm.%'
      and source_row.source_type = 'LEGACY'
    )
    and (
      not app_private.is_hrm_template_only_permission(source_row.permission_code)
      or (
        source_row.source_type = 'ROLE'
        and source_row.source_code in ('HR', 'HR_MANAGE')
      )
    );

  return query
  select manager_source.*
  from app_private.resolve_manager_derived_permission_sources(p_target_user_id) manager_source;
end;
$$;


--
-- Name: get_fleet_vehicle_candidates_impl(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_fleet_vehicle_candidates_impl(p_actor_user_id uuid) RETURNS TABLE(asset_id text, asset_code text, asset_name text, asset_image_url text, asset_brand text, asset_model text, category_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_actor_user_id is distinct from public.current_app_user_id() then
    perform app_private.vehicle_raise_permission_denied('Actor mismatch');
  end if;

  if not app_private.vehicle_user_has_permission(
    p_actor_user_id,
    'booking.vehicle.manage_fleet'
  ) then
    perform app_private.vehicle_raise_permission_denied(
      'Fleet management permission required'
    );
  end if;

  return query
  select
    asset.id,
    asset.code,
    asset.name,
    asset.image_url,
    asset.brand,
    asset.model,
    category.name
  from public.assets asset
  join public.asset_categories category on category.id = asset.category_id
  where category.type = 'vehicle'
    and coalesce(asset.asset_type, 'single') = 'single'
    and asset.status::text <> 'DISPOSED'
    and not exists (
      select 1
      from public.fleet_vehicle_profiles profile
      where profile.asset_id = asset.id
    )
  order by asset.code, asset.name;
end;
$$;


--
-- Name: get_fleet_vehicle_profiles_admin_impl(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_fleet_vehicle_profiles_admin_impl(p_actor_user_id uuid) RETURNS TABLE(asset_id text, home_base_id uuid, vehicle_type text, seat_count integer, availability_status text, allow_self_drive boolean, current_odometer numeric, custody_status text, current_custody_assignment_id uuid, inspection_certificate_number text, inspection_expiry_date date, inspection_photo_path text, insurance_expiry_date date, parking_spot_code text, active boolean, created_at timestamp with time zone, updated_at timestamp with time zone, asset_code text, asset_name text, asset_image_url text, asset_brand text, asset_model text, home_base_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_actor_user_id is distinct from public.current_app_user_id() then
    perform app_private.vehicle_raise_permission_denied('Actor mismatch');
  end if;

  if not (
    app_private.vehicle_user_has_permission(
      p_actor_user_id,
      'booking.vehicle.manage_fleet'
    )
    or app_private.vehicle_user_has_permission(
      p_actor_user_id,
      'booking.vehicle.dispatch'
    )
    or app_private.vehicle_user_has_permission(
      p_actor_user_id,
      'booking.vehicle.create'
    )
  ) then
    perform app_private.vehicle_raise_permission_denied(
      'Fleet read permission required'
    );
  end if;

  return query
  select
    profile.asset_id,
    profile.home_base_id,
    profile.vehicle_type,
    profile.seat_count,
    profile.availability_status,
    profile.allow_self_drive,
    profile.current_odometer,
    profile.custody_status,
    profile.current_custody_assignment_id,
    profile.inspection_certificate_number,
    profile.inspection_expiry_date,
    profile.inspection_photo_path,
    profile.insurance_expiry_date,
    profile.parking_spot_code,
    profile.active,
    profile.created_at,
    profile.updated_at,
    asset.code,
    asset.name,
    asset.image_url,
    asset.brand,
    asset.model,
    home_base.name
  from public.fleet_vehicle_profiles profile
  join public.assets asset on asset.id = profile.asset_id
  left join public.fleet_locations home_base on home_base.id = profile.home_base_id
  order by asset.code, asset.name;
end;
$$;


--
-- Name: get_fleet_vehicle_type_options_impl(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_fleet_vehicle_type_options_impl(p_actor_user_id uuid) RETURNS TABLE(vehicle_type text, vehicle_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_actor_user_id is distinct from public.current_app_user_id() then
    perform app_private.vehicle_raise_permission_denied('Actor mismatch');
  end if;

  if not (
    app_private.vehicle_user_has_permission(
      p_actor_user_id,
      'booking.vehicle.manage_authorizations'
    )
    or app_private.vehicle_user_has_permission(
      p_actor_user_id,
      'booking.vehicle.manage_fleet'
    )
    or app_private.vehicle_user_has_permission(
      p_actor_user_id,
      'booking.vehicle.dispatch'
    )
  ) then
    perform app_private.vehicle_raise_permission_denied(
