  where nullif(trim(profile.vehicle_type), '') is not null
  group by trim(profile.vehicle_type)
  order by trim(profile.vehicle_type);
end;
$$;


--
-- Name: get_hrm_employee_attendance_leave(uuid, integer, integer); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_hrm_employee_attendance_leave(p_employee_id uuid, p_year integer DEFAULT (EXTRACT(year FROM CURRENT_DATE))::integer, p_month integer DEFAULT (EXTRACT(month FROM CURRENT_DATE))::integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_level text := app_private.assert_hrm_profile_section_access(
    p_employee_id, array['SELF','MANAGER','HR','HR_MANAGE']
  );
  v_result jsonb;
begin
  if p_month not between 1 and 12 or p_year not between 2000 and 2200 then
    raise exception using errcode = '22023', message = 'HRM_ATTENDANCE_PERIOD_INVALID';
  end if;
  select jsonb_build_object(
    'employeeId', p_employee_id, 'year', p_year, 'month', p_month,
    'attendance', coalesce((select jsonb_agg(jsonb_build_object(
      'id', attendance.id, 'date', attendance.date, 'status', attendance.status,
      'checkIn', attendance."checkIn", 'checkOut', attendance."checkOut",
      'overtimeHours', attendance."overtimeHours", 'approvalStatus', attendance."approvalStatus"
    ) order by attendance.date)
      from public.hrm_attendance attendance
      where attendance."employeeId" = p_employee_id
        and substring(attendance.date from 1 for 7) = format('%s-%s', p_year, lpad(p_month::text, 2, '0'))
    ), '[]'::jsonb),
    'leaveBalance', (select jsonb_build_object(
      'year', balance.year, 'accruedDays', balance."accruedDays",
      'usedPaidDays', balance."usedPaidDays", 'usedUnpaidDays', balance."usedUnpaidDays",
      'remainingDays', balance."accruedDays" - balance."usedPaidDays"
    ) from public.hrm_leave_balances balance
      where balance."employeeId" = p_employee_id and balance.year = p_year limit 1),
    'leaveRequests', coalesce((select jsonb_agg(jsonb_build_object(
      'id', request.id, 'code', request.code, 'type', request.type,
      'startDate', request."startDate", 'endDate', request."endDate",
      'totalDays', request."totalDays", 'status', request.status
    ) order by request."startDate" desc)
      from public.hrm_leave_requests request
      where request."employeeId" = p_employee_id
        and substring(request."startDate" from 1 for 4) = p_year::text
    ), '[]'::jsonb)
  ) into v_result;
  return v_result;
end;
$$;


--
-- Name: get_hrm_employee_compensation_tax_bank(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_hrm_employee_compensation_tax_bank(p_employee_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_level text := app_private.assert_hrm_profile_section_access(p_employee_id, array['HR','HR_MANAGE']);
  v_result jsonb;
begin
  if not app_private.has_hrm_template_permission(public.current_app_user_id(), 'hrm.compensation.view') then
    raise exception using errcode = '42501', message = 'HRM_COMPENSATION_VIEW_REQUIRED';
  end if;
  select jsonb_build_object(
    'employeeId', p_employee_id,
    'taxProfile', (select jsonb_build_object(
      'taxCode', tax.tax_code, 'taxResidencyCode', tax.tax_residency_code,
      'registrationDate', tax.registration_date, 'status', tax.status
    ) from public.hrm_employee_tax_profiles tax where tax.employee_id = p_employee_id),
    'bankAccounts', coalesce((select jsonb_agg(jsonb_build_object(
      'recordCode', bank.record_code, 'bankCode', bank.bank_code,
      'branchName', bank.branch_name, 'accountNumber', bank.account_number,
      'accountHolder', bank.account_holder, 'isPayrollAccount', bank.is_payroll_account,
      'status', bank.status
    ) order by bank.is_payroll_account desc, bank.record_code)
      from public.hrm_employee_bank_accounts bank
      where bank.employee_id = p_employee_id and bank.status = 'ACTIVE'
    ), '[]'::jsonb),
    'salaryHistory', coalesce((select jsonb_agg(jsonb_build_object(
      'id', salary.id, 'effectiveFrom', salary.effective_from,
      'effectiveTo', salary.effective_to, 'previousSalary', salary.previous_salary,
      'newSalary', salary.new_salary, 'previousAllowance', salary.previous_allowance,
      'newAllowance', salary.new_allowance, 'reason', salary.reason, 'status', salary.status
    ) order by salary.effective_from desc)
      from public.hrm_salary_history salary
      where salary.employee_id = p_employee_id and salary.status <> 'VOID'
    ), '[]'::jsonb),
    'recentPayrolls', coalesce((select jsonb_agg(payroll_row.payload order by payroll_row.year desc, payroll_row.month desc)
      from (select payroll.year, payroll.month, jsonb_build_object(
        'id', payroll.id, 'month', payroll.month, 'year', payroll.year,
        'grossSalary', payroll."grossSalary", 'netSalary', payroll."netSalary",
        'status', payroll.status, 'paidDate', payroll."paidDate"
      ) payload from public.hrm_payrolls payroll
      where payroll."employeeId" = p_employee_id
      order by payroll.year desc, payroll.month desc limit 12) payroll_row
    ), '[]'::jsonb)
  ) into v_result;
  return v_result;
end;
$$;


--
-- Name: get_hrm_employee_contract_employment(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_hrm_employee_contract_employment(p_employee_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_level text := app_private.assert_hrm_profile_section_access(p_employee_id, array['HR','HR_MANAGE']);
  v_result jsonb;
begin
  select jsonb_build_object(
    'employeeId', p_employee_id,
    'contracts', coalesce((select jsonb_agg(jsonb_build_object(
      'id', contract.id, 'contractNumber', contract.contract_number,
      'type', contract.type, 'status', contract.status,
      'effectiveFrom', contract.effective_from, 'effectiveTo', contract.effective_to,
      'signedBy', contract.signed_by, 'note', contract.note
    ) order by contract.effective_from desc)
      from public.hrm_labor_contracts contract where contract.employee_id = p_employee_id
    ), '[]'::jsonb),
    'employmentEvents', coalesce((select jsonb_agg(jsonb_build_object(
      'recordCode', event.record_code, 'eventTypeCode', event.event_type_code,
      'eventDate', event.event_date, 'titleSnapshot', event.title_snapshot,
      'reason', event.reason, 'sourceReference', event.source_reference,
      'orgUnitName', org.name, 'positionName', position.name
    ) order by event.event_date desc, event.record_code)
      from public.hrm_employee_employment_events event
      left join public.org_units org on org.id = event.org_unit_id
      left join public.hrm_positions position on position.id = event.position_id
      where event.employee_id = p_employee_id and event.status = 'ACTIVE'
    ), '[]'::jsonb)
  ) into v_result;
  return v_result;
end;
$$;


--
-- Name: get_hrm_employee_legal_insurance(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_hrm_employee_legal_insurance(p_employee_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_level text := app_private.assert_hrm_profile_section_access(p_employee_id, array['HR','HR_MANAGE']);
  v_result jsonb;
begin
  select jsonb_build_object(
    'employeeId', p_employee_id,
    'identityDocuments', coalesce((select jsonb_agg(jsonb_build_object(
      'recordCode', identity_doc.record_code, 'documentTypeCode', identity_doc.document_type_code,
      'documentNumber', identity_doc.document_number, 'issuedDate', identity_doc.issued_date,
      'issuedPlace', identity_doc.issued_place, 'expiryDate', identity_doc.expiry_date,
      'isPrimary', identity_doc.is_primary, 'status', identity_doc.status
    ) order by identity_doc.is_primary desc, identity_doc.record_code)
      from public.hrm_employee_identity_documents identity_doc
      where identity_doc.employee_id = p_employee_id and identity_doc.status <> 'INACTIVE'
    ), '[]'::jsonb),
    'insuranceProfile', (select jsonb_build_object(
      'socialInsuranceNumber', insurance.social_insurance_number,
      'healthInsuranceNumber', insurance.health_insurance_number,
      'registeredClinicCode', insurance.registered_clinic_code,
      'participationStatusCode', insurance.participation_status_code,
      'effectiveFrom', insurance.effective_from, 'effectiveTo', insurance.effective_to,
      'status', insurance.status
    ) from public.hrm_employee_insurance_profiles insurance
      where insurance.employee_id = p_employee_id),
    'dependents', coalesce((select jsonb_agg(jsonb_build_object(
      'recordCode', dependent.record_code, 'fullName', dependent.full_name,
      'relationshipCode', dependent.relationship_code, 'dateOfBirth', dependent.date_of_birth,
      'taxCode', dependent.tax_code, 'deductionFrom', dependent.deduction_from,
      'deductionTo', dependent.deduction_to, 'status', dependent.status
    ) order by dependent.full_name)
      from public.hrm_employee_dependents dependent
      where dependent.employee_id = p_employee_id and dependent.status = 'ACTIVE'
    ), '[]'::jsonb)
  ) into v_result;
  return v_result;
end;
$$;


--
-- Name: get_hrm_employee_overview(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_hrm_employee_overview(p_employee_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_level text := app_private.assert_hrm_profile_section_access(
    p_employee_id, array['DIRECTORY','SELF','MANAGER','HR','HR_MANAGE']
  );
  v_result jsonb;
  v_visible text[];
begin
  v_visible := case
    when v_level in ('HR','HR_MANAGE') then array[
      'overview','personal_contact','work_organization','attendance_leave',
      'contracts_employment','legal_insurance','compensation_tax_bank',
      'qualifications_documents'
    ]
    when v_level in ('SELF','MANAGER') then array[
      'overview','personal_contact','work_organization','attendance_leave',
      'qualifications_documents'
    ]
    else array['overview','work_organization']
  end;

  select jsonb_build_object(
    'employeeId', employee.id,
    'employeeCode', employee.employee_code,
    'fullName', employee.full_name,
    'title', employee.title,
    'status', employee.status,
    'avatarUrl', employee.avatar_url,
    'accessLevel', v_level,
    'visibleSections', to_jsonb(v_visible),
    'maskedFields', case
      when v_level = 'DIRECTORY' then '["dateOfBirth","privateContact","legal","compensation"]'::jsonb
      when v_level = 'MANAGER' then '["privateAddress","emergencyContact","legal","compensation"]'::jsonb
      when v_level = 'SELF' then '["legal","compensation"]'::jsonb
      else '[]'::jsonb
    end,
    'canEditSections', case
      when v_level = 'HR_MANAGE' then '["personal_contact","contracts_employment","legal_insurance","compensation_tax_bank","qualifications_documents"]'::jsonb
      when v_level = 'HR' then '["personal_contact","contracts_employment","legal_insurance","qualifications_documents"]'::jsonb
      when v_level = 'SELF' then '["personal_contact"]'::jsonb
      else '[]'::jsonb
    end,
    'summary', jsonb_build_object(
      'startDate', employee.start_date,
      'officialDate', employee.official_date,
      'orgUnitName', org.name,
      'positionName', position.name,
      'qualificationCount', case when v_level <> 'DIRECTORY' then (
        select count(*) from public.hrm_employee_qualifications qualification
        where qualification.employee_id = employee.id and qualification.status = 'ACTIVE'
      ) else null end,
      'currentContractNumber', case when v_level in ('HR','HR_MANAGE') then (
        select contract.contract_number from public.hrm_labor_contracts contract
        where contract.employee_id = employee.id and contract.status = 'active'
          and contract.effective_from <= current_date
          and (contract.effective_to is null or contract.effective_to >= current_date)
        order by contract.effective_from desc limit 1
      ) else null end
    )
  ) into v_result
  from public.employees employee
  left join public.org_units org on org.id = employee.org_unit_id
  left join public.hrm_positions position on position.id = employee.position_id
  where employee.id = p_employee_id;
  return v_result;
end;
$$;


--
-- Name: get_hrm_employee_personal_contact(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_hrm_employee_personal_contact(p_employee_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_level text := app_private.assert_hrm_profile_section_access(
    p_employee_id, array['SELF','MANAGER','HR','HR_MANAGE']
  );
  v_result jsonb;
begin
  select jsonb_build_object(
    'employeeId', employee.id,
    'gender', employee.gender,
    'dateOfBirth', case when v_level = 'MANAGER' then null else employee.date_of_birth end,
    'maritalStatus', case when v_level = 'MANAGER' then null else employee.marital_status end,
    'workPhone', employee.phone,
    'workEmail', employee.email,
    'personal', case when v_level = 'MANAGER' then null else jsonb_build_object(
      'personalPhone', private_profile.personal_phone,
      'personalEmail', private_profile.personal_email,
      'nationalityCode', private_profile.nationality_code,
      'placeOfBirth', private_profile.place_of_birth,
      'hometown', private_profile.hometown
    ) end,
    'addresses', case when v_level = 'MANAGER' then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object(
        'recordCode', address.record_code, 'addressType', address.address_type,
        'addressLine', address.address_line, 'wardCode', address.ward_code,
        'districtCode', address.district_code, 'provinceCode', address.province_code,
        'countryCode', address.country_code
      ) order by address.address_type, address.record_code)
      from public.hrm_employee_addresses address
      where address.employee_id = employee.id and address.status = 'ACTIVE'
        and address.effective_from <= current_date
        and (address.effective_to is null or address.effective_to >= current_date)
    ), '[]'::jsonb) end,
    'emergencyContacts', case when v_level = 'MANAGER' then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object(
        'recordCode', contact.record_code, 'fullName', contact.full_name,
        'relationshipCode', contact.relationship_code, 'phone', contact.phone,
        'email', contact.email, 'address', contact.address, 'isPrimary', contact.is_primary
      ) order by contact.is_primary desc, contact.record_code)
      from public.hrm_employee_emergency_contacts contact
      where contact.employee_id = employee.id and contact.status = 'ACTIVE'
    ), '[]'::jsonb) end,
    'maskedFields', case when v_level = 'MANAGER'
      then '["dateOfBirth","maritalStatus","personal","addresses","emergencyContacts"]'::jsonb
      else '[]'::jsonb end
  ) into v_result
  from public.employees employee
  left join public.hrm_employee_private_profiles private_profile
    on private_profile.employee_id = employee.id and private_profile.status = 'ACTIVE'
  where employee.id = p_employee_id;
  return v_result;
end;
$$;


--
-- Name: get_hrm_employee_qualifications_documents(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_hrm_employee_qualifications_documents(p_employee_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_level text := app_private.assert_hrm_profile_section_access(
    p_employee_id, array['SELF','MANAGER','HR','HR_MANAGE']
  );
  v_result jsonb;
begin
  select jsonb_build_object(
    'employeeId', p_employee_id,
    'qualifications', coalesce((select jsonb_agg(jsonb_build_object(
      'recordCode', qualification.record_code,
      'educationLevelCode', qualification.education_level_code,
      'institutionName', qualification.institution_name, 'majorName', qualification.major_name,
      'degreeName', qualification.degree_name, 'graduationYear', qualification.graduation_year,
      'startDate', qualification.start_date, 'endDate', qualification.end_date
    ) order by qualification.graduation_year desc nulls last, qualification.record_code)
      from public.hrm_employee_qualifications qualification
      where qualification.employee_id = p_employee_id and qualification.status = 'ACTIVE'
    ), '[]'::jsonb),
    'certifications', coalesce((select jsonb_agg(jsonb_build_object(
      'recordCode', certification.record_code,
      'certificationTypeCode', certification.certification_type_code,
      'certificationName', certification.certification_name,
      'certificateNumber', certification.certificate_number,
      'issuerName', certification.issuer_name, 'issuedDate', certification.issued_date,
      'expiryDate', certification.expiry_date, 'status', certification.status
    ) order by certification.issued_date desc nulls last, certification.record_code)
      from public.hrm_employee_certifications certification
      where certification.employee_id = p_employee_id and certification.status <> 'INACTIVE'
    ), '[]'::jsonb),
    'documents', case when v_level in ('HR','HR_MANAGE') then coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', document.id, 'docType', document.doc_type,
        'docCategory', document.doc_category, 'title', document.title,
        'docNumber', document.doc_number, 'docDate', document.doc_date,
        'deadline', document.deadline, 'status', document.status,
        'fileName', document.file_name, 'fileType', document.file_type,
        'fileSize', document.file_size
      ) order by document.created_at desc)
      from public.hrm_documents document
      where document.employee_id = p_employee_id::text
    ), '[]'::jsonb) else '[]'::jsonb end,
    'maskedFields', case when v_level in ('SELF','MANAGER')
      then '["documents"]'::jsonb else '[]'::jsonb end
  ) into v_result;
  return v_result;
end;
$$;


--
-- Name: get_hrm_employee_work_organization(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_hrm_employee_work_organization(p_employee_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_level text := app_private.assert_hrm_profile_section_access(
    p_employee_id, array['DIRECTORY','SELF','MANAGER','HR','HR_MANAGE']
  );
  v_result jsonb;
begin
  select jsonb_build_object(
    'employeeId', employee.id, 'employeeCode', employee.employee_code,
    'title', employee.title, 'status', employee.status,
    'startDate', employee.start_date, 'officialDate', employee.official_date,
    'orgUnit', jsonb_build_object('id', org.id, 'code', org.code, 'name', org.name),
    'position', jsonb_build_object('id', position.id, 'code', position.code, 'name', position.name, 'levelCode', position.level_code),
    'primaryAssignment', case when assignment.id is null then null else jsonb_build_object(
      'assignmentId', assignment.id, 'slotId', slot.id,
      'effectiveFrom', assignment.effective_from, 'assignmentType', assignment.assignment_type
    ) end,
    'directManager', case when manager_employee.id is null then null else jsonb_build_object(
      'employeeId', manager_employee.id, 'employeeCode', manager_employee.employee_code,
      'fullName', manager_employee.full_name, 'title', manager_employee.title
    ) end
  ) into v_result
  from public.employees employee
  left join public.org_units org on org.id = employee.org_unit_id
  left join public.hrm_positions position on position.id = employee.position_id
  left join public.hrm_employee_slot_assignments assignment
    on assignment.employee_id = employee.id and assignment.assignment_type = 'PRIMARY'
   and assignment.status = 'ACTIVE' and assignment.effective_from <= current_date
   and (assignment.effective_to is null or assignment.effective_to >= current_date)
  left join public.hrm_org_position_slots slot on slot.id = assignment.slot_id
  left join public.users manager_user
    on manager_user.id = app_private.resolve_slot_direct_manager(employee.user_id)
  left join public.employees manager_employee on manager_employee.user_id = manager_user.id
  where employee.id = p_employee_id;
  return v_result;
end;
$$;


--
-- Name: get_hrm_manager_scope_readiness(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_hrm_manager_scope_readiness() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with active_employees as (
    select employee.id, employee.user_id
    from public.employees employee
    where employee.status = 'Đang làm việc'
  ), active_exclusions as (
    select exclusion.employee_id
    from public.hrm_manager_scope_exclusions exclusion
    where exclusion.effective_from <= current_date
      and (exclusion.effective_to is null or exclusion.effective_to >= current_date)
  ), active_primary as (
    select assignment.employee_id, assignment.slot_id, slot.org_unit_id
    from public.hrm_employee_slot_assignments assignment
    join public.hrm_org_position_slots slot on slot.id = assignment.slot_id
    where assignment.assignment_type = 'PRIMARY'
      and assignment.status = 'ACTIVE'
      and assignment.effective_from <= current_date
      and (assignment.effective_to is null or assignment.effective_to >= current_date)
      and slot.status = 'ACTIVE'
      and slot.effective_from <= current_date
      and (slot.effective_to is null or slot.effective_to >= current_date)
  ), overlapping_employees as (
    select distinct first_assignment.employee_id
    from public.hrm_employee_slot_assignments first_assignment
    join public.hrm_employee_slot_assignments second_assignment
      on second_assignment.employee_id = first_assignment.employee_id
     and second_assignment.id > first_assignment.id
     and second_assignment.assignment_type = 'PRIMARY'
     and first_assignment.assignment_type = 'PRIMARY'
     and daterange(first_assignment.effective_from, coalesce(first_assignment.effective_to, 'infinity'::date), '[)')
       && daterange(second_assignment.effective_from, coalesce(second_assignment.effective_to, 'infinity'::date), '[)')
  ), invalid_manager_units as (
    select unit.id
    from public.org_units unit
    left join public.hrm_org_position_slots manager_slot
      on manager_slot.id = unit.manager_slot_id
     and manager_slot.org_unit_id = unit.id
     and manager_slot.status = 'ACTIVE'
    where unit.is_active
      and (
        manager_slot.id is null
        or not exists (
          select 1
          from public.hrm_employee_slot_assignments manager_assignment
          join active_employees manager_employee
            on manager_employee.id = manager_assignment.employee_id
          where manager_assignment.slot_id = manager_slot.id
            and manager_assignment.assignment_type in ('PRIMARY', 'ACTING')
            and manager_assignment.status = 'ACTIVE'
            and manager_assignment.effective_from <= current_date
            and (manager_assignment.effective_to is null or manager_assignment.effective_to >= current_date)
        )
      )
  ), metrics as (
    select
      (select count(*) from active_employees)::integer as active_employee_count,
      (select count(*) from active_primary
       where employee_id in (select id from active_employees))::integer as primary_assigned_count,
      (select count(*) from active_exclusions
       where employee_id in (select id from active_employees))::integer as excluded_count,
      (select count(*) from active_employees employee
       where not exists (select 1 from active_primary assignment where assignment.employee_id = employee.id)
         and not exists (select 1 from active_exclusions exclusion where exclusion.employee_id = employee.id))::integer as missing_primary_count,
      (select count(*) from overlapping_employees)::integer as overlapping_assignment_count,
      (select count(*) from invalid_manager_units)::integer as units_without_manager_count,
      (select count(*)
       from active_employees employee
       where app_private.resolve_slot_direct_manager(employee.user_id) = employee.user_id)::integer as self_managed_count,
      (select is_enabled from app_private.hrm_manager_scope_settings where singleton) as is_enabled
  )
  select jsonb_build_object(
    'activeEmployeeCount', active_employee_count,
    'primaryAssignedCount', primary_assigned_count,
    'excludedCount', excluded_count,
    'missingPrimaryCount', missing_primary_count,
    'overlappingAssignmentCount', overlapping_assignment_count,
    'unitsWithoutManagerCount', units_without_manager_count,
    'selfManagedCount', self_managed_count,
    'isReady', missing_primary_count = 0
      and overlapping_assignment_count = 0
      and units_without_manager_count = 0
      and self_managed_count = 0,
    'isEnabled', coalesce(is_enabled, false)
  )
  from metrics;
$$;


--
-- Name: get_pending_vehicle_booking_approval_cards_impl(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_pending_vehicle_booking_approval_cards_impl(p_actor_user_id uuid) RETURNS TABLE(id uuid, booking_code text, requester_user_id uuid, trip_owner_user_id uuid, requester_employee_id_snapshot uuid, department_id_snapshot uuid, manager_user_id_snapshot uuid, manager_resolution_status text, requested_pickup_at timestamp with time zone, expected_return_at timestamp with time zone, trip_type text, pickup_location_text text, destination_text text, route_stops jsonb, purpose text, passenger_count integer, requested_mode text, preferred_vehicle_asset_id text, preferred_driver_user_id uuid, note text, status text, submitted_at timestamp with time zone, approved_by_user_id uuid, approved_at timestamp with time zone, approval_source text, approval_note text, cancelled_by_user_id uuid, cancelled_at timestamp with time zone, close_reason text, close_note text, created_at timestamp with time zone, updated_at timestamp with time zone, requester_employee_code text, requester_employee_name text, requester_employee_title text, requester_avatar_url text, requester_department_name text, preferred_vehicle_asset_code text, preferred_vehicle_asset_name text, preferred_vehicle_image_url text, preferred_vehicle_type text, preferred_vehicle_seat_count integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_actor_user_id is distinct from public.current_app_user_id() then
    perform app_private.vehicle_raise_permission_denied('Actor mismatch');
  end if;

  if p_actor_user_id is null then
    perform app_private.vehicle_raise_permission_denied('Authentication required');
  end if;

  return query
  select
    booking.id,
    booking.booking_code,
    booking.requester_user_id,
    booking.trip_owner_user_id,
    booking.requester_employee_id_snapshot,
    booking.department_id_snapshot,
    booking.manager_user_id_snapshot,
    booking.manager_resolution_status,
    booking.requested_pickup_at,
    booking.expected_return_at,
    booking.trip_type,
    booking.pickup_location_text,
    booking.destination_text,
    booking.route_stops,
    booking.purpose,
    booking.passenger_count,
    booking.requested_mode,
    booking.preferred_vehicle_asset_id,
    booking.preferred_driver_user_id,
    booking.note,
    booking.status,
    booking.submitted_at,
    booking.approved_by_user_id,
    booking.approved_at,
    booking.approval_source,
    booking.approval_note,
    booking.cancelled_by_user_id,
    booking.cancelled_at,
    booking.close_reason,
    booking.close_note,
    booking.created_at,
    booking.updated_at,
    requester.employee_code::text,
    requester.full_name::text,
    requester.title::text,
    requester.avatar_url,
    requester_department.name,
    asset.code,
    asset.name,
    asset.image_url,
    vehicle.vehicle_type,
    vehicle.seat_count
  from public.vehicle_bookings booking
  left join lateral (
    select employee.*
    from public.employees employee
    where employee.id = booking.requester_employee_id_snapshot
       or employee.user_id = booking.requester_user_id
    order by (employee.id = booking.requester_employee_id_snapshot) desc,
             employee.updated_at desc
    limit 1
  ) requester on true
  left join public.org_units requester_department
    on requester_department.id = coalesce(requester.department_id, booking.department_id_snapshot)
  left join public.fleet_vehicle_profiles vehicle
    on vehicle.asset_id = booking.preferred_vehicle_asset_id
  left join public.assets asset
    on asset.id = booking.preferred_vehicle_asset_id
  where booking.status = 'PENDING_APPROVAL'
    and (
      booking.manager_user_id_snapshot = p_actor_user_id
      or app_private.vehicle_user_has_permission(
        p_actor_user_id,
        'booking.vehicle.approve_direct_reports'
      )
    )
  order by booking.requested_pickup_at, booking.created_at;
end;
$$;


--
-- Name: get_permission_health_summary_impl(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_permission_health_summary_impl() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_base jsonb := app_private.get_permission_health_summary_legacy_base();
  v_anon_sensitive_select jsonb := '[]'::jsonb;
  v_hrm_sensitive_broad_read jsonb := '[]'::jsonb;
  v_hrm_raw_table_exposure jsonb := '[]'::jsonb;
  v_hrm_legacy_admin_policies jsonb := '[]'::jsonb;
  v_hr_sensitive_grant_outside_template jsonb := '[]'::jsonb;
  v_hr_admin_implicit_bypass jsonb := '[]'::jsonb;
  v_hr_template_definition_drift jsonb := '[]'::jsonb;
  v_hrm_manager_readiness jsonb := '[]'::jsonb;
  v_status text := coalesce(v_base ->> 'status', 'ok');
begin
  select coalesce(jsonb_agg(jsonb_build_object(
    'schema', grant_row.table_schema,
    'table', grant_row.table_name,
    'privilege', grant_row.privilege_type,
    'severity', 'critical'
  ) order by grant_row.table_name), '[]'::jsonb)
  into v_anon_sensitive_select
  from information_schema.role_table_grants grant_row
  where grant_row.table_schema = 'public'
    and grant_row.grantee = 'anon'
    and grant_row.privilege_type = 'SELECT'
    and grant_row.table_name ~ '^(employees|hrm_(employee_(private_profiles|addresses|emergency_contacts|identity_documents|tax_profiles|bank_accounts|insurance_profiles|dependents|qualifications|certifications|compensation_assignments|manual_allowances)|employment_events|labor_contracts|salary_history|documents|payrolls|payroll_components))$';

  select coalesce(jsonb_agg(jsonb_build_object(
    'schema', policy_row.schemaname,
    'table', policy_row.tablename,
    'policy', policy_row.policyname,
    'command', policy_row.cmd,
    'severity', 'critical'
  ) order by policy_row.tablename, policy_row.policyname), '[]'::jsonb)
  into v_hrm_sensitive_broad_read
  from pg_policies policy_row
  where policy_row.schemaname = 'public'
    and policy_row.tablename ~ '^(employees|hrm_(employee_(private_profiles|addresses|emergency_contacts|identity_documents|tax_profiles|bank_accounts|insurance_profiles|dependents|qualifications|certifications|compensation_assignments|manual_allowances)|employment_events|labor_contracts|salary_history|documents|payrolls|payroll_components))$'
    and policy_row.cmd in ('SELECT', 'ALL')
    and lower(trim(coalesce(policy_row.qual, ''))) in ('true', '(true)');

  select coalesce(jsonb_agg(jsonb_build_object(
    'schema', grant_row.table_schema,
    'table', grant_row.table_name,
    'privilege', grant_row.privilege_type,
    'grantee', grant_row.grantee,
    'severity', 'high'
  ) order by grant_row.table_name, grant_row.grantee), '[]'::jsonb)
  into v_hrm_raw_table_exposure
  from information_schema.role_table_grants grant_row
  where grant_row.table_schema = 'public'
    and grant_row.grantee in ('anon', 'authenticated')
    and grant_row.privilege_type = 'SELECT'
    and grant_row.table_name ~ '^hrm_(employee_(private_profiles|addresses|emergency_contacts|identity_documents|tax_profiles|bank_accounts|insurance_profiles|dependents|qualifications|certifications|compensation_assignments|manual_allowances)|employment_events|labor_contracts|salary_history|documents|payrolls|payroll_components)$';

  select coalesce(jsonb_agg(finding order by finding ->> 'schema', finding ->> 'function'), '[]'::jsonb)
  into v_hrm_legacy_admin_policies
  from (
    select jsonb_build_object(
      'schema', namespace.nspname,
      'function', procedure.proname,
      'identityArguments', pg_get_function_identity_arguments(procedure.oid),
      'severity', 'high'
    ) as finding
    from pg_proc procedure
    join pg_namespace namespace on namespace.oid = procedure.pronamespace
    where namespace.nspname in ('public', 'app_private')
      and procedure.prokind in ('f', 'p')
      and procedure.proname not like 'get_permission_health_summary%'
      and pg_get_functiondef(procedure.oid) ~* '(hrm_|employees|payroll)'
      and pg_get_functiondef(procedure.oid) ~* '(is_module_admin|system\.hrm\.manage)'
  ) findings;

  select coalesce(jsonb_agg(jsonb_build_object(
    'userId', grant_row.user_id,
    'permissionCode', grant_row.permission_code,
    'scopeType', grant_row.scope_type,
    'scopeId', grant_row.scope_id,
    'severity', 'critical'
  ) order by grant_row.user_id, grant_row.permission_code), '[]'::jsonb)
  into v_hr_sensitive_grant_outside_template
  from public.user_permission_grants grant_row
  where grant_row.is_active
    and (grant_row.expires_at is null or grant_row.expires_at > now())
    and app_private.is_hrm_template_only_permission(grant_row.permission_code);

  select coalesce(jsonb_agg(finding order by finding ->> 'schema', finding ->> 'function'), '[]'::jsonb)
  into v_hr_admin_implicit_bypass
  from (
    select jsonb_build_object(
      'schema', namespace.nspname,
      'function', procedure.proname,
      'identityArguments', pg_get_function_identity_arguments(procedure.oid),
      'severity', 'critical'
    ) as finding
    from pg_proc procedure
    join pg_namespace namespace on namespace.oid = procedure.pronamespace
    where namespace.nspname in ('public', 'app_private')
      and procedure.prokind in ('f', 'p')
      and procedure.proname not like 'get_permission_health_summary%'
      and pg_get_functiondef(procedure.oid) ~* '(hrm_|employees|payroll)'
      and pg_get_functiondef(procedure.oid) ~* '(is_admin\s*\(|role\s*=\s*''ADMIN'')'
  ) findings;

  with expected(template_code, permission_code) as (
    values
      ('HR', 'hrm.organization.view'), ('HR', 'hrm.staffing.view'),
      ('HR', 'hrm.employee.view_directory'), ('HR', 'hrm.employee.view_profile'),
      ('HR', 'hrm.employee.edit_profile'), ('HR', 'hrm.employee.view_sensitive'),
      ('HR', 'hrm.employee.edit_sensitive'), ('HR', 'hrm.employee.import'),
      ('HR', 'hrm.contract.view'), ('HR', 'hrm.contract.manage'),
      ('HR', 'hrm.document.view'), ('HR', 'hrm.document.manage'),
      ('HR', 'hrm.attendance.view'), ('HR', 'hrm.attendance.edit'),
      ('HR', 'hrm.attendance.approve'), ('HR', 'hrm.leave.view'),
      ('HR', 'hrm.leave.approve'), ('HR', 'hrm.compensation.view'),
      ('HR', 'hrm.payroll.view'), ('HR', 'hrm.master_data.view'),
      ('HR_MANAGE', 'hrm.organization.view'), ('HR_MANAGE', 'hrm.staffing.view'),
      ('HR_MANAGE', 'hrm.employee.view_directory'), ('HR_MANAGE', 'hrm.employee.view_profile'),
      ('HR_MANAGE', 'hrm.employee.edit_profile'), ('HR_MANAGE', 'hrm.employee.view_sensitive'),
      ('HR_MANAGE', 'hrm.employee.edit_sensitive'), ('HR_MANAGE', 'hrm.employee.import'),
      ('HR_MANAGE', 'hrm.contract.view'), ('HR_MANAGE', 'hrm.contract.manage'),
      ('HR_MANAGE', 'hrm.document.view'), ('HR_MANAGE', 'hrm.document.manage'),
      ('HR_MANAGE', 'hrm.attendance.view'), ('HR_MANAGE', 'hrm.attendance.edit'),
      ('HR_MANAGE', 'hrm.attendance.approve'), ('HR_MANAGE', 'hrm.leave.view'),
      ('HR_MANAGE', 'hrm.leave.approve'), ('HR_MANAGE', 'hrm.compensation.view'),
      ('HR_MANAGE', 'hrm.payroll.view'), ('HR_MANAGE', 'hrm.master_data.view'),
      ('HR_MANAGE', 'hrm.organization.manage'), ('HR_MANAGE', 'hrm.staffing.manage'),
      ('HR_MANAGE', 'hrm.staffing.assign'), ('HR_MANAGE', 'hrm.staffing.set_manager'),
      ('HR_MANAGE', 'hrm.compensation.manage'), ('HR_MANAGE', 'hrm.payroll.manage'),
      ('HR_MANAGE', 'hrm.master_data.manage'), ('HR_MANAGE', 'hrm.employee.export'),
      ('HR_MANAGE', 'hrm.payroll.export')
  ), actual as (
    select template.code as template_code, item.permission_code
    from public.role_permission_templates template
    join public.role_permission_template_items item on item.template_id = template.id
    where template.code in ('HR', 'HR_MANAGE') and template.is_system and template.is_active
  ), drift as (
    select template_code, permission_code, 'missing'::text as issue from expected
    except select template_code, permission_code, 'missing'::text from actual
    union all
    select template_code, permission_code, 'extra'::text as issue from actual
    except select template_code, permission_code, 'extra'::text from expected
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'roleCode', drift.template_code,
    'permissionCode', drift.permission_code,
    'issueCode', drift.issue,
    'severity', 'high'
  ) order by drift.template_code, drift.issue, drift.permission_code), '[]'::jsonb)
  into v_hr_template_definition_drift
  from drift;

  with readiness as (
    select
      (select count(*)::integer from public.employees employee where employee.status = 'Đang làm việc') as active_employees,
      (select count(distinct assignment_row.employee_id)::integer
       from public.hrm_employee_slot_assignments assignment_row
       join public.employees employee on employee.id = assignment_row.employee_id
       where employee.status = 'Đang làm việc'
         and assignment_row.status = 'ACTIVE'
         and assignment_row.assignment_type = 'PRIMARY') as assigned_employees,
      (select count(*)::integer
       from (
         select assignment_row.employee_id
         from public.hrm_employee_slot_assignments assignment_row
         where assignment_row.status = 'ACTIVE' and assignment_row.assignment_type = 'PRIMARY'
         group by assignment_row.employee_id having count(*) > 1
       ) overlap_row) as overlapping_primary,
      (select count(*)::integer
       from public.org_units unit_row
       where unit_row.is_active
         and unit_row.manager_slot_id is null
         and exists (
           select 1 from public.hrm_org_position_slots slot_row
           where slot_row.org_unit_id = unit_row.id and slot_row.status = 'ACTIVE'
         )) as units_without_manager
  )
  select case
    when active_employees = assigned_employees
      and overlapping_primary = 0
      and units_without_manager = 0
    then '[]'::jsonb
    else jsonb_build_array(jsonb_build_object(
      'activeEmployees', active_employees,
      'assignedEmployees', assigned_employees,
      'missingAssignments', greatest(active_employees - assigned_employees, 0),
      'overlappingPrimaryAssignments', overlapping_primary,
      'unitsWithoutManager', units_without_manager,
      'severity', 'high'
    ))
  end
  into v_hrm_manager_readiness
  from readiness;

  if jsonb_array_length(v_anon_sensitive_select) > 0
    or jsonb_array_length(v_hrm_sensitive_broad_read) > 0
    or jsonb_array_length(v_hr_sensitive_grant_outside_template) > 0
    or jsonb_array_length(v_hr_admin_implicit_bypass) > 0
  then
    v_status := 'critical';
  elsif v_status = 'ok' and (
    jsonb_array_length(v_hrm_raw_table_exposure) > 0
    or jsonb_array_length(v_hrm_legacy_admin_policies) > 0
    or jsonb_array_length(v_hr_template_definition_drift) > 0
    or jsonb_array_length(v_hrm_manager_readiness) > 0
  ) then
    v_status := 'warning';
  end if;

  return v_base || jsonb_build_object(
    'generatedAt', now(),
    'status', v_status,
    'checks', coalesce(v_base -> 'checks', '{}'::jsonb) || jsonb_build_object(
      'anonSensitiveSelect', v_anon_sensitive_select,
      'hrmSensitiveBroadRead', v_hrm_sensitive_broad_read,
      'hrmRawTableExposure', v_hrm_raw_table_exposure,
      'hrmLegacyAdminPolicies', v_hrm_legacy_admin_policies,
      'hrSensitiveGrantOutsideApprovedTemplate', v_hr_sensitive_grant_outside_template,
      'hrAdminImplicitBypass', v_hr_admin_implicit_bypass,
      'hrTemplateDefinitionDrift', v_hr_template_definition_drift,
      'hrmManagerReadiness', v_hrm_manager_readiness
    )
  );
end;
$_$;


--
-- Name: get_permission_health_summary_impl_v2(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_permission_health_summary_impl_v2() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_raw jsonb := app_private.get_permission_health_summary_impl();
  v_base_status text := coalesce(app_private.get_permission_health_summary_legacy_base() ->> 'status', 'ok');
  v_checks jsonb;
  v_admin_bypass jsonb := '[]'::jsonb;
  v_legacy_bypass jsonb := '[]'::jsonb;
  v_status text;
begin
  select coalesce(jsonb_agg(jsonb_build_object(
    'schema', namespace.nspname, 'function', procedure.proname,
    'identityArguments', pg_get_function_identity_arguments(procedure.oid), 'severity', 'critical'
  ) order by namespace.nspname, procedure.proname), '[]'::jsonb)
  into v_admin_bypass
  from pg_proc procedure
  join pg_namespace namespace on namespace.oid = procedure.pronamespace
  where namespace.nspname in ('public','app_private')
    and procedure.prokind in ('f','p')
    and procedure.proname ~* '(hrm|employee|attendance|payroll)'
    and procedure.proname not like 'get_permission_health_summary%'
    and pg_get_functiondef(procedure.oid) ~* '(public\.)?is_(module_)?admin\s*\(';

  select coalesce(jsonb_agg(jsonb_build_object(
    'schema', namespace.nspname, 'function', procedure.proname,
    'identityArguments', pg_get_function_identity_arguments(procedure.oid), 'severity', 'high'
  ) order by namespace.nspname, procedure.proname), '[]'::jsonb)
  into v_legacy_bypass
  from pg_proc procedure
  join pg_namespace namespace on namespace.oid = procedure.pronamespace
  where namespace.nspname in ('public','app_private')
    and procedure.prokind in ('f','p')
    and procedure.proname ~* '(hrm|employee|attendance|payroll)'
    and procedure.proname not like 'get_permission_health_summary%'
    and pg_get_functiondef(procedure.oid) ~* '(is_module_admin|system\.hrm\.manage)';

  v_checks := coalesce(v_raw -> 'checks', '{}'::jsonb) || jsonb_build_object(
    'hrAdminImplicitBypass', v_admin_bypass,
    'hrmLegacyAdminPolicies', v_legacy_bypass
  );
  v_status := v_base_status;
  if jsonb_array_length(coalesce(v_checks -> 'anonSensitiveSelect','[]'::jsonb)) > 0
    or jsonb_array_length(coalesce(v_checks -> 'hrmSensitiveBroadRead','[]'::jsonb)) > 0
    or jsonb_array_length(coalesce(v_checks -> 'hrSensitiveGrantOutsideApprovedTemplate','[]'::jsonb)) > 0
    or jsonb_array_length(v_admin_bypass) > 0
  then v_status := 'critical';
  elsif v_status = 'ok' and (
    jsonb_array_length(coalesce(v_checks -> 'hrmRawTableExposure','[]'::jsonb)) > 0
    or jsonb_array_length(v_legacy_bypass) > 0
    or jsonb_array_length(coalesce(v_checks -> 'hrTemplateDefinitionDrift','[]'::jsonb)) > 0
    or jsonb_array_length(coalesce(v_checks -> 'hrmManagerReadiness','[]'::jsonb)) > 0
  ) then v_status := 'warning';
  end if;
  return v_raw || jsonb_build_object('generatedAt',now(),'status',v_status,'checks',v_checks);
end;
$$;


--
-- Name: get_permission_health_summary_legacy_base(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_permission_health_summary_legacy_base() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_broad_policies jsonb := '[]'::jsonb;
  v_anon_crud jsonb := '[]'::jsonb;
  v_sensitive_without_rls jsonb := '[]'::jsonb;
  v_non_namespaced_actions jsonb := '[]'::jsonb;
  v_legacy_admin_consumers jsonb := '[]'::jsonb;
  v_tables_with_legacy_columns jsonb := '[]'::jsonb;
  v_projects_without_scoped_grants jsonb := '[]'::jsonb;
  v_warehouses_without_scoped_grants jsonb := '[]'::jsonb;
  v_status text := 'ok';
begin
  if not app_private.can_manage_permissions() then
    raise exception 'Not allowed to view permission health'
      using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'schema', p.schemaname,
      'table', p.tablename,
      'policy', p.policyname,
      'command', p.cmd,
      'qual', p.qual,
      'withCheck', p.with_check,
      'severity', 'high'
    )
    order by p.schemaname, p.tablename, p.policyname
  ), '[]'::jsonb)
  into v_broad_policies
  from pg_policies p
  where p.schemaname = 'public'
    and p.tablename <> all(array[
      'app_release_notices',
      'permission_applications',
      'permission_modules',
      'permission_actions'
    ])
    and (
      lower(trim(coalesce(p.qual, ''))) in ('true', '(true)')
      or lower(trim(coalesce(p.with_check, ''))) in ('true', '(true)')
    );

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'schema', g.table_schema,
      'table', g.table_name,
      'privilege', g.privilege_type,
      'severity', 'critical'
    )
    order by g.table_schema, g.table_name, g.privilege_type
  ), '[]'::jsonb)
  into v_anon_crud
  from information_schema.role_table_grants g
  where g.table_schema = 'public'
    and g.grantee = 'anon'
    and g.privilege_type in ('INSERT', 'UPDATE', 'DELETE');

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'schema', n.nspname,
      'table', c.relname,
      'severity', 'critical'
    )
    order by n.nspname, c.relname
  ), '[]'::jsonb)
  into v_sensitive_without_rls
  from pg_class c
  join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public'
    and c.relkind in ('r', 'p')
    and not c.relrowsecurity
    and c.relname <> all(array[
      'schema_migrations',
      'spatial_ref_sys'
    ])
    and (
      c.relname ~ '(user|permission|employee|payroll|attendance|transaction|request|asset|contract|payment|expense|workflow|warehouse)'
    );

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'permissionCode', pa.permission_code,
      'moduleCode', pa.module_code,
      'severity', 'medium'
    )
    order by pa.permission_code
  ), '[]'::jsonb)
  into v_non_namespaced_actions
  from public.permission_actions pa
  where coalesce(pa.is_active, true)
    and (
      pa.permission_code = any(array['view','edit','delete','approve','verify','confirm','submit','manage'])
      or pa.permission_code !~ '^[a-z][a-z0-9_]*(\.[a-z0-9_]+)+$'
    );

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'schema', n.nspname,
      'function', p.proname,
      'identityArguments', pg_get_function_identity_arguments(p.oid),
      'severity', 'medium'
    )
    order by n.nspname, p.proname, pg_get_function_identity_arguments(p.oid)
  ), '[]'::jsonb)
  into v_legacy_admin_consumers
  from pg_proc p
  join pg_namespace n on n.oid = p.pronamespace
  where n.nspname in ('public', 'app_private')
    and p.prokind in ('f', 'p')
    and p.proname <> 'is_module_admin'
    and pg_get_functiondef(p.oid) ilike '%is_module_admin%';

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'schema', c.table_schema,
      'table', c.table_name,
      'columns', c.columns,
      'severity', 'info'
    )
    order by c.table_schema, c.table_name
  ), '[]'::jsonb)
  into v_tables_with_legacy_columns
  from (
    select
      table_schema,
      table_name,
      jsonb_agg(column_name order by column_name) as columns
    from information_schema.columns
    where table_schema = 'public'
      and column_name in ('allowed_modules','admin_modules','allowed_sub_modules','admin_sub_modules')
    group by table_schema, table_name
  ) c;

  if to_regclass('public.projects') is not null then
    execute $q$
      select coalesce(jsonb_agg(
        jsonb_build_object('projectId', p.id, 'severity', 'low')
        order by p.id
      ), '[]'::jsonb)
      from (
        select p.id
        from public.projects p
        where not exists (
          select 1
          from public.user_permission_grants g
          where g.scope_type = 'project'
            and g.scope_id = p.id::text
            and g.permission_code like 'project.%'
            and coalesce(g.is_active, false)
            and (g.expires_at is null or g.expires_at > now())
        )
        order by p.id
        limit 50
      ) p
    $q$
    into v_projects_without_scoped_grants;
  end if;

  if to_regclass('public.warehouses') is not null then
    execute $q$
      select coalesce(jsonb_agg(
        jsonb_build_object('warehouseId', w.id, 'severity', 'low')
        order by w.id
      ), '[]'::jsonb)
      from (
        select w.id
        from public.warehouses w
        where not exists (
          select 1
          from public.user_permission_grants g
          where g.scope_type = 'warehouse'
            and g.scope_id = w.id::text
            and coalesce(g.is_active, false)
            and (g.expires_at is null or g.expires_at > now())
        )
        order by w.id
        limit 50
      ) w
    $q$
    into v_warehouses_without_scoped_grants;
  end if;

  if jsonb_array_length(v_anon_crud) > 0 or jsonb_array_length(v_sensitive_without_rls) > 0 then
    v_status := 'critical';
  elsif jsonb_array_length(v_broad_policies) > 0
    or jsonb_array_length(v_non_namespaced_actions) > 0
    or jsonb_array_length(v_legacy_admin_consumers) > 0 then
    v_status := 'warning';
  end if;

  return jsonb_build_object(
    'generatedAt', now(),
    'status', v_status,
    'legacyProjectionEnabled', app_private.permission_hardening_flag('legacy_projection_enabled'),
    'legacyFallbackDisabled', app_private.permission_hardening_flag('legacy_fallback_disabled'),
    'checks', jsonb_build_object(
      'unmappedRoutes', '[]'::jsonb,
      'broadPolicies', v_broad_policies,
      'anonCrudGrants', v_anon_crud,
      'sensitiveTablesWithoutRls', v_sensitive_without_rls,
      'nonNamespacedPermissionActions', v_non_namespaced_actions,
      'legacyAdminFunctionConsumers', v_legacy_admin_consumers,
      'legacyProjectionColumns', v_tables_with_legacy_columns,
      'projectsWithoutScopedGrants', v_projects_without_scoped_grants,
      'warehousesWithoutScopedGrants', v_warehouses_without_scoped_grants,
      'departmentsWithoutScopedGrants', '[]'::jsonb
    )
  );
end;
$_$;


--
-- Name: get_project_gantt_catalog_impl(text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_project_gantt_catalog_impl(p_project_id text, p_construction_site_id text, p_consumer_room text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := public.current_app_user_id();
  v_site_id text := nullif(btrim(coalesce(p_construction_site_id, '')), '');
  v_result jsonb;
begin
  if p_consumer_room not in (
    'daily_log', 'weekly_progress', 'material_planning',
    'quantity_acceptance', 'quality', 'payment'
  ) or not app_private.project_actor_has_effective_room_action(
    v_actor_user_id, p_project_id, v_site_id, p_consumer_room, 'view'
  ) then
    raise exception 'GANTT_PERMISSION_DENIED' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', task.id,
    'projectId', task.project_id,
    'constructionSiteId', task.construction_site_id,
    'parentId', task.parent_id,
    'name', task.name,
    'wbsCode', task.wbs_code,
    'startDate', task.start_date,
    'endDate', task.end_date,
    'actualStartDate', task.actual_start_date,
    'actualEndDate', task.actual_end_date,
    'duration', task.duration,
    'progress', task.progress,
    'progressMode', task.progress_mode,
    'isMilestone', task.is_milestone,
    'order', task.sort_order,
    'quantity', task.quantity,
    'unit', task.unit,
    'fallbackUnit', task.fallback_unit,
    'provisionalQuantity', task.provisional_quantity,
    'completedQuantity', task.completed_quantity,
    'rowVersion', task.row_version,
    'updatedAt', task.updated_at,
    'contractItemIds', coalesce((
      select jsonb_agg(link.contract_item_id order by link.contract_item_id)
      from public.task_contract_items link where link.task_id = task.id
    ), '[]'::jsonb)
  ) order by task.sort_order, task.id), '[]'::jsonb)
  into v_result
  from public.project_tasks task
  where task.project_id = p_project_id
    and task.construction_site_id is not distinct from v_site_id;

  return v_result;
end;
$$;


--
-- Name: get_project_opening_balance_snapshot_retry_impl(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_project_opening_balance_snapshot_retry_impl(p_opening_balance_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_balance public.project_opening_balances%rowtype;
  v_site_id text;
  v_scope_key text;
  v_week_start date;
  v_snapshot jsonb;
  v_status text;
begin
  if public.current_app_user_id() is null or not (
    public.is_admin()
    or app_private.current_user_is_global_wms_keeper()
  ) then
    raise exception 'Chỉ System Admin hoặc thủ kho tổng được xem trạng thái snapshot đầu kỳ.'
      using errcode = '42501';
  end if;

  select balance.* into v_balance
  from public.project_opening_balances balance
  where balance.id = p_opening_balance_id;

  if not found or v_balance.status <> 'locked' then
    raise exception 'Không tìm thấy dữ liệu đầu kỳ đã khóa.' using errcode = '23514';
  end if;

  v_site_id := nullif(btrim(coalesce(v_balance.construction_site_id, '')), '');
  v_week_start := date_trunc('week', v_balance.as_of_date)::date;
  v_scope_key := app_private.assert_project_progress_scope_period(
    v_balance.project_id, v_site_id, 'weekly', v_week_start
  );
  if v_balance.scope_key is distinct from v_scope_key then
    raise exception 'Opening Balance scope does not match its canonical project/site scope'
      using errcode = '23514';
  end if;

  v_snapshot := jsonb_build_object(
    'constructionProgressPercent', v_balance.construction_progress_percent,
    'valueProgressPercent', case
      when v_balance.contract_value > 0 then least(
        100::numeric,
        round(v_balance.recognized_value / v_balance.contract_value * 100)
      )
      else 0::numeric
    end,
    'progressMode', 'opening_balance',
    'suppliedValue', case when v_balance.recognized_value > 0 then v_balance.recognized_value else null end,
    'contractTotalValue', case when v_balance.contract_value > 0 then v_balance.contract_value else null end,
    'purchasedValue', v_balance.purchased_value,
    'issuedValue', v_balance.issued_value,
    'recognizedValue', v_balance.recognized_value,
    'ganttPercent', v_balance.construction_progress_percent,
    'calculatedAt', now()
  );
  perform app_private.assert_project_progress_snapshot(v_snapshot);
  v_status := case
    when v_balance.progress_snapshot_status = 'synced'
      and (v_balance.progress_snapshot_payload - 'calculatedAt') = (v_snapshot - 'calculatedAt')
    then 'synced'
    else 'pending'
  end;

  return jsonb_build_object(
    'openingBalanceId', v_balance.id,
    'status', v_status,
    'canRetry', v_status = 'pending',
    'scopeKey', v_scope_key,
    'weekStart', v_week_start,
    'refreshedAt', case when v_status = 'synced' then v_balance.progress_snapshot_refreshed_at else null end
  );
end;
$$;


--
-- Name: get_project_progress_period_bundle_impl(text, text, text, date, date, date); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_project_progress_period_bundle_impl(p_project_id text, p_construction_site_id text, p_period_type text, p_period_start date, p_window_from_week date, p_window_to_week date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := public.current_app_user_id();
  v_site_id text := nullif(btrim(coalesce(p_construction_site_id, '')), '');
  v_scope_key text;
  v_period_week date;
  v_state public.project_progress_period_states%rowtype;
  v_state_json jsonb;
  v_tasks jsonb;
  v_daily_rows jsonb;
  v_daily_baseline_rows jsonb;
  v_weekly_rows jsonb;
  v_weekly_baseline_rows jsonb;
  v_selected_weekly_rows jsonb;
begin
  v_scope_key := app_private.assert_project_progress_scope_period(
    p_project_id, v_site_id, p_period_type, p_period_start
  );
  perform app_private.assert_project_progress_action(
    v_actor_id, p_project_id, v_site_id, 'view'
  );

  if (p_window_from_week is null) <> (p_window_to_week is null) then
    raise exception 'windowFromWeek and windowToWeek must both be null or both be provided'
      using errcode = '23514';
  end if;
  if p_window_from_week is not null and (
    extract(isodow from p_window_from_week) <> 1
    or extract(isodow from p_window_to_week) <> 1
    or p_window_from_week > p_window_to_week
  ) then
    raise exception 'progress history window must be an ordered Monday range'
      using errcode = '23514';
  end if;

  v_period_week := p_period_start
    - (extract(isodow from p_period_start)::integer - 1);

  select state.* into v_state
  from public.project_progress_period_states state
  where state.scope_key = v_scope_key
    and state.period_type = p_period_type
    and state.period_start = p_period_start;

  if found then
    v_state_json := app_private.project_progress_period_state_json(v_state);
  else
    v_state_json := jsonb_build_object(
      'id', null,
      'scopeKey', v_scope_key,
      'projectId', p_project_id,
      'constructionSiteId', v_site_id,
      'periodType', p_period_type,
      'periodStart', p_period_start,
      'isLocked', false,
      'lockedBy', null,
      'lockedAt', null,
      'unlockedBy', null,
      'unlockedAt', null,
      'unlockReason', null,
      'createdAt', null,
      'updatedAt', null
    );
  end if;

  with task_links as (
    select
      link.task_id,
      jsonb_agg(link.contract_item_id order by link.contract_item_id) as contract_item_ids
    from public.task_contract_items link
    where link.project_id = p_project_id
      and nullif(link.construction_site_id::text, '') is not distinct from v_site_id
    group by link.task_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', task.id,
    'projectId', task.project_id,
    'constructionSiteId', task.construction_site_id,
    'parentId', task.parent_id,
    'name', task.name,
    'wbsCode', task.wbs_code,
    'startDate', task.start_date,
    'endDate', task.end_date,
    'actualStartDate', task.actual_start_date,
    'actualEndDate', task.actual_end_date,
    'duration', task.duration,
    'progress', task.progress,
    'progressMode', task.progress_mode,
    'isMilestone', task.is_milestone,
    'order', task.sort_order,
    'quantity', task.quantity,
    'unit', task.unit,
    'fallbackUnit', task.fallback_unit,
    'provisionalQuantity', task.provisional_quantity,
    'completedQuantity', task.completed_quantity,
    'rowVersion', task.row_version,
    'updatedAt', task.updated_at,
    'contractItemIds', coalesce(task_links.contract_item_ids, '[]'::jsonb)
  ) order by task.sort_order, task.id), '[]'::jsonb)
  into v_tasks
  from public.project_tasks task
  left join task_links on task_links.task_id = task.id
  where task.project_id = p_project_id
    and nullif(task.construction_site_id::text, '') is not distinct from v_site_id;

  select coalesce(jsonb_agg(to_jsonb(daily_row)
    order by daily_row.progress_date, daily_row.updated_at, daily_row.task_id), '[]'::jsonb)
  into v_daily_rows
  from public.project_daily_task_progress daily_row
  where daily_row.scope_key = v_scope_key
    and daily_row.week_start = v_period_week;

  select coalesce(jsonb_agg(to_jsonb(latest_row)
    order by latest_row.task_id), '[]'::jsonb)
  into v_daily_baseline_rows
  from (
    select distinct on (daily_row.task_id) daily_row.*
    from public.project_daily_task_progress daily_row
    where daily_row.scope_key = v_scope_key
      and daily_row.progress_date < v_period_week
    order by daily_row.task_id, daily_row.progress_date desc, daily_row.updated_at desc
  ) latest_row;

  if p_window_from_week is null then
    select coalesce(jsonb_agg(to_jsonb(weekly_row)
      order by weekly_row.week_start, weekly_row.task_id), '[]'::jsonb)
    into v_weekly_rows
    from public.project_weekly_task_progress weekly_row
    where weekly_row.scope_key = v_scope_key;

    v_weekly_baseline_rows := '[]'::jsonb;
  else
    select coalesce(jsonb_agg(to_jsonb(weekly_row)
      order by weekly_row.week_start, weekly_row.task_id), '[]'::jsonb)
    into v_weekly_rows
    from public.project_weekly_task_progress weekly_row
    where weekly_row.scope_key = v_scope_key
      and weekly_row.week_start >= p_window_from_week
      and weekly_row.week_start <= p_window_to_week;

    select coalesce(jsonb_agg(to_jsonb(latest_row)
      order by latest_row.task_id), '[]'::jsonb)
    into v_weekly_baseline_rows
    from (
      select distinct on (weekly_row.task_id) weekly_row.*
      from public.project_weekly_task_progress weekly_row
      where weekly_row.scope_key = v_scope_key
        and weekly_row.week_start < p_window_from_week
      order by weekly_row.task_id, weekly_row.week_start desc, weekly_row.updated_at desc
    ) latest_row;
  end if;

  if p_period_type = 'daily' then
    select coalesce(jsonb_agg(to_jsonb(weekly_row)
      order by weekly_row.updated_at desc, weekly_row.task_id), '[]'::jsonb)
    into v_selected_weekly_rows
    from public.project_weekly_task_progress weekly_row
    where weekly_row.scope_key = v_scope_key
      and weekly_row.week_start = v_period_week;
  else
    select coalesce(jsonb_agg(to_jsonb(latest_row)
      order by latest_row.task_id), '[]'::jsonb)
    into v_selected_weekly_rows
    from (
      select distinct on (weekly_row.task_id) weekly_row.*
      from public.project_weekly_task_progress weekly_row
      where weekly_row.scope_key = v_scope_key
        and weekly_row.week_start <= p_period_start
      order by weekly_row.task_id, weekly_row.week_start desc, weekly_row.updated_at desc
    ) latest_row;
  end if;

  return jsonb_build_object(
    'state', v_state_json,
    'tasks', v_tasks,
    'dailyRows', v_daily_rows,
    'dailyBaselineRows', v_daily_baseline_rows,
    'weeklyRows', v_weekly_rows,
    'weeklyBaselineRows', v_weekly_baseline_rows,
    'selectedWeeklyRows', v_selected_weekly_rows,
    'windowFromWeek', p_window_from_week,
    'windowToWeek', p_window_to_week
  );
end;
$$;


--
-- Name: get_project_progress_period_state_impl(text, text, text, date); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_project_progress_period_state_impl(p_project_id text, p_construction_site_id text, p_period_type text, p_period_start date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := public.current_app_user_id();
  v_site_id text := nullif(btrim(coalesce(p_construction_site_id, '')), '');
  v_scope_key text;
  v_state public.project_progress_period_states%rowtype;
begin
  v_scope_key := app_private.assert_project_progress_scope_period(
    p_project_id, v_site_id, p_period_type, p_period_start
  );
  perform app_private.assert_project_progress_action(
    v_actor_id, p_project_id, v_site_id, 'view'
  );

  select state.* into v_state
  from public.project_progress_period_states state
  where state.scope_key = v_scope_key
    and state.period_type = p_period_type
    and state.period_start = p_period_start;

  if found then
    return app_private.project_progress_period_state_json(v_state);
  end if;

  return jsonb_build_object(
    'id', null,
    'scopeKey', v_scope_key,
    'projectId', p_project_id,
    'constructionSiteId', v_site_id,
    'periodType', p_period_type,
    'periodStart', p_period_start,
    'isLocked', false,
    'lockedBy', null,
    'lockedAt', null,
    'unlockedBy', null,
    'unlockedAt', null,
    'unlockReason', null,
    'createdAt', null,
    'updatedAt', null
  );
end;
$$;


--
-- Name: get_safety_card_by_qr(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_safety_card_by_qr(p_qr_token text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_result jsonb;
begin
  if public.current_app_user_id() is null or nullif(trim(p_qr_token), '') is null then
    return null;
  end if;

  select app_private.safety_workforce_card_json(card)
    || jsonb_build_object(
      'worker', jsonb_build_object(
        'id', worker.id,
        'workerCode', worker.worker_code,
        'fullName', worker.full_name,
        'workerKind', worker.worker_kind,
        'phone', worker.phone,
        'status', worker.status,
        'photoAttachment', worker.photo_attachment
      ),
      'assignment', app_private.safety_workforce_assignment_json(assignment),
      'contractor', case when subcontractor.id is null then null else jsonb_build_object(
        'id', subcontractor.id,
        'name', subcontractor.name,
        'code', subcontractor.code,
        'status', subcontractor.status
      ) end
    )
  into v_result
  from public.safety_cards card
  join public.safety_project_assignments assignment on assignment.id = card.assignment_id
  join public.safety_worker_site_memberships membership on membership.id = assignment.membership_id
  join public.safety_worker_profiles worker on worker.id = membership.worker_id
  left join public.safety_subcontractors subcontractor on subcontractor.id = assignment.subcontractor_id
  where card.qr_token = trim(p_qr_token)
    and app_private.safety_workforce_can_view(membership.project_id, membership.construction_site_id)
  limit 1;

  return v_result;
end;
$$;


--
-- Name: get_safety_passport_dashboard(text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_safety_passport_dashboard(p_project_id text, p_construction_site_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_result jsonb;
begin
  perform app_private.safety_workforce_assert_scope(p_project_id, p_construction_site_id);
  if not app_private.safety_workforce_can_view(p_project_id, p_construction_site_id) then
    raise exception 'SAFETY_SCOPE_MISMATCH: actor cannot view target site'
      using errcode = '42501';
  end if;

  with scoped_memberships as materialized (
    select membership.id, membership.worker_id
    from public.safety_worker_site_memberships membership
    where membership.project_id = p_project_id
      and membership.construction_site_id = p_construction_site_id
  ),
  active_assignments as materialized (
    select assignment.id,
           assignment.worker_id,
           assignment.subcontractor_id,
           assignment.eligibility_status
    from public.safety_project_assignments assignment
    join scoped_memberships membership on membership.id = assignment.membership_id
    where assignment.assignment_status = 'active'
  ),
  certificate_metrics as (
    select
      count(*) filter (
        where certificate.expiry_date between current_date and current_date + 7
          and certificate.status not in ('rejected', 'revoked')
      ) as expiring_7,
      count(*) filter (
        where certificate.expiry_date between current_date and current_date + 30
          and certificate.status not in ('rejected', 'revoked')
      ) as expiring_30,
      count(*) filter (
        where certificate.expiry_date < current_date
          and certificate.status not in ('rejected', 'revoked')
      ) as expired
    from public.safety_worker_certificates certificate
    join scoped_memberships membership on membership.worker_id = certificate.worker_id
  ),
  card_metrics as (
    select count(*) filter (
      where card.status = 'active'
        and card.expires_at between current_date and current_date + 30
    ) as expiring_30
    from public.safety_cards card
    join active_assignments assignment on assignment.id = card.assignment_id
  ),
  problematic_subcontractors as (
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', issue.id,
      'name', issue.name,
      'issueCount', issue.issue_count
    ) order by issue.issue_count desc, issue.name), '[]'::jsonb) as items
    from (
      select subcontractor.id,
             subcontractor.name,
             count(*)::integer as issue_count
      from active_assignments assignment
      join public.safety_subcontractors subcontractor on subcontractor.id = assignment.subcontractor_id
      where assignment.eligibility_status <> 'eligible'
      group by subcontractor.id, subcontractor.name
      order by count(*) desc, subcontractor.name
      limit 10
    ) issue
  )
  select jsonb_build_object(
    'totalWorkers', (select count(*) from scoped_memberships),
    'activeAssignments', (select count(*) from active_assignments),
    'eligibleAssignments', (select count(*) from active_assignments where eligibility_status = 'eligible'),
    'missingProfile', (select count(*) from active_assignments where eligibility_status = 'missing_profile'),
    'missingCertificate', (select count(*) from active_assignments where eligibility_status = 'missing_certificate'),
    'expiredCertificate', (select count(*) from active_assignments where eligibility_status = 'expired_certificate'),
    'missingSiteRequirement', (select count(*) from active_assignments where eligibility_status = 'missing_site_requirement'),
    'suspendedAssignments', (select count(*) from active_assignments where eligibility_status = 'suspended'),
    'expiringCertificates7Days', coalesce(certificate_metrics.expiring_7, 0),
    'expiringCertificates30Days', coalesce(certificate_metrics.expiring_30, 0),
    'expiredCertificates', coalesce(certificate_metrics.expired, 0),
    'expiringCards30Days', coalesce(card_metrics.expiring_30, 0),
    'problematicSubcontractors', problematic_subcontractors.items
  )
  into v_result
  from certificate_metrics
  cross join card_metrics
  cross join problematic_subcontractors;

  return v_result;
end;
$$;


--
-- Name: get_safety_site_worker_detail(text, uuid, uuid, boolean); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_safety_site_worker_detail(p_project_id text, p_construction_site_id uuid, p_membership_id uuid, p_include_sensitive boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_membership public.safety_worker_site_memberships%rowtype;
  v_worker public.safety_worker_profiles%rowtype;
  v_result jsonb;
begin
  perform app_private.safety_workforce_assert_scope(p_project_id, p_construction_site_id);
  if not app_private.safety_workforce_can_view(p_project_id, p_construction_site_id) then
    raise exception 'SAFETY_SCOPE_MISMATCH: actor cannot view target site'
      using errcode = '42501';
  end if;
  if p_include_sensitive and not app_private.safety_workforce_can_view_sensitive(p_project_id, p_construction_site_id) then
    raise exception 'SAFETY_SCOPE_MISMATCH: actor cannot view sensitive worker detail'
      using errcode = '42501';
  end if;

  select membership.*
  into v_membership
  from public.safety_worker_site_memberships membership
  where membership.id = p_membership_id
    and membership.project_id = p_project_id
    and membership.construction_site_id = p_construction_site_id;

  if not found then
    raise exception 'SAFETY_SCOPE_MISMATCH: membership is outside target site'
      using errcode = '42501';
  end if;

  select worker.*
  into v_worker
  from public.safety_worker_profiles worker
  where worker.id = v_membership.worker_id;

  with active_assignment as materialized (
    select assignment as value
    from public.safety_project_assignments assignment
    where assignment.membership_id = v_membership.id
      and assignment.assignment_status = 'active'
    order by assignment.started_at desc, assignment.id desc
    limit 1
  ),
  active_card as materialized (
    select card as value
    from public.safety_cards card
    join active_assignment active_assignment_row
      on (active_assignment_row.value).id = card.assignment_id
    where card.status = 'active'
    order by card.issued_at desc, card.id desc
    limit 1
  )
  select jsonb_build_object(
    'rosterItem', jsonb_build_object(
      'membership', jsonb_build_object(
        'id', v_membership.id,
        'workerId', v_membership.worker_id,
        'projectId', v_membership.project_id,
        'constructionSiteId', v_membership.construction_site_id,
        'defaultSubcontractorId', v_membership.default_subcontractor_id,
        'defaultTeamId', v_membership.default_team_id,
        'status', v_membership.status,
        'firstJoinedAt', v_membership.first_joined_at,
        'lastLeftAt', v_membership.last_left_at,
        'source', v_membership.source
      ),
      'worker', jsonb_build_object(
        'id', v_worker.id,
        'workerCode', v_worker.worker_code,
        'fullName', v_worker.full_name,
        'workerKind', v_worker.worker_kind,
        'phone', v_worker.phone,
        'status', v_worker.status,
        'photoStoragePath', coalesce(
          v_worker.photo_attachment ->> 'storagePath',
          v_worker.photo_attachment ->> 'storage_path',
          case
            when coalesce(v_worker.photo_attachment ->> 'url', '') !~* '^https?://' then v_worker.photo_attachment ->> 'url'
            else null
          end
        )
      ),
      'subcontractor', case when subcontractor.id is null then null else jsonb_build_object(
        'id', subcontractor.id,
        'name', subcontractor.name,
        'code', subcontractor.code,
        'status', subcontractor.status
      ) end,
      'team', case when team.id is null then null else jsonb_build_object(
        'id', team.id,
        'name', team.name,
        'code', team.code,
        'status', team.status
      ) end,
      'activeAssignment', case when (active_assignment_row.value).id is null then null
        else app_private.safety_workforce_assignment_json(active_assignment_row.value)
      end,
      'activeCard', case when (active_card_row.value).id is null then null
        else app_private.safety_workforce_card_json(active_card_row.value)
      end,
      'identityNumberMasked', coalesce(app_private.safety_workforce_mask_identity(v_worker.id), '-'),
      'profileStatus', coalesce(app_private.safety_workforce_profile_readiness(v_worker.id), 'missing'),
      'healthStatus', app_private.safety_workforce_document_readiness(v_worker.id, 'health_check'),
      'insuranceStatus', app_private.safety_workforce_document_readiness(v_worker.id, 'insurance')
    ),
    'profile', jsonb_build_object(
      'id', v_worker.id,
      'workerCode', v_worker.worker_code,
      'fullName', v_worker.full_name,
      'workerKind', v_worker.worker_kind,
      'phone', v_worker.phone,
      'dateOfBirth', v_worker.date_of_birth,
      'roleName', v_worker.role_name,
      'status', v_worker.status,
      'photoAttachment', v_worker.photo_attachment
    ) || case when p_include_sensitive then jsonb_build_object(
      'identityType', v_worker.identity_type,
      'identityNumber', v_worker.identity_number,
      'identityIssueDate', v_worker.identity_issue_date,
      'identityIssuePlace', v_worker.identity_issue_place,
      'permanentAddress', v_worker.permanent_address
    ) else '{}'::jsonb end,
    'documents', case when p_include_sensitive then coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', document.id,
        'workerId', document.worker_id,
        'documentType', document.document_type,
        'name', document.name,
        'issueDate', document.issue_date,
        'expiryDate', document.expiry_date,
        'attachments', document.attachments,
        'status', document.status,
        'isRequired', document.is_required,
        'note', document.note,
        'createdBy', document.created_by,
        'createdAt', document.created_at,
        'updatedAt', document.updated_at
      ) order by document.document_type, document.created_at desc)
      from public.safety_worker_documents document
      where document.worker_id = v_worker.id
    ), '[]'::jsonb) else '[]'::jsonb end,
    'certificates', case when p_include_sensitive then coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', certificate.id,
        'workerId', certificate.worker_id,
        'certificateTypeId', certificate.certificate_type_id,
        'certificateNo', certificate.certificate_no,
        'issueDate', certificate.issue_date,
        'expiryDate', certificate.expiry_date,
        'attachments', certificate.attachments,
        'status', certificate.status,
        'computedStatus', case
          when certificate.status = 'rejected' then 'rejected'
          when certificate.status = 'revoked' then 'revoked'
          when certificate.expiry_date < current_date then 'expired'
          when certificate.expiry_date <= current_date + 30 then 'expiring_soon'
          else 'valid'
        end,
        'verifiedBy', certificate.verified_by,
        'verifiedAt', certificate.verified_at,
        'note', certificate.note,
        'createdBy', certificate.created_by,
        'createdAt', certificate.created_at,
        'updatedAt', certificate.updated_at
      ) order by certificate.expiry_date desc nulls last, certificate.created_at desc)
      from public.safety_worker_certificates certificate
      where certificate.worker_id = v_worker.id
    ), '[]'::jsonb) else '[]'::jsonb end,
    'assignments', coalesce((
      select jsonb_agg(app_private.safety_workforce_assignment_json(assignment_history)
        order by assignment_history.started_at desc, assignment_history.id desc)
      from public.safety_project_assignments assignment_history
      where assignment_history.membership_id = v_membership.id
    ), '[]'::jsonb),
    'cards', coalesce((
      select jsonb_agg(app_private.safety_workforce_card_json(card_history)
        order by card_history.issued_at desc, card_history.id desc)
      from public.safety_cards card_history
      join public.safety_project_assignments assignment_history
        on assignment_history.id = card_history.assignment_id
      where assignment_history.membership_id = v_membership.id
    ), '[]'::jsonb),
    'capabilities', app_private.safety_workforce_capabilities(p_project_id, p_construction_site_id),
    'sensitiveLoaded', p_include_sensitive
  )
  into v_result
  from (select 1) anchor
  left join public.safety_subcontractors subcontractor on subcontractor.id = v_membership.default_subcontractor_id
  left join public.safety_teams team on team.id = v_membership.default_team_id
  left join active_assignment active_assignment_row on true
  left join active_card active_card_row on true;

  return v_result;
end;
$$;


--
-- Name: get_user_hr_authorization_impl(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_user_hr_authorization_impl(p_target_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := public.current_app_user_id();
  v_target public.users%rowtype;
  v_employee_id uuid;
  v_employee_code text;
  v_assignment_id uuid;
  v_hr_role text;
  v_starts_at timestamptz;
  v_expires_at timestamptz;
  v_direct_report_count integer := 0;
  v_effective_permissions jsonb := '[]'::jsonb;
  v_history jsonb := '[]'::jsonb;
begin
  if v_actor_user_id is null
    or (
      v_actor_user_id is distinct from p_target_user_id
      and not app_private.has_any_permission(
        v_actor_user_id,
        array[
          'system.authorization.view',
          'system.authorization.audit',
          'system.authorization.manage_roles',
          'system.authorization.manage_grants'
        ],
        'global',
        '*'
      )
    )
  then
    raise exception 'Not allowed to view HR authorization'
      using errcode = '42501';
  end if;

  select * into v_target
  from public.users target_row
  where target_row.id = p_target_user_id;

  if v_target.id is null then
    raise exception 'Target user does not exist'
      using errcode = 'P0002';
  end if;

  select employee.id, employee.employee_code
  into v_employee_id, v_employee_code
  from public.employees employee
  where employee.user_id = p_target_user_id
  order by employee.created_at
  limit 1;

  select assignment_row.id, template.code, assignment_row.starts_at, assignment_row.expires_at
  into v_assignment_id, v_hr_role, v_starts_at, v_expires_at
  from public.principal_role_assignments assignment_row
  join public.role_permission_templates template
    on template.id = assignment_row.role_template_id
   and template.code in ('HR', 'HR_MANAGE')
  where assignment_row.principal_type = 'user'
    and assignment_row.principal_id = p_target_user_id
    and assignment_row.status = 'ACTIVE'
    and assignment_row.starts_at <= now()
    and (assignment_row.expires_at is null or assignment_row.expires_at > now())
  order by case template.code when 'HR_MANAGE' then 0 else 1 end,
           assignment_row.created_at desc
  limit 1;

  select count(*)::integer into v_direct_report_count
  from public.employees report
  where report.user_id is not null
    and report.user_id is distinct from p_target_user_id
    and report.status = 'Đang làm việc'
    and app_private.resolve_slot_direct_manager(report.user_id) = p_target_user_id;

  select coalesce(jsonb_agg(jsonb_build_object(
    'permissionCode', source_row.permission_code,
    'sourceType', source_row.source_type,
    'sourceId', source_row.source_id,
    'sourceCode', source_row.source_code,
    'sourceLabel', source_row.source_label,
    'scopeType', source_row.scope_type,
    'scopeId', source_row.scope_id,
    'startsAt', source_row.starts_at,
    'expiresAt', source_row.expires_at,
    'riskLevel', source_row.risk_level,
    'isBusinessApproval', source_row.is_business_approval,
    'metadata', source_row.metadata
  ) order by source_row.permission_code, source_row.scope_type, source_row.scope_id), '[]'::jsonb)
  into v_effective_permissions
  from app_private.resolve_effective_permission_sources(
    p_target_user_id, null, null, null, now()
  ) source_row
  where source_row.permission_code like 'hrm.%'
    and not (source_row.source_type = 'LEGACY')
    and (
      source_row.permission_code <> all(array[
        'hrm.organization.manage',
        'hrm.staffing.manage', 'hrm.staffing.assign', 'hrm.staffing.set_manager',
        'hrm.employee.view_sensitive', 'hrm.employee.edit_sensitive',
        'hrm.employee.import', 'hrm.employee.export',
        'hrm.contract.view', 'hrm.contract.manage',
        'hrm.document.view', 'hrm.document.manage',
        'hrm.compensation.view', 'hrm.compensation.manage',
        'hrm.payroll.manage', 'hrm.payroll.export',
        'hrm.master_data.manage'
      ]::text[])
      or (
        source_row.source_type = 'ROLE'
        and source_row.source_code in ('HR', 'HR_MANAGE')
      )
    );

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', history_row.id,
    'eventType', history_row.event_type,
    'actorUserId', history_row.actor_user_id,
    'actorName', history_row.actor_name,
    'createdAt', history_row.created_at,
    'metadata', history_row.metadata
  ) order by history_row.created_at desc), '[]'::jsonb)
  into v_history
  from (
    select event_row.id, event_row.event_type, event_row.actor_user_id,
           actor_row.name as actor_name, event_row.created_at, event_row.metadata
    from public.permission_audit_events event_row
    left join public.users actor_row on actor_row.id = event_row.actor_user_id
    where event_row.target_user_id = p_target_user_id
      and (
        event_row.event_type like 'hr_business_role_%'
        or event_row.event_type in ('business_role_assigned', 'business_role_revoked')
      )
    order by event_row.created_at desc
    limit 50
  ) history_row;

  return jsonb_build_object(
    'targetUserId', v_target.id,
    'systemRole', v_target.role,
    'employeeId', v_employee_id,
    'employeeCode', v_employee_code,
    'isDirectManager', v_direct_report_count > 0,
    'directReportCount', v_direct_report_count,
    'hrRole', v_hr_role,
    'assignmentId', v_assignment_id,
    'startsAt', v_starts_at,
    'expiresAt', v_expires_at,
    'fingerprint', app_private.hrm_authorization_fingerprint(p_target_user_id),
    'effectivePermissions', v_effective_permissions,
    'history', v_history
  );
end;
$$;


--
-- Name: get_vehicle_booking_analytics_phase3_impl(timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_vehicle_booking_analytics_phase3_impl(p_from_at timestamp with time zone, p_to_at timestamp with time zone, p_department_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_completed_trips bigint := 0;
  v_on_time_eligible bigint := 0;
  v_on_time_trips bigint := 0;
  v_submitted_bookings bigint := 0;
  v_late_cancelled bigint := 0;
  v_used_vehicle_minutes numeric := 0;
  v_available_vehicle_minutes numeric := 0;
  v_total_capacity_minutes numeric := 0;
  v_unavailable_vehicle_minutes numeric := 0;
  v_distance_by_vehicle jsonb := '[]'::jsonb;
  v_fulfillment_breakdown jsonb := '[]'::jsonb;
  v_external_cost_by_department jsonb := '[]'::jsonb;
begin
  if p_from_at is null or p_to_at is null or p_to_at <= p_from_at then
    raise exception using errcode = '22023', message = 'INVALID_REPORTING_PERIOD';
  end if;

  perform app_private.vehicle_require_report_scope(
    public.current_app_user_id(),
    p_department_id
  );

  with report_bookings as (
    select b.*
    from public.vehicle_bookings b
    where b.requested_pickup_at >= p_from_at
      and b.requested_pickup_at < p_to_at
      and (p_department_id is null or b.department_id_snapshot = p_department_id)
  ), completed_rows as (
    select
      b.id,
      b.requested_pickup_at,
      a.id as assignment_id,
      a.fulfillment_type,
      t.actual_pickup_at
    from report_bookings b
    left join public.vehicle_booking_assignments a
      on a.booking_id = b.id and a.is_active
    left join public.vehicle_trip_logs t
      on t.booking_id = b.id
    where b.status = 'COMPLETED'
  )
  select
    count(*)::bigint,
    count(*) filter (
      where completed_rows.fulfillment_type in (
        'INTERNAL_WITH_DRIVER', 'INTERNAL_SELF_DRIVE'
      )
      and completed_rows.actual_pickup_at is not null
    )::bigint,
    count(*) filter (
      where completed_rows.fulfillment_type in (
        'INTERNAL_WITH_DRIVER', 'INTERNAL_SELF_DRIVE'
      )
      and completed_rows.actual_pickup_at is not null
      and completed_rows.actual_pickup_at <= completed_rows.requested_pickup_at
        + make_interval(mins => settings.on_time_tolerance_minutes)
    )::bigint
  into v_completed_trips, v_on_time_eligible, v_on_time_trips
  from completed_rows
  cross join public.fleet_system_settings settings
  where settings.id = 1;

  select
    count(*) filter (where b.status <> 'DRAFT')::bigint,
    count(*) filter (where b.close_reason = 'LATE_CANCELLED')::bigint
  into v_submitted_bookings, v_late_cancelled
  from public.vehicle_bookings b
  where b.requested_pickup_at >= p_from_at
    and b.requested_pickup_at < p_to_at
    and (p_department_id is null or b.department_id_snapshot = p_department_id);

  select coalesce(sum(
    extract(epoch from (
      least(coalesce(t.actual_return_at, least(now(), p_to_at)), p_to_at)
      - greatest(t.departed_home_base_at, p_from_at)
    )) / 60.0
  ), 0)
  into v_used_vehicle_minutes
  from public.vehicle_trip_logs t
  join public.vehicle_bookings b on b.id = t.booking_id
  join public.vehicle_booking_assignments a on a.id = t.assignment_id
  where a.fulfillment_type in ('INTERNAL_WITH_DRIVER', 'INTERNAL_SELF_DRIVE')
    and t.departed_home_base_at is not null
    and t.departed_home_base_at < p_to_at
    and coalesce(t.actual_return_at, least(now(), p_to_at)) > p_from_at
    and (p_department_id is null or b.department_id_snapshot = p_department_id);

  select count(*) * extract(epoch from (p_to_at - p_from_at)) / 60.0
  into v_total_capacity_minutes
  from public.fleet_vehicle_profiles profile
  where profile.active;

  select coalesce(sum(
    extract(epoch from (
      least(period.end_at, p_to_at) - greatest(period.start_at, p_from_at)
    )) / 60.0
  ), 0)
  into v_unavailable_vehicle_minutes
  from public.vehicle_unavailability_periods period
  join public.fleet_vehicle_profiles profile
    on profile.asset_id = period.vehicle_asset_id and profile.active
  where period.start_at < p_to_at
    and period.end_at > p_from_at;

  v_available_vehicle_minutes := greatest(
    v_total_capacity_minutes - v_unavailable_vehicle_minutes,
    0
  );

  select coalesce(jsonb_agg(jsonb_build_object(
    'vehicleAssetId', distance_rows.vehicle_asset_id,
    'vehicleCode', distance_rows.vehicle_code,
    'vehicleName', distance_rows.vehicle_name,
    'distanceKm', distance_rows.distance_km,
    'tripCount', distance_rows.trip_count
  ) order by distance_rows.distance_km desc, distance_rows.vehicle_code), '[]'::jsonb)
  into v_distance_by_vehicle
  from (
    select
      t.vehicle_asset_id_snapshot as vehicle_asset_id,
      coalesce(asset.code, t.vehicle_asset_id_snapshot) as vehicle_code,
      coalesce(asset.name, t.vehicle_asset_id_snapshot) as vehicle_name,
      round(coalesce(sum(t.distance_km), 0)::numeric, 1) as distance_km,
      count(*)::bigint as trip_count
    from public.vehicle_trip_logs t
    join public.vehicle_bookings b on b.id = t.booking_id
    left join public.assets asset on asset.id = t.vehicle_asset_id_snapshot
    where b.requested_pickup_at >= p_from_at
      and b.requested_pickup_at < p_to_at
      and (p_department_id is null or b.department_id_snapshot = p_department_id)
      and t.trip_status = 'FINISHED'
      and t.vehicle_asset_id_snapshot is not null
    group by t.vehicle_asset_id_snapshot, asset.code, asset.name
  ) distance_rows;

  select coalesce(jsonb_agg(jsonb_build_object(
    'fulfillmentType', fulfillment_rows.fulfillment_type,
    'tripCount', fulfillment_rows.trip_count
  ) order by fulfillment_rows.fulfillment_type), '[]'::jsonb)
  into v_fulfillment_breakdown
  from (
    select a.fulfillment_type, count(*)::bigint as trip_count
    from public.vehicle_bookings b
    join public.vehicle_booking_assignments a
      on a.booking_id = b.id and a.is_active
    where b.requested_pickup_at >= p_from_at
      and b.requested_pickup_at < p_to_at
      and (p_department_id is null or b.department_id_snapshot = p_department_id)
      and b.status = 'COMPLETED'
    group by a.fulfillment_type
  ) fulfillment_rows;

  select coalesce(jsonb_agg(jsonb_build_object(
    'departmentId', cost_rows.department_id,
    'departmentName', cost_rows.department_name,
    'actualCost', cost_rows.actual_cost,
    'tripCount', cost_rows.trip_count
  ) order by cost_rows.actual_cost desc, cost_rows.department_name), '[]'::jsonb)
  into v_external_cost_by_department
  from (
    select
      b.department_id_snapshot as department_id,
      coalesce(org.name, 'Chưa xác định') as department_name,
      round(coalesce(sum(a.external_actual_cost), 0)::numeric, 2) as actual_cost,
      count(*)::bigint as trip_count
    from public.vehicle_bookings b
    join public.vehicle_booking_assignments a
      on a.booking_id = b.id and a.is_active
    left join public.org_units org on org.id = b.department_id_snapshot
    where b.requested_pickup_at >= p_from_at
      and b.requested_pickup_at < p_to_at
      and (p_department_id is null or b.department_id_snapshot = p_department_id)
      and b.status = 'COMPLETED'
      and a.fulfillment_type = 'EXTERNAL_TRANSPORT'
    group by b.department_id_snapshot, org.name
  ) cost_rows;

  return jsonb_build_object(
    'period', jsonb_build_object(
      'fromAt', p_from_at,
      'toAt', p_to_at,
      'timeZone', 'Asia/Ho_Chi_Minh'
    ),
    'scope', jsonb_build_object(
      'departmentId', p_department_id,
      'capacityDenominator', 'CURRENT_ACTIVE_COMPANY_FLEET'
    ),
    'kpis', jsonb_build_object(
      'completedTrips', v_completed_trips,
      'onTimeEligibleTrips', v_on_time_eligible,
      'onTimeTrips', v_on_time_trips,
      'onTimeRate', case when v_on_time_eligible = 0 then null
        else round(100.0 * v_on_time_trips / v_on_time_eligible, 1) end,
      'submittedBookings', v_submitted_bookings,
      'lateCancelledBookings', v_late_cancelled,
      'lateCancellationRate', case when v_submitted_bookings = 0 then null
        else round(100.0 * v_late_cancelled / v_submitted_bookings, 1) end,
      'usedVehicleMinutes', round(v_used_vehicle_minutes, 1),
      'availableVehicleMinutes', round(v_available_vehicle_minutes, 1),
      'vehicleUtilizationRate', case when v_available_vehicle_minutes = 0 then null
        else round(100.0 * v_used_vehicle_minutes / v_available_vehicle_minutes, 1) end
    ),
    'distanceByVehicle', v_distance_by_vehicle,
    'fulfillmentBreakdown', v_fulfillment_breakdown,
    'externalCostByDepartment', v_external_cost_by_department
  );
end;
$$;


--
-- Name: get_vehicle_booking_assignment_display_impl(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_vehicle_booking_assignment_display_impl(p_actor_user_id uuid, p_booking_id uuid) RETURNS TABLE(assignment_id uuid, fulfillment_type text, vehicle_code text, vehicle_name text, vehicle_image_url text, operator_name text, operator_title text, operator_avatar_url text, external_provider_name text, external_driver_name text, external_vehicle_plate text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_actor_user_id is distinct from public.current_app_user_id() then
    raise exception using errcode = '42501', message = 'VEHICLE_ACTOR_MISMATCH';
  end if;

  if not app_private.vehicle_user_can_view_booking(p_actor_user_id, p_booking_id) then
    raise exception using errcode = '42501', message = 'VEHICLE_BOOKING_ACCESS_DENIED';
  end if;

  return query
  select
    assignment.id,
    assignment.fulfillment_type,
    asset.code,
    asset.name,
    asset.image_url,
    coalesce(nullif(trim(employee.full_name), ''), nullif(trim(app_user.name), '')),
    nullif(trim(employee.title), ''),
    coalesce(nullif(trim(employee.avatar_url), ''), nullif(trim(app_user.avatar), '')),
    assignment.external_provider_name,
    assignment.external_driver_name,
    assignment.external_vehicle_plate
  from public.vehicle_booking_assignments assignment
  left join public.assets asset on asset.id = assignment.vehicle_asset_id
  left join public.users app_user on app_user.id = assignment.operator_user_id
  left join lateral (
    select employee_row.full_name, employee_row.title, employee_row.avatar_url
    from public.employees employee_row
    where employee_row.user_id = assignment.operator_user_id
    order by
      case when employee_row.status = 'Đang làm việc' then 0 else 1 end,
      employee_row.updated_at desc,
      employee_row.id
    limit 1
  ) employee on true
  where assignment.booking_id = p_booking_id
    and assignment.is_active
  order by assignment.version desc
  limit 1;
end;
$$;


--
-- Name: get_vehicle_booking_audit_timeline_phase3_impl(uuid, uuid, text, timestamp with time zone, timestamp with time zone, integer, timestamp with time zone, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_vehicle_booking_audit_timeline_phase3_impl(p_booking_id uuid DEFAULT NULL::uuid, p_department_id uuid DEFAULT NULL::uuid, p_event_type text DEFAULT NULL::text, p_from_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 50, p_cursor_occurred_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 50), 100));
  v_effective_department_id uuid := p_department_id;
  v_booking_department_id uuid;
  v_rows jsonb := '[]'::jsonb;
  v_items jsonb := '[]'::jsonb;
  v_next_cursor jsonb := null;
begin
  if p_from_at is not null and p_to_at is not null and p_to_at <= p_from_at then
    raise exception using errcode = '22023', message = 'INVALID_AUDIT_PERIOD';
  end if;
  if p_event_type is not null and p_event_type not in (
    'BOOKING_EVENT', 'ASSIGNMENT_VERSION', 'HANDOVER'
  ) then
    raise exception using errcode = '22023', message = 'INVALID_AUDIT_EVENT_TYPE';
  end if;

  if p_booking_id is not null then
    select booking.department_id_snapshot
    into v_booking_department_id
    from public.vehicle_bookings booking
    where booking.id = p_booking_id;

    if not found then
      raise exception using errcode = 'P0001', message = 'BOOKING_NOT_FOUND';
    end if;
    if p_department_id is not null
       and p_department_id is distinct from v_booking_department_id then
      raise exception using errcode = '22023', message = 'BOOKING_DEPARTMENT_MISMATCH';
    end if;
    v_effective_department_id := v_booking_department_id;
  end if;

  perform app_private.vehicle_require_audit_scope(
    public.current_app_user_id(),
    v_effective_department_id
  );

  with timeline as (
    select
      'AUDIT:' || audit.id::text as synthetic_id,
      booking.id as booking_id,
      booking.booking_code,
      booking.department_id_snapshot as department_id,
      audit.created_at as occurred_at,
      'BOOKING_EVENT'::text as source_type,
      coalesce(audit.changes ->> 'event', audit.action) as event_type,
      coalesce(audit.description, audit.changes ->> 'event', audit.action) as title,
      coalesce(actor.name, actor.email, nullif(audit.user_name, '')) as actor_name,
      coalesce(audit.description, audit.action) as summary,
      jsonb_strip_nulls(jsonb_build_object(
        'oldStatus', audit.old_data ->> 'status',
        'newStatus', audit.new_data ->> 'status',
        'rating', audit.new_data ->> 'rating',
        'issueCategory', audit.new_data ->> 'issue_category',
        'approvalSource', audit.new_data ->> 'approval_source',
        'closeReason', audit.new_data ->> 'close_reason'
      )) as details
    from public.audit_trail audit
    join public.vehicle_bookings booking on booking.id::text = audit.record_id
    left join public.users actor on actor.id::text = audit.user_id
    where audit.module = 'VEHICLE_BOOKING'

    union all

    select
      'ASSIGNMENT_CREATED:' || assignment.id::text,
      booking.id,
      booking.booking_code,
      booking.department_id_snapshot,
      assignment.assigned_at,
      'ASSIGNMENT_VERSION'::text,
      'ASSIGNMENT_CREATED'::text,
      'Phân công phiên bản ' || assignment.version::text,
      coalesce(actor.name, actor.email),
      'Tạo phương án điều phối',
      jsonb_strip_nulls(jsonb_build_object(
        'version', assignment.version,
        'fulfillmentType', assignment.fulfillment_type,
        'vehicleAssetId', assignment.vehicle_asset_id,
        'operatorUserId', assignment.operator_user_id,
        'dispatchReasonCode', assignment.dispatch_reason_code
      ))
    from public.vehicle_booking_assignments assignment
    join public.vehicle_bookings booking on booking.id = assignment.booking_id
    left join public.users actor on actor.id = assignment.assigned_by_user_id

    union all

    select
      'ASSIGNMENT_SUPERSEDED:' || assignment.id::text,
      booking.id,
      booking.booking_code,
      booking.department_id_snapshot,
      assignment.superseded_at,
      'ASSIGNMENT_VERSION'::text,
      'ASSIGNMENT_SUPERSEDED'::text,
      'Thay đổi phân công phiên bản ' || assignment.version::text,
      coalesce(actor.name, actor.email),
      'Thay đổi phương án điều phối',
      jsonb_strip_nulls(jsonb_build_object(
        'version', assignment.version,
        'fulfillmentType', assignment.fulfillment_type,
        'vehicleAssetId', assignment.vehicle_asset_id,
        'operatorUserId', assignment.operator_user_id,
        'supersedeReason', assignment.supersede_reason,
        'dispatchReasonCode', assignment.dispatch_reason_code
      ))
    from public.vehicle_booking_assignments assignment
    join public.vehicle_bookings booking on booking.id = assignment.booking_id
    left join public.users actor on actor.id = assignment.superseded_by_user_id
    where assignment.superseded_at is not null

    union all

    select
      'HANDOVER:' || handover.id::text,
      booking.id,
      booking.booking_code,
      booking.department_id_snapshot,
      handover.confirmed_at,
      'HANDOVER'::text,
      handover.event_type,
      case handover.event_type
        when 'OUTBOUND_HANDOVER' then 'Bàn giao xe và chìa khóa'
        else 'Nhận lại xe và chìa khóa'
      end,
      coalesce(actor.name, actor.email),
      case handover.event_type
        when 'OUTBOUND_HANDOVER' then 'Xác nhận bàn giao xe tự lái'
        else 'Xác nhận nhận lại xe tự lái'
      end,
      jsonb_strip_nulls(jsonb_build_object(
        'assignmentVersion', handover.assignment_version_snapshot,
        'vehicleAssetId', handover.vehicle_asset_id_snapshot,
        'confirmedOnBehalf', handover.confirmed_on_behalf,
        'overrideReason', handover.override_reason,
        'note', handover.note
      ))
    from public.vehicle_handover_logs handover
    join public.vehicle_bookings booking on booking.id = handover.booking_id
    left join public.users actor on actor.id = handover.officer_user_id
  ), filtered_timeline as (
    select timeline.*
    from timeline
    where (p_booking_id is null or timeline.booking_id = p_booking_id)
      and (
        v_effective_department_id is null
        or timeline.department_id = v_effective_department_id
      )
      and (p_event_type is null or timeline.source_type = p_event_type)
      and (p_from_at is null or timeline.occurred_at >= p_from_at)
      and (p_to_at is null or timeline.occurred_at < p_to_at)
      and (
        p_cursor_occurred_at is null
        or (timeline.occurred_at, timeline.synthetic_id)
          < (p_cursor_occurred_at, p_cursor_id)
      )
    order by timeline.occurred_at desc, timeline.synthetic_id desc
    limit v_limit + 1
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', row.synthetic_id,
    'bookingId', row.booking_id,
    'bookingCode', row.booking_code,
    'occurredAt', row.occurred_at,
    'sourceType', row.source_type,
    'eventType', row.event_type,
    'title', row.title,
    'actorName', row.actor_name,
    'summary', row.summary,
    'details', row.details
  ) order by row.occurred_at desc, row.synthetic_id desc), '[]'::jsonb)
  into v_rows
  from filtered_timeline row;

  if jsonb_array_length(v_rows) > v_limit then
    v_items := v_rows - v_limit;
    v_next_cursor := jsonb_build_object(
      'occurredAt', v_items -> (v_limit - 1) ->> 'occurredAt',
      'id', v_items -> (v_limit - 1) ->> 'id'
    );
  else
    v_items := v_rows;
  end if;

  return jsonb_build_object('items', v_items, 'nextCursor', v_next_cursor);
end;
$$;


--
-- Name: get_vehicle_booking_dispatcher_candidates_impl(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_vehicle_booking_dispatcher_candidates_impl(p_actor_user_id uuid) RETURNS TABLE(user_id uuid, employee_id uuid, employee_code text, employee_name text, employee_title text, employee_avatar_url text, department_id uuid, department_name text, is_dispatcher boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_actor_user_id is distinct from public.current_app_user_id() then
    perform app_private.vehicle_raise_permission_denied('Actor mismatch');
  end if;

  if not app_private.vehicle_user_has_permission(
    p_actor_user_id,
    'booking.vehicle.admin'
  ) then
    perform app_private.vehicle_raise_permission_denied(
      'Booking administrator permission required'
    );
  end if;

  return query
  select
    app_user.id,
    employee.id,
    employee.employee_code::text,
    employee.full_name::text,
    employee.title::text,
    employee.avatar_url,
    employee.department_id,
    department.name,
    exists (
      select 1
      from public.user_permission_grants grant_row
      where grant_row.user_id = app_user.id
        and grant_row.permission_code = 'booking.vehicle.dispatch'
        and grant_row.scope_type = 'global'
        and grant_row.scope_id = '*'
        and grant_row.is_active
        and grant_row.revoked_at is null
        and (grant_row.expires_at is null or grant_row.expires_at > now())
    )
  from public.employees employee
  join public.users app_user on app_user.id = employee.user_id
  left join public.org_units department on department.id = employee.department_id
  where employee.status = 'Đang làm việc'
    and app_user.is_active
    and app_user.account_status = 'ACTIVE'
    and app_user.role::text <> 'ADMIN'
  order by employee.full_name, employee.employee_code;
end;
$$;


--
-- Name: get_vehicle_booking_issues_phase3_impl(text, integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_vehicle_booking_issues_phase3_impl(p_status text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_cursor_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 50), 100));
  v_rows jsonb := '[]'::jsonb;
  v_items jsonb := '[]'::jsonb;
  v_next_cursor jsonb := null;
begin
  perform app_private.vehicle_require_sensitive_issue_view(
    public.current_app_user_id()
  );

  if p_status is not null and p_status not in (
    'PENDING', 'IN_REVIEW', 'RESOLVED', 'DISMISSED'
  ) then
    raise exception using errcode = '22023', message = 'INVALID_ISSUE_STATUS';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', issue_rows.id,
    'bookingId', issue_rows.booking_id,
    'bookingCode', issue_rows.booking_code,
    'reporterUserId', issue_rows.reporter_user_id,
    'reporterName', issue_rows.reporter_name,
    'departmentName', issue_rows.department_name,
    'issueCategory', issue_rows.issue_category,
    'comment', issue_rows.comment,
    'rating', issue_rows.rating,
    'resolutionStatus', issue_rows.resolution_status,
    'resolutionNote', issue_rows.resolution_note,
    'resolvedByName', issue_rows.resolved_by_name,
    'resolvedAt', issue_rows.resolved_at,
    'createdAt', issue_rows.created_at
  ) order by issue_rows.created_at desc, issue_rows.id desc), '[]'::jsonb)
  into v_rows
  from (
    select
      issue.id,
      issue.booking_id,
      booking.booking_code,
      issue.reporter_user_id,
      coalesce(reporter.name, reporter.email, issue.reporter_user_id::text) as reporter_name,
      org.name as department_name,
      issue.issue_category,
      issue.comment,
      feedback.rating,
      issue.resolution_status,
      issue.resolution_note,
      coalesce(resolver.name, resolver.email) as resolved_by_name,
      issue.resolved_at,
      issue.created_at
    from public.vehicle_booking_issues issue
    join public.vehicle_bookings booking on booking.id = issue.booking_id
    left join public.vehicle_booking_feedback feedback
      on feedback.booking_id = issue.booking_id
    left join public.users reporter on reporter.id = issue.reporter_user_id
    left join public.users resolver on resolver.id = issue.resolved_by_user_id
    left join public.org_units org on org.id = booking.department_id_snapshot
    where (p_status is null or issue.resolution_status = p_status)
      and (
        p_cursor_created_at is null
        or (issue.created_at, issue.id) < (p_cursor_created_at, p_cursor_id)
      )
    order by issue.created_at desc, issue.id desc
    limit v_limit + 1
  ) issue_rows;

  if jsonb_array_length(v_rows) > v_limit then
    v_items := v_rows - v_limit;
    v_next_cursor := jsonb_build_object(
      'createdAt', v_items -> (v_limit - 1) ->> 'createdAt',
      'id', v_items -> (v_limit - 1) ->> 'id'
    );
  else
    v_items := v_rows;
  end if;

  return jsonb_build_object('items', v_items, 'nextCursor', v_next_cursor);
end;
$$;


--
-- Name: get_vehicle_driver_authorizations_admin_impl(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_vehicle_driver_authorizations_admin_impl(p_actor_user_id uuid) RETURNS TABLE(id uuid, user_id uuid, employee_id uuid, authorization_type text, license_number text, license_class text, license_expiry date, license_front_photo_path text, license_back_photo_path text, health_check_expiry_date date, allowed_vehicle_types text[], status text, approved_by_user_id uuid, approved_at timestamp with time zone, note text, created_at timestamp with time zone, updated_at timestamp with time zone, employee_code text, employee_name text, employee_title text, employee_avatar_url text, department_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_actor_user_id is distinct from public.current_app_user_id() then
    perform app_private.vehicle_raise_permission_denied('Actor mismatch');
  end if;

  if not app_private.vehicle_user_has_permission(
    p_actor_user_id,
    'booking.vehicle.manage_authorizations'
  ) then
    perform app_private.vehicle_raise_permission_denied(
      'Driver authorization permission required'
    );
  end if;

  return query
  select
    authorization_row.id,
    authorization_row.user_id,
    authorization_row.employee_id,
    authorization_row.authorization_type,
    authorization_row.license_number,
    authorization_row.license_class,
    authorization_row.license_expiry,
    authorization_row.license_front_photo_path,
    authorization_row.license_back_photo_path,
    authorization_row.health_check_expiry_date,
    authorization_row.allowed_vehicle_types,
    authorization_row.status,
    authorization_row.approved_by_user_id,
    authorization_row.approved_at,
    authorization_row.note,
    authorization_row.created_at,
    authorization_row.updated_at,
    employee.employee_code::text,
    employee.full_name::text,
    employee.title::text,
    employee.avatar_url,
    employee.department_id
  from public.vehicle_driver_authorizations authorization_row
  left join public.employees employee
    on employee.id = authorization_row.employee_id
  order by employee.full_name nulls last, authorization_row.created_at desc;
end;
$$;


--
-- Name: get_vehicle_driver_authorizations_eligible_impl(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_vehicle_driver_authorizations_eligible_impl(p_actor_user_id uuid) RETURNS TABLE(id uuid, user_id uuid, employee_id uuid, authorization_type text, license_class text, license_expiry date, allowed_vehicle_types text[], status text, is_eligible boolean, employee_name text, employee_title text, employee_avatar_url text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_actor_user_id is distinct from public.current_app_user_id() then
    perform app_private.vehicle_raise_permission_denied('Actor mismatch');
  end if;

  if p_actor_user_id is null then
    perform app_private.vehicle_raise_permission_denied(
      'Authenticated booking user required'
    );
  end if;

  return query
  select
    authorization_row.id,
    authorization_row.user_id,
    authorization_row.employee_id,
    authorization_row.authorization_type,
    authorization_row.license_class,
    authorization_row.license_expiry,
    authorization_row.allowed_vehicle_types,
    authorization_row.status,
    authorization_row.status = 'ACTIVE'
      and authorization_row.license_expiry >= current_date,
    employee.full_name::text,
    employee.title::text,
    employee.avatar_url
  from public.vehicle_driver_authorizations authorization_row
  left join public.employees employee
    on employee.id = authorization_row.employee_id
  where authorization_row.status = 'ACTIVE'
    and authorization_row.license_expiry >= current_date
  order by employee.full_name nulls last, authorization_row.created_at;
end;
$$;


--
-- Name: get_vehicle_driver_candidates_impl(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.get_vehicle_driver_candidates_impl(p_actor_user_id uuid) RETURNS TABLE(employee_id uuid, user_id uuid, employee_code text, employee_name text, employee_title text, employee_avatar_url text, department_id uuid, authorization_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_actor_user_id is distinct from public.current_app_user_id() then
    perform app_private.vehicle_raise_permission_denied('Actor mismatch');
  end if;

  if not app_private.vehicle_user_has_permission(
    p_actor_user_id,
    'booking.vehicle.manage_authorizations'
  ) then
    perform app_private.vehicle_raise_permission_denied(
      'Driver authorization permission required'
    );
  end if;

  return query
  select
    employee.id,
    employee.user_id,
    employee.employee_code::text,
    employee.full_name::text,
    employee.title::text,
    employee.avatar_url,
    employee.department_id,
    count(authorization_row.id)::bigint
  from public.employees employee
  join public.users app_user on app_user.id = employee.user_id
  left join public.vehicle_driver_authorizations authorization_row
    on authorization_row.user_id = employee.user_id
  where employee.status = 'Đang làm việc'
    and employee.user_id is not null
    and coalesce(app_user.is_active, true)
  group by
    employee.id,
    employee.user_id,
    employee.employee_code,
    employee.full_name,
    employee.title,
    employee.avatar_url,
    employee.department_id
  order by employee.full_name, employee.employee_code;
end;
$$;


--
-- Name: global_has_action(text, text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.global_has_action(p_permission_code text, p_legacy_module_key text, p_user_id uuid DEFAULT public.current_app_user_id()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
