--
-- Name: guard_chat_member_role_update(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_chat_member_role_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := public.current_app_user_id();
  v_can_change_role boolean := false;
begin
  if new.role is distinct from old.role then
    select
      public.is_admin()
      or exists (
        select 1
        from public.chat_conversations cc
        where cc.id = old.conversation_id
          and cc.created_by = v_user_id::text
          and cc.deleted_at is null
      )
      or exists (
        select 1
        from public.chat_members cm
        where cm.conversation_id = old.conversation_id
          and cm.user_id = v_user_id::text
          and cm.role = 'owner'
          and cm.left_at is null
      )
    into v_can_change_role;

    if not coalesce(v_can_change_role, false) then
      raise exception 'Only channel owners can change chat member roles.';
    end if;

    if old.role = 'owner'
      and new.role <> 'owner'
      and not (
        public.is_admin()
        or exists (
          select 1
          from public.chat_conversations cc
          where cc.id = old.conversation_id
            and cc.created_by = v_user_id::text
            and cc.deleted_at is null
        )
      )
    then
      raise exception 'Only the channel creator or system admin can change the owner role.';
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: guard_chat_message_recall_update(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_chat_message_recall_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := public.current_app_user_id();
begin
  if old.recalled_at is not null and new.recalled_at is null then
    raise exception 'A recalled chat message cannot be restored.';
  end if;

  if new.recalled_at is distinct from old.recalled_at
    or new.recalled_by is distinct from old.recalled_by
  then
    if not (
      public.is_admin()
      or old.sender_id = v_user_id::text
      or app_private.chat_conversation_can_manage(old.conversation_id, v_user_id)
    ) then
      raise exception 'Only the sender or channel admins can recall this message.';
    end if;
    new.recalled_by = coalesce(new.recalled_by, v_user_id);
    new.recalled_at = coalesce(new.recalled_at, now());
  end if;

  return new;
end;
$$;


--
-- Name: guard_chat_v2_message_update(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_chat_v2_message_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_is_manager boolean;
begin
  if v_actor is null then
    raise exception 'Không xác định được người dùng hiện tại.';
  end if;

  if public.is_admin() then
    return new;
  end if;

  if new.conversation_id is distinct from old.conversation_id
    or new.sender_id is distinct from old.sender_id
    or new.kind is distinct from old.kind
    or new.reply_to_message_id is distinct from old.reply_to_message_id
    or new.created_at is distinct from old.created_at then
    raise exception 'Không thể thay đổi dữ liệu gốc của tin nhắn.';
  end if;

  if old.deleted_at is not null and new.deleted_at is null then
    raise exception 'Không thể khôi phục tin nhắn đã xóa.';
  end if;

  v_is_manager := app_private.chat_v2_can_manage(old.conversation_id, v_actor);

  if new.body is distinct from old.body
    or new.metadata is distinct from old.metadata
    or new.edited_at is distinct from old.edited_at then
    if old.sender_id <> v_actor then
      raise exception 'Bạn chỉ có thể sửa tin nhắn của mình.';
    end if;
    if old.deleted_at is not null then
      raise exception 'Không thể sửa tin nhắn đã xóa.';
    end if;
  end if;

  if new.deleted_at is distinct from old.deleted_at or new.deleted_by is distinct from old.deleted_by then
    if old.sender_id <> v_actor and not v_is_manager then
      raise exception 'Bạn không có quyền xóa tin nhắn này.';
    end if;
    if new.deleted_at is not null and new.deleted_by is distinct from v_actor then
      raise exception 'Người xóa tin nhắn không hợp lệ.';
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: guard_chat_v2_participant_mutation(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_chat_v2_participant_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_conversation_id uuid := coalesce(new.conversation_id, old.conversation_id);
  v_conversation_type text;
  v_is_manager boolean;
  v_is_creator boolean;
  v_active_owner_count integer;
begin
  if tg_op = 'UPDATE'
    and new.conversation_id is not distinct from old.conversation_id
    and new.user_id is not distinct from old.user_id
    and new.role is not distinct from old.role
    and new.is_muted is not distinct from old.is_muted
    and new.is_pinned is not distinct from old.is_pinned
    and new.last_read_message_id is not distinct from old.last_read_message_id
    and new.last_read_at is not distinct from old.last_read_at
    and new.joined_at is not distinct from old.joined_at
    and new.left_at is not distinct from old.left_at
    and new.created_at is not distinct from old.created_at then
    return new;
  end if;

  if v_actor is null then
    raise exception 'Không xác định được người dùng hiện tại.';
  end if;

  select c.type, c.created_by = v_actor
  into v_conversation_type, v_is_creator
  from public.chat_v2_conversations c
  where c.id = v_conversation_id
    and c.deleted_at is null;

  if v_conversation_type is null then
    raise exception 'Hội thoại không tồn tại hoặc đã bị xóa.';
  end if;

  if public.is_admin() then
    return coalesce(new, old);
  end if;

  v_is_manager := app_private.chat_v2_can_manage(v_conversation_id, v_actor);

  if tg_op = 'INSERT' then
    if not (v_is_manager or v_is_creator) then
      raise exception 'Bạn không có quyền thêm thành viên vào nhóm này.';
    end if;
    if v_conversation_type = 'direct' and not v_is_creator then
      raise exception 'Không thể thêm thành viên vào hội thoại cá nhân.';
    end if;
    if new.role = 'owner' and not v_is_creator then
      raise exception 'Không thể tự tạo quyền chủ nhóm.';
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if new.conversation_id is distinct from old.conversation_id
      or new.user_id is distinct from old.user_id
      or new.joined_at is distinct from old.joined_at then
      raise exception 'Không thể thay đổi danh tính thành viên.';
    end if;

    if old.user_id = v_actor and not v_is_manager then
      if new.role is distinct from old.role then
        raise exception 'Bạn không thể tự thay đổi quyền nhóm.';
      end if;
      if old.role = 'owner' and old.left_at is null and new.left_at is not null then
        select count(*)
        into v_active_owner_count
        from public.chat_v2_participants p
        where p.conversation_id = old.conversation_id
          and p.role = 'owner'
          and p.left_at is null
          and p.user_id <> old.user_id;
        if coalesce(v_active_owner_count, 0) = 0 then
          raise exception 'Không thể rời nhóm khi bạn là chủ nhóm cuối cùng.';
        end if;
      end if;
      return new;
    end if;

    if not v_is_manager then
      raise exception 'Bạn không có quyền quản trị thành viên nhóm này.';
    end if;

    if v_conversation_type = 'direct' and (
      new.role is distinct from old.role
      or new.left_at is distinct from old.left_at
      or new.user_id is distinct from old.user_id
    ) then
      raise exception 'Không thể quản trị thành viên trong hội thoại cá nhân.';
    end if;

    if new.role = 'owner' and old.role is distinct from 'owner' then
      raise exception 'Chỉ được gán quyền quản trị viên nhóm, không được tạo thêm chủ nhóm.';
    end if;

    if old.role = 'owner' and (
      new.role is distinct from 'owner'
      or (old.left_at is null and new.left_at is not null)
    ) then
      select count(*)
      into v_active_owner_count
      from public.chat_v2_participants p
      where p.conversation_id = old.conversation_id
        and p.role = 'owner'
        and p.left_at is null
        and p.user_id <> old.user_id;
      if coalesce(v_active_owner_count, 0) = 0 then
        raise exception 'Không thể hạ quyền hoặc loại bỏ chủ nhóm cuối cùng.';
      end if;
    end if;

    return new;
  end if;

  if tg_op = 'DELETE' then
    raise exception 'Không xóa cứng thành viên chat; hãy dùng left_at để loại khỏi nhóm.';
  end if;

  return coalesce(new, old);
end;
$$;


--
-- Name: guard_chat_v2_reply_target(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_chat_v2_reply_target() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_reply_conversation_id uuid;
begin
  if new.reply_to_message_id is null then
    return new;
  end if;

  if new.id = new.reply_to_message_id then
    raise exception 'Không thể trả lời chính tin nhắn này.';
  end if;

  select m.conversation_id
  into v_reply_conversation_id
  from public.chat_v2_messages m
  where m.id = new.reply_to_message_id
    and m.deleted_at is null;

  if v_reply_conversation_id is null then
    raise exception 'Tin nhắn được trả lời không tồn tại hoặc đã bị xóa.';
  end if;

  if v_reply_conversation_id is distinct from new.conversation_id then
    raise exception 'Tin nhắn được trả lời phải cùng hội thoại.';
  end if;

  return new;
end;
$$;


--
-- Name: guard_chat_v2_structured_message_link(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_chat_v2_structured_message_link() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_conversation_id uuid;
begin
  select m.conversation_id
  into v_conversation_id
  from public.chat_v2_messages m
  where m.id = coalesce(new.message_id, old.message_id);

  if v_conversation_id is null then
    raise exception 'Tin nhắn không tồn tại.';
  end if;

  if tg_op in ('INSERT', 'UPDATE') and new.conversation_id is distinct from v_conversation_id then
    raise exception 'Dữ liệu tương tác không thuộc hội thoại của tin nhắn.';
  end if;

  return coalesce(new, old);
end;
$$;


--
-- Name: guard_custom_material_direct_status_update(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_custom_material_direct_status_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if app_private.material_transition_context_enabled() or pg_trigger_depth() > 1 then
    return new;
  end if;

  if new.status is distinct from old.status
    or new.submitted_at is distinct from old.submitted_at
    or new.approved_at is distinct from old.approved_at
    or new.approved_by is distinct from old.approved_by
    or new.returned_at is distinct from old.returned_at
    or new.returned_by is distinct from old.returned_by
    or new.rejected_at is distinct from old.rejected_at
    or new.rejected_by is distinct from old.rejected_by
    or new.cancelled_at is distinct from old.cancelled_at
    or new.cancelled_by is distinct from old.cancelled_by then
    raise exception 'Custom Material workflow fields must be changed through transition_custom_material_request_status.'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


--
-- Name: guard_daily_log_direct_status_update(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_daily_log_direct_status_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if app_private.daily_log_transition_context_enabled() then
    return new;
  end if;

  if new.status is distinct from old.status
    or new.verified is distinct from old.verified
    or new.submitted_by is distinct from old.submitted_by
    or new.submitted_by_id is distinct from old.submitted_by_id
    or new.submitted_at is distinct from old.submitted_at
    or new.requested_verifier_id is distinct from old.requested_verifier_id
    or new.requested_verifier_name is distinct from old.requested_verifier_name
    or new.submitted_to_user_id is distinct from old.submitted_to_user_id
    or new.submitted_to_name is distinct from old.submitted_to_name
    or new.submitted_to_permission is distinct from old.submitted_to_permission
    or new.submission_note is distinct from old.submission_note
    or new.verified_by is distinct from old.verified_by
    or new.verified_by_id is distinct from old.verified_by_id
    or new.verified_at is distinct from old.verified_at
    or new.rejected_by is distinct from old.rejected_by
    or new.rejected_by_id is distinct from old.rejected_by_id
    or new.rejected_at is distinct from old.rejected_at
    or new.rejection_reason is distinct from old.rejection_reason then
    raise exception 'Daily Log workflow fields must be changed through transition_daily_log_status.'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


--
-- Name: guard_daily_log_legacy_summary_source_delete(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_daily_log_legacy_summary_source_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if exists (
    select 1
    from public.daily_logs summary_log
    where summary_log.id <> old.id
      and summary_log.summary_source_type = 'member_contributions'
      and coalesce(summary_log.summary_source_metadata -> 'legacyDailyLogIds', '[]'::jsonb) ? old.id
  ) then
    raise exception 'Phiếu nhật ký nguồn đang được dùng trong bản tổng hợp. Hãy bỏ phiếu khỏi tổng hợp trước khi xoá.'
      using errcode = '23503';
  end if;

  return old;
end;
$$;


--
-- Name: guard_hrm_template_only_direct_grant(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_hrm_template_only_direct_grant() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.is_active
    and app_private.is_hrm_template_only_permission(new.permission_code)
  then
    raise exception 'HRM_TEMPLATE_ONLY_PERMISSION: % must be assigned through HR or HR_MANAGE', new.permission_code
      using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: guard_material_po_pbac_grant_write(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_material_po_pbac_grant_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if current_user not in ('postgres', 'supabase_admin')
    and new.permission_code like 'project.material_po.%'
    and (
      tg_op = 'INSERT'
      or old.permission_code not like 'project.material_po.%'
      or (not old.is_active and new.is_active)
    )
  then
    raise exception 'Quyền PBAC Đơn hàng PO đã chuyển sang Room và không thể cấp mới.'
      using errcode = '42501';
  end if;
  return new;
end;
$$;


