--
-- Name: guard_paid_supplier_payment_allocation_write(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_paid_supplier_payment_allocation_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_batch_id uuid := case when tg_op = 'DELETE' then old.payment_batch_id else new.payment_batch_id end;
  v_old_batch_id uuid := case when tg_op = 'UPDATE' then old.payment_batch_id else null end;
  v_trusted_executor boolean := current_user in ('postgres', 'supabase_admin', 'service_role');
begin
  if v_trusted_executor then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  if exists (
    select 1
    from public.supplier_payment_batches batch
    where batch.id in (v_batch_id, v_old_batch_id)
      and batch.status in ('paid', 'reversed')
  ) then
    raise exception 'Không được sửa phân bổ của đợt thanh toán đã paid/reversed.';
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


--
-- Name: guard_payment_certificate_direct_workflow_update(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_payment_certificate_direct_workflow_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    if coalesce(new.status, 'draft') <> 'draft' then
      raise exception 'Payment Certificate workflow must start in draft.'
        using errcode = '23514';
    end if;
    return new;
  end if;

  if current_setting('app.project_document_transition_context', true) is distinct from 'on'
    and (
      old.status is distinct from new.status
      or old.submitted_by is distinct from new.submitted_by
      or old.submitted_at is distinct from new.submitted_at
      or old.approved_by is distinct from new.approved_by
      or old.approved_at is distinct from new.approved_at
      or old.paid_at is distinct from new.paid_at
      or old.returned_by is distinct from new.returned_by
      or old.returned_at is distinct from new.returned_at
      or old.return_reason is distinct from new.return_reason
      or old.submitted_to_user_id is distinct from new.submitted_to_user_id
      or old.submitted_to_name is distinct from new.submitted_to_name
      or old.submitted_to_permission is distinct from new.submitted_to_permission
      or old.submission_note is distinct from new.submission_note
    )
  then
    raise exception 'Payment Certificate workflow fields must be changed through transition_project_payment_certificate_status.'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


--
-- Name: guard_po_supplemental_direct_status_update(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_po_supplemental_direct_status_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if current_setting('app.material_transition_context', true) = 'on'
     or pg_trigger_depth() > 1 then
    return new;
  end if;

  if new.status is distinct from old.status
    or new.approved_by is distinct from old.approved_by
    or new.approved_at is distinct from old.approved_at
    or new.rejected_by is distinct from old.rejected_by
    or new.rejected_at is distinct from old.rejected_at
    or new.decision_note is distinct from old.decision_note then
    raise exception 'Purchase Order supplemental approval status must be changed through the approval RPC.'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


--
-- Name: guard_po_supplemental_pending_wms(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_po_supplemental_pending_wms() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.po_delivery_batch_id is null then
    return new;
  end if;

  if exists (
    select 1
    from public.purchase_order_delivery_batches batch
    where batch.id = new.po_delivery_batch_id
      and batch.status = 'supplemental_pending'
  ) then
    raise exception 'Đợt mua đang chờ duyệt bổ sung nên chưa thể tạo WMS/QR.'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


--
-- Name: guard_principal_role_assignment_principal(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_principal_role_assignment_principal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.principal_type <> 'user' then
    raise exception 'Only user principals are supported in authorization Phase 2'
      using errcode = '22023';
  end if;
  if new.status = 'ACTIVE' then
    perform app_private.assert_active_principal(new.principal_id);
  end if;
  return new;
end;
$$;


--
-- Name: guard_project_material_request_workflow_fields(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_project_material_request_workflow_fields() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if coalesce(old.request_origin, 'wms') = 'project'
    and current_user not in ('postgres', 'supabase_admin', 'service_role')
    and current_setting('app.material_request_workflow_context', true) <> 'on'
    and (
      new.status is distinct from old.status
      or new.submitted_to_user_id is distinct from old.submitted_to_user_id
      or new.submitted_to_name is distinct from old.submitted_to_name
      or new.submitted_to_permission is distinct from old.submitted_to_permission
      or new.workflow_step is distinct from old.workflow_step
      or new.workflow_instance_id is distinct from old.workflow_instance_id
      or new.workflow_subject_id is distinct from old.workflow_subject_id
      or new.workflow_template_id is distinct from old.workflow_template_id
    )
  then
    raise exception 'Workflow Yêu cầu chỉ được thay đổi qua RPC nghiệp vụ.' using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: guard_project_purchase_order_room_write(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_project_purchase_order_room_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_is_admin boolean := public.is_admin();
  v_workflow_changed boolean;
begin
  if v_actor is null and session_user in ('postgres', 'supabase_admin') then
    if tg_op = 'DELETE' then return old; else return new; end if;
  end if;
  if tg_op = 'DELETE' then
    if old.source_mode = 'company_consolidated' or v_is_admin then return old; end if;
    if v_actor is null
      or nullif(old.created_by_id, '') <> v_actor::text
      or not app_private.project_actor_has_effective_room_action(
        v_actor, old.project_id, old.construction_site_id, 'material_po', 'delete'
      ) then
      raise exception 'Bạn phải là người tạo PO và có quyền Xóa trong Room Đơn hàng PO.'
        using errcode = '42501';
    end if;
    return old;
  end if;
  if tg_op = 'INSERT' then
    if new.source_mode = 'company_consolidated' then return new; end if;
    if v_is_admin then return new; end if;
    if v_actor is null
      or new.status <> 'draft'
      or nullif(new.created_by_id, '') <> v_actor::text
      or not app_private.project_actor_has_effective_room_action(
        v_actor, new.project_id, new.construction_site_id, 'material_po', 'edit'
      ) then
      raise exception 'Bạn cần quyền Sửa và phải là người tạo PO nháp.' using errcode = '42501';
    end if;
    return new;
  end if;

  if old.source_mode = 'company_consolidated' and new.source_mode = 'company_consolidated' then
    return new;
  end if;
  if v_is_admin then return new; end if;
  if v_actor is null then
    raise exception 'Không xác định được người thao tác PO.' using errcode = '42501';
  end if;
  if new.project_id is distinct from old.project_id
    or new.construction_site_id is distinct from old.construction_site_id
    or new.created_by_id is distinct from old.created_by_id
    or new.source_mode is distinct from old.source_mode then
    raise exception 'Không được thay đổi scope, nguồn hoặc người tạo PO.' using errcode = '42501';
  end if;

  if new.archived_at is distinct from old.archived_at then
    if nullif(old.created_by_id, '') <> v_actor::text
      or not app_private.project_actor_has_effective_room_action(
        v_actor, old.project_id, old.construction_site_id, 'material_po', 'delete'
      ) then
      raise exception 'Bạn phải là người tạo PO và có quyền Xóa trong Room Đơn hàng PO.'
        using errcode = '42501';
    end if;
    return new;
  end if;

  v_workflow_changed := new.status is distinct from old.status
    or new.submitted_to_user_id is distinct from old.submitted_to_user_id
    or new.submitted_to_name is distinct from old.submitted_to_name
    or new.submitted_to_permission is distinct from old.submitted_to_permission
    or new.submission_note is distinct from old.submission_note
    or new.received_transaction_ids is distinct from old.received_transaction_ids
    or new.actual_delivery_date is distinct from old.actual_delivery_date;

  if old.status in ('draft', 'returned') and new.status = 'sent' then
    if nullif(old.created_by_id, '') <> v_actor::text
      or not app_private.project_actor_has_effective_room_action(
        v_actor, old.project_id, old.construction_site_id, 'material_po', 'submit'
      ) then
      raise exception 'Bạn phải là người tạo PO và có quyền Gửi.' using errcode = '42501';
    end if;
    if new.submitted_to_user_id is null
      or not app_private.project_user_has_room_action(
        new.submitted_to_user_id::uuid,
        old.project_id,
        old.construction_site_id,
        'material_po',
        'approve'
      ) then
      raise exception 'Người nhận phải có quyền Duyệt thuần trong Room Đơn hàng PO.' using errcode = '42501';
    end if;
    return new;
  end if;

  if old.status = 'sent' and new.status in ('confirmed', 'returned') then
    if old.submitted_to_user_id is null
      or old.submitted_to_user_id::text <> v_actor::text
      or not app_private.project_actor_has_effective_room_action(
        v_actor, old.project_id, old.construction_site_id, 'material_po', 'approve'
      ) then
      raise exception 'Bạn cần quyền Duyệt và phải là người được giao xử lý PO.' using errcode = '42501';
    end if;
    if new.status = 'returned' and (
      new.submitted_to_user_id is not null
      or new.submitted_to_name is not null
      or new.submitted_to_permission is not null
    ) then
      raise exception 'PO Trả lại phải xóa assignment duyệt cũ.' using errcode = '42501';
    end if;
    return new;
  end if;

  if v_workflow_changed then
    if new.status = 'cancelled' then
      if not (
        app_private.current_user_is_global_wms_keeper()
        or app_private.current_user_is_wms_keeper_for(old.target_warehouse_id)
      ) then
        raise exception 'Chỉ System Admin hoặc Thủ kho được hủy PO.' using errcode = '42501';
      end if;
      return new;
    end if;
    if new.status in ('confirmed', 'in_transit', 'partial', 'delivered', 'closed')
      or old.status in ('confirmed', 'in_transit', 'partial', 'delivered') then
      if not (
        app_private.project_actor_has_effective_room_action(
          v_actor, old.project_id, old.construction_site_id, 'material_po', 'confirm'
        )
        or app_private.current_user_is_global_wms_keeper()
        or app_private.current_user_is_wms_keeper_for(old.target_warehouse_id)
      ) then
        raise exception 'Bạn cần quyền Xác nhận để quản lý giao nhận PO.' using errcode = '42501';
      end if;
      return new;
    end if;
    raise exception 'Transition PO không hợp lệ.' using errcode = '42501';
  end if;

  if app_private.current_user_is_global_wms_keeper()
    or app_private.current_user_is_wms_keeper_for(old.target_warehouse_id) then
    return new;
  end if;
  if current_setting('app.material_transition_context', true) = 'on'
    and (
      new.supplemental_approval_status is distinct from old.supplemental_approval_status
      or new.approved_total_amount is distinct from old.approved_total_amount
    )
    and app_private.project_actor_has_effective_room_action(
      v_actor, old.project_id, old.construction_site_id, 'material_po', 'approve'
    ) then
    return new;
  end if;
  if old.status not in ('draft', 'returned')
    or new.status not in ('draft', 'returned')
    or nullif(old.created_by_id, '') <> v_actor::text
    or not app_private.project_actor_has_effective_room_action(
      v_actor, old.project_id, old.construction_site_id, 'material_po', 'edit'
    ) then
    raise exception 'Chỉ người tạo có quyền Sửa mới được sửa PO draft/returned.' using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: guard_project_staff_permission_principal(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_project_staff_permission_principal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid;
begin
  if coalesce(new.is_active, true) then
    select u.id into v_user_id
    from public.project_staff ps
    join public.users u on u.id::text = ps.user_id
    where ps.id = new.staff_id
    limit 1;
    perform app_private.assert_active_principal(v_user_id);
  end if;
  return new;
end;
$$;


