--
-- Name: guard_site_direct_purchase_lifecycle(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_site_direct_purchase_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_payable_status text;
begin
  if tg_op = 'INSERT' then
    if new.status <> 'draft' then
      raise exception 'Phiếu mua nóng mới phải được tạo ở trạng thái Nháp.';
    end if;
    return new;
  end if;

  if new.status = old.status then
    if old.status <> 'draft'
      and (to_jsonb(new) - array['updated_at', 'wms_transaction_id', 'last_action_by', 'last_action_at'])
        <> (to_jsonb(old) - array['updated_at', 'wms_transaction_id', 'last_action_by', 'last_action_at']) then
      raise exception 'Chỉ sửa được phiếu mua nóng ở trạng thái Nháp.';
    end if;
    return new;
  end if;

  if not (
    (old.status = 'draft' and new.status = 'submitted')
    or (old.status = 'submitted' and new.status in ('draft', 'approved_to_buy', 'rejected'))
    or (old.status = 'approved_to_buy' and new.status in ('submitted', 'purchased', 'rejected'))
    or (old.status in ('purchased', 'received', 'finance_review') and new.status in ('finance_review', 'reconciled', 'rejected'))
    or (old.status = 'reconciled' and new.status in ('finance_review', 'rejected', 'closed'))
    or (old.status = 'closed' and new.status = 'reconciled')
  ) then
    raise exception 'Chuyển trạng thái mua nóng không hợp lệ: % -> %.', old.status, new.status;
  end if;

  if new.status = 'reconciled' then
    select status into v_payable_status
    from public.supplier_payable_documents
    where source_type = 'site_direct_purchase'
      and source_id = new.id::text;

    if v_payable_status not in ('open', 'payable', 'partial') then
      raise exception 'Chỉ xác nhận công nợ khi phiếu có công nợ nhà cung cấp đang mở.';
    end if;
  end if;

  if new.status = 'closed' then
    select status into v_payable_status
    from public.supplier_payable_documents
    where source_type = 'site_direct_purchase'
      and source_id = new.id::text;

    if v_payable_status <> 'paid' then
      raise exception 'Chỉ đóng phiếu khi công nợ nhà cung cấp đã thanh toán đủ.';
    end if;
  end if;

  if new.status = 'rejected' then
    if exists (
      select 1
      from public.supplier_payable_documents payable
      where payable.source_type = 'site_direct_purchase'
        and payable.source_id = new.id::text
        and payable.status not in ('cancelled', 'reversed')
    ) then
      raise exception 'Phải hủy công nợ nhà cung cấp trước khi từ chối phiếu.';
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: guard_site_direct_purchase_wms(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_site_direct_purchase_wms() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.status in ('received', 'finance_review', 'reconciled', 'closed')
    and exists (
      select 1
      from public.site_direct_purchase_lines line
      where line.direct_purchase_id = new.id
        and line.line_type = 'stock_item'
    )
    and not exists (
      select 1
      from public.transactions tx
      where tx.id = new.wms_transaction_id
        and tx.status::text = 'COMPLETED'
    )
  then
    raise exception 'Mua nóng vật tư tồn kho phải có phiếu nhập WMS hoàn tất trước khi ghi nhận.';
  end if;
  return new;
end;
$$;


--
-- Name: guard_supplier_delivery_note_site_binding(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_supplier_delivery_note_site_binding() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_site public.hrm_construction_sites%rowtype;
begin
  if new.construction_site_id is not distinct from old.construction_site_id then
    return new;
  end if;

  select * into v_site
  from public.hrm_construction_sites site
  where site.id::text = new.construction_site_id;

  if not found or not v_site.warehouse_binding_enforced then
    return new;
  end if;

  if exists (
    select 1
    from public.supplier_direct_delivery_lines delivery_line
    left join public.warehouses warehouse on warehouse.id = delivery_line.target_warehouse_id
    where delivery_line.delivery_note_id = new.id
      and coalesce(delivery_line.wms_flow_mode, 'none') = 'direct_in_out'
      and (
        warehouse.id is null
        or coalesce(warehouse.is_archived, false)
        or warehouse.type <> 'SITE'
        or warehouse.construction_site_id is distinct from v_site.id
      )
  ) then
    raise exception 'Không thể chuyển phiếu giao sang công trường % vì kho nhận hiện tại không thuộc công trường này.', v_site.name;
  end if;

  return new;
end;
$$;


--
-- Name: guard_supplier_delivery_statement_line_wms(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_supplier_delivery_statement_line_wms() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_line public.supplier_direct_delivery_lines%rowtype;
begin
  select * into v_line
  from public.supplier_direct_delivery_lines
  where id = new.delivery_line_id;

  if not found then
    raise exception 'Không tìm thấy dòng giao nhận HĐ NCC %. ', new.delivery_line_id;
  end if;

  if v_line.status not in ('accepted', 'adjusted') then
    raise exception 'Bảng đối soát chỉ được gồm dòng giao nhận accepted/adjusted.';
  end if;

  if coalesce(v_line.wms_flow_mode, 'none') = 'direct_in_out'
    and coalesce(v_line.wms_status, 'not_required') <> 'exported'
  then
    raise exception 'Dòng nhập-xuất thẳng % phải hoàn tất WMS import và WMS xuất dùng trước khi đối soát/AP.', v_line.item_name_snapshot;
  end if;

  return new;
end;
$$;


--
-- Name: guard_supplier_delivery_warehouse_site_binding(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_supplier_delivery_warehouse_site_binding() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_note public.supplier_direct_delivery_notes%rowtype;
  v_site public.hrm_construction_sites%rowtype;
  v_warehouse public.warehouses%rowtype;
begin
  if tg_op = 'UPDATE'
     and new.delivery_note_id is not distinct from old.delivery_note_id
     and new.wms_flow_mode is not distinct from old.wms_flow_mode
     and new.target_warehouse_id is not distinct from old.target_warehouse_id
  then
    return new;
  end if;

  if coalesce(new.wms_flow_mode, 'none') <> 'direct_in_out' then
    return new;
  end if;

  select * into v_note
  from public.supplier_direct_delivery_notes
  where id = new.delivery_note_id;

  if not found or v_note.construction_site_id is null then
    return new;
  end if;

  select * into v_site
  from public.hrm_construction_sites
  where id = v_note.construction_site_id::uuid;

  if not found or not v_site.warehouse_binding_enforced then
    return new;
  end if;

  select * into v_warehouse
  from public.warehouses
  where id = new.target_warehouse_id;

  if not found
     or coalesce(v_warehouse.is_archived, false)
     or v_warehouse.type <> 'SITE'
     or v_warehouse.construction_site_id is distinct from v_site.id
  then
    raise exception 'Kho nhận không thuộc công trường % hoặc không còn là kho SITE đang hoạt động.', v_site.name;
  end if;

  return new;
end;
$$;


--
-- Name: guard_supplier_payment_batch_direct_write(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_supplier_payment_batch_direct_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_trusted_executor boolean := current_user in ('postgres', 'supabase_admin', 'service_role');
begin
  if v_trusted_executor then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  if tg_op = 'INSERT' and new.status in ('paid', 'reversed') then
    raise exception 'Đợt thanh toán chỉ được chuyển sang paid/reversed qua RPC tài chính.';
  end if;

  if tg_op = 'UPDATE' and (
    old.status in ('paid', 'reversed')
    or new.status in ('paid', 'reversed')
  ) then
    raise exception 'Đợt thanh toán đã paid/reversed là bất biến ngoài RPC tài chính.';
  end if;

  if tg_op = 'DELETE' and old.status in ('paid', 'reversed') then
    raise exception 'Không được xóa trực tiếp đợt thanh toán đã paid/reversed.';
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


--
-- Name: guard_used_warehouse_project_reassignment(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_used_warehouse_project_reassignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.project_id is not distinct from old.project_id
     and new.construction_site_id is not distinct from old.construction_site_id
  then
    return new;
  end if;

  if exists (
    select 1 from public.transactions transaction_row
    where transaction_row.source_warehouse_id = old.id
       or transaction_row.target_warehouse_id = old.id
  ) or exists (
    select 1 from public.inventory_ledger_entries entry
    where entry.warehouse_id = old.id
  ) or exists (
    select 1 from public.inventory_balances balance
    where balance.warehouse_id = old.id
      and coalesce(balance.on_hand_qty, 0) <> 0
  ) or exists (
    select 1 from public.material_issue_orders issue_order
    where issue_order.source_warehouse_id = old.id
  ) then
    raise exception 'Kho % đã phát sinh nghiệp vụ nên không thể đổi dự án/công trường.', old.name;
  end if;

  return new;
end;
$$;


--
-- Name: guard_used_warehouse_site_reassignment(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_used_warehouse_site_reassignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.construction_site_id is null
     or new.construction_site_id is not distinct from old.construction_site_id
  then
    return new;
  end if;

  if exists (
    select 1
    from public.inventory_balances balance
    where balance.warehouse_id = old.id
      and coalesce(balance.on_hand_qty, 0) <> 0
  ) or exists (
    select 1
    from public.transactions transaction_row
    where transaction_row.source_warehouse_id = old.id
       or transaction_row.target_warehouse_id = old.id
  ) or exists (
    select 1
    from public.supplier_direct_delivery_lines delivery_line
    where delivery_line.target_warehouse_id = old.id
      and (
        delivery_line.wms_import_transaction_id is not null
        or delivery_line.wms_export_transaction_id is not null
      )
  ) then
    raise exception 'Kho % đã phát sinh tồn kho/WMS nên không thể chuyển sang công trường khác. Hãy tạo kho mới hoặc dùng quy trình sửa dữ liệu có kiểm soát.', old.name;
  end if;

  return new;
end;
$$;


--
-- Name: guard_user_account_lifecycle_metadata(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_user_account_lifecycle_metadata() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.account_status is distinct from new.account_status
    or old.disabled_at is distinct from new.disabled_at
    or old.disabled_by is distinct from new.disabled_by
    or old.disabled_reason is distinct from new.disabled_reason
    or old.reactivated_at is distinct from new.reactivated_at
    or old.reactivated_by is distinct from new.reactivated_by
    or old.reactivation_reason is distinct from new.reactivation_reason
    or old.account_operation_status is distinct from new.account_operation_status
    or old.account_operation_action is distinct from new.account_operation_action
  then
    if auth.role() = 'service_role'
      and coalesce(current_setting('app.account_lifecycle_command', true), '') = 'on'
    then
      return new;
    end if;

    raise exception 'Account lifecycle metadata can only be changed by the trusted command'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


--
-- Name: guard_user_permission_grant_principal(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.guard_user_permission_grant_principal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.is_active then
    perform app_private.assert_active_principal(new.user_id);
  end if;
  return new;
end;
$$;


--
-- Name: has_any_permission(uuid, text[], text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.has_any_permission(p_user_id uuid, p_permission_codes text[], p_scope_type text DEFAULT 'global'::text, p_scope_id text DEFAULT '*'::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from unnest(coalesce(p_permission_codes, '{}'::text[])) permission_code
    where app_private.has_permission(p_user_id, permission_code, p_scope_type, p_scope_id)
  );
$$;


--
-- Name: has_explicit_permission(uuid, text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.has_explicit_permission(p_user_id uuid, p_permission_code text, p_scope_type text DEFAULT 'global'::text, p_scope_id text DEFAULT '*'::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.users u
    where u.id = p_user_id
      and coalesce(u.is_active, true)
      and u.role = 'ADMIN'
  )
  or exists (
    select 1
    from public.users u
    join public.user_permission_grants g on g.user_id = u.id
    where u.id = p_user_id
      and coalesce(u.is_active, true)
      and g.permission_code = p_permission_code
      and coalesce(g.is_active, false)
      and (g.expires_at is null or g.expires_at > now())
      and (
        g.scope_type = 'global'
        or (
          g.scope_type = coalesce(p_scope_type, 'global')
          and (g.scope_id = '*' or g.scope_id = coalesce(p_scope_id, '*'))
        )
      )
  );
$$;


--
-- Name: has_governed_hrm_permission(uuid, text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.has_governed_hrm_permission(p_user_id uuid, p_permission_code text, p_scope_type text DEFAULT 'global'::text, p_scope_id text DEFAULT '*'::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from app_private.resolve_effective_permission_sources(
      p_user_id, p_permission_code, p_scope_type, p_scope_id, now()
    ) source_row
    where not (
      source_row.permission_code like 'hrm.%'
      and source_row.source_type = 'LEGACY'
    )
    and (
      not app_private.is_hrm_template_only_permission(source_row.permission_code)
      or (source_row.source_type = 'ROLE' and source_row.source_code in ('HR','HR_MANAGE'))
    )
  );
$$;


--
-- Name: has_hrm_template_permission(uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.has_hrm_template_permission(p_user_id uuid, p_permission_code text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_user_id is not null and exists (
    select 1
    from app_private.resolve_effective_permission_sources(
      p_user_id,
      p_permission_code,
      'global',
      '*',
      now()
    ) source_row
    where source_row.source_type = 'ROLE'
      and source_row.source_code in ('HR', 'HR_MANAGE')
      and source_row.scope_type = 'global'
      and source_row.scope_id = '*'
  );
$$;


--
-- Name: has_permission(uuid, text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.has_permission(p_user_id uuid, p_permission_code text, p_scope_type text DEFAULT 'global'::text, p_scope_id text DEFAULT '*'::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from app_private.resolve_effective_permission_sources(
      p_user_id, p_permission_code, p_scope_type, p_scope_id, now()
    ) source_row
  );
$$;


--
-- Name: has_valid_authorization_override(uuid, text, uuid, text, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.has_valid_authorization_override(p_override_id uuid, p_rule_code text, p_actor_user_id uuid, p_subject_type text, p_subject_id text, p_scope_type text, p_scope_id text, p_at timestamp with time zone DEFAULT now()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.authorization_override_events override_row
    join public.authorization_sod_rules rule_row
      on rule_row.rule_code = override_row.rule_code
     and rule_row.effect = 'REQUIRE_OVERRIDE'
     and rule_row.overridable
     and rule_row.is_active
    where override_row.id = p_override_id
      and p_actor_user_id = public.current_app_user_id()
      and override_row.rule_code = p_rule_code
      and override_row.actor_user_id = p_actor_user_id
      and override_row.subject_type = p_subject_type
      and override_row.subject_id = p_subject_id
      and override_row.scope_type = coalesce(nullif(p_scope_type, ''), 'global')
      and override_row.scope_id = coalesce(nullif(p_scope_id, ''), '*')
      and override_row.revoked_at is null
      and override_row.starts_at <= p_at
      and override_row.expires_at > p_at
  );
$$;


--
-- Name: hide_project(text, text, text, boolean, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.hide_project(p_project_id text, p_reason text, p_hidden_by text DEFAULT NULL::text, p_force boolean DEFAULT false, p_construction_site_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_project public.projects%rowtype;
begin
  if not app_private.can_manage_project_master(p_project_id, 'project.master.hide') then
    raise exception 'Not allowed to hide project'
      using errcode = '42501';
  end if;

  if nullif(p_reason, '') is null then
    raise exception 'Hide reason is required'
      using errcode = '23502';
  end if;

  update public.projects
  set is_hidden = true,
      hidden_at = now(),
      hidden_by = nullif(p_hidden_by, ''),
      hidden_reason = btrim(p_reason)
  where id = p_project_id
  returning *
  into v_project;

  if v_project.id is null then
    raise exception 'Project not found: %', p_project_id
      using errcode = 'P0002';
  end if;

  return to_jsonb(v_project);
end;
$$;


--
-- Name: hrm_authorization_fingerprint(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.hrm_authorization_fingerprint(p_target_user_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select md5(coalesce((
    select jsonb_agg(
      jsonb_build_object(
        'assignmentId', assignment_row.id,
        'roleCode', template.code,
        'templateVersion', template.version,
        'scopeType', assignment_row.scope_type,
        'scopeId', assignment_row.scope_id,
        'startsAt', assignment_row.starts_at,
        'expiresAt', assignment_row.expires_at,
        'updatedAt', assignment_row.updated_at
      )
      order by template.code, assignment_row.id
    )::text
    from public.principal_role_assignments assignment_row
    join public.role_permission_templates template
      on template.id = assignment_row.role_template_id
     and template.code in ('HR', 'HR_MANAGE')
    where assignment_row.principal_type = 'user'
      and assignment_row.principal_id = p_target_user_id
      and assignment_row.status = 'ACTIVE'
      and assignment_row.starts_at <= now()
      and (assignment_row.expires_at is null or assignment_row.expires_at > now())
  ), '[]'));
$$;


--
-- Name: hrm_can_access_employee_subject(uuid, text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.hrm_can_access_employee_subject(p_employee_id uuid, p_permission_code text, p_actor_user_id uuid DEFAULT public.current_app_user_id()) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request_user_id uuid := public.current_app_user_id();
  v_subject_user_id uuid;
begin
  if v_request_user_id is null
    or p_actor_user_id is distinct from v_request_user_id
    or p_employee_id is null
    or p_permission_code not like 'hrm.%'
  then return false;
  end if;
  if app_private.has_governed_hrm_permission(v_request_user_id, p_permission_code, 'global', '*') then
    return true;
  end if;
  select employee.user_id into v_subject_user_id
  from public.employees employee where employee.id = p_employee_id;
  if v_subject_user_id is null then return false; end if;
  return (v_subject_user_id = v_request_user_id
      and app_private.has_governed_hrm_permission(v_request_user_id, p_permission_code, 'own', '*'))
    or (
      app_private.has_governed_hrm_permission(v_request_user_id, p_permission_code, 'direct_reports', '*')
      and app_private.resolve_strict_direct_manager(v_subject_user_id) = v_request_user_id
    );
end;
$$;


--
-- Name: hrm_can_access_leave_request(uuid, text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.hrm_can_access_leave_request(p_leave_request_id uuid, p_permission_code text, p_actor_user_id uuid DEFAULT public.current_app_user_id()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_actor_user_id = public.current_app_user_id()
    and coalesce((
      select app_private.hrm_can_access_employee_subject(
        request_row."employeeId", p_permission_code, p_actor_user_id
      )
      from public.hrm_leave_requests request_row where request_row.id = p_leave_request_id
    ), false);
$$;


--
-- Name: hrm_current_email(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.hrm_current_email() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select lower(coalesce(
    (select auth.jwt() ->> 'email'),
    current_setting('request.jwt.claim.email', true),
    ''
  ));
$$;


--
-- Name: hrm_employee_has_action(text, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.hrm_employee_has_action(p_permission_code text, p_department_id uuid DEFAULT NULL::uuid, p_target_user_id uuid DEFAULT NULL::uuid, p_assigned_user_id uuid DEFAULT NULL::uuid, p_user_id uuid DEFAULT public.current_app_user_id()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_permission_code in (
    'hrm.employee.view',
    'hrm.employee.create',
    'hrm.employee.edit'
  )
  and app_private.hrm_employee_has_permission(
    'hrm.employee.view',
    p_department_id,
    p_target_user_id,
    p_assigned_user_id,
    p_user_id
  )
  and (
    p_permission_code = 'hrm.employee.view'
    or app_private.hrm_employee_has_permission(
      p_permission_code,
      p_department_id,
      p_target_user_id,
      p_assigned_user_id,
      p_user_id
    )
  );
$$;


--
-- Name: hrm_employee_has_permission(text, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.hrm_employee_has_permission(p_permission_code text, p_department_id uuid DEFAULT NULL::uuid, p_target_user_id uuid DEFAULT NULL::uuid, p_assigned_user_id uuid DEFAULT NULL::uuid, p_user_id uuid DEFAULT public.current_app_user_id()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_permission_code like 'hrm.employee.%'
  and p_user_id is not null
  and (
    app_private.has_permission(p_user_id, p_permission_code, 'global', '*')
    or (
      p_department_id is not null
      and app_private.has_permission(p_user_id, p_permission_code, 'department', p_department_id::text)
    )
    or (
      p_target_user_id = p_user_id
      and app_private.has_permission(p_user_id, p_permission_code, 'own', p_user_id::text)
    )
    or (
      p_assigned_user_id = p_user_id
      and app_private.has_permission(p_user_id, p_permission_code, 'assigned', p_user_id::text)
    )
  );
$$;


--
-- Name: hrm_employee_is_current_user(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.hrm_employee_is_current_user(p_employee_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with current_identity as (
    select
      (select auth.uid()) as auth_user_id,
      public.current_app_user_id() as app_user_id,
      app_private.hrm_current_email() as jwt_email
  ),
  current_user_row as (
    select
      u.id,
      u.auth_id,
      lower(coalesce(u.email, '')) as email
    from public.users u
    cross join current_identity ci
    where u.id = ci.app_user_id
       or (ci.auth_user_id is not null and u.auth_id = ci.auth_user_id)
       or (ci.jwt_email <> '' and lower(coalesce(u.email, '')) = ci.jwt_email)
    order by
      case
        when u.id = ci.app_user_id then 0
        when ci.auth_user_id is not null and u.auth_id = ci.auth_user_id then 1
        else 2
      end
    limit 1
  )
  select exists (
    select 1
    from public.employees e
    cross join current_identity ci
    left join current_user_row u on true
    where e.id::text = p_employee_id
      and (
        (ci.app_user_id is not null and e.user_id::text = ci.app_user_id::text)
        or (ci.auth_user_id is not null and e.user_id::text = ci.auth_user_id::text)
        or (u.id is not null and e.user_id::text = u.id::text)
        or (u.auth_id is not null and e.user_id::text = u.auth_id::text)
        or (ci.jwt_email <> '' and lower(coalesce(e.email, '')) = ci.jwt_email)
        or (u.email <> '' and lower(coalesce(e.email, '')) = u.email)
      )
  );
$$;


--
-- Name: hrm_employee_profile_access_level(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.hrm_employee_profile_access_level(p_employee_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := public.current_app_user_id();
  v_subject_user_id uuid;
begin
  if v_actor_id is null then return 'NONE'; end if;
  select employee.user_id into v_subject_user_id
  from public.employees employee where employee.id = p_employee_id;
  if not found then return 'NONE'; end if;

  if app_private.has_hrm_template_permission(v_actor_id, 'hrm.employee.view_sensitive') then
    return case
      when app_private.has_hrm_template_permission(v_actor_id, 'hrm.compensation.manage')
      then 'HR_MANAGE' else 'HR' end;
  end if;
  if v_subject_user_id = v_actor_id then return 'SELF'; end if;
  if v_subject_user_id is not null
    and app_private.resolve_strict_direct_manager(v_subject_user_id) = v_actor_id
  then return 'MANAGER'; end if;
  if app_private.has_governed_hrm_permission(v_actor_id, 'hrm.employee.view_directory') then
    return 'DIRECTORY';
  end if;
  return 'NONE';
end;
$$;


--
-- Name: hrm_has_action(text, uuid, text, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.hrm_has_action(p_permission_code text, p_target_user_id uuid DEFAULT NULL::uuid, p_department_id text DEFAULT NULL::text, p_assigned_user_id uuid DEFAULT NULL::uuid, p_user_id uuid DEFAULT public.current_app_user_id()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_permission_code like 'hrm.%'
    and p_user_id is not null
    and (
      app_private.has_governed_hrm_permission(p_user_id, p_permission_code, 'global', '*')
      or (p_target_user_id = p_user_id
        and app_private.has_governed_hrm_permission(p_user_id, p_permission_code, 'own', p_user_id::text))
      or (p_assigned_user_id = p_user_id
        and app_private.has_governed_hrm_permission(p_user_id, p_permission_code, 'assigned', p_user_id::text))
    );
$$;


--
-- Name: hrm_import_domain_for_type(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.hrm_import_domain_for_type(p_record_type text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case upper(trim(p_record_type))
    when 'EMPLOYEE_CORE' then 'C2'
    when 'PERSONAL_CONTACT' then 'C2'
    when 'ADDRESS' then 'C2'
    when 'EMERGENCY_CONTACT' then 'C2'
    when 'CONTRACT' then 'C3'
    when 'EMPLOYMENT_EVENT' then 'C3'
    when 'IDENTITY_DOCUMENT' then 'C3'
    when 'INSURANCE' then 'C3'
    when 'DEPENDENT' then 'C3'
    when 'QUALIFICATION' then 'C3'
    when 'CERTIFICATION' then 'C3'
    when 'BANK_ACCOUNT' then 'C4'
    when 'TAX_PROFILE' then 'C4'
    else 'UNSUPPORTED'
  end;
$$;


--
-- Name: hrm_import_is_iso_date(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.hrm_import_is_iso_date(p_value text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
begin
  if p_value is null or trim(p_value) = '' then return true; end if;
  if trim(p_value) !~ '^\d{4}-\d{2}-\d{2}$' then return false; end if;
  perform trim(p_value)::date;
  return true;
exception when others then return false;
end;
$_$;


--
-- Name: hrm_import_required_fields(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.hrm_import_required_fields(p_record_type text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_record_type
    when 'EMPLOYEE_CORE' then array[]::text[]
    when 'PERSONAL_CONTACT' then array[]::text[]
    when 'ADDRESS' then array['addressType','addressLine']
    when 'EMERGENCY_CONTACT' then array['fullName','relationshipCode','phone']
    when 'CONTRACT' then array['type','effectiveFrom']
    when 'EMPLOYMENT_EVENT' then array['eventTypeCode','eventDate','sourceReference']
    when 'IDENTITY_DOCUMENT' then array['documentTypeCode','documentNumber']
    when 'INSURANCE' then array[]::text[]
    when 'DEPENDENT' then array['fullName','relationshipCode']
    when 'BANK_ACCOUNT' then array['bankCode','accountNumber','accountHolder']
    when 'TAX_PROFILE' then array[]::text[]
    when 'QUALIFICATION' then array['institutionName']
    when 'CERTIFICATION' then array['certificationName']
    else array[]::text[]
  end;
$$;


--
-- Name: hrm_import_safe_error(text, integer, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.hrm_import_safe_error(p_sheet_code text, p_row_number integer, p_column text, p_error_code text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'sheetCode', p_sheet_code,
    'rowNumber', p_row_number,
