--
-- Name: hrm_is_location_manager(text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.hrm_is_location_manager(p_location_type text, p_location_id text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'app_private', 'pg_temp'
    AS $$
  select app_private.hrm_location_manager_id(p_location_type, p_location_id) = public.current_app_user_id()::text;
$$;


--
-- Name: hrm_location_manager_id(text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.hrm_location_manager_id(p_location_type text, p_location_id text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case
    when p_location_type = 'construction_site' then (
      select nullif(s."managerId", '')
      from public.hrm_construction_sites s
      where s.id::text = p_location_id
      limit 1
    )
    when p_location_type = 'office' then (
      select nullif(o."managerId", '')
      from public.hrm_offices o
      where o.id::text = p_location_id
      limit 1
    )
    else null
  end;
$$;


--
-- Name: hrm_location_name(text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.hrm_location_name(p_location_type text, p_location_id text, p_fallback text DEFAULT NULL::text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(
    case
      when p_location_type = 'construction_site' then (
        select s.name
        from public.hrm_construction_sites s
        where s.id::text = p_location_id
        limit 1
      )
      when p_location_type = 'office' then (
        select o.name
        from public.hrm_offices o
        where o.id::text = p_location_id
        limit 1
      )
      else null
    end,
    nullif(trim(coalesce(p_fallback, '')), '')
  );
$$;


--
-- Name: hrm_validate_manual_allowance_component(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.hrm_validate_manual_allowance_component() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not exists (
    select 1
    from public.hrm_payroll_components component
    where component.id = new.component_id
      and component.component_type = 'allowance'
      and component.is_active
  ) then
    raise exception using errcode = '22023', message = 'HRM_MANUAL_ALLOWANCE_COMPONENT_INVALID';
  end if;
  return new;
end;
$$;


--
-- Name: hrm_validate_org_manager_slot(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.hrm_validate_org_manager_slot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.manager_slot_id is not null and not exists (
    select 1
    from public.hrm_org_position_slots slot
    where slot.id = new.manager_slot_id
      and slot.org_unit_id = new.id
      and slot.status = 'ACTIVE'
  ) then
    raise exception using errcode = '22023', message = 'HRM_MANAGER_SLOT_MUST_BELONG_TO_UNIT';
  end if;
  return new;
end;
$$;


--
-- Name: hrm_validate_slot_reporting(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.hrm_validate_slot_reporting() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_cycle_found boolean;
begin
  if new.reports_to_slot_id is null then
    return new;
  end if;
  if new.reports_to_slot_id = new.id then
    raise exception using errcode = '22023', message = 'HRM_SLOT_SELF_REPORT_NOT_ALLOWED';
  end if;

  with recursive manager_chain as (
    select slot.id, slot.reports_to_slot_id
    from public.hrm_org_position_slots slot
    where slot.id = new.reports_to_slot_id
    union all
    select parent.id, parent.reports_to_slot_id
    from public.hrm_org_position_slots parent
    join manager_chain chain on parent.id = chain.reports_to_slot_id
  )
  select exists(select 1 from manager_chain where id = new.id)
  into v_cycle_found;

  if v_cycle_found then
    raise exception using errcode = '22023', message = 'HRM_SLOT_REPORTING_CYCLE';
  end if;
  return new;
end;
$$;


--
-- Name: increment_safety_card_print_count(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.increment_safety_card_print_count() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.safety_cards
  set printed_count = printed_count + 1,
      updated_at = now()
  where id = new.card_id;
  return new;
end;
$$;


--
-- Name: insert_vehicle_booking_notification(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.insert_vehicle_booking_notification(p_outbox_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_outbox app_private.vehicle_booking_notification_outbox%rowtype;
  v_booking_id uuid;
  v_assignment_id uuid;
  v_context jsonb;
  v_purpose text;
  v_compact_purpose text;
  v_message text;
  v_notification_id uuid;
begin
  select outbox.* into v_outbox
  from app_private.vehicle_booking_notification_outbox outbox
  where outbox.id = p_outbox_id;

  if not found then
    raise exception using errcode = 'P0001', message = 'VEHICLE_NOTIFICATION_OUTBOX_NOT_FOUND';
  end if;

  if coalesce(v_outbox.payload ->> 'booking_id', '')
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    v_booking_id := (v_outbox.payload ->> 'booking_id')::uuid;
  end if;

  if coalesce(v_outbox.payload ->> 'assignment_id', '')
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    v_assignment_id := (v_outbox.payload ->> 'assignment_id')::uuid;
  end if;

  v_context := app_private.build_vehicle_booking_notification_context(
    v_booking_id,
    v_assignment_id,
    v_outbox.recipient_user_id,
    v_outbox.event_type
  );

  if v_context is null then
    raise exception using errcode = 'P0001', message = 'VEHICLE_NOTIFICATION_BOOKING_NOT_FOUND';
  end if;

  v_purpose := v_context ->> 'purpose';
  v_compact_purpose := case
    when char_length(v_purpose) > 80 then left(v_purpose, 80) || '…'
    else v_purpose
  end;
  v_message := concat(
    'Người đặt: ', v_context ->> 'requester_name',
    ' · Nội dung: ', v_compact_purpose,
    ' · Tài xế: ', v_context ->> 'driver_name',
    ' · ', v_context ->> 'pickup_location',
    ' → ', v_context ->> 'destination'
  );

  insert into public.notifications(
    user_id, title, body, type, priority, module, link, metadata,
    category, message, severity, source_type, source_id,
    push_enabled, action_url, entity_type, entity_id
  ) values (
    v_outbox.recipient_user_id::text,
    app_private.vehicle_notification_title(v_outbox.event_type),
    v_message,
    'info', 'normal', 'VEHICLE_BOOKING',
    '/booking/vehicle/my?booking=' || v_booking_id,
    coalesce(v_outbox.payload, '{}'::jsonb)
      || v_context
      || jsonb_build_object('eventKey', v_outbox.event_key),
    'vehicle_booking', v_message, 'info', 'vehicle_booking',
    v_booking_id::text, true,
    '/booking/vehicle/my?booking=' || v_booking_id,
    'vehicle_booking', v_booking_id
  ) returning id into v_notification_id;

  return v_notification_id;
end;
$_$;


--
-- Name: inventory_transaction_type_for_entry(text, text, boolean); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.inventory_transaction_type_for_entry(p_wms_type text, p_direction text, p_has_related_request boolean) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_wms_type = 'IMPORT' and p_direction = 'in' then 'purchase_receipt'
    when p_wms_type = 'TRANSFER' and p_direction = 'in' then 'transfer_receipt'
    when p_wms_type = 'TRANSFER' and p_direction = 'out' then 'transfer_issue'
    when p_wms_type = 'EXPORT' and p_direction = 'out' and p_has_related_request then 'project_issue'
    when p_wms_type = 'EXPORT' and p_direction = 'out' then 'project_issue'
    when p_wms_type = 'LIQUIDATION' and p_direction = 'out' then 'loss_issue'
    when p_wms_type = 'ADJUSTMENT' and p_direction = 'in' then 'adjustment_in'
    when p_wms_type = 'ADJUSTMENT' and p_direction = 'out' then 'adjustment_out'
    else
      case when p_direction = 'in' then 'adjustment_in' else 'adjustment_out' end
  end;
$$;


--
-- Name: is_active_system_admin(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.is_active_system_admin(p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select count(*) = 1
    and coalesce(bool_and(user_row.id = p_user_id), false)
    from public.users user_row
    where user_row.role = 'ADMIN'
      and user_row.is_active
      and user_row.account_status = 'ACTIVE';
$$;


--
-- Name: is_hrm_template_only_permission(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.is_hrm_template_only_permission(p_permission_code text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select p_permission_code = any(array[
    'hrm.organization.manage',
    'hrm.staffing.manage',
    'hrm.staffing.assign',
    'hrm.staffing.set_manager',
    'hrm.employee.view_sensitive',
    'hrm.employee.edit_sensitive',
    'hrm.employee.import',
    'hrm.employee.export',
    'hrm.contract.view',
    'hrm.contract.manage',
    'hrm.document.view',
    'hrm.document.manage',
    'hrm.compensation.view',
    'hrm.compensation.manage',
    'hrm.payroll.manage',
    'hrm.payroll.export',
    'hrm.master_data.manage'
  ]::text[]);
$$;


--
-- Name: issue_safety_assignment_card(uuid, date, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.issue_safety_assignment_card(p_assignment_id uuid, p_expires_at date, p_template_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_assignment public.safety_project_assignments%rowtype;
  v_membership public.safety_worker_site_memberships%rowtype;
  v_worker public.safety_worker_profiles%rowtype;
  v_existing_card uuid;
  v_card_id uuid;
  v_card_code text;
begin
  if p_expires_at is null or p_expires_at <= current_date then
    raise exception 'SAFETY_INVALID_RPC_PAYLOAD: card expiry must be in the future'
      using errcode = '22023';
  end if;

  select assignment.*
  into v_assignment
  from public.safety_project_assignments assignment
  where assignment.id = p_assignment_id;

  select membership.*
  into v_membership
  from public.safety_worker_site_memberships membership
  where membership.id = v_assignment.membership_id;

  if v_assignment.id is null
    or v_assignment.assignment_status <> 'active'
    or v_membership.id is null
    or v_actor is null
    or not app_private.safety_workforce_can_manage(v_membership.project_id, v_membership.construction_site_id)
  then
    raise exception 'SAFETY_SCOPE_MISMATCH: active assignment is not manageable'
      using errcode = '42501';
  end if;

  select worker.*
  into v_worker
  from public.safety_worker_profiles worker
  where worker.id = v_assignment.worker_id
  for update;

  select assignment.*
  into v_assignment
  from public.safety_project_assignments assignment
  where assignment.id = p_assignment_id
  for update;

  perform membership.id
  from public.safety_worker_site_memberships membership
  where membership.id = v_membership.id
  for update;

  if v_assignment.eligibility_status <> 'eligible' then
    raise exception 'SAFETY_ASSIGNMENT_NOT_ELIGIBLE: assignment must be eligible before card issue'
      using errcode = '22023';
  end if;

  select card.id
  into v_existing_card
  from public.safety_cards card
  where card.assignment_id = v_assignment.id
    and card.status = 'active'
  limit 1;

  if v_existing_card is not null then
    raise exception 'SAFETY_ACTIVE_CARD_EXISTS: assignment already has an active card'
      using errcode = '23505';
  end if;

  if p_template_id is not null and not exists (
    select 1
    from public.safety_card_templates template
    where template.id = p_template_id
      and template.is_active
  ) then
    raise exception 'SAFETY_INVALID_RPC_PAYLOAD: active card template not found'
      using errcode = '22023';
  end if;

  v_card_code := 'SAFE-CARD-' || lpad(nextval('public.safety_card_code_seq')::text, 5, '0');

  insert into public.safety_cards (
    assignment_id, worker_id, project_id, construction_site_id,
    template_id, card_code, expires_at, status, created_by
  ) values (
    v_assignment.id,
    v_worker.id,
    v_membership.project_id,
    v_membership.construction_site_id::text,
    p_template_id,
    v_card_code,
    p_expires_at,
    'active',
    v_actor::text
  )
  returning id into v_card_id;

  insert into public.safety_audit_logs (
    actor_user_id, action, target_type, target_id, project_id, construction_site_id, metadata
  ) values (
    v_actor::text,
    'card.issue',
    'safety_cards',
    v_card_id,
    v_membership.project_id,
    v_membership.construction_site_id::text,
    jsonb_build_object('assignmentId', v_assignment.id, 'expiresAt', p_expires_at)
  );

  return app_private.safety_workforce_detail_for_membership(v_membership.id);
end;
$$;


--
-- Name: kb_has_action(text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.kb_has_action(p_permission_code text, p_user_id uuid DEFAULT public.current_app_user_id()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_user_id is not null
    and p_permission_code like 'kb.%'
    and app_private.global_has_action(p_permission_code, 'KB', p_user_id);
$$;


--
-- Name: legacy_admin_state_is_subset(jsonb, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.legacy_admin_state_is_subset(p_before jsonb, p_after jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select not exists (
    select 1
    from jsonb_array_elements_text(p_after -> 'adminModules') module_key
    where not (p_before -> 'adminModules' @> jsonb_build_array(module_key.value))
  ) and not exists (
    select 1
    from jsonb_each(p_after -> 'adminSubModules') module_entry
    cross join lateral jsonb_array_elements_text(module_entry.value) route
    where not (
      p_before -> 'adminModules' @> jsonb_build_array(module_entry.key)
      or coalesce(p_before -> 'adminSubModules' -> module_entry.key, '[]'::jsonb)
        @> jsonb_build_array(route.value)
    )
  );
$$;


--
-- Name: list_authorization_principals_impl(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.list_authorization_principals_impl() RETURNS TABLE(user_id uuid, name text, email text, account_status text, allowed_modules text[], allowed_sub_modules jsonb, admin_modules text[], admin_sub_modules jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := public.current_app_user_id();
begin
  if not app_private.has_permission(
    v_actor_user_id,
    'system.authorization.view',
    'global',
    '*'
  ) then
    raise exception 'Not allowed to view authorization principals'
      using errcode = '42501';
  end if;

  return query
  select
    user_row.id,
    user_row.name,
    user_row.email,
    user_row.account_status,
    coalesce(user_row.allowed_modules, '{}'::text[]),
    coalesce(user_row.allowed_sub_modules, '{}'::jsonb),
    coalesce(user_row.admin_modules, '{}'::text[]),
    coalesce(user_row.admin_sub_modules, '{}'::jsonb)
  from public.users user_row
  order by user_row.name, user_row.email, user_row.id;
end;
$$;


--
-- Name: list_permission_quick_templates_impl(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.list_permission_quick_templates_impl() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid;
begin
  v_actor_user_id := app_private.assert_authorization_permission('system.authorization.view');

  return coalesce((
    select jsonb_agg(
      jsonb_build_object(
        'id', template.id,
        'code', template.code,
        'name', template.name,
        'description', template.description,
        'isActive', template.is_active,
        'permissionCodes', coalesce(items.permission_codes, '[]'::jsonb),
        'updatedAt', template.updated_at
      )
      order by template.name, template.code
    )
    from public.permission_quick_templates template
    left join lateral (
      select jsonb_agg(item.permission_code order by item.sort_order, item.permission_code) as permission_codes
      from public.permission_quick_template_items item
      join public.permission_actions action
        on action.permission_code = item.permission_code
      where item.template_id = template.id
        and action.is_active
        and action.grant_readiness in ('enforced', 'verified')
    ) items on true
    where template.is_active
  ), '[]'::jsonb);
end;
$$;


--
-- Name: list_project_permission_recipients(text, text, text[]); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.list_project_permission_recipients(p_project_id text, p_construction_site_id text, p_permission_codes text[]) RETURNS TABLE(staff_id uuid, project_id text, construction_site_id text, user_id text, user_name text, position_id uuid, position_name text, permission_codes text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not (
    public.is_admin()
    or public.is_module_admin('DA')
    or app_private.project_scope_has_any_grant_v2(p_project_id, p_construction_site_id, public.current_app_user_id())
  ) then
    raise exception 'Not allowed to list Project permission recipients'
      using errcode = '42501';
  end if;

  return query
  with active_grants as (
    select
      g.user_id,
      array_agg(distinct g.permission_code order by g.permission_code) as permission_codes
    from public.user_permission_grants g
    where g.permission_code = any(coalesce(p_permission_codes, '{}'::text[]))
      and g.permission_code like 'project.%'
      and coalesce(g.is_active, false)
      and (g.expires_at is null or g.expires_at > now())
      and (
        g.scope_type = 'global'
        or (g.scope_type = 'project' and (g.scope_id = '*' or g.scope_id = p_project_id))
        or (
          p_construction_site_id is not null
          and g.scope_type = 'construction_site'
          and (g.scope_id = '*' or g.scope_id = p_construction_site_id)
        )
      )
    group by g.user_id
  )
  select
    ps.id,
    ps.project_id,
    ps.construction_site_id,
    ps.user_id,
    u.name,
    ps.position_id,
    hp.name,
    ag.permission_codes
  from active_grants ag
  join public.project_staff ps
    on ps.user_id = ag.user_id::text
   and ps.end_date is null
  left join public.users u
    on u.id = ag.user_id
  left join public.hrm_positions hp
    on hp.id = ps.position_id
  where (p_project_id is null or ps.project_id = p_project_id)
    and (
      p_construction_site_id is null
      or ps.construction_site_id is null
      or ps.construction_site_id = p_construction_site_id
    )
  order by hp.level nulls last, hp.name nulls last, u.name nulls last;
end;
$$;


--
-- Name: list_safety_site_worker_roster(text, uuid, text, text, text, text, text, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.list_safety_site_worker_roster(p_project_id text, p_construction_site_id uuid, p_search text DEFAULT NULL::text, p_membership_status text DEFAULT NULL::text, p_assignment_status text DEFAULT NULL::text, p_eligibility_status text DEFAULT NULL::text, p_document_status text DEFAULT NULL::text, p_cursor_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 50), 100));
  v_result jsonb;
begin
  perform app_private.safety_workforce_assert_scope(p_project_id, p_construction_site_id);
  if not app_private.safety_workforce_can_view(p_project_id, p_construction_site_id) then
    raise exception 'SAFETY_SCOPE_MISMATCH: actor cannot view target site'
      using errcode = '42501';
  end if;

  if p_membership_status is not null and p_membership_status not in ('candidate', 'active', 'inactive') then
    raise exception 'SAFETY_INVALID_RPC_PAYLOAD: invalid membership status' using errcode = '22023';
  end if;
  if p_assignment_status is not null and p_assignment_status not in ('active', 'ended', 'suspended', 'cancelled') then
    raise exception 'SAFETY_INVALID_RPC_PAYLOAD: invalid assignment status' using errcode = '22023';
  end if;
  if p_eligibility_status is not null and p_eligibility_status not in ('eligible', 'missing_profile', 'missing_certificate', 'expired_certificate', 'missing_site_requirement', 'suspended') then
    raise exception 'SAFETY_INVALID_RPC_PAYLOAD: invalid eligibility status' using errcode = '22023';
  end if;
  if p_document_status is not null and p_document_status not in ('missing', 'expired') then
    raise exception 'SAFETY_INVALID_RPC_PAYLOAD: invalid document status' using errcode = '22023';
  end if;
  if (p_cursor_created_at is null) <> (p_cursor_id is null) then
    raise exception 'SAFETY_INVALID_RPC_PAYLOAD: cursor timestamp and id are both required' using errcode = '22023';
  end if;

  with filtered as materialized (
    select membership.id as membership_id,
           membership.created_at as membership_created_at,
           jsonb_build_object(
             'id', membership.id,
             'workerId', membership.worker_id,
             'projectId', membership.project_id,
             'constructionSiteId', membership.construction_site_id,
             'defaultSubcontractorId', membership.default_subcontractor_id,
             'defaultTeamId', membership.default_team_id,
             'status', membership.status,
             'firstJoinedAt', membership.first_joined_at,
             'lastLeftAt', membership.last_left_at,
             'source', membership.source
           ) as membership_json,
           jsonb_build_object(
             'id', worker.id,
             'workerCode', worker.worker_code,
             'fullName', worker.full_name,
             'workerKind', worker.worker_kind,
             'phone', worker.phone,
             'status', worker.status,
             'photoStoragePath', coalesce(
               worker.photo_attachment ->> 'storagePath',
               worker.photo_attachment ->> 'storage_path',
               case
                 when coalesce(worker.photo_attachment ->> 'url', '') !~* '^https?://' then worker.photo_attachment ->> 'url'
                 else null
               end
             )
           ) as worker_json,
           case when subcontractor.id is null then null else jsonb_build_object(
             'id', subcontractor.id,
             'name', subcontractor.name,
             'code', subcontractor.code,
             'status', subcontractor.status
           ) end as subcontractor_json,
           case when team.id is null then null else jsonb_build_object(
             'id', team.id,
             'name', team.name,
             'code', team.code,
             'status', team.status
           ) end as team_json,
           case when (active_assignment.value).id is null then null
             else app_private.safety_workforce_assignment_json(active_assignment.value)
           end as assignment_json,
           case when (active_card.value).id is null then null
             else app_private.safety_workforce_card_json(active_card.value)
           end as card_json,
           coalesce(app_private.safety_workforce_mask_identity(worker.id), '-') as masked_identity,
           coalesce(app_private.safety_workforce_profile_readiness(worker.id), 'missing') as profile_readiness,
           app_private.safety_workforce_document_readiness(worker.id, 'health_check') as health_readiness,
           app_private.safety_workforce_document_readiness(worker.id, 'insurance') as insurance_readiness
    from public.safety_worker_site_memberships membership
    join public.safety_worker_profiles worker on worker.id = membership.worker_id
    left join public.safety_subcontractors subcontractor on subcontractor.id = membership.default_subcontractor_id
    left join public.safety_teams team on team.id = membership.default_team_id
    left join lateral (
      select assignment_row as value
      from public.safety_project_assignments assignment_row
      where assignment_row.membership_id = membership.id
        and assignment_row.assignment_status = 'active'
      order by assignment_row.started_at desc, assignment_row.id desc
      limit 1
    ) active_assignment on true
    left join lateral (
      select card_row as value
      from public.safety_cards card_row
      where card_row.assignment_id = (active_assignment.value).id
        and card_row.status = 'active'
      order by card_row.issued_at desc, card_row.id desc
      limit 1
    ) active_card on true
    where membership.project_id = p_project_id
      and membership.construction_site_id = p_construction_site_id
      and (p_membership_status is null or membership.status = p_membership_status)
      and (
        p_assignment_status is null
        or exists (
          select 1
          from public.safety_project_assignments assignment_filter
          where assignment_filter.membership_id = membership.id
            and assignment_filter.assignment_status = p_assignment_status
        )
      )
      and (p_eligibility_status is null or (active_assignment.value).eligibility_status = p_eligibility_status)
      and (
        p_document_status is null
        or app_private.safety_workforce_document_readiness(worker.id, 'health_check') = p_document_status
        or app_private.safety_workforce_document_readiness(worker.id, 'insurance') = p_document_status
      )
      and (
        nullif(trim(p_search), '') is null
        or worker.worker_code ilike '%' || trim(p_search) || '%'
        or worker.full_name ilike '%' || trim(p_search) || '%'
        or worker.phone ilike '%' || trim(p_search) || '%'
      )
      and (
        p_cursor_created_at is null
        or p_cursor_id is null
        or (membership.created_at, membership.id) < (p_cursor_created_at, p_cursor_id)
      )
    order by membership.created_at desc, membership.id desc
    limit v_limit + 1
  ),
  page as materialized (
    select filtered.membership_id,
           filtered.membership_created_at,
           filtered.membership_json,
           filtered.worker_json,
           filtered.subcontractor_json,
           filtered.team_json,
           filtered.assignment_json,
           filtered.card_json,
           filtered.masked_identity,
           filtered.profile_readiness,
           filtered.health_readiness,
           filtered.insurance_readiness
    from filtered
    order by filtered.membership_created_at desc, filtered.membership_id desc
    limit v_limit
  )
  select jsonb_build_object(
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'membership', page.membership_json,
        'worker', page.worker_json,
        'subcontractor', page.subcontractor_json,
        'team', page.team_json,
        'activeAssignment', page.assignment_json,
        'activeCard', page.card_json,
        'identityNumberMasked', page.masked_identity,
        'profileStatus', page.profile_readiness,
        'healthStatus', page.health_readiness,
        'insuranceStatus', page.insurance_readiness
      ) order by page.membership_created_at desc, page.membership_id desc)
      from page
    ), '[]'::jsonb),
    'nextCursor', case when (select count(*) from filtered) > v_limit then (
      select jsonb_build_object(
        'createdAt', page.membership_created_at,
        'id', page.membership_id
      )
      from page
      order by page.membership_created_at, page.membership_id
      limit 1
    ) else null end,
    'capabilities', app_private.safety_workforce_capabilities(p_project_id, p_construction_site_id)
  )
  into v_result;

  return v_result;
end;
$$;


--
-- Name: list_safety_site_workforce_options(text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.list_safety_site_workforce_options(p_project_id text, p_construction_site_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform app_private.safety_workforce_assert_scope(p_project_id, p_construction_site_id);
  if not app_private.safety_workforce_can_view(p_project_id, p_construction_site_id) then
    raise exception 'SAFETY_SCOPE_MISMATCH: actor cannot view target site' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'subcontractors', coalesce((
      select jsonb_agg(jsonb_build_object('id', subcontractor.id, 'name', subcontractor.name, 'code', subcontractor.code, 'status', subcontractor.status) order by subcontractor.name, subcontractor.id)
      from public.safety_subcontractors subcontractor
      where subcontractor.project_id = p_project_id
        and subcontractor.construction_site_id = p_construction_site_id::text
        and subcontractor.status in ('approved', 'active')
    ), '[]'::jsonb),
    'teams', coalesce((
      select jsonb_agg(jsonb_build_object('id', team.id, 'name', team.name, 'code', team.code, 'status', team.status, 'subcontractorId', team.subcontractor_id) order by team.name, team.id)
      from public.safety_teams team
      where team.project_id = p_project_id
        and team.construction_site_id = p_construction_site_id::text
        and team.status = 'active'
    ), '[]'::jsonb),
    'certificateTypes', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', certificate_type.id,
        'code', certificate_type.code,
        'name', certificate_type.name,
        'isRequiredDefault', certificate_type.is_required_default,
        'validityDays', certificate_type.validity_days,
        'appliesToRoles', certificate_type.applies_to_roles,
        'isActive', certificate_type.is_active,
        'sortOrder', certificate_type.sort_order
      ) order by certificate_type.sort_order, certificate_type.name, certificate_type.id)
      from public.safety_certificate_types certificate_type
      where certificate_type.is_active
    ), '[]'::jsonb)
  );
end;
$$;


--
-- Name: list_usable_request_templates(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.list_usable_request_templates() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object('items', coalesce(jsonb_agg(item order by item ->> 'name'), '[]'::jsonb))
  from (
    select jsonb_build_object(
      'templateId', template.id,
      'templateVersionId', version.id,
      'name', template.name,
      'description', template.description,
      'versionNumber', version.version_number,
      'formSchema', version.form_schema,
      'approvalBlocks', coalesce((
        select jsonb_agg(jsonb_build_object(
          'key', block.block_key,
          'name', block.name,
          'source', block.approver_source,
          'minimumDynamicApprovers', block.minimum_dynamic_approvers,
          'sortOrder', block.sort_order
        ) order by block.sort_order)
        from public.request_approval_blocks block
        where block.request_template_version_id = version.id
      ), '[]'::jsonb)
    ) as item
    from public.request_templates template
    join public.request_template_versions version on version.id = template.current_version_id
    where template.lifecycle_status = 'PUBLISHED'
      and version.status = 'PUBLISHED'
      and app_private.request_template_version_can_use(
        version.id, public.current_app_user_id()
      )
  ) usable;
$$;


--
-- Name: log_feedback_status_change(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.log_feedback_status_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.status is distinct from new.status then
    insert into public.feedback_status_logs(
      feedback_id,
      old_status,
      new_status,
      changed_by,
      reason,
      metadata
    )
    values (
      new.id,
      old.status,
      new.status,
      public.current_app_user_id(),
      case when new.status = 'rejected' then new.rejected_reason else null end,
      jsonb_build_object(
        'priority', new.priority,
        'assignedTo', new.assigned_to
      )
    );
  end if;

  return new;
end;
$$;


--
-- Name: log_safety_card_print(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.log_safety_card_print(p_card_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_card public.safety_cards%rowtype;
  v_assignment public.safety_project_assignments%rowtype;
  v_membership public.safety_worker_site_memberships%rowtype;
  v_template_snapshot jsonb := '{}'::jsonb;
begin
  select card.*
  into v_card
  from public.safety_cards card
  where card.id = p_card_id
  for update;

  select assignment.*
  into v_assignment
  from public.safety_project_assignments assignment
  where assignment.id = v_card.assignment_id;

  select membership.*
  into v_membership
  from public.safety_worker_site_memberships membership
  where membership.id = v_assignment.membership_id;

  if v_card.id is null
    or v_actor is null
    or not app_private.safety_workforce_can_manage(v_membership.project_id, v_membership.construction_site_id)
  then
    raise exception 'SAFETY_SCOPE_MISMATCH: card is not printable'
      using errcode = '42501';
  end if;

  if v_card.template_id is not null then
    select jsonb_build_object(
      'id', template.id,
      'name', template.name,
      'layoutJson', template.layout_json,
      'backgroundAttachment', template.background_attachment
    )
    into v_template_snapshot
    from public.safety_card_templates template
    where template.id = v_card.template_id;
  end if;

  insert into public.safety_card_print_logs (
    card_id, printed_by, template_snapshot, metadata
  ) values (
    v_card.id,
    v_actor::text,
    coalesce(v_template_snapshot, '{}'::jsonb),
    jsonb_build_object('membershipId', v_membership.id)
  );

  update public.safety_cards as card
  set printed_count = card.printed_count + 1,
      updated_at = now()
  where card.id = v_card.id;

  insert into public.safety_audit_logs (
    actor_user_id, action, target_type, target_id, project_id, construction_site_id, metadata
  ) values (
    v_actor::text,
    'card.print',
    'safety_cards',
    v_card.id,
    v_membership.project_id,
    v_membership.construction_site_id::text,
    jsonb_build_object('assignmentId', v_assignment.id)
  );

  return app_private.safety_workforce_detail_for_membership(v_membership.id);
end;
$$;


--
-- Name: log_safety_issue_status_change(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.log_safety_issue_status_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    insert into public.safety_issue_status_logs(
      project_id,
      construction_site_id,
      issue_id,
      from_status,
      to_status,
      metadata,
      created_by
    )
    values (
      new.project_id,
      new.construction_site_id,
      new.id,
      null,
      new.status,
      jsonb_build_object('event', 'created'),
      coalesce(public.current_app_user_id()::text, new.created_by)
    );
    return new;
  end if;

  if old.status is distinct from new.status then
    insert into public.safety_issue_status_logs(
      project_id,
      construction_site_id,
      issue_id,
      from_status,
      to_status,
      metadata,
      created_by
    )
    values (
      new.project_id,
      new.construction_site_id,
      new.id,
      old.status,
      new.status,
      jsonb_build_object('event', 'status_changed'),
      coalesce(public.current_app_user_id()::text, new.created_by)
    );
  end if;

  return new;
end;
$$;


--
-- Name: lookup_safety_worker_exact(text, uuid, text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.lookup_safety_worker_exact(p_project_id text, p_construction_site_id uuid, p_worker_code text DEFAULT NULL::text, p_identity_type text DEFAULT NULL::text, p_identity_number text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_worker public.safety_worker_profiles%rowtype;
  v_membership public.safety_worker_site_memberships%rowtype;
  v_assignment public.safety_project_assignments%rowtype;
  v_active_site_name text;
  v_match_type text;
  v_result jsonb;
begin
  perform app_private.safety_workforce_assert_scope(p_project_id, p_construction_site_id);
  if not app_private.safety_workforce_can_manage(p_project_id, p_construction_site_id) then
    raise exception 'SAFETY_SCOPE_MISMATCH: actor cannot search global worker profiles'
      using errcode = '42501';
  end if;

  if nullif(trim(p_worker_code), '') is not null then
    v_match_type := 'worker_code';
    select worker.*
    into v_worker
    from public.safety_worker_profiles worker
    where lower(worker.worker_code) = lower(trim(p_worker_code))
    limit 1;
  elsif p_identity_type in ('cccd', 'passport', 'other')
    and app_private.safety_workforce_normalize_identity(p_identity_number) is not null
  then
    v_match_type := 'identity';
    select worker.*
    into v_worker
    from public.safety_worker_profiles worker
    where worker.identity_type = p_identity_type
      and worker.identity_number_normalized = app_private.safety_workforce_normalize_identity(p_identity_number)
    limit 1;
  else
    raise exception 'SAFETY_INVALID_RPC_PAYLOAD: exact worker code or identity is required'
      using errcode = '22023';
  end if;

  if v_worker.id is null then
    insert into public.safety_audit_logs (
      actor_user_id, action, target_type, project_id, construction_site_id, metadata
    ) values (
      public.current_app_user_id()::text,
      'worker.exact_lookup',
      'safety_worker_profiles',
      p_project_id,
      p_construction_site_id::text,
      jsonb_build_object('matchType', v_match_type, 'found', false)
    );
    return null;
  end if;

  select membership.*
  into v_membership
  from public.safety_worker_site_memberships membership
  where membership.worker_id = v_worker.id
    and membership.project_id = p_project_id
    and membership.construction_site_id = p_construction_site_id
  limit 1;

  select assignment.*
  into v_assignment
  from public.safety_project_assignments assignment
  where assignment.worker_id = v_worker.id
    and assignment.assignment_status = 'active'
  order by assignment.started_at desc, assignment.id desc
  limit 1;

  if v_assignment.id is not null then
    select site.name
    into v_active_site_name
    from public.safety_worker_site_memberships active_membership
    join public.hrm_construction_sites site on site.id = active_membership.construction_site_id
    where active_membership.id = v_assignment.membership_id;
  end if;

  v_result := jsonb_build_object(
    'workerId', v_worker.id,
    'workerCode', v_worker.worker_code,
    'fullName', v_worker.full_name,
    'workerKind', v_worker.worker_kind,
    'identityNumberMasked', coalesce(app_private.safety_workforce_mask_identity(v_worker.id), '-'),
    'targetMembershipId', v_membership.id,
    'activeAssignmentId', v_assignment.id,
    'activeProjectId', v_assignment.project_id,
    'activeConstructionSiteId', v_assignment.construction_site_id,
    'activeSiteName', v_active_site_name,
    'canTransfer', case
      when v_assignment.id is null then false
      when v_assignment.membership_id = v_membership.id then false
      else exists (
        select 1
        from public.safety_worker_site_memberships active_membership
        where active_membership.id = v_assignment.membership_id
          and app_private.safety_workforce_can_manage(
            active_membership.project_id,
            active_membership.construction_site_id
          )
      )
    end
  );

  insert into public.safety_audit_logs (
    actor_user_id, action, target_type, target_id, project_id, construction_site_id, metadata
  ) values (
    public.current_app_user_id()::text,
    'worker.exact_lookup',
    'safety_worker_profiles',
    v_worker.id,
    p_project_id,
    p_construction_site_id::text,
    jsonb_build_object('matchType', v_match_type, 'found', true)
  );

  return v_result;
end;
$$;


--
-- Name: material_flow_has_action_or_legacy(text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.material_flow_has_action_or_legacy(p_project_id text, p_construction_site_id text, p_permission_code text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    public.is_admin()
    or public.is_module_admin('DA')
    or app_private.company_procurement_can_manage()
    or app_private.project_user_has_permission(p_project_id, p_construction_site_id, 'edit')
    or app_private.project_user_has_permission(p_project_id, p_construction_site_id, 'submit')
    or app_private.project_user_has_permission(p_project_id, p_construction_site_id, 'approve')
    or app_private.project_user_has_permission(p_project_id, p_construction_site_id, 'confirm')
    or app_private.material_has_action(p_project_id, p_construction_site_id, p_permission_code, public.current_app_user_id()),
    false
  );
$$;


--
-- Name: material_has_action(text, text, text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.material_has_action(p_project_id text, p_construction_site_id text, p_permission_code text, p_user_id uuid DEFAULT public.current_app_user_id()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when p_permission_code = 'project.material_po.view' then
      app_private.project_actor_has_effective_room_action(
        p_user_id, p_project_id, p_construction_site_id, 'material_po', 'view'
      )
    when p_permission_code = 'project.material_po.create' then
      app_private.project_actor_has_effective_room_action(
        p_user_id, p_project_id, p_construction_site_id, 'material_po', 'edit'
      )
    when p_permission_code = 'project.material_po.delete' then
      app_private.project_actor_has_effective_room_action(
        p_user_id, p_project_id, p_construction_site_id, 'material_po', 'delete'
      )
    when p_permission_code = 'project.material_po.approve' then
      app_private.project_actor_has_effective_room_action(
        p_user_id, p_project_id, p_construction_site_id, 'material_po', 'approve'
      )
    when p_permission_code = 'project.material_po.receive' then
      app_private.project_actor_has_effective_room_action(
        p_user_id, p_project_id, p_construction_site_id, 'material_po', 'confirm'
      )
    when p_permission_code = 'project.material_po.manage' then
      public.is_admin()
      or (
        app_private.permission_hardening_flag('project_room_pbac_fallback_enabled')
        and app_private.project_has_permission_v2(
          p_project_id, p_construction_site_id, p_permission_code, p_user_id
        )
      )
    else
      (
        p_permission_code like 'project.material%'
        or p_permission_code like 'project.custom_material.%'
      )
      and (
        public.is_admin()
        or public.is_module_admin('DA')
        or app_private.project_has_permission_v2(
          p_project_id, p_construction_site_id, p_permission_code, p_user_id
        )
      )
  end;
$$;


--
-- Name: material_has_any_action(text, text, text[], uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.material_has_any_action(p_project_id text, p_construction_site_id text, p_permission_codes text[], p_user_id uuid DEFAULT public.current_app_user_id()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
