--
-- Name: material_issue_orders; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.material_issue_orders (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    issue_no text NOT NULL,
    project_id text,
    construction_site_id text,
    source_warehouse_id text NOT NULL,
    recipient_type text NOT NULL,
    recipient_id text,
    recipient_name text NOT NULL,
    responsible_user_id uuid,
    subcontractor_contract_id text,
    material_request_id text,
    work_boq_item_id text,
    needed_date date,
    status text DEFAULT 'draft'::text NOT NULL,
    transaction_id text,
    qr_token text DEFAULT replace((gen_random_uuid())::text, '-'::text, ''::text) NOT NULL,
    note text,
    override_reason text,
    attachments jsonb DEFAULT '[]'::jsonb NOT NULL,
    created_by uuid,
    submitted_by uuid,
    submitted_at timestamp with time zone,
    issued_by uuid,
    issued_at timestamp with time zone,
    closed_by uuid,
    closed_at timestamp with time zone,
    cancelled_by uuid,
    cancelled_at timestamp with time zone,
    cancel_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    recipient_source_type text,
    recipient_source_id text,
    voucher_date date,
    CONSTRAINT material_issue_orders_recipient_source_type_check CHECK (((recipient_source_type IS NULL) OR (recipient_source_type = ANY (ARRAY['supplier_contract'::text, 'business_partner'::text])))),
    CONSTRAINT material_issue_orders_recipient_type_check CHECK ((recipient_type = ANY (ARRAY['employee'::text, 'work_group'::text, 'subcontractor'::text, 'partner'::text, 'manual'::text]))),
    CONSTRAINT material_issue_orders_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'submitted'::text, 'wms_pending'::text, 'issued'::text, 'partially_received'::text, 'received'::text, 'settling'::text, 'partially_returned'::text, 'closed'::text, 'rejected'::text, 'cancelled'::text])))
);


--
-- Name: material_issue_refresh_status(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.material_issue_refresh_status(p_order_id uuid) RETURNS public.material_issue_orders
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_order public.material_issue_orders%rowtype;
  v_total_issued numeric;
  v_total_received numeric;
  v_total_open numeric;
  v_next_status text;
begin
  select * into v_order from public.material_issue_orders where id = p_order_id for update;
  if not found then raise exception 'Không tìm thấy phiếu xuất cấp.'; end if;
  if v_order.status in ('draft', 'submitted', 'wms_pending', 'rejected', 'cancelled') then
    return v_order;
  end if;

  select
    coalesce(sum(issued_qty), 0),
    coalesce(sum(received_qty), 0),
    coalesce(sum(greatest(issued_qty - consumed_qty - returned_qty - lost_qty, 0)), 0)
  into v_total_issued, v_total_received, v_total_open
  from public.material_issue_lines
  where issue_order_id = p_order_id;

  if v_total_issued <= 0 then
    v_next_status := 'wms_pending';
  elsif v_total_open = 0 then
    v_next_status := 'closed';
  elsif v_total_received >= v_total_issued then
    v_next_status := 'received';
  elsif v_total_received > 0 then
    v_next_status := 'partially_received';
  elsif exists (
    select 1 from public.material_issue_lines
    where issue_order_id = p_order_id and returned_qty > 0
  ) then
    v_next_status := 'partially_returned';
  else
    v_next_status := 'issued';
  end if;

  update public.material_issue_orders
  set status = v_next_status,
      closed_by = case when v_next_status = 'closed' then coalesce(closed_by, public.current_app_user_id()) else closed_by end,
      closed_at = case when v_next_status = 'closed' then coalesce(closed_at, now()) else closed_at end
  where id = p_order_id
  returning * into v_order;

  return v_order;
end;
$$;


--
-- Name: material_request_actor_is_current_assignee(text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.material_request_actor_is_current_assignee(p_request_id text, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.requests request_row
    where request_row.id = p_request_id
      and (
        request_row.submitted_to_user_id = p_user_id::text
        or exists (
          select 1
          from public.workflow_subjects subject
          join public.workflow_step_assignments assignment
            on assignment.workflow_subject_id = subject.id
            and assignment.status = 'PENDING'
          where subject.subject_type = 'material_request'
            and subject.subject_id = request_row.id
            and subject.status in ('RUNNING', 'RETURNED')
            and assignment.assignee_user_id = p_user_id
        )
      )
  );
$$;


--
-- Name: material_request_batch_is_fully_reversed(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.material_request_batch_is_fully_reversed(p_batch_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_batch public.material_request_fulfillment_batches%rowtype;
  v_transaction_status text;
  v_return_transaction_ids text[] := '{}'::text[];
  v_has_unfinished_return boolean := false;
  v_has_insufficient_return boolean := false;
begin
  select * into v_batch
  from public.material_request_fulfillment_batches b
  where b.id = p_batch_id;

  if not found
     or lower(coalesce(v_batch.status::text, '')) not in ('cancelled', 'canceled', 'returned', 'reversed', 'void') then
    return false;
  end if;

  if v_batch.transaction_id is null then
    return not exists (
      select 1
      from public.material_request_fulfillment_lines line
      where line.batch_id = p_batch_id
        and case when coalesce(line.received_qty, 0) > 0
          then coalesce(line.received_qty, 0) else coalesce(line.issued_qty, 0) end > 0
    );
  end if;

  select upper(coalesce(t.status::text, '')) into v_transaction_status
  from public.transactions t
  where t.id::text = v_batch.transaction_id::text;

  if coalesce(v_transaction_status, '') = 'CANCELLED' then
    return true;
  end if;
  if coalesce(v_transaction_status, '') <> 'COMPLETED' then
    return false;
  end if;

  select coalesce(array_agg(distinct match[1]), '{}'::text[])
    into v_return_transaction_ids
  from regexp_matches(
    coalesce(v_batch.note, ''),
    'Phiếu hoàn kho:[[:space:]]*([^[:space:]|]+)',
    'gi'
  ) as match;

  if coalesce(array_length(v_return_transaction_ids, 1), 0) = 0 then
    return false;
  end if;

  select exists (
    select 1
    from unnest(v_return_transaction_ids) return_id
    left join public.transactions t
      on t.id::text = return_id
     and upper(coalesce(t.status::text, '')) = 'COMPLETED'
    where t.id is null
  ) into v_has_unfinished_return;
  if v_has_unfinished_return then
    return false;
  end if;

  select exists (
    with line_required as (
      select line.item_id::text as item_id,
        sum(case when coalesce(line.received_qty, 0) > 0
          then coalesce(line.received_qty, 0) else coalesce(line.issued_qty, 0) end)::numeric as qty
      from public.material_request_fulfillment_lines line
      where line.batch_id = p_batch_id
        and line.item_id is not null
        and case when coalesce(line.received_qty, 0) > 0
          then coalesce(line.received_qty, 0) else coalesce(line.issued_qty, 0) end > 0
      group by line.item_id::text
    ),
    transaction_required as (
      select
        coalesce(item.value ->> 'itemId', item.value ->> 'item_id') as item_id,
        sum(coalesce(nullif(item.value ->> 'quantity', '')::numeric, 0))::numeric as qty
      from public.transactions t
      cross join lateral jsonb_array_elements(coalesce(t.items, '[]'::jsonb)) item(value)
      where t.id::text = v_batch.transaction_id::text
        and coalesce(item.value ->> 'itemId', item.value ->> 'item_id') is not null
      group by coalesce(item.value ->> 'itemId', item.value ->> 'item_id')
    ),
    required as (
      select item_id, qty from line_required
      union all
      select item_id, qty from transaction_required
      where not exists (select 1 from line_required)
    ),
    returned as (
      select
        coalesce(item.value ->> 'itemId', item.value ->> 'item_id') as item_id,
        sum(coalesce(nullif(item.value ->> 'quantity', '')::numeric, 0))::numeric as qty
      from public.transactions t
      cross join lateral jsonb_array_elements(coalesce(t.items, '[]'::jsonb)) item(value)
      where t.id::text = any(v_return_transaction_ids)
        and upper(coalesce(t.status::text, '')) = 'COMPLETED'
        and coalesce(item.value ->> 'itemId', item.value ->> 'item_id') is not null
      group by coalesce(item.value ->> 'itemId', item.value ->> 'item_id')
    )
    select 1
    from required req
    left join returned ret on ret.item_id = req.item_id
    where coalesce(ret.qty, 0) + 0.000000001 < req.qty
    limit 1
  ) into v_has_insufficient_return;

  return not v_has_insufficient_return;
end;
$$;


