--
-- Name: material_request_can_delete(text, text, text, boolean, uuid, text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.material_request_can_delete(p_request_origin text, p_project_id text, p_status text, p_ever_submitted boolean, p_requester_id uuid, p_submitted_to_user_id text, p_source_warehouse_id text, p_site_warehouse_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when coalesce(p_request_origin, 'wms') = 'project' then
      coalesce(p_status, 'DRAFT') in ('DRAFT', 'REJECTED')
      and (
        public.is_admin()
        or public.is_module_admin('DA')
        or (
          p_requester_id = public.current_app_user_id()
          and not coalesce(p_ever_submitted, false)
          and app_private.material_has_action(p_project_id, null, 'project.material_request.create', public.current_app_user_id())
        )
      )
    else (
      public.is_admin()
      or public.is_module_admin('WMS')
      or (
        coalesce(p_status, 'DRAFT') in ('DRAFT', 'REJECTED')
        and p_requester_id = public.current_app_user_id()
      )
      or app_private.current_user_is_global_wms_keeper()
      or app_private.current_user_is_wms_keeper_for(p_source_warehouse_id)
      or app_private.current_user_is_wms_keeper_for(p_site_warehouse_id)
      or p_submitted_to_user_id = public.current_app_user_id()::text
    )
  end;
$$;


--
-- Name: material_request_can_delete_v2(text, text, text, boolean, uuid, text, text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.material_request_can_delete_v2(p_request_origin text, p_project_id text, p_status text, p_ever_submitted boolean, p_requester_id uuid, p_submitted_to_user_id text, p_source_warehouse_id text, p_site_warehouse_id text, p_workflow_step text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when coalesce(p_request_origin, 'wms') = 'project' then (
      public.is_admin()
      or app_private.project_user_has_permission(p_project_id, null, 'delete')
      or (
        p_requester_id = public.current_app_user_id()
        and (
          coalesce(p_status, 'DRAFT') = 'REJECTED'
          or coalesce(p_workflow_step, '') = 'returned_to_creator'
          or (
            coalesce(p_status, 'DRAFT') = 'DRAFT'
            and not coalesce(p_ever_submitted, false)
          )
        )
      )
    )
    else (
      public.is_admin()
      or public.is_module_admin('WMS')
      or (
        coalesce(p_status, 'DRAFT') in ('DRAFT', 'REJECTED')
        and p_requester_id = public.current_app_user_id()
      )
      or app_private.current_user_is_global_wms_keeper()
      or app_private.current_user_is_wms_keeper_for(p_source_warehouse_id)
      or app_private.current_user_is_wms_keeper_for(p_site_warehouse_id)
      or (
        p_submitted_to_user_id is not null
        and p_submitted_to_user_id = public.current_app_user_id()::text
      )
    )
  end;
$$;


--
-- Name: material_request_can_delete_v3(text, text, text, text, boolean, uuid, text, text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.material_request_can_delete_v3(p_request_origin text, p_project_id text, p_construction_site_id text, p_status text, p_ever_submitted boolean, p_requester_id uuid, p_submitted_to_user_id text, p_source_warehouse_id text, p_site_warehouse_id text, p_workflow_step text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case when coalesce(p_request_origin, 'wms') = 'project' then
    p_requester_id = public.current_app_user_id()
    and (
      coalesce(p_status, 'DRAFT') in ('DRAFT', 'REJECTED')
      or coalesce(p_workflow_step, '') = 'returned_to_creator'
    )
    and app_private.current_actor_has_effective_room_action(
      p_project_id, p_construction_site_id, 'material_request', 'delete'
    )
  else app_private.material_request_can_delete_v2(
    p_request_origin, p_project_id, p_status, p_ever_submitted, p_requester_id,
    p_submitted_to_user_id, p_source_warehouse_id, p_site_warehouse_id, p_workflow_step
  ) end;
$$;


--
-- Name: material_request_can_select(text, text, uuid, text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.material_request_can_select(p_request_origin text, p_project_id text, p_requester_id uuid, p_submitted_to_user_id text, p_source_warehouse_id text, p_site_warehouse_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when coalesce(p_request_origin, 'wms') = 'project' then
      p_project_id is not null
      and (
        public.is_admin()
        or public.is_module_admin('DA')
        or p_requester_id = public.current_app_user_id()
        or p_submitted_to_user_id = public.current_app_user_id()::text
        or app_private.project_scope_has_any_grant_v2(p_project_id, null, public.current_app_user_id())
        or app_private.material_has_any_action(
          p_project_id,
          null,
          array[
            'project.material_request.view',
            'project.material_request.create',
            'project.material_request.edit_own',
            'project.material_request.edit_all',
            'project.material_request.submit',
            'project.material_request.return',
            'project.material_request.approve',
            'project.material_request.confirm_fulfillment',
            'project.material_request.view_available_stock'
          ],
          public.current_app_user_id()
        )
      )
    else app_private.wms_request_can_access(
      p_requester_id,
      p_submitted_to_user_id,
      p_source_warehouse_id,
      p_site_warehouse_id
    )
  end;
$$;


