--
-- Name: migrate_hrm_legacy_position(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.migrate_hrm_legacy_position(p_legacy_position_id uuid, p_target_position_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid;
  v_legacy public.hrm_positions%rowtype;
  v_target public.hrm_positions%rowtype;
  v_employee_count integer := 0;
  v_slot_count integer := 0;
begin
  if not app_private.has_hrm_template_permission(public.current_app_user_id(), 'hrm.master_data.manage') then
    raise exception using errcode = '42501', message = 'HRM_ADMIN_REQUIRED';
  end if;
  if p_legacy_position_id = p_target_position_id then
    raise exception using errcode = '22023', message = 'HRM_POSITION_TARGET_MUST_DIFFER';
  end if;

  v_actor_id := public.current_app_user_id();

  select * into v_legacy
  from public.hrm_positions
  where id = p_legacy_position_id
  for update;
  if v_legacy.id is null or v_legacy.source <> 'legacy' then
    raise exception using errcode = '22023', message = 'HRM_LEGACY_POSITION_REQUIRED';
  end if;

  select * into v_target
  from public.hrm_positions
  where id = p_target_position_id
    and source <> 'legacy'
    and is_active
  for update;
  if v_target.id is null then
    raise exception using errcode = '22023', message = 'HRM_ACTIVE_TARGET_POSITION_REQUIRED';
  end if;

  update public.employees
  set position_id = p_target_position_id,
      title = v_target.name,
      updated_at = now()
  where position_id = p_legacy_position_id;
  get diagnostics v_employee_count = row_count;

  update public.hrm_org_position_slots
  set position_id = p_target_position_id,
      level_code = v_target.level_code,
      updated_by = v_actor_id,
      updated_at = now(),
      description = concat_ws(E'\n', nullif(description, ''),
        'Chuyển từ vị trí LEGACY ' || coalesce(v_legacy.name, p_legacy_position_id::text))
  where position_id = p_legacy_position_id;
  get diagnostics v_slot_count = row_count;

  update public.hrm_positions
  set is_active = false
  where id = p_legacy_position_id;

  insert into public.audit_trail (
    table_name, record_id, action, old_data, new_data, user_id, module,
    description, record_label, entity_type, changed_fields, change_count, impact_level
  ) values (
    'hrm_positions', p_legacy_position_id::text, 'UPDATE', to_jsonb(v_legacy),
    jsonb_build_object(
      'target_position_id', p_target_position_id,
      'target_position_code', v_target.code,
      'target_position_name', v_target.name,
      'employees_migrated', v_employee_count,
      'slots_migrated', v_slot_count,
      'legacy_position_archived', true
    ),
    v_actor_id::text, 'HRM', 'Chuyển đổi vị trí LEGACY sang vị trí dùng chung',
    coalesce(v_legacy.name, p_legacy_position_id::text), 'HRM_POSITION_MIGRATION',
    array['position_id', 'title', 'level_code', 'is_active'], 4, 'high'
  );

  return jsonb_build_object(
    'legacy_position_id', p_legacy_position_id,
    'target_position_id', p_target_position_id,
    'employees_migrated', v_employee_count,
    'slots_migrated', v_slot_count
  );
end;
$$;


--
-- Name: next_inventory_ledger_code(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.next_inventory_ledger_code(p_direction text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_prefix text;
  v_seq regclass;
begin
  if lower(coalesce(p_direction, '')) = 'in' then
    v_prefix := 'NK';
    v_seq := 'public.inventory_receipt_code_seq'::regclass;
  elsif lower(coalesce(p_direction, '')) = 'out' then
    v_prefix := 'XK';
    v_seq := 'public.inventory_issue_code_seq'::regclass;
  else
    raise exception 'invalid inventory ledger direction: %', p_direction;
  end if;

  return v_prefix || to_char(now(), 'YYYYMMDD') || '-' || lpad(nextval(v_seq)::text, 5, '0');
end;
$$;


--
-- Name: next_request_code(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.next_request_code() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_year integer := extract(year from now())::integer;
  v_next bigint;
begin
  v_next := nextval('app_private.request_code_sequence'::regclass);

  return 'RQ-' || v_year::text || '-' || lpad(v_next::text, 6, '0');
end;
$$;


--
-- Name: normalize_direct_permission_state(jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.normalize_direct_permission_state(p_grants jsonb) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'permissionCode', normalized.permission_code,
        'scopeType', normalized.scope_type,
        'scopeId', normalized.scope_id,
        'expiresAt', normalized.expires_at
      )
      order by normalized.permission_code, normalized.scope_type,
        normalized.scope_id, normalized.expires_at
    ),
    '[]'::jsonb
  )
  from (
    select
      grant_row.permission_code,
      coalesce(nullif(grant_row.scope_type, ''), 'global') as scope_type,
      coalesce(nullif(grant_row.scope_id, ''), '*') as scope_id,
      grant_row.expires_at
    from jsonb_to_recordset(coalesce(p_grants, '[]'::jsonb)) grant_row(
      permission_code text,
      scope_type text,
      scope_id text,
      is_active boolean,
      expires_at timestamptz
    )
    where coalesce(grant_row.is_active, true)
      and (grant_row.expires_at is null or grant_row.expires_at > now())
  ) normalized;
$$;


--
-- Name: normalize_legacy_permission_state(jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.normalize_legacy_permission_state(p_state jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_allowed_modules jsonb;
  v_admin_modules jsonb;
  v_allowed_sub_modules jsonb;
  v_admin_sub_modules jsonb;
  v_module_count integer;
  v_route_count integer;
begin
  if p_state is null or jsonb_typeof(p_state) <> 'object'
    or jsonb_typeof(p_state -> 'allowedModules') <> 'array'
    or jsonb_typeof(p_state -> 'adminModules') <> 'array'
    or jsonb_typeof(p_state -> 'allowedSubModules') <> 'object'
    or jsonb_typeof(p_state -> 'adminSubModules') <> 'object'
  then
    raise exception 'Legacy permission state must contain module arrays and submodule objects'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_state -> 'allowedModules') item
    where jsonb_typeof(item) <> 'string'
  ) or exists (
    select 1
    from jsonb_array_elements(p_state -> 'adminModules') item
    where jsonb_typeof(item) <> 'string'
  ) or exists (
    select 1
    from jsonb_each(p_state -> 'allowedSubModules') entry
    where jsonb_typeof(entry.value) <> 'array'
       or exists (
         select 1
         from jsonb_array_elements(entry.value) item
         where jsonb_typeof(item) <> 'string'
       )
  ) or exists (
    select 1
    from jsonb_each(p_state -> 'adminSubModules') entry
    where jsonb_typeof(entry.value) <> 'array'
       or exists (
         select 1
         from jsonb_array_elements(entry.value) item
         where jsonb_typeof(item) <> 'string'
       )
  ) then
    raise exception 'Legacy permission values must be strings'
      using errcode = '22023';
  end if;

  select coalesce(jsonb_agg(value order by value), '[]'::jsonb)
  into v_allowed_modules
  from (
    select distinct btrim(item #>> '{}') as value
    from jsonb_array_elements(p_state -> 'allowedModules') item
    where btrim(item #>> '{}') <> ''
  ) normalized;

  select coalesce(jsonb_agg(value order by value), '[]'::jsonb)
  into v_admin_modules
  from (
    select distinct btrim(item #>> '{}') as value
    from jsonb_array_elements(p_state -> 'adminModules') item
    where btrim(item #>> '{}') <> ''
  ) normalized;

  select coalesce(jsonb_object_agg(module_key, routes order by module_key), '{}'::jsonb)
  into v_allowed_sub_modules
  from (
    select
      btrim(entry.key) as module_key,
      (
        select coalesce(jsonb_agg(route order by route), '[]'::jsonb)
        from (
          select distinct btrim(item #>> '{}') as route
          from jsonb_array_elements(entry.value) item
          where btrim(item #>> '{}') <> ''
        ) normalized_routes
      ) as routes
    from jsonb_each(p_state -> 'allowedSubModules') entry
    where btrim(entry.key) <> ''
  ) normalized;

  select coalesce(jsonb_object_agg(module_key, routes order by module_key), '{}'::jsonb)
  into v_admin_sub_modules
  from (
    select
      btrim(entry.key) as module_key,
      (
        select coalesce(jsonb_agg(route order by route), '[]'::jsonb)
        from (
          select distinct btrim(item #>> '{}') as route
          from jsonb_array_elements(entry.value) item
          where btrim(item #>> '{}') <> ''
        ) normalized_routes
      ) as routes
    from jsonb_each(p_state -> 'adminSubModules') entry
    where btrim(entry.key) <> ''
  ) normalized;

  select count(*)
  into v_module_count
  from (
    select value from jsonb_array_elements_text(v_allowed_modules)
    union
    select value from jsonb_array_elements_text(v_admin_modules)
    union
    select key from jsonb_object_keys(v_allowed_sub_modules) key
    union
    select key from jsonb_object_keys(v_admin_sub_modules) key
  ) modules;

  select count(*)
  into v_route_count
  from (
    select entry.key, route.value
    from jsonb_each(v_allowed_sub_modules) entry
    cross join lateral jsonb_array_elements_text(entry.value) route
    union all
    select entry.key, route.value
    from jsonb_each(v_admin_sub_modules) entry
    cross join lateral jsonb_array_elements_text(entry.value) route
  ) routes;

  if v_module_count > 100 or v_route_count > 1000 then
    raise exception 'Legacy permission state exceeds bounded limits'
      using errcode = '22023';
  end if;

  return jsonb_build_object(
    'allowedModules', v_allowed_modules,
    'allowedSubModules', v_allowed_sub_modules,
    'adminModules', v_admin_modules,
    'adminSubModules', v_admin_sub_modules
  );
end;
$$;


--
-- Name: normalize_permission_quick_template_codes(jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.normalize_permission_quick_template_codes(p_permission_codes jsonb) RETURNS TABLE(permission_code text, sort_order integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with raw_items as (
    select
      btrim(value #>> '{}') as permission_code,
      row_number() over ()::integer as sort_order
    from jsonb_array_elements(coalesce(p_permission_codes, '[]'::jsonb))
  )
  select raw_items.permission_code, min(raw_items.sort_order)::integer
  from raw_items
  where raw_items.permission_code <> ''
  group by raw_items.permission_code
  order by min(raw_items.sort_order), raw_items.permission_code
$$;


--
-- Name: normalize_po_delivery_transaction_counterparty_v2(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.normalize_po_delivery_transaction_counterparty_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.source_type = 'po_delivery_batch'
    and new.supplier_id is not null
    and not exists (
      select 1
      from public.suppliers supplier
      where supplier.id = new.supplier_id
    )
    and exists (
      select 1
      from public.business_partners partner
      where partner.id = new.supplier_id
    )
  then
    new.business_partner_id := new.supplier_id;
    new.supplier_id := null;
  end if;

  return new;
end;
$$;


--
-- Name: normalize_safety_equipment_document_checklist(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.normalize_safety_equipment_document_checklist() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.is_done then
    new.done_at := coalesce(new.done_at, now());
    new.done_by := coalesce(new.done_by, public.current_app_user_id()::text);
    if new.status = 'missing' then
      new.status := 'submitted';
    end if;
  else
    new.done_at := null;
    new.done_by := null;
    if new.status in ('submitted', 'approved') then
      new.status := 'missing';
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: normalize_workflow_instance_comment_mentions(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.normalize_workflow_instance_comment_mentions() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  select coalesce(
    jsonb_agg(
      jsonb_build_object('userId', candidate.user_id, 'displayName', candidate.display_name)
      order by candidate.display_name, candidate.user_id
    ),
    '[]'::jsonb
  )
  into new.mentions
  from (
    select distinct on (mentioned_user.id)
      mentioned_user.id as user_id,
      mentioned_user.name as display_name
    from jsonb_array_elements(coalesce(new.mentions, '[]'::jsonb)) mention
    join public.users mentioned_user
      on mentioned_user.id::text = nullif(mention ->> 'userId', '')
     and mentioned_user.is_active
     and mentioned_user.account_status = 'ACTIVE'
    where mentioned_user.id <> new.author_user_id
      and position(('@' || mentioned_user.name) in new.body) > 0
    order by mentioned_user.id
    limit 20
  ) candidate;

  return new;
end;
$$;


--
-- Name: notify_workflow_instance_comment_mentions(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.notify_workflow_instance_comment_mentions() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_author_name text;
  v_instance_code text;
  v_instance_title text;
  v_message text;
begin
  if jsonb_array_length(new.mentions) = 0 then
    return new;
  end if;

  select author.name
  into v_author_name
  from public.users author
  where author.id = new.author_user_id;

  select instance.code, instance.title
  into v_instance_code, v_instance_title
  from public.workflow_instances instance
  where instance.id = new.instance_id;

  v_message := format(
    '%s đã nhắc đến bạn trong quy trình %s%s.',
    coalesce(v_author_name, 'Một nhân viên'),
    coalesce(v_instance_code, ''),
    case
      when nullif(trim(coalesce(v_instance_title, '')), '') is null then ''
      when nullif(trim(coalesce(v_instance_code, '')), '') is null then v_instance_title
      else ' - ' || v_instance_title
    end
  );

  insert into public.notifications (
    user_id,
    title,
    body,
    type,
    priority,
    module,
    link,
    metadata,
    category,
    message,
    icon,
    severity,
    source_type,
    source_id,
    push_enabled,
    action_url,
    entity_type,
    entity_id
  )
  select
    mention ->> 'userId',
    'Bạn được nhắc đến trong thảo luận quy trình',
    v_message,
    'info',
    'normal',
    'WF',
    '/wf?instanceId=' || new.instance_id::text,
    jsonb_build_object(
      'instanceId', new.instance_id,
      'commentId', new.id,
      'authorUserId', new.author_user_id
    ),
    'workflow',
    v_message,
    '💬',
    'info',
    'workflow_comment_mention',
    new.instance_id::text,
    true,
    '/wf?instanceId=' || new.instance_id::text,
    'workflow_instance_comment',
    new.id
  from jsonb_array_elements(new.mentions) mention;

  return new;
end;
$$;


--
-- Name: operator_unavailability_calendar_rows(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.operator_unavailability_calendar_rows(p_actor_user_id uuid) RETURNS TABLE(id uuid, operator_user_id uuid, start_at timestamp with time zone, end_at timestamp with time zone, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    period.id,
    period.operator_user_id,
    period.start_at,
    period.end_at,
    period.created_at
  from public.operator_unavailability_periods period
  where period.operator_user_id = p_actor_user_id
     or app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.dispatch')
     or app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.manage_authorizations');
$$;


--
-- Name: permission_hardening_flag(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.permission_hardening_flag(p_key text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    (
      select case jsonb_typeof(s.value)
        when 'boolean' then (s.value #>> '{}')::boolean
        when 'string' then (s.value #>> '{}')::boolean
        else false
      end
      from app_private.permission_hardening_settings s
      where s.key = p_key
      limit 1
    ),
    false
  );
$$;


--
-- Name: permission_state_fingerprint_for_values(jsonb, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.permission_state_fingerprint_for_values(p_legacy_state jsonb, p_direct_state jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select md5(jsonb_build_object(
    'legacy', app_private.normalize_legacy_permission_state(p_legacy_state),
    'direct', coalesce(p_direct_state, '[]'::jsonb)
  )::text);
$$;


--
-- Name: post_inventory_ledger_entry(uuid, integer, text, timestamp with time zone, text, text, text, text, text, text, text, text, text, text, text, numeric, numeric, text, jsonb, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.post_inventory_ledger_entry(p_inventory_transaction_id uuid, p_entry_no integer, p_document_code text, p_transaction_date timestamp with time zone, p_transaction_type text, p_direction text, p_material_id text, p_warehouse_id text, p_project_id text, p_construction_site_id text, p_source_type text, p_source_id text, p_source_code text, p_source_line_id text, p_related_request_id text, p_qty numeric, p_unit_price numeric, p_description text, p_metadata jsonb, p_created_by uuid, p_approved_by uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_entry_id uuid := gen_random_uuid();
  v_delta numeric;
  v_value_delta numeric;
  v_balance_after_qty numeric;
  v_balance_after_value numeric;
  v_unit text;
begin
  if p_qty is null or p_qty <= 0 then
    raise exception 'ledger quantity must be positive';
  end if;
  if nullif(p_material_id, '') is null then
    raise exception 'material id is required';
  end if;
  if nullif(p_warehouse_id, '') is null then
    raise exception 'warehouse id is required';
  end if;

  select i.unit into v_unit
  from public.items i
  where i.id = p_material_id;

  v_unit := coalesce(
    v_unit,
    nullif(p_metadata->>'unit', ''),
    nullif(p_metadata->>'unitSnapshot', ''),
    nullif(p_metadata->>'accountingUnit', '')
  );

  v_delta := case when p_direction = 'in' then p_qty else -p_qty end;
  v_value_delta := v_delta * coalesce(p_unit_price, 0);

  insert into public.inventory_balances (
    material_id, warehouse_id, project_id, construction_site_id,
    on_hand_qty, total_value, average_unit_cost,
    last_ledger_entry_id, last_transaction_date, updated_at
  )
  values (
    p_material_id, p_warehouse_id, nullif(p_project_id, ''), nullif(p_construction_site_id, ''),
    v_delta, v_value_delta,
    case when v_delta = 0 then 0 else coalesce(p_unit_price, 0) end,
    v_entry_id, p_transaction_date, now()
  )
  on conflict (material_id, warehouse_id, scope_key)
  do update set
    on_hand_qty = public.inventory_balances.on_hand_qty + excluded.on_hand_qty,
    total_value = public.inventory_balances.total_value + excluded.total_value,
    average_unit_cost = case
      when (public.inventory_balances.on_hand_qty + excluded.on_hand_qty) = 0 then 0
      else (public.inventory_balances.total_value + excluded.total_value)
        / nullif(public.inventory_balances.on_hand_qty + excluded.on_hand_qty, 0)
    end,
    last_ledger_entry_id = excluded.last_ledger_entry_id,
    last_transaction_date = excluded.last_transaction_date,
    updated_at = now()
  returning on_hand_qty, total_value
    into v_balance_after_qty, v_balance_after_value;

  insert into public.inventory_ledger_entries (
    id, inventory_transaction_id, entry_no, document_code,
    transaction_date, transaction_type, movement_direction,
    material_id, warehouse_id, project_id, construction_site_id,
    source_type, source_id, source_code, source_line_id, related_request_id,
    quantity_in, quantity_out, unit, unit_price,
    balance_after_qty, balance_after_value,
    description, metadata, created_by, approved_by
  )
  values (
    v_entry_id, p_inventory_transaction_id, p_entry_no, p_document_code,
    p_transaction_date, p_transaction_type, p_direction,
    p_material_id, p_warehouse_id, nullif(p_project_id, ''), nullif(p_construction_site_id, ''),
    p_source_type, p_source_id, p_source_code, nullif(p_source_line_id, ''), nullif(p_related_request_id, ''),
    case when p_direction = 'in' then p_qty else 0 end,
    case when p_direction = 'out' then p_qty else 0 end,
    v_unit, coalesce(p_unit_price, 0),
    v_balance_after_qty, v_balance_after_value,
    p_description, coalesce(p_metadata, '{}'::jsonb), p_created_by, p_approved_by
  );

  return v_entry_id;
end;
$$;


--
-- Name: post_purchase_receipt_finance_v2(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.post_purchase_receipt_finance_v2(p_delivery_batch_id uuid, p_actor_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_batch public.purchase_order_delivery_batches%rowtype;
  v_po public.purchase_orders%rowtype;
  v_tx public.transactions%rowtype;
  v_project_finance_id text;
  v_received_gross numeric(18,2);
  v_committed_gross numeric(18,2);
  v_source_ref text := 'purchase_receipt:' || p_delivery_batch_id::text;
  v_description text;
  v_existing_cost public.project_transactions%rowtype;
  v_existing_ap public.supplier_payable_documents%rowtype;
begin
  select * into v_batch
  from public.purchase_order_delivery_batches
  where id = p_delivery_batch_id
  for update;
  if not found then
    raise exception 'Khong tim thay Dot giao %.', p_delivery_batch_id using errcode = '22023';
  end if;

  v_received_gross := round(coalesce(v_batch.accepted_gross_amount, 0), 2);
  if v_received_gross <= 0 then
    return;
  end if;

  select * into v_po
  from public.purchase_orders
  where id = v_batch.purchase_order_id
  for update;
  if not found then
    raise exception 'Khong tim thay Goi mua hang cua Dot giao %.', p_delivery_batch_id using errcode = '22023';
  end if;

  select * into v_tx
  from public.transactions
  where id = v_batch.wms_transaction_id
  for update;
  if not found then
    raise exception 'Khong tim thay WMS cua Dot giao %.', p_delivery_batch_id using errcode = '22023';
  end if;
  if v_tx.status <> 'COMPLETED'::public.transaction_status then
    raise exception 'Chi ghi nhan chi phi receipt khi WMS da COMPLETED.' using errcode = '22023';
  end if;

  select round(coalesce(sum(
    coalesce(line.planned_qty, 0)
    * coalesce(line.delivery_unit_price, 0)
    * (1 + coalesce(v_batch.vat_rate, 0) / 100)
  ), 0), 2)
  into v_committed_gross
  from public.purchase_order_delivery_lines line
  where line.delivery_batch_id = p_delivery_batch_id;

  select id into v_project_finance_id
  from public.project_finances
  where (v_po.project_id is not null and project_id = v_po.project_id)
     or (v_po.construction_site_id is not null and construction_site_id = v_po.construction_site_id)
  limit 1;

  v_description := 'Nhận hàng NCC '
    || coalesce(v_batch.supplier_name_snapshot, v_po.vendor_name, v_po.vendor_id, 'Nhà cung cấp')
    || ' - '
    || coalesce(v_po.po_number, v_po.id)
    || ' - đợt '
    || coalesce(v_batch.delivery_no::text, p_delivery_batch_id::text);

  select * into v_existing_cost
  from public.project_transactions
  where source_ref = v_source_ref
  for update;
  if found then
    if round(coalesce(v_existing_cost.amount, 0), 2) <> v_received_gross then
      raise exception 'Anomaly: chi phi receipt da ton tai voi gia tri khac.' using errcode = 'P0001';
    end if;
  else
    insert into public.project_transactions (
      id, "projectFinanceId", "constructionSiteId",
      project_id, project_finance_id, construction_site_id,
      type, category, amount, description, date, source,
      "sourceRef", source_ref, contract_cost_item_id,
      cost_classification_status, counterparty_partner_id,
      counterparty_name, attachments, "createdBy", "createdAt"
    )
    values (
      'purchase-receipt-' || p_delivery_batch_id::text,
      coalesce(v_project_finance_id, ''),
      coalesce(v_po.construction_site_id, ''),
      v_po.project_id,
      nullif(v_project_finance_id, ''),
      v_po.construction_site_id,
      'expense',
      'materials',
      v_received_gross,
      v_description,
      current_date::text,
      'workflow',
      v_source_ref,
      v_source_ref,
      null,
      'auto',
      null,
      coalesce(v_batch.supplier_name_snapshot, v_po.vendor_name, v_po.vendor_id, 'Nhà cung cấp'),
      coalesce(v_tx.attachments, '[]'::jsonb),
      p_actor_user_id::text,
      now()
    )
    on conflict (source_ref) do nothing;
  end if;

  select * into v_existing_ap
  from public.supplier_payable_documents
  where source_type = 'purchase_delivery_receipt'
    and source_id = p_delivery_batch_id::text
  for update;
  if found then
    if round(coalesce(v_existing_ap.recognized_amount, 0), 2) <> v_received_gross
       or round(coalesce(v_existing_ap.committed_amount, 0), 2) <> v_committed_gross then
      raise exception 'Anomaly: AP receipt da ton tai voi gia tri khac.' using errcode = 'P0001';
    end if;
    return;
  end if;

  insert into public.supplier_payable_documents (
    code, source_type, source_id, project_id, construction_site_id,
    supplier_id, supplier_name_snapshot, document_no, document_date, due_date,
    committed_amount, recognized_amount, credit_amount, status, qr_token,
    metadata, created_by
  )
  values (
    'AP-REC-' || replace(p_delivery_batch_id::text, '-', ''),
    'purchase_delivery_receipt',
    p_delivery_batch_id::text,
    v_po.project_id,
    v_po.construction_site_id,
    v_batch.supplier_id,
    coalesce(v_batch.supplier_name_snapshot, v_po.vendor_name, v_po.vendor_id, 'Nhà cung cấp'),
    coalesce(v_po.po_number, v_po.id) || '-' || lpad(coalesce(v_batch.delivery_no, 0)::text, 2, '0'),
    current_date,
    null,
    v_committed_gross,
    v_received_gross,
    0,
    'open',
    'ap_receipt_' || replace(p_delivery_batch_id::text, '-', ''),
    jsonb_build_object(
      'purchaseOrderId', v_po.id,
      'purchaseOrderNo', v_po.po_number,
      'deliveryBatchId', p_delivery_batch_id,
      'wmsTransactionId', v_tx.id,
      'fulfillmentMode', v_batch.fulfillment_mode,
      'sourceRef', v_source_ref
    ),
    p_actor_user_id
  )
  on conflict (source_type, source_id) do nothing;
end;
$$;


--
-- Name: post_purchase_receipt_return_finance_v2(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.post_purchase_receipt_return_finance_v2(p_supplier_return_id uuid, p_actor_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_return public.purchase_order_supplier_returns%rowtype;
  v_po public.purchase_orders%rowtype;
  v_tx public.transactions%rowtype;
  v_has_v2_receipt boolean := false;
  v_existing_cost public.project_transactions%rowtype;
  v_project_finance_id text;
  v_source_ref text := 'purchase_receipt_return:' || p_supplier_return_id::text;
  v_description text;
  v_total_gross numeric(18,2) := 0;
  v_return_line record;
  v_delivery record;
  v_remaining_qty numeric;
  v_take_qty numeric;
  v_line_gross numeric(18,2);
  v_ap public.supplier_payable_documents%rowtype;
  v_credit_key text;
  v_existing_credit jsonb;
begin
  select * into v_return
  from public.purchase_order_supplier_returns
  where id = p_supplier_return_id
  for update;
  if not found then
    raise exception 'Khong tim thay phieu tra NCC %.', p_supplier_return_id using errcode = '22023';
  end if;
  if v_return.status <> 'completed' then
    raise exception 'Chi post finance cho phieu tra NCC da completed.' using errcode = '22023';
  end if;

  select * into v_existing_cost
  from public.project_transactions
  where source_ref = v_source_ref
  for update;
  if found then
    return;
  end if;

  select * into v_tx
  from public.transactions
  where id = v_return.transaction_id
  for update;
  if not found or v_tx.status <> 'COMPLETED'::public.transaction_status then
    raise exception 'Chi post finance tra NCC khi WMS EXPORT da COMPLETED.' using errcode = '22023';
  end if;

  select * into v_po
  from public.purchase_orders
  where id = v_return.purchase_order_id
  for update;
  if not found then
    raise exception 'Khong tim thay PO cua phieu tra NCC %.', p_supplier_return_id using errcode = '22023';
  end if;

  select exists (
    select 1
    from public.purchase_order_delivery_lines line
    join public.purchase_order_delivery_batches batch on batch.id = line.delivery_batch_id
    where line.purchase_order_id = v_return.purchase_order_id
      and batch.status in ('received', 'received_short', 'received_over')
      and coalesce(line.accepted_qty, 0) > 0
  ) into v_has_v2_receipt;

  if not v_has_v2_receipt then
    return;
  end if;

  select id into v_project_finance_id
  from public.project_finances
  where (v_po.project_id is not null and project_id = v_po.project_id)
     or (v_po.construction_site_id is not null and construction_site_id = v_po.construction_site_id)
  limit 1;

  for v_return_line in
    select *
    from public.purchase_order_supplier_return_lines
    where supplier_return_id = p_supplier_return_id
    order by id
  loop
    v_remaining_qty := coalesce(v_return_line.return_qty, 0);
    if v_remaining_qty <= 0 then
      raise exception 'Dong tra NCC khong hop le.' using errcode = '22023';
    end if;

    for v_delivery in
      select
        line.id as delivery_line_id,
        line.delivery_batch_id,
        line.purchase_order_line_id,
        line.accepted_qty,
        line.returned_qty,
        line.delivery_unit_price,
        batch.delivery_no,
        batch.vat_rate,
        batch.received_at,
        batch.updated_at,
        batch.created_at
      from public.purchase_order_delivery_lines line
      join public.purchase_order_delivery_batches batch on batch.id = line.delivery_batch_id
      where line.purchase_order_id = v_return.purchase_order_id
        and line.purchase_order_line_id = v_return_line.purchase_order_line_id
        and batch.status in ('received', 'received_short', 'received_over')
        and coalesce(line.accepted_qty, 0) > coalesce(line.returned_qty, 0)
      order by coalesce(batch.received_at, batch.updated_at, batch.created_at), batch.delivery_no, line.id
      for update of line
    loop
      exit when v_remaining_qty <= 0;

      v_take_qty := least(
        v_remaining_qty,
        greatest(0, coalesce(v_delivery.accepted_qty, 0) - coalesce(v_delivery.returned_qty, 0))
      );
      if v_take_qty <= 0 then
        continue;
      end if;

      update public.purchase_order_delivery_lines
      set returned_qty = round(coalesce(returned_qty, 0) + v_take_qty, 6),
          updated_at = now()
      where id = v_delivery.delivery_line_id;

      v_line_gross := round(
        v_take_qty
        * coalesce(v_delivery.delivery_unit_price, 0)
        * (1 + coalesce(v_delivery.vat_rate, 0) / 100),
        2
      );
      v_total_gross := round(v_total_gross + v_line_gross, 2);

      select * into v_ap
      from public.supplier_payable_documents
      where source_type = 'purchase_delivery_receipt'
        and source_id = v_delivery.delivery_batch_id::text
      for update;
      if not found then
        raise exception 'Anomaly: AP receipt cua Dot giao % chua duoc ghi nhan.', v_delivery.delivery_batch_id
          using errcode = 'P0001';
      end if;
      if v_ap.status in ('cancelled', 'reversed') then
        raise exception 'Anomaly: khong the credit AP receipt da huy/dao.' using errcode = 'P0001';
      end if;

      v_credit_key := p_supplier_return_id::text || ':' || v_delivery.delivery_line_id::text;
      v_existing_credit := coalesce(v_ap.metadata, '{}'::jsonb)
        -> 'purchaseReceiptReturnCredits'
        -> v_credit_key;

      if v_existing_credit is not null then
        if round(coalesce(nullif(v_existing_credit ->> 'amount', '')::numeric, 0), 2) <> v_line_gross then
          raise exception 'Anomaly: AP return credit da ton tai voi gia tri khac.' using errcode = 'P0001';
        end if;
      else
        update public.supplier_payable_documents
        set credit_amount = round(coalesce(credit_amount, 0) + v_line_gross, 2),
            status = case
              when round(coalesce(recognized_amount, 0) - (coalesce(credit_amount, 0) + v_line_gross), 2) <= 0 then 'paid'
              when coalesce(credit_amount, 0) + v_line_gross > 0 then 'partial'
              else status
            end,
            metadata = jsonb_set(
              coalesce(metadata, '{}'::jsonb),
              '{purchaseReceiptReturnCredits}',
              coalesce(metadata -> 'purchaseReceiptReturnCredits', '{}'::jsonb)
                || jsonb_build_object(
                  v_credit_key,
                  jsonb_build_object(
                    'sourceType', 'supplier_return_credit',
                    'sourceId', p_supplier_return_id::text,
                    'sourceRef', v_source_ref,
                    'deliveryBatchId', v_delivery.delivery_batch_id::text,
                    'deliveryLineId', v_delivery.delivery_line_id::text,
                    'purchaseOrderLineId', v_return_line.purchase_order_line_id,
                    'returnQty', v_take_qty,
                    'amount', v_line_gross
                  )
                ),
              true
            ),
            updated_at = now()
        where id = v_ap.id;
      end if;

      v_remaining_qty := v_remaining_qty - v_take_qty;
    end loop;

    if round(v_remaining_qty, 6) > 0 then
      raise exception 'So luong tra cua dong % vuot so luong delivery da accepted con co the tra.',
        v_return_line.purchase_order_line_id using errcode = '22023';
    end if;
  end loop;

  if v_total_gross <= 0 then
    return;
  end if;

  v_description := 'Return to supplier '
    || coalesce(v_return.return_no, p_supplier_return_id::text)
    || ' - '
    || coalesce(v_po.po_number, v_po.id);

  insert into public.project_transactions (
    id, "projectFinanceId", "constructionSiteId",
    project_id, project_finance_id, construction_site_id,
    type, category, amount, description, date, source,
    "sourceRef", source_ref, contract_cost_item_id,
    cost_classification_status, counterparty_partner_id,
    counterparty_name, attachments, "createdBy", "createdAt"
  )
  values (
    'purchase-return-cost-' || p_supplier_return_id::text,
    coalesce(v_project_finance_id, ''),
    coalesce(v_po.construction_site_id, ''),
    v_po.project_id,
    nullif(v_project_finance_id, ''),
    v_po.construction_site_id,
    'expense',
    'materials',
    -v_total_gross,
    v_description,
    current_date::text,
    'workflow',
    v_source_ref,
    v_source_ref,
    null,
    'auto',
    null,
    coalesce(v_po.vendor_name, v_po.vendor_id, 'Nha cung cap'),
    coalesce(v_tx.attachments, '[]'::jsonb),
    coalesce(p_actor_user_id, v_return.completed_by, v_return.created_by)::text,
    now()
  )
  on conflict (source_ref) do nothing;
end;
$$;


--
-- Name: preflight_project_progress_snapshot_impl(text, text, date, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.preflight_project_progress_snapshot_impl(p_project_id text, p_construction_site_id text, p_week_start date, p_snapshot jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := public.current_app_user_id();
  v_site_id text := nullif(btrim(coalesce(p_construction_site_id, '')), '');
  v_scope_key text;
begin
  v_scope_key := app_private.assert_project_progress_scope_period(
    p_project_id, v_site_id, 'weekly', p_week_start
  );
  if v_actor_id is null or not (
    public.is_admin()
    or app_private.current_user_is_global_wms_keeper()
  ) then
    raise exception 'Chỉ System Admin hoặc thủ kho tổng được cập nhật snapshot đầu kỳ.'
      using errcode = '42501';
  end if;
  perform app_private.assert_project_progress_snapshot(p_snapshot);

  if p_snapshot ->> 'progressMode' <> 'opening_balance' then
    raise exception 'Opening Balance snapshot refresh requires progressMode opening_balance'
      using errcode = '23514';
  end if;

  if exists (
    select 1
    from public.project_progress_period_states state
    where state.scope_key = v_scope_key
      and state.period_type = 'weekly'
      and state.period_start = p_week_start
      and state.is_locked
  ) then
    raise exception 'Kỳ tiến độ đã được chốt. Hãy mở chốt trước khi sửa.'
      using errcode = '23514';
  end if;

  return jsonb_build_object(
    'allowed', true,
    'scopeKey', v_scope_key,
    'weekStart', p_week_start
  );
end;
$$;


--
-- Name: prepare_feedback_item_insert(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.prepare_feedback_item_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
begin
  if v_actor is null then
    raise exception 'feedback actor profile not found for current auth session'
      using errcode = '28000';
  end if;

  new.created_by := v_actor;
  new.status := 'new';
  new.priority := 'medium';
  new.assigned_to := null;
  new.rejected_reason := null;
  new.completed_at := null;
  new.closed_by := null;
  new.due_at := null;
  new.target_release := null;
  new.roadmap_stage := null;
  new.tags := '{}'::text[];
  new.device_info := coalesce(new.device_info, '{}'::jsonb);
  new.metadata := coalesce(new.metadata, '{}'::jsonb);

  return new;
end;
$$;


--
-- Name: prepare_feedback_item_update(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.prepare_feedback_item_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  new.updated_at := now();
  new.last_activity_at := now();

  if old.completed_at is not null then
    new.completed_at := old.completed_at;
  elsif old.status is distinct from 'done' and new.status = 'done' then
    new.completed_at := coalesce(new.completed_at, now());
  end if;

  if new.status is distinct from 'rejected' then
    new.rejected_reason := null;
  end if;

  if new.status in ('done', 'rejected') then
    new.closed_by := coalesce(new.closed_by, public.current_app_user_id());
    if new.roadmap_stage is null and new.status = 'done' then
      new.roadmap_stage := 'done';
    end if;
  else
    new.closed_by := null;
  end if;

  return new;
end;
$$;


--
-- Name: prepare_planned_purchase_delivery_batch_with_wms_qr_v2(uuid, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.prepare_planned_purchase_delivery_batch_with_wms_qr_v2(p_delivery_batch_id uuid, p_actor_user_id uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_batch public.purchase_order_delivery_batches%rowtype;
  v_po public.purchase_orders%rowtype;
  v_line public.purchase_order_delivery_lines%rowtype;
  v_qr_token text := 'pod_' || replace(gen_random_uuid()::text, '-', '');
  v_tx_id text := 'tx-po-delivery-' || replace(gen_random_uuid()::text, '-', '');
  v_wms_items jsonb := '[]'::jsonb;
  v_purchase_unit_price numeric;
  v_stock_unit_price numeric;
begin
  if p_actor_user_id is null then
    raise exception 'Nguoi thuc hien lenh khong hop le.' using errcode = '42501';
  end if;
  if public.current_app_user_id() is null or p_actor_user_id <> public.current_app_user_id() then
    raise exception 'Nguoi thuc hien lenh khong hop le.' using errcode = '42501';
  end if;
  if p_idempotency_key is null then
    raise exception 'Idempotency key is required.' using errcode = '22023';
  end if;

  select * into v_batch
  from public.purchase_order_delivery_batches
  where id = p_delivery_batch_id
  for update;
  if not found then
    raise exception 'Khong tim thay Dot giao %.', p_delivery_batch_id using errcode = '22023';
  end if;

  select * into v_po
  from public.purchase_orders
  where id = v_batch.purchase_order_id
  for update;
  if not found then
    raise exception 'Khong tim thay Goi mua hang cua Dot giao %.', p_delivery_batch_id using errcode = '22023';
  end if;
  if coalesce(v_po.source_mode, '') <> 'from_request' then
    raise exception 'Chi chuan bi Dot giao cho Goi mua hang V2 tao tu MR.' using errcode = '22023';
  end if;
  if v_po.status not in ('confirmed', 'in_transit', 'partial') then
    raise exception 'Chi chuan bi Dot giao sau khi Goi da duyet.' using errcode = '22023';
  end if;
  if coalesce(v_batch.status, 'planned') not in ('planned', 'waiting_delivery', 'receiving', 'wms_pending') then
    raise exception 'Trang thai Dot giao khong cho phep tao WMS/QR: %', v_batch.status using errcode = '22023';
  end if;
  if coalesce(v_batch.wms_transaction_id, '') <> '' and coalesce(v_batch.qr_token, '') <> '' then
    return app_private.purchase_delivery_command_result_v2(v_batch.id);
  end if;
  if nullif(trim(coalesce(v_po.target_warehouse_id, '')), '') is null then
    raise exception 'Kho nhan hang la bat buoc de tao WMS/QR Dot giao.' using errcode = '22023';
  end if;

  for v_line in
    select *
    from public.purchase_order_delivery_lines
    where delivery_batch_id = v_batch.id
    order by id
  loop
    if coalesce(v_line.planned_qty, 0) <= 0 or coalesce(v_line.stock_planned_qty, 0) <= 0 then
      raise exception 'So luong Dot giao phai lon hon 0.' using errcode = '22023';
    end if;
    v_purchase_unit_price := coalesce(v_line.delivery_unit_price, 0);
    if v_purchase_unit_price < 0 then
      raise exception 'Don gia Dot giao khong duoc am.' using errcode = '22023';
    end if;
    v_stock_unit_price := case
      when coalesce(v_line.stock_planned_qty, 0) > 0
        then v_purchase_unit_price * coalesce(v_line.planned_qty, 0) / coalesce(v_line.stock_planned_qty, 1)
      else 0
    end;

    v_wms_items := v_wms_items || jsonb_build_array(jsonb_build_object(
      'itemId', v_line.item_id,
      'quantity', v_line.stock_planned_qty,
      'orderedQty', v_line.stock_planned_qty,
      'price', v_stock_unit_price,
      'accountingQty', v_line.planned_qty,
      'accountingUnit', coalesce(v_line.unit, 'DV mua'),
      'accountingPrice', v_purchase_unit_price,
      'purchaseOrderLineId', v_line.purchase_order_line_id,
      'purchaseOrderDeliveryBatchId', v_batch.id,
      'purchaseOrderDeliveryLineId', v_line.id,
      'fulfillmentMode', coalesce(v_batch.fulfillment_mode, v_po.fulfillment_mode)
    ));
  end loop;

  if jsonb_array_length(v_wms_items) = 0 then
    raise exception 'Dot giao phai co it nhat mot dong vat tu.' using errcode = '22023';
  end if;

  insert into public.transactions (
    id, type, date, items, target_warehouse_id, supplier_id,
    requester_id, created_by, approver_id, status, note,
    business_partner_id, business_partner_name_snapshot, source_type, source_id
  ) values (
    v_tx_id, 'IMPORT'::public.transaction_type, now(), v_wms_items, v_po.target_warehouse_id, nullif(coalesce(v_batch.supplier_id, v_po.vendor_id), ''),
    p_actor_user_id, p_actor_user_id, p_actor_user_id, 'PENDING'::public.transaction_status,
    coalesce(v_po.po_number, v_po.id) || '-' || lpad(v_batch.delivery_no::text, 2, '0') || ' dang giao',
    null, nullif(coalesce(v_batch.supplier_name_snapshot, v_po.vendor_name), ''), 'po_delivery_batch', v_batch.id::text
  );

  update public.purchase_order_delivery_batches
  set supplier_id = nullif(coalesce(v_batch.supplier_id, v_po.vendor_id), ''),
      supplier_name_snapshot = nullif(coalesce(v_batch.supplier_name_snapshot, v_po.vendor_name), ''),
      fulfillment_mode = coalesce(v_batch.fulfillment_mode, v_po.fulfillment_mode),
      vat_rate = coalesce(v_batch.vat_rate, v_po.vat_rate, 0),
      qr_token = coalesce(v_batch.qr_token, v_qr_token),
      idempotency_key = coalesce(v_batch.idempotency_key, p_idempotency_key),
      wms_transaction_id = v_tx_id,
      status = 'receiving',
      updated_at = now()
  where id = v_batch.id;

  return app_private.purchase_delivery_command_result_v2(v_batch.id);
end;
$$;


--
-- Name: prepare_project_opening_balance_snapshot_impl(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.prepare_project_opening_balance_snapshot_impl(p_opening_balance_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_balance public.project_opening_balances%rowtype;
  v_site_id text;
  v_scope_key text;
  v_week_start date;
  v_snapshot jsonb;
begin
  if public.current_app_user_id() is null or not (
    public.is_admin()
    or app_private.current_user_is_global_wms_keeper()
  ) then
    raise exception 'Chỉ System Admin hoặc thủ kho tổng được chuẩn bị snapshot đầu kỳ.'
      using errcode = '42501';
  end if;

  select balance.* into v_balance
  from public.project_opening_balances balance
  where balance.id = p_opening_balance_id
  for update;

  if not found or v_balance.status <> 'locked' then
    raise exception 'Không tìm thấy dữ liệu đầu kỳ đã khóa.' using errcode = '23514';
  end if;

  v_site_id := nullif(btrim(coalesce(v_balance.construction_site_id, '')), '');
  v_week_start := date_trunc('week', v_balance.as_of_date)::date;
  v_scope_key := app_private.assert_project_progress_scope_period(
    v_balance.project_id, v_site_id, 'weekly', v_week_start
  );
  if v_balance.scope_key is distinct from v_scope_key then
    raise exception 'Opening Balance scope does not match its canonical project/site scope'
      using errcode = '23514';
  end if;

  v_snapshot := jsonb_build_object(
    'constructionProgressPercent', v_balance.construction_progress_percent,
    'valueProgressPercent', case
      when v_balance.contract_value > 0 then least(
        100::numeric,
        round(v_balance.recognized_value / v_balance.contract_value * 100)
      )
      else 0::numeric
    end,
    'progressMode', 'opening_balance',
    'suppliedValue', case when v_balance.recognized_value > 0 then v_balance.recognized_value else null end,
    'contractTotalValue', case when v_balance.contract_value > 0 then v_balance.contract_value else null end,
    'purchasedValue', v_balance.purchased_value,
    'issuedValue', v_balance.issued_value,
    'recognizedValue', v_balance.recognized_value,
    'ganttPercent', v_balance.construction_progress_percent,
    'calculatedAt', now()
  );
  perform app_private.assert_project_progress_snapshot(v_snapshot);

  update public.project_opening_balances balance
  set progress_snapshot_status = 'pending',
      progress_snapshot_payload = v_snapshot,
      progress_snapshot_refreshed_at = null
  where balance.id = p_opening_balance_id;

  return jsonb_build_object(
    'openingBalanceId', v_balance.id,
    'status', 'pending',
    'canRetry', true,
    'scopeKey', v_scope_key,
    'weekStart', v_week_start,
    'refreshedAt', null
  );
end;
$$;


--
-- Name: preserve_daily_log_summary_approval_route(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.preserve_daily_log_summary_approval_route() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if app_private.daily_log_target_permission(
    new.summary_source_type,
    new.submitted_to_permission
  ) = 'project.daily_log.approve' then
    new.submitted_to_permission := 'approve';
  end if;
  return new;
end;
$$;


--
-- Name: prevent_project_workflow_instance_delete(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.prevent_project_workflow_instance_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if exists (
    select 1 from public.workflow_subjects ws where ws.workflow_instance_id = old.id
  ) then
    raise exception 'project-linked workflow instances cannot be deleted';
  end if;
  return old;
end;
$$;


--
-- Name: prevent_used_workflow_template_delete(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.prevent_used_workflow_template_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if exists (select 1 from public.project_workflow_bindings b where b.workflow_template_id = old.id)
     or exists (select 1 from public.workflow_template_versions v where v.template_id = old.id)
     or exists (select 1 from public.workflow_instances i where i.template_id = old.id) then
    raise exception 'workflow template has bindings/versions/instances and must be deactivated instead of deleted';
  end if;
  return old;
end;
$$;


--
-- Name: prevent_users_privilege_self_update(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.prevent_users_privilege_self_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  current_user_id uuid;
begin
  if session_user = 'supabase_auth_admin' then
    return new;
  end if;

  if auth.role() = 'service_role'
    and coalesce(current_setting('app.account_lifecycle_command', true), '') = 'on'
  then
    return new;
  end if;

  if public.is_admin() then
    return new;
  end if;

  current_user_id := public.current_app_user_id();

  if coalesce(current_setting('app.authorization_permission_command', true), '') = 'on'
    and current_user_id is not null
    and app_private.has_permission(
      current_user_id,
      'system.authorization.manage_grants',
      'global',
      '*'
    )
  then
    return new;
  end if;

  if current_user_id is null
    or old.id is distinct from current_user_id
    or new.id is distinct from current_user_id
  then
    raise exception 'Only admins can update other user rows'
      using errcode = '42501';
  end if;

  if old.role is distinct from new.role
    or old.auth_id is distinct from new.auth_id
    or old.email is distinct from new.email
    or old.username is distinct from new.username
    or old.assigned_warehouse_id is distinct from new.assigned_warehouse_id
    or old.allowed_modules is distinct from new.allowed_modules
    or old.admin_modules is distinct from new.admin_modules
    or old.allowed_sub_modules is distinct from new.allowed_sub_modules
    or old.admin_sub_modules is distinct from new.admin_sub_modules
    or old.is_active is distinct from new.is_active
  then
    raise exception 'Self profile updates cannot change protected permission fields'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


