--
-- Name: preview_request_template_resolvers(jsonb, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.preview_request_template_resolvers(p_payload jsonb, p_sample_creator_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_block jsonb;
  v_source text;
  v_ids uuid[];
  v_resolved uuid;
  v_result jsonb := '[]'::jsonb;
begin
  if v_actor is null or not app_private.request_user_can_manage(v_actor) then
    raise exception using errcode = '42501', message = 'REQUEST_TEMPLATE_FORBIDDEN';
  end if;
  for v_block in select value from jsonb_array_elements(coalesce(p_payload -> 'blocks', '[]'::jsonb))
  loop
    v_source := v_block ->> 'source';
    select coalesce(array_agg(value::uuid), '{}'::uuid[]) into v_ids
    from jsonb_array_elements_text(coalesce(v_block -> 'fixedUserIds', '[]'::jsonb));
    if v_source = 'DIRECT_MANAGER' then
      v_resolved := app_private.resolve_request_direct_manager(p_sample_creator_id);
      v_ids := case when v_resolved is null then '{}'::uuid[] else array[v_resolved] end;
    end if;
    v_result := v_result || jsonb_build_array(jsonb_build_object(
      'blockKey', v_block ->> 'key',
      'source', v_source,
      'resolvedUserIds', to_jsonb(v_ids),
      'errorCode', case
        when cardinality(v_ids) = 0 and v_source = 'DIRECT_MANAGER'
          then 'REQUEST_DIRECT_MANAGER_MISSING'
        when exists (
          select 1 from unnest(v_ids) resolved_id
          left join public.users app_user on app_user.id = resolved_id
          where app_user.id is null
             or not coalesce(app_user.is_active, true)
             or coalesce(app_user.account_status, 'ACTIVE') <> 'ACTIVE'
        ) then 'REQUEST_APPROVER_INACTIVE'
        else null
      end
    ));
  end loop;
  return jsonb_build_object('sampleCreatorId', p_sample_creator_id, 'blocks', v_result);
end;
$$;


--
-- Name: preview_user_hr_business_role_impl(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.preview_user_hr_business_role_impl(p_target_user_id uuid, p_target_role_code text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := app_private.assert_hrm_role_admin();
  v_target_role_code text := upper(btrim(coalesce(p_target_role_code, '')));
  v_current_role_code text;
  v_target_template_id uuid;
  v_decision jsonb := jsonb_build_object('hardDenies', '[]'::jsonb, 'warnings', '[]'::jsonb);
  v_added jsonb := '[]'::jsonb;
  v_removed jsonb := '[]'::jsonb;
begin
  if v_target_role_code not in ('NONE', 'HR', 'HR_MANAGE') then
    raise exception 'Target HR role must be NONE, HR or HR_MANAGE'
      using errcode = '22023';
  end if;

  if not exists (
    select 1 from public.users target_row
    where target_row.id = p_target_user_id
      and target_row.is_active
      and target_row.account_status = 'ACTIVE'
  ) then
    raise exception 'Active target user required'
      using errcode = '23514';
  end if;

  if p_expires_at is not null and p_expires_at <= now() then
    raise exception 'HR role expiry must be in the future'
      using errcode = '22023';
  end if;

  select template.code into v_current_role_code
  from public.principal_role_assignments assignment_row
  join public.role_permission_templates template
    on template.id = assignment_row.role_template_id
   and template.code in ('HR', 'HR_MANAGE')
  where assignment_row.principal_type = 'user'
    and assignment_row.principal_id = p_target_user_id
    and assignment_row.status = 'ACTIVE'
    and assignment_row.starts_at <= now()
    and (assignment_row.expires_at is null or assignment_row.expires_at > now())
  order by case template.code when 'HR_MANAGE' then 0 else 1 end
  limit 1;

  if v_actor_user_id = p_target_user_id and v_target_role_code = 'HR' then
    raise exception 'System Admin may self-assign only HR_MANAGE'
      using errcode = '42501';
  end if;

  if v_target_role_code <> 'NONE' then
    select template.id into v_target_template_id
    from public.role_permission_templates template
    where template.code = v_target_role_code
      and template.is_system
      and template.is_active;

    if v_target_template_id is null then
      raise exception 'Target HR role template is unavailable'
        using errcode = '23514';
    end if;
  end if;

  select coalesce(jsonb_agg(desired.permission_code order by desired.permission_code), '[]'::jsonb)
  into v_added
  from (
    select desired_item.permission_code
    from public.role_permission_template_items desired_item
    where desired_item.template_id = v_target_template_id
    except
    select current_item.permission_code
    from public.principal_role_assignments assignment_row
    join public.role_permission_templates current_template
      on current_template.id = assignment_row.role_template_id
     and current_template.code in ('HR', 'HR_MANAGE')
    join public.role_permission_template_items current_item
      on current_item.template_id = current_template.id
    where assignment_row.principal_type = 'user'
      and assignment_row.principal_id = p_target_user_id
      and assignment_row.status = 'ACTIVE'
      and assignment_row.starts_at <= now()
      and (assignment_row.expires_at is null or assignment_row.expires_at > now())
  ) desired;

  select coalesce(jsonb_agg(current_permission.permission_code order by current_permission.permission_code), '[]'::jsonb)
  into v_removed
  from (
    select current_item.permission_code
    from public.principal_role_assignments assignment_row
    join public.role_permission_templates current_template
      on current_template.id = assignment_row.role_template_id
     and current_template.code in ('HR', 'HR_MANAGE')
    join public.role_permission_template_items current_item
      on current_item.template_id = current_template.id
    where assignment_row.principal_type = 'user'
      and assignment_row.principal_id = p_target_user_id
      and assignment_row.status = 'ACTIVE'
      and assignment_row.starts_at <= now()
      and (assignment_row.expires_at is null or assignment_row.expires_at > now())
    except
    select desired_item.permission_code
    from public.role_permission_template_items desired_item
    where desired_item.template_id = v_target_template_id
  ) current_permission;

  if v_target_role_code <> 'NONE' and v_target_role_code is distinct from v_current_role_code then
    if v_actor_user_id = p_target_user_id and v_target_role_code = 'HR_MANAGE' then
      v_decision := jsonb_build_object(
        'hardDenies', '[]'::jsonb,
        'warnings', jsonb_build_array(jsonb_build_object(
          'ruleCode', 'HRM_ADMIN_SELF_GRANT',
          'message', 'System Admin đang tự mở toàn bộ dữ liệu HR nhạy cảm.',
          'scopeType', 'global',
          'scopeId', '*'
        ))
      );
    else
      v_decision := app_private.evaluate_business_role_assignment_impl(
        v_actor_user_id,
        p_target_user_id,
        v_target_template_id,
        'global',
        '*'
      );
    end if;
  end if;

  return jsonb_build_object(
    'targetRoleCode', v_target_role_code,
    'currentRoleCode', v_current_role_code,
    'fingerprint', app_private.hrm_authorization_fingerprint(p_target_user_id),
    'added', v_added,
    'removed', v_removed,
    'warnings', coalesce(v_decision -> 'warnings', '[]'::jsonb),
    'hardDenies', coalesce(v_decision -> 'hardDenies', '[]'::jsonb),
    'opensC3', v_target_role_code in ('HR', 'HR_MANAGE'),
    'opensC4', v_target_role_code in ('HR', 'HR_MANAGE'),
    'allowsC4Mutation', v_target_role_code = 'HR_MANAGE',
    'allowsSensitiveExport', v_target_role_code = 'HR_MANAGE',
    'expiresAt', p_expires_at
  );
end;
$$;


--
-- Name: preview_user_permission_change_impl(uuid, jsonb, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.preview_user_permission_change_impl(p_user_id uuid, p_legacy_state jsonb, p_grants jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid;
  v_target public.users%rowtype;
  v_legacy_before jsonb;
  v_legacy_after jsonb;
  v_direct_before jsonb;
  v_direct_after jsonb;
  v_decision jsonb;
  v_before_fingerprint text;
begin
  v_actor_user_id := app_private.assert_authorization_permission(
    'system.authorization.manage_grants'
  );

  select *
  into v_target
  from public.users
  where id = p_user_id;

  if v_target.id is null
    or not v_target.is_active
    or v_target.account_status <> 'ACTIVE'
    or v_target.role = 'ADMIN'::public.user_role
  then
    raise exception 'Active non-Admin target user required'
      using errcode = '23514';
  end if;

  v_legacy_before := app_private.normalize_legacy_permission_state(
    jsonb_build_object(
      'allowedModules', to_jsonb(v_target.allowed_modules),
      'allowedSubModules', v_target.allowed_sub_modules,
      'adminModules', to_jsonb(v_target.admin_modules),
      'adminSubModules', v_target.admin_sub_modules
    )
  );
  v_legacy_after := case
    when p_legacy_state is null then v_legacy_before
    else app_private.normalize_legacy_permission_state(p_legacy_state)
  end;

  if not app_private.legacy_admin_state_is_subset(v_legacy_before, v_legacy_after) then
    raise exception 'Unified editor cannot add Legacy administration umbrellas'
      using errcode = '42501';
  end if;

  if v_actor_user_id = p_user_id
    and v_legacy_before is distinct from v_legacy_after
  then
    raise exception 'Self-directed Legacy permission change is not allowed'
      using errcode = '42501';
  end if;

  v_decision := app_private.evaluate_direct_grant_replacement_impl(
    v_actor_user_id,
    p_user_id,
    p_grants
  );
  perform app_private.assert_unified_direct_grant_readiness(p_user_id, p_grants);

  v_direct_before := app_private.direct_permission_state_for_user(p_user_id);
  v_direct_after := app_private.normalize_direct_permission_state(p_grants);
  v_before_fingerprint := app_private.permission_state_fingerprint_for_values(
    v_legacy_before,
    v_direct_before
  );

  return jsonb_build_object(
    'beforeFingerprint', v_before_fingerprint,
    'decision', v_decision,
    'legacyBefore', v_legacy_before,
    'legacyAfter', v_legacy_after,
    'directBefore', v_direct_before,
    'directAfter', v_direct_after
  );
end;
$$;


--
-- Name: preview_vehicle_booking_submission_route_impl(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.preview_vehicle_booking_submission_route_impl(p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_requires_manager boolean := true;
  v_manager_user_id uuid;
  v_dispatcher_count integer := 0;
begin
  if p_actor_user_id is null
     or p_actor_user_id is distinct from public.current_app_user_id() then
    raise exception using errcode = '42501', message = 'VEHICLE_ACTOR_MISMATCH';
  end if;

  select coalesce(settings.require_direct_manager_approval, true)
  into v_requires_manager
  from public.fleet_system_settings settings
  where settings.id = 1;

  if not coalesce(v_requires_manager, true) then
    v_dispatcher_count := app_private.vehicle_active_dispatcher_count();
    if v_dispatcher_count = 0 then
      raise exception using errcode = '22023', message = 'VEHICLE_DISPATCHER_MISSING';
    end if;
    return jsonb_build_object(
      'route', 'CONFIG_DISABLED',
      'manager_user_id', null,
      'dispatcher_count', v_dispatcher_count
    );
  end if;

  v_manager_user_id := app_private.resolve_active_direct_manager(p_actor_user_id);
  if v_manager_user_id is not null then
    return jsonb_build_object(
      'route', 'MANAGER',
      'manager_user_id', v_manager_user_id,
      'dispatcher_count', app_private.vehicle_active_dispatcher_count()
    );
  end if;

  v_dispatcher_count := app_private.vehicle_active_dispatcher_count();
  if v_dispatcher_count = 0 then
    raise exception using errcode = '22023', message = 'VEHICLE_DISPATCHER_MISSING';
  end if;
  return jsonb_build_object(
    'route', 'MISSING_MANAGER_CONFIRMATION_REQUIRED',
    'manager_user_id', null,
    'dispatcher_count', v_dispatcher_count
  );
end;
$$;


--
-- Name: process_feedback_auto_close(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.process_feedback_auto_close() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_count integer;
begin
  with closed as (
    update public.vehicle_booking_feedback feedback
    set status = 'AUTO_CLOSED', submitted_at = now(), updated_at = now()
    from public.fleet_system_settings settings,
         public.vehicle_bookings booking
    where settings.id = 1
      and booking.id = feedback.booking_id
      and feedback.status = 'PENDING'
      and feedback.created_at <= now() - make_interval(hours => settings.feedback_auto_close_hours)
    returning feedback.booking_id, booking.requester_user_id, booking.booking_code
  ), enqueued as (
    insert into app_private.vehicle_booking_notification_outbox(
      event_key, event_type, recipient_user_id, payload
    )
    select
      'vehicle:' || closed.booking_id::text || ':FEEDBACK_AUTO_CLOSED:' || closed.requester_user_id::text,
      'FEEDBACK_AUTO_CLOSED',
      closed.requester_user_id,
      jsonb_build_object(
        'booking_id', closed.booking_id,
        'booking_code', closed.booking_code,
        'event_type', 'FEEDBACK_AUTO_CLOSED'
      )
    from closed
    on conflict (event_key, recipient_user_id) do nothing
    returning 1
  )
  select count(*) into v_count from closed;
  return v_count;
end;
$$;


--
-- Name: process_vehicle_notification_outbox(integer); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.process_vehicle_notification_outbox(p_limit integer DEFAULT 50) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_outbox record;
  v_processed integer := 0;
begin
  update app_private.vehicle_booking_notification_outbox outbox
  set status = 'FAILED', locked_at = null,
      last_error = 'Stale PROCESSING lease recovered', available_at = now(), updated_at = now()
  where outbox.status = 'PROCESSING'
    and outbox.locked_at < now() - interval '15 minutes'
    and outbox.attempt_count < 10;

  for v_outbox in
    select outbox.*
    from app_private.vehicle_booking_notification_outbox outbox
    where outbox.status in ('PENDING', 'FAILED')
      and outbox.attempt_count < 10
      and outbox.available_at <= now()
    order by outbox.available_at, outbox.id
    limit least(greatest(coalesce(p_limit, 50), 1), 100)
    for update skip locked
  loop
    begin
      update app_private.vehicle_booking_notification_outbox
      set status = 'PROCESSING', locked_at = now(),
          attempt_count = attempt_count + 1, updated_at = now()
      where id = v_outbox.id;

      perform app_private.insert_vehicle_booking_notification(v_outbox.id);

      update app_private.vehicle_booking_notification_outbox
      set status = 'DELIVERED', delivered_at = now(), locked_at = null,
          last_error = null, updated_at = now()
      where id = v_outbox.id;
      v_processed := v_processed + 1;
    exception when others then
      update app_private.vehicle_booking_notification_outbox
      set status = 'FAILED', locked_at = null, last_error = left(sqlerrm, 500),
          available_at = now() + interval '5 minutes', updated_at = now()
      where id = v_outbox.id;
    end;
  end loop;

  return v_processed;
end;
$$;


--
-- Name: project_actor_has_effective_room_action(uuid, text, text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_actor_has_effective_room_action(p_user_id uuid, p_project_id text, p_construction_site_id text, p_room_code text, p_action_code text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with binding as (
    select item.enforcement_status, item.legacy_permission_codes,
      item.pbac_fallback_enabled, item.prerequisite_action_codes
    from app_private.project_permission_room_action_bindings item
    where item.room_code = p_room_code
      and item.action_code = p_action_code
  ), actor as (
    select user_row.id, user_row.role
    from public.users user_row
    where user_row.id = p_user_id
      and coalesce(user_row.is_active, true)
  ), scoped_actor as (
    select actor.id, actor.role
    from actor
    where actor.role = 'ADMIN'
      or exists (
        select 1
        from public.project_staff staff
        where staff.user_id = actor.id::text
          and staff.project_id = p_project_id
          and staff.end_date is null
          and (
            nullif(p_construction_site_id, '') is null
            or staff.construction_site_id is null
            or staff.construction_site_id = p_construction_site_id
          )
      )
  )
  select exists (
    select 1
    from binding
    cross join scoped_actor
    where scoped_actor.role = 'ADMIN'
      or (
        binding.enforcement_status in ('pilot', 'enforced')
        and app_private.project_user_has_room_action(
          scoped_actor.id,
          p_project_id,
          nullif(p_construction_site_id, ''),
          p_room_code,
          p_action_code
        )
        and not exists (
          select 1
          from unnest(binding.prerequisite_action_codes) required(action_code)
          where not app_private.project_user_has_room_action(
            scoped_actor.id,
            p_project_id,
            nullif(p_construction_site_id, ''),
            p_room_code,
            required.action_code
          )
        )
      )
      or (
        binding.pbac_fallback_enabled
        and app_private.permission_hardening_flag('project_room_pbac_fallback_enabled')
        and exists (
          select 1
          from unnest(binding.legacy_permission_codes) legacy(permission_code)
          where app_private.project_has_permission_v2(
            p_project_id,
            nullif(p_construction_site_id, ''),
            legacy.permission_code,
            scoped_actor.id
          )
        )
      )
  );
$$;


