-- Name: project_has_any_permission_v2(text, text, text[], uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_has_any_permission_v2(p_project_id text, p_construction_site_id text, p_permission_codes text[], p_user_id uuid DEFAULT public.current_app_user_id()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
