--
-- Name: project_po_can_archive_v1(text, text, text, text, boolean, jsonb, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_po_can_archive_v1(p_po_id text, p_project_id text, p_construction_site_id text, p_status text, p_ever_submitted boolean, p_received_transaction_ids jsonb, p_items jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_status text := lower(coalesce(p_status, 'draft'));
  v_has_permission boolean := false;
  v_received_item_qty numeric := 0;
  v_has_received_batch_qty boolean := false;
  v_no_receipt boolean := false;
  v_stock_cleanup_ok boolean := false;
  v_direct_supplier_return_cleanup_ok boolean := false;
begin
  v_has_permission := public.is_admin()
    or exists (
      select 1
      from public.purchase_orders po
      where po.id = p_po_id
        and nullif(po.created_by_id, '') = public.current_app_user_id()::text
    );

  if not v_has_permission then
    return false;
  end if;

  select coalesce(sum(coalesce(nullif(elem->>'receivedQty', '')::numeric, 0)), 0)
    into v_received_item_qty
  from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) as elem;

  if to_regclass('public.material_request_fulfillment_lines') is not null then
    select coalesce(bool_or(coalesce(received_qty, 0) > 0), false)
      into v_has_received_batch_qty
    from public.material_request_fulfillment_lines
    where po_id = p_po_id;
  end if;

  v_no_receipt := v_received_item_qty <= 0
    and jsonb_array_length(coalesce(p_received_transaction_ids, '[]'::jsonb)) = 0
    and not v_has_received_batch_qty;

  if v_status in ('returned', 'cancelled', 'partial', 'delivered', 'closed') then
    v_stock_cleanup_ok := app_private.project_po_stock_cleanup_ok(p_po_id, p_received_transaction_ids);
    v_direct_supplier_return_cleanup_ok := app_private.project_po_direct_supplier_return_cleanup_ok(p_po_id, p_received_transaction_ids);
  end if;

  return
    (v_status = 'draft' and not coalesce(p_ever_submitted, false) and v_no_receipt)
    or (
      v_status in ('returned', 'cancelled')
      and (v_no_receipt or v_stock_cleanup_ok or v_direct_supplier_return_cleanup_ok)
    )
    or (
      v_status in ('partial', 'delivered', 'closed')
      and (v_stock_cleanup_ok or v_direct_supplier_return_cleanup_ok)
    );
end;
$$;


--
-- Name: project_po_can_delete(text, text, text, boolean, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_po_can_delete(p_project_id text, p_construction_site_id text, p_status text, p_ever_submitted boolean, p_received_transaction_ids jsonb) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select (
      (
        coalesce(p_status, 'draft') = 'draft'
        and not coalesce(p_ever_submitted, false)
      )
      or (
        coalesce(p_status, 'draft') = 'cancelled'
        and jsonb_array_length(coalesce(p_received_transaction_ids, '[]'::jsonb)) = 0
      )
      or coalesce(p_status, 'draft') = 'returned'
    )
    and (
      public.is_admin()
      or app_private.project_user_has_permission(p_project_id, p_construction_site_id, 'delete')
    );
$$;


--
-- Name: project_po_can_delete_v2(text, text, text, text, boolean, jsonb, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_po_can_delete_v2(p_po_id text, p_project_id text, p_construction_site_id text, p_status text, p_ever_submitted boolean, p_received_transaction_ids jsonb, p_items jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_status text := lower(coalesce(p_status, 'draft'));
  v_has_permission boolean := false;
  v_has_received_batch_qty boolean := false;
  v_received_item_qty numeric := 0;
  v_no_receipt boolean := false;
  v_stock_cleanup_ok boolean := false;
begin
  v_has_permission := public.is_admin()
    or app_private.project_user_has_permission(p_project_id, p_construction_site_id, 'delete');

  if not v_has_permission then
    return false;
  end if;

  if v_status = 'draft' and not coalesce(p_ever_submitted, false) then
    return true;
  end if;

  select coalesce(sum(coalesce(nullif(elem->>'receivedQty', '')::numeric, 0)), 0)
    into v_received_item_qty
  from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) as elem;

  if to_regclass('public.material_request_fulfillment_lines') is not null then
    select coalesce(bool_or(coalesce(received_qty, 0) > 0), false)
      into v_has_received_batch_qty
    from public.material_request_fulfillment_lines
    where po_id = p_po_id;
  end if;

  v_no_receipt := v_received_item_qty <= 0
    and jsonb_array_length(coalesce(p_received_transaction_ids, '[]'::jsonb)) = 0
    and not v_has_received_batch_qty;

  if v_status in ('returned', 'cancelled', 'partial', 'delivered', 'closed') then
    v_stock_cleanup_ok := app_private.project_po_stock_cleanup_ok(
      p_po_id,
      p_received_transaction_ids
    );
  end if;

  return (
    v_status in ('returned', 'cancelled')
    and (v_no_receipt or v_stock_cleanup_ok)
  )
  or (
    v_status in ('partial', 'delivered', 'closed')
    and v_has_received_batch_qty
    and v_stock_cleanup_ok
  );
end;
$$;


--
-- Name: project_po_can_update(text, text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_po_can_update(p_project_id text, p_construction_site_id text, p_status text, p_submitted_to_user_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.is_admin()
    or (
      coalesce(p_status, 'draft') = 'draft'
      and (
        app_private.project_user_has_permission(p_project_id, p_construction_site_id, 'edit')
        or app_private.project_user_has_permission(p_project_id, p_construction_site_id, 'submit')
      )
    )
    or (
      coalesce(p_status, 'draft') in ('sent', 'confirmed', 'in_transit', 'partial', 'delivered', 'closed', 'returned', 'cancelled')
      and (
        app_private.project_doc_is_current_handler(p_submitted_to_user_id)
        or app_private.project_user_has_permission(p_project_id, p_construction_site_id, 'approve')
        or app_private.project_user_has_permission(p_project_id, p_construction_site_id, 'confirm')
        or app_private.project_user_has_permission(p_project_id, p_construction_site_id, 'edit')
      )
    );
$$;


--
-- Name: project_po_delivery_batch_refresh_status_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_po_delivery_batch_refresh_status_v1(p_delivery_batch_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_has_rows boolean := false;
  v_has_open boolean := false;
  v_has_received boolean := false;
  v_all_rejected boolean := false;
  v_next_status text;
begin
  if p_delivery_batch_id is null
     or to_regclass('public.purchase_order_delivery_batches') is null
     or to_regclass('public.material_request_fulfillment_batches') is null
     or to_regclass('public.material_request_fulfillment_lines') is null then
    return;
  end if;

  select
    count(*) > 0,
    coalesce(bool_or(lower(coalesce(batch.status::text, '')) in ('issued', 'variance_pending')), false),
    coalesce(bool_or(lower(coalesce(batch.status::text, '')) = 'received' or coalesce(line_totals.received_qty, 0) > 0), false),
    count(*) > 0
      and coalesce(bool_and(lower(coalesce(batch.status::text, '')) in ('returned', 'cancelled')), false)
      and not coalesce(bool_or(coalesce(line_totals.received_qty, 0) > 0), false)
  into v_has_rows, v_has_open, v_has_received, v_all_rejected
  from public.material_request_fulfillment_batches batch
  left join lateral (
    select coalesce(sum(coalesce(line.received_qty, 0)), 0) as received_qty
    from public.material_request_fulfillment_lines line
    where line.batch_id = batch.id
  ) line_totals on true
  where batch.po_delivery_batch_id = p_delivery_batch_id;

  if not v_has_rows then
    return;
  end if;

  v_next_status := case
    when v_all_rejected then 'cancelled'
    when v_has_open then 'wms_pending'
    when v_has_received then 'received'
    else 'wms_pending'
  end;

  update public.purchase_order_delivery_batches
  set status = v_next_status
  where id = p_delivery_batch_id
    and status is distinct from v_next_status;
end;
$$;


--
-- Name: project_po_delivery_group_refresh_status_v1(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_po_delivery_group_refresh_status_v1(p_delivery_group_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_has_rows boolean := false;
  v_has_open boolean := false;
  v_has_received boolean := false;
  v_all_rejected boolean := false;
  v_next_status text;
begin
  if p_delivery_group_id is null
     or to_regclass('public.purchase_order_delivery_groups') is null
     or to_regclass('public.material_request_fulfillment_batches') is null
     or to_regclass('public.material_request_fulfillment_lines') is null then
    return;
  end if;

  select
    count(*) > 0,
    coalesce(bool_or(lower(coalesce(batch.status::text, '')) in ('issued', 'variance_pending')), false),
    coalesce(bool_or(lower(coalesce(batch.status::text, '')) = 'received' or coalesce(line_totals.received_qty, 0) > 0), false),
    count(*) > 0
      and coalesce(bool_and(lower(coalesce(batch.status::text, '')) in ('returned', 'cancelled')), false)
      and not coalesce(bool_or(coalesce(line_totals.received_qty, 0) > 0), false)
  into v_has_rows, v_has_open, v_has_received, v_all_rejected
  from public.material_request_fulfillment_batches batch
  left join lateral (
    select coalesce(sum(coalesce(line.received_qty, 0)), 0) as received_qty
    from public.material_request_fulfillment_lines line
    where line.batch_id = batch.id
  ) line_totals on true
  where batch.po_delivery_group_id = p_delivery_group_id;

  if not v_has_rows then
    return;
  end if;

  v_next_status := case
    when v_all_rejected then 'cancelled'
    when v_has_open then 'issued'
    when v_has_received then 'received'
    else 'issued'
  end;

  update public.purchase_order_delivery_groups
  set status = v_next_status
  where id = p_delivery_group_id
    and status is distinct from v_next_status;
end;
$$;


--
-- Name: project_po_direct_supplier_return_cleanup_ok(text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_po_direct_supplier_return_cleanup_ok(p_po_id text, p_received_transaction_ids jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_receipt_transaction_ids text[] := array[]::text[];
  v_has_received_qty boolean := false;
  v_has_unfinished_receipts boolean := false;
  v_has_active_supplier_returns boolean := false;
  v_has_unfinished_return_transactions boolean := false;
  v_has_insufficient_return_qty boolean := true;
begin
  if to_regclass('public.purchase_order_supplier_returns') is null
    or to_regclass('public.transactions') is null
  then
    return false;
  end if;

  select coalesce(array_agg(distinct tx_id), array[]::text[])
    into v_receipt_transaction_ids
  from (
    select jsonb_array_elements_text(coalesce(p_received_transaction_ids, '[]'::jsonb)) as tx_id
  ) tx
  where nullif(tx_id, '') is not null;

  if coalesce(array_length(v_receipt_transaction_ids, 1), 0) = 0 then
    return false;
  end if;

  select coalesce(bool_or(upper(coalesce(t.status::text, '')) not in ('COMPLETED', 'CANCELLED')), false)
    into v_has_unfinished_receipts
  from public.transactions t
  where t.id::text = any(v_receipt_transaction_ids);

  if v_has_unfinished_receipts then
    return false;
  end if;

  select exists (
    select 1
    from public.transactions t
    cross join lateral jsonb_array_elements(coalesce(t.items, '[]'::jsonb)) elem
    where t.id::text = any(v_receipt_transaction_ids)
      and upper(coalesce(t.status::text, '')) = 'COMPLETED'
      and nullif(elem->>'itemId', '') is not null
      and coalesce(nullif(elem->>'quantity', '')::numeric, 0) > 0
  )
    into v_has_received_qty;

  if not v_has_received_qty then
    return false;
  end if;

  select exists (
    select 1
    from public.purchase_order_supplier_returns r
    where r.purchase_order_id = p_po_id
      and lower(coalesce(r.status, '')) not in ('completed', 'cancelled')
  )
    into v_has_active_supplier_returns;

  if v_has_active_supplier_returns then
    return false;
  end if;

  select exists (
    select 1
    from public.purchase_order_supplier_returns r
    left join public.transactions t on t.id::text = r.transaction_id::text
    where r.purchase_order_id = p_po_id
      and lower(coalesce(r.status, '')) = 'completed'
      and (t.id is null or upper(coalesce(t.status::text, '')) <> 'COMPLETED')
  )
    into v_has_unfinished_return_transactions;

  if v_has_unfinished_return_transactions then
    return false;
  end if;

  select exists (
    with received as (
      select
        elem->>'itemId' as item_id,
        sum(coalesce(nullif(elem->>'quantity', '')::numeric, 0))::numeric as qty
      from public.transactions t
      cross join lateral jsonb_array_elements(coalesce(t.items, '[]'::jsonb)) elem
      where t.id::text = any(v_receipt_transaction_ids)
        and upper(coalesce(t.status::text, '')) = 'COMPLETED'
        and nullif(elem->>'itemId', '') is not null
      group by elem->>'itemId'
    ),
    returned as (
      select
        elem->>'itemId' as item_id,
        sum(coalesce(nullif(elem->>'quantity', '')::numeric, 0))::numeric as qty
      from public.purchase_order_supplier_returns r
      join public.transactions t on t.id::text = r.transaction_id::text
      cross join lateral jsonb_array_elements(coalesce(t.items, '[]'::jsonb)) elem
      where r.purchase_order_id = p_po_id
        and lower(coalesce(r.status, '')) = 'completed'
        and upper(coalesce(t.status::text, '')) = 'COMPLETED'
        and nullif(elem->>'itemId', '') is not null
      group by elem->>'itemId'
    )
    select 1
    from received r
    left join returned ret on ret.item_id = r.item_id
    where coalesce(ret.qty, 0) + 0.000000001 < r.qty
    limit 1
  )
    into v_has_insufficient_return_qty;

  return not v_has_insufficient_return_qty;
end;
$$;


--
-- Name: project_po_has_failed_delivery_work_v1(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_po_has_failed_delivery_work_v1(p_po_id text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_has_failed boolean := false;
begin
  if to_regclass('public.material_request_fulfillment_batches') is not null
     and to_regclass('public.material_request_fulfillment_lines') is not null then
    select exists (
      select 1
      from public.material_request_fulfillment_lines line
      join public.material_request_fulfillment_batches batch on batch.id = line.batch_id
      left join public.transactions tx on tx.id::text = batch.transaction_id::text
      where line.po_id = p_po_id
        and coalesce(line.received_qty, 0) <= 0
        and (
          lower(coalesce(batch.status::text, '')) in ('returned', 'cancelled')
          or (
            lower(coalesce(batch.status::text, '')) in ('issued', 'variance_pending')
            and tx.status = 'CANCELLED'::public.transaction_status
          )
        )
    )
      into v_has_failed;

    if v_has_failed then
      return true;
    end if;
  end if;

  if to_regclass('public.purchase_order_delivery_batches') is not null then
    select exists (
      select 1
      from public.purchase_order_delivery_batches batch
      where batch.purchase_order_id = p_po_id
        and lower(coalesce(batch.status::text, '')) = 'cancelled'
    )
      into v_has_failed;

    if v_has_failed then
      return true;
    end if;
  end if;

  if to_regclass('public.purchase_order_delivery_groups') is not null then
    select exists (
      select 1
      from public.purchase_order_delivery_groups delivery_group
      where delivery_group.purchase_order_id = p_po_id
        and lower(coalesce(delivery_group.status::text, '')) = 'cancelled'
    )
      into v_has_failed;
  end if;

  return coalesce(v_has_failed, false);
end;
$$;


--
-- Name: project_po_has_pending_work_v1(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_po_has_pending_work_v1(p_po_id text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_has_pending boolean := false;
begin
  if to_regclass('public.material_request_fulfillment_batches') is not null
     and to_regclass('public.material_request_fulfillment_lines') is not null then
    select exists (
      select 1
      from public.material_request_fulfillment_lines line
      join public.material_request_fulfillment_batches batch on batch.id = line.batch_id
      left join public.transactions tx on tx.id::text = batch.transaction_id::text
      where line.po_id = p_po_id
        and lower(coalesce(batch.status::text, '')) in ('issued', 'variance_pending')
        and coalesce(tx.status, 'PENDING'::public.transaction_status) <> 'CANCELLED'::public.transaction_status
    )
      into v_has_pending;

    if v_has_pending then
      return true;
    end if;
  end if;

  if to_regclass('public.purchase_order_delivery_batches') is not null then
    select exists (
      select 1
      from public.purchase_order_delivery_batches batch
      where batch.purchase_order_id = p_po_id
        and lower(coalesce(batch.status::text, '')) = 'wms_pending'
    )
      into v_has_pending;

    if v_has_pending then
      return true;
    end if;
  end if;

  if app_private.project_po_has_failed_delivery_work_v1(p_po_id) then
    return true;
  end if;

  if to_regclass('public.purchase_order_supplier_returns') is not null then
    select exists (
      select 1
      from public.purchase_order_supplier_returns r
      where r.purchase_order_id = p_po_id
        and lower(coalesce(r.status::text, '')) not in ('completed', 'cancelled')
    )
      into v_has_pending;
  end if;

  return coalesce(v_has_pending, false);
end;
$$;


--
-- Name: project_po_has_stock_impact_v1(text, jsonb, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_po_has_stock_impact_v1(p_po_id text, p_received_transaction_ids jsonb, p_items jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_received_transaction_ids text[] := array[]::text[];
  v_has_stock_impact boolean := false;
begin
  select coalesce(array_agg(distinct tx_id), array[]::text[])
    into v_received_transaction_ids
  from (
    select jsonb_array_elements_text(
      case
        when jsonb_typeof(coalesce(p_received_transaction_ids, '[]'::jsonb)) = 'array'
          then coalesce(p_received_transaction_ids, '[]'::jsonb)
        else '[]'::jsonb
      end
    ) as tx_id
  ) tx
  where nullif(tx_id, '') is not null;

  select exists (
    select 1
    from jsonb_array_elements(
      case
        when jsonb_typeof(coalesce(p_items, '[]'::jsonb)) = 'array'
          then coalesce(p_items, '[]'::jsonb)
        else '[]'::jsonb
      end
    ) item(value)
    where coalesce(nullif(item.value->>'receivedQty', '')::numeric, 0) > 0
  )
    into v_has_stock_impact;

  if v_has_stock_impact then
    return true;
  end if;

  if to_regclass('public.material_request_fulfillment_lines') is not null then
    select exists (
      select 1
      from public.material_request_fulfillment_lines line
      where line.po_id = p_po_id
        and coalesce(line.received_qty, 0) > 0
    )
      into v_has_stock_impact;

    if v_has_stock_impact then
      return true;
    end if;
  end if;

  if coalesce(array_length(v_received_transaction_ids, 1), 0) > 0 then
    select exists (
      select 1
      from public.transactions t
      where t.id::text = any(v_received_transaction_ids)
        and upper(coalesce(t.status::text, '')) = 'COMPLETED'
        and exists (
          select 1
          from jsonb_array_elements(coalesce(t.items, '[]'::jsonb)) tx_item(value)
          where coalesce(nullif(tx_item.value->>'quantity', '')::numeric, 0) <> 0
        )
    )
      into v_has_stock_impact;

    if v_has_stock_impact then
      return true;
    end if;

    if to_regclass('public.inventory_ledger_entries') is not null then
      select exists (
        select 1
        from public.inventory_ledger_entries entry
        where entry.source_type = 'wms_transaction'
          and entry.source_id = any(v_received_transaction_ids)
      )
      into v_has_stock_impact;

      if v_has_stock_impact then
        return true;
      end if;
    end if;
  end if;

  if to_regclass('public.material_request_fulfillment_batches') is not null
     and to_regclass('public.material_request_fulfillment_lines') is not null then
    select exists (
      select 1
      from public.material_request_fulfillment_lines line
      join public.material_request_fulfillment_batches batch
        on batch.id = line.batch_id
      left join public.transactions t
        on t.id::text = batch.transaction_id::text
      where line.po_id = p_po_id
        and batch.transaction_id is not null
        and (
          upper(coalesce(t.status::text, '')) = 'COMPLETED'
          or (
            to_regclass('public.inventory_ledger_entries') is not null
            and exists (
              select 1
              from public.inventory_ledger_entries entry
              where entry.source_type = 'wms_transaction'
                and entry.source_id = batch.transaction_id::text
            )
          )
        )
    )
      into v_has_stock_impact;

    if v_has_stock_impact then
      return true;
    end if;
  end if;

  if to_regclass('public.purchase_order_supplier_returns') is not null then
    select exists (
      select 1
      from public.purchase_order_supplier_returns r
      left join public.transactions t
        on t.id::text = r.transaction_id::text
      where r.purchase_order_id = p_po_id
        and (
          lower(coalesce(r.status, '')) = 'completed'
          or upper(coalesce(t.status::text, '')) = 'COMPLETED'
          or (
            to_regclass('public.inventory_ledger_entries') is not null
            and exists (
              select 1
              from public.inventory_ledger_entries entry
              where entry.source_type = 'wms_transaction'
                and entry.source_id = r.transaction_id::text
            )
          )
        )
    )
      into v_has_stock_impact;

    if v_has_stock_impact then
      return true;
    end if;
  end if;

  return false;
end;
$$;


--
-- Name: project_po_refresh_request_status_v1(text[]); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_po_refresh_request_status_v1(p_request_ids text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request_id text;
  v_total_committed numeric := 0;
  v_total_active_issued numeric := 0;
  v_total_received numeric := 0;
  v_total_closed numeric := 0;
  v_open_need numeric := 0;
  v_next_status public.request_status;
  v_next_step text;
begin
  if p_request_ids is null or array_length(p_request_ids, 1) is null then
    return;
  end if;

  foreach v_request_id in array p_request_ids loop
    select coalesce(sum(
      coalesce(
        nullif(item.value ->> 'approvedQty', '')::numeric,
        nullif(item.value ->> 'requestQty', '')::numeric,
        0
      )
    ), 0)
    into v_total_committed
    from public.requests request
    cross join lateral jsonb_array_elements(coalesce(request.items, '[]'::jsonb)) item(value)
    where request.id = v_request_id;

    select
      coalesce(sum(case
        when lower(coalesce(batch.status::text, '')) not in ('draft', 'cancelled', 'returned')
          then coalesce(line.issued_qty, 0)
        else 0
      end), 0),
      coalesce(sum(case
        when lower(coalesce(batch.status::text, '')) = 'received'
          then coalesce(line.received_qty, 0)
        else 0
      end), 0)
    into v_total_active_issued, v_total_received
    from public.material_request_fulfillment_lines line
    join public.material_request_fulfillment_batches batch on batch.id = line.batch_id
    where line.material_request_id = v_request_id;

    v_total_closed := 0;
    if to_regclass('public.material_request_line_need_closures') is not null then
      select coalesce(sum(coalesce(closure.closed_qty, 0)), 0)
      into v_total_closed
      from public.material_request_line_need_closures closure
      where closure.material_request_id = v_request_id
        and lower(coalesce(closure.status::text, 'active')) = 'active';
    end if;

    v_open_need := greatest(0, v_total_committed - v_total_received - v_total_closed);
    v_next_status := case
      when v_total_committed > 0 and v_open_need <= 0 then 'COMPLETED'::public.request_status
      when v_total_active_issued > 0 or v_total_received > 0 then 'IN_TRANSIT'::public.request_status
      else 'APPROVED'::public.request_status
    end;
    v_next_step := case
      when v_next_status = 'COMPLETED'::public.request_status then 'completed'
      when v_next_status = 'IN_TRANSIT'::public.request_status then 'site_quality_check'
      else 'batch_planning'
    end;

    update public.requests
    set status = v_next_status,
        workflow_step = v_next_step,
        workflow_step_started_at = now(),
        submission_note = concat_ws(
          ' | ',
          nullif(submission_note, ''),
          'Đồng bộ lại sau khi phiếu nhập PO bị từ chối trước nhập kho.'
        )
    where id = v_request_id
      and status not in (
        'DRAFT'::public.request_status,
        'PENDING'::public.request_status,
        'REJECTED'::public.request_status
      )
      and (
        status is distinct from v_next_status
        or workflow_step is distinct from v_next_step
      );
  end loop;
end;
$$;


--
-- Name: project_po_status_marks_submitted(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_po_status_marks_submitted(p_status text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select lower(coalesce(p_status, 'draft')) in (
    'sent',
    'confirmed',
    'in_transit',
    'partial',
    'delivered',
    'closed',
    'returned'
  );
$$;


--
-- Name: project_po_stock_cleanup_ok(text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_po_stock_cleanup_ok(p_po_id text, p_received_transaction_ids jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_has_received_batch_qty boolean := false;
  v_has_active_batches boolean := false;
  v_has_returned_batch boolean := false;
  v_has_unfinished_transactions boolean := false;
  v_missing_return_transaction boolean := false;
  v_has_insufficient_return_qty boolean := false;
  v_return_transaction_ids text[] := array[]::text[];
  v_receipt_transaction_ids text[] := array[]::text[];
  v_all_transaction_ids text[] := array[]::text[];
begin
  if to_regclass('public.material_request_fulfillment_lines') is null then
    return false;
  end if;

  select coalesce(bool_or(coalesce(received_qty, 0) > 0), false)
    into v_has_received_batch_qty
  from public.material_request_fulfillment_lines
  where po_id = p_po_id;

  if not v_has_received_batch_qty then
    return false;
  end if;

  if to_regclass('public.material_request_fulfillment_batches') is null then
    return false;
  end if;

  select
    coalesce(bool_or(lower(coalesce(b.status::text, '')) not in ('returned', 'cancelled')), false),
    coalesce(bool_or(lower(coalesce(b.status::text, '')) = 'returned'), false)
    into v_has_active_batches, v_has_returned_batch
  from public.material_request_fulfillment_batches b
  where b.id in (
    select distinct batch_id
    from public.material_request_fulfillment_lines
    where po_id = p_po_id
      and batch_id is not null
  );

  select coalesce(array_agg(distinct m.match[1]), array[]::text[])
    into v_return_transaction_ids
  from public.material_request_fulfillment_batches b
  cross join lateral regexp_matches(coalesce(b.note, ''), '(tx-[a-z0-9-]+)', 'gi') as m(match)
  where b.id in (
    select distinct batch_id
    from public.material_request_fulfillment_lines
    where po_id = p_po_id
      and batch_id is not null
  );

  select coalesce(array_agg(distinct tx_id), array[]::text[])
    into v_receipt_transaction_ids
  from (
    select jsonb_array_elements_text(coalesce(p_received_transaction_ids, '[]'::jsonb)) as tx_id
    union
    select b.transaction_id::text as tx_id
    from public.material_request_fulfillment_batches b
    where b.id in (
      select distinct batch_id
      from public.material_request_fulfillment_lines
      where po_id = p_po_id
        and batch_id is not null
    )
  ) tx
  where nullif(tx_id, '') is not null;

  select coalesce(array_agg(distinct tx_id), array[]::text[])
    into v_all_transaction_ids
  from (
    select unnest(v_return_transaction_ids) as tx_id
    union
    select unnest(v_receipt_transaction_ids) as tx_id
  ) tx
  where nullif(tx_id, '') is not null;

  if coalesce(array_length(v_all_transaction_ids, 1), 0) > 0 then
    select coalesce(bool_or(upper(coalesce(t.status::text, '')) not in ('COMPLETED', 'CANCELLED')), false)
      into v_has_unfinished_transactions
    from public.transactions t
    where t.id::text = any(v_all_transaction_ids);
  end if;

  if v_has_received_batch_qty and v_has_returned_batch then
    if coalesce(array_length(v_return_transaction_ids, 1), 0) = 0 then
      v_missing_return_transaction := true;
    else
      select exists (
        select 1
        from unnest(v_return_transaction_ids) as r(tx_id)
        left join public.transactions t
          on t.id::text = r.tx_id
         and upper(coalesce(t.status::text, '')) = 'COMPLETED'
        where t.id is null
      )
        into v_missing_return_transaction;
    end if;
  end if;

  if coalesce(array_length(v_return_transaction_ids, 1), 0) > 0 then
    select exists (
      with received as (
        select item_id::text as item_id, sum(coalesce(received_qty, 0))::numeric as qty
        from public.material_request_fulfillment_lines
        where po_id = p_po_id
          and item_id is not null
          and coalesce(received_qty, 0) > 0
        group by item_id::text
      ),
      returned as (
        select
          elem->>'itemId' as item_id,
          sum(coalesce(nullif(elem->>'quantity', '')::numeric, 0))::numeric as qty
        from public.transactions t
        cross join lateral jsonb_array_elements(coalesce(t.items, '[]'::jsonb)) as elem
        where t.id::text = any(v_return_transaction_ids)
          and upper(coalesce(t.status::text, '')) = 'COMPLETED'
          and nullif(elem->>'itemId', '') is not null
        group by elem->>'itemId'
      )
      select 1
      from received r
      left join returned ret on ret.item_id = r.item_id
      where coalesce(ret.qty, 0) + 0.000000001 < r.qty
      limit 1
    )
      into v_has_insufficient_return_qty;
  else
    v_has_insufficient_return_qty := true;
  end if;

  return not v_has_active_batches
    and not v_has_unfinished_transactions
    and not v_missing_return_transaction
    and not v_has_insufficient_return_qty;
end;
$$;


--
-- Name: project_po_sync_cancelled_receipt_transaction_trigger_v1(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_po_sync_cancelled_receipt_transaction_trigger_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'UPDATE'
     and new.status = 'CANCELLED'::public.transaction_status
     and old.status is distinct from new.status then
    perform app_private.project_po_sync_cancelled_receipt_transaction_v1(
      new.id::text,
      'Phiếu kho nhập PO đã bị từ chối trước khi nhập kho.'
    );
  end if;

  return new;
end;
$$;


--
-- Name: project_po_sync_cancelled_receipt_transaction_v1(text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_po_sync_cancelled_receipt_transaction_v1(p_transaction_id text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tx public.transactions%rowtype;
  v_reason text := coalesce(nullif(trim(p_reason), ''), 'Phiếu kho nhập PO đã bị từ chối trước khi nhập kho.');
  v_batch_ids uuid[] := array[]::uuid[];
  v_delivery_batch_ids uuid[] := array[]::uuid[];
  v_delivery_group_ids uuid[] := array[]::uuid[];
  v_id uuid;
begin
  if p_transaction_id is null
     or to_regclass('public.material_request_fulfillment_batches') is null
     or to_regclass('public.material_request_fulfillment_lines') is null then
    return jsonb_build_object('synced', false, 'reason', 'missing_input_or_tables');
  end if;

  select *
    into v_tx
  from public.transactions
  where id = p_transaction_id
  for update;

  if not found then
    return jsonb_build_object('synced', false, 'reason', 'transaction_not_found');
  end if;

  if v_tx.status <> 'CANCELLED'::public.transaction_status then
    return jsonb_build_object('synced', false, 'reason', 'transaction_not_cancelled');
  end if;

  if to_regclass('public.inventory_ledger_entries') is not null
     and exists (
       select 1
       from public.inventory_ledger_entries entry
       where entry.source_type = 'wms_transaction'
         and entry.source_id = v_tx.id::text
     ) then
    return jsonb_build_object('synced', false, 'reason', 'stock_ledger_exists');
  end if;

  select coalesce(array_agg(distinct batch.id), array[]::uuid[])
    into v_batch_ids
  from public.material_request_fulfillment_batches batch
  where (
      batch.transaction_id::text = v_tx.id::text
      or (
        v_tx.source_type = 'po_delivery_batch'
        and batch.po_delivery_batch_id::text = v_tx.source_id
      )
    )
    and lower(coalesce(batch.source_type::text, '')) = 'po_receipt'
    and lower(coalesce(batch.status::text, '')) in ('issued', 'variance_pending')
    and not exists (
      select 1
      from public.material_request_fulfillment_lines line
      where line.batch_id = batch.id
        and coalesce(line.received_qty, 0) > 0
    );

  if coalesce(array_length(v_batch_ids, 1), 0) = 0 then
    return jsonb_build_object('synced', false, 'reason', 'no_receipt_batches_to_return');
  end if;

  update public.material_request_fulfillment_batches batch
  set status = 'returned',
      cancel_reason = coalesce(nullif(batch.cancel_reason, ''), v_reason),
      reason = coalesce(nullif(batch.reason, ''), v_reason)
  where batch.id = any(v_batch_ids);

  select coalesce(array_agg(distinct batch.po_delivery_batch_id) filter (where batch.po_delivery_batch_id is not null), array[]::uuid[]),
         coalesce(array_agg(distinct batch.po_delivery_group_id) filter (where batch.po_delivery_group_id is not null), array[]::uuid[])
    into v_delivery_batch_ids, v_delivery_group_ids
  from public.material_request_fulfillment_batches batch
  where batch.id = any(v_batch_ids);

  foreach v_id in array v_delivery_batch_ids loop
    perform app_private.project_po_delivery_batch_refresh_status_v1(v_id);
  end loop;

  foreach v_id in array v_delivery_group_ids loop
    perform app_private.project_po_delivery_group_refresh_status_v1(v_id);
  end loop;

  return jsonb_build_object(
    'synced', true,
    'transactionId', v_tx.id,
    'returnedBatchCount', coalesce(array_length(v_batch_ids, 1), 0)
  );
end;
$$;


--
-- Name: project_po_update_delivery_group_impl_v1(uuid, timestamp with time zone, text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_po_update_delivery_group_impl_v1(p_delivery_group_id uuid, p_planned_date timestamp with time zone, p_note text, p_lines jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_delivery public.purchase_order_delivery_groups%rowtype;
  v_po public.purchase_orders%rowtype;
  v_line_row public.material_request_fulfillment_lines%rowtype;
  v_batch_row public.material_request_fulfillment_batches%rowtype;
  v_payload jsonb;
  v_payload_count integer := 0;
  v_line_count integer := 0;
  v_issued_qty numeric;
  v_unit_price numeric;
begin
  if p_planned_date is null then
    raise exception 'Ngày giao dự kiến không được để trống.';
  end if;

  if jsonb_typeof(coalesce(p_lines, '[]'::jsonb)) <> 'array' then
    raise exception 'Danh sách vật tư của đợt giao không hợp lệ.';
  end if;

  select *
    into v_delivery
  from public.purchase_order_delivery_groups delivery_group
  where delivery_group.id = p_delivery_group_id
  for update;

  if not found then
    raise exception 'Không tìm thấy đợt giao cần sửa.';
  end if;

  select *
    into v_po
  from public.purchase_orders purchase_order
  where purchase_order.id = v_delivery.purchase_order_id
  for update;

  if not found then
    raise exception 'Không tìm thấy PO của đợt giao.';
  end if;

  if not (
    public.is_admin()
    or nullif(v_po.created_by_id, '') = public.current_app_user_id()::text
  ) then
    raise exception 'Chỉ Admin hoặc người tạo PO được sửa đợt giao này.'
      using errcode = '42501';
  end if;

  if lower(coalesce(v_delivery.status, '')) not in ('draft', 'issued') then
    raise exception 'Chỉ sửa được đợt giao chưa nhập kho và chưa bị huỷ/từ chối.';
  end if;

  perform 1
  from public.material_request_fulfillment_batches batch
  where batch.po_delivery_group_id = p_delivery_group_id
  for update;

  perform 1
  from public.transactions transaction_row
  where transaction_row.id::text in (
    select batch.transaction_id::text
    from public.material_request_fulfillment_batches batch
    where batch.po_delivery_group_id = p_delivery_group_id
      and batch.transaction_id is not null
  )
  for update;

  if exists (
    select 1
    from public.material_request_fulfillment_batches batch
    where batch.po_delivery_group_id = p_delivery_group_id
      and lower(coalesce(batch.status::text, '')) not in ('draft', 'issued')
  ) then
    raise exception 'Đợt giao đã được kho xử lý hoặc đã bị từ chối, không thể sửa.';
  end if;

  if exists (
    select 1
    from public.material_request_fulfillment_batches batch
    join public.transactions transaction_row
      on transaction_row.id::text = batch.transaction_id::text
    where batch.po_delivery_group_id = p_delivery_group_id
      and transaction_row.status <> 'PENDING'::public.transaction_status
  ) then
    raise exception 'Phiếu kho của đợt giao đã được xử lý, không thể sửa.';
  end if;

  if exists (
    select 1
    from public.material_request_fulfillment_lines line
    join public.material_request_fulfillment_batches batch on batch.id = line.batch_id
    where batch.po_delivery_group_id = p_delivery_group_id
      and coalesce(line.received_qty, 0) > 0
  ) then
    raise exception 'Đợt giao đã phát sinh thực nhận, không thể sửa.';
  end if;

  if to_regclass('public.inventory_ledger_entries') is not null
     and exists (
       select 1
       from public.inventory_ledger_entries entry
       where entry.source_type = 'wms_transaction'
         and entry.source_id in (
           select batch.transaction_id::text
           from public.material_request_fulfillment_batches batch
           where batch.po_delivery_group_id = p_delivery_group_id
             and batch.transaction_id is not null
         )
     ) then
    raise exception 'Đợt giao đã phát sinh ledger kho, không thể sửa.';
  end if;

  select count(*)
    into v_line_count
  from public.material_request_fulfillment_lines line
  join public.material_request_fulfillment_batches batch on batch.id = line.batch_id
  where batch.po_delivery_group_id = p_delivery_group_id;

  select count(*)
    into v_payload_count
  from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb));

  if v_payload_count <> v_line_count then
    raise exception 'Không được thêm hoặc xoá dòng vật tư khi sửa đợt giao.';
  end if;

  if (
    select count(distinct value ->> 'id')
    from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) payload(value)
  ) <> v_payload_count then
    raise exception 'Danh sách vật tư có dòng bị trùng.';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) payload(value)
    left join public.material_request_fulfillment_lines line
      on line.id::text = payload.value ->> 'id'
    left join public.material_request_fulfillment_batches batch
      on batch.id = line.batch_id
     and batch.po_delivery_group_id = p_delivery_group_id
    where line.id is null or batch.id is null
  ) then
    raise exception 'Có dòng vật tư không thuộc đợt giao này.';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) payload(value)
    where coalesce(payload.value ->> 'issuedQty', '') !~ '^\s*[0-9]+([.][0-9]+)?\s*$'
       or coalesce(payload.value ->> 'deliveryUnitPrice', '') !~ '^\s*[0-9]+([.][0-9]+)?\s*$'
       or (payload.value ->> 'issuedQty')::numeric <= 0
       or (payload.value ->> 'deliveryUnitPrice')::numeric < 0
  ) then
    raise exception 'Số lượng phải lớn hơn 0 và đơn giá không được âm.';
  end if;

  update public.purchase_order_delivery_groups delivery_group
  set planned_date = p_planned_date,
      note = nullif(trim(coalesce(p_note, '')), '')
  where delivery_group.id = p_delivery_group_id;

  for v_payload in
    select value
    from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) payload(value)
  loop
    v_issued_qty := (v_payload ->> 'issuedQty')::numeric;
    v_unit_price := (v_payload ->> 'deliveryUnitPrice')::numeric;

    select line.*
      into v_line_row
    from public.material_request_fulfillment_lines line
    join public.material_request_fulfillment_batches batch on batch.id = line.batch_id
    where line.id::text = v_payload ->> 'id'
      and batch.po_delivery_group_id = p_delivery_group_id
    for update of line;

    select *
      into v_batch_row
    from public.material_request_fulfillment_batches batch
    where batch.id = v_line_row.batch_id;

    if v_batch_row.transaction_id is not null and not exists (
      select 1
      from public.transactions transaction_row,
           jsonb_array_elements(coalesce(transaction_row.items, '[]'::jsonb)) transaction_item(value)
      where transaction_row.id::text = v_batch_row.transaction_id::text
        and coalesce(transaction_item.value ->> 'fulfillmentBatchId', transaction_item.value ->> 'fulfillment_batch_id', '') = v_batch_row.id::text
        and coalesce(transaction_item.value ->> 'requestLineId', transaction_item.value ->> 'request_line_id', '') = v_line_row.request_line_id
        and coalesce(transaction_item.value ->> 'itemId', transaction_item.value ->> 'item_id', '') = v_line_row.item_id
    ) then
      raise exception 'Không đồng bộ được dòng vật tư với phiếu kho liên quan.';
    end if;

    update public.material_request_fulfillment_lines line
    set issued_qty = v_issued_qty,
        committed_qty_snapshot = greatest(coalesce(line.committed_qty_snapshot, 0), v_issued_qty),
        delivery_unit_price = v_unit_price
    where line.id = v_line_row.id;

    if v_batch_row.transaction_id is not null then
      update public.transactions transaction_row
      set items = (
        select coalesce(
          jsonb_agg(
            app_private.project_po_update_transaction_delivery_item_v1(
              transaction_item.value,
              v_batch_row.id,
              v_line_row.request_line_id,
              v_line_row.item_id,
              v_issued_qty,
              v_unit_price
            )
            order by transaction_item.ordinality
          ),
          '[]'::jsonb
        )
        from jsonb_array_elements(coalesce(transaction_row.items, '[]'::jsonb))
          with ordinality as transaction_item(value, ordinality)
      )
      where transaction_row.id::text = v_batch_row.transaction_id::text;
    end if;
  end loop;

  return jsonb_build_object(
    'id', v_delivery.id,
    'purchaseOrderId', v_delivery.purchase_order_id,
    'deliveryNo', v_delivery.delivery_no,
    'lineCount', v_line_count,
    'updatedAt', now()
  );
end;
$_$;


--
-- Name: project_po_update_transaction_delivery_item_v1(jsonb, uuid, text, text, numeric, numeric); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_po_update_transaction_delivery_item_v1(p_item jsonb, p_batch_id uuid, p_request_line_id text, p_item_id text, p_issued_qty numeric, p_unit_price numeric) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_result jsonb := p_item;
  v_old_qty numeric := coalesce(nullif(p_item ->> 'quantity', '')::numeric, 0);
  v_old_accounting_qty numeric := coalesce(nullif(p_item ->> 'accountingQty', '')::numeric, 0);
  v_factor numeric := 1;
begin
  if coalesce(p_item ->> 'fulfillmentBatchId', p_item ->> 'fulfillment_batch_id', '') <> p_batch_id::text
     or coalesce(p_item ->> 'requestLineId', p_item ->> 'request_line_id', '') <> p_request_line_id
     or coalesce(p_item ->> 'itemId', p_item ->> 'item_id', '') <> p_item_id then
    return p_item;
  end if;

  if v_old_qty > 0 and v_old_accounting_qty > 0 then
    v_factor := v_old_qty / v_old_accounting_qty;
  end if;

  v_result := jsonb_set(v_result, '{quantity}', to_jsonb(p_issued_qty), true);
  v_result := jsonb_set(v_result, '{price}', to_jsonb(p_unit_price), true);

  if p_item ? 'accountingQty' then
    v_result := jsonb_set(
      v_result,
      '{accountingQty}',
      to_jsonb(round(p_issued_qty / nullif(v_factor, 0), 6)),
      true
    );
  end if;

  if p_item ? 'accountingPrice' then
    v_result := jsonb_set(
      v_result,
      '{accountingPrice}',
      to_jsonb(round(p_unit_price * v_factor, 6)),
      true
    );
  end if;

  return v_result;
end;
$$;


--
-- Name: project_progress_period_states; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.project_progress_period_states (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    scope_key text NOT NULL,
    project_id text NOT NULL,
    construction_site_id text,
    period_type text NOT NULL,
    period_start date NOT NULL,
    is_locked boolean DEFAULT false NOT NULL,
    locked_by uuid,
    locked_at timestamp with time zone,
    unlocked_by uuid,
    unlocked_at timestamp with time zone,
    unlock_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT project_progress_period_states_period_type_check CHECK ((period_type = ANY (ARRAY['daily'::text, 'weekly'::text]))),
    CONSTRAINT project_progress_period_states_scope_key_check CHECK ((((construction_site_id IS NULL) OR (NULLIF(btrim(construction_site_id), ''::text) IS NOT NULL)) AND (scope_key = (project_id ||
CASE
    WHEN (construction_site_id IS NULL) THEN ''::text
    ELSE ('_'::text || construction_site_id)
END)))),
    CONSTRAINT project_progress_period_states_transition_check CHECK (((is_locked AND (locked_by IS NOT NULL) AND (locked_at IS NOT NULL) AND (unlocked_by IS NULL) AND (unlocked_at IS NULL) AND (unlock_reason IS NULL)) OR ((NOT is_locked) AND (locked_by IS NULL) AND (locked_at IS NULL) AND (unlocked_by IS NULL) AND (unlocked_at IS NULL) AND (unlock_reason IS NULL)) OR ((NOT is_locked) AND (locked_by IS NOT NULL) AND (locked_at IS NOT NULL) AND (unlocked_by IS NOT NULL) AND (unlocked_at IS NOT NULL) AND (NULLIF(btrim(unlock_reason), ''::text) IS NOT NULL)))),
    CONSTRAINT project_progress_period_states_week_start_check CHECK (((period_type <> 'weekly'::text) OR (EXTRACT(isodow FROM period_start) = (1)::numeric)))
);


--
-- Name: project_progress_period_state_json(public.project_progress_period_states); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_progress_period_state_json(p_state public.project_progress_period_states) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'id', p_state.id,
    'scopeKey', p_state.scope_key,
    'projectId', p_state.project_id,
    'constructionSiteId', p_state.construction_site_id,
    'periodType', p_state.period_type,
    'periodStart', p_state.period_start,
    'isLocked', p_state.is_locked,
    'lockedBy', p_state.locked_by,
    'lockedAt', p_state.locked_at,
    'unlockedBy', p_state.unlocked_by,
    'unlockedAt', p_state.unlocked_at,
    'unlockReason', p_state.unlock_reason,
    'createdAt', p_state.created_at,
    'updatedAt', p_state.updated_at
  );
$$;


--
-- Name: project_progress_scope_key(text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_progress_scope_key(p_project_id text, p_construction_site_id text) RETURNS text
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select nullif(btrim(p_project_id), '') || case
    when nullif(btrim(coalesce(p_construction_site_id, '')), '') is null then ''
    else '_' || btrim(p_construction_site_id)
  end;
$$;


--
-- Name: project_request_can_write(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_request_can_write(p_project_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_project_id is not null
    and (
      public.is_admin()
      or app_private.project_user_has_permission(p_project_id, null, 'submit')
      or app_private.project_user_has_permission(p_project_id, null, 'edit')
    );
$$;


--
-- Name: project_room_action_from_material_permission(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_room_action_from_material_permission(p_permission_code text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_permission_code in ('project.material_request.submit', 'project.material_po.create') then 'submit'
    when p_permission_code in ('project.material_request.confirm_fulfillment', 'project.material_po.receive') then 'confirm'
    else 'approve'
  end;
$$;


--
-- Name: project_scope_has_any_grant_v2(text, text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_scope_has_any_grant_v2(p_project_id text, p_construction_site_id text, p_user_id uuid DEFAULT public.current_app_user_id()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.users u
    where u.id = p_user_id
      and coalesce(u.is_active, true)
      and u.role = 'ADMIN'
  )
  or exists (
    select 1
    from public.user_permission_grants g
    join public.users u on u.id = g.user_id
    where g.user_id = p_user_id
      and coalesce(u.is_active, true)
      and g.permission_code like 'project.%'
      and coalesce(g.is_active, false)
      and (g.expires_at is null or g.expires_at > now())
      and (
        g.scope_type = 'global'
        or (g.scope_type = 'project' and (g.scope_id = '*' or g.scope_id = p_project_id))
        or (
          p_construction_site_id is not null
          and g.scope_type = 'construction_site'
          and (g.scope_id = '*' or g.scope_id = p_construction_site_id)
        )
      )
  );
$$;


--
-- Name: project_staff_scope_id(text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_staff_scope_id(p_project_id text, p_construction_site_id text) RETURNS text
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(nullif(p_construction_site_id, ''), nullif(p_project_id, ''));
$$;


--
-- Name: project_staff_scope_type(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_staff_scope_type(p_construction_site_id text) RETURNS text
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case when nullif(p_construction_site_id, '') is not null then 'construction_site' else 'project' end;
$$;


--
-- Name: project_user_has_any_permission(text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_user_has_any_permission(p_project_id text, p_construction_site_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.is_admin()
    or exists (
      select 1
      from public.project_staff ps
      join public.project_staff_permissions psp
        on psp.staff_id = ps.id
       and coalesce(psp.is_active, true)
      join public.project_permission_types ppt
        on ppt.id = psp.permission_type_id
       and coalesce(ppt.is_active, true)
      where ps.user_id::text = public.current_app_user_id()::text
        and ps.end_date is null
        and (
          (p_project_id is not null and ps.project_id::text = p_project_id)
          or (p_construction_site_id is not null and ps.construction_site_id::text = p_construction_site_id)
        )
    );
$$;


--
-- Name: project_user_has_permission(text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_user_has_permission(p_project_id text, p_construction_site_id text, p_permission_code text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.is_admin()
    or exists (
      select 1
      from public.project_staff ps
      join public.project_staff_permissions psp
        on psp.staff_id = ps.id
       and coalesce(psp.is_active, true)
      join public.project_permission_types ppt
        on ppt.id = psp.permission_type_id
       and ppt.code = p_permission_code
       and coalesce(ppt.is_active, true)
      where ps.user_id::text = public.current_app_user_id()::text
        and ps.end_date is null
        and (
          (p_project_id is not null and ps.project_id::text = p_project_id)
          or (p_construction_site_id is not null and ps.construction_site_id::text = p_construction_site_id)
        )
    );
$$;


--
-- Name: project_user_has_permission(text, text, text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_user_has_permission(p_project_id text, p_construction_site_id text, p_permission_code text, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    exists (
      select 1
      from public.project_staff ps
      join public.project_staff_permissions psp
        on psp.staff_id = ps.id
       and coalesce(psp.is_active, true)
      join public.project_permission_types ppt
        on ppt.id = psp.permission_type_id
       and ppt.code = p_permission_code
       and coalesce(ppt.is_active, true)
      where ps.user_id::text = p_user_id::text
        and ps.end_date is null
        and (
          (p_project_id is not null and ps.project_id::text = p_project_id)
          or (p_construction_site_id is not null and ps.construction_site_id::text = p_construction_site_id)
        )
    ),
    false
  );
$$;


--
-- Name: project_user_has_room_action(uuid, text, text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_user_has_room_action(p_user_id uuid, p_project_id text, p_construction_site_id text, p_room_code text, p_action_code text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.users u
    join public.project_staff staff on staff.user_id = u.id::text
    join public.project_permission_room_members member on member.project_staff_id = staff.id
    join public.project_permission_room_member_actions action on action.room_member_id = member.id
    join public.project_permission_rooms room on room.code = member.room_code
    where u.id = p_user_id
      and coalesce(u.is_active, true)
      and staff.end_date is null
      and staff.project_id = p_project_id
      and member.project_id = p_project_id
      and member.room_code = p_room_code
      and coalesce(member.is_active, false)
      and coalesce(action.is_active, false)
      and coalesce(room.is_active, false)
      and action.action_code = p_action_code
      and p_action_code = any(room.allowed_actions)
      and (member.construction_site_id is null or member.construction_site_id = p_construction_site_id)
  );
$$;


--
-- Name: project_workflow_actor_can_act(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_workflow_actor_can_act(p_workflow_subject_id uuid, p_actor uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    exists (
      select 1
      from public.workflow_subjects ws
      join public.workflow_step_assignments wsa
        on wsa.workflow_subject_id = ws.id
       and wsa.workflow_instance_id = ws.workflow_instance_id
       and wsa.instance_node_id = ws.current_instance_node_id
       and wsa.assignee_user_id = p_actor
       and wsa.status = 'PENDING'
      where ws.id = p_workflow_subject_id
        and ws.status = 'RUNNING'
    ),
    false
  );
$$;


--
-- Name: project_workflow_actor_can_select(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_workflow_actor_can_select(p_workflow_subject_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(case when subject.subject_type = 'material_request' then
    app_private.material_request_parent_can_view(subject.subject_id)
  else
    app_private.workflow_subject_can_select(p_workflow_subject_id)
    or exists (
      select 1 from public.workflow_participants participant
      where participant.workflow_subject_id = p_workflow_subject_id
        and participant.user_id = public.current_app_user_id()
        and coalesce(participant.is_active, true)
    )
  end, false)
  from public.workflow_subjects subject
  where subject.id = p_workflow_subject_id;
$$;


--
-- Name: project_workflow_actor_is_admin(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_workflow_actor_is_admin(p_workflow_subject_id uuid, p_actor uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    public.is_admin()
    or public.is_module_admin('WF')
    or exists (
      select 1
      from public.workflow_participants wp
      where wp.workflow_subject_id = p_workflow_subject_id
        and wp.user_id = p_actor
        and wp.role = 'ADMIN'
        and coalesce(wp.is_active, true)
    ),
    false
  );
$$;


--
-- Name: project_workflow_assignee_is_eligible(text, text, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_workflow_assignee_is_eligible(p_subject_type text, p_subject_id text, p_node_id uuid, p_assignee_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_node public.workflow_nodes%rowtype;
  v_request public.requests%rowtype;
  v_mode text;
  v_fixed_user text;
  v_role text;
  v_code_count integer := 0;
  v_target_count integer := 0;
begin
  if p_subject_type <> 'material_request' or p_assignee_user_id is null then return false; end if;
  select * into v_node from public.workflow_nodes wn where wn.id = p_node_id;
  if not found or v_node.type = 'END'::public.workflow_node_type then return false; end if;
  select * into v_request from public.requests r where r.id = p_subject_id;
  if not found then return false; end if;

  if not exists (
    select 1 from public.users u
    where u.id = p_assignee_user_id and coalesce(u.is_active, true)
  ) then return false; end if;

  v_mode := coalesce(nullif(v_node.config ->> 'assignmentMode', ''), 'select_on_transition');
  v_fixed_user := nullif(v_node.config ->> 'assigneeUserId', '');
  v_role := nullif(v_node.config ->> 'assigneeRole', '');
  if v_fixed_user is not null then return v_fixed_user = p_assignee_user_id::text; end if;
  if v_mode = 'creator' then return v_request.requester_id = p_assignee_user_id; end if;
  if v_role is not null and not exists (
    select 1 from public.users u
    where u.id = p_assignee_user_id and u.role::text = v_role and coalesce(u.is_active, true)
  ) then return false; end if;

  select count(*) into v_target_count
  from jsonb_array_elements(coalesce(v_node.config -> 'assignmentTargets', '[]'::jsonb)) target(value);
  if v_target_count > 0 then
    return exists (
      select 1
      from jsonb_array_elements(coalesce(v_node.config -> 'assignmentTargets', '[]'::jsonb)) target(value)
      where (
        target.value ->> 'type' = 'user'
        and target.value ->> 'userId' = p_assignee_user_id::text
      ) or (
        target.value ->> 'type' = 'creator'
        and v_request.requester_id = p_assignee_user_id
      ) or (
        target.value ->> 'type' = 'department'
        and exists (
          select 1 from public.employees e
          where e.user_id = p_assignee_user_id
            and coalesce(e.status, 'Đang làm việc') = 'Đang làm việc'
            and (
              e.department_id::text = target.value ->> 'orgUnitId'
              or e.org_unit_id::text = target.value ->> 'orgUnitId'
            )
        )
      ) or (
        target.value ->> 'type' = 'project_permission'
        and app_private.project_user_has_permission(
          v_request.project_id, v_request.construction_site_id,
          target.value ->> 'permissionCode', p_assignee_user_id
        )
      )
    );
  end if;

  select count(*) into v_code_count
  from jsonb_array_elements_text(coalesce(v_node.config -> 'eligiblePermissionCodes', '[]'::jsonb)) code(value);
  if v_code_count > 0 then
    return exists (
      select 1
      from jsonb_array_elements_text(coalesce(v_node.config -> 'eligiblePermissionCodes', '[]'::jsonb)) code(value)
      where app_private.project_user_has_permission(
        v_request.project_id, v_request.construction_site_id, code.value, p_assignee_user_id
      )
    );
  end if;

  return exists (
    select 1 from public.project_staff ps
    where ps.user_id::text = p_assignee_user_id::text
      and ps.end_date is null
      and (
        (v_request.project_id is not null and ps.project_id::text = v_request.project_id)
        or (v_request.construction_site_id is not null and ps.construction_site_id::text = v_request.construction_site_id)
      )
  );
end;
$$;


--
-- Name: project_workflow_assignees_are_eligible(text, text, uuid, uuid[]); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_workflow_assignees_are_eligible(p_subject_type text, p_subject_id text, p_node_id uuid, p_assignee_user_ids uuid[]) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_ids uuid[] := app_private.project_workflow_distinct_uuid_array(p_assignee_user_ids);
  v_id uuid;
begin
  if coalesce(array_length(v_ids, 1), 0) = 0 then
    return false;
  end if;

  foreach v_id in array v_ids loop
    if not app_private.project_workflow_assignee_is_eligible(p_subject_type, p_subject_id, p_node_id, v_id) then
      return false;
    end if;
  end loop;

  return true;
end;
$$;


--
-- Name: project_workflow_binding_can_manage(text, text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_workflow_binding_can_manage(p_project_id text, p_construction_site_id text, p_template_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    public.is_admin()
    or public.is_module_admin('WF')
    or (
      p_project_id is not null
      and app_private.project_user_has_permission(
        p_project_id, p_construction_site_id, 'edit', public.current_app_user_id()
      )
      and (
        public.is_module_admin('DA')
        or (
          (
            (p_template_id is not null and app_private.project_workflow_template_manager(p_template_id, public.current_app_user_id()))
            or (
              p_template_id is null
              and exists (
                select 1
                from public.workflow_templates wt
                where public.current_app_user_id()::text = any(coalesce(wt.managers, '{}'::text[]))
              )
            )
          )
        )
      )
    ),
    false
  );
$$;


--
-- Name: project_workflow_distinct_uuid_array(uuid[]); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_workflow_distinct_uuid_array(p_ids uuid[]) RETURNS uuid[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(array_agg(distinct id order by id), '{}'::uuid[])
  from unnest(coalesce(p_ids, '{}'::uuid[])) as ids(id)
  where id is not null;
$$;


--
-- Name: project_workflow_ensure_template_version(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_workflow_ensure_template_version(p_template_id uuid, p_actor uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_template public.workflow_templates%rowtype;
  v_version_number integer;
  v_version_id uuid;
  v_snapshot jsonb;
begin
  select *
    into v_template
  from public.workflow_templates
  where id = p_template_id;

  if not found then
    raise exception 'workflow template not found: %', p_template_id;
  end if;

  select coalesce(max(version_number), 0) + 1
    into v_version_number
  from public.workflow_template_versions
  where template_id = p_template_id;

  v_snapshot := jsonb_build_object(
    'template', to_jsonb(v_template),
    'nodes', coalesce((
      select jsonb_agg(to_jsonb(wn) order by wn.position_y nulls first, wn.position_x nulls first)
      from public.workflow_nodes wn
      where wn.template_id = p_template_id
    ), '[]'::jsonb),
    'edges', coalesce((
      select jsonb_agg(to_jsonb(we) order by we.id)
      from public.workflow_edges we
      where we.template_id = p_template_id
    ), '[]'::jsonb)
  );

  insert into public.workflow_template_versions(
    template_id,
    version_number,
    name,
    description,
    custom_fields,
    managers,
    default_watchers,
    snapshot,
    created_by
  )
  values (
    p_template_id,
    v_version_number,
    v_template.name,
    v_template.description,
    coalesce(v_template.custom_fields, '[]'::jsonb),
    coalesce(v_template.managers, '{}'::text[]),
    coalesce(v_template.default_watchers, '{}'::text[]),
    v_snapshot,
    p_actor
  )
  returning id into v_version_id;

  return v_version_id;
end;
$$;


--
-- Name: project_workflow_first_assignee_name(uuid[]); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_workflow_first_assignee_name(p_assignee_ids uuid[]) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_ids uuid[] := app_private.project_workflow_distinct_uuid_array(p_assignee_ids);
  v_first uuid;
  v_first_name text;
  v_count integer;
begin
  v_count := coalesce(array_length(v_ids, 1), 0);
  if v_count = 0 then
    return null;
  end if;

  v_first := v_ids[1];
  select u.name into v_first_name from public.users u where u.id = v_first;
  if v_count = 1 then
    return coalesce(v_first_name, v_first::text);
  end if;
  return coalesce(v_first_name, v_first::text) || ' + ' || (v_count - 1)::text || ' người';
end;
$$;


--
-- Name: project_workflow_first_task_node(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_workflow_first_task_node(p_template_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select e.target_node_id
  from public.workflow_nodes start_node
  join public.workflow_edges e
    on e.source_node_id = start_node.id
  join public.workflow_nodes target_node
    on target_node.id = e.target_node_id
  where start_node.template_id = p_template_id
    and start_node.type = 'START'::public.workflow_node_type
    and target_node.type <> 'END'::public.workflow_node_type
  order by target_node.position_y nulls last
  limit 1;
$$;


--
-- Name: project_workflow_insert_assignment_pool(uuid, uuid, uuid, uuid, uuid[], uuid, text, jsonb, text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_workflow_insert_assignment_pool(p_workflow_subject_id uuid, p_workflow_instance_id uuid, p_node_id uuid, p_instance_node_id uuid, p_assignee_user_ids uuid[], p_assigned_by uuid, p_comment text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_assignment_source text DEFAULT 'manual'::text, p_assignment_group_type text DEFAULT NULL::text, p_assignment_group_id text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_ids uuid[] := app_private.project_workflow_distinct_uuid_array(p_assignee_user_ids);
  v_id uuid;
  v_sla_hours integer := app_private.project_workflow_runtime_sla_hours(p_instance_node_id);
  v_due_at timestamptz := app_private.project_workflow_runtime_sla_due_at(p_instance_node_id);
  v_node_config jsonb := app_private.project_workflow_runtime_node_config(p_instance_node_id);
  v_target jsonb;
  v_watcher_user_id uuid;
  v_round_id uuid := gen_random_uuid();
begin
  foreach v_id in array v_ids loop
    insert into public.workflow_step_assignments(
      workflow_subject_id, workflow_instance_id, node_id, instance_node_id,
      assignee_user_id, assigned_by, status, assigned_at, action_comment,
      metadata, due_at, sla_hours, assignment_source, assignment_group_type,
      assignment_group_id
    )
    values (
      p_workflow_subject_id, p_workflow_instance_id, p_node_id, p_instance_node_id,
      v_id, p_assigned_by, 'PENDING', now(), nullif(coalesce(p_comment, ''), ''),
      coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object('assignmentRoundId', v_round_id),
      v_due_at, v_sla_hours,
      p_assignment_source, p_assignment_group_type, p_assignment_group_id
    );

    update public.workflow_step_assignments
    set assignment_round_id = v_round_id
    where id = (
      select wsa.id
      from public.workflow_step_assignments wsa
      where wsa.workflow_subject_id = p_workflow_subject_id
        and wsa.workflow_instance_id = p_workflow_instance_id
        and wsa.assignee_user_id = v_id
        and wsa.status = 'PENDING'
      order by wsa.assigned_at desc
      limit 1
    );

    perform app_private.project_workflow_register_participant(
      p_workflow_subject_id, p_workflow_instance_id, v_id, 'ASSIGNEE',
      p_assignment_source, p_assignment_group_id, p_node_id, p_instance_node_id, p_assigned_by
    );
  end loop;

  for v_target in
    select value
    from jsonb_array_elements(coalesce(v_node_config -> 'stepWatcherTargets', '[]'::jsonb)) target(value)
  loop
    if coalesce(v_target ->> 'type', '') = 'user' and nullif(v_target ->> 'userId', '') is not null then
      perform app_private.project_workflow_register_participant(
        p_workflow_subject_id, p_workflow_instance_id, (v_target ->> 'userId')::uuid,
        'WATCHER', 'step_watcher', p_instance_node_id::text, p_node_id,
        p_instance_node_id, p_assigned_by
      );
    elsif coalesce(v_target ->> 'type', '') = 'department' and nullif(v_target ->> 'orgUnitId', '') is not null then
      for v_watcher_user_id in
        select distinct e.user_id
        from public.employees e
        where e.user_id is not null
          and coalesce(e.status, 'Đang làm việc') = 'Đang làm việc'
          and (
            e.department_id::text = v_target ->> 'orgUnitId'
            or e.org_unit_id::text = v_target ->> 'orgUnitId'
          )
      loop
        perform app_private.project_workflow_register_participant(
          p_workflow_subject_id, p_workflow_instance_id, v_watcher_user_id,
          'WATCHER', 'step_watcher_department', v_target ->> 'orgUnitId',
          p_node_id, p_instance_node_id, p_assigned_by
        );
      end loop;
    end if;
  end loop;
end;
$$;


--
-- Name: project_workflow_instance_can_select(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_workflow_instance_can_select(p_instance_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select not exists (
    select 1 from public.workflow_subjects ws where ws.workflow_instance_id = p_instance_id
  ) or exists (
    select 1
    from public.workflow_subjects ws
    where ws.workflow_instance_id = p_instance_id
      and app_private.project_workflow_actor_can_select(ws.id)
  );
$$;


--
