-- Name: project_workflow_node_sla_hours(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_workflow_node_sla_hours(p_node_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  select nullif(wn.config ->> 'slaHours', '')::integer
  from public.workflow_nodes wn
  where wn.id = p_node_id
    and (wn.config ->> 'slaHours') ~ '^[0-9]+$';
$_$;


--
-- Name: project_workflow_pending_assignee_ids(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_workflow_pending_assignee_ids(p_workflow_subject_id uuid, p_node_id uuid) RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(array_agg(wsa.assignee_user_id order by wsa.assigned_at, wsa.assignee_user_id), '{}'::uuid[])
  from public.workflow_step_assignments wsa
  join public.workflow_subjects ws on ws.id = wsa.workflow_subject_id
  where wsa.workflow_subject_id = p_workflow_subject_id
    and wsa.workflow_instance_id = ws.workflow_instance_id
    and (
      (ws.current_instance_node_id is not null and wsa.instance_node_id = ws.current_instance_node_id)
      or (ws.current_instance_node_id is null and wsa.node_id = p_node_id)
    )
    and wsa.status = 'PENDING'
    and wsa.assignee_user_id is not null;
$$;


--
-- Name: project_workflow_register_participant(uuid, uuid, uuid, text, text, text, uuid, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_workflow_register_participant(p_workflow_subject_id uuid, p_workflow_instance_id uuid, p_user_id uuid, p_role text, p_source text DEFAULT 'manual'::text, p_source_ref text DEFAULT NULL::text, p_node_id uuid DEFAULT NULL::uuid, p_instance_node_id uuid DEFAULT NULL::uuid, p_created_by uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_user_id is null or p_role not in ('ADMIN', 'WATCHER', 'CREATOR', 'ASSIGNEE') then
    return;
  end if;

  update public.workflow_participants
  set workflow_instance_id = p_workflow_instance_id,
      source = coalesce(nullif(p_source, ''), 'manual'),
      source_ref = p_source_ref,
      instance_node_id = p_instance_node_id,
      created_by = p_created_by,
      is_active = true
  where workflow_subject_id = p_workflow_subject_id
    and user_id = p_user_id
    and role = p_role
    and coalesce(node_id, '00000000-0000-0000-0000-000000000000'::uuid)
      = coalesce(p_node_id, '00000000-0000-0000-0000-000000000000'::uuid)
    and coalesce(is_active, true);

  if not found then
    insert into public.workflow_participants(
      workflow_subject_id,
      workflow_instance_id,
      user_id,
      role,
      source,
      source_ref,
      node_id,
      instance_node_id,
      created_by,
      is_active
    )
    values (
      p_workflow_subject_id,
      p_workflow_instance_id,
      p_user_id,
      p_role,
      coalesce(nullif(p_source, ''), 'manual'),
      p_source_ref,
      p_node_id,
      p_instance_node_id,
      p_created_by,
      true
    );
  end if;
end;
$$;


--
-- Name: project_workflow_resolve_template(text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_workflow_resolve_template(p_subject_type text, p_project_id text, p_construction_site_id text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select pwb.workflow_template_id
  from public.project_workflow_bindings pwb
  join public.workflow_templates wt
    on wt.id = pwb.workflow_template_id
   and coalesce(wt.is_active, true)
  where pwb.subject_type = p_subject_type
    and coalesce(pwb.is_active, true)
    and coalesce(pwb.is_default, true)
    and (
      (p_construction_site_id is not null and pwb.construction_site_id = p_construction_site_id)
      or (p_project_id is not null and pwb.project_id = p_project_id and pwb.construction_site_id is null)
      or (pwb.project_id is null and pwb.construction_site_id is null)
    )
  order by case
    when p_construction_site_id is not null and pwb.construction_site_id = p_construction_site_id then 1
    when p_project_id is not null and pwb.project_id = p_project_id and pwb.construction_site_id is null then 2
    else 3
  end
  limit 1;
$$;


--
-- Name: project_workflow_runtime_assignee_is_eligible(text, text, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_workflow_runtime_assignee_is_eligible(p_subject_type text, p_subject_id text, p_instance_node_id uuid, p_assignee_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_node public.workflow_instance_nodes%rowtype;
  v_request public.requests%rowtype;
  v_mode text;
  v_fixed_user text;
  v_role text;
  v_code_count integer := 0;
  v_target_count integer := 0;
begin
  if p_subject_type <> 'material_request' or p_assignee_user_id is null then
    return false;
  end if;

  select * into v_node
  from public.workflow_instance_nodes win
  where win.id = p_instance_node_id;
  if not found or v_node.type = 'END'::public.workflow_node_type then
    return false;
  end if;

  select * into v_request from public.requests r where r.id = p_subject_id;
  if not found then return false; end if;

  if not exists (
    select 1 from public.users u
    where u.id = p_assignee_user_id and coalesce(u.is_active, true)
  ) then
    return false;
  end if;

  v_mode := coalesce(nullif(v_node.config ->> 'assignmentMode', ''), 'select_on_transition');
  v_fixed_user := nullif(v_node.config ->> 'assigneeUserId', '');
  v_role := nullif(v_node.config ->> 'assigneeRole', '');

  if v_fixed_user is not null then
    return v_fixed_user = p_assignee_user_id::text;
  end if;
  if v_mode = 'creator' then
    return v_request.requester_id = p_assignee_user_id;
  end if;
  if v_role is not null and not exists (
    select 1 from public.users u
    where u.id = p_assignee_user_id and u.role::text = v_role and coalesce(u.is_active, true)
  ) then
    return false;
  end if;

  select count(*) into v_target_count
  from jsonb_array_elements(coalesce(v_node.config -> 'assignmentTargets', '[]'::jsonb)) target(value);

  if v_target_count > 0 then
    return exists (
      select 1
      from jsonb_array_elements(coalesce(v_node.config -> 'assignmentTargets', '[]'::jsonb)) target(value)
      where (
        target.value ->> 'type' = 'user'
        and target.value ->> 'userId' = p_assignee_user_id::text
      ) or (
        target.value ->> 'type' = 'creator'
        and v_request.requester_id = p_assignee_user_id
      ) or (
        target.value ->> 'type' = 'department'
        and exists (
          select 1
          from public.employees e
          where e.user_id = p_assignee_user_id
            and coalesce(e.status, 'Đang làm việc') = 'Đang làm việc'
            and (
              e.department_id::text = target.value ->> 'orgUnitId'
              or e.org_unit_id::text = target.value ->> 'orgUnitId'
            )
        )
      ) or (
        target.value ->> 'type' = 'project_permission'
        and app_private.project_user_has_permission(
          v_request.project_id,
          v_request.construction_site_id,
          target.value ->> 'permissionCode',
          p_assignee_user_id
        )
      )
    );
  end if;

  select count(*) into v_code_count
  from jsonb_array_elements_text(coalesce(v_node.config -> 'eligiblePermissionCodes', '[]'::jsonb)) code(value);

  if v_code_count > 0 then
    return exists (
      select 1
      from jsonb_array_elements_text(coalesce(v_node.config -> 'eligiblePermissionCodes', '[]'::jsonb)) code(value)
      where app_private.project_user_has_permission(
        v_request.project_id,
        v_request.construction_site_id,
        code.value,
        p_assignee_user_id
      )
    );
  end if;

  return exists (
    select 1
    from public.project_staff ps
    where ps.user_id::text = p_assignee_user_id::text
      and ps.end_date is null
      and (
        (v_request.project_id is not null and ps.project_id::text = v_request.project_id)
        or (v_request.construction_site_id is not null and ps.construction_site_id::text = v_request.construction_site_id)
      )
  );
end;
$$;


--
-- Name: project_workflow_runtime_assignees_are_eligible(text, text, uuid, uuid[]); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_workflow_runtime_assignees_are_eligible(p_subject_type text, p_subject_id text, p_instance_node_id uuid, p_assignee_user_ids uuid[]) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_ids uuid[] := app_private.project_workflow_distinct_uuid_array(p_assignee_user_ids);
  v_id uuid;
begin
  if coalesce(array_length(v_ids, 1), 0) = 0 then return false; end if;
  foreach v_id in array v_ids loop
    if not app_private.project_workflow_runtime_assignee_is_eligible(
      p_subject_type, p_subject_id, p_instance_node_id, v_id
    ) then
      return false;
    end if;
  end loop;
  return true;
end;
$$;


