--
-- Name: project_workflow_runtime_to_coarse_step(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_workflow_runtime_to_coarse_step(p_workflow_instance_id uuid, p_instance_node_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when p_instance_node_id is null then null
    when p_instance_node_id = (
      select wie.target_instance_node_id
      from public.workflow_instance_nodes start_node
      join public.workflow_instance_edges wie
        on wie.workflow_instance_id = start_node.workflow_instance_id
       and wie.source_instance_node_id = start_node.id
      join public.workflow_instance_nodes target_node
        on target_node.id = wie.target_instance_node_id
      where start_node.workflow_instance_id = p_workflow_instance_id
        and start_node.type = 'START'::public.workflow_node_type
        and target_node.type <> 'END'::public.workflow_node_type
      order by target_node.position_y, target_node.position_x
      limit 1
    ) then 'site_manager_review'
    else 'material_department_review'
  end;
$$;


--
-- Name: project_workflow_snapshot_instance(uuid, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_workflow_snapshot_instance(p_workflow_instance_id uuid, p_template_version_id uuid, p_template_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.workflow_instance_nodes(
    workflow_instance_id,
    template_version_id,
    template_node_id,
    type,
    label,
    config,
    position_x,
    position_y
  )
  select
    p_workflow_instance_id,
    p_template_version_id,
    wn.id,
    wn.type,
    wn.label,
    coalesce(wn.config, '{}'::jsonb),
    coalesce(wn.position_x, 0),
    coalesce(wn.position_y, 0)
  from public.workflow_nodes wn
  where wn.template_id = p_template_id
  on conflict (workflow_instance_id, template_node_id) do nothing;

  insert into public.workflow_instance_edges(
    workflow_instance_id,
    template_version_id,
    template_edge_id,
    source_instance_node_id,
    target_instance_node_id,
    label
  )
  select
    p_workflow_instance_id,
    p_template_version_id,
    we.id,
    source_node.id,
    target_node.id,
    we.label
  from public.workflow_edges we
  join public.workflow_instance_nodes source_node
    on source_node.workflow_instance_id = p_workflow_instance_id
   and source_node.template_node_id = we.source_node_id
  join public.workflow_instance_nodes target_node
    on target_node.workflow_instance_id = p_workflow_instance_id
   and target_node.template_node_id = we.target_node_id
  where we.template_id = p_template_id;
end;
$$;


