-- Name: project_workflow_to_coarse_step(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_workflow_to_coarse_step(p_template_id uuid, p_node_id uuid) RETURNS text
