--
-- Name: project_workflow_validate_template(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.project_workflow_validate_template(p_template_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_template_active boolean := false;
  v_start_count integer := 0;
  v_end_count integer := 0;
  v_task_count integer := 0;
  v_path_reaches_end boolean := false;
  v_invalid_step_count integer := 0;
  v_errors text[] := '{}'::text[];
begin
  select coalesce(wt.is_active, true)
    into v_template_active
  from public.workflow_templates wt
  where wt.id = p_template_id;

  if not found then
    return jsonb_build_object('valid', false, 'errors', jsonb_build_array('Không tìm thấy mẫu workflow.'));
  end if;

  if not v_template_active then
    v_errors := array_append(v_errors, 'Mẫu workflow đang ngừng hoạt động.');
  end if;

  select
    count(*) filter (where wn.type = 'START'::public.workflow_node_type),
    count(*) filter (where wn.type = 'END'::public.workflow_node_type),
    count(*) filter (where wn.type not in ('START'::public.workflow_node_type, 'END'::public.workflow_node_type)),
    count(*) filter (
      where wn.type not in ('START'::public.workflow_node_type, 'END'::public.workflow_node_type)
        and (
          coalesce(nullif(wn.label, ''), '') = ''
          or coalesce(nullif(wn.config ->> 'approvalPolicy', ''), 'ANY_ONE') <> 'ANY_ONE'
        )
    )
  into v_start_count, v_end_count, v_task_count, v_invalid_step_count
  from public.workflow_nodes wn
  where wn.template_id = p_template_id
    and coalesce((wn.config ->> '__templateRemoved')::boolean, false) = false;

  if v_start_count <> 1 then
    v_errors := array_append(v_errors, 'Workflow phải có đúng một bước Bắt đầu.');
  end if;
  if v_end_count <> 1 then
    v_errors := array_append(v_errors, 'Workflow phải có đúng một bước Kết thúc.');
  end if;
  if v_task_count < 1 then
    v_errors := array_append(v_errors, 'Workflow phải có ít nhất một bước xử lý.');
  end if;
  if v_invalid_step_count > 0 then
    v_errors := array_append(v_errors, 'Có bước xử lý thiếu tên hoặc dùng approval policy chưa được hỗ trợ.');
  end if;

  with recursive walk(node_id, visited) as (
    select wn.id, array[wn.id]
    from public.workflow_nodes wn
    where wn.template_id = p_template_id
      and wn.type = 'START'::public.workflow_node_type
      and coalesce((wn.config ->> '__templateRemoved')::boolean, false) = false
    union all
    select we.target_node_id, walk.visited || we.target_node_id
    from walk
    join public.workflow_edges we on we.source_node_id = walk.node_id
    join public.workflow_nodes target_node on target_node.id = we.target_node_id
    where not (we.target_node_id = any(walk.visited))
      and coalesce((target_node.config ->> '__templateRemoved')::boolean, false) = false
  )
  select exists (
    select 1
    from walk
    join public.workflow_nodes wn on wn.id = walk.node_id
    where wn.type = 'END'::public.workflow_node_type
      and coalesce((wn.config ->> '__templateRemoved')::boolean, false) = false
  ) into v_path_reaches_end;

  if not v_path_reaches_end then
    v_errors := array_append(v_errors, 'Không có đường đi hợp lệ từ Bắt đầu tới Kết thúc.');
  end if;

  return jsonb_build_object(
    'valid', coalesce(array_length(v_errors, 1), 0) = 0,
    'errors', to_jsonb(v_errors),
    'startCount', v_start_count,
    'endCount', v_end_count,
    'taskCount', v_task_count
  );
end;
$$;


--
-- Name: publish_request_template_version(uuid, timestamp with time zone); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.publish_request_template_version(p_request_template_id uuid, p_expected_updated_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_template public.request_templates%rowtype;
  v_draft public.request_template_versions%rowtype;
  v_old_version public.request_template_versions%rowtype;
  v_workflow_template_id uuid;
  v_workflow_version_id uuid;
  v_start_node_id uuid := gen_random_uuid();
  v_end_node_id uuid := gen_random_uuid();
  v_node_id uuid;
  v_next_node_id uuid;
  v_block record;
  v_block_ids uuid[] := '{}'::uuid[];
  v_number integer;
  v_snapshot jsonb;
  v_docx_path text;
begin
  if v_actor is null or not app_private.request_user_can_manage(v_actor) then
    raise exception using errcode = '42501', message = 'REQUEST_TEMPLATE_FORBIDDEN';
  end if;
  if p_expected_updated_at is null then
    raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_EXPECTED_UPDATED_AT_REQUIRED';
  end if;
  select * into v_template
  from public.request_templates
  where id = p_request_template_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'REQUEST_TEMPLATE_NOT_FOUND';
  end if;
  if v_template.updated_at <> p_expected_updated_at then
    raise exception using errcode = '40001', message = 'CONFLICT';
  end if;
  select * into v_draft
  from public.request_template_versions
  where request_template_id = v_template.id
    and status = 'DRAFT'
  order by version_number desc
  limit 1
  for update;
  if not found then
    raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_DRAFT_REQUIRED';
  end if;
  if jsonb_typeof(v_draft.form_schema) <> 'array'
     or jsonb_array_length(v_draft.form_schema) = 0
     or not exists (
       select 1 from public.request_approval_blocks block
       where block.request_template_version_id = v_draft.id
     ) then
    raise exception using errcode = '22023', message = 'REQUEST_FORM_SCHEMA_INVALID';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(v_draft.form_schema) field
    where jsonb_typeof(field) <> 'object'
       or nullif(trim(field ->> 'key'), '') is null
       or nullif(trim(field ->> 'label'), '') is null
       or coalesce(field ->> 'fieldType', '') not in (
         'text', 'textarea', 'number', 'date', 'select', 'table', 'user', 'file'
       )
  ) or exists (
    select field ->> 'key'
    from jsonb_array_elements(v_draft.form_schema) field
    group by field ->> 'key'
    having count(*) > 1
  ) then
    raise exception using errcode = '22023', message = 'REQUEST_FORM_SCHEMA_INVALID';
  end if;
  if exists (
    select 1
    from public.request_approval_blocks block
    left join public.users app_user
      on app_user.id = any(block.fixed_user_ids)
    where block.request_template_version_id = v_draft.id
      and block.approver_source in ('FIXED_SINGLE', 'FIXED_MULTI')
      and (
        cardinality(block.fixed_user_ids) = 0
        or exists (
          select 1
          from unnest(block.fixed_user_ids) fixed_id
          left join public.users fixed_user on fixed_user.id = fixed_id
          where fixed_user.id is null
             or not coalesce(fixed_user.is_active, true)
             or coalesce(fixed_user.account_status, 'ACTIVE') <> 'ACTIVE'
        )
      )
  ) then
    raise exception using errcode = '22023', message = 'REQUEST_APPROVER_INACTIVE';
  end if;

  v_docx_path := v_draft.print_config ->> 'docxStoragePath';
  if v_docx_path is not null and v_docx_path <> '' then
    if not exists (
      select 1
      from public.request_print_templates print_template
      where print_template.request_template_version_id = v_draft.id
        and print_template.storage_path = v_docx_path
        and print_template.validation_status = 'VALID'
    ) then
      raise exception using errcode = '22023', message = 'REQUEST_PRINT_TEMPLATE_INVALID';
    end if;
    if exists (
      select 1
      from public.request_print_templates print_template
      cross join lateral jsonb_object_keys(
        case
          when jsonb_typeof(print_template.placeholder_schema) = 'object'
            then print_template.placeholder_schema
          else '{}'::jsonb
        end
      ) placeholder_key
      where print_template.request_template_version_id = v_draft.id
        and print_template.storage_path = v_docx_path
        and print_template.validation_status = 'VALID'
        and placeholder_key not in (
          select field ->> 'key'
          from jsonb_array_elements(v_draft.form_schema) field
          union all
          select value from jsonb_array_elements_text(
            '["title","description","requestCode","createdAt","createdBy"]'::jsonb
          )
        )
    ) then
      raise exception using errcode = '22023', message = 'REQUEST_PRINT_PLACEHOLDER_UNKNOWN';
    end if;
    if exists (
      select 1
      from public.request_print_templates print_template
      where print_template.request_template_version_id = v_draft.id
        and print_template.storage_path = v_docx_path
        and jsonb_typeof(print_template.placeholder_schema) <> 'object'
    ) then
      raise exception using errcode = '22023', message = 'REQUEST_PRINT_PLACEHOLDER_INVALID';
    end if;
  end if;

  v_workflow_template_id := gen_random_uuid();
  insert into public.workflow_templates(
    id, name, description, created_by, is_active, custom_fields,
    managers, default_watchers
  ) values (
    v_workflow_template_id,
    '[Request] ' || v_template.name,
    coalesce(v_template.description, ''),
    v_actor,
    true,
    jsonb_build_array(jsonb_build_object('_requestTemplateId', v_template.id)),
    '{}'::text[],
    '{}'::text[]
  );
  update public.request_templates
  set workflow_template_id = v_workflow_template_id
  where id = v_template.id;

  insert into public.workflow_nodes(id, template_id, type, label, config, position_x, position_y)
  values (
    v_start_node_id, v_workflow_template_id, 'START'::public.workflow_node_type,
    'Bắt đầu đề xuất', jsonb_build_object('executionPolicy', 'AUTO_ADVANCE_APPROVAL'), 0, 0
  );

  for v_block in
    select *
    from public.request_approval_blocks
    where request_template_version_id = v_draft.id
    order by sort_order, block_key
  loop
    v_node_id := gen_random_uuid();
    v_block_ids := array_append(v_block_ids, v_node_id);
    insert into public.workflow_nodes(
      id, template_id, type, label, config, position_x, position_y
    ) values (
      v_node_id,
      v_workflow_template_id,
      'APPROVAL'::public.workflow_node_type,
      v_block.name,
      jsonb_build_object(
        'executionPolicy', 'AUTO_ADVANCE_APPROVAL',
        'requestBlockKey', v_block.block_key,
        'approverSource', v_block.approver_source,
        'fixedUserIds', to_jsonb(v_block.fixed_user_ids),
        'minimumDynamicApprovers', v_block.minimum_dynamic_approvers,
        'flowMode', v_draft.flow_mode,
        'completionPolicy', v_draft.completion_policy,
        'slaHours', v_block.sla_hours
      ),
      v_block.sort_order * 240 + 180,
      v_block.sort_order * 120
    );
  end loop;

  insert into public.workflow_nodes(id, template_id, type, label, config, position_x, position_y)
  values (
    v_end_node_id, v_workflow_template_id, 'END'::public.workflow_node_type,
    'Hoàn thành đề xuất', jsonb_build_object('executionPolicy', 'AUTO_ADVANCE_APPROVAL'),
    (coalesce(array_length(v_block_ids, 1), 0) + 1) * 240, 0
  );

  if v_draft.flow_mode = 'PARALLEL' then
    for v_number in 1..coalesce(array_length(v_block_ids, 1), 0) loop
      insert into public.workflow_edges(template_id, source_node_id, target_node_id, label)
      values (v_workflow_template_id, v_start_node_id, v_block_ids[v_number], 'Bước duyệt');
      insert into public.workflow_edges(template_id, source_node_id, target_node_id, label)
      values (v_workflow_template_id, v_block_ids[v_number], v_end_node_id, 'Hoàn tất');
    end loop;
  else
    v_next_node_id := v_start_node_id;
    for v_number in 1..coalesce(array_length(v_block_ids, 1), 0) loop
      insert into public.workflow_edges(template_id, source_node_id, target_node_id, label)
      values (v_workflow_template_id, v_next_node_id, v_block_ids[v_number], 'Bước kế tiếp');
      v_next_node_id := v_block_ids[v_number];
    end loop;
    insert into public.workflow_edges(template_id, source_node_id, target_node_id, label)
    values (v_workflow_template_id, v_next_node_id, v_end_node_id, 'Hoàn tất');
  end if;

  select coalesce(max(version_number), 0) + 1
    into v_number
  from public.workflow_template_versions
  where template_id = v_workflow_template_id;
  v_snapshot := jsonb_build_object(
    'template', (select to_jsonb(template) from public.workflow_templates template where template.id = v_workflow_template_id),
    'nodes', coalesce((
      select jsonb_agg(to_jsonb(node) order by node.position_y, node.position_x, node.id)
      from public.workflow_nodes node
      where node.template_id = v_workflow_template_id
    ), '[]'::jsonb),
    'edges', coalesce((
      select jsonb_agg(to_jsonb(edge) order by edge.id)
      from public.workflow_edges edge
      where edge.template_id = v_workflow_template_id
    ), '[]'::jsonb)
  );
  insert into public.workflow_template_versions(
    template_id, version_number, name, description, custom_fields,
    managers, default_watchers, snapshot, created_by
  )
  select workflow_template.id, v_number, workflow_template.name,
    workflow_template.description, workflow_template.custom_fields,
    workflow_template.managers, workflow_template.default_watchers,
    v_snapshot, v_actor
  from public.workflow_templates workflow_template
  where workflow_template.id = v_workflow_template_id
  returning id into v_workflow_version_id;

  select * into v_old_version
  from public.request_template_versions
  where request_template_id = v_template.id
    and status = 'PUBLISHED'
  order by version_number desc
  limit 1
  for update;
  if found then
    update public.request_template_versions
    set status = 'SUPERSEDED'
    where id = v_old_version.id;
  end if;
  update public.request_template_versions
  set status = 'PUBLISHED',
      workflow_template_version_id = v_workflow_version_id,
      published_by = v_actor,
      published_at = now()
  where id = v_draft.id;
  update public.request_templates
  set lifecycle_status = 'PUBLISHED', current_version_id = v_draft.id
  where id = v_template.id;

  return jsonb_build_object(
    'requestTemplateId', v_template.id,
    'requestTemplateVersionId', v_draft.id,
    'versionNumber', v_draft.version_number,
    'workflowTemplateId', v_workflow_template_id,
    'workflowTemplateVersionId', v_workflow_version_id
  );
end;
$$;


--
-- Name: purchase_delivery_command_result_v2(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.purchase_delivery_command_result_v2(p_delivery_batch_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'deliveryBatchId', batch.id::text,
    'deliveryNo', batch.delivery_no,
    'deliveryCode', po.po_number || '-' || lpad(batch.delivery_no::text, 2, '0'),
    'wmsTransactionId', coalesce(batch.wms_transaction_id, ''),
    'qrToken', coalesce(batch.qr_token, '')
  )
  from public.purchase_order_delivery_batches batch
  join public.purchase_orders po on po.id = batch.purchase_order_id
  where batch.id = p_delivery_batch_id;
$$;


--
-- Name: purchase_order_can_receive(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.purchase_order_can_receive(p_purchase_order_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    public.is_admin()
    or app_private.current_user_is_global_wms_keeper()
    or exists (
      select 1
      from public.purchase_orders po
      where po.id = p_purchase_order_id
        and (
          app_private.current_user_is_wms_keeper_for(po.target_warehouse_id)
          or app_private.project_actor_has_effective_room_action(
            public.current_app_user_id(), po.project_id, po.construction_site_id,
            'material_po', 'confirm'
          )
        )
    );
$$;


--
-- Name: purchase_order_can_receive_by_delivery_batch(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.purchase_order_can_receive_by_delivery_batch(p_delivery_batch_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.purchase_order_delivery_batches batch
    where batch.id = p_delivery_batch_id
      and app_private.purchase_order_can_receive(batch.purchase_order_id)
  );
$$;


--
-- Name: purchase_order_can_view(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.purchase_order_can_view(p_purchase_order_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.purchase_orders po
    where po.id = p_purchase_order_id
      and po.archived_at is null
      and (
        (
          po.source_mode = 'company_consolidated'
          and (
            app_private.company_procurement_can_manage()
            or app_private.company_purchase_order_can_view_from_links(po.id)
          )
        )
        or (
          po.source_mode is distinct from 'company_consolidated'
          and (
            app_private.current_actor_has_effective_room_action(
              po.project_id, po.construction_site_id, 'material_po', 'view'
            )
            or app_private.current_user_is_global_wms_keeper()
            or app_private.current_user_is_wms_keeper_for(po.target_warehouse_id)
          )
        )
      )
  );
$$;


--
-- Name: purchase_order_delivery_can_mutate(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.purchase_order_delivery_can_mutate(p_purchase_order_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    public.is_admin()
    or app_private.company_procurement_can_manage()
    or app_private.current_user_is_global_wms_keeper()
    or exists (
      select 1
      from public.purchase_orders po
      where po.id = p_purchase_order_id
        and (
          app_private.current_user_is_wms_keeper_for(po.target_warehouse_id)
          or app_private.project_actor_has_effective_room_action(
            public.current_app_user_id(), po.project_id, po.construction_site_id,
            'material_po', 'confirm'
          )
          or (
            po.status in ('draft', 'returned')
            and nullif(po.created_by_id, '') = public.current_app_user_id()::text
            and app_private.project_actor_has_effective_room_action(
              public.current_app_user_id(), po.project_id, po.construction_site_id,
              'material_po', 'edit'
            )
          )
        )
    );
$$;


--
-- Name: purchase_order_delivery_can_view(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.purchase_order_delivery_can_view(p_purchase_order_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app_private.purchase_order_can_view(p_purchase_order_id);
$$;


--
-- Name: purchase_order_delivery_group_can_access(text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.purchase_order_delivery_group_can_access(p_purchase_order_id text, p_project_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app_private.purchase_order_can_view(p_purchase_order_id);
$$;


--
-- Name: purchase_order_link_can_access(text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.purchase_order_link_can_access(p_purchase_order_id text, p_project_id text, p_construction_site_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app_private.purchase_order_can_view(p_purchase_order_id)
    or app_private.current_actor_has_effective_room_action(
      p_project_id, p_construction_site_id, 'material_po', 'view'
    );
$$;


--
-- Name: purchase_order_supplemental_can_approve(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.purchase_order_supplemental_can_approve(p_purchase_order_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.is_admin() or exists (
    select 1
    from public.purchase_orders po
    join public.purchase_order_supplemental_approvals approval
      on approval.purchase_order_id = po.id
    where po.id = p_purchase_order_id
      and approval.status = 'pending'
      and approval.submitted_to_user_id = public.current_app_user_id()::text
      and app_private.project_actor_has_effective_room_action(
        public.current_app_user_id(), po.project_id, po.construction_site_id,
        'material_po', 'approve'
      )
  );
$$;


--
-- Name: purchase_order_supplemental_can_create(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.purchase_order_supplemental_can_create(p_purchase_order_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.is_admin() or exists (
    select 1
    from public.purchase_orders po
    where po.id = p_purchase_order_id
      and (
        (
          po.status in ('draft', 'returned')
          and nullif(po.created_by_id, '') = public.current_app_user_id()::text
          and app_private.project_actor_has_effective_room_action(
            public.current_app_user_id(), po.project_id, po.construction_site_id,
            'material_po', 'edit'
          )
        )
        or (
          po.status in ('confirmed', 'in_transit', 'partial')
          and app_private.project_actor_has_effective_room_action(
            public.current_app_user_id(), po.project_id, po.construction_site_id,
            'material_po', 'confirm'
          )
        )
      )
  );
$$;


--
-- Name: purchase_order_supplemental_can_view(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.purchase_order_supplemental_can_view(p_purchase_order_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app_private.purchase_order_can_view(p_purchase_order_id);
$$;


--
-- Name: purchase_receipt_command_result_v2(uuid, boolean); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.purchase_receipt_command_result_v2(p_delivery_batch_id uuid, p_already_finalized boolean DEFAULT false) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'deliveryBatchId', batch.id::text,
    'wmsTransactionId', coalesce(batch.wms_transaction_id, ''),
    'deliveryStatus', batch.status,
    'transactionStatus', tx.status::text,
    'acceptedGrossAmount', coalesce(batch.accepted_gross_amount, 0),
    'alreadyFinalized', p_already_finalized
  )
  from public.purchase_order_delivery_batches batch
  join public.transactions tx on tx.id = batch.wms_transaction_id
  where batch.id = p_delivery_batch_id;
$$;


--
-- Name: quality_current_actor_has_action(text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.quality_current_actor_has_action(p_project_id text, p_construction_site_id text, p_action_code text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app_private.project_actor_has_effective_room_action(
    public.current_app_user_id(), p_project_id, p_construction_site_id,
    'quality', p_action_code
  );
$$;


--
-- Name: quality_storage_can_mutate(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.quality_storage_can_mutate(name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with path as (
    select
      public.current_app_user_id() as actor_id,
      split_part(name, '/', 1) as prefix,
      split_part(name, '/', 2) as first_scope_id,
      case
        when nullif(split_part(name, '/', 5), '') is null
          then split_part(name, '/', 2)
        else split_part(name, '/', 3)
      end as site_id,
      split_part(name, '/', 3) as third_segment,
      split_part(name, '/', 4) as fourth_segment,
      nullif(split_part(name, '/', 5), '') as canonical_file_name
  )
  select case
    when path.actor_id is null
      or path.prefix <> 'quality'
      or nullif(path.first_scope_id, '') is null
      or nullif(path.third_segment, '') is null
      or nullif(path.fourth_segment, '') is null
      then false
    when path.canonical_file_name is not null then
      app_private.project_actor_has_effective_room_action(
        path.actor_id,
        path.first_scope_id,
        path.site_id,
        'quality',
        'edit'
      )
    else exists (
      select 1
      from public.projects project_row
      where project_row.construction_site_id::text = path.site_id
        and app_private.project_actor_has_effective_room_action(
          path.actor_id,
          project_row.id,
          path.site_id,
          'quality',
          'edit'
        )
    )
  end
  from path;
$$;


--
-- Name: recompute_safety_assignment_eligibility(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.recompute_safety_assignment_eligibility(p_assignment_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_next text;
begin
  v_next := app_private.safety_assignment_eligibility_status(p_assignment_id);

  update public.safety_project_assignments
  set eligibility_status = v_next,
      eligibility_checked_at = now(),
      updated_at = now()
  where id = p_assignment_id;

  return v_next;
end;
$$;


--
-- Name: recompute_safety_worker_assignments(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.recompute_safety_worker_assignments(p_worker_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_assignment_id uuid;
begin
  for v_assignment_id in
    select id from public.safety_project_assignments where worker_id = p_worker_id
  loop
    perform app_private.recompute_safety_assignment_eligibility(v_assignment_id);
  end loop;
end;
$$;


--
-- Name: recompute_site_cash_settlement_totals(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.recompute_site_cash_settlement_totals(p_batch_id uuid) RETURNS TABLE(accepted_spend_amount numeric, rejected_spend_amount numeric, approved_site_cash_spend numeric, approved_staff_paid_amount numeric, staff_reimbursed_amount numeric, staff_outstanding_amount numeric, closing_balance numeric)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  with batch as (
    select opening_balance, topup_amount
    from public.site_cash_settlement_batches
    where id = p_batch_id
  ),
  totals as (
    select
      coalesce(sum(case when status in ('accepted', 'adjusted') then approved_amount else 0 end), 0)::numeric(18,2) as accepted_spend_amount,
      coalesce(sum(case when status = 'rejected' then greatest(claimed_amount, spend_amount) else 0 end), 0)::numeric(18,2) as rejected_spend_amount,
      coalesce(sum(case when status in ('accepted', 'adjusted') and payment_source = 'site_cash' then coalesce(nullif(fund_spend_amount, 0), approved_amount) when status in ('accepted', 'adjusted') then fund_spend_amount else 0 end), 0)::numeric(18,2) as approved_site_cash_spend,
      coalesce(sum(case when status in ('accepted', 'adjusted') and payment_source = 'staff_paid' then approved_amount else 0 end), 0)::numeric(18,2) as approved_staff_paid_amount,
      coalesce(sum(case when status in ('accepted', 'adjusted') then staff_reimbursed_amount else 0 end), 0)::numeric(18,2) as staff_reimbursed_amount
    from public.site_cash_settlement_lines
    where settlement_batch_id = p_batch_id
  )
  select
    totals.accepted_spend_amount,
    totals.rejected_spend_amount,
    totals.approved_site_cash_spend,
    totals.approved_staff_paid_amount,
    totals.staff_reimbursed_amount,
    greatest(0, totals.approved_staff_paid_amount - totals.staff_reimbursed_amount)::numeric(18,2) as staff_outstanding_amount,
    (batch.opening_balance + batch.topup_amount - totals.approved_site_cash_spend - totals.staff_reimbursed_amount)::numeric(18,2) as closing_balance
  from batch, totals;
$$;


--
-- Name: record_authorization_override_impl(text, text, text, text, text, text, uuid, timestamp with time zone, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.record_authorization_override_impl(p_rule_code text, p_subject_type text, p_subject_id text, p_scope_type text, p_scope_id text, p_reason text, p_control_owner_user_id uuid, p_expires_at timestamp with time zone, p_idempotency_key uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_actor_user_id uuid;
  v_rule_code text := btrim(coalesce(p_rule_code, ''));
  v_subject_type text := btrim(coalesce(p_subject_type, ''));
  v_subject_id text := btrim(coalesce(p_subject_id, ''));
  v_scope_type text := coalesce(
    nullif(btrim(coalesce(p_scope_type, '')), ''),
    'global'
  );
  v_scope_id text := coalesce(
    nullif(btrim(coalesce(p_scope_id, '')), ''),
    '*'
  );
  v_reason text := btrim(coalesce(p_reason, ''));
  v_existing public.authorization_override_events%rowtype;
  v_rule public.authorization_sod_rules%rowtype;
  v_override_id uuid := gen_random_uuid();
begin
  v_actor_user_id := app_private.assert_authorization_permission(
    'system.authorization.override'
  );

  if p_idempotency_key is null then
    raise exception 'Override idempotency key is required'
      using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      'authorization_override:' || p_idempotency_key::text,
      0
    )
  );

  select *
  into v_existing
  from public.authorization_override_events
  where idempotency_key = p_idempotency_key
  for update;

  if v_existing.id is not null then
    if v_existing.actor_user_id is distinct from v_actor_user_id
      or v_existing.rule_code is distinct from v_rule_code
      or v_existing.subject_type is distinct from v_subject_type
      or v_existing.subject_id is distinct from v_subject_id
      or v_existing.scope_type is distinct from v_scope_type
      or v_existing.scope_id is distinct from v_scope_id
      or v_existing.reason is distinct from v_reason
      or v_existing.control_owner_user_id is distinct from p_control_owner_user_id
      or v_existing.expires_at is distinct from p_expires_at
    then
      raise exception 'Idempotency key is already used for another override command'
        using errcode = '23505';
    end if;

    return v_existing.id;
  end if;

  select *
  into v_rule
  from public.authorization_sod_rules
  where rule_code = v_rule_code
    and is_active
    and effect = 'REQUIRE_OVERRIDE'
    and overridable
  for share;

  if v_rule.rule_code is null then
    raise exception 'Rule cannot be overridden'
      using errcode = '42501';
  end if;

  if v_subject_type !~ '^[a-z][a-z0-9_]*$'
    or v_rule.subject_type is distinct from v_subject_type
    or v_subject_id = ''
    or v_scope_type not in (
      'global','own','assigned','project','construction_site','warehouse','department'
    )
    or (v_scope_type = 'global' and v_scope_id <> '*')
    or (v_scope_type <> 'global' and v_scope_id = '')
    or char_length(v_reason) < 10
    or p_expires_at is null
    or p_expires_at <= now()
    or p_control_owner_user_id is null
    or p_control_owner_user_id = v_actor_user_id
    or not exists (
      select 1
      from public.users owner_row
      where owner_row.id = p_control_owner_user_id
        and owner_row.is_active
        and owner_row.account_status = 'ACTIVE'
        and app_private.has_permission(
          owner_row.id,
          'system.authorization.audit',
          'global',
          '*'
        )
    )
  then
    raise exception 'Invalid override control evidence'
      using errcode = '22023';
  end if;

  insert into public.authorization_override_events (
    id,
    idempotency_key,
    rule_code,
    actor_user_id,
    subject_type,
    subject_id,
    scope_type,
    scope_id,
    reason,
    control_owner_user_id,
    expires_at,
    metadata
  )
  values (
    v_override_id,
    p_idempotency_key,
    v_rule_code,
    v_actor_user_id,
    v_subject_type,
    v_subject_id,
    v_scope_type,
    v_scope_id,
    v_reason,
    p_control_owner_user_id,
    p_expires_at,
    jsonb_build_object('source', 'governed_authorization_override')
  );

  insert into public.permission_audit_events (
    actor_user_id,
    target_user_id,
    event_type,
    before_grants,
    after_grants,
    metadata
  )
  values (
    v_actor_user_id,
    v_actor_user_id,
    'authorization_override_recorded',
    '[]'::jsonb,
    '[]'::jsonb,
    jsonb_build_object(
      'overrideId', v_override_id,
      'ruleCode', v_rule_code,
      'subjectType', v_subject_type,
      'scopeType', v_scope_type,
      'scopeId', v_scope_id,
      'controlOwnerUserId', p_control_owner_user_id,
      'expiresAt', p_expires_at,
      'reason', v_reason
    )
  );

  insert into public.notifications (
    user_id,
    type,
    category,
    title,
    message,
    icon,
    link,
    severity,
    source_type,
    source_id,
    priority,
    push_enabled,
    action_url,
    entity_type,
    entity_id,
    metadata
  )
  values (
    p_control_owner_user_id,
    'warning',
    'authorization',
    'Có override phân quyền cần giám sát',
    'Một ngoại lệ được kiểm soát vừa được ghi nhận. Mở quản trị phân quyền để xem chi tiết.',
    'shield-alert',
    '/settings',
    'warning',
    'authorization_override',
    v_override_id::text,
    'high',
    true,
    '/#/settings',
    'authorization_override',
    v_override_id,
    jsonb_build_object(
      'ruleCode', v_rule_code,
      'subjectType', v_subject_type
    )
  );

  return v_override_id;
end;
$_$;


--
-- Name: record_request_export_audit(uuid, text, text, text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.record_request_export_audit(p_request_id uuid, p_format text, p_result text, p_error_message text, p_client_action_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_audit app_private.request_export_audit;
begin
  if v_actor is null
    or not app_private.request_instance_can_select(p_request_id, v_actor) then
    raise exception using errcode = 'P0001', message = 'REQUEST_NOT_FOUND_OR_FORBIDDEN';
  end if;
  if upper(coalesce(p_format, '')) not in ('PRINT', 'PDF', 'WORD')
    or upper(coalesce(p_result, '')) not in ('SUCCEEDED', 'FAILED')
    or p_client_action_id is null then
    raise exception using errcode = '22023', message = 'REQUEST_PRINT_AUDIT_INVALID';
  end if;

  insert into app_private.request_export_audit (
    request_id, actor_id, format, result, error_message, client_action_id
  ) values (
    p_request_id, v_actor, upper(p_format), upper(p_result),
    nullif(left(trim(coalesce(p_error_message, '')), 500), ''), p_client_action_id
  )
  on conflict (actor_id, client_action_id) do update
    set request_id = excluded.request_id
  returning * into v_audit;

  return jsonb_build_object('id', v_audit.id, 'createdAt', v_audit.created_at);
end;
$$;


--
-- Name: supplier_invoices; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.supplier_invoices (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    supplier_id text NOT NULL,
    supplier_name_snapshot text NOT NULL,
    invoice_number text NOT NULL,
    invoice_date date NOT NULL,
    net_amount numeric NOT NULL,
    vat_amount numeric NOT NULL,
    gross_amount numeric NOT NULL,
    variance_reason text,
    attachments jsonb DEFAULT '[]'::jsonb NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT supplier_invoices_gross_amount_check CHECK ((gross_amount >= (0)::numeric)),
    CONSTRAINT supplier_invoices_net_amount_check CHECK ((net_amount >= (0)::numeric)),
    CONSTRAINT supplier_invoices_vat_amount_check CHECK ((vat_amount >= (0)::numeric))
);


--
-- Name: record_supplier_invoice_reconciliation_v2(jsonb, jsonb, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.record_supplier_invoice_reconciliation_v2(p_invoice jsonb, p_links jsonb, p_actor_user_id uuid) RETURNS public.supplier_invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_invoice public.supplier_invoices%rowtype;
  v_invoice_id uuid := coalesce(nullif(p_invoice ->> 'id', '')::uuid, gen_random_uuid());
  v_supplier_id text := nullif(trim(coalesce(p_invoice ->> 'supplierId', p_invoice ->> 'supplier_id')), '');
  v_supplier_name text := nullif(trim(coalesce(p_invoice ->> 'supplierNameSnapshot', p_invoice ->> 'supplier_name_snapshot')), '');
  v_invoice_number text := nullif(trim(coalesce(p_invoice ->> 'invoiceNumber', p_invoice ->> 'invoice_number')), '');
  v_invoice_date date := nullif(coalesce(p_invoice ->> 'invoiceDate', p_invoice ->> 'invoice_date'), '')::date;
  v_net_amount numeric(18,2) := round(coalesce(nullif(coalesce(p_invoice ->> 'netAmount', p_invoice ->> 'net_amount'), '')::numeric, 0), 2);
  v_vat_amount numeric(18,2) := round(coalesce(nullif(coalesce(p_invoice ->> 'vatAmount', p_invoice ->> 'vat_amount'), '')::numeric, 0), 2);
  v_gross_amount numeric(18,2) := round(coalesce(nullif(coalesce(p_invoice ->> 'grossAmount', p_invoice ->> 'gross_amount'), '')::numeric, 0), 2);
  v_variance_reason text := nullif(trim(coalesce(p_invoice ->> 'varianceReason', p_invoice ->> 'variance_reason', '')), '');
  v_attachments jsonb := coalesce(p_invoice -> 'attachments', '[]'::jsonb);
  v_link jsonb;
  v_payable_id uuid;
  v_allocated numeric(18,2);
  v_allocated_total numeric(18,2) := 0;
  v_estimated_total numeric(18,2) := 0;
  v_variance numeric(18,2);
  v_ap public.supplier_payable_documents%rowtype;
  v_project_id text := null;
  v_site_id text := null;
  v_project_finance_id text := null;
  v_adjustment_ref text;
  v_adjustment_id text;
begin
  if public.current_app_user_id() is null or p_actor_user_id <> public.current_app_user_id() then
    raise exception 'Nguoi thao tac khong hop le.' using errcode = '42501';
  end if;
  if v_supplier_id is null or v_supplier_name is null or v_invoice_number is null then
    raise exception 'Hoa don thieu NCC hoac so hoa don.' using errcode = '22023';
  end if;
  if v_gross_amount <= 0 or v_net_amount < 0 or v_vat_amount < 0 then
    raise exception 'Gia tri hoa don khong hop le.' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_links, '[]'::jsonb)) <> 'array' or jsonb_array_length(p_links) = 0 then
    raise exception 'Hoa don phai link it nhat mot AP.' using errcode = '22023';
  end if;
  if jsonb_typeof(v_attachments) <> 'array' then
    raise exception 'Dinh kem hoa don phai la mang JSON.' using errcode = '22023';
  end if;

  for v_link in select value from jsonb_array_elements(p_links) as link(value)
  loop
    v_payable_id := nullif(coalesce(v_link ->> 'payableDocumentId', v_link ->> 'payable_document_id'), '')::uuid;
    v_allocated := round(coalesce(nullif(coalesce(v_link ->> 'allocatedGrossAmount', v_link ->> 'allocated_gross_amount'), '')::numeric, 0), 2);
    if v_payable_id is null or v_allocated <= 0 then
      raise exception 'Link AP hoa don khong hop le.' using errcode = '22023';
    end if;

    select * into v_ap
    from public.supplier_payable_documents
    where id = v_payable_id
    for update;
    if not found then
      raise exception 'Khong tim thay AP %.', v_payable_id using errcode = '22023';
    end if;
    if coalesce(v_ap.supplier_id, '') <> v_supplier_id then
      raise exception 'Tat ca AP duoc link phai cung nha cung cap voi hoa don.' using errcode = '22023';
    end if;
    if not app_private.ap_scope_can_mutate(v_ap.project_id, v_ap.construction_site_id) then
      raise exception 'Nguoi dung khong co quyen doi soat AP.' using errcode = '42501';
    end if;
    if v_project_id is null and v_site_id is null then
      v_project_id := v_ap.project_id;
      v_site_id := v_ap.construction_site_id;
    end if;

    v_allocated_total := round(v_allocated_total + v_allocated, 2);
    v_estimated_total := round(v_estimated_total + greatest(coalesce(v_ap.recognized_amount, 0) - coalesce(v_ap.credit_amount, 0), 0), 2);
  end loop;

  if v_allocated_total <> v_gross_amount then
    raise exception 'Tong phan bo AP phai bang tong tien hoa don.' using errcode = '22023';
  end if;

  v_variance := round(v_gross_amount - v_estimated_total, 2);
  if v_variance <> 0 and v_variance_reason is null then
    raise exception 'Hoa don lech AP phai co ly do chenh lech.' using errcode = '22023';
  end if;

  insert into public.supplier_invoices (
    id, supplier_id, supplier_name_snapshot, invoice_number, invoice_date,
    net_amount, vat_amount, gross_amount, variance_reason, attachments, created_by
  )
  values (
    v_invoice_id, v_supplier_id, v_supplier_name, v_invoice_number, v_invoice_date,
    v_net_amount, v_vat_amount, v_gross_amount, v_variance_reason, v_attachments, p_actor_user_id
  )
  returning * into v_invoice;

  for v_link in select value from jsonb_array_elements(p_links) as link(value)
  loop
    v_payable_id := nullif(coalesce(v_link ->> 'payableDocumentId', v_link ->> 'payable_document_id'), '')::uuid;
    v_allocated := round(coalesce(nullif(coalesce(v_link ->> 'allocatedGrossAmount', v_link ->> 'allocated_gross_amount'), '')::numeric, 0), 2);

    insert into public.supplier_invoice_payable_links (
      invoice_id, payable_document_id, allocated_gross_amount
    ) values (
      v_invoice_id, v_payable_id, v_allocated
    );

    update public.supplier_payable_documents
    set invoice_number = v_invoice_number,
        invoice_date = v_invoice_date,
        metadata = coalesce(metadata, '{}'::jsonb)
          || jsonb_build_object('supplierInvoiceId', v_invoice_id, 'supplierInvoiceNumber', v_invoice_number),
        updated_at = now()
    where id = v_payable_id;
  end loop;

  if v_variance <> 0 then
    select id into v_project_finance_id
    from public.project_finances
    where (v_project_id is not null and project_id = v_project_id)
       or (v_site_id is not null and construction_site_id = v_site_id)
    limit 1;

    v_adjustment_ref := 'supplier_invoice_adjustment:' || v_invoice_id::text;
    v_adjustment_id := 'supplier-invoice-adjustment-' || v_invoice_id::text;

    insert into public.project_transactions (
      id, "projectFinanceId", "constructionSiteId",
      project_id, project_finance_id, construction_site_id,
      type, category, amount, description, date, source,
      "sourceRef", source_ref, contract_cost_item_id,
      cost_classification_status, counterparty_partner_id,
      counterparty_name, attachments, "createdBy", "createdAt"
    )
    values (
      v_adjustment_id,
      coalesce(v_project_finance_id, ''),
      coalesce(v_site_id, ''),
      v_project_id,
      nullif(v_project_finance_id, ''),
      v_site_id,
      'expense',
      'materials',
      v_variance,
      'Chênh lệch hóa đơn NCC ' || v_invoice_number,
      v_invoice_date::text,
      'workflow',
      v_adjustment_ref,
      v_adjustment_ref,
      null,
      'auto',
      null,
      v_supplier_name,
      v_attachments,
      p_actor_user_id::text,
      now()
    )
    on conflict (source_ref) do nothing;

    insert into public.supplier_payable_documents (
      code, source_type, source_id, project_id, construction_site_id,
      supplier_id, supplier_name_snapshot, document_no, document_date, due_date,
      committed_amount, recognized_amount, credit_amount, status, qr_token,
      invoice_number, invoice_date, metadata, created_by
    )
    values (
      'AP-INV-ADJ-' || replace(v_invoice_id::text, '-', ''),
      'supplier_invoice_adjustment',
      v_invoice_id::text,
      v_project_id,
      v_site_id,
      v_supplier_id,
      v_supplier_name,
      v_invoice_number || '-ADJ',
      v_invoice_date,
      null,
      abs(v_variance),
      greatest(v_variance, 0),
      greatest(-v_variance, 0),
      case when v_variance > 0 then 'open' else 'paid' end,
      'ap_invoice_adj_' || replace(v_invoice_id::text, '-', ''),
      v_invoice_number,
      v_invoice_date,
      jsonb_build_object(
        'supplierInvoiceId', v_invoice_id,
        'supplierInvoiceNumber', v_invoice_number,
        'sourceRef', v_adjustment_ref,
        'varianceAmount', v_variance,
        'varianceReason', v_variance_reason
      ),
      p_actor_user_id
    )
    on conflict (source_type, source_id) do nothing;
  end if;

  if to_regclass('public.project_document_links') is not null then
    for v_link in select value from jsonb_array_elements(p_links) as link(value)
    loop
      v_payable_id := nullif(coalesce(v_link ->> 'payableDocumentId', v_link ->> 'payable_document_id'), '')::uuid;
      v_allocated := round(coalesce(nullif(coalesce(v_link ->> 'allocatedGrossAmount', v_link ->> 'allocated_gross_amount'), '')::numeric, 0), 2);
      insert into public.project_document_links (
        source_type, source_id, target_type, target_id, project_id, relation_type, status, metadata
      )
      values (
        'supplier_payable_document', v_payable_id::text,
        'supplier_invoice', v_invoice_id::text,
        v_project_id,
        'invoiced_by',
        'active',
        jsonb_build_object('allocatedGrossAmount', v_allocated)
      )
      on conflict (source_type, source_id, target_type, target_id, relation_type) do update
      set status = excluded.status,
          metadata = coalesce(public.project_document_links.metadata, '{}'::jsonb) || excluded.metadata,
          updated_at = now();
    end loop;

    if v_variance <> 0 then
      insert into public.project_document_links (
        source_type, source_id, target_type, target_id, project_id, relation_type, status, metadata
      )
      values (
        'supplier_invoice', v_invoice_id::text,
        'supplier_payable_document',
        (select id::text from public.supplier_payable_documents
         where source_type = 'supplier_invoice_adjustment' and source_id = v_invoice_id::text limit 1),
        v_project_id,
        'adjusts_ap',
        'active',
        jsonb_build_object('varianceAmount', v_variance)
      )
      on conflict (source_type, source_id, target_type, target_id, relation_type) do update
      set status = excluded.status,
          metadata = coalesce(public.project_document_links.metadata, '{}'::jsonb) || excluded.metadata,
          updated_at = now();

      insert into public.project_document_links (
        source_type, source_id, target_type, target_id, project_id, relation_type, status, metadata
      )
      values (
        'supplier_invoice', v_invoice_id::text,
        'project_transaction', v_adjustment_id,
        v_project_id,
        'adjusts_cost',
        'active',
        jsonb_build_object('varianceAmount', v_variance)
      )
      on conflict (source_type, source_id, target_type, target_id, relation_type) do update
      set status = excluded.status,
          metadata = coalesce(public.project_document_links.metadata, '{}'::jsonb) || excluded.metadata,
          updated_at = now();
    end if;
  end if;

  return v_invoice;
end;
$$;


--
-- Name: record_user_application_membership_audit(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.record_user_application_membership_audit(p_actor_user_id uuid, p_target_user_id uuid, p_event_type text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_event_type not in (
    'APPLICATION_MEMBERSHIP_GRANTED',
    'APPLICATION_MEMBERSHIP_REVOKED'
  ) then
    raise exception 'Unsupported application membership audit event type'
      using errcode = '22023';
  end if;

  insert into public.permission_audit_events (
    actor_user_id,
    target_user_id,
    event_type,
    metadata
  )
  values (
    p_actor_user_id,
    p_target_user_id,
    p_event_type,
    coalesce(p_metadata, '{}'::jsonb)
  );
end;
$$;


--
-- Name: refresh_project_progress_snapshot_impl(text, text, date, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.refresh_project_progress_snapshot_impl(p_project_id text, p_construction_site_id text, p_week_start date, p_snapshot jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_site_id text := nullif(btrim(coalesce(p_construction_site_id, '')), '');
  v_preflight jsonb;
  v_scope_key text;
  v_state public.project_progress_period_states%rowtype;
begin
  v_preflight := app_private.preflight_project_progress_snapshot_impl(
    p_project_id, v_site_id, p_week_start, p_snapshot
  );
  v_scope_key := v_preflight ->> 'scopeKey';

  insert into public.project_progress_period_states (
    scope_key, project_id, construction_site_id, period_type, period_start
  ) values (
    v_scope_key, p_project_id, v_site_id, 'weekly', p_week_start
  ) on conflict (scope_key, period_type, period_start) do nothing;

  select state.*
  into v_state
  from public.project_progress_period_states state
  where state.scope_key = v_scope_key
    and state.period_type = 'weekly'
    and state.period_start = p_week_start
  for update;

  if v_state.is_locked then
    raise exception 'Kỳ tiến độ đã được chốt. Hãy mở chốt trước khi sửa.'
      using errcode = '23514';
  end if;

  return app_private.upsert_project_progress_snapshot(
    v_scope_key, p_project_id, v_site_id, p_week_start, p_snapshot
  );
end;
$$;


--
-- Name: register_request_template_docx_draft(uuid, text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.register_request_template_docx_draft(p_request_template_version_id uuid, p_storage_path text, p_placeholder_schema jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_expected_path text;
  v_print_template public.request_print_templates%rowtype;
begin
  if v_actor is null or not app_private.request_user_can_manage(v_actor) then
    raise exception using errcode = '42501', message = 'REQUEST_TEMPLATE_FORBIDDEN';
  end if;
  if not exists (
    select 1 from public.request_template_versions version
    where version.id = p_request_template_version_id and version.status = 'DRAFT'
  ) then
    raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_DRAFT_VERSION_REQUIRED';
  end if;
  v_expected_path := format('request-template-versions/%s/template.docx', p_request_template_version_id);
  if p_storage_path <> v_expected_path or jsonb_typeof(p_placeholder_schema) <> 'object' then
    raise exception using errcode = '22023', message = 'REQUEST_PRINT_TEMPLATE_INVALID';
  end if;

  delete from public.request_print_templates
  where request_template_version_id = p_request_template_version_id;

  insert into public.request_print_templates(
    request_template_version_id, name, file_name, storage_path,
    validation_status, placeholder_schema
  ) values (
    p_request_template_version_id, 'Mẫu DOCX đề xuất', 'template.docx',
    p_storage_path, 'VALID', p_placeholder_schema
  ) returning * into v_print_template;

  return jsonb_build_object(
    'id', v_print_template.id,
    'storagePath', v_print_template.storage_path,
    'validationStatus', v_print_template.validation_status,
    'placeholderSchema', v_print_template.placeholder_schema
  );
end;
$$;


--
-- Name: remove_project_staff_assignment(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.remove_project_staff_assignment(p_staff_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_staff public.project_staff%rowtype;
begin
  select *
  into v_staff
  from public.project_staff
  where id = p_staff_id;

  if v_staff.id is null then
    raise exception 'Project staff row does not exist: %', p_staff_id
      using errcode = 'P0002';
  end if;

  if not app_private.can_manage_project_staff_assignment(v_staff.project_id, v_staff.construction_site_id) then
    raise exception 'Not allowed to remove this project staff assignment'
      using errcode = '42501';
  end if;

  perform app_private.deactivate_project_staff_scoped_grants(v_staff);

  if v_staff.user_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    delete from public.user_permission_grants
    where user_id = v_staff.user_id::uuid
      and permission_code like 'project.%'
      and scope_type = app_private.project_staff_scope_type(v_staff.construction_site_id)
      and scope_id = app_private.project_staff_scope_id(v_staff.project_id, v_staff.construction_site_id);
  end if;

  delete from public.project_staff
  where id = p_staff_id;

  insert into public.permission_audit_events (
    actor_user_id,
    target_user_id,
    event_type,
    metadata
  )
  values (
    public.current_app_user_id(),
    case when v_staff.user_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then v_staff.user_id::uuid else null end,
    'remove_project_staff_assignment',
    jsonb_build_object(
      'staff_id', p_staff_id,
      'project_id', v_staff.project_id,
      'construction_site_id', v_staff.construction_site_id
    )
  );

  return to_jsonb(v_staff);
end;
$_$;


--
-- Name: renew_safety_assignment_card(uuid, date); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.renew_safety_assignment_card(p_card_id uuid, p_expires_at date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_card public.safety_cards%rowtype;
  v_assignment public.safety_project_assignments%rowtype;
  v_membership public.safety_worker_site_memberships%rowtype;
  v_old_expiry date;
begin
  if p_expires_at is null or p_expires_at <= current_date then
    raise exception 'SAFETY_INVALID_RPC_PAYLOAD: renewed expiry must be in the future'
      using errcode = '22023';
  end if;

  select card.*
  into v_card
  from public.safety_cards card
  where card.id = p_card_id
  for update;

  select assignment.*
  into v_assignment
  from public.safety_project_assignments assignment
  where assignment.id = v_card.assignment_id;

  select membership.*
  into v_membership
  from public.safety_worker_site_memberships membership
  where membership.id = v_assignment.membership_id;

  if v_card.id is null
    or v_card.status <> 'active'
    or v_assignment.assignment_status <> 'active'
    or v_actor is null
    or not app_private.safety_workforce_can_manage(v_membership.project_id, v_membership.construction_site_id)
  then
    raise exception 'SAFETY_SCOPE_MISMATCH: active card is not renewable'
      using errcode = '42501';
  end if;

  v_old_expiry := v_card.expires_at;
  update public.safety_cards card
  set expires_at = p_expires_at,
      updated_at = now()
  where card.id = v_card.id;

  insert into public.safety_audit_logs (
    actor_user_id, action, target_type, target_id, project_id, construction_site_id, metadata
  ) values (
    v_actor::text,
    'card.renew',
    'safety_cards',
    v_card.id,
    v_membership.project_id,
    v_membership.construction_site_id::text,
    jsonb_build_object('oldExpiry', v_old_expiry, 'newExpiry', p_expires_at)
  );

  return app_private.safety_workforce_detail_for_membership(v_membership.id);
end;
$$;


--
-- Name: reopen_project_progress_period_impl(text, text, text, date, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.reopen_project_progress_period_impl(p_project_id text, p_construction_site_id text, p_period_type text, p_period_start date, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := public.current_app_user_id();
  v_site_id text := nullif(btrim(coalesce(p_construction_site_id, '')), '');
  v_scope_key text;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_before public.project_progress_period_states%rowtype;
  v_after public.project_progress_period_states%rowtype;
begin
  v_scope_key := app_private.assert_project_progress_scope_period(
    p_project_id, v_site_id, p_period_type, p_period_start
  );
  perform app_private.assert_project_progress_action(
    v_actor_id, p_project_id, v_site_id, 'confirm'
  );

  if v_reason is null then
    raise exception 'Vui lòng nhập lý do mở chốt.' using errcode = '23514';
  end if;

  select state.* into v_before
  from public.project_progress_period_states state
  where state.scope_key = v_scope_key
    and state.period_type = p_period_type
    and state.period_start = p_period_start
  for update;

  if not found or not v_before.is_locked then
    raise exception 'Kỳ tiến độ chưa được chốt.' using errcode = '23514';
  end if;

  update public.project_progress_period_states state
  set is_locked = false,
      unlocked_by = v_actor_id,
      unlocked_at = now(),
      unlock_reason = v_reason,
      updated_at = now()
  where state.id = v_before.id
  returning state.* into v_after;

  insert into public.permission_audit_events (
    actor_user_id, event_type, before_grants, after_grants, metadata
  ) values (
    v_actor_id,
    'weekly_progress_period_unlocked',
    jsonb_build_array(app_private.project_progress_period_state_json(v_before)),
    jsonb_build_array(app_private.project_progress_period_state_json(v_after)),
    jsonb_build_object(
      'scope_key', v_scope_key,
      'project_id', p_project_id,
      'construction_site_id', v_site_id,
      'period_type', p_period_type,
      'period_start', p_period_start,
      'event', 'unlocked',
      'occurred_at', v_after.unlocked_at,
      'reason', v_reason
    )
  );

  return app_private.project_progress_period_state_json(v_after);
end;
$$;


--
-- Name: replace_project_gantt_task_contract_items_impl(uuid, text, text, text, bigint, uuid[]); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.replace_project_gantt_task_contract_items_impl(p_request_id uuid, p_project_id text, p_construction_site_id text, p_task_id text, p_expected_row_version bigint, p_contract_item_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid;
  v_site_id text := nullif(btrim(coalesce(p_construction_site_id, '')), '');
  v_ids uuid[] := array(select distinct unnest(coalesce(p_contract_item_ids, '{}'::uuid[])) order by 1);
  v_replay jsonb;
  v_result jsonb;
begin
  v_actor_user_id := app_private.assert_project_gantt_action(p_project_id, v_site_id, 'edit');
  v_replay := app_private.begin_project_gantt_command(
    v_actor_user_id, p_request_id, 'replace_project_gantt_task_contract_items',
    md5(jsonb_build_object('projectId', p_project_id, 'constructionSiteId', v_site_id,
      'taskId', p_task_id, 'expectedRowVersion', p_expected_row_version,
      'contractItemIds', to_jsonb(v_ids))::text)
  );
  if v_replay is not null then return v_replay; end if;

  perform task.id from public.project_tasks task where task.id = p_task_id for update;
  if not found or exists (
    select 1 from public.project_tasks task
    where task.id = p_task_id and (
      task.project_id is distinct from p_project_id
      or task.construction_site_id is distinct from v_site_id
    )
  ) then
    raise exception 'GANTT_SCOPE_MISMATCH' using errcode = '23514';
  end if;
  if not exists (
    select 1 from public.project_tasks task
    where task.id = p_task_id and task.row_version = p_expected_row_version
  ) then
    raise exception 'GANTT_STALE_VERSION' using errcode = '40001';
  end if;
  if exists (
    select 1 from unnest(v_ids) contract_item_id
    where not exists (
      select 1 from public.contract_items item
      where item.id = contract_item_id
        and item.project_id = p_project_id
        and item.construction_site_id::text is not distinct from v_site_id
    )
  ) then
    raise exception 'GANTT_SCOPE_MISMATCH' using errcode = '23514';
  end if;

  delete from public.task_contract_items link where link.task_id = p_task_id;
  insert into public.task_contract_items (
    task_id, contract_item_id, project_id, construction_site_id
  )
  select p_task_id, contract_item_id, p_project_id, v_site_id from unnest(v_ids) contract_item_id;

  v_result := jsonb_build_object(
    'ok', true, 'requestId', p_request_id, 'replayed', false,
    'taskId', p_task_id, 'rowVersion', p_expected_row_version,
    'contractItemIds', to_jsonb(v_ids)
  );
  return app_private.finish_project_gantt_command(v_actor_user_id, p_request_id, v_result);
end;
$$;


--
-- Name: replace_project_permission_room_members(text, text, text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.replace_project_permission_room_members(p_project_id text, p_construction_site_id text, p_room_code text, p_members jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_scope_site_id text := nullif(p_construction_site_id, '');
  v_effective_members jsonb;
begin
  if jsonb_typeof(coalesce(p_members, 'null'::jsonb)) <> 'array' then
    raise exception 'Room members must be a JSON array' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_members) item(project_staff_id uuid, action_codes jsonb)
    cross join lateral jsonb_array_elements_text(coalesce(item.action_codes, '[]'::jsonb)) code(action_code)
    join app_private.project_permission_room_action_bindings binding
      on binding.room_code = p_room_code and binding.action_code = code.action_code
    where binding.enforcement_status = 'audit_only'
      and not exists (
        select 1
        from public.project_permission_room_members member
        join public.project_permission_room_member_actions action on action.room_member_id = member.id
        where member.project_id = p_project_id
          and member.construction_site_id is not distinct from v_scope_site_id
          and member.room_code = p_room_code
          and member.project_staff_id = item.project_staff_id
          and member.is_active and action.is_active
          and action.action_code = code.action_code
      )
  ) then
    raise exception 'Action chưa áp dụng đầy đủ không thể được cấp mới.' using errcode = '23514';
  end if;

  with payload as (
    select item.project_staff_id,
      coalesce(array_agg(distinct code.action_code) filter (
        where coalesce(binding.enforcement_status, 'audit_only') <> 'audit_only'
      ), '{}'::text[]) action_codes
    from jsonb_to_recordset(p_members) item(project_staff_id uuid, action_codes jsonb)
    left join lateral jsonb_array_elements_text(coalesce(item.action_codes, '[]'::jsonb)) code(action_code) on true
    left join app_private.project_permission_room_action_bindings binding
      on binding.room_code = p_room_code and binding.action_code = code.action_code
    group by item.project_staff_id
  ), locked as (
    select member.project_staff_id, array_agg(action.action_code order by action.action_code) action_codes
    from public.project_permission_room_members member
    join public.project_permission_room_member_actions action
      on action.room_member_id = member.id and action.is_active
    join app_private.project_permission_room_action_bindings binding
      on binding.room_code = member.room_code
      and binding.action_code = action.action_code
      and binding.enforcement_status = 'audit_only'
    where member.project_id = p_project_id
      and member.construction_site_id is not distinct from v_scope_site_id
      and member.room_code = p_room_code
      and member.is_active
    group by member.project_staff_id
  ), combined as (
    select coalesce(payload.project_staff_id, locked.project_staff_id) project_staff_id,
      array(select distinct code from unnest(
        coalesce(payload.action_codes, '{}'::text[]) || coalesce(locked.action_codes, '{}'::text[])
      ) code order by code) action_codes
    from payload full join locked using (project_staff_id)
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'project_staff_id', project_staff_id,
    'action_codes', to_jsonb(action_codes)
  ) order by project_staff_id), '[]'::jsonb)
  into v_effective_members
  from combined
  where cardinality(action_codes) > 0;

  if exists (
    select 1
    from jsonb_to_recordset(v_effective_members) item(project_staff_id uuid, action_codes jsonb)
    cross join lateral jsonb_array_elements_text(item.action_codes) code(action_code)
    join app_private.project_permission_room_action_bindings binding
      on binding.room_code = p_room_code and binding.action_code = code.action_code
    cross join lateral unnest(binding.prerequisite_action_codes) required(action_code)
    where not (item.action_codes ? required.action_code)
  ) then
    raise exception 'Quyền nghiệp vụ phải đi cùng quyền tiên quyết trong Room.' using errcode = '23514';
  end if;

  perform app_private.replace_project_permission_room_members_room_cutover_legacy(
    p_project_id, v_scope_site_id, p_room_code, v_effective_members
  );
end;
$$;


--
-- Name: replace_project_permission_room_members_room_cutover_legacy(text, text, text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.replace_project_permission_room_members_room_cutover_legacy(p_project_id text, p_construction_site_id text, p_room_code text, p_members jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid;
  v_scope_site_id text := nullif(p_construction_site_id, '');
  v_allowed_actions text[];
  v_required_actions text[];
  v_before jsonb;
  v_after jsonb;
begin
  v_actor_user_id := app_private.assert_project_permission_room_admin();

  if jsonb_typeof(coalesce(p_members, 'null'::jsonb)) <> 'array' then
    raise exception 'Room members must be a JSON array' using errcode = '22023';
  end if;

  select room.allowed_actions, room.required_actions
  into v_allowed_actions, v_required_actions
  from public.project_permission_rooms room
  where room.code = p_room_code and room.is_active;

  if v_allowed_actions is null then
    raise exception 'Unknown active permission Room: %', p_room_code using errcode = 'P0002';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_members) item(project_staff_id uuid, action_codes jsonb)
    where item.project_staff_id is null
      or jsonb_typeof(coalesce(item.action_codes, 'null'::jsonb)) <> 'array'
  ) then
    raise exception 'Each Room member requires project_staff_id and action_codes[]' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_members) item(project_staff_id uuid, action_codes jsonb)
    cross join lateral jsonb_array_elements_text(item.action_codes) code(action_code)
    where not (code.action_code = any(v_allowed_actions))
  ) then
    raise exception 'Payload contains an action not allowed in this Room' using errcode = '23514';
  end if;

  if exists (
    select 1 from jsonb_to_recordset(p_members) item(project_staff_id uuid, action_codes jsonb)
    group by item.project_staff_id having count(*) > 1
  ) then
    raise exception 'Each project staff member can appear once in a Room payload' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_members) item(project_staff_id uuid, action_codes jsonb)
    cross join lateral (
      select code.action_code
      from jsonb_array_elements_text(item.action_codes) code(action_code)
      group by code.action_code having count(*) > 1
    ) duplicated
  ) then
    raise exception 'A Room action can only be assigned once per staff member' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_members) item(project_staff_id uuid, action_codes jsonb)
    left join public.project_staff staff on staff.id = item.project_staff_id
    left join public.users user_row on user_row.id::text = staff.user_id
    where staff.id is null
      or staff.project_id is distinct from p_project_id
      or staff.end_date is not null
      or not coalesce(user_row.is_active, true)
      or (v_scope_site_id is not null and staff.construction_site_id is not null
          and staff.construction_site_id <> v_scope_site_id)
  ) then
    raise exception 'Room members must be active staff in the selected project scope' using errcode = '23503';
  end if;

  if p_room_code = 'material_po' and exists (
    select 1
    from jsonb_to_recordset(p_members) item(project_staff_id uuid, action_codes jsonb)
    where exists (
      select 1 from jsonb_array_elements_text(item.action_codes) code(action_code)
      where code.action_code <> 'view'
    )
    and not (item.action_codes ? 'view')
  ) then
    raise exception 'Quyền nghiệp vụ PO phải đi cùng quyền Xem trong Room.' using errcode = '23514';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'project_staff_id', member.project_staff_id,
    'action_codes', coalesce(actions.action_codes, '[]'::jsonb)
  ) order by member.project_staff_id), '[]'::jsonb)
  into v_before
  from public.project_permission_room_members member
  left join lateral (
    select jsonb_agg(action.action_code order by action.action_code) action_codes
    from public.project_permission_room_member_actions action
    where action.room_member_id = member.id and action.is_active
  ) actions on true
  where member.project_id = p_project_id
    and member.construction_site_id is not distinct from v_scope_site_id
    and member.room_code = p_room_code
    and member.is_active;

  insert into public.project_permission_room_members (
    project_id, construction_site_id, room_code, project_staff_id,
    is_active, created_by, updated_at
  )
  select p_project_id, v_scope_site_id, p_room_code, item.project_staff_id,
         true, v_actor_user_id, now()
  from jsonb_to_recordset(p_members) item(project_staff_id uuid, action_codes jsonb)
  on conflict (project_id, (coalesce(construction_site_id, '')), room_code, project_staff_id)
  do update set is_active = true, updated_at = now();

  update public.project_permission_room_members member
  set is_active = false, updated_at = now()
  where member.project_id = p_project_id
    and member.construction_site_id is not distinct from v_scope_site_id
    and member.room_code = p_room_code
    and member.is_active
    and not exists (
      select 1 from jsonb_to_recordset(p_members) item(project_staff_id uuid, action_codes jsonb)
      where item.project_staff_id = member.project_staff_id
    );

  update public.project_permission_room_member_actions action
  set is_active = false, updated_at = now()
  from public.project_permission_room_members member
  where member.id = action.room_member_id
    and member.project_id = p_project_id
    and member.construction_site_id is not distinct from v_scope_site_id
    and member.room_code = p_room_code
    and not exists (
      select 1
      from jsonb_to_recordset(p_members) item(project_staff_id uuid, action_codes jsonb)
      cross join lateral jsonb_array_elements_text(item.action_codes) code(action_code)
      where item.project_staff_id = member.project_staff_id
        and code.action_code = action.action_code
    );

  insert into public.project_permission_room_member_actions (
    room_member_id, action_code, is_active, granted_by, granted_at, updated_at, grant_source
  )
  select member.id, code.action_code, true, v_actor_user_id, now(), now(), 'manual_room'
  from jsonb_to_recordset(p_members) item(project_staff_id uuid, action_codes jsonb)
  join public.project_permission_room_members member
    on member.project_id = p_project_id
    and member.construction_site_id is not distinct from v_scope_site_id
    and member.room_code = p_room_code
    and member.project_staff_id = item.project_staff_id
  cross join lateral jsonb_array_elements_text(item.action_codes) code(action_code)
  on conflict (room_member_id, action_code) do update
  set is_active = true,
      granted_by = case when public.project_permission_room_member_actions.is_active
                        then public.project_permission_room_member_actions.granted_by
                        else excluded.granted_by end,
      granted_at = case when public.project_permission_room_member_actions.is_active
                        then public.project_permission_room_member_actions.granted_at
                        else excluded.granted_at end,
      grant_source = case when public.project_permission_room_member_actions.is_active
                          then public.project_permission_room_member_actions.grant_source
                          else 'manual_room' end,
      updated_at = now();

  if exists (
    select 1 from unnest(v_required_actions) required(action_code)
    where not exists (
      select 1
      from public.project_permission_room_members member
      join public.project_permission_room_member_actions action on action.room_member_id = member.id
      where member.project_id = p_project_id
        and member.construction_site_id is not distinct from v_scope_site_id
        and member.room_code = p_room_code
        and member.is_active and action.is_active
        and action.action_code = required.action_code
    )
  ) then
    raise exception 'Required workflow action has no active Room recipient' using errcode = '23514';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'project_staff_id', item.project_staff_id, 'action_codes', item.action_codes
  ) order by item.project_staff_id), '[]'::jsonb)
  into v_after
  from jsonb_to_recordset(p_members) item(project_staff_id uuid, action_codes jsonb);

  insert into public.permission_audit_events (
    actor_user_id, event_type, before_grants, after_grants, metadata
  ) values (
    v_actor_user_id, 'replace_project_permission_room_members', v_before, v_after,
    jsonb_build_object('project_id', p_project_id,
      'construction_site_id', v_scope_site_id, 'room_code', p_room_code)
  );
end;
$$;


--
-- Name: replace_project_staff_permission_grants(uuid, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.replace_project_staff_permission_grants(p_staff_id uuid, p_grants jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_staff record;
  v_actor_user_id uuid := public.current_app_user_id();
  v_target_user_id uuid;
  v_scope_type text;
  v_scope_id text;
  v_before jsonb;
  v_after jsonb := coalesce(p_grants, '[]'::jsonb);
begin
  select ps.*
  into v_staff
  from public.project_staff ps
  where ps.id = p_staff_id;

  if v_staff.id is null then
    raise exception 'Project staff row does not exist'
      using errcode = '23503';
  end if;

  if v_staff.user_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    raise exception 'Project staff user_id is not a UUID: %', v_staff.user_id
      using errcode = '22P02';
  end if;

  v_target_user_id := v_staff.user_id::uuid;
  v_scope_type := case when nullif(v_staff.construction_site_id, '') is not null then 'construction_site' else 'project' end;
  v_scope_id := coalesce(nullif(v_staff.construction_site_id, ''), nullif(v_staff.project_id, ''));

  if v_scope_id is null then
    raise exception 'Project staff row has no project or construction site scope'
      using errcode = '23502';
  end if;

  if not (
    public.is_admin()
    or public.is_module_admin('DA')
    or app_private.project_has_permission_v2(v_staff.project_id, v_staff.construction_site_id, 'project.org.grant_permissions', v_actor_user_id)
    or app_private.project_has_permission_v2(v_staff.project_id, v_staff.construction_site_id, 'project.org.manage', v_actor_user_id)
  ) then
    raise exception 'Not allowed to manage project staff permissions'
      using errcode = '42501';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(v_after) as grant_row(
      permission_code text,
      scope_type text,
      scope_id text,
      is_active boolean,
      expires_at timestamptz
    )
    left join public.permission_actions pa on pa.permission_code = grant_row.permission_code
    where coalesce(grant_row.is_active, true)
      and (
        grant_row.permission_code is null
        or grant_row.permission_code not like 'project.%'
        or pa.permission_code is null
      )
  ) then
    raise exception 'All grants must be registered project.* permission codes'
      using errcode = '23503';
  end if;

  select coalesce(jsonb_agg(to_jsonb(g) order by g.permission_code), '[]'::jsonb)
  into v_before
  from public.user_permission_grants g
  where g.user_id = v_target_user_id
    and g.permission_code like 'project.%'
    and g.scope_type = v_scope_type
    and g.scope_id = v_scope_id;

  delete from public.user_permission_grants g
  where g.user_id = v_target_user_id
    and g.permission_code like 'project.%'
    and g.scope_type = v_scope_type
    and g.scope_id = v_scope_id;

  insert into public.user_permission_grants (
    user_id,
    permission_code,
    scope_type,
    scope_id,
    is_active,
    granted_by,
    granted_at,
    expires_at
  )
  select
    v_target_user_id,
    grant_row.permission_code,
    v_scope_type,
    v_scope_id,
    coalesce(grant_row.is_active, true),
    v_actor_user_id,
    now(),
    grant_row.expires_at
  from jsonb_to_recordset(v_after) as grant_row(
    permission_code text,
    scope_type text,
    scope_id text,
    is_active boolean,
    expires_at timestamptz
  )
  where coalesce(grant_row.is_active, true)
  on conflict (user_id, permission_code, scope_type, scope_id) do update
  set is_active = excluded.is_active,
      granted_by = excluded.granted_by,
      granted_at = excluded.granted_at,
      expires_at = excluded.expires_at,
      updated_at = now();

  delete from public.project_staff_permissions
  where staff_id = p_staff_id;

  insert into public.project_staff_permissions (
    staff_id,
    permission_type_id,
    is_active,
    granted_by,
    granted_at
  )
  with active_grants as (
    select g.permission_code, pa.action
    from public.user_permission_grants g
    join public.permission_actions pa on pa.permission_code = g.permission_code
    where g.user_id = v_target_user_id
      and g.permission_code like 'project.%'
      and g.scope_type = v_scope_type
      and g.scope_id = v_scope_id
      and coalesce(g.is_active, false)
      and (g.expires_at is null or g.expires_at > now())
  ),
  legacy_codes as (
    select distinct legacy_code
    from active_grants
    cross join lateral (
      values
        (case when action = 'view' then 'view' end),
        (case when action in ('create','edit','edit_own','edit_all') then 'edit' end),
        (case when action in ('delete','delete_own','delete_all') then 'delete' end),
        (case when action = 'submit' then 'submit' end),
        (case when action in ('verify','return') then 'verify' end),
        (case when action in ('confirm','mark_paid') then 'confirm' end),
        (case when action = 'approve' then 'approve' end),
        (case when permission_code = 'project.material_request.view_available_stock' then 'view_available_stock' end)
    ) as mapped(legacy_code)
    where legacy_code is not null
  )
  select
    p_staff_id,
    ppt.id,
    true,
    v_actor_user_id::text,
    now()
  from legacy_codes lc
  join public.project_permission_types ppt on ppt.code = lc.legacy_code
  where coalesce(ppt.is_active, true)
  on conflict (staff_id, permission_type_id) do update
  set is_active = true,
      granted_by = excluded.granted_by,
      granted_at = excluded.granted_at;

  insert into public.permission_audit_events (
    actor_user_id,
    target_user_id,
    event_type,
    before_grants,
    after_grants,
    metadata
  )
  values (
    v_actor_user_id,
    v_target_user_id,
    'replace_project_staff_permission_grants',
    v_before,
    (
      select coalesce(jsonb_agg(to_jsonb(g) order by g.permission_code), '[]'::jsonb)
      from public.user_permission_grants g
      where g.user_id = v_target_user_id
        and g.permission_code like 'project.%'
        and g.scope_type = v_scope_type
        and g.scope_id = v_scope_id
    ),
    jsonb_build_object(
      'source', 'phase2_project_pbac_v2_foundation',
      'staff_id', p_staff_id,
      'scope_type', v_scope_type,
      'scope_id', v_scope_id
    )
  );
end;
$_$;


--
-- Name: replace_user_permission_grants_v2_impl(uuid, jsonb, text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.replace_user_permission_grants_v2_impl(p_user_id uuid, p_grants jsonb, p_reason text, p_warning_acceptances jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid;
  v_target public.users%rowtype;
  v_grants jsonb := coalesce(p_grants, '[]'::jsonb);
  v_reason text := btrim(coalesce(p_reason, ''));
  v_before jsonb := '[]'::jsonb;
  v_after jsonb := '[]'::jsonb;
  v_decision jsonb;
  v_command_id uuid := gen_random_uuid();
begin
  v_actor_user_id := app_private.assert_authorization_permission(
    'system.authorization.manage_grants'
  );

  if jsonb_typeof(v_grants) <> 'array' then
    raise exception 'Permission grants payload must be an array'
      using errcode = '22023';
  end if;

  select *
  into v_target
  from public.users
  where id = p_user_id
  for update;

  if v_target.id is null
    or not v_target.is_active
    or v_target.account_status <> 'ACTIVE'
  then
    raise exception 'Active target user required'
      using errcode = '23514';
  end if;

  v_decision := app_private.evaluate_direct_grant_replacement_impl(
    v_actor_user_id,
    p_user_id,
    v_grants
  );

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'permissionCode', grant_row.permission_code,
        'scopeType', grant_row.scope_type,
        'scopeId', grant_row.scope_id,
        'expiresAt', grant_row.expires_at
      )
      order by grant_row.permission_code, grant_row.scope_type, grant_row.scope_id
    ),
    '[]'::jsonb
  )
  into v_before
  from public.user_permission_grants grant_row
  where grant_row.user_id = p_user_id
    and grant_row.is_active;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'permissionCode', normalized.permission_code,
        'scopeType', normalized.scope_type,
        'scopeId', normalized.scope_id,
        'expiresAt', normalized.expires_at
      )
      order by normalized.permission_code, normalized.scope_type, normalized.scope_id
    ),
    '[]'::jsonb
  )
  into v_after
  from (
    select
      grant_row.permission_code,
      coalesce(nullif(grant_row.scope_type, ''), 'global') as scope_type,
      coalesce(nullif(grant_row.scope_id, ''), '*') as scope_id,
      grant_row.expires_at
    from jsonb_to_recordset(v_grants) grant_row(
      permission_code text,
      scope_type text,
      scope_id text,
      is_active boolean,
      expires_at timestamptz
    )
    where coalesce(grant_row.is_active, true)
  ) normalized;

  if v_before is not distinct from v_after then
    return v_after;
  end if;

  if char_length(v_reason) < 10 then
    raise exception 'Direct permission grant change reason required'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(v_grants) grant_row(
      permission_code text,
      is_active boolean
    )
    join public.permission_actions action_row
      on action_row.permission_code = grant_row.permission_code
     and action_row.is_active
    where coalesce(grant_row.is_active, true)
      and action_row.risk_level in ('important', 'sensitive')
      and char_length(v_reason) < 10
  ) then
    raise exception 'Important direct permission grant requires a reason'
      using errcode = '23514';
  end if;

  perform app_private.assert_and_record_sod_warnings(
    v_decision,
    p_warning_acceptances,
    'REPLACE_DIRECT_GRANTS',
    v_command_id,
    v_actor_user_id,
    p_user_id
  );

  update public.user_permission_grants existing
  set is_active = false,
      revoked_at = coalesce(existing.revoked_at, now()),
      revoked_by = coalesce(existing.revoked_by, v_actor_user_id),
      revoked_reason = coalesce(existing.revoked_reason, v_reason),
      updated_at = now()
  where existing.user_id = p_user_id
    and existing.is_active
    and not exists (
      select 1
      from jsonb_to_recordset(v_grants) desired(
        permission_code text,
        scope_type text,
        scope_id text,
        is_active boolean,
        expires_at timestamptz
      )
      where coalesce(desired.is_active, true)
        and desired.permission_code = existing.permission_code
        and coalesce(nullif(desired.scope_type, ''), 'global') = existing.scope_type
        and coalesce(nullif(desired.scope_id, ''), '*') = existing.scope_id
    );

  insert into public.user_permission_grants (
    user_id,
    permission_code,
    scope_type,
    scope_id,
    is_active,
    granted_by,
    granted_at,
    expires_at,
    grant_reason,
    revoked_at,
    revoked_by,
    revoked_reason
  )
  select
    p_user_id,
    desired.permission_code,
    coalesce(nullif(desired.scope_type, ''), 'global'),
    coalesce(nullif(desired.scope_id, ''), '*'),
    true,
    v_actor_user_id,
    now(),
    desired.expires_at,
    nullif(v_reason, ''),
    null,
    null,
    null
  from jsonb_to_recordset(v_grants) desired(
    permission_code text,
    scope_type text,
    scope_id text,
    is_active boolean,
    expires_at timestamptz
  )
  where coalesce(desired.is_active, true)
  on conflict (user_id, permission_code, scope_type, scope_id) do update
  set is_active = true,
      granted_by = excluded.granted_by,
      granted_at = excluded.granted_at,
      expires_at = excluded.expires_at,
      grant_reason = excluded.grant_reason,
      revoked_at = null,
      revoked_by = null,
      revoked_reason = null,
      updated_at = now();

  insert into public.permission_audit_events (
    actor_user_id,
    target_user_id,
    event_type,
    before_grants,
    after_grants,
    metadata
  )
  values (
    v_actor_user_id,
    p_user_id,
    'direct_permission_grants_changed',
    v_before,
    v_after,
    jsonb_build_object(
      'commandId', v_command_id,
      'reason', v_reason,
      'decision', v_decision
    )
  );

  if app_private.permission_hardening_flag('legacy_projection_enabled') then
    perform app_private.sync_legacy_permission_projection(p_user_id);
  end if;

  return v_after;
end;
$$;


--
-- Name: request_action_current_blocks(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.request_action_current_blocks(p_request_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(block_key order by min_sort, block_key), '[]'::jsonb)
  from (
    select assignment.metadata ->> 'requestBlockKey' as block_key,
           min(assignment.assigned_at) as min_sort
    from public.workflow_step_assignments assignment
    join public.request_instances request_instance
      on request_instance.workflow_subject_id = assignment.workflow_subject_id
    where request_instance.id = p_request_id
      and assignment.status = 'PENDING'
      and assignment.metadata ->> 'requestBlockKey' is not null
    group by assignment.metadata ->> 'requestBlockKey'
  ) active_blocks;
$$;


--
-- Name: request_action_is_admin(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.request_action_is_admin(p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.is_admin()
    or public.is_module_admin('WF')
    or app_private.request_user_can_manage(p_user_id);
$$;


--
-- Name: request_detail_payload(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.request_detail_payload(p_request_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when p_user_id is distinct from public.current_app_user_id()
      or not app_private.request_instance_can_select(r.id, p_user_id) then null
    else app_private.request_list_item(r.id, p_user_id)
      || jsonb_build_object(
        'description', coalesce(r.description, ''),
        'templateVersionId', r.request_template_version_id,
        'templateVersionNumber', coalesce(version.version_number, 0),
        'flowMode', coalesce(r.approval_config_snapshot ->> 'flowMode', version.flow_mode),
        'completionPolicy', coalesce(r.approval_config_snapshot ->> 'completionPolicy', version.completion_policy),
        'formSchema', case when jsonb_typeof(r.form_schema_snapshot) = 'array'
          then r.form_schema_snapshot else '[]'::jsonb end,
        'formData', case when jsonb_typeof(r.form_data) = 'object'
          then r.form_data else '{}'::jsonb end,
        'approvalBlocks', coalesce((
          select jsonb_agg(
            jsonb_build_object(
              'key', block.block_key,
              'name', block.name,
              'sortOrder', block.sort_order,
              'status', case
                when exists (
                  select 1 from public.workflow_step_assignments returned_assignment
                  where returned_assignment.workflow_subject_id = r.workflow_subject_id
                    and returned_assignment.metadata ->> 'requestBlockKey' = block.block_key
                    and returned_assignment.status = 'RETURNED'
                ) then 'RETURNED'
                when exists (
                  select 1 from public.workflow_step_assignments pending_assignment
                  where pending_assignment.workflow_subject_id = r.workflow_subject_id
                    and pending_assignment.metadata ->> 'requestBlockKey' = block.block_key
                    and pending_assignment.status = 'PENDING'
                ) then 'ACTIVE'
                when exists (
                  select 1 from public.workflow_step_assignments completed_assignment
                  where completed_assignment.workflow_subject_id = r.workflow_subject_id
                    and completed_assignment.metadata ->> 'requestBlockKey' = block.block_key
                ) and not exists (
                  select 1 from public.workflow_step_assignments cancelled_assignment
                  where cancelled_assignment.workflow_subject_id = r.workflow_subject_id
                    and cancelled_assignment.metadata ->> 'requestBlockKey' = block.block_key
                    and cancelled_assignment.status = 'CANCELLED'
                ) then 'COMPLETED'
                when exists (
                  select 1 from public.workflow_step_assignments cancelled_assignment
                  where cancelled_assignment.workflow_subject_id = r.workflow_subject_id
                    and cancelled_assignment.metadata ->> 'requestBlockKey' = block.block_key
                    and cancelled_assignment.status = 'CANCELLED'
                ) then 'CANCELLED'
                else 'NOT_ACTIVE'
              end,
              'slaHours', block.sla_hours,
              'assignments', coalesce((
                select jsonb_agg(
                  jsonb_build_object(
                    'id', assignment.id,
                    'roundId', assignment.assignment_round_id,
                    'approver', app_private.request_user_snapshot(assignment.assignee_user_id),
                    'status', assignment.status,
                    'actedAt', assignment.acted_at,
                    'comment', assignment.action_comment
                  ) order by assignment.assigned_at, assignment.id
                )
                from public.workflow_step_assignments assignment
                where assignment.workflow_subject_id = r.workflow_subject_id
                  and assignment.metadata ->> 'requestBlockKey' = block.block_key
              ), '[]'::jsonb)
            ) order by block.sort_order, block.block_key
          )
          from public.request_approval_blocks block
          where block.request_template_version_id = r.request_template_version_id
        ), '[]'::jsonb),
        'watcherIds', coalesce((
          select jsonb_agg(participant.user_id order by participant.user_id)
          from public.workflow_participants participant
          where participant.workflow_subject_id = r.workflow_subject_id
            and participant.role = 'WATCHER'
            and coalesce(participant.is_active, true)
        ), '[]'::jsonb),
        'timeline', coalesce((
          select jsonb_agg(
            jsonb_build_object(
              'id', log.id,
              'eventType', log.action::text,
              'actor', app_private.request_user_snapshot(log.acted_by),
              'comment', log.comment,
              'createdAt', log.created_at
            ) order by log.created_at, log.id
          )
          from public.workflow_instance_logs log
          where log.instance_id = r.workflow_instance_id
        ), '[]'::jsonb),
        'printConfig', jsonb_build_object(
          'browserPrintEnabled', coalesce((r.print_config_snapshot ->> 'browserPrintEnabled')::boolean, true),
          'docxStoragePath', (
            select print_template.storage_path
            from public.request_print_templates print_template
            where print_template.request_template_version_id = r.request_template_version_id
              and print_template.validation_status = 'VALID'
            order by print_template.updated_at desc, print_template.id desc
            limit 1
          )
        ),
        'capabilities', jsonb_build_object(
          'canApprove', r.status = 'PENDING' and exists (
            select 1 from public.workflow_step_assignments assignment
            where assignment.workflow_subject_id = r.workflow_subject_id
              and assignment.assignee_user_id = p_user_id
              and assignment.status = 'PENDING'
          ),
          'canReject', r.status = 'PENDING' and exists (
            select 1 from public.workflow_step_assignments assignment
            where assignment.workflow_subject_id = r.workflow_subject_id
              and assignment.assignee_user_id = p_user_id
              and assignment.status = 'PENDING'
          ),
          'canReturn', r.status = 'PENDING' and exists (
            select 1 from public.workflow_step_assignments assignment
            where assignment.workflow_subject_id = r.workflow_subject_id
              and assignment.assignee_user_id = p_user_id
              and assignment.status = 'PENDING'
          ),
          'canResubmit', r.created_by = p_user_id and r.status = 'RETURNED',
          'canCancel', (r.created_by = p_user_id or app_private.request_action_is_admin(p_user_id))
            and r.status in ('PENDING', 'RETURNED'),
          'canReassign', app_private.request_user_can_manage(p_user_id)
            and r.status = 'PENDING'
            and exists (
              select 1 from public.workflow_step_assignments assignment
              where assignment.workflow_subject_id = r.workflow_subject_id
                and assignment.status = 'PENDING'
            ),
          'canPrint', coalesce((r.print_config_snapshot ->> 'browserPrintEnabled')::boolean, true)
            or exists (
              select 1
              from public.request_print_templates print_template
              where print_template.request_template_version_id = r.request_template_version_id
                and print_template.validation_status = 'VALID'
            )
        )
      )
  end
  from public.request_instances r
  left join public.request_template_versions version
    on version.id = r.request_template_version_id
  where r.id = p_request_id;
$$;


--
-- Name: request_instance_can_select(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.request_instance_can_select(p_request_instance_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.users app_user
    where app_user.id = p_user_id
      and coalesce(app_user.is_active, true)
      and coalesce(app_user.account_status, 'ACTIVE') = 'ACTIVE'
  )
  and (
    app_private.request_user_can_manage(p_user_id)
    or exists (
      select 1
      from public.request_instances request_instance
      where request_instance.id = p_request_instance_id
        and (
          request_instance.created_by = p_user_id
          or exists (
            select 1
            from public.workflow_participants participant
            where participant.workflow_subject_id =
              request_instance.workflow_subject_id
              and participant.user_id = p_user_id
              and participant.role in ('ASSIGNEE', 'WATCHER')
          )
          or exists (
            select 1
            from public.workflow_step_assignments assignment
            where assignment.workflow_subject_id =
              request_instance.workflow_subject_id
              and assignment.assignee_user_id = p_user_id
          )
          or exists (
            select 1
            from public.request_template_watchers watcher
            where watcher.request_template_version_id =
              request_instance.request_template_version_id
              and watcher.user_id = p_user_id
          )
          or (
            request_instance.workflow_subject_id is null
            and request_instance.request_template_version_id is null
            and (
              request_instance.assigned_to::text = p_user_id::text
              or request_instance.approver_id::text = p_user_id::text
              or exists (
                select 1
                from jsonb_array_elements(
                  case
                    when jsonb_typeof(request_instance.approvers) = 'array'
                    then request_instance.approvers
                    else '[]'::jsonb
                  end
                ) legacy_approver
                where legacy_approver ->> 'userId' = p_user_id::text
              )
            )
          )
        )
    )
  );
$$;


--
-- Name: request_list_item(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.request_list_item(p_request_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when p_user_id is distinct from public.current_app_user_id()
      or not app_private.request_instance_can_select(r.id, p_user_id) then null
    else jsonb_build_object(
      'id', r.id,
      'code', r.code,
      'title', r.title,
      'status', r.status,
      'templateId', r.request_template_id,
      'templateName', coalesce(template.name, ''),
      'creator', app_private.request_user_snapshot(r.created_by),
      'activeApprovers', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id', app_user.id,
            'name', coalesce(nullif(app_user.name, ''), app_user.username, app_user.email, app_user.id::text),
            'avatarUrl', app_user.avatar,
            'position', null,
            'assignmentStatus', assignment.status
          ) order by assignment.assigned_at, assignment.id
        )
        from public.workflow_step_assignments assignment
        join public.users app_user on app_user.id = assignment.assignee_user_id
        where assignment.workflow_subject_id = r.workflow_subject_id
          and assignment.status = 'PENDING'
      ), '[]'::jsonb),
      'dueAt', r.due_at,
      'createdAt', r.created_at,
      'updatedAt', r.updated_at
    )
  end
  from public.request_instances r
  left join public.request_templates template on template.id = r.request_template_id
  where r.id = p_request_id;
$$;


--
-- Name: request_list_payload(jsonb, integer); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.request_list_payload(p_filters jsonb, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_view text := upper(coalesce(nullif(trim(p_filters ->> 'view'), ''), 'ALL'));
  v_status text := upper(nullif(trim(p_filters ->> 'status'), ''));
  v_search text := nullif(trim(p_filters ->> 'search'), '');
  v_template_id text := nullif(trim(p_filters ->> 'templateId'), '');
  v_overdue boolean;
  v_cursor_created_at timestamptz;
  v_cursor_id uuid;
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 100);
  v_items jsonb := '[]'::jsonb;
  v_next_cursor jsonb := null;
begin
  if v_actor is null then
    return jsonb_build_object('items', '[]'::jsonb);
  end if;

  if v_view not in ('ALL', 'ASSIGNED_TO_ME', 'CREATED_BY_ME', 'WATCHING') then
    raise exception using errcode = '22023', message = 'REQUEST_QUERY_FILTER_INVALID';
  end if;

  if v_status is not null and v_status not in ('PENDING', 'RETURNED', 'APPROVED', 'REJECTED', 'CANCELLED') then
    raise exception using errcode = '22023', message = 'REQUEST_QUERY_FILTER_INVALID';
  end if;

  if (
    nullif(trim(p_filters ->> 'cursorCreatedAt'), '') is null
  ) <> (
    nullif(trim(p_filters ->> 'cursorId'), '') is null
  ) then
    raise exception using errcode = '22023', message = 'REQUEST_QUERY_CURSOR_INVALID';
  end if;

  if nullif(trim(p_filters ->> 'cursorCreatedAt'), '') is not null then
    v_cursor_created_at := (p_filters ->> 'cursorCreatedAt')::timestamptz;
    v_cursor_id := nullif(trim(p_filters ->> 'cursorId'), '')::uuid;
  end if;

  if p_filters ? 'overdue' then
    v_overdue := (p_filters ->> 'overdue')::boolean;
  end if;

  with candidates as (
    select r.id, r.created_at
    from public.request_instances r
    where app_private.request_instance_can_select(r.id, v_actor)
      and (
        v_view = 'ALL'
        or (v_view = 'CREATED_BY_ME' and r.created_by = v_actor)
        or (v_view = 'ASSIGNED_TO_ME' and exists (
          select 1 from public.workflow_step_assignments assignment
          where assignment.workflow_subject_id = r.workflow_subject_id
            and assignment.assignee_user_id = v_actor
            and assignment.status = 'PENDING'
        ))
        or (v_view = 'WATCHING' and (
          exists (
            select 1 from public.workflow_participants participant
            where participant.workflow_subject_id = r.workflow_subject_id
              and participant.user_id = v_actor
              and participant.role = 'WATCHER'
              and coalesce(participant.is_active, true)
          )
          or exists (
            select 1 from public.request_template_watchers watcher
            where watcher.request_template_version_id = r.request_template_version_id
              and watcher.user_id = v_actor
          )
        ))
      )
      and (v_status is null or r.status = v_status)
      and (v_template_id is null or r.request_template_id::text = v_template_id)
      and (v_search is null or r.code ilike '%' || v_search || '%' or r.title ilike '%' || v_search || '%')
      and (
        v_overdue is not true
        or r.due_at < now()
        or exists (
          select 1 from public.workflow_step_assignments assignment
          where assignment.workflow_subject_id = r.workflow_subject_id
            and assignment.status = 'PENDING'
            and assignment.due_at < now()
        )
      )
      and (
        v_cursor_created_at is null
        or (r.created_at, r.id) < (v_cursor_created_at, v_cursor_id)
      )
    order by r.created_at desc, r.id desc
    limit v_limit + 1
  ), numbered as (
    select candidate.id, candidate.created_at,
           row_number() over (order by candidate.created_at desc, candidate.id desc) as row_number
    from candidates candidate
  ), page as (
    select numbered.id, numbered.created_at
    from numbered
    where numbered.row_number <= v_limit
  )
  select
    coalesce(
      jsonb_agg(app_private.request_list_item(page.id, v_actor)
      order by page.created_at desc, page.id desc),
      '[]'::jsonb
    ) as items,
    (
      select jsonb_build_object('createdAt', n.created_at, 'id', n.id)
      from numbered n
      where n.row_number = v_limit + 1
    ) as next_cursor
  into v_items, v_next_cursor
  from page;

  return case
    when v_next_cursor is null then jsonb_build_object('items', v_items)
    else jsonb_build_object('items', v_items, 'nextCursor', v_next_cursor)
  end;
end;
$$;


--
-- Name: request_print_template_can_select(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.request_print_template_can_select(p_request_print_template_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app_private.request_user_can_manage(p_user_id)
    or exists (
      select 1
      from public.request_print_templates print_template
      join public.request_instances request_instance
        on request_instance.request_template_version_id =
          print_template.request_template_version_id
      where print_template.id = p_request_print_template_id
        and app_private.request_instance_can_select(
          request_instance.id,
          p_user_id
        )
    );
$$;


--
-- Name: request_summary_payload(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.request_summary_payload(p_user_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with visible as (
    select r.*
    from public.request_instances r
    where app_private.request_instance_can_select(r.id, p_user_id)
  ), counts as (
    select
      count(*)::integer as all_count,
      count(*) filter (where exists (
        select 1 from public.workflow_step_assignments assignment
        where assignment.workflow_subject_id = visible.workflow_subject_id
          and assignment.assignee_user_id = p_user_id
          and assignment.status = 'PENDING'
      ))::integer as assigned_count,
      count(*) filter (where visible.created_by = p_user_id)::integer as created_count,
      count(*) filter (where exists (
        select 1 from public.workflow_participants participant
        where participant.workflow_subject_id = visible.workflow_subject_id
          and participant.user_id = p_user_id
          and participant.role = 'WATCHER'
          and coalesce(participant.is_active, true)
      ) or exists (
        select 1 from public.request_template_watchers watcher
        where watcher.request_template_version_id = visible.request_template_version_id
          and watcher.user_id = p_user_id
      ))::integer as watching_count,
      count(*) filter (where visible.status = 'PENDING')::integer as pending_count,
      count(*) filter (where visible.status = 'RETURNED')::integer as returned_count,
      count(*) filter (where visible.status = 'APPROVED')::integer as approved_count,
      count(*) filter (where visible.status = 'REJECTED')::integer as rejected_count,
      count(*) filter (where visible.due_at < now()
        or exists (
          select 1 from public.workflow_step_assignments assignment
          where assignment.workflow_subject_id = visible.workflow_subject_id
            and assignment.status = 'PENDING'
            and assignment.due_at < now()
        ))::integer as overdue_count
    from visible
  )
  select jsonb_build_object(
    'all', all_count,
    'assignedToMe', assigned_count,
    'createdByMe', created_count,
    'watching', watching_count,
    'pending', pending_count,
    'returned', returned_count,
    'overdue', overdue_count,
    'approved', approved_count,
    'rejected', rejected_count
  )
  from counts
  where p_user_id is not distinct from public.current_app_user_id();
$$;


--
-- Name: request_template_can_select(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.request_template_can_select(p_request_template_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app_private.request_user_can_manage(p_user_id)
    or exists (
      select 1
      from public.request_templates template
      join public.request_template_versions version
        on version.id = template.current_version_id
      where template.id = p_request_template_id
        and template.lifecycle_status = 'PUBLISHED'
        and version.status = 'PUBLISHED'
        and app_private.request_template_version_can_use(
          version.id,
          p_user_id
        )
    );
$$;


--
-- Name: request_template_docx_can_manage(text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.request_template_docx_can_manage(p_object_name text, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app_private.request_user_can_manage(p_user_id)
    and exists (
      select 1
      from public.request_template_versions version
      where version.id =
        app_private.request_template_docx_version_id(p_object_name)
        and version.status = 'DRAFT'
    );
$$;


--
-- Name: request_template_docx_can_select(text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.request_template_docx_can_select(p_object_name text, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.request_template_versions version
    where version.id =
      app_private.request_template_docx_version_id(p_object_name)
      and (
        app_private.request_user_can_manage(p_user_id)
        or exists (
          select 1
          from public.request_instances request_instance
          where request_instance.request_template_version_id = version.id
            and app_private.request_instance_can_select(
              request_instance.id,
              p_user_id
            )
        )
      )
  );
$$;


--
-- Name: request_template_docx_version_id(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.request_template_docx_version_id(p_object_name text) RETURNS uuid
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  select case
    when p_object_name ~
      '^request-template-versions/[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}/template[.]docx$'
    then split_part(p_object_name, '/', 2)::uuid
    else null
  end;
$_$;


--
-- Name: request_template_draft_payload(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.request_template_draft_payload(p_template_version_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'templateId', version.request_template_id,
    'name', template.name,
    'description', coalesce(template.description, ''),
    'formSchema', coalesce(version.form_schema, '[]'::jsonb),
    'usageScope', coalesce(version.usage_scope, '{}'::jsonb),
    'flowMode', version.flow_mode,
    'completionPolicy', version.completion_policy,
    'requestSlaHours', version.request_sla_hours,
    'blocks', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'key', block.block_key,
          'name', block.name,
          'source', block.approver_source,
          'fixedUserIds', to_jsonb(block.fixed_user_ids),
          'minimumDynamicApprovers', block.minimum_dynamic_approvers,
          'slaHours', block.sla_hours,
          'sortOrder', block.sort_order
        ) order by block.sort_order, block.block_key
      )
      from public.request_approval_blocks block
      where block.request_template_version_id = version.id
    ), '[]'::jsonb),
    'watcherUserIds', coalesce((
      select jsonb_agg(watcher.user_id order by watcher.user_id)
      from public.request_template_watchers watcher
      where watcher.request_template_version_id = version.id
    ), '[]'::jsonb),
    'printConfig', coalesce(version.print_config, '{}'::jsonb),
    'notificationConfig', coalesce(version.notification_config, '{}'::jsonb)
  )
  from public.request_template_versions version
  join public.request_templates template
    on template.id = version.request_template_id
  where version.id = p_template_version_id
    and (
      app_private.request_user_can_manage(public.current_app_user_id())
      or app_private.request_template_version_can_select(
        version.id, public.current_app_user_id()
      )
    );
$$;


--
-- Name: request_template_summary(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.request_template_summary(p_template_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'id', template.id,
    'name', template.name,
    'status', template.lifecycle_status,
    'publishedVersionNumber', (
      select version.version_number
      from public.request_template_versions version
      where version.id = template.current_version_id
    ),
    'usageScopeLabel', case
      when coalesce((current_version.usage_scope ->> 'companyWide')::boolean, false)
        then 'Toàn công ty'
      when jsonb_array_length(coalesce(current_version.usage_scope -> 'userIds', '[]'::jsonb)) > 0
        then 'Người dùng cụ thể'
      when jsonb_array_length(coalesce(current_version.usage_scope -> 'orgUnitIds', '[]'::jsonb)) > 0
        then 'Đơn vị/phòng ban'
      when jsonb_array_length(coalesce(current_version.usage_scope -> 'permissionCodes', '[]'::jsonb)) > 0
        then 'Nhóm quyền'
      else 'Chưa giới hạn'
    end,
    'updatedAt', template.updated_at
  )
  from public.request_templates template
  left join public.request_template_versions current_version
    on current_version.id = template.current_version_id
  where template.id = p_template_id
    and (
      app_private.request_user_can_manage(public.current_app_user_id())
      or app_private.request_template_can_select(
        template.id, public.current_app_user_id()
      )
    );
$$;


--
-- Name: request_template_version_can_select(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.request_template_version_can_select(p_request_template_version_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app_private.request_user_can_manage(p_user_id)
    or exists (
      select 1
      from public.request_template_versions version
      join public.request_templates template
        on template.id = version.request_template_id
      where version.id = p_request_template_version_id
        and template.lifecycle_status = 'PUBLISHED'
        and version.status in ('PUBLISHED', 'SUPERSEDED')
        and app_private.request_template_version_can_use(
          version.id,
          p_user_id
        )
    );
$$;


--
-- Name: request_template_version_can_use(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.request_template_version_can_use(p_request_template_version_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.request_template_versions version
    join public.users app_user
      on app_user.id = p_user_id
     and coalesce(app_user.is_active, true)
     and coalesce(app_user.account_status, 'ACTIVE') = 'ACTIVE'
    where version.id = p_request_template_version_id
      and (
        version.usage_scope @> '{"companyWide": true}'::jsonb
        or version.usage_scope @> jsonb_build_object(
          'userIds',
          jsonb_build_array(p_user_id::text)
        )
        or exists (
          select 1
          from public.employees employee
          where employee.user_id = p_user_id
            and (
              (
                employee.department_id is not null
                and version.usage_scope @> jsonb_build_object(
                  'departmentIds',
                  jsonb_build_array(employee.department_id::text)
                )
              )
              or (
                employee.org_unit_id is not null
                and version.usage_scope @> jsonb_build_object(
                  'orgUnitIds',
                  jsonb_build_array(employee.org_unit_id::text)
                )
              )
            )
        )
        or exists (
          select 1
          from public.user_permission_grants permission_grant
          where permission_grant.user_id = p_user_id
            and coalesce(permission_grant.is_active, false)
            and (
              permission_grant.expires_at is null
              or permission_grant.expires_at > now()
            )
            and version.usage_scope @> jsonb_build_object(
              'permissionCodes',
              jsonb_build_array(permission_grant.permission_code)
            )
        )
      )
  );
$$;


--
-- Name: request_user_can_manage(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.request_user_can_manage(p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.users app_user
    where app_user.id = p_user_id
      and coalesce(app_user.is_active, true)
      and coalesce(app_user.account_status, 'ACTIVE') = 'ACTIVE'
      and (
        app_user.role = 'ADMIN'
        or 'RQ' = any(coalesce(app_user.admin_modules, '{}'::text[]))
        or exists (
          select 1
          from jsonb_array_elements_text(
            coalesce(app_user.admin_sub_modules -> 'RQ', '[]'::jsonb)
          ) as admin_route(route)
          where admin_route.route = '/rq/templates'
        )
        or app_private.has_permission(
          p_user_id,
          'request.template.manage',
          'global',
          '*'
        )
      )
  );
$$;


--
-- Name: request_user_snapshot(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.request_user_snapshot(p_user_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case when app_user.id is null then null else jsonb_build_object(
    'id', app_user.id,
    'name', coalesce(nullif(app_user.name, ''), app_user.username, app_user.email, app_user.id::text),
    'avatarUrl', app_user.avatar,
    'position', null
  ) end
  from public.users app_user
  where app_user.id = p_user_id;
$$;


--
-- Name: require_request_notification_worker(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.require_request_notification_worker() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.role() <> 'service_role' then
    raise exception using errcode = '42501', message = 'REQUEST_NOTIFICATION_WORKER_FORBIDDEN';
  end if;
end;
$$;


