--
-- Name: resolve_active_direct_manager(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.resolve_active_direct_manager(p_user_id uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_slot_manager_id uuid;
  v_legacy_manager_id uuid;
begin
  v_slot_manager_id := app_private.resolve_slot_direct_manager(p_user_id);

  select manager.id
  into v_legacy_manager_id
  from public.users employee
  join public.users manager on manager.id = employee.manager_id
  where employee.id = p_user_id
    and manager.id <> p_user_id
    and coalesce(manager.is_active, true)
    and coalesce(manager.account_status, 'ACTIVE') = 'ACTIVE';

  return coalesce(v_slot_manager_id, v_legacy_manager_id);
end;
$$;


--
-- Name: resolve_daily_log_responsibility(text, text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.resolve_daily_log_responsibility(p_project_id text, p_construction_site_id text, p_responsibility text, p_permission_code text) RETURNS TABLE(responsibility_slot_id uuid, assignee_user_id uuid, scope_type text, scope_id text, permission_code text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with candidate_slots as (
    select
      slot.id as responsibility_slot_id,
      slot.assignee_user_id,
      slot.scope_type,
      slot.scope_id,
      slot.permission_code,
      slot.priority,
      slot.created_at,
      case
        when slot.scope_type = 'construction_site' and slot.scope_id = p_construction_site_id then 1
        when slot.scope_type = 'project' and slot.scope_id = p_project_id then 2
        when slot.scope_type = 'global' and slot.scope_id = '*' then 3
        else 99
      end as scope_rank
    from public.app_responsibility_slots slot
    where slot.subject_type = 'daily_log'
      and slot.responsibility = p_responsibility
      and slot.permission_code = p_permission_code
      and slot.status = 'active'
      and slot.starts_at <= now()
      and (slot.expires_at is null or slot.expires_at > now())
      and (
        (slot.scope_type = 'construction_site' and slot.scope_id = p_construction_site_id)
        or (slot.scope_type = 'project' and slot.scope_id = p_project_id)
        or (slot.scope_type = 'global' and slot.scope_id = '*')
      )
  )
  select
    candidate_slots.responsibility_slot_id,
    candidate_slots.assignee_user_id,
    candidate_slots.scope_type,
    candidate_slots.scope_id,
    candidate_slots.permission_code
  from candidate_slots
  where app_private.daily_log_user_can_receive_assignment(
    p_project_id,
    p_construction_site_id,
    candidate_slots.permission_code,
    candidate_slots.assignee_user_id
  )
  order by scope_rank asc, priority asc, created_at asc
  limit 1;
$$;


--
-- Name: resolve_effective_permission_sources(uuid, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.resolve_effective_permission_sources(p_user_id uuid, p_permission_code text DEFAULT NULL::text, p_scope_type text DEFAULT NULL::text, p_scope_id text DEFAULT NULL::text, p_at timestamp with time zone DEFAULT now()) RETURNS TABLE(permission_code text, source_type text, source_id text, source_code text, source_label text, scope_type text, scope_id text, starts_at timestamp with time zone, expires_at timestamp with time zone, risk_level text, is_business_approval boolean, metadata jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with active_user as (
    select u.*
    from public.users u
    where u.id = p_user_id
      and u.is_active
      and u.account_status = 'ACTIVE'
  ),
  active_actions as (
    select pa.*, pm.application_code, pm.legacy_module_key as module_legacy_key
    from public.permission_actions pa
    join public.permission_modules pm on pm.code = pa.module_code
    where pa.is_active
      and pm.is_active
      and (p_permission_code is null or pa.permission_code = p_permission_code)
  ),
  role_sources as (
    select
      item.permission_code,
      'ROLE'::text as source_type,
      assignment.id::text as source_id,
      role_template.code as source_code,
      role_template.name as source_label,
      case
        when assignment.scope_type = 'global' then item.scope_type
        else assignment.scope_type
      end as scope_type,
      case
        when assignment.scope_type = 'global' then item.scope_id
        when item.scope_type = 'global' then assignment.scope_id
        when assignment.scope_id = '*' then item.scope_id
        else assignment.scope_id
      end as scope_id,
      assignment.starts_at,
      assignment.expires_at,
      action_row.risk_level,
      action_row.is_business_approval,
      jsonb_build_object(
        'roleTemplateId', role_template.id,
        'assignmentId', assignment.id,
        'assignmentScopeType', assignment.scope_type,
        'assignmentScopeId', assignment.scope_id
      ) as metadata
    from active_user user_row
    join public.principal_role_assignments assignment
      on assignment.principal_type = 'user'
     and assignment.principal_id = user_row.id
     and assignment.status = 'ACTIVE'
     and assignment.starts_at <= p_at
     and (assignment.expires_at is null or assignment.expires_at > p_at)
    join public.role_permission_templates role_template
      on role_template.id = assignment.role_template_id
     and role_template.is_active
    join public.role_permission_template_items item
      on item.template_id = role_template.id
    join active_actions action_row
      on action_row.permission_code = item.permission_code
    where app_private.permission_hardening_flag('business_role_resolver_enabled')
      and (
        item.permission_code <> 'system.settings.manage'
        or (role_template.code = 'SYSTEM_ADMIN' and user_row.role = 'ADMIN')
      )
      and (
        assignment.scope_type = 'global'
        or item.scope_type = 'global'
        or (
          assignment.scope_type = item.scope_type
          and (assignment.scope_id = '*' or item.scope_id = '*' or assignment.scope_id = item.scope_id)
        )
      )
      and (
        p_scope_type is null
        or (
          app_private.scope_covers(assignment.scope_type, assignment.scope_id, p_scope_type, p_scope_id)
          and app_private.scope_covers(item.scope_type, item.scope_id, p_scope_type, p_scope_id)
        )
      )
  ),
  direct_sources as (
    select
      grant_row.permission_code,
      'DIRECT'::text,
      grant_row.id::text,
      'DIRECT'::text,
      'Direct grant'::text,
      grant_row.scope_type,
      grant_row.scope_id,
      grant_row.granted_at,
      grant_row.expires_at,
      action_row.risk_level,
      action_row.is_business_approval,
      jsonb_build_object('grantedBy', grant_row.granted_by, 'reason', grant_row.grant_reason)
    from active_user user_row
    join public.user_permission_grants grant_row
      on grant_row.user_id = user_row.id
     and grant_row.is_active
     and grant_row.granted_at <= p_at
     and (grant_row.expires_at is null or grant_row.expires_at > p_at)
    join active_actions action_row
      on action_row.permission_code = grant_row.permission_code
    where grant_row.permission_code <> 'system.settings.manage'
      and (
        p_scope_type is null
        or app_private.scope_covers(grant_row.scope_type, grant_row.scope_id, p_scope_type, p_scope_id)
      )
  ),
  legacy_sources as (
    select
      action_row.permission_code,
      'LEGACY'::text,
      coalesce(action_row.legacy_module_key, action_row.module_legacy_key, 'legacy')::text,
      coalesce(action_row.legacy_module_key, action_row.module_legacy_key, 'LEGACY')::text,
      'Legacy permission'::text,
      'global'::text,
      '*'::text,
      null::timestamptz,
      null::timestamptz,
      action_row.risk_level,
      action_row.is_business_approval,
      jsonb_build_object(
        'legacyModuleKey', coalesce(action_row.legacy_module_key, action_row.module_legacy_key),
        'legacyRoute', action_row.legacy_route,
        'legacyAdminCompatibility', user_row.role = 'ADMIN'
      )
    from active_user user_row
    join active_actions action_row on true
    where not app_private.permission_hardening_flag('legacy_fallback_disabled')
      and (
        (
          user_row.role = 'ADMIN'
          and (
            (
              action_row.is_business_approval
              and not app_private.permission_hardening_flag('system_admin_business_approval_bypass_disabled')
            )
            or (
              action_row.module_code = 'system.authorization'
              and not app_private.permission_hardening_flag('legacy_governance_fallback_disabled')
            )
            or (
              not action_row.is_business_approval
              and action_row.module_code <> 'system.authorization'
            )
          )
        )
        or (
          user_row.role <> 'ADMIN'
          and (
            action_row.module_code <> 'system.authorization'
            or not app_private.permission_hardening_flag('legacy_governance_fallback_disabled')
          )
          and coalesce(action_row.legacy_module_key, action_row.module_legacy_key) is not null
          and case
            when action_row.legacy_admin_only or action_row.action = 'manage' then
              coalesce(action_row.legacy_module_key, action_row.module_legacy_key) = any(coalesce(user_row.admin_modules, '{}'::text[]))
              or (
                action_row.legacy_route is null
                and coalesce(user_row.admin_sub_modules, '{}'::jsonb) ? coalesce(action_row.legacy_module_key, action_row.module_legacy_key)
              )
              or (
                action_row.legacy_route is not null
                and coalesce(user_row.admin_sub_modules -> coalesce(action_row.legacy_module_key, action_row.module_legacy_key), '[]'::jsonb) ? action_row.legacy_route
              )
            else
              user_row.allowed_modules is null
              or coalesce(action_row.legacy_module_key, action_row.module_legacy_key) = any(coalesce(user_row.allowed_modules, '{}'::text[]))
              or coalesce(action_row.legacy_module_key, action_row.module_legacy_key) = any(coalesce(user_row.admin_modules, '{}'::text[]))
              or (
                action_row.legacy_route is null
                and (
                  coalesce(user_row.allowed_sub_modules, '{}'::jsonb) ? coalesce(action_row.legacy_module_key, action_row.module_legacy_key)
                  or coalesce(user_row.admin_sub_modules, '{}'::jsonb) ? coalesce(action_row.legacy_module_key, action_row.module_legacy_key)
                )
              )
              or (
                action_row.legacy_route is not null
                and (
                  coalesce(user_row.allowed_sub_modules -> coalesce(action_row.legacy_module_key, action_row.module_legacy_key), '[]'::jsonb) ? action_row.legacy_route
                  or coalesce(user_row.admin_sub_modules -> coalesce(action_row.legacy_module_key, action_row.module_legacy_key), '[]'::jsonb) ? action_row.legacy_route
                )
              )
          end
        )
      )
  )
  select * from role_sources
  union all
  select * from direct_sources
  union all
  select * from legacy_sources;
$$;


--
-- Name: resolve_manager_derived_permission_sources(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.resolve_manager_derived_permission_sources(p_target_user_id uuid) RETURNS TABLE(permission_code text, source_type text, source_id text, source_code text, source_label text, scope_type text, scope_id text, starts_at timestamp with time zone, expires_at timestamp with time zone, risk_level text, is_business_approval boolean, metadata jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with manager_state as (
    select exists (
      select 1
      from public.employees report_employee
      where report_employee.status = 'Đang làm việc'
        and report_employee.user_id is not null
        and app_private.resolve_strict_direct_manager(report_employee.user_id) = p_target_user_id
    ) as has_direct_reports
  ), manager_permissions(permission_code, risk_level) as (
    values
      ('hrm.employee.view_profile'::text, 'medium'::text),
      ('hrm.attendance.view'::text, 'medium'::text),
      ('hrm.attendance.approve'::text, 'high'::text),
      ('hrm.leave.view'::text, 'medium'::text),
      ('hrm.leave.approve'::text, 'high'::text)
  )
  select permission.permission_code,
    'ORGANIZATION'::text,
    'organization_manager'::text,
    'organization_manager'::text,
    'Quản lý trực tiếp'::text,
    'direct_reports'::text,
    '*'::text,
    null::timestamptz,
    null::timestamptz,
    permission.risk_level,
    true,
    jsonb_build_object('resolver', 'strict_slot', 'readinessGate', true)
  from manager_permissions permission
  cross join manager_state
  where manager_state.has_direct_reports;
$$;


--
-- Name: resolve_request_block_approvers(uuid, uuid, uuid[]); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.resolve_request_block_approvers(p_block_id uuid, p_creator_id uuid, p_dynamic_user_ids uuid[]) RETURNS uuid[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_block public.request_approval_blocks%rowtype;
  v_source text;
  v_result uuid[] := '{}'::uuid[];
  v_ids uuid[] := '{}'::uuid[];
  v_id uuid;
  v_manager_id uuid;
  v_minimum integer;
begin
  select * into v_block
  from public.request_approval_blocks
  where id = p_block_id;
  if not found then
    raise exception using errcode = 'P0002', message = 'REQUEST_APPROVAL_BLOCK_NOT_FOUND';
  end if;

  v_source := v_block.approver_source;
  if v_source in ('FIXED_SINGLE', 'FIXED_MULTI') then
    v_ids := coalesce(v_block.fixed_user_ids, '{}'::uuid[]);
  elsif v_source = 'DIRECT_MANAGER' then
    v_manager_id := app_private.resolve_active_direct_manager(p_creator_id);
    if v_manager_id is null then
      raise exception using errcode = '22023', message = 'REQUEST_DIRECT_MANAGER_MISSING';
    end if;
    v_ids := array[v_manager_id];
  elsif v_source = 'DYNAMIC_CREATOR_SELECT' then
    v_ids := coalesce(p_dynamic_user_ids, '{}'::uuid[]);
    v_minimum := coalesce(v_block.minimum_dynamic_approvers, 1);
    if cardinality(v_ids) < v_minimum then
      raise exception using errcode = '22023', message = 'REQUEST_DYNAMIC_APPROVER_REQUIRED';
    end if;
  else
    raise exception using errcode = '22023', message = 'REQUEST_APPROVER_SOURCE_INVALID';
  end if;

  foreach v_id in array v_ids loop
    if v_id is null or v_id = any(v_result) then
      continue;
    end if;
    if v_id = p_creator_id then
      raise exception using errcode = '22023', message = 'REQUEST_APPROVER_SELF_NOT_ALLOWED';
    end if;
    if not exists (
      select 1
      from public.users app_user
      where app_user.id = v_id
        and coalesce(app_user.is_active, true)
        and coalesce(app_user.account_status, 'ACTIVE') = 'ACTIVE'
    ) then
      raise exception using errcode = '22023', message = 'REQUEST_APPROVER_INACTIVE';
    end if;
    v_result := array_append(v_result, v_id);
  end loop;

  if cardinality(v_result) = 0 then
    raise exception using errcode = '22023', message = 'REQUEST_APPROVER_REQUIRED';
  end if;
  if v_source = 'FIXED_SINGLE' and cardinality(v_result) <> 1 then
    raise exception using errcode = '22023', message = 'REQUEST_APPROVER_SINGLE_REQUIRED';
  end if;
  return v_result;
end;
$$;


--
-- Name: resolve_request_direct_manager(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.resolve_request_direct_manager(p_user_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app_private.resolve_active_direct_manager(p_user_id);
$$;


--
-- Name: resolve_slot_direct_manager(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.resolve_slot_direct_manager(p_user_id uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_employee_id uuid;
  v_slot_id uuid;
  v_unit_id uuid;
  v_target_slot_id uuid;
  v_manager_user_id uuid;
begin
  select employee.id
  into v_employee_id
  from public.employees employee
  where employee.user_id = p_user_id
    and employee.status = 'Đang làm việc'
  limit 1;

  if v_employee_id is null then
    return null;
  end if;

  select slot.id, slot.org_unit_id,
         coalesce(
           slot.reports_to_slot_id,
           case when org.manager_slot_id is distinct from slot.id then org.manager_slot_id end
         )
  into v_slot_id, v_unit_id, v_target_slot_id
  from public.hrm_employee_slot_assignments assignment
  join public.hrm_org_position_slots slot on slot.id = assignment.slot_id
  join public.org_units org on org.id = slot.org_unit_id
  where assignment.employee_id = v_employee_id
    and assignment.assignment_type = 'PRIMARY'
    and assignment.status = 'ACTIVE'
    and assignment.effective_from <= current_date
    and (assignment.effective_to is null or assignment.effective_to >= current_date)
    and slot.status = 'ACTIVE'
  order by assignment.effective_from desc
  limit 1;

  if v_slot_id is null then
    return null;
  end if;

  if v_target_slot_id is null then
    with recursive ancestor_units as (
      select parent.id, parent.parent_id, parent.manager_slot_id, 1 as depth
      from public.org_units child
      join public.org_units parent on parent.id = child.parent_id
      where child.id = v_unit_id
      union all
      select parent.id, parent.parent_id, parent.manager_slot_id, ancestor.depth + 1
      from ancestor_units ancestor
      join public.org_units parent on parent.id = ancestor.parent_id
    )
    select manager_slot_id
    into v_target_slot_id
    from ancestor_units
    where manager_slot_id is not null
      and manager_slot_id <> v_slot_id
    order by depth
    limit 1;
  end if;

  if v_target_slot_id is null then
    return null;
  end if;

  select manager_user.id
  into v_manager_user_id
  from public.hrm_employee_slot_assignments assignment
  join public.employees manager_employee on manager_employee.id = assignment.employee_id
  join public.users manager_user on manager_user.id = manager_employee.user_id
  where assignment.slot_id = v_target_slot_id
    and assignment.assignment_type in ('PRIMARY', 'ACTING')
    and assignment.status = 'ACTIVE'
    and assignment.effective_from <= current_date
    and (assignment.effective_to is null or assignment.effective_to >= current_date)
    and manager_user.id <> p_user_id
    and coalesce(manager_user.is_active, true)
    and coalesce(manager_user.account_status, 'ACTIVE') = 'ACTIVE'
  order by case assignment.assignment_type when 'ACTING' then 0 else 1 end,
           assignment.effective_from desc
  limit 1;

  return v_manager_user_id;
end;
$$;


--
-- Name: resolve_strict_direct_manager(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.resolve_strict_direct_manager(p_user_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when coalesce((
      select setting.is_enabled
      from app_private.hrm_manager_scope_settings setting
      where setting.singleton
    ), false)
    then app_private.resolve_slot_direct_manager(p_user_id)
    else null::uuid
  end;
$$;


--
-- Name: FUNCTION resolve_strict_direct_manager(p_user_id uuid); Type: COMMENT; Schema: app_private; Owner: -
--

COMMENT ON FUNCTION app_private.resolve_strict_direct_manager(p_user_id uuid) IS 'Authorization-only manager resolver. Uses slot assignments and the readiness gate; never users.manager_id.';


--
-- Name: resolve_warehouse_project_scope(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.resolve_warehouse_project_scope(p_warehouse_id text) RETURNS TABLE(project_id text, construction_site_id text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    warehouse.project_id as project_id,
    warehouse.construction_site_id::text as construction_site_id
  from public.warehouses warehouse
  where warehouse.id = p_warehouse_id;
$$;


--
-- Name: resolve_wms_business_event(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.resolve_wms_business_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_derived text;
  v_warehouse_id text;
  v_scope record;
  v_line jsonb;
  v_payload_project_id text;
  v_payload_site_id text;
begin
  v_derived := app_private.classify_wms_business_event(
    new.type::text, new.source_type, new.related_request_id, new.items
  );
  new.business_event_type := coalesce(new.business_event_type, v_derived);

  if new.status::text = 'COMPLETED' then
    if new.business_event_type is null then
      raise exception 'Phiếu kho hoàn tất phải có mục đích nghiệp vụ.';
    end if;
    if new.business_event_type in ('direct_manual_receipt', 'warehouse_loss', 'inventory_adjustment')
       and nullif(btrim(coalesce(new.business_event_reason, new.note, '')), '') is null then
      raise exception 'Bắt buộc nhập lý do cho mục đích nghiệp vụ này.';
    end if;

    for v_line in select value from jsonb_array_elements(coalesce(new.items, '[]'::jsonb))
    loop
      v_warehouse_id := case
        when new.type::text in ('EXPORT', 'LIQUIDATION') then new.source_warehouse_id
        when new.type::text = 'ADJUSTMENT' then coalesce(new.target_warehouse_id, new.source_warehouse_id)
        else new.target_warehouse_id
      end;
      select * into v_scope from app_private.resolve_warehouse_project_scope(v_warehouse_id);
      v_payload_project_id := nullif(coalesce(v_line->>'projectId', v_line->>'project_id'), '');
      v_payload_site_id := nullif(coalesce(v_line->>'constructionSiteId', v_line->>'construction_site_id'), '');
      if (v_payload_project_id is not null and v_payload_project_id is distinct from v_scope.project_id)
         or (v_payload_site_id is not null and v_payload_site_id is distinct from v_scope.construction_site_id) then
        raise exception 'Scope chứng từ không khớp scope kho.';
      end if;
    end loop;
  end if;
  return new;
end;
$$;


--
-- Name: restore_project(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.restore_project(p_project_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_project public.projects%rowtype;
begin
  if not app_private.can_manage_project_master(p_project_id, 'project.master.restore') then
    raise exception 'Not allowed to restore project'
      using errcode = '42501';
  end if;

  update public.projects
  set is_hidden = false,
      hidden_at = null,
      hidden_by = null,
      hidden_reason = null
  where id = p_project_id
  returning *
  into v_project;

  if v_project.id is null then
    raise exception 'Project not found: %', p_project_id
      using errcode = 'P0002';
  end if;

  return to_jsonb(v_project);
end;
$$;


--
-- Name: review_attendance_proposal_v1(uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.review_attendance_proposal_v1(p_proposal_id uuid, p_decision text, p_rejection_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app_private', 'pg_temp'
    AS $$
declare
  v_proposal public.hrm_attendance_proposals;
  v_updated_proposal public.hrm_attendance_proposals;
  v_attendance public.hrm_attendance;
  v_app_user_id uuid := public.current_app_user_id();
  v_decision text := lower(trim(coalesce(p_decision, '')));
  v_location_name text;
  v_can_review boolean;
begin
  if auth.uid() is null then
    raise exception 'Phiên đăng nhập Supabase không hợp lệ.'
      using errcode = '28000';
  end if;

  if v_app_user_id is null then
    raise exception 'Không tìm thấy tài khoản ứng dụng tương ứng.'
      using errcode = '28000';
  end if;

  if v_decision not in ('approved', 'rejected') then
    raise exception 'Quyết định duyệt đề xuất không hợp lệ.'
      using errcode = '22023';
  end if;

  select *
  into v_proposal
  from public.hrm_attendance_proposals
  where id = p_proposal_id
  for update;

  if v_proposal.id is null then
    raise exception 'Không tìm thấy đề xuất chấm công.'
      using errcode = 'P0002';
  end if;

  if v_proposal."proposalStatus" <> 'pending' then
    raise exception 'Đề xuất này đã được xử lý.'
      using errcode = '23514';
  end if;

  v_can_review := app_private.has_governed_hrm_permission(v_app_user_id, 'hrm.attendance.approve')
    or app_private.hrm_is_location_manager(v_proposal."locationType", v_proposal."locationId");

  if not v_can_review then
    raise exception 'Bạn không phải người quản lý địa điểm của đề xuất này.'
      using errcode = '42501';
  end if;

  v_location_name := app_private.hrm_location_name(
    v_proposal."locationType",
    v_proposal."locationId",
    v_proposal."locationName"
  );

  if v_decision = 'rejected' then
    update public.hrm_attendance_proposals
      set "proposalStatus" = 'rejected',
          "approvedBy" = v_app_user_id::text,
          "approvedAt" = now(),
          "rejectionReason" = coalesce(nullif(trim(p_rejection_reason), ''), 'Từ chối'),
          "submittedToUserId" = coalesce("submittedToUserId", app_private.hrm_location_manager_id("locationType", "locationId")),
          "submittedToName" = coalesce(
            "submittedToName",
            (select u.name from public.users u where u.id::text = app_private.hrm_location_manager_id("locationType", "locationId"))
          ),
          "locationName" = coalesce("locationName", v_location_name)
    where id = v_proposal.id
    returning * into v_updated_proposal;

    return jsonb_build_object(
      'proposal', to_jsonb(v_updated_proposal),
      'attendance', null
    );
  end if;

  update public.hrm_attendance_proposals
    set "proposalStatus" = 'approved',
        "approvedBy" = v_app_user_id::text,
        "approvedAt" = now(),
        "rejectionReason" = null,
        "submittedToUserId" = coalesce("submittedToUserId", app_private.hrm_location_manager_id("locationType", "locationId")),
        "submittedToName" = coalesce(
          "submittedToName",
          (select u.name from public.users u where u.id::text = app_private.hrm_location_manager_id("locationType", "locationId"))
        ),
        "locationName" = coalesce("locationName", v_location_name)
  where id = v_proposal.id
  returning * into v_updated_proposal;

  insert into public.hrm_attendance (
    id,
    "employeeId",
    date,
    status,
    "checkIn",
    "checkOut",
    "constructionSiteId",
    "locationName",
    "locationType",
    note,
    "approvalStatus",
    "approvedBy",
    "approvedAt",
    "submittedToUserId",
    "createdAt"
  )
  values (
    gen_random_uuid(),
    v_proposal."targetEmployeeId"::uuid,
    v_proposal.date::text,
    v_proposal.status,
    nullif(v_proposal."checkIn", ''),
    nullif(v_proposal."checkOut", ''),
    case when v_proposal."locationType" = 'construction_site' then v_proposal."locationId" else null end,
    v_location_name,
    v_proposal."locationType",
    left('Bù công từ đề xuất ' || v_proposal.id::text || ': ' || v_proposal.reason, 1000),
    'approved',
    v_app_user_id::text,
    now(),
    app_private.hrm_location_manager_id(v_proposal."locationType", v_proposal."locationId"),
    now()
  )
  on conflict ("employeeId", date) do update
    set status = excluded.status,
        "checkIn" = case
          when excluded."checkIn" is null then public.hrm_attendance."checkIn"
          when public.hrm_attendance."checkIn" is null then excluded."checkIn"
          when excluded."checkIn" < public.hrm_attendance."checkIn" then excluded."checkIn"
          else public.hrm_attendance."checkIn"
        end,
        "checkOut" = case
          when excluded."checkOut" is null then public.hrm_attendance."checkOut"
          when public.hrm_attendance."checkOut" is null then excluded."checkOut"
          when excluded."checkOut" > public.hrm_attendance."checkOut" then excluded."checkOut"
          else public.hrm_attendance."checkOut"
        end,
        "constructionSiteId" = coalesce(excluded."constructionSiteId", public.hrm_attendance."constructionSiteId"),
        "locationName" = coalesce(excluded."locationName", public.hrm_attendance."locationName"),
        "locationType" = coalesce(excluded."locationType", public.hrm_attendance."locationType"),
        note = left(concat_ws(E'\n', nullif(public.hrm_attendance.note, ''), excluded.note), 1000),
        "approvalStatus" = 'approved',
        "approvedBy" = excluded."approvedBy",
        "approvedAt" = excluded."approvedAt",
        "submittedToUserId" = coalesce(excluded."submittedToUserId", public.hrm_attendance."submittedToUserId")
  returning * into v_attendance;

  return jsonb_build_object(
    'proposal', to_jsonb(v_updated_proposal),
    'attendance', to_jsonb(v_attendance)
  );
end;
$$;


--
-- Name: revoke_business_role_assignment_impl(uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.revoke_business_role_assignment_impl(p_assignment_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid;
  v_initial_target_id uuid;
  v_initial_role_id uuid;
  v_target public.users%rowtype;
  v_role public.role_permission_templates%rowtype;
  v_assignment public.principal_role_assignments%rowtype;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  v_actor_user_id := app_private.assert_authorization_permission(
    'system.authorization.manage_roles'
  );

  if char_length(v_reason) < 10 then
    raise exception 'Business Role revoke reason required'
      using errcode = '22023';
  end if;

  select assignment_row.principal_id, assignment_row.role_template_id
  into v_initial_target_id, v_initial_role_id
  from public.principal_role_assignments assignment_row
  where assignment_row.id = p_assignment_id
    and assignment_row.principal_type = 'user';

  if v_initial_target_id is null then
    raise exception 'Business Role assignment does not exist'
      using errcode = '23503';
  end if;

  select *
  into v_target
  from public.users
  where id = v_initial_target_id
  for update;

  select *
  into v_role
  from public.role_permission_templates
  where id = v_initial_role_id
  for update;

  select *
  into v_assignment
  from public.principal_role_assignments
  where id = p_assignment_id
  for update;

  if v_target.id is null
    or v_role.id is null
    or v_assignment.id is null
    or v_assignment.principal_id is distinct from v_target.id
    or v_assignment.role_template_id is distinct from v_role.id
  then
    raise exception 'Business Role assignment changed during revoke'
      using errcode = '55000';
  end if;

  if v_assignment.status = 'REVOKED' then
    if btrim(coalesce(v_assignment.revoked_reason, '')) = v_reason then
      return;
    end if;

    raise exception 'Business Role assignment was already revoked with another reason'
      using errcode = '55000';
  end if;

  if v_assignment.status <> 'ACTIVE' then
    raise exception 'Only an active Business Role assignment can be revoked'
      using errcode = '55000';
  end if;

  if v_role.code = 'SYSTEM_ADMIN'
    and v_target.role = 'ADMIN'
    and v_target.is_active
    and v_target.account_status = 'ACTIVE'
  then
    raise exception 'System Admin identity must be demoted before revoking its role mirror'
      using errcode = '55000';
  end if;

  if v_assignment.expires_at is null
    and v_assignment.scope_type = 'global'
    and v_assignment.scope_id = '*'
    and exists (
      select 1
      from public.role_permission_template_items item
      where item.template_id = v_role.id
        and item.permission_code = 'system.authorization.manage_roles'
        and item.scope_type = 'global'
        and item.scope_id = '*'
    )
  then
    perform app_private.assert_rollout_operator_continuity(
      v_assignment.id,
      null
    );
  end if;

  update public.principal_role_assignments
  set status = 'REVOKED',
      revoked_at = now(),
      revoked_by = v_actor_user_id,
      revoked_reason = v_reason,
      updated_at = now()
  where id = v_assignment.id;

  insert into public.permission_audit_events (
    actor_user_id,
    target_user_id,
    event_type,
    before_grants,
    after_grants,
    metadata
  )
  values (
    v_actor_user_id,
    v_target.id,
    'business_role_revoked',
    jsonb_build_array(to_jsonb(v_assignment)),
    '[]'::jsonb,
    jsonb_build_object(
      'assignmentId', v_assignment.id,
      'roleTemplateId', v_role.id,
      'reason', v_reason
    )
  );
end;
$$;


--
-- Name: revoke_business_roles_on_account_disable(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.revoke_business_roles_on_account_disable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_revoked_count integer := 0;
  v_operation_id uuid;
begin
  if old.account_status = 'ACTIVE' and new.account_status = 'DISABLED' then
    if old.role = 'ADMIN' then
      perform app_private.assert_rollout_operator_continuity(null, new.id);
    end if;

    select operation_row.id
    into v_operation_id
    from app_private.user_account_operations operation_row
    where operation_row.target_user_id = new.id
      and operation_row.status = 'PREPARED'
      and operation_row.action = 'DISABLE'
    order by operation_row.created_at
    limit 1
    for update;

    update public.principal_role_assignments assignment_row
    set status = 'REVOKED',
        revoked_at = coalesce(assignment_row.revoked_at, now()),
        revoked_by = coalesce(assignment_row.revoked_by, new.disabled_by),
        revoked_reason = coalesce(
          assignment_row.revoked_reason,
          'account_disabled: ' || coalesce(new.disabled_reason, 'Account disabled')
        ),
        updated_at = now()
    where assignment_row.principal_type = 'user'
      and assignment_row.principal_id = new.id
      and assignment_row.status in ('ACTIVE');
    get diagnostics v_revoked_count = row_count;

    if v_operation_id is not null then
      update app_private.user_account_operations
      set before_state = before_state || jsonb_build_object(
            'businessRoleAssignmentsRevoked', v_revoked_count
          ),
          updated_at = now()
      where id = v_operation_id;
    end if;

    if v_revoked_count > 0 then
      insert into public.permission_audit_events (
        actor_user_id,
        target_user_id,
        event_type,
        before_grants,
        after_grants,
        metadata
      )
      values (
        new.disabled_by,
        new.id,
        'business_roles_revoked_on_account_disable',
        '[]'::jsonb,
        '[]'::jsonb,
        jsonb_build_object(
          'operationId', v_operation_id,
          'revokedCount', v_revoked_count,
          'reason', new.disabled_reason
        )
      );
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: revoke_safety_assignment_card(uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.revoke_safety_assignment_card(p_card_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_card public.safety_cards%rowtype;
  v_assignment public.safety_project_assignments%rowtype;
  v_membership public.safety_worker_site_memberships%rowtype;
begin
  if nullif(trim(p_reason), '') is null then
    raise exception 'SAFETY_INVALID_RPC_PAYLOAD: revoke reason is required'
      using errcode = '22023';
  end if;

  select card.*
  into v_card
  from public.safety_cards card
  where card.id = p_card_id
  for update;

  select assignment.*
  into v_assignment
  from public.safety_project_assignments assignment
  where assignment.id = v_card.assignment_id;

  select membership.*
  into v_membership
  from public.safety_worker_site_memberships membership
  where membership.id = v_assignment.membership_id;

  if v_card.id is null
    or v_card.status <> 'active'
    or v_actor is null
    or not app_private.safety_workforce_can_manage(v_membership.project_id, v_membership.construction_site_id)
  then
    raise exception 'SAFETY_SCOPE_MISMATCH: active card is not revocable'
      using errcode = '42501';
  end if;

  update public.safety_cards card
  set status = 'revoked',
      revoked_reason = trim(p_reason),
      updated_at = now()
  where card.id = v_card.id;

  insert into public.safety_audit_logs (
    actor_user_id, action, target_type, target_id, project_id, construction_site_id, metadata
  ) values (
    v_actor::text,
    'card.revoke',
    'safety_cards',
    v_card.id,
    v_membership.project_id,
    v_membership.construction_site_id::text,
    jsonb_build_object('reason', trim(p_reason))
  );

  return app_private.safety_workforce_detail_for_membership(v_membership.id);
end;
$$;


--
-- Name: revoke_user_access_sources(uuid, uuid, uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.revoke_user_access_sources(p_target_user_id uuid, p_actor_user_id uuid, p_operation_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_slot public.app_responsibility_slots%rowtype;
  v_assignment public.app_assignments%rowtype;
  v_direct_grants integer := 0;
  v_project_permissions integer := 0;
  v_project_staff integer := 0;
  v_slots integer := 0;
  v_assignments integer := 0;
begin
  update public.user_permission_grants
  set is_active = false,
      revoked_at = coalesce(revoked_at, now()),
      revoked_by = coalesce(revoked_by, p_actor_user_id),
      revoked_reason = coalesce(revoked_reason, p_reason),
      updated_at = now()
  where user_id = p_target_user_id
    and is_active;
  get diagnostics v_direct_grants = row_count;

  update public.project_staff_permissions psp
  set is_active = false
  from public.project_staff ps
  where psp.staff_id = ps.id
    and ps.user_id = p_target_user_id::text
    and coalesce(psp.is_active, true);
  get diagnostics v_project_permissions = row_count;

  update public.project_staff
  set end_date = current_date,
      updated_at = now()
  where user_id = p_target_user_id::text
    and end_date is null;
  get diagnostics v_project_staff = row_count;

  for v_slot in
    select *
    from public.app_responsibility_slots
    where assignee_user_id = p_target_user_id
      and status = 'active'
    for update
  loop
    update public.app_responsibility_slots
    set status = 'inactive',
        metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
          'needsReassignment', true,
          'accountOperationId', p_operation_id
        ),
        updated_at = now()
    where id = v_slot.id;

    insert into public.app_responsibility_slot_events (
      responsibility_slot_id,
      event_type,
      actor_user_id,
      before_data,
      after_data
    )
    select
      v_slot.id,
      'updated',
      p_actor_user_id,
      to_jsonb(v_slot),
      to_jsonb(updated_slot)
    from public.app_responsibility_slots updated_slot
    where updated_slot.id = v_slot.id;

    v_slots := v_slots + 1;
  end loop;

  for v_assignment in
    select *
    from public.app_assignments
    where principal_id = p_target_user_id
      and status = 'active'
    for update
  loop
    update public.app_assignments
    set status = 'closed',
        closed_at = now(),
        closed_by = p_actor_user_id,
        close_reason = 'account_disabled',
        metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
          'needsReassignment', true,
          'accountOperationId', p_operation_id
        ),
        updated_at = now()
    where id = v_assignment.id;

    insert into public.app_assignment_events (
      assignment_id,
      event_type,
      actor_user_id,
      metadata
    )
    values (
      v_assignment.id,
      'closed',
      p_actor_user_id,
      jsonb_build_object(
        'reason', 'account_disabled',
        'needsReassignment', true,
        'operationId', p_operation_id
      )
    );

    v_assignments := v_assignments + 1;
  end loop;

  return jsonb_build_object(
    'directGrants', v_direct_grants,
    'projectPermissions', v_project_permissions,
    'projectStaffAssignments', v_project_staff,
    'responsibilitySlots', v_slots,
    'runtimeAssignments', v_assignments,
    'needsReassignment', v_slots + v_assignments
  );
end;
$$;


--
-- Name: rollup_site_direct_purchase_totals(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.rollup_site_direct_purchase_totals() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_purchase_id uuid;
begin
  v_purchase_id := case when tg_op = 'DELETE' then old.direct_purchase_id else new.direct_purchase_id end;
  update public.site_direct_purchases p
  set
    gross_amount = coalesce(t.gross_amount, 0),
    vat_amount = coalesce(t.vat_amount, 0),
    total_amount = coalesce(t.gross_amount, 0) + coalesce(t.vat_amount, 0),
    updated_at = now()
  from (
    select
      direct_purchase_id,
      sum(line_amount)::numeric(18,2) as gross_amount,
      sum(vat_amount)::numeric(18,2) as vat_amount
    from public.site_direct_purchase_lines
    where direct_purchase_id = v_purchase_id
    group by direct_purchase_id
  ) t
  where p.id = v_purchase_id
    and t.direct_purchase_id = p.id;

  update public.site_direct_purchases p
  set
    gross_amount = 0,
    vat_amount = 0,
    total_amount = 0,
    updated_at = now()
  where p.id = v_purchase_id
    and not exists (
      select 1 from public.site_direct_purchase_lines line
      where line.direct_purchase_id = v_purchase_id
    );

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


--
-- Name: rollup_supplier_direct_delivery_note_totals(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.rollup_supplier_direct_delivery_note_totals() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_note_id uuid;
begin
  v_note_id := case when tg_op = 'DELETE' then old.delivery_note_id else new.delivery_note_id end;
  update public.supplier_direct_delivery_notes note
  set
    gross_amount = coalesce(t.gross_amount, 0),
    vat_amount = coalesce(t.vat_amount, 0),
    total_amount = coalesce(t.total_amount, 0),
    updated_at = now()
  from (
    select
      delivery_note_id,
      sum(line_amount)::numeric(18,2) as gross_amount,
      sum(vat_amount)::numeric(18,2) as vat_amount,
      sum(total_amount)::numeric(18,2) as total_amount
    from public.supplier_direct_delivery_lines
    where delivery_note_id = v_note_id
    group by delivery_note_id
  ) t
  where note.id = v_note_id
    and t.delivery_note_id = note.id;

  update public.supplier_direct_delivery_notes note
  set gross_amount = 0, vat_amount = 0, total_amount = 0, updated_at = now()
  where note.id = v_note_id
    and not exists (
      select 1
      from public.supplier_direct_delivery_lines line
      where line.delivery_note_id = v_note_id
    );

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


--
-- Name: safe_date(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.safe_date(p_value text) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
begin
  return nullif(p_value, '')::date;
exception when others then
  return null;
end;
$$;


--
-- Name: safety_assignment_eligibility_status(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.safety_assignment_eligibility_status(p_assignment_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_assignment public.safety_project_assignments%rowtype;
  v_worker public.safety_worker_profiles%rowtype;
  v_required_count integer := 0;
  v_missing_count integer := 0;
  v_expired_count integer := 0;
  v_required_document_missing_count integer := 0;
begin
  select * into v_assignment
  from public.safety_project_assignments assignment
  where assignment.id = p_assignment_id;

  if not found then return 'missing_profile'; end if;

  select * into v_worker
  from public.safety_worker_profiles worker
  where worker.id = v_assignment.worker_id;

  if not found then return 'missing_profile'; end if;
  if v_worker.status = 'suspended' or v_assignment.is_locked then return 'suspended'; end if;

  if v_worker.status <> 'active'
    or nullif(trim(v_worker.full_name), '') is null
    or nullif(trim(v_worker.worker_code), '') is null
    or v_worker.photo_attachment = 'null'::jsonb
    or nullif(trim(coalesce(v_worker.identity_number, '')), '') is null
    or (
      jsonb_array_length(coalesce(v_worker.identity_attachments, '[]'::jsonb)) = 0
      and not app_private.safety_workforce_has_canonical_identity_document(v_worker.id)
    )
  then return 'missing_profile'; end if;

  with required_documents(document_type) as (
    values ('health_check'), ('insurance')
  ), document_state as (
    select required_documents.document_type, document.id, document.status, document.expiry_date, document.attachments
    from required_documents
    left join lateral (
      select worker_document.*
      from public.safety_worker_documents worker_document
      where worker_document.worker_id = v_worker.id
        and worker_document.document_type = required_documents.document_type
        and worker_document.status <> 'rejected'
      order by worker_document.expiry_date desc nulls last, worker_document.created_at desc
      limit 1
    ) document on true
  )
  select count(*) into v_required_document_missing_count
  from document_state
  where id is null
    or status in ('missing', 'expired', 'rejected')
    or jsonb_array_length(coalesce(attachments, '[]'::jsonb)) = 0
    or (expiry_date is not null and expiry_date < current_date);

  if v_required_document_missing_count > 0 then return 'missing_profile'; end if;

  select count(*) into v_required_count
  from public.safety_certificate_types certificate_type
  where certificate_type.is_active
    and certificate_type.is_required_default
    and app_private.safety_required_certificate_type_applies(
      certificate_type.applies_to_roles,
      coalesce(v_assignment.role_name, v_worker.role_name)
    );

  if v_required_count > 0 then
    select
      count(*) filter (where certificate.id is null),
      count(*) filter (where certificate.id is not null and certificate.expiry_date is not null and certificate.expiry_date < current_date)
    into v_missing_count, v_expired_count
    from public.safety_certificate_types certificate_type
    left join lateral (
      select worker_certificate.*
      from public.safety_worker_certificates worker_certificate
      where worker_certificate.worker_id = v_worker.id
        and worker_certificate.certificate_type_id = certificate_type.id
        and worker_certificate.status in ('approved', 'submitted')
        and worker_certificate.status not in ('rejected', 'revoked')
      order by worker_certificate.expiry_date desc nulls last, worker_certificate.created_at desc
      limit 1
    ) certificate on true
    where certificate_type.is_active
      and certificate_type.is_required_default
      and app_private.safety_required_certificate_type_applies(
        certificate_type.applies_to_roles,
        coalesce(v_assignment.role_name, v_worker.role_name)
      );

    if v_missing_count > 0 then return 'missing_certificate'; end if;
    if v_expired_count > 0 then return 'expired_certificate'; end if;
  end if;

  if v_assignment.site_training_status <> 'completed'
    or v_assignment.commitment_status <> 'signed'
    or v_assignment.ppe_status <> 'complete'
    or v_assignment.toolbox_status <> 'completed'
  then return 'missing_site_requirement'; end if;

  return 'eligible';
end;
$$;


--
-- Name: safety_can_delete(text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.safety_can_delete(p_project_id text, p_construction_site_id text, p_status text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    public.is_admin()
    or public.is_module_admin('DA')
    or (
      coalesce(p_status, 'new') in ('draft', 'new')
      and app_private.project_user_has_permission(p_project_id, p_construction_site_id, 'delete', public.current_app_user_id())
    ),
    false
  );
$$;


