--
-- Name: safety_required_certificate_type_applies(jsonb, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.safety_required_certificate_type_applies(p_applies_to_roles jsonb, p_role_name text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_array_length(p_applies_to_roles), 0) = 0
    or exists (
      select 1
      from jsonb_array_elements_text(coalesce(p_applies_to_roles, '[]'::jsonb)) role_value
      where lower(role_value) = lower(coalesce(p_role_name, ''))
    );
$$;


--
-- Name: safety_worker_certificate_status(date); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.safety_worker_certificate_status(p_expiry_date date) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select case
    when p_expiry_date is null then 'valid'
    when p_expiry_date < current_date then 'expired'
    when p_expiry_date <= current_date + 30 then 'expiring_soon'
    else 'valid'
  end;
$$;


--
-- Name: safety_workforce_assert_scope(text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.safety_workforce_assert_scope(p_project_id text, p_construction_site_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if nullif(trim(p_project_id), '') is null or p_construction_site_id is null then
    raise exception 'SAFETY_SCOPE_REQUIRED: project and construction site are required'
      using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.projects project_row
    where project_row.id = p_project_id
      and project_row.construction_site_id = p_construction_site_id
  ) then
    raise exception 'SAFETY_SCOPE_MISMATCH: project is not linked to construction site'
      using errcode = '22023';
  end if;
end;
$$;


--
-- Name: safety_workforce_assert_subcontractor_team(text, uuid, uuid, uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.safety_workforce_assert_subcontractor_team(p_project_id text, p_construction_site_id uuid, p_subcontractor_id uuid, p_team_id uuid, p_worker_kind text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform app_private.safety_workforce_assert_scope(p_project_id, p_construction_site_id);

  if p_worker_kind is null or p_worker_kind not in ('company_staff', 'contractor_worker') then
    raise exception 'SAFETY_INVALID_WORKER_KIND: unsupported worker kind'
      using errcode = '22023';
  end if;

  if p_worker_kind = 'company_staff' then
    if p_subcontractor_id is not null or p_team_id is not null then
      raise exception 'SAFETY_CONTRACTOR_SCOPE_MISMATCH: company staff cannot use contractor or team'
        using errcode = '22023';
    end if;
    return;
  end if;

  if p_subcontractor_id is null or not exists (
    select 1
    from public.safety_subcontractors subcontractor
    where subcontractor.id = p_subcontractor_id
      and subcontractor.project_id = p_project_id
      and subcontractor.construction_site_id = p_construction_site_id::text
      and subcontractor.status in ('approved', 'active')
  ) then
    raise exception 'SAFETY_CONTRACTOR_SCOPE_MISMATCH: contractor is not active in target site'
      using errcode = '22023';
  end if;

  if p_team_id is not null and not exists (
    select 1
    from public.safety_teams team
    where team.id = p_team_id
      and team.project_id = p_project_id
      and team.construction_site_id = p_construction_site_id::text
      and team.subcontractor_id = p_subcontractor_id
      and team.status = 'active'
  ) then
    raise exception 'SAFETY_TEAM_SCOPE_MISMATCH: team is not active for contractor in target site'
      using errcode = '22023';
  end if;
end;
$$;


--
-- Name: safety_project_assignments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.safety_project_assignments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    worker_id uuid NOT NULL,
    project_id text,
    construction_site_id text,
    contractor_id uuid,
    team_name text,
    role_name text,
    start_date date DEFAULT CURRENT_DATE NOT NULL,
    end_date date,
    site_training_status text DEFAULT 'pending'::text NOT NULL,
    commitment_status text DEFAULT 'pending'::text NOT NULL,
    ppe_status text DEFAULT 'missing'::text NOT NULL,
    toolbox_status text DEFAULT 'pending'::text NOT NULL,
    is_locked boolean DEFAULT false NOT NULL,
    lock_reason text,
    eligibility_status text DEFAULT 'missing_profile'::text NOT NULL,
    eligibility_checked_at timestamp with time zone,
    created_by text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    site_access_card_code text,
    work_type text,
    membership_id uuid NOT NULL,
    assignment_status text NOT NULL,
    started_at timestamp with time zone NOT NULL,
    ended_at timestamp with time zone,
    subcontractor_id uuid,
    team_id uuid,
    ended_by uuid,
    ended_reason text,
    source text NOT NULL,
    CONSTRAINT safety_project_assignments_commitment_status_check CHECK ((commitment_status = ANY (ARRAY['pending'::text, 'signed'::text]))),
    CONSTRAINT safety_project_assignments_eligibility_status_check CHECK ((eligibility_status = ANY (ARRAY['eligible'::text, 'missing_profile'::text, 'missing_certificate'::text, 'expired_certificate'::text, 'missing_site_requirement'::text, 'suspended'::text]))),
    CONSTRAINT safety_project_assignments_lifecycle_dates_check CHECK (((ended_at IS NULL) OR (started_at IS NULL) OR (ended_at >= started_at))),
    CONSTRAINT safety_project_assignments_lifecycle_status_check CHECK (((assignment_status IS NULL) OR (assignment_status = ANY (ARRAY['active'::text, 'ended'::text, 'suspended'::text, 'cancelled'::text])))),
    CONSTRAINT safety_project_assignments_ppe_status_check CHECK ((ppe_status = ANY (ARRAY['missing'::text, 'partial'::text, 'complete'::text]))),
    CONSTRAINT safety_project_assignments_site_training_status_check CHECK ((site_training_status = ANY (ARRAY['pending'::text, 'completed'::text, 'expired'::text]))),
    CONSTRAINT safety_project_assignments_source_check CHECK (((source IS NULL) OR (source = ANY (ARRAY['manual'::text, 'legacy'::text, 'transfer'::text, 'son_mien_bac_backfill_v1'::text])))),
    CONSTRAINT safety_project_assignments_toolbox_status_check CHECK ((toolbox_status = ANY (ARRAY['pending'::text, 'completed'::text, 'expired'::text])))
);


--
-- Name: safety_workforce_assignment_json(public.safety_project_assignments); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.safety_workforce_assignment_json(p_assignment public.safety_project_assignments) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'id', (p_assignment).id,
    'workerId', (p_assignment).worker_id,
    'membershipId', (p_assignment).membership_id,
    'projectId', (p_assignment).project_id,
    'constructionSiteId', (p_assignment).construction_site_id,
    'contractorId', (p_assignment).contractor_id,
    'subcontractorId', (p_assignment).subcontractor_id,
    'subcontractorName', (
      select subcontractor.name
      from public.safety_subcontractors subcontractor
      where subcontractor.id = (p_assignment).subcontractor_id
    ),
    'teamId', (p_assignment).team_id,
    'teamName', coalesce((p_assignment).team_name, (
      select team.name
      from public.safety_teams team
      where team.id = (p_assignment).team_id
    )),
    'roleName', (p_assignment).role_name,
    'workType', (p_assignment).work_type,
    'siteAccessCardCode', (p_assignment).site_access_card_code,
    'startDate', (p_assignment).start_date,
    'endDate', (p_assignment).end_date,
    'assignmentStatus', (p_assignment).assignment_status,
    'startedAt', (p_assignment).started_at,
    'endedAt', (p_assignment).ended_at,
    'endedBy', (p_assignment).ended_by,
    'endedReason', (p_assignment).ended_reason,
    'source', (p_assignment).source,
    'siteTrainingStatus', (p_assignment).site_training_status,
    'commitmentStatus', (p_assignment).commitment_status,
    'ppeStatus', (p_assignment).ppe_status,
    'toolboxStatus', (p_assignment).toolbox_status,
    'isLocked', (p_assignment).is_locked,
    'lockReason', (p_assignment).lock_reason,
    'eligibilityStatus', (p_assignment).eligibility_status,
    'eligibilityCheckedAt', (p_assignment).eligibility_checked_at,
    'createdBy', (p_assignment).created_by,
    'createdAt', (p_assignment).created_at,
    'updatedAt', (p_assignment).updated_at
  );
$$;


--
-- Name: safety_workforce_can_access_worker_storage(uuid, boolean, boolean); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.safety_workforce_can_access_worker_storage(p_worker_id uuid, p_sensitive boolean, p_write boolean) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    p_worker_id is not null
    and public.current_app_user_id() is not null
    and exists (
      select 1
      from public.safety_worker_site_memberships membership
      where membership.worker_id = p_worker_id
        and case
          when p_write then app_private.safety_workforce_can_manage(
            membership.project_id,
            membership.construction_site_id
          )
          when p_sensitive then app_private.safety_workforce_can_view_sensitive(
            membership.project_id,
            membership.construction_site_id
          )
          else app_private.safety_workforce_can_view(
            membership.project_id,
            membership.construction_site_id
          )
        end
    ),
    false
  );
$$;


--
-- Name: safety_workforce_can_manage(text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

