-- Name: safety_workforce_card_json(public.safety_cards); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.safety_workforce_card_json(p_card public.safety_cards) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'id', (p_card).id,
    'assignmentId', (p_card).assignment_id,
    'workerId', (p_card).worker_id,
    'projectId', (p_card).project_id,
    'constructionSiteId', (p_card).construction_site_id,
    'contractorId', (p_card).contractor_id,
    'templateId', (p_card).template_id,
    'cardCode', (p_card).card_code,
    'qrToken', (p_card).qr_token,
    'issuedAt', (p_card).issued_at,
    'expiresAt', (p_card).expires_at,
    'status', (p_card).status,
    'printedCount', (p_card).printed_count,
    'revokedReason', (p_card).revoked_reason,
    'createdBy', (p_card).created_by,
    'createdAt', (p_card).created_at,
    'updatedAt', (p_card).updated_at
  );
$$;


--
-- Name: safety_workforce_detail_for_membership(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.safety_workforce_detail_for_membership(p_membership_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_membership public.safety_worker_site_memberships%rowtype;
begin
  select membership.*
  into v_membership
  from public.safety_worker_site_memberships membership
  where membership.id = p_membership_id;

  if v_membership.id is null then
    raise exception 'SAFETY_SCOPE_MISMATCH: membership not found'
      using errcode = '42501';
  end if;

  return app_private.get_safety_site_worker_detail(
    v_membership.project_id,
    v_membership.construction_site_id,
    v_membership.id,
    true
  );
end;
$$;


--
-- Name: safety_workforce_document_readiness(uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.safety_workforce_document_readiness(p_worker_id uuid, p_document_type text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select case
      when document.status = 'rejected' then 'rejected'
      when document.status in ('missing', 'expired') then document.status
      when document.expiry_date is not null and document.expiry_date < current_date then 'expired'
      when jsonb_array_length(coalesce(document.attachments, '[]'::jsonb)) = 0 then 'missing'
      else 'valid'
    end
    from public.safety_worker_documents document
    where document.worker_id = p_worker_id
      and document.document_type = p_document_type
    order by document.expiry_date desc nulls last, document.created_at desc, document.id desc
    limit 1
  ), 'missing');
$$;


--
-- Name: safety_workforce_has_canonical_identity_document(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.safety_workforce_has_canonical_identity_document(p_worker_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.safety_worker_documents document
    where document.worker_id = p_worker_id
      and document.document_type in ('identity_front', 'identity_back')
      and document.status not in ('missing', 'expired', 'rejected')
      and jsonb_array_length(coalesce(document.attachments, '[]'::jsonb)) > 0
  );
$$;


--
-- Name: safety_workforce_mask_identity(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.safety_workforce_mask_identity(p_worker_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when worker.identity_number_normalized is null then '-'
    when length(worker.identity_number_normalized) <= 4 then repeat('*', length(worker.identity_number_normalized))
    else repeat('*', length(worker.identity_number_normalized) - 4) || right(worker.identity_number_normalized, 4)
  end
  from public.safety_worker_profiles worker
  where worker.id = p_worker_id;
$$;


--
-- Name: safety_workforce_normalize_identity(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.safety_workforce_normalize_identity(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select nullif(upper(regexp_replace(trim(coalesce(p_value, '')), '[^[:alnum:]]', '', 'g')), '');
$$;


--
-- Name: safety_workforce_profile_readiness(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.safety_workforce_profile_readiness(p_worker_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when worker.id is null
      or worker.status <> 'active'
      or nullif(trim(worker.full_name), '') is null
      or nullif(trim(worker.worker_code), '') is null
      or worker.photo_attachment = 'null'::jsonb
      or worker.identity_number_normalized is null
      or (
        jsonb_array_length(coalesce(worker.identity_attachments, '[]'::jsonb)) = 0
        and not app_private.safety_workforce_has_canonical_identity_document(worker.id)
      )
    then 'missing'
    else 'valid'
  end
  from public.safety_worker_profiles worker
  where worker.id = p_worker_id;
$$;


--
-- Name: save_business_role_impl(uuid, text, text, text, jsonb, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.save_business_role_impl(p_role_template_id uuid, p_code text, p_name text, p_description text, p_items jsonb, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_actor_user_id uuid;
  v_role public.role_permission_templates%rowtype;
  v_role_id uuid := p_role_template_id;
  v_code text;
  v_before_items jsonb := '[]'::jsonb;
  v_after_items jsonb := '[]'::jsonb;
  v_before jsonb := '{}'::jsonb;
  v_after jsonb := '{}'::jsonb;
begin
  v_actor_user_id := app_private.assert_authorization_permission(
    'system.authorization.manage_roles'
  );

  if jsonb_typeof(coalesce(p_items, '[]'::jsonb)) <> 'array'
    or char_length(btrim(coalesce(p_name, ''))) < 3
    or char_length(btrim(coalesce(p_reason, ''))) < 10
  then
    raise exception 'Invalid Business Role command'
      using errcode = '22023';
  end if;

  if p_role_template_id is not null then
    select *
    into v_role
    from public.role_permission_templates
    where id = p_role_template_id
    for update;

    if v_role.id is null then
      raise exception 'Business Role does not exist'
        using errcode = '23503';
    end if;

    if v_role.is_system then
      raise exception 'System Business Roles are seed-controlled'
        using errcode = '42501';
    end if;
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(coalesce(p_items, '[]'::jsonb)) item(
      permission_code text,
      scope_type text,
      scope_id text
    )
    left join public.permission_actions action_row
      on action_row.permission_code = item.permission_code
     and action_row.is_active
    where action_row.permission_code is null
       or coalesce(nullif(item.scope_type, ''), 'global') <> all(action_row.scope_modes)
       or (
         coalesce(nullif(item.scope_type, ''), 'global') = 'global'
         and coalesce(nullif(item.scope_id, ''), '*') <> '*'
       )
       or (
         coalesce(nullif(item.scope_type, ''), 'global') <> 'global'
         and btrim(coalesce(item.scope_id, '')) = ''
       )
  ) then
    raise exception 'Business Role contains an unknown permission or unsupported scope'
      using errcode = '23514';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(coalesce(p_items, '[]'::jsonb)) item(
      permission_code text,
      scope_type text,
      scope_id text
    )
    group by
      item.permission_code,
      coalesce(nullif(item.scope_type, ''), 'global'),
      coalesce(nullif(item.scope_id, ''), '*')
    having count(*) > 1
  ) then
    raise exception 'Duplicate Business Role permission item'
      using errcode = '23505';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(coalesce(p_items, '[]'::jsonb)) item(permission_code text)
    where item.permission_code = 'system.settings.manage'
  ) then
    raise exception 'System identity permissions are seed-controlled'
      using errcode = '42501';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'permissionCode', item.permission_code,
        'scopeType', item.scope_type,
        'scopeId', item.scope_id,
        'sortOrder', item.sort_order
      )
      order by item.permission_code, item.scope_type, item.scope_id
    ),
    '[]'::jsonb
  )
  into v_before_items
  from public.role_permission_template_items item
  where item.template_id = p_role_template_id;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'permissionCode', item.permission_code,
        'scopeType', item.scope_type,
        'scopeId', item.scope_id,
        'sortOrder', item.sort_order
      )
      order by item.permission_code, item.scope_type, item.scope_id
    ),
    '[]'::jsonb
  )
  into v_after_items
  from (
    select
      item.permission_code,
      coalesce(nullif(item.scope_type, ''), 'global') as scope_type,
      coalesce(nullif(item.scope_id, ''), '*') as scope_id,
      coalesce(item.sort_order, 0) as sort_order
    from jsonb_to_recordset(coalesce(p_items, '[]'::jsonb)) item(
      permission_code text,
      scope_type text,
      scope_id text,
      sort_order integer
    )
  ) item;

  if v_role.id is not null
    and v_before_items is distinct from v_after_items
    and exists (
      select 1
      from public.principal_role_assignments assignment_row
      where assignment_row.role_template_id = v_role.id
      for update
    )
  then
    raise exception 'Assigned Business Role permissions are immutable; create a new role and reassign principals'
      using errcode = '55000';
  end if;

  if v_role.id is null then
    v_code := trim(both '_' from regexp_replace(
      upper(btrim(coalesce(p_code, ''))),
      '[^A-Z0-9]+',
      '_',
      'g'
    ));

    if v_code !~ '^[A-Z][A-Z0-9_]*$' then
      raise exception 'Invalid Business Role code'
        using errcode = '22023';
    end if;

    v_role_id := gen_random_uuid();
    insert into public.role_permission_templates (
      id,
      code,
      name,
      description,
      is_active,
      is_system,
      version,
      created_by
    )
    values (
      v_role_id,
      v_code,
      btrim(p_name),
      nullif(btrim(coalesce(p_description, '')), ''),
      true,
      false,
      1,
      v_actor_user_id
    );
  else
    v_code := v_role.code;
    v_before := jsonb_build_object(
      'id', v_role.id,
      'code', v_role.code,
      'name', v_role.name,
      'description', v_role.description,
      'version', v_role.version,
      'items', v_before_items
    );

    update public.role_permission_templates
    set name = btrim(p_name),
        description = nullif(btrim(coalesce(p_description, '')), ''),
        version = version + 1,
        updated_at = now()
    where id = v_role_id;
  end if;

  if v_role.id is null or v_before_items is distinct from v_after_items then
    delete from public.role_permission_template_items
    where template_id = v_role_id;

    insert into public.role_permission_template_items (
      template_id,
      permission_code,
      scope_type,
      scope_id,
      sort_order
    )
    select
      v_role_id,
      item.permission_code,
      coalesce(nullif(item.scope_type, ''), 'global'),
      coalesce(nullif(item.scope_id, ''), '*'),
      coalesce(item.sort_order, 0)
    from jsonb_to_recordset(coalesce(p_items, '[]'::jsonb)) item(
      permission_code text,
      scope_type text,
      scope_id text,
      sort_order integer
    );
  end if;

  select jsonb_build_object(
    'id', role_row.id,
    'code', role_row.code,
    'name', role_row.name,
    'description', role_row.description,
    'version', role_row.version,
    'items', v_after_items
  )
  into v_after
  from public.role_permission_templates role_row
  where role_row.id = v_role_id;

  insert into public.permission_audit_events (
    actor_user_id,
    target_user_id,
    event_type,
    before_grants,
    after_grants,
    metadata
  )
  values (
    v_actor_user_id,
    null,
    case
      when v_role.id is null then 'business_role_created'
      else 'business_role_permissions_changed'
    end,
    v_before,
    v_after,
    jsonb_build_object(
      'roleTemplateId', v_role_id,
      'reason', btrim(p_reason)
    )
  );

  return v_role_id;
end;
$_$;


--
-- Name: save_material_po_batch_draft(text, uuid, date, numeric, text, text, jsonb, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.save_material_po_batch_draft(p_purchase_order_id text, p_delivery_batch_id uuid, p_planned_delivery_date date, p_vat_rate numeric, p_variance_reason text, p_note text, p_lines jsonb, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_po public.purchase_orders%rowtype;
  v_batch public.purchase_order_delivery_batches%rowtype;
  v_line jsonb;
  v_line_key text;
  v_item_id text;
  v_stock_qty numeric;
  v_purchase_qty numeric;
  v_price numeric;
  v_delivery_no integer;
  v_line_count integer := 0;
begin
  if p_actor_user_id is null
     or public.current_app_user_id() is null
     or p_actor_user_id <> public.current_app_user_id() then
    raise exception 'Người thực hiện lệnh không hợp lệ.' using errcode = '42501';
  end if;
  if jsonb_typeof(coalesce(p_lines, '[]'::jsonb)) <> 'array'
     or jsonb_array_length(coalesce(p_lines, '[]'::jsonb)) = 0 then
    raise exception 'Đợt giao phải có ít nhất một dòng vật tư.' using errcode = '22023';
  end if;
  if coalesce(p_vat_rate, 0) < 0 or coalesce(p_vat_rate, 0) > 100 then
    raise exception 'Thuế VAT phải trong khoảng 0 đến 100.' using errcode = '22023';
  end if;

  select * into v_po
  from public.purchase_orders po
  where po.id = p_purchase_order_id
  for update;
  if not found then
    raise exception 'Không tìm thấy PO.' using errcode = '22023';
  end if;
  if v_po.source_mode <> 'from_request' or v_po.purchase_mode <> 'multiple' then
    raise exception 'Chỉ lập đợt riêng cho PO vật tư giao nhiều lần.' using errcode = '22023';
  end if;
  if v_po.status in ('cancelled', 'closed', 'delivered') then
    raise exception 'PO đã kết thúc nên không thể lập thêm đợt giao.' using errcode = '22023';
  end if;
  perform app_private.assert_project_permission_room_action(
    v_po.project_id,
    v_po.construction_site_id,
    'material_po',
    'edit',
    p_actor_user_id
  );

  if p_delivery_batch_id is null then
    select coalesce(max(batch.delivery_no), 0) + 1
    into v_delivery_no
    from public.purchase_order_delivery_batches batch
    where batch.purchase_order_id = v_po.id;

    insert into public.purchase_order_delivery_batches (
      purchase_order_id, project_id, construction_site_id,
      supplier_id, supplier_name_snapshot, delivery_no,
      planned_delivery_date, status, approval_status,
      fulfillment_mode, vat_rate, variance_reason, note, created_by
    ) values (
      v_po.id, v_po.project_id, v_po.construction_site_id,
      v_po.vendor_id, v_po.vendor_name, v_delivery_no,
      p_planned_delivery_date, 'planned', 'draft',
      v_po.fulfillment_mode, coalesce(p_vat_rate, 0),
      nullif(trim(coalesce(p_variance_reason, '')), ''),
      nullif(trim(coalesce(p_note, '')), ''),
      p_actor_user_id
    ) returning * into v_batch;
  else
    select * into v_batch
    from public.purchase_order_delivery_batches batch
    where batch.id = p_delivery_batch_id
      and batch.purchase_order_id = v_po.id
    for update;
    if not found then
      raise exception 'Không tìm thấy đợt giao cần sửa.' using errcode = '22023';
    end if;
    if coalesce(v_batch.approval_status, 'draft') not in ('draft', 'revision_requested', 'rejected')
       or v_batch.wms_transaction_id is not null
       or v_batch.status <> 'planned' then
      raise exception 'Đợt đã gửi duyệt hoặc đã tạo WMS nên không thể sửa.' using errcode = '22023';
    end if;

    update public.purchase_order_delivery_batches
    set supplier_id = v_po.vendor_id,
        supplier_name_snapshot = v_po.vendor_name,
        planned_delivery_date = p_planned_delivery_date,
        vat_rate = coalesce(p_vat_rate, 0),
        variance_reason = nullif(trim(coalesce(p_variance_reason, '')), ''),
        note = nullif(trim(coalesce(p_note, '')), ''),
        approval_status = 'draft',
        approval_decided_by = null,
        approval_decided_at = null,
        approval_decision_note = null,
        updated_at = now()
    where id = v_batch.id
    returning * into v_batch;

    delete from public.purchase_order_delivery_lines
    where delivery_batch_id = v_batch.id;
  end if;

  for v_line in
    select value from jsonb_array_elements(p_lines) line(value)
  loop
    v_line_key := nullif(coalesce(
      v_line ->> 'purchaseOrderLineId', v_line ->> 'purchase_order_line_id'
    ), '');
    v_item_id := nullif(coalesce(v_line ->> 'itemId', v_line ->> 'item_id'), '');
    v_stock_qty := coalesce(nullif(coalesce(
      v_line ->> 'stockQty', v_line ->> 'requestQty', v_line ->> 'stock_planned_qty'
    ), '')::numeric, 0);
    v_purchase_qty := coalesce(nullif(coalesce(
      v_line ->> 'purchaseQty', v_line ->> 'planned_qty'
    ), '')::numeric, 0);
    v_price := coalesce(nullif(coalesce(
      v_line ->> 'purchaseUnitPrice', v_line ->> 'delivery_unit_price'
    ), '')::numeric, 0);

    if v_line_key is null
       or v_item_id is null
       or v_stock_qty <= 0
       or v_purchase_qty <= 0
       or v_price < 0 then
      raise exception 'Dòng đợt giao thiếu hoặc sai số lượng/đơn giá.' using errcode = '22023';
    end if;
    if not exists (
      select 1
      from jsonb_array_elements(coalesce(v_po.items, '[]'::jsonb)) item(value)
      where coalesce(item.value ->> 'lineId', item.value ->> 'itemId') = v_line_key
        and item.value ->> 'itemId' = v_item_id
    ) then
      raise exception 'Dòng đợt giao không thuộc PO.' using errcode = '22023';
    end if;

    insert into public.purchase_order_delivery_lines (
      delivery_batch_id, purchase_order_id, purchase_order_line_id,
      item_id, planned_qty, unit, stock_planned_qty, stock_unit,
      delivery_unit_price
    ) values (
      v_batch.id, v_po.id, v_line_key,
      v_item_id, v_purchase_qty,
      nullif(coalesce(v_line ->> 'purchaseUnit', v_line ->> 'unit'), ''),
      v_stock_qty,
      nullif(coalesce(v_line ->> 'stockUnit', v_line ->> 'requestUnit', v_line ->> 'stock_unit'), ''),
      v_price
    );
    v_line_count := v_line_count + 1;
  end loop;

  return jsonb_build_object(
    'deliveryBatchId', v_batch.id,
    'deliveryNo', v_batch.delivery_no,
    'approvalStatus', 'draft',
    'lineCount', v_line_count
  );
end;
$$;


--
-- Name: save_permission_quick_template_impl(uuid, text, text, text, jsonb, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.save_permission_quick_template_impl(p_template_id uuid, p_code text, p_name text, p_description text, p_permission_codes jsonb, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_actor_user_id uuid;
  v_template_id uuid;
  v_code text := lower(btrim(coalesce(p_code, '')));
  v_name text := btrim(coalesce(p_name, ''));
  v_description text := nullif(btrim(coalesce(p_description, '')), '');
  v_reason text := btrim(coalesce(p_reason, ''));
  v_before jsonb;
  v_after jsonb;
  v_permission_count integer;
begin
  v_actor_user_id := app_private.assert_authorization_permission('system.authorization.manage_grants');

  if v_code = ''
    or v_code !~ '^[a-z0-9][a-z0-9_]{1,62}[a-z0-9]$'
  then
    raise exception 'Valid quick template code required'
      using errcode = '22023';
  end if;

  if char_length(v_name) < 2 then
    raise exception 'Quick template name required'
      using errcode = '22023';
  end if;

  if char_length(v_reason) < 10 then
    raise exception 'Quick template change reason required'
      using errcode = '22023';
  end if;

  if jsonb_typeof(coalesce(p_permission_codes, 'null'::jsonb)) <> 'array' then
    raise exception 'Quick template permissions must be an array'
      using errcode = '22023';
  end if;

  create temporary table pg_temp.quick_template_permission_codes (
    permission_code text primary key,
    sort_order integer not null
  ) on commit drop;

  insert into pg_temp.quick_template_permission_codes (permission_code, sort_order)
  select normalized.permission_code, normalized.sort_order
  from app_private.normalize_permission_quick_template_codes(p_permission_codes) normalized;

  select count(*)
  into v_permission_count
  from pg_temp.quick_template_permission_codes;

  if v_permission_count = 0 then
    raise exception 'Quick template must include at least one permission'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from pg_temp.quick_template_permission_codes supplied
    left join public.permission_actions action
      on action.permission_code = supplied.permission_code
    where action.permission_code is null
      or not action.is_active
      or action.grant_readiness not in ('enforced', 'verified')
  ) then
    raise exception 'Quick template includes a permission that is not grantable'
      using errcode = '23514';
  end if;

  if p_template_id is not null then
    select jsonb_build_object(
      'id', template.id,
      'code', template.code,
      'name', template.name,
      'description', template.description,
      'isActive', template.is_active,
      'permissionCodes', coalesce(items.permission_codes, '[]'::jsonb)
    )
    into v_before
    from public.permission_quick_templates template
    left join lateral (
      select jsonb_agg(item.permission_code order by item.sort_order, item.permission_code) as permission_codes
      from public.permission_quick_template_items item
      where item.template_id = template.id
    ) items on true
    where template.id = p_template_id;

    if v_before is null then
      raise exception 'Quick template does not exist'
        using errcode = '23503';
    end if;
  else
    select jsonb_build_object(
      'id', template.id,
      'code', template.code,
      'name', template.name,
      'description', template.description,
      'isActive', template.is_active,
      'permissionCodes', coalesce(items.permission_codes, '[]'::jsonb)
    )
    into v_before
    from public.permission_quick_templates template
    left join lateral (
      select jsonb_agg(item.permission_code order by item.sort_order, item.permission_code) as permission_codes
      from public.permission_quick_template_items item
      where item.template_id = template.id
    ) items on true
    where template.code = v_code;
  end if;

  insert into public.permission_quick_templates (
    id,
    code,
    name,
    description,
    is_active,
    created_by,
    updated_by
  )
  values (
    coalesce(p_template_id, gen_random_uuid()),
    v_code,
    v_name,
    v_description,
    true,
    v_actor_user_id,
    v_actor_user_id
  )
  on conflict (code) do update
  set name = excluded.name,
      description = excluded.description,
      is_active = true,
      updated_by = excluded.updated_by,
      updated_at = now()
  returning id into v_template_id;

  if p_template_id is not null and v_template_id is distinct from p_template_id then
    raise exception 'Quick template code belongs to another template'
      using errcode = '23505';
  end if;

  delete from public.permission_quick_template_items
  where template_id = v_template_id;

  insert into public.permission_quick_template_items (
    template_id,
    permission_code,
    sort_order
  )
  select v_template_id, supplied.permission_code, supplied.sort_order
  from pg_temp.quick_template_permission_codes supplied
  order by supplied.sort_order, supplied.permission_code;

  select jsonb_build_object(
    'id', template.id,
    'code', template.code,
    'name', template.name,
    'description', template.description,
    'isActive', template.is_active,
    'permissionCodes', coalesce(items.permission_codes, '[]'::jsonb)
  )
  into v_after
  from public.permission_quick_templates template
  left join lateral (
    select jsonb_agg(item.permission_code order by item.sort_order, item.permission_code) as permission_codes
    from public.permission_quick_template_items item
    where item.template_id = template.id
  ) items on true
  where template.id = v_template_id;

  insert into public.permission_audit_events (
    actor_user_id,
    event_type,
    before_grants,
    after_grants,
    metadata
  ) values (
    v_actor_user_id,
    'permission_quick_template_saved',
    coalesce(v_before, '{}'::jsonb),
    v_after,
    jsonb_build_object(
      'reason', v_reason,
      'templateId', v_template_id
    )
  );

  return v_template_id;
end;
$_$;


--
-- Name: save_project_gantt_tasks_impl(uuid, text, text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.save_project_gantt_tasks_impl(p_request_id uuid, p_project_id text, p_construction_site_id text, p_changes jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_actor_user_id uuid;
  v_site_id text := nullif(btrim(coalesce(p_construction_site_id, '')), '');
  v_payload_hash text;
  v_replay jsonb;
  v_result jsonb;
  v_ids text[];
begin
  v_actor_user_id := app_private.assert_project_gantt_action(p_project_id, v_site_id, 'edit');

  if jsonb_typeof(coalesce(p_changes, 'null'::jsonb)) <> 'array'
    or jsonb_array_length(p_changes) = 0 then
    raise exception 'GANTT_INVALID_PAYLOAD' using errcode = '22023';
  end if;

  v_payload_hash := md5(jsonb_build_object(
    'projectId', p_project_id,
    'constructionSiteId', v_site_id,
    'changes', p_changes
  )::text);
  v_replay := app_private.begin_project_gantt_command(
    v_actor_user_id, p_request_id, 'save_project_gantt_tasks', v_payload_hash
  );
  if v_replay is not null then return v_replay; end if;

  select array_agg(change ->> 'id' order by change ->> 'id')
  into v_ids
  from jsonb_array_elements(p_changes) change;

  if exists (
    select 1 from unnest(v_ids) id
    where nullif(btrim(coalesce(id, '')), '') is null
  ) or cardinality(v_ids) <> (select count(distinct id) from unnest(v_ids) id) then
    raise exception 'GANTT_INVALID_PAYLOAD' using errcode = '22023';
  end if;

  if exists (
    select 1 from jsonb_array_elements(p_changes) change
    where change ?| array[
      'gate_status', 'gate_approved_by', 'gate_approved_at',
      'code', 'quantity', 'unit', 'unit_price', 'total_price',
      'completed_quantity', 'contract_item_id', 'created_at',
      'updated_at', 'row_version', 'project_id', 'construction_site_id'
    ]
      or exists (
        select 1 from jsonb_array_elements(coalesce(change -> 'dependencies', '[]'::jsonb)) dependency
        where dependency ? 'requires_gate_approval'
      )
  ) then
    raise exception 'GANTT_GATE_METADATA_IMMUTABLE' using errcode = '23514';
  end if;

  perform task.id
  from public.project_tasks task
  where task.id = any(v_ids)
  order by task.id
  for update;

  if exists (
    select 1 from public.project_tasks task
    where task.id = any(v_ids)
      and (
        task.project_id is distinct from p_project_id
        or task.construction_site_id is distinct from v_site_id
      )
  ) then
    raise exception 'GANTT_SCOPE_MISMATCH' using errcode = '23514';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_changes) change
    join public.project_tasks task on task.id = change ->> 'id'
    where nullif(change ->> 'expected_row_version', '') is null
      or (change ->> 'expected_row_version')::bigint <> task.row_version
  ) then
    raise exception 'GANTT_STALE_VERSION' using errcode = '40001';
  end if;

  if exists (
    select 1 from jsonb_array_elements(p_changes) change
    left join public.project_tasks task on task.id = change ->> 'id'
    where task.id is null
      and coalesce((change ->> 'expected_row_version')::bigint, 0) <> 0
  ) then
    raise exception 'GANTT_STALE_VERSION' using errcode = '40001';
  end if;

  if exists (
    select 1 from jsonb_array_elements(p_changes) change
    where nullif(btrim(coalesce(change ->> 'name', '')), '') is null
      or coalesce(change ->> 'start_date', '') !~ '^\d{4}-\d{2}-\d{2}$'
      or coalesce(change ->> 'end_date', '') !~ '^\d{4}-\d{2}-\d{2}$'
      or case
        when coalesce(change ->> 'start_date', '') ~ '^\d{4}-\d{2}-\d{2}$'
          and coalesce(change ->> 'end_date', '') ~ '^\d{4}-\d{2}-\d{2}$'
        then (change ->> 'start_date')::date > (change ->> 'end_date')::date
        else false
      end
      or coalesce((change ->> 'duration')::integer, 0) < 0
      or coalesce((change ->> 'progress')::numeric, 0) < 0
      or coalesce(change ->> 'progress_mode', 'manual') not in (
        'manual', 'derived_from_acceptance', 'daily_log', 'children_auto', 'weekly_report'
      )
  ) then
    raise exception 'GANTT_INVALID_DATES' using errcode = '22007';
  end if;

  if exists (
    select 1 from jsonb_array_elements(p_changes) change
    where nullif(change ->> 'parent_id', '') = change ->> 'id'
      or (
        nullif(change ->> 'parent_id', '') is not null
        and not (nullif(change ->> 'parent_id', '') = any(v_ids))
        and not exists (
          select 1 from public.project_tasks parent
          where parent.id = nullif(change ->> 'parent_id', '')
            and parent.project_id = p_project_id
            and parent.construction_site_id is not distinct from v_site_id
        )
      )
  ) then
    raise exception 'GANTT_HIERARCHY_INVALID' using errcode = '23514';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_changes) change
    cross join lateral jsonb_array_elements(coalesce(change -> 'dependencies', '[]'::jsonb)) dependency
    where nullif(dependency ->> 'task_id', '') is null
      or dependency ->> 'task_id' = change ->> 'id'
      or coalesce(dependency ->> 'type', '') not in ('FS', 'SS', 'FF', 'SF')
      or (
        not (dependency ->> 'task_id' = any(v_ids))
        and not exists (
          select 1 from public.project_tasks predecessor
          where predecessor.id = dependency ->> 'task_id'
            and predecessor.project_id = p_project_id
            and predecessor.construction_site_id is not distinct from v_site_id
        )
      )
  ) then
    raise exception 'GANTT_DEPENDENCY_INVALID' using errcode = '23514';
  end if;

  if exists (
    select 1 from jsonb_array_elements(p_changes) change
    cross join lateral unnest(
      array_remove(
        coalesce(array(select jsonb_array_elements_text(change -> 'watchers')), '{}'::text[])
          || array[nullif(change ->> 'assignee_user_id', '')],
        null
      )
    ) actor_user_id
    where not exists (
      select 1
      from public.users user_row
      join public.project_staff staff on staff.user_id = user_row.id::text
      where user_row.id::text = actor_user_id
        and coalesce(user_row.is_active, true)
        and staff.project_id = p_project_id
        and staff.end_date is null
        and (
          v_site_id is null
          or staff.construction_site_id is null
          or staff.construction_site_id = v_site_id
        )
    )
  ) then
    raise exception 'GANTT_INVALID_ASSIGNEE' using errcode = '23514';
  end if;

  insert into public.project_tasks (
    id, project_id, construction_site_id, parent_id, name, start_date, end_date,
    duration, progress, progress_mode, assignee, assignee_user_id, dependencies,
    is_milestone, color, notes, sort_order, lag_time, float_days, is_critical,
    baseline_start, baseline_end, baseline_locked, resource_count, resource_type,
    estimated_cost_per_day, delay_reason, delay_category, baseline_version,
    baseline_change_reason, actual_start_date, actual_end_date, wbs_code,
    fallback_unit, provisional_quantity, watchers
  )
  select
    change ->> 'id', p_project_id, v_site_id, nullif(change ->> 'parent_id', ''),
    btrim(change ->> 'name'), change ->> 'start_date', change ->> 'end_date',
    coalesce((change ->> 'duration')::integer, 1),
    coalesce((change ->> 'progress')::integer, 0),
    coalesce(change ->> 'progress_mode', 'manual'),
    nullif(change ->> 'assignee', ''), nullif(change ->> 'assignee_user_id', ''),
    coalesce(change -> 'dependencies', '[]'::jsonb),
    coalesce((change ->> 'is_milestone')::boolean, false),
    nullif(change ->> 'color', ''), nullif(change ->> 'notes', ''),
    coalesce((change ->> 'sort_order')::integer, 0),
    coalesce((change ->> 'lag_time')::integer, 0),
    coalesce((change ->> 'float_days')::integer, 0),
    coalesce((change ->> 'is_critical')::boolean, false),
    nullif(change ->> 'baseline_start', ''), nullif(change ->> 'baseline_end', ''),
    coalesce((change ->> 'baseline_locked')::boolean, false),
    greatest(coalesce((change ->> 'resource_count')::integer, 1), 0),
    coalesce(nullif(change ->> 'resource_type', ''), 'worker'),
    greatest(coalesce((change ->> 'estimated_cost_per_day')::numeric, 0), 0),
    nullif(change ->> 'delay_reason', ''), nullif(change ->> 'delay_category', ''),
    nullif(change ->> 'baseline_version', ''),
    nullif(change ->> 'baseline_change_reason', ''),
    nullif(change ->> 'actual_start_date', '')::date,
    nullif(change ->> 'actual_end_date', '')::date,
    nullif(btrim(coalesce(change ->> 'wbs_code', '')), ''),
    nullif(btrim(coalesce(change ->> 'fallback_unit', '')), ''),
    greatest(coalesce((change ->> 'provisional_quantity')::numeric, 0), 0),
    coalesce(array(select jsonb_array_elements_text(change -> 'watchers')), '{}'::text[])
  from jsonb_array_elements(p_changes) change
  on conflict (id) do update
  set parent_id = excluded.parent_id,
      name = excluded.name,
      start_date = excluded.start_date,
      end_date = excluded.end_date,
      duration = excluded.duration,
      progress = excluded.progress,
      progress_mode = excluded.progress_mode,
      assignee = excluded.assignee,
      assignee_user_id = excluded.assignee_user_id,
      dependencies = excluded.dependencies,
      is_milestone = excluded.is_milestone,
      color = excluded.color,
      notes = excluded.notes,
      sort_order = excluded.sort_order,
      lag_time = excluded.lag_time,
      float_days = excluded.float_days,
      is_critical = excluded.is_critical,
      baseline_start = excluded.baseline_start,
      baseline_end = excluded.baseline_end,
      baseline_locked = excluded.baseline_locked,
      resource_count = excluded.resource_count,
      resource_type = excluded.resource_type,
      estimated_cost_per_day = excluded.estimated_cost_per_day,
      delay_reason = excluded.delay_reason,
      delay_category = excluded.delay_category,
      baseline_version = excluded.baseline_version,
      baseline_change_reason = excluded.baseline_change_reason,
      actual_start_date = excluded.actual_start_date,
      actual_end_date = excluded.actual_end_date,
      wbs_code = excluded.wbs_code,
      fallback_unit = excluded.fallback_unit,
      provisional_quantity = excluded.provisional_quantity,
      watchers = excluded.watchers;

  if exists (
    with recursive ancestry as (
      select task.id as origin_id, task.parent_id, array[task.id]::text[] as path
      from public.project_tasks task
      where task.project_id = p_project_id
        and task.construction_site_id is not distinct from v_site_id
      union all
      select ancestry.origin_id, parent.parent_id, ancestry.path || parent.id
      from ancestry
      join public.project_tasks parent on parent.id = ancestry.parent_id
      where not parent.id = any(ancestry.path)
    )
    select 1 from ancestry
    where parent_id = any(path)
  ) then
    raise exception 'GANTT_HIERARCHY_CYCLE' using errcode = '23514';
  end if;

  if exists (
    with recursive dependency_graph as (
      select task.id as origin_id,
        dependency ->> 'task_id' as current_id,
        array[task.id]::text[] as path
      from public.project_tasks task
      cross join lateral jsonb_array_elements(coalesce(task.dependencies, '[]'::jsonb)) dependency
      where task.project_id = p_project_id
        and task.construction_site_id is not distinct from v_site_id
      union all
      select graph.origin_id,
        dependency ->> 'task_id',
        graph.path || graph.current_id
      from dependency_graph graph
      join public.project_tasks task on task.id = graph.current_id
      cross join lateral jsonb_array_elements(coalesce(task.dependencies, '[]'::jsonb)) dependency
      where not graph.current_id = any(graph.path)
    )
    select 1 from dependency_graph where current_id = origin_id
  ) then
    raise exception 'GANTT_DEPENDENCY_CYCLE' using errcode = '23514';
  end if;

  if exists (
    select 1
    from public.project_tasks task
    where task.project_id = p_project_id
      and task.construction_site_id is not distinct from v_site_id
      and task.wbs_code is not null
    group by lower(btrim(task.wbs_code))
    having count(*) > 1
  ) then
    raise exception 'GANTT_DUPLICATE_WBS' using errcode = '23505';
  end if;

  if exists (
    select 1 from jsonb_array_elements(p_changes) change
    cross join lateral jsonb_array_elements_text(coalesce(change -> 'contract_item_ids', '[]'::jsonb)) link(contract_item_id)
    where change ? 'contract_item_ids'
      and not exists (
        select 1 from public.contract_items contract_item
        where contract_item.id = link.contract_item_id::uuid
          and contract_item.project_id = p_project_id
          and contract_item.construction_site_id::text is not distinct from v_site_id
      )
  ) then
    raise exception 'GANTT_SCOPE_MISMATCH' using errcode = '23514';
  end if;

  delete from public.task_contract_items link
  using jsonb_array_elements(p_changes) change
  where change ? 'contract_item_ids'
    and link.task_id = change ->> 'id';

  insert into public.task_contract_items (
    task_id, contract_item_id, project_id, construction_site_id
  )
  select distinct change ->> 'id', link.contract_item_id::uuid, p_project_id, v_site_id
  from jsonb_array_elements(p_changes) change
  cross join lateral jsonb_array_elements_text(coalesce(change -> 'contract_item_ids', '[]'::jsonb)) link(contract_item_id)
  where change ? 'contract_item_ids'
  on conflict (task_id, contract_item_id) do nothing;

  select jsonb_build_object(
    'ok', true,
    'requestId', p_request_id,
    'replayed', false,
    'tasks', coalesce(jsonb_agg(to_jsonb(task) order by task.sort_order, task.id), '[]'::jsonb)
  ) into v_result
  from public.project_tasks task
  where task.id = any(v_ids);

  return app_private.finish_project_gantt_command(v_actor_user_id, p_request_id, v_result);
end;
$_$;


--
-- Name: save_project_progress_period_impl(text, text, text, date, jsonb, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.save_project_progress_period_impl(p_project_id text, p_construction_site_id text, p_period_type text, p_period_start date, p_rows jsonb, p_snapshot jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := public.current_app_user_id();
  v_site_id text := nullif(btrim(coalesce(p_construction_site_id, '')), '');
  v_scope_key text;
  v_state public.project_progress_period_states%rowtype;
  v_weekly_frozen boolean;
begin
  v_scope_key := app_private.assert_project_progress_scope_period(
    p_project_id, v_site_id, p_period_type, p_period_start
  );
  perform app_private.assert_project_progress_action(
    v_actor_id, p_project_id, v_site_id, 'edit'
  );
  perform app_private.assert_project_progress_rows(
    p_project_id, v_site_id, p_period_type, p_rows
  );
  perform app_private.assert_project_progress_snapshot(p_snapshot);

  insert into public.project_progress_period_states (
    scope_key, project_id, construction_site_id, period_type, period_start
  ) values (
    v_scope_key, p_project_id, v_site_id, p_period_type, p_period_start
  ) on conflict (scope_key, period_type, period_start) do nothing;

  select state.* into v_state
  from public.project_progress_period_states state
  where state.scope_key = v_scope_key
    and state.period_type = p_period_type
    and state.period_start = p_period_start
  for update;

  if v_state.is_locked then
    raise exception 'Kỳ tiến độ đã được chốt. Hãy mở chốt trước khi sửa.'
      using errcode = '23514';
  end if;

  v_weekly_frozen := app_private.write_project_progress_period_payload(
    v_actor_id, v_scope_key, p_project_id, v_site_id,
    p_period_type, p_period_start, p_rows, p_snapshot
  );

  select state.* into v_state
  from public.project_progress_period_states state
  where state.scope_key = v_scope_key
    and state.period_type = p_period_type
    and state.period_start = p_period_start;

  return jsonb_build_object(
    'state', app_private.project_progress_period_state_json(v_state),
    'savedRowCount', jsonb_array_length(p_rows),
    'weeklyAggregateFrozen', v_weekly_frozen
  );
end;
$$;


--
-- Name: save_request_template_draft(jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.save_request_template_draft(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_template public.request_templates%rowtype;
  v_version public.request_template_versions%rowtype;
  v_template_id uuid;
  v_version_number integer;
  v_block jsonb;
  v_fixed_ids uuid[];
  v_expected_updated_at timestamptz;
  v_name text := nullif(trim(p_payload ->> 'name'), '');
  v_form_schema jsonb := coalesce(p_payload -> 'formSchema', '[]'::jsonb);
  v_usage_scope jsonb := coalesce(p_payload -> 'usageScope', '{}'::jsonb);
  v_blocks jsonb := coalesce(p_payload -> 'blocks', '[]'::jsonb);
  v_watcher_ids jsonb := coalesce(p_payload -> 'watcherUserIds', '[]'::jsonb);
begin
  if v_actor is null or not app_private.request_user_can_manage(v_actor) then
    raise exception using errcode = '42501', message = 'REQUEST_TEMPLATE_FORBIDDEN';
  end if;
  if v_name is null then
    raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_NAME_REQUIRED';
  end if;
  if jsonb_typeof(v_form_schema) <> 'array'
     or jsonb_typeof(v_usage_scope) <> 'object'
     or jsonb_typeof(v_blocks) <> 'array'
     or jsonb_typeof(v_watcher_ids) <> 'array' then
    raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_PAYLOAD_INVALID';
  end if;
  if coalesce(p_payload ->> 'flowMode', 'SEQUENTIAL') not in ('SEQUENTIAL', 'PARALLEL')
     or coalesce(p_payload ->> 'completionPolicy', 'ALL') not in ('ALL', 'ANY_ONE') then
    raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_POLICY_INVALID';
  end if;
  if jsonb_array_length(v_blocks) = 0 then
    raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_BLOCK_REQUIRED';
  end if;
  if coalesce(v_usage_scope ->> 'companyWide', 'false') not in ('true', 'false')
     or jsonb_typeof(coalesce(v_usage_scope -> 'orgUnitIds', '[]'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(v_usage_scope -> 'permissionCodes', '[]'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(v_usage_scope -> 'userIds', '[]'::jsonb)) <> 'array' then
    raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_SCOPE_INVALID';
  end if;
  if p_payload ? 'requestSlaHours'
     and nullif(p_payload ->> 'requestSlaHours', '')::numeric < 0 then
    raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_SLA_INVALID';
  end if;

  v_template_id := nullif(p_payload ->> 'templateId', '')::uuid;
  v_expected_updated_at := nullif(p_payload ->> 'expectedUpdatedAt', '')::timestamptz;

  if v_template_id is null then
    insert into public.request_templates(name, description, created_by)
    values (v_name, coalesce(p_payload ->> 'description', ''), v_actor)
    returning * into v_template;
  else
    select * into v_template
    from public.request_templates
    where id = v_template_id
    for update;
    if not found then
      raise exception using errcode = 'P0002', message = 'REQUEST_TEMPLATE_NOT_FOUND';
    end if;
    if v_expected_updated_at is not null
       and v_template.updated_at <> v_expected_updated_at then
      raise exception using errcode = '40001', message = 'CONFLICT';
    end if;
    if v_template.lifecycle_status = 'DEACTIVATED' then
      raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_DEACTIVATED';
    end if;
    update public.request_templates
    set name = v_name,
        description = coalesce(p_payload ->> 'description', ''),
        lifecycle_status = 'DRAFT'
    where id = v_template.id
    returning * into v_template;
  end if;

  select * into v_version
  from public.request_template_versions
  where request_template_id = v_template.id
    and status = 'DRAFT'
  order by version_number desc
  limit 1
  for update;

  if not found then
    select coalesce(max(version_number), 0) + 1
      into v_version_number
    from public.request_template_versions
    where request_template_id = v_template.id;
    insert into public.request_template_versions(
      request_template_id, version_number, form_schema, usage_scope,
      flow_mode, completion_policy, request_sla_hours, print_config,
      notification_config, status, created_by
    ) values (
      v_template.id, v_version_number, v_form_schema, v_usage_scope,
      coalesce(p_payload ->> 'flowMode', 'SEQUENTIAL'),
      coalesce(p_payload ->> 'completionPolicy', 'ALL'),
      nullif(p_payload ->> 'requestSlaHours', '')::numeric,
      coalesce(p_payload -> 'printConfig', '{}'::jsonb),
      coalesce(p_payload -> 'notificationConfig', '{}'::jsonb),
      'DRAFT', v_actor
    ) returning * into v_version;
  else
    update public.request_template_versions
    set form_schema = v_form_schema,
        usage_scope = v_usage_scope,
        flow_mode = coalesce(p_payload ->> 'flowMode', 'SEQUENTIAL'),
        completion_policy = coalesce(p_payload ->> 'completionPolicy', 'ALL'),
        request_sla_hours = nullif(p_payload ->> 'requestSlaHours', '')::numeric,
        print_config = coalesce(p_payload -> 'printConfig', '{}'::jsonb),
        notification_config = coalesce(p_payload -> 'notificationConfig', '{}'::jsonb),
        created_by = v_actor
    where id = v_version.id
    returning * into v_version;
    delete from public.request_approval_blocks
    where request_template_version_id = v_version.id;
    delete from public.request_template_watchers
    where request_template_version_id = v_version.id;
  end if;

  for v_block in select value from jsonb_array_elements(v_blocks)
  loop
    if nullif(trim(v_block ->> 'key'), '') is null
       or nullif(trim(v_block ->> 'name'), '') is null
       or coalesce(v_block ->> 'source', '') not in (
         'FIXED_SINGLE', 'FIXED_MULTI', 'DIRECT_MANAGER', 'DYNAMIC_CREATOR_SELECT'
       ) then
      raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_BLOCK_INVALID';
    end if;
    select coalesce(array_agg(value::uuid), '{}'::uuid[])
      into v_fixed_ids
    from jsonb_array_elements_text(coalesce(v_block -> 'fixedUserIds', '[]'::jsonb));
    if coalesce(v_block ->> 'source', '') in ('FIXED_SINGLE', 'FIXED_MULTI')
       and cardinality(v_fixed_ids) = 0 then
      raise exception using errcode = '22023', message = 'REQUEST_APPROVER_REQUIRED';
    end if;
    if exists (
      select 1
      from unnest(v_fixed_ids) as target_user(fixed_id)
      left join public.users app_user on app_user.id = target_user.fixed_id
      where app_user.id is null
         or not coalesce(app_user.is_active, true)
         or coalesce(app_user.account_status, 'ACTIVE') <> 'ACTIVE'
       ) then
      raise exception using errcode = '22023', message = 'REQUEST_APPROVER_INACTIVE';
    end if;
    if coalesce((v_block ->> 'sortOrder')::integer, 0) < 0
       or nullif(v_block ->> 'slaHours', '')::numeric < 0
       or nullif(v_block ->> 'minimumDynamicApprovers', '')::integer < 1 then
      raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_BLOCK_INVALID';
    end if;
    insert into public.request_approval_blocks(
      request_template_version_id, block_key, name, sort_order,
      approver_source, fixed_user_ids, minimum_dynamic_approvers, sla_hours
    ) values (
      v_version.id,
      trim(v_block ->> 'key'),
      trim(v_block ->> 'name'),
      coalesce((v_block ->> 'sortOrder')::integer, 0),
      v_block ->> 'source',
      v_fixed_ids,
      nullif(v_block ->> 'minimumDynamicApprovers', '')::integer,
      nullif(v_block ->> 'slaHours', '')::numeric
    );
  end loop;

  insert into public.request_template_watchers(request_template_version_id, user_id)
  select v_version.id, value::uuid
  from jsonb_array_elements_text(v_watcher_ids)
  on conflict do nothing;

  update public.request_templates
  set current_version_id = null,
      lifecycle_status = 'DRAFT'
  where id = v_template.id
    and current_version_id = v_version.id;
  select * into v_template
  from public.request_templates
  where id = v_template.id;

  return jsonb_build_object(
    'id', v_version.request_template_id,
    'status', v_version.status,
    'versionNumber', v_version.version_number,
    'updatedAt', v_template.updated_at,
    'payload', app_private.request_template_draft_payload(v_version.id)
  );
end;
$$;


--
-- Name: scope_covers(text, text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.scope_covers(p_grant_scope_type text, p_grant_scope_id text, p_requested_scope_type text, p_requested_scope_id text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select
    p_grant_scope_type = 'global'
    or (
      p_grant_scope_type = coalesce(p_requested_scope_type, 'global')
      and (
        coalesce(nullif(p_grant_scope_id, ''), '*') = '*'
        or coalesce(nullif(p_grant_scope_id, ''), '*') = coalesce(nullif(p_requested_scope_id, ''), '*')
      )
    );
$$;


--
-- Name: set_authorization_rollout_flags_impl(boolean, boolean, boolean, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.set_authorization_rollout_flags_impl(p_business_role_resolver_enabled boolean, p_legacy_governance_fallback_disabled boolean, p_admin_business_approval_bypass_disabled boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := public.current_app_user_id();
  v_before jsonb;
  v_after jsonb;
begin
  if (
      p_legacy_governance_fallback_disabled
      or p_admin_business_approval_bypass_disabled
    )
    and not p_business_role_resolver_enabled
  then
    raise exception 'Business Role resolver must be enabled before disabling compatibility fallbacks'
      using errcode = '22023';
  end if;

  if char_length(btrim(coalesce(p_reason, ''))) < 10
    or not exists (
      select 1
      from public.users actor_row
      where actor_row.id = v_actor_user_id
        and actor_row.role = 'ADMIN'
        and actor_row.is_active
        and actor_row.account_status = 'ACTIVE'
    )
    or not app_private.has_permission(
      v_actor_user_id,
      'system.authorization.manage_roles',
      'global',
      '*'
    )
  then
    raise exception 'System Admin and role-management permission required'
      using errcode = '42501';
  end if;

  if p_legacy_governance_fallback_disabled
    or p_admin_business_approval_bypass_disabled
  then
    perform app_private.assert_rollout_operator_continuity(null, null);
  end if;

  perform 1
  from app_private.permission_hardening_settings setting_row
  where setting_row.key in (
    'business_role_resolver_enabled',
    'legacy_governance_fallback_disabled',
    'system_admin_business_approval_bypass_disabled'
  )
  order by setting_row.key
  for update;

  select jsonb_object_agg(setting_row.key, setting_row.value)
  into v_before
  from app_private.permission_hardening_settings setting_row
  where setting_row.key in (
    'business_role_resolver_enabled',
    'legacy_governance_fallback_disabled',
    'system_admin_business_approval_bypass_disabled'
  );

  update app_private.permission_hardening_settings
  set value = case key
        when 'business_role_resolver_enabled'
          then to_jsonb(p_business_role_resolver_enabled)
        when 'legacy_governance_fallback_disabled'
          then to_jsonb(p_legacy_governance_fallback_disabled)
        else to_jsonb(p_admin_business_approval_bypass_disabled)
      end,
      updated_at = now()
  where key in (
    'business_role_resolver_enabled',
    'legacy_governance_fallback_disabled',
    'system_admin_business_approval_bypass_disabled'
  );

  v_after := jsonb_build_object(
    'business_role_resolver_enabled', p_business_role_resolver_enabled,
    'legacy_governance_fallback_disabled', p_legacy_governance_fallback_disabled,
    'system_admin_business_approval_bypass_disabled',
      p_admin_business_approval_bypass_disabled
  );

  if v_before is distinct from v_after then
    insert into public.permission_audit_events (
      actor_user_id,
      target_user_id,
      event_type,
      before_grants,
      after_grants,
      metadata
    )
    values (
      v_actor_user_id,
      v_actor_user_id,
      'authorization_rollout_flags_changed',
      coalesce(v_before, '{}'::jsonb),
      v_after,
      jsonb_build_object('reason', btrim(p_reason))
    );
  end if;

  return v_after;
end;
$$;


--
-- Name: set_hrm_unit_manager_staffing(uuid, uuid, text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.set_hrm_unit_manager_staffing(p_org_unit_id uuid, p_position_id uuid, p_level_code text, p_reports_to_slot_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid;
  v_unit public.org_units%rowtype;
  v_manager_slot_id uuid;
  v_slot_count integer;
  v_level_code text := nullif(trim(p_level_code), '');
begin
  if not app_private.current_user_has_hrm_template_permission('hrm.staffing.set_manager') then
    raise exception using errcode = '42501', message = 'HRM_STAFFING_SET_MANAGER_REQUIRED';
  end if;
  v_actor_id := public.current_app_user_id();
  if v_actor_id is null then
    raise exception using errcode = '42501', message = 'HRM_ACTIVE_ACTOR_REQUIRED';
  end if;

  select * into v_unit
  from public.org_units
  where id = p_org_unit_id and is_active
  for update;
  if v_unit.id is null then
    raise exception using errcode = '22023', message = 'HRM_ACTIVE_ORG_UNIT_NOT_FOUND';
  end if;

  if not exists (
    select 1 from public.hrm_positions position
    where position.id = p_position_id and position.is_active
  ) then
    raise exception using errcode = '22023', message = 'HRM_ACTIVE_POSITION_NOT_FOUND';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      pg_catalog.concat_ws('|', p_org_unit_id::text, p_position_id::text,
        coalesce(v_level_code, ''), coalesce(p_reports_to_slot_id::text, '')),
      0
    )
  );

  select count(*)::integer, (array_agg(slot.id order by slot.id))[1]
  into v_slot_count, v_manager_slot_id
  from public.hrm_org_position_slots slot
  where slot.source = 'workforce_plan'
    and slot.status = 'ACTIVE'
    and slot.org_unit_id = p_org_unit_id
    and slot.position_id = p_position_id
    and slot.level_code is not distinct from v_level_code
    and slot.reports_to_slot_id is not distinct from p_reports_to_slot_id;

  if v_slot_count <> 1 then
    raise exception using errcode = '22023', message = 'HRM_MANAGER_STAFFING_MUST_HAVE_ONE_SLOT';
  end if;

  update public.org_units
  set manager_slot_id = v_manager_slot_id
  where id = p_org_unit_id;

  insert into public.audit_trail (
    table_name, record_id, action, old_data, new_data, user_id, module,
    description, record_label, entity_type, changed_fields, change_count,
    impact_level
  ) values (
    'org_units', p_org_unit_id::text, 'UPDATE',
    jsonb_build_object('manager_slot_id', v_unit.manager_slot_id),
    jsonb_build_object('manager_slot_id', v_manager_slot_id),
    v_actor_id::text, 'HRM', 'Thiết lập định biên quản lý trực tiếp',
    v_unit.name, 'HRM_UNIT_MANAGER_STAFFING', array['manager_slot_id'], 1, 'high'
  );

  return jsonb_build_object(
    'org_unit_id', p_org_unit_id,
    'manager_slot_id', v_manager_slot_id,
    'position_id', p_position_id,
    'level_code', v_level_code,
    'reports_to_slot_id', p_reports_to_slot_id
  );
end;
$$;


--
-- Name: set_hrm_unit_manager_staffing(uuid, uuid, text, uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.set_hrm_unit_manager_staffing(p_org_unit_id uuid, p_position_id uuid, p_level_code text, p_reports_to_slot_id uuid, p_reason text, p_source_reference text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_result jsonb;
begin
  perform app_private.assert_hrm_mutation_context(p_reason, p_source_reference);
  v_result := app_private.set_hrm_unit_manager_staffing(
    p_org_unit_id, p_position_id, p_level_code, p_reports_to_slot_id
  );
  update public.audit_trail
  set context = coalesce(context, '{}'::jsonb) || jsonb_build_object(
    'reason', pg_catalog.btrim(p_reason),
    'source_reference', pg_catalog.btrim(p_source_reference)
  )
  where xmin = pg_catalog.pg_current_xact_id()::text::xid
    and user_id = public.current_app_user_id()::text
    and entity_type = 'HRM_UNIT_MANAGER_STAFFING';
  return v_result;
end;
$$;


