--
-- Name: set_site_direct_purchase_line_totals(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.set_site_direct_purchase_line_totals() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  new.line_amount := round(coalesce(new.quantity, 0) * coalesce(new.unit_price, 0), 2);
  new.vat_amount := round(new.line_amount * coalesce(new.vat_rate, 0) / 100, 2);
  if new.status in ('accepted', 'adjusted') and coalesce(new.accepted_amount, 0) = 0 then
    new.accepted_amount := new.line_amount + new.vat_amount;
  end if;
  return new;
end;
$$;


--
-- Name: set_supplier_direct_delivery_line_totals(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.set_supplier_direct_delivery_line_totals() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  new.line_amount := round(coalesce(new.quantity, 0) * coalesce(new.unit_price, 0), 2);
  new.vat_amount := round(new.line_amount * coalesce(new.vat_rate, 0) / 100, 2);
  new.total_amount := round(new.line_amount + new.vat_amount, 2);
  if new.status in ('accepted', 'adjusted') and coalesce(new.accepted_amount, 0) = 0 then
    new.accepted_amount := new.total_amount;
  end if;
  if new.status in ('accepted', 'adjusted') and coalesce(new.accepted_quantity, 0) = 0 then
    new.accepted_quantity := new.quantity;
  end if;
  if new.status = 'rejected' then
    new.accepted_amount := 0;
    new.accepted_quantity := 0;
  end if;
  return new;
end;
$$;


--
-- Name: set_user_hr_business_role_impl(uuid, text, timestamp with time zone, text, jsonb, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.set_user_hr_business_role_impl(p_target_user_id uuid, p_target_role_code text, p_expires_at timestamp with time zone, p_reason text, p_warning_acceptances jsonb, p_expected_fingerprint text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := app_private.assert_hrm_role_admin();
  v_target_role_code text := upper(btrim(coalesce(p_target_role_code, '')));
  v_reason text := btrim(coalesce(p_reason, ''));
  v_preview jsonb;
  v_assignment record;
  v_target_template_id uuid;
  v_assignment_id uuid;
begin
  if char_length(v_reason) < 10 then
    raise exception 'HR role change reason must contain at least 10 characters'
      using errcode = '22023';
  end if;

  perform 1
  from public.users target_row
  where target_row.id = p_target_user_id
    and target_row.is_active
    and target_row.account_status = 'ACTIVE'
  for update;

  if not found then
    raise exception 'Active target user required'
      using errcode = '23514';
  end if;

  if app_private.hrm_authorization_fingerprint(p_target_user_id)
      is distinct from p_expected_fingerprint then
    raise exception 'HR authorization changed; reload preview before applying'
      using errcode = '40001';
  end if;

  v_preview := app_private.preview_user_hr_business_role_impl(
    p_target_user_id,
    v_target_role_code,
    p_expires_at
  );

  if jsonb_array_length(coalesce(v_preview -> 'hardDenies', '[]'::jsonb)) > 0 then
    raise exception 'HR role change violates a hard SoD rule'
      using errcode = '42501';
  end if;

  if v_actor_user_id = p_target_user_id
    and v_target_role_code = 'HR_MANAGE'
    and v_preview ->> 'currentRoleCode' is distinct from 'HR_MANAGE'
    and not exists (
      select 1
      from jsonb_array_elements(coalesce(p_warning_acceptances, '[]'::jsonb)) acceptance
      where acceptance ->> 'ruleCode' = 'HRM_ADMIN_SELF_GRANT'
        and coalesce((acceptance ->> 'accepted')::boolean, false)
    )
  then
    raise exception 'System Admin self-grant warning acceptance required'
      using errcode = '22023';
  end if;

  for v_assignment in
    select assignment_row.id
    from public.principal_role_assignments assignment_row
    join public.role_permission_templates template
      on template.id = assignment_row.role_template_id
     and template.code in ('HR', 'HR_MANAGE')
    where assignment_row.principal_type = 'user'
      and assignment_row.principal_id = p_target_user_id
      and assignment_row.status = 'ACTIVE'
    order by assignment_row.created_at
  loop
    perform app_private.revoke_business_role_assignment_impl(v_assignment.id, v_reason);
  end loop;

  if v_target_role_code <> 'NONE' then
    select template.id into v_target_template_id
    from public.role_permission_templates template
    where template.code = v_target_role_code
      and template.is_system
      and template.is_active;

    if v_actor_user_id = p_target_user_id then
      if v_target_role_code <> 'HR_MANAGE' then
        raise exception 'System Admin may self-assign only HR_MANAGE'
          using errcode = '42501';
      end if;

      v_assignment_id := gen_random_uuid();
      insert into public.principal_role_assignments (
        id, principal_type, principal_id, role_template_id, scope_type, scope_id,
        starts_at, expires_at, status, assigned_by, assigned_reason
      ) values (
        v_assignment_id, 'user', p_target_user_id, v_target_template_id,
        'global', '*', now(), p_expires_at, 'ACTIVE', v_actor_user_id, v_reason
      );

      insert into public.permission_audit_events (
        actor_user_id, target_user_id, event_type, before_grants, after_grants, metadata
      ) values (
        v_actor_user_id,
        p_target_user_id,
        'hr_business_role_self_granted',
        coalesce(v_preview -> 'removed', '[]'::jsonb),
        coalesce(v_preview -> 'added', '[]'::jsonb),
        jsonb_build_object(
          'assignmentId', v_assignment_id,
          'roleCode', v_target_role_code,
          'reason', v_reason,
          'warningAcceptances', coalesce(p_warning_acceptances, '[]'::jsonb)
        )
      );
    else
      v_assignment_id := app_private.assign_business_role_impl(
        p_target_user_id,
        v_target_template_id,
        'global',
        '*',
        now(),
        p_expires_at,
        v_reason,
        coalesce(p_warning_acceptances, '[]'::jsonb)
      );
    end if;
  elsif v_actor_user_id = p_target_user_id then
    insert into public.permission_audit_events (
      actor_user_id, target_user_id, event_type, before_grants, after_grants, metadata
    ) values (
      v_actor_user_id,
      p_target_user_id,
      'hr_business_role_self_revoked',
      coalesce(v_preview -> 'removed', '[]'::jsonb),
      '[]'::jsonb,
      jsonb_build_object('reason', v_reason)
    );
  end if;

  return app_private.get_user_hr_authorization_impl(p_target_user_id);
end;
$$;


--
-- Name: storage_has_action(text, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.storage_has_action(p_permission_code text, p_user_id uuid DEFAULT public.current_app_user_id()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_user_id is not null
    and p_permission_code like 'storage.%'
    and app_private.global_has_action(p_permission_code, 'STORAGE', p_user_id);
$$;


--
-- Name: submit_material_po_batch(uuid, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.submit_material_po_batch(p_delivery_batch_id uuid, p_approver_user_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := coalesce(p_actor_user_id, public.current_app_user_id());
  v_batch public.purchase_order_delivery_batches%rowtype;
  v_po public.purchase_orders%rowtype;
begin
  if public.current_app_user_id() is null or v_actor <> public.current_app_user_id() then
    raise exception 'Người thực hiện lệnh không hợp lệ.' using errcode = '42501';
  end if;
  if p_approver_user_id is null then
    raise exception 'Phải chọn người duyệt đợt giao.' using errcode = '22023';
  end if;

  select * into v_batch
  from public.purchase_order_delivery_batches
  where id = p_delivery_batch_id
  for update;
  if not found then
    raise exception 'Không tìm thấy đợt giao.' using errcode = '22023';
  end if;
  select * into v_po
  from public.purchase_orders
  where id = v_batch.purchase_order_id
  for update;

  if coalesce(v_po.source_mode, '') <> 'from_request'
     or coalesce(v_po.purchase_mode, '') <> 'multiple' then
    raise exception 'Chỉ gửi duyệt từng đợt cho PO vật tư giao nhiều lần.' using errcode = '22023';
  end if;
  perform app_private.assert_project_permission_room_action(
    v_po.project_id, v_po.construction_site_id, 'material_po', 'submit', v_actor
  );
  perform app_private.assert_project_permission_room_action(
    v_po.project_id, v_po.construction_site_id, 'material_po', 'approve', p_approver_user_id
  );

  if v_batch.status <> 'planned'
     or v_batch.wms_transaction_id is not null
     or v_batch.qr_token is not null then
    raise exception 'Chỉ gửi duyệt đợt nháp chưa tạo WMS/QR.' using errcode = '22023';
  end if;
  if coalesce(v_batch.approval_status, 'draft') not in ('draft', 'revision_requested', 'rejected') then
    raise exception 'Đợt giao đang chờ duyệt hoặc đã duyệt.' using errcode = '22023';
  end if;
  if v_batch.supplier_id is not null
     and v_batch.supplier_id is distinct from v_po.vendor_id then
    raise exception 'Nhà cung cấp của đợt giao không khớp PO.' using errcode = '22023';
  end if;
  if coalesce(v_batch.vat_rate, v_po.vat_rate, 0) < 0
     or coalesce(v_batch.vat_rate, v_po.vat_rate, 0) > 100 then
    raise exception 'Thuế VAT phải trong khoảng 0 đến 100.' using errcode = '22023';
  end if;
  if not exists (
    select 1
    from public.purchase_order_delivery_lines line
    where line.delivery_batch_id = v_batch.id
      and line.planned_qty > 0
      and line.stock_planned_qty > 0
      and coalesce(line.delivery_unit_price, 0) >= 0
  ) then
    raise exception 'Đợt giao phải có số lượng lớn hơn 0 và đơn giá không âm.' using errcode = '22023';
  end if;
  if exists (
    select 1
    from public.purchase_order_delivery_lines line
    where line.delivery_batch_id = v_batch.id
      and (
        line.planned_qty <= 0
        or line.stock_planned_qty <= 0
        or coalesce(line.delivery_unit_price, 0) < 0
      )
  ) then
    raise exception 'Mọi dòng đợt giao phải có số lượng lớn hơn 0 và đơn giá không âm.'
      using errcode = '22023';
  end if;

  perform app_private.assert_material_po_batch_overage_reason(v_po.id, v_batch.id);

  update public.purchase_order_delivery_batches
  set approval_status = 'pending_approval',
      approval_assignee_user_id = p_approver_user_id,
      approval_requested_by = v_actor,
      approval_requested_at = now(),
      approval_decided_by = null,
      approval_decided_at = null,
      approval_decision_note = null,
      updated_at = now()
  where id = v_batch.id;

  return jsonb_build_object(
    'deliveryBatchId', v_batch.id,
    'approvalStatus', 'pending_approval',
    'approverUserId', p_approver_user_id
  );
end;
$$;


--
-- Name: submit_request(uuid, text, text, jsonb, jsonb, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.submit_request(p_request_template_version_id uuid, p_title text, p_description text, p_form_data jsonb, p_dynamic_approvers_by_block jsonb, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions'
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_template public.request_templates%rowtype;
  v_version public.request_template_versions%rowtype;
  v_workflow_version public.workflow_template_versions%rowtype;
  v_request public.request_instances%rowtype;
  v_instance public.workflow_instances%rowtype;
  v_subject public.workflow_subjects%rowtype;
  v_existing app_private.request_command_idempotency%rowtype;
  v_block record;
  v_dynamic_ids uuid[];
  v_resolved_ids uuid[];
  v_current_user_ids uuid[] := '{}'::uuid[];
  v_watcher_ids uuid[] := '{}'::uuid[];
  v_step_assignees jsonb := '{}'::jsonb;
  v_block_users jsonb := '{}'::jsonb;
  v_result jsonb;
  v_payload_hash text;
  v_request_code text;
  v_first_block_key text;
  v_first_node_id uuid;
  v_first_instance_node_id uuid;
  v_node_id uuid;
  v_instance_node_id uuid;
  v_assignment_round_id uuid := gen_random_uuid();
  v_current_block_keys jsonb := '[]'::jsonb;
  v_request_due_at timestamptz;
  v_block_due_at timestamptz;
  v_min_sort integer;
  v_user_id uuid;
begin
  if v_actor is null or not exists (
    select 1 from public.users app_user
    where app_user.id = v_actor
      and coalesce(app_user.is_active, true)
      and coalesce(app_user.account_status, 'ACTIVE') = 'ACTIVE'
  ) then
    raise exception using errcode = '42501', message = 'REQUEST_AUTHENTICATION_REQUIRED';
  end if;
  if nullif(trim(coalesce(p_idempotency_key, '')), '') is null then
    raise exception using errcode = '22023', message = 'REQUEST_IDEMPOTENCY_KEY_REQUIRED';
  end if;
  if nullif(trim(coalesce(p_title, '')), '') is null then
    raise exception using errcode = '22023', message = 'REQUEST_TITLE_REQUIRED';
  end if;
  if jsonb_typeof(coalesce(p_form_data, '{}'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_dynamic_approvers_by_block, '{}'::jsonb)) <> 'object' then
    raise exception using errcode = '22023', message = 'REQUEST_PAYLOAD_INVALID';
  end if;

  v_payload_hash := encode(
    digest(
      jsonb_build_object(
        'requestTemplateVersionId', p_request_template_version_id,
        'title', p_title,
        'description', coalesce(p_description, ''),
        'formData', coalesce(p_form_data, '{}'::jsonb),
        'dynamicApproversByBlock', coalesce(p_dynamic_approvers_by_block, '{}'::jsonb)
      )::text,
      'sha256'
    ),
    'hex'
  );

  insert into app_private.request_command_idempotency(
    actor_id, idempotency_key, command_name, payload_hash
  ) values (
    v_actor, p_idempotency_key, 'submit_request', v_payload_hash
  ) on conflict (actor_id, idempotency_key) do nothing;

  select * into v_existing
  from app_private.request_command_idempotency
  where actor_id = v_actor
    and idempotency_key = p_idempotency_key
  for update;
  if v_existing.payload_hash <> v_payload_hash
     or v_existing.command_name <> 'submit_request' then
    raise exception using errcode = '40001', message = 'REQUEST_IDEMPOTENCY_CONFLICT';
  end if;
  if v_existing.result is not null then
    return v_existing.result;
  end if;

  select * into v_version
  from public.request_template_versions
  where id = p_request_template_version_id
    and status = 'PUBLISHED'
  for update;
  if not found then
    raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_VERSION_NOT_PUBLISHED';
  end if;
  select * into v_template
  from public.request_templates
  where id = v_version.request_template_id
    and lifecycle_status = 'PUBLISHED'
  for update;
  if not found or not app_private.request_template_version_can_use(v_version.id, v_actor) then
    raise exception using errcode = '42501', message = 'REQUEST_TEMPLATE_FORBIDDEN';
  end if;
  if v_version.workflow_template_version_id is null then
    raise exception using errcode = '22023', message = 'REQUEST_WORKFLOW_VERSION_MISSING';
  end if;
  select * into v_workflow_version
  from public.workflow_template_versions
  where id = v_version.workflow_template_version_id;
  if not found then
    raise exception using errcode = '22023', message = 'REQUEST_WORKFLOW_VERSION_MISSING';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(coalesce(v_version.form_schema, '[]'::jsonb)) field
    where coalesce((field ->> 'required')::boolean, false)
      and (
        not (coalesce(p_form_data, '{}'::jsonb) ? (field ->> 'key'))
        or nullif(trim(coalesce(p_form_data ->> (field ->> 'key'), '')), '') is null
      )
  ) then
    raise exception using errcode = '22023', message = 'REQUEST_REQUIRED_FIELD_MISSING';
  end if;

  select min(sort_order) into v_min_sort
  from public.request_approval_blocks
  where request_template_version_id = v_version.id;
  if v_min_sort is null then
    raise exception using errcode = '22023', message = 'REQUEST_APPROVAL_BLOCK_REQUIRED';
  end if;

  for v_block in
    select block.*
    from public.request_approval_blocks block
    where block.request_template_version_id = v_version.id
    order by block.sort_order, block.block_key
  loop
    v_dynamic_ids := '{}'::uuid[];
    if jsonb_typeof(p_dynamic_approvers_by_block -> v_block.block_key) = 'array' then
      select coalesce(array_agg(value::uuid), '{}'::uuid[])
        into v_dynamic_ids
      from jsonb_array_elements_text(p_dynamic_approvers_by_block -> v_block.block_key);
    end if;
    v_resolved_ids := app_private.resolve_request_block_approvers(
      v_block.id, v_actor, v_dynamic_ids
    );
    v_block_users := v_block_users || jsonb_build_object(
      v_block.block_key, to_jsonb(v_resolved_ids)
    );
    v_current_block_keys := case
      when v_version.flow_mode = 'PARALLEL'
        then v_current_block_keys || jsonb_build_array(v_block.block_key)
      when v_block.sort_order = v_min_sort
        then jsonb_build_array(v_block.block_key)
      else v_current_block_keys
    end;

    v_node_id := null;
    select node.id into v_node_id
    from public.workflow_nodes node
    where node.template_id = v_workflow_version.template_id
      and node.type = 'APPROVAL'::public.workflow_node_type
      and node.config ->> 'requestBlockKey' = v_block.block_key
    order by node.position_x, node.id
    limit 1;
    if v_node_id is null then
      raise exception using errcode = '22023', message = 'REQUEST_WORKFLOW_BLOCK_NODE_MISSING';
    end if;

    v_step_assignees := v_step_assignees || case
      when v_version.flow_mode = 'PARALLEL' or v_block.sort_order = v_min_sort
        then jsonb_build_object(v_node_id::text, to_jsonb(v_resolved_ids))
      else '{}'::jsonb
    end;

    if v_version.flow_mode = 'PARALLEL' or v_block.sort_order = v_min_sort then
      foreach v_user_id in array v_resolved_ids loop
        if v_user_id <> all(coalesce(v_current_user_ids, '{}'::uuid[])) then
          v_current_user_ids := array_append(v_current_user_ids, v_user_id);
        end if;
      end loop;
    end if;
  end loop;

  select block.block_key, node.id
    into v_first_block_key, v_first_node_id
  from public.request_approval_blocks block
  join public.workflow_nodes node
    on node.template_id = v_workflow_version.template_id
   and node.type = 'APPROVAL'::public.workflow_node_type
   and node.config ->> 'requestBlockKey' = block.block_key
  where block.request_template_version_id = v_version.id
    and block.sort_order = v_min_sort
  order by block.block_key, node.id
  limit 1;
  if v_first_node_id is null or cardinality(v_current_user_ids) = 0 then
    raise exception using errcode = '22023', message = 'REQUEST_APPROVER_REQUIRED';
  end if;

  if v_version.request_sla_hours is not null then
    v_request_due_at := now() + make_interval(hours => v_version.request_sla_hours::integer);
  end if;
  v_request_code := app_private.next_request_code();

  insert into public.request_instances(
    category_id, code, title, description, form_data, created_by, status,
    request_template_id, request_template_version_id, workflow_template_version_id,
    form_schema_snapshot, approval_config_snapshot, print_config_snapshot,
    submitted_at, due_at
  ) values (
    null, v_request_code, trim(p_title), coalesce(p_description, ''),
    coalesce(p_form_data, '{}'::jsonb), v_actor, 'PENDING',
    v_template.id, v_version.id, v_version.workflow_template_version_id,
    coalesce(v_version.form_schema, '[]'::jsonb),
    jsonb_build_object(
      'flowMode', v_version.flow_mode,
      'completionPolicy', v_version.completion_policy,
      'blocks', coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', block.id,
          'key', block.block_key,
          'name', block.name,
          'source', block.approver_source,
          'fixedUserIds', to_jsonb(block.fixed_user_ids),
          'slaHours', block.sla_hours,
          'resolvedUserIds', v_block_users -> block.block_key
        ) order by block.sort_order, block.block_key)
        from public.request_approval_blocks block
        where block.request_template_version_id = v_version.id
      ), '[]'::jsonb),
      'assignmentRoundId', v_assignment_round_id
    ),
    coalesce(v_version.print_config, '{}'::jsonb),
    now(), v_request_due_at
  ) returning * into v_request;

  insert into public.workflow_instances(
    template_id, code, title, created_by, current_node_id, status,
    form_data, watchers, step_assignees, template_version_id
  ) values (
    v_workflow_version.template_id, v_request.code, v_request.title, v_actor,
    v_first_node_id, 'RUNNING'::public.workflow_instance_status,
    jsonb_build_object('subjectType', 'request', 'subjectId', v_request.id, 'requestCode', v_request.code),
    coalesce(v_workflow_version.default_watchers, '{}'::text[]),
    v_step_assignees, v_version.workflow_template_version_id
  ) returning * into v_instance;

  perform app_private.project_workflow_snapshot_instance(
    v_instance.id, v_version.workflow_template_version_id, v_workflow_version.template_id
  );
  select instance_node.id into v_first_instance_node_id
  from public.workflow_instance_nodes instance_node
  where instance_node.workflow_instance_id = v_instance.id
    and instance_node.template_node_id = v_first_node_id
  limit 1;
  update public.workflow_instances
  set current_instance_node_id = v_first_instance_node_id,
      updated_at = now()
  where id = v_instance.id
  returning * into v_instance;

  insert into public.workflow_instance_logs(instance_id, node_id, action, acted_by, comment)
  values (v_instance.id, v_first_node_id, 'SUBMITTED'::public.workflow_instance_action, v_actor, null);

  insert into public.workflow_subjects(
    workflow_instance_id, subject_type, subject_id,
    current_assignee_user_id, current_assignee_user_ids,
    current_node_id, current_instance_node_id, template_version_id,
    status, created_by
  ) values (
    v_instance.id, 'request', v_request.id::text,
    v_current_user_ids[1], v_current_user_ids, v_first_node_id,
    v_first_instance_node_id, v_version.workflow_template_version_id,
    'RUNNING', v_actor
  ) returning * into v_subject;

  update public.request_instances
  set workflow_instance_id = v_instance.id,
      workflow_subject_id = v_subject.id
  where id = v_request.id
  returning * into v_request;

  perform app_private.project_workflow_register_participant(
    v_subject.id, v_instance.id, v_actor, 'CREATOR', 'request_creator', v_request.id::text,
    null, null, v_actor
  );
  select coalesce(array_agg(watcher.user_id order by watcher.user_id), '{}'::uuid[])
    into v_watcher_ids
  from public.request_template_watchers watcher
  where watcher.request_template_version_id = v_version.id;
  foreach v_user_id in array v_watcher_ids loop
    perform app_private.project_workflow_register_participant(
      v_subject.id, v_instance.id, v_user_id, 'WATCHER', 'request_template', v_version.id::text,
      null, null, v_actor
    );
  end loop;

  for v_block in
    select block.*
    from public.request_approval_blocks block
    where block.request_template_version_id = v_version.id
    order by block.sort_order, block.block_key
  loop
    if v_version.flow_mode <> 'PARALLEL' and v_block.sort_order <> v_min_sort then
      continue;
    end if;
    select node.id into v_node_id
    from public.workflow_nodes node
    where node.template_id = v_workflow_version.template_id
      and node.type = 'APPROVAL'::public.workflow_node_type
      and node.config ->> 'requestBlockKey' = v_block.block_key
    order by node.position_x, node.id
    limit 1;
    select instance_node.id into v_instance_node_id
    from public.workflow_instance_nodes instance_node
    where instance_node.workflow_instance_id = v_instance.id
      and instance_node.template_node_id = v_node_id
    limit 1;
    select coalesce(array_agg(value::uuid), '{}'::uuid[])
      into v_resolved_ids
    from jsonb_array_elements_text(
      coalesce(
        (select block_snapshot -> 'resolvedUserIds'
         from jsonb_array_elements(
           v_request.approval_config_snapshot -> 'blocks'
         ) block_snapshot
         where block_snapshot ->> 'key' = v_block.block_key),
        '[]'::jsonb
      )
    ) value;
    if v_block.sla_hours is not null then
      v_block_due_at := now() + make_interval(hours => v_block.sla_hours::integer);
    else
      v_block_due_at := null;
    end if;
    foreach v_user_id in array v_resolved_ids loop
      insert into public.workflow_step_assignments(
        workflow_subject_id, workflow_instance_id, node_id, instance_node_id,
        assignee_user_id, assigned_by, status, assigned_at, due_at, sla_hours,
        assignment_source, assignment_group_type, assignment_group_id,
        assignment_round_id, metadata
      ) values (
        v_subject.id, v_instance.id, v_node_id, v_instance_node_id,
        v_user_id, v_actor, 'PENDING', now(), v_block_due_at,
        v_block.sla_hours::integer, v_block.approver_source, 'REQUEST_BLOCK',
        v_block.block_key, v_assignment_round_id,
        jsonb_build_object('requestId', v_request.id, 'requestBlockKey', v_block.block_key)
      );
      perform app_private.project_workflow_register_participant(
        v_subject.id, v_instance.id, v_user_id, 'ASSIGNEE', 'request_block',
        v_block.block_key, v_node_id, v_instance_node_id, v_actor
      );
      insert into app_private.request_notification_outbox(
        event_key, request_id, recipient_user_id, event_type, payload
      ) values (
        'request:' || v_request.id::text || ':SUBMITTED:' || v_user_id::text,
        v_request.id, v_user_id, 'REQUEST_SUBMITTED',
        jsonb_build_object(
          'requestId', v_request.id,
          'requestCode', v_request.code,
          'title', v_request.title,
          'blockKey', v_block.block_key
        )
      ) on conflict (event_key) do nothing;
    end loop;
  end loop;

  v_result := jsonb_build_object(
    'requestId', v_request.id,
    'requestCode', v_request.code,
    'status', v_request.status,
    'workflowInstanceId', v_instance.id,
    'workflowSubjectId', v_subject.id,
    'currentBlockKeys', v_current_block_keys,
    'updatedAt', v_request.updated_at
  );
  update app_private.request_command_idempotency
  set request_id = v_request.id, result = v_result
  where id = v_existing.id;
  return v_result;
end;
$$;


--
-- Name: supplier_direct_delivery_line_statement_ready(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.supplier_direct_delivery_line_statement_ready(p_delivery_line_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select
      dl.status in ('accepted', 'adjusted')
      and (
        coalesce(dl.wms_flow_mode, 'none') <> 'direct_in_out'
        or dl.wms_status = 'exported'
      )
    from public.supplier_direct_delivery_lines dl
    where dl.id = p_delivery_line_id
  ), false);
$$;


--
-- Name: sync_legacy_permission_projection(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_legacy_permission_projection(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := public.current_app_user_id();
  v_before jsonb;
  v_after jsonb;
  v_allowed_modules text[] := '{}'::text[];
  v_admin_modules text[] := '{}'::text[];
  v_allowed_sub_modules jsonb := '{}'::jsonb;
  v_admin_sub_modules jsonb := '{}'::jsonb;
begin
  select jsonb_build_object(
    'allowed_modules', coalesce(u.allowed_modules, '{}'::text[]),
    'admin_modules', coalesce(u.admin_modules, '{}'::text[]),
    'allowed_sub_modules', coalesce(u.allowed_sub_modules, '{}'::jsonb),
    'admin_sub_modules', coalesce(u.admin_sub_modules, '{}'::jsonb)
  )
  into v_before
  from public.users u
  where u.id = p_user_id
  for update;

  if v_before is null then
    raise exception 'Target user does not exist'
      using errcode = '23503';
  end if;

  with active_grants as (
    select
      coalesce(pa.legacy_module_key, pm.legacy_module_key) as legacy_module_key,
      pa.legacy_route,
      (coalesce(pa.legacy_admin_only, false) or pa.action = 'manage') as is_admin_like
    from public.user_permission_grants g
    join public.permission_actions pa
      on pa.permission_code = g.permission_code
      and coalesce(pa.is_active, true)
    join public.permission_modules pm
      on pm.code = pa.module_code
      and coalesce(pm.is_active, true)
    where g.user_id = p_user_id
      and coalesce(g.is_active, false)
      and (g.expires_at is null or g.expires_at > now())
      and coalesce(pa.legacy_module_key, pm.legacy_module_key) is not null
  )
  select
    coalesce(array_agg(distinct legacy_module_key order by legacy_module_key) filter (where not is_admin_like), '{}'::text[]),
    coalesce(array_agg(distinct legacy_module_key order by legacy_module_key) filter (where is_admin_like), '{}'::text[])
  into v_allowed_modules, v_admin_modules
  from active_grants;

  with active_routes as (
    select distinct
      coalesce(pa.legacy_module_key, pm.legacy_module_key) as legacy_module_key,
      pa.legacy_route,
      (coalesce(pa.legacy_admin_only, false) or pa.action = 'manage') as is_admin_like
    from public.user_permission_grants g
    join public.permission_actions pa
      on pa.permission_code = g.permission_code
      and coalesce(pa.is_active, true)
    join public.permission_modules pm
      on pm.code = pa.module_code
      and coalesce(pm.is_active, true)
    where g.user_id = p_user_id
      and coalesce(g.is_active, false)
      and (g.expires_at is null or g.expires_at > now())
      and coalesce(pa.legacy_module_key, pm.legacy_module_key) is not null
      and pa.legacy_route is not null
  ),
  grouped_routes as (
    select
      legacy_module_key,
      is_admin_like,
      jsonb_agg(legacy_route order by legacy_route) as routes
    from active_routes
    group by legacy_module_key, is_admin_like
  )
  select
    coalesce(jsonb_object_agg(legacy_module_key, routes) filter (where not is_admin_like), '{}'::jsonb),
    coalesce(jsonb_object_agg(legacy_module_key, routes) filter (where is_admin_like), '{}'::jsonb)
  into v_allowed_sub_modules, v_admin_sub_modules
  from grouped_routes;

  v_after := jsonb_build_object(
    'allowed_modules', v_allowed_modules,
    'admin_modules', v_admin_modules,
    'allowed_sub_modules', v_allowed_sub_modules,
    'admin_sub_modules', v_admin_sub_modules
  );

  if v_before is distinct from v_after then
    update public.users
    set allowed_modules = v_allowed_modules,
        admin_modules = v_admin_modules,
        allowed_sub_modules = v_allowed_sub_modules,
        admin_sub_modules = v_admin_sub_modules
    where id = p_user_id;

    insert into public.permission_audit_events (
      actor_user_id,
      target_user_id,
      event_type,
      before_grants,
      after_grants,
      metadata
    )
    values (
      v_actor_user_id,
      p_user_id,
      'legacy_projection_synced',
      v_before,
      v_after,
      jsonb_build_object(
        'source', 'phase5_legacy_permission_projection',
        'legacy_event_alias', 'legacy_permission_projection_sync'
      )
    );
  end if;
end;
$$;


--
-- Name: sync_material_issue_document_links(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_material_issue_document_links(p_order_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_order public.material_issue_orders%rowtype;
  v_link_status text;
begin
  if to_regclass('public.project_document_links') is null then
    return;
  end if;

  select * into v_order from public.material_issue_orders where id = p_order_id;
  if not found then return; end if;

  v_link_status := case
    when v_order.status in ('closed', 'cancelled', 'rejected') then 'reversed'
    else 'active'
  end;

  update public.project_document_links
  set status = v_link_status,
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'materialIssueStatus', v_order.status,
        'settledAt', case when v_order.status = 'closed' then now() else null end
      ),
      updated_at = now()
  where (
      source_type = 'material_request'
      and source_id = coalesce(v_order.material_request_id, '')
      and target_type = 'material_issue_order'
      and target_id = v_order.id::text
    )
    or (
      source_type = 'material_issue_order'
      and source_id = v_order.id::text
    )
    or (
      source_type = 'subcontractor_contract'
      and source_id = coalesce(v_order.subcontractor_contract_id, '')
      and target_type = 'material_issue_order'
      and target_id = v_order.id::text
    );
end;
$$;


--
-- Name: sync_material_issue_document_links_trigger(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_material_issue_document_links_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.status is distinct from old.status then
    perform app_private.sync_material_issue_document_links(new.id);
  end if;
  return new;
end;
$$;


--
-- Name: sync_material_issue_from_transaction(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_material_issue_from_transaction() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_item jsonb;
  v_order_id uuid;
  v_line_id uuid;
  v_return_id uuid;
  v_qty numeric;
  v_order public.material_issue_orders%rowtype;
  v_issue_line public.material_issue_lines%rowtype;
begin
  if new.status = old.status then return new; end if;

  for v_item in select value from jsonb_array_elements(coalesce(new.items, '[]'::jsonb))
  loop
    v_order_id := nullif(v_item ->> 'materialIssueOrderId', '')::uuid;
    v_line_id := nullif(v_item ->> 'materialIssueLineId', '')::uuid;
    v_return_id := nullif(v_item ->> 'materialIssueReturnId', '')::uuid;
    v_qty := coalesce(nullif(v_item ->> 'quantity', '')::numeric, 0);
    if v_order_id is null or v_line_id is null or v_qty <= 0 then
      continue;
    end if;

    select * into v_order from public.material_issue_orders where id = v_order_id for update;
    select * into v_issue_line from public.material_issue_lines where id = v_line_id for update;
    if not found then continue; end if;

    if v_return_id is null then
      if new.status = 'COMPLETED' and old.status <> 'COMPLETED' then
        update public.material_issue_lines
        set issued_qty = greatest(issued_qty, v_qty)
        where id = v_line_id;

        update public.material_issue_orders
        set status = 'issued',
            issued_by = coalesce(new.approver_id, public.current_app_user_id()),
            issued_at = coalesce(issued_at, now())
        where id = v_order_id and status in ('wms_pending', 'submitted', 'draft');

        insert into public.material_party_ledger(
          issue_order_id, issue_line_id, source_document_type, source_document_id,
          ledger_type, project_id, construction_site_id, recipient_type, recipient_id,
          recipient_name, item_id, item_name_snapshot, unit, quantity_delta, reason,
          metadata, created_by
        ) values (
          v_order_id, v_line_id, 'transaction', new.id,
          'issue', v_order.project_id, v_order.construction_site_id, v_order.recipient_type, v_order.recipient_id,
          v_order.recipient_name, v_issue_line.item_id, v_issue_line.item_name_snapshot, v_issue_line.unit, v_qty,
          new.note, jsonb_build_object('transactionType', new.type), coalesce(new.approver_id, public.current_app_user_id())
        )
        on conflict do nothing;

        perform app_private.material_issue_refresh_status(v_order_id);
      elsif new.status = 'CANCELLED' and old.status <> 'CANCELLED' then
        update public.material_issue_orders
        set status = 'rejected',
            cancel_reason = coalesce(cancel_reason, 'Phiếu kho xuất cấp bị từ chối/hủy.')
        where id = v_order_id and status = 'wms_pending';
      end if;
    else
      if new.status = 'COMPLETED' and old.status <> 'COMPLETED' then
        update public.material_issue_return_lines
        set return_qty = return_qty
        where issue_return_id = v_return_id and issue_line_id = v_line_id;

        update public.material_issue_lines
        set returned_qty = returned_qty + v_qty
        where id = v_line_id;

        update public.material_issue_returns
        set status = 'completed',
            completed_by = coalesce(new.approver_id, public.current_app_user_id()),
            completed_at = now()
        where id = v_return_id and status = 'pending';

        insert into public.material_party_ledger(
          issue_order_id, issue_line_id, source_document_type, source_document_id,
          ledger_type, project_id, construction_site_id, recipient_type, recipient_id,
          recipient_name, item_id, item_name_snapshot, unit, quantity_delta, reason,
          metadata, created_by
        ) values (
          v_order_id, v_line_id, 'material_issue_return', v_return_id::text,
          'return', v_order.project_id, v_order.construction_site_id, v_order.recipient_type, v_order.recipient_id,
          v_order.recipient_name, v_issue_line.item_id, v_issue_line.item_name_snapshot, v_issue_line.unit, -v_qty,
          new.note, jsonb_build_object('transactionId', new.id), coalesce(new.approver_id, public.current_app_user_id())
        )
        on conflict do nothing;

        perform app_private.material_issue_refresh_status(v_order_id);
      elsif new.status = 'CANCELLED' and old.status <> 'CANCELLED' then
        update public.material_issue_returns
        set status = 'cancelled',
            cancelled_at = now()
        where id = v_return_id and status = 'pending';
      end if;
    end if;
  end loop;

  return new;
end;
$$;


--
-- Name: sync_material_request_downstream_link(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_material_request_downstream_link() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request_id text;
  v_target_type text;
  v_target_id text;
  v_project_id text;
  v_status text;
  v_transaction_id text;
begin
  if tg_table_name = 'material_request_fulfillment_batches' then
    v_request_id := new.material_request_id;
    v_target_type := 'fulfillment_batch';
    v_target_id := new.id::text;
    v_project_id := new.project_id;
    v_status := case when app_private.material_request_batch_is_fully_reversed(new.id)
      then 'reversed' else 'active' end;
  elsif tg_table_name = 'purchase_order_request_lines' then
    v_request_id := coalesce(new.material_request_id, old.material_request_id);
    v_target_type := 'purchase_order';
    v_target_id := coalesce(new.purchase_order_id, old.purchase_order_id);
    v_project_id := coalesce(new.project_id, old.project_id);
    v_status := case when tg_op = 'DELETE' then 'void' else 'active' end;
  elsif tg_table_name = 'transactions' then
    v_request_id := new.related_request_id;
    v_target_type := 'transaction';
    v_target_id := new.id::text;
    select r.project_id into v_project_id from public.requests r where r.id = v_request_id;
    v_status := app_private.material_request_transaction_dependency_status(new.id::text, v_request_id);
  else
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;

  if coalesce(v_request_id, '') <> '' then
    insert into public.project_document_links(
      source_type, source_id, target_type, target_id, project_id,
      relation_type, status, metadata
    )
    values (
      'material_request', v_request_id, v_target_type, v_target_id, v_project_id,
      'downstream', v_status, jsonb_build_object('syncedFrom', tg_table_name)
    )
    on conflict (source_type, source_id, target_type, target_id, relation_type)
    do update set status = excluded.status, project_id = excluded.project_id,
      metadata = coalesce(public.project_document_links.metadata, '{}'::jsonb) || excluded.metadata,
      updated_at = now();
  end if;

  if tg_table_name = 'material_request_fulfillment_batches' then
    for v_transaction_id in
      select distinct transaction_id
      from (
        select nullif(new.transaction_id::text, '') as transaction_id
        union all
        select match[1]
        from regexp_matches(
          coalesce(new.note, ''),
          'Phiếu hoàn kho:[[:space:]]*([^[:space:]|]+)',
          'gi'
        ) match
      ) transaction_ids
      where transaction_id is not null
    loop
      insert into public.project_document_links(
        source_type, source_id, target_type, target_id, project_id,
        relation_type, status, metadata
      )
      values (
        'material_request', v_request_id, 'transaction', v_transaction_id, v_project_id,
        'downstream',
        app_private.material_request_transaction_dependency_status(v_transaction_id, v_request_id),
        jsonb_build_object('syncedFrom', 'material_request_fulfillment_batches')
      )
      on conflict (source_type, source_id, target_type, target_id, relation_type)
      do update set status = excluded.status, project_id = excluded.project_id,
        metadata = coalesce(public.project_document_links.metadata, '{}'::jsonb) || excluded.metadata,
        updated_at = now();
    end loop;
  end if;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


--
-- Name: sync_material_request_receipt_status_v1(text, uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_material_request_receipt_status_v1(p_request_id text, p_actor_user_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app_private'
    AS $$
declare
  v_request public.requests%rowtype;
  v_total_committed numeric := 0;
  v_total_issued numeric := 0;
  v_total_received numeric := 0;
  v_total_closed numeric := 0;
  v_open_need numeric := 0;
  v_has_open_batch boolean := false;
  v_next_status public.request_status;
  v_next_step text;
  v_step_changed boolean := false;
  v_sla_hours integer;
begin
  if coalesce(p_request_id, '') = '' then
    return jsonb_build_object('synced', false, 'reason', 'missing_request_id');
  end if;

  select *
  into v_request
  from public.requests
  where id = p_request_id
  for update;

  if not found then
    return jsonb_build_object('synced', false, 'reason', 'request_not_found', 'requestId', p_request_id);
  end if;

  if v_request.status in (
    'DRAFT'::public.request_status,
    'PENDING'::public.request_status,
    'REJECTED'::public.request_status
  ) then
    return jsonb_build_object(
      'synced', false,
      'reason', 'request_waiting_approval_or_rejected',
      'requestId', p_request_id,
      'status', v_request.status
    );
  end if;

  select coalesce(sum(coalesce(
    nullif(item.value ->> 'requestQty', '')::numeric,
    nullif(item.value ->> 'request_qty', '')::numeric,
    nullif(item.value ->> 'approvedQty', '')::numeric,
    nullif(item.value ->> 'approved_qty', '')::numeric,
    0
  )), 0)
  into v_total_committed
  from jsonb_array_elements(coalesce(v_request.items, '[]'::jsonb)) item(value);

  select
    coalesce(sum(case when b.status not in ('draft', 'cancelled', 'returned') then coalesce(l.issued_qty, 0) else 0 end), 0),
    coalesce(sum(case when b.status = 'received' then coalesce(l.received_qty, 0) else 0 end), 0),
    coalesce(bool_or(b.status in ('issued', 'variance_pending')), false)
  into v_total_issued, v_total_received, v_has_open_batch
  from public.material_request_fulfillment_batches b
  left join public.material_request_fulfillment_lines l on l.batch_id = b.id
  where b.material_request_id = p_request_id;

  if to_regclass('public.material_request_line_need_closures') is not null then
    select coalesce(sum(coalesce(closed_qty, 0)), 0)
    into v_total_closed
    from public.material_request_line_need_closures
    where material_request_id = p_request_id
      and status = 'active';
  end if;

  v_open_need := greatest(0, v_total_committed - v_total_received - v_total_closed);

  v_next_status := case
    when v_total_committed > 0 and v_open_need <= 0 then 'COMPLETED'::public.request_status
    when v_total_issued > 0 or v_total_received > 0 then 'IN_TRANSIT'::public.request_status
    else 'APPROVED'::public.request_status
  end;

  v_next_step := case
    when v_next_status = 'COMPLETED'::public.request_status then 'completed'
    when v_has_open_batch then 'site_quality_check'
    when v_total_received > 0 and v_open_need > 0 then 'batch_planning'
    when v_total_issued > 0 then 'site_quality_check'
    else 'batch_planning'
  end;

  v_step_changed := v_request.workflow_step is distinct from v_next_step;
  v_sla_hours := case
    when v_next_step = 'batch_planning' then 48
    when v_next_step = 'site_quality_check' then 8
    else null
  end;

  update public.requests
  set status = v_next_status,
      workflow_step = v_next_step,
      workflow_step_started_at = case when v_step_changed then now() else workflow_step_started_at end,
      workflow_step_due_at = case
        when v_next_step = 'completed' then null
        when v_step_changed and v_sla_hours is not null then now() + make_interval(hours => v_sla_hours)
        else workflow_step_due_at
      end,
      workflow_step_sla_hours = case
        when v_next_step = 'completed' then null
        when v_step_changed then v_sla_hours
        else workflow_step_sla_hours
      end,
      workflow_step_actor_user_id = coalesce(p_actor_user_id::text, workflow_step_actor_user_id),
      submitted_to_user_id = case when v_next_step = 'completed' then null else submitted_to_user_id end,
      submitted_to_name = case when v_next_step = 'completed' then null else submitted_to_name end,
      submitted_to_permission = case when v_next_step = 'completed' then null else submitted_to_permission end,
      submission_note = case
        when v_next_step = 'completed' then null
        when nullif(trim(coalesce(p_note, '')), '') is not null then p_note
        else submission_note
      end
  where id = p_request_id;

  return jsonb_build_object(
    'synced', true,
    'requestId', p_request_id,
    'status', v_next_status,
    'workflowStep', v_next_step,
    'committedQty', v_total_committed,
    'receivedQty', v_total_received,
    'closedNeedQty', v_total_closed,
    'openNeedQty', v_open_need
  );
end;
$$;


--
-- Name: sync_po_delivery_batch_from_cancelled_wms_v2(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_po_delivery_batch_from_cancelled_wms_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
  if new.source_type = 'po_delivery_batch'
    and new.status = 'CANCELLED'::public.transaction_status
    and coalesce(new.source_id, '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  then
    update public.purchase_order_delivery_batches batch
    set status = 'cancelled',
        quality_result = 'rejected',
        variance_reason = coalesce(nullif(batch.variance_reason, ''), 'Phiếu WMS bị từ chối.'),
        note = case
          when coalesce(batch.note, '') = '' then 'Phiếu WMS ' || new.id || ' bị từ chối.'
          when batch.note ilike '%' || new.id || '%bị từ chối%' then batch.note
          else batch.note || E'\n' || 'Phiếu WMS ' || new.id || ' bị từ chối.'
        end,
        updated_at = now()
    where batch.id = new.source_id::uuid
      and batch.status <> 'cancelled';
  end if;

  return new;
end;
$_$;


--
-- Name: sync_po_delivery_schedule_status_v1(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_po_delivery_schedule_status_v1(p_po_delivery_batch_id uuid DEFAULT NULL::uuid, p_po_delivery_group_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'app_private'
    AS $$
declare
  v_batch_count integer := 0;
  v_all_received boolean := false;
  v_all_rejected boolean := false;
  v_fulfillment_batch_ids text[] := '{}';
  v_next_schedule_status text;
  v_next_group_status text;
begin
  if p_po_delivery_batch_id is not null then
    with related as (
      select
        b.id,
        b.status,
        coalesce(sum(coalesce(l.received_qty, 0)), 0) as received_qty
      from public.material_request_fulfillment_batches b
      left join public.material_request_fulfillment_lines l on l.batch_id = b.id
      where b.po_delivery_batch_id = p_po_delivery_batch_id
      group by b.id, b.status
    )
    select
      count(*)::integer,
      coalesce(bool_and(status = 'received'), false),
      coalesce(bool_and(status in ('cancelled', 'returned') and received_qty <= 0), false),
      coalesce(array_agg(id::text order by id::text), '{}')
    into v_batch_count, v_all_received, v_all_rejected, v_fulfillment_batch_ids
    from related;

    if v_batch_count > 0 then
      v_next_schedule_status := case
        when v_all_received then 'received'
        when v_all_rejected then 'cancelled'
        else 'wms_pending'
      end;

      update public.purchase_order_delivery_batches
      set status = v_next_schedule_status,
          fulfillment_batch_ids = v_fulfillment_batch_ids
      where id = p_po_delivery_batch_id;
    end if;
  end if;

  if p_po_delivery_group_id is not null then
    with related as (
      select
        b.id,
        b.status,
        coalesce(sum(coalesce(l.received_qty, 0)), 0) as received_qty
      from public.material_request_fulfillment_batches b
      left join public.material_request_fulfillment_lines l on l.batch_id = b.id
      where b.po_delivery_group_id = p_po_delivery_group_id
      group by b.id, b.status
    )
    select
      count(*)::integer,
      coalesce(bool_and(status = 'received'), false),
      coalesce(bool_and(status in ('cancelled', 'returned') and received_qty <= 0), false)
    into v_batch_count, v_all_received, v_all_rejected
    from related;

    if v_batch_count > 0 then
      v_next_group_status := case
        when v_all_received then 'received'
        when v_all_rejected then 'cancelled'
        else 'issued'
      end;

      update public.purchase_order_delivery_groups
      set status = v_next_group_status
      where id = p_po_delivery_group_id;
    end if;
  end if;

  return jsonb_build_object(
    'synced', true,
    'poDeliveryBatchId', p_po_delivery_batch_id,
    'poDeliveryGroupId', p_po_delivery_group_id
  );
end;
$$;


--
-- Name: sync_po_supplemental_approval_to_batch(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_po_supplemental_approval_to_batch() RETURNS trigger
