$$;


--
-- Name: sync_project_opening_balance_snapshot_impl(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_project_opening_balance_snapshot_impl(p_opening_balance_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_balance public.project_opening_balances%rowtype;
  v_site_id text;
  v_scope_key text;
  v_week_start date;
  v_snapshot jsonb;
begin
  if public.current_app_user_id() is null or not (
    public.is_admin()
    or app_private.current_user_is_global_wms_keeper()
  ) then
    raise exception 'Chỉ System Admin hoặc thủ kho tổng được đồng bộ snapshot đầu kỳ.'
      using errcode = '42501';
  end if;

  select balance.* into v_balance
  from public.project_opening_balances balance
  where balance.id = p_opening_balance_id
  for update;

  if not found or v_balance.status <> 'locked' then
    raise exception 'Không tìm thấy dữ liệu đầu kỳ đã khóa.' using errcode = '23514';
  end if;

  v_site_id := nullif(btrim(coalesce(v_balance.construction_site_id, '')), '');
  v_week_start := date_trunc('week', v_balance.as_of_date)::date;
  v_scope_key := app_private.assert_project_progress_scope_period(
    v_balance.project_id, v_site_id, 'weekly', v_week_start
  );
  if v_balance.scope_key is distinct from v_scope_key then
    raise exception 'Opening Balance scope does not match its canonical project/site scope'
      using errcode = '23514';
  end if;

  v_snapshot := jsonb_build_object(
    'constructionProgressPercent', v_balance.construction_progress_percent,
    'valueProgressPercent', case
      when v_balance.contract_value > 0 then least(
        100::numeric,
        round(v_balance.recognized_value / v_balance.contract_value * 100)
      )
      else 0::numeric
    end,
    'progressMode', 'opening_balance',
    'suppliedValue', case when v_balance.recognized_value > 0 then v_balance.recognized_value else null end,
    'contractTotalValue', case when v_balance.contract_value > 0 then v_balance.contract_value else null end,
    'purchasedValue', v_balance.purchased_value,
    'issuedValue', v_balance.issued_value,
    'recognizedValue', v_balance.recognized_value,
    'ganttPercent', v_balance.construction_progress_percent,
    'calculatedAt', now()
  );
  perform app_private.assert_project_progress_snapshot(v_snapshot);
  perform app_private.refresh_project_progress_snapshot_impl(
    v_balance.project_id, v_site_id, v_week_start, v_snapshot
  );

  update public.project_opening_balances balance
  set progress_snapshot_status = 'synced',
      progress_snapshot_payload = v_snapshot,
      progress_snapshot_refreshed_at = now()
  where balance.id = p_opening_balance_id;

  return jsonb_build_object(
    'openingBalanceId', v_balance.id,
    'status', 'synced',
    'canRetry', false,
    'scopeKey', v_scope_key,
    'weekStart', v_week_start,
    'refreshedAt', now()
  );
end;
$$;


--
-- Name: sync_purchase_order_archive_dependencies(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_purchase_order_archive_dependencies() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.archived_at is null
    and new.archived_at is not null
    and to_regclass('public.project_document_links') is not null
  then
    update public.project_document_links
    set status = case when status = 'active' then 'archived' else status end,
        metadata = coalesce(metadata, '{}'::jsonb)
          || jsonb_build_object(
            'purchaseOrderArchivedAt', new.archived_at,
            'purchaseOrderArchiveReason', new.archive_reason
          ),
        updated_at = now()
    where (source_type = 'purchase_order' and source_id = new.id)
       or (target_type = 'purchase_order' and target_id = new.id);
  end if;

  return new;
end;
$$;


--
-- Name: sync_purchase_order_request_dependencies(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_purchase_order_request_dependencies() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.project_document_links pdl
  set status = case
        when not exists (
          select 1
          from public.purchase_order_request_lines porl
          where porl.material_request_id = pdl.source_id
            and porl.purchase_order_id = new.id::text
        ) then 'void'
        when lower(coalesce(new.status::text, '')) in ('cancelled', 'canceled', 'returned', 'reversed', 'void')
          then 'reversed' else 'active' end,
      updated_at = now(),
      metadata = coalesce(pdl.metadata, '{}'::jsonb) || jsonb_build_object('syncedFrom', 'purchase_orders')
  where pdl.source_type = 'material_request'
    and pdl.target_type = 'purchase_order'
    and pdl.target_id = new.id::text
    and pdl.relation_type = 'downstream';
  return new;
end;
$$;


--
-- Name: sync_purchase_order_supplier_return_from_transaction(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_purchase_order_supplier_return_from_transaction() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_return public.purchase_order_supplier_returns%rowtype;
  v_po public.purchase_orders%rowtype;
  v_next_items jsonb;
  v_is_fully_returned boolean := false;
begin
  if new.status not in ('COMPLETED'::public.transaction_status, 'CANCELLED'::public.transaction_status) then
    return new;
  end if;

  select * into v_return
  from public.purchase_order_supplier_returns r
  where r.transaction_id = new.id
  for update;
  if not found or v_return.status <> 'pending' then return new; end if;

  if new.status = 'CANCELLED'::public.transaction_status then
    update public.purchase_order_supplier_returns
    set status = 'cancelled', cancelled_at = now()
    where id = v_return.id;
    return new;
  end if;

  update public.purchase_order_supplier_returns
  set status = 'completed', completed_by = new.approver_id, completed_at = now()
  where id = v_return.id;

  select * into v_po
  from public.purchase_orders po
  where po.id = v_return.purchase_order_id
  for update;

  with returned_by_line as (
    select line.purchase_order_line_id, sum(line.return_qty) as returned_qty
    from public.purchase_order_supplier_return_lines line
    join public.purchase_order_supplier_returns r on r.id = line.supplier_return_id
    where r.purchase_order_id = v_return.purchase_order_id
      and r.status = 'completed'
    group by line.purchase_order_line_id
  ),
  po_items as (
    select item.value, item.ordinality,
      coalesce(item.value ->> 'lineId', item.value ->> 'itemId') as line_id
    from jsonb_array_elements(coalesce(v_po.items, '[]'::jsonb)) with ordinality item(value, ordinality)
  )
  select coalesce(jsonb_agg(
    jsonb_set(p.value, '{returnedQty}', to_jsonb(coalesce(r.returned_qty, 0)), true)
    order by p.ordinality
  ), '[]'::jsonb)
  into v_next_items
  from po_items p
  left join returned_by_line r on r.purchase_order_line_id = p.line_id;

  select
    coalesce(bool_and(
      coalesce(nullif(item.value ->> 'receivedQty', '')::numeric, 0) <=
      coalesce(nullif(item.value ->> 'returnedQty', '')::numeric, 0)
    ), false)
    and coalesce(sum(coalesce(nullif(item.value ->> 'receivedQty', '')::numeric, 0)), 0) > 0
  into v_is_fully_returned
  from jsonb_array_elements(v_next_items) item(value);

  update public.purchase_orders
  set items = v_next_items,
      status = case when v_is_fully_returned then 'returned' else status end,
      delivery_note = concat_ws(
        ' | ',
        nullif(delivery_note, ''),
        case when v_is_fully_returned
          then 'Đã hoàn trả đủ hàng cho NCC qua phiếu ' || v_return.return_no
          else 'Đã hoàn trả một phần cho NCC qua phiếu ' || v_return.return_no
        end
      )
  where id = v_return.purchase_order_id;

  -- Do not mutate historical PO receipt fulfillment batches here.
  -- Gross received stays gross; return quantities are displayed beside it.

  return new;
end;
$$;


--
-- Name: sync_safety_equipment_documents_status(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_safety_equipment_documents_status(p_equipment_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_total integer;
  v_done integer;
  v_next_status text;
begin
  if p_equipment_id is null then
    return;
  end if;

  select count(*), count(*) filter (where is_done)
    into v_total, v_done
  from public.safety_equipment_documents
  where equipment_id = p_equipment_id;

  v_next_status := case
    when coalesce(v_total, 0) = 0 then 'missing'
    when v_done = v_total then 'complete'
    else 'partial'
  end;

  update public.safety_equipment
  set documents_status = v_next_status,
      updated_at = now()
  where id = p_equipment_id
    and documents_status is distinct from v_next_status;
end;
$$;


--
-- Name: sync_safety_site_induction_assignment(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_safety_site_induction_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.safety_project_assignments
  set site_training_status = case
        when new.training_type = 'site_rules' and new.status = 'completed' then 'completed'
        when new.training_type = 'site_rules' and new.status = 'expired' then 'expired'
        else site_training_status
      end,
      toolbox_status = case
        when new.training_type = 'toolbox' and new.status = 'completed' then 'completed'
        when new.training_type = 'toolbox' and new.status = 'expired' then 'expired'
        else toolbox_status
      end,
      commitment_status = case
        when new.training_type = 'commitment' and new.status = 'completed' then 'signed'
        else commitment_status
      end,
      ppe_status = case
        when new.training_type = 'ppe' and new.status = 'completed' then 'complete'
        else ppe_status
      end,
      updated_at = now()
  where id = new.assignment_id;
  return new;
end;
$$;


--
-- Name: sync_site_cash_settlement_trace_links(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_site_cash_settlement_trace_links(p_settlement_batch_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_batch public.site_cash_settlement_batches%rowtype;
  v_row record;
begin
  select * into v_batch
  from public.site_cash_settlement_batches
  where id = p_settlement_batch_id;

  if not found then
    return;
  end if;

  for v_row in
    select
      line.source_id,
      line.document_no_snapshot,
      line.approved_amount
    from public.site_cash_settlement_lines line
    where line.settlement_batch_id = p_settlement_batch_id
      and line.source_type = 'site_direct_purchase'
      and nullif(line.source_id, '') is not null
  loop
    perform app_private.upsert_project_document_link(
      'site_direct_purchase',
      v_row.source_id,
      'site_cash_settlement_batch',
      v_batch.id::text,
      v_batch.project_id,
      'settled_by',
      v_batch.status,
      jsonb_build_object(
        'settlementCode', v_batch.code,
        'documentNo', v_row.document_no_snapshot,
        'approvedAmount', v_row.approved_amount
      )
    );
  end loop;

  if v_batch.project_transaction_id is not null then
    perform app_private.upsert_project_document_link(
      'site_cash_settlement_batch',
      v_batch.id::text,
      'project_transaction',
      v_batch.project_transaction_id,
      v_batch.project_id,
      'cashflow',
      v_batch.status,
      jsonb_build_object(
        'settlementCode', v_batch.code,
        'amount', coalesce(v_batch.approved_site_cash_spend, 0) + coalesce(v_batch.staff_reimbursed_amount, 0)
      )
    );
  end if;
end;
$$;


--
-- Name: sync_site_direct_purchase_payment_status(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_site_direct_purchase_payment_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.source_type <> 'site_direct_purchase' then
    return new;
  end if;

  if new.status = 'paid' then
    update public.site_direct_purchases purchase
    set status = 'closed', updated_at = now()
    where purchase.id::text = new.source_id
      and purchase.status = 'reconciled';
  elsif old.status = 'paid' and new.status in ('open', 'payable', 'partial') then
    update public.site_direct_purchases purchase
    set status = 'reconciled', updated_at = now()
    where purchase.id::text = new.source_id
      and purchase.status = 'closed';
  end if;

  return new;
end;
$$;


--
-- Name: sync_supplier_delivery_statement_trace_links(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_supplier_delivery_statement_trace_links(p_statement_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_statement public.supplier_delivery_statements%rowtype;
  v_row record;
begin
  select * into v_statement
  from public.supplier_delivery_statements
  where id = p_statement_id;

  if not found then
    return;
  end if;

  for v_row in
    select distinct
      note.id as delivery_note_id,
      note.code as delivery_note_code,
      note.total_amount as delivery_note_amount
    from public.supplier_delivery_statement_lines sl
    join public.supplier_direct_delivery_notes note on note.id = sl.delivery_note_id
    where sl.statement_id = p_statement_id
  loop
    perform app_private.upsert_project_document_link(
      'supplier_direct_delivery_note',
      v_row.delivery_note_id::text,
      'supplier_delivery_statement',
      v_statement.id::text,
      v_statement.project_id,
      'statement',
      v_statement.status,
      jsonb_build_object(
        'deliveryNoteCode', v_row.delivery_note_code,
        'statementCode', v_statement.code,
        'amount', v_statement.total_amount
      )
    );
  end loop;

  if v_statement.payable_document_id is not null then
    perform app_private.upsert_project_document_link(
      'supplier_delivery_statement',
      v_statement.id::text,
      'supplier_payable_document',
      v_statement.payable_document_id::text,
      v_statement.project_id,
      'recognizes',
      v_statement.status,
      jsonb_build_object(
        'statementCode', v_statement.code,
        'supplierContractId', v_statement.supplier_contract_id,
        'amount', v_statement.total_amount
      )
    );
  end if;
end;
$$;


--
-- Name: sync_supplier_direct_delivery_trace_links(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_supplier_direct_delivery_trace_links(p_note_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_note public.supplier_direct_delivery_notes%rowtype;
  v_row record;
begin
  select * into v_note
  from public.supplier_direct_delivery_notes
  where id = p_note_id;

  if not found then
    return;
  end if;

  perform app_private.upsert_project_document_link(
    'supplier_contract',
    v_note.supplier_contract_id,
    'supplier_direct_delivery_note',
    v_note.id::text,
    v_note.project_id,
    'delivery_note',
    v_note.status,
    jsonb_build_object(
      'code', v_note.code,
      'deliveryTicketNo', v_note.delivery_ticket_no,
      'deliveryDate', v_note.delivery_date,
      'supplierName', v_note.supplier_name_snapshot,
      'amount', v_note.total_amount
    )
  );

  for v_row in
    select
      dl.wms_import_transaction_id as import_transaction_id,
      min(tx.status::text) as transaction_status,
      jsonb_agg(dl.id order by dl.line_no) as line_ids,
      count(*) as line_count
    from public.supplier_direct_delivery_lines dl
    left join public.transactions tx on tx.id = dl.wms_import_transaction_id
    where dl.delivery_note_id = p_note_id
      and dl.wms_import_transaction_id is not null
    group by dl.wms_import_transaction_id
  loop
    perform app_private.upsert_project_document_link(
      'supplier_direct_delivery_note',
      v_note.id::text,
      'wms_transaction',
      v_row.import_transaction_id,
      v_note.project_id,
      'wms_import',
      coalesce(v_row.transaction_status, v_note.status),
      jsonb_build_object(
        'lineIds', v_row.line_ids,
        'lineCount', v_row.line_count,
        'supplierDirectDeliveryNoteCode', v_note.code
      )
    );
  end loop;

  for v_row in
    select
      dl.wms_import_transaction_id as import_transaction_id,
      dl.wms_export_transaction_id as export_transaction_id,
      min(tx.status::text) as transaction_status,
      jsonb_agg(dl.id order by dl.line_no) as line_ids,
      count(*) as line_count
    from public.supplier_direct_delivery_lines dl
    left join public.transactions tx on tx.id = dl.wms_export_transaction_id
    where dl.delivery_note_id = p_note_id
      and dl.wms_import_transaction_id is not null
      and dl.wms_export_transaction_id is not null
    group by dl.wms_import_transaction_id, dl.wms_export_transaction_id
  loop
    perform app_private.upsert_project_document_link(
      'wms_transaction',
      v_row.import_transaction_id,
      'wms_transaction',
      v_row.export_transaction_id,
      v_note.project_id,
      'wms_export',
      coalesce(v_row.transaction_status, v_note.status),
      jsonb_build_object(
        'lineIds', v_row.line_ids,
        'lineCount', v_row.line_count,
        'supplierDirectDeliveryNoteId', v_note.id
      )
    );
  end loop;

  for v_row in
    select distinct
      s.id as statement_id,
      s.code as statement_code,
      s.status as statement_status,
      s.total_amount as statement_total_amount
    from public.supplier_delivery_statement_lines sl
    join public.supplier_delivery_statements s on s.id = sl.statement_id
    where sl.delivery_note_id = p_note_id
  loop
    perform app_private.upsert_project_document_link(
      'supplier_direct_delivery_note',
      v_note.id::text,
      'supplier_delivery_statement',
      v_row.statement_id::text,
      v_note.project_id,
      'statement',
      v_row.statement_status,
      jsonb_build_object(
        'statementCode', v_row.statement_code,
        'amount', v_row.statement_total_amount
      )
    );
  end loop;
end;
$$;


--
-- Name: sync_supplier_direct_delivery_wms_from_transaction(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_supplier_direct_delivery_wms_from_transaction() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_group record;
  v_export_tx_id text;
  v_note_code text;
  v_supplier_name text;
  v_actor_id uuid;
  v_uuid_pattern constant text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
begin
  if tg_op <> 'UPDATE' or new.status is not distinct from old.status then
    return new;
  end if;

  v_actor_id := coalesce(
    new.created_by,
    case
      when new.requester_id::text ~* v_uuid_pattern then new.requester_id::text::uuid
      else null
    end
  );

  if exists (
    select 1
    from public.supplier_direct_delivery_lines dl
    where dl.wms_import_transaction_id = new.id
      and dl.wms_flow_mode = 'direct_in_out'
  ) then
    if upper(coalesce(new.status::text, '')) = 'COMPLETED' then
      update public.supplier_direct_delivery_lines dl
      set wms_status = 'imported', updated_at = now()
      where dl.wms_import_transaction_id = new.id
        and dl.wms_flow_mode = 'direct_in_out'
        and dl.wms_status in ('not_required', 'import_pending', 'blocked');

      for v_group in
        select
          dl.delivery_note_id,
          dl.target_warehouse_id,
          min(note.code) as note_code,
          min(note.supplier_name_snapshot) as supplier_name,
          min(note.supplier_id::text) as supplier_id_text,
          jsonb_agg(
            jsonb_build_object(
              'itemId', dl.item_id,
              'quantity', coalesce(nullif(dl.accepted_quantity, 0), dl.quantity),
              'price', 0,
              'accountingQty', coalesce(nullif(dl.accepted_quantity, 0), dl.quantity),
              'accountingUnit', dl.unit_snapshot,
              'accountingPrice', 0,
              'supplierDirectDeliveryNoteId', dl.delivery_note_id,
              'supplierDirectDeliveryLineId', dl.id,
              'supplierDeliveryWmsFlow', 'direct_in_out'
            )
            order by dl.line_no
          ) as items,
          array_agg(dl.id order by dl.line_no) as line_ids
        from public.supplier_direct_delivery_lines dl
        join public.supplier_direct_delivery_notes note on note.id = dl.delivery_note_id
        where dl.wms_import_transaction_id = new.id
          and dl.wms_flow_mode = 'direct_in_out'
          and dl.wms_status = 'imported'
          and dl.wms_export_transaction_id is null
        group by dl.delivery_note_id, dl.target_warehouse_id
      loop
        v_export_tx_id := 'tx-supplier-delivery-export-' || replace(gen_random_uuid()::text, '-', '');
        v_note_code := coalesce(v_group.note_code, v_group.delivery_note_id::text);
        v_supplier_name := coalesce(v_group.supplier_name, '');

        insert into public.transactions (
          id, type, date, items, source_warehouse_id,
          requester_id, created_by, updated_by, approver_id, status, note,
          related_request_id, business_partner_id, business_partner_name_snapshot,
          source_type, source_id
        )
        values (
          v_export_tx_id,
          'EXPORT',
          now(),
          v_group.items,
          v_group.target_warehouse_id,
          new.requester_id,
          v_actor_id,
          coalesce(new.updated_by, v_actor_id),
          new.approver_id,
          'PENDING',
          trim('Xuất dùng ngay từ phiếu giao HĐ ' || v_note_code || ' ' || v_supplier_name),
          'supplier-direct-delivery:' || v_group.delivery_note_id::text,
          coalesce(new.business_partner_id, nullif(v_group.supplier_id_text, '')),
          coalesce(new.business_partner_name_snapshot, nullif(v_supplier_name, '')),
          'supplier_direct_delivery_note',
          v_group.delivery_note_id::text
        );

        update public.supplier_direct_delivery_lines dl
        set
          wms_export_transaction_id = v_export_tx_id,
          wms_status = 'export_pending',
          updated_at = now()
        where dl.id = any(v_group.line_ids);
      end loop;
    elsif upper(coalesce(new.status::text, '')) = 'CANCELLED' then
      update public.supplier_direct_delivery_lines dl
      set wms_status = 'blocked', updated_at = now()
      where dl.wms_import_transaction_id = new.id
        and dl.wms_flow_mode = 'direct_in_out'
        and dl.wms_status <> 'exported';
    end if;
  end if;

  if exists (
    select 1
    from public.supplier_direct_delivery_lines dl
    where dl.wms_export_transaction_id = new.id
      and dl.wms_flow_mode = 'direct_in_out'
  ) then
    if upper(coalesce(new.status::text, '')) = 'COMPLETED' then
      update public.supplier_direct_delivery_lines dl
      set wms_status = 'exported', updated_at = now()
      where dl.wms_export_transaction_id = new.id
        and dl.wms_flow_mode = 'direct_in_out';
    elsif upper(coalesce(new.status::text, '')) = 'CANCELLED' then
      update public.supplier_direct_delivery_lines dl
      set wms_status = 'blocked', updated_at = now()
      where dl.wms_export_transaction_id = new.id
        and dl.wms_flow_mode = 'direct_in_out'
        and dl.wms_status <> 'exported';
    end if;
  end if;

  return new;
end;
$_$;


--
-- Name: sync_supplier_payable_recognition_transaction(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_supplier_payable_recognition_transaction() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_finance_id text := '';
  v_source_ref text;
  v_recognized_amount numeric(18,2);
begin
  if tg_op = 'DELETE' then
    if old.source_type = 'supplier_delivery_statement' then
      update public.project_transactions
      set
        amount = 0,
        description = 'Ngừng ghi nhận công nợ vật tư NCC ' || old.supplier_name_snapshot || ' - ' || old.code
      where source_ref = 'supplier_payable_document:' || old.id::text || ':recognition';
    end if;
    return old;
  end if;

  if tg_op = 'UPDATE'
     and old.source_type = 'supplier_delivery_statement'
     and new.source_type is distinct from 'supplier_delivery_statement'
  then
    update public.project_transactions
    set
      amount = 0,
      description = 'Ngừng ghi nhận công nợ vật tư NCC ' || old.supplier_name_snapshot || ' - ' || old.code
    where source_ref = 'supplier_payable_document:' || old.id::text || ':recognition';
  end if;

  if new.source_type is distinct from 'supplier_delivery_statement' then
    return new;
  end if;

  select finance.id into v_finance_id
  from public.project_finances finance
  where (new.project_id is not null and finance.project_id = new.project_id)
     or (new.construction_site_id is not null and finance.construction_site_id = new.construction_site_id)
  order by
    case when new.project_id is not null and finance.project_id = new.project_id then 0 else 1 end,
    finance.id
  limit 1;

  v_source_ref := 'supplier_payable_document:' || new.id::text || ':recognition';
  v_recognized_amount := case
    when new.status = 'cancelled' then 0
    else greatest(coalesce(new.recognized_amount, 0), 0)
  end;

  insert into public.project_transactions (
    id, "projectFinanceId", "constructionSiteId", project_id, project_finance_id, construction_site_id,
    type, category, amount, description, date, source, "sourceRef", source_ref,
    attachments, "createdBy", "createdAt", counterparty_name, counterparty_partner_id
  )
  values (
    'supplier-ap-recognition-' || new.id::text,
    coalesce(v_finance_id, ''),
    coalesce(new.construction_site_id, ''),
    new.project_id,
    nullif(v_finance_id, ''),
    new.construction_site_id,
    'expense',
    'materials',
    v_recognized_amount,
    'Ghi nhận công nợ vật tư NCC ' || new.supplier_name_snapshot || ' - ' || new.code,
    coalesce(new.document_date, current_date)::text,
    'workflow',
    v_source_ref,
    v_source_ref,
    '[]'::jsonb,
    coalesce(new.created_by::text, 'system'),
    coalesce(new.created_at, now()),
    new.supplier_name_snapshot,
    new.supplier_id
  )
  on conflict (source_ref) do update
  set
    "projectFinanceId" = excluded."projectFinanceId",
    "constructionSiteId" = excluded."constructionSiteId",
    project_id = excluded.project_id,
    project_finance_id = excluded.project_finance_id,
    construction_site_id = excluded.construction_site_id,
    type = excluded.type,
    category = excluded.category,
    amount = excluded.amount,
    description = excluded.description,
    date = excluded.date,
    source = excluded.source,
    "sourceRef" = excluded."sourceRef",
    counterparty_name = excluded.counterparty_name,
    counterparty_partner_id = excluded.counterparty_partner_id;

  return new;
end;
$$;


--
-- Name: sync_supplier_payable_trace_links(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_supplier_payable_trace_links(p_payable_document_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_document public.supplier_payable_documents%rowtype;
begin
  select * into v_document
  from public.supplier_payable_documents
  where id = p_payable_document_id;

  if not found then
    return;
  end if;

  if v_document.source_type in ('purchase_order', 'site_direct_purchase', 'supplier_delivery_statement')
    and nullif(v_document.source_id, '') is not null
  then
    perform app_private.upsert_project_document_link(
      v_document.source_type,
      v_document.source_id,
      'supplier_payable_document',
      v_document.id::text,
      v_document.project_id,
      'recognizes',
      v_document.status,
      jsonb_build_object(
        'payableCode', v_document.code,
        'documentNo', v_document.document_no,
        'recognizedAmount', v_document.recognized_amount,
        'supplierName', v_document.supplier_name_snapshot
      )
    );
  end if;
end;
$$;


--
-- Name: sync_supplier_payment_batch_trace_links(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_supplier_payment_batch_trace_links(p_payment_batch_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_batch public.supplier_payment_batches%rowtype;
  v_row record;
begin
  select * into v_batch
  from public.supplier_payment_batches
  where id = p_payment_batch_id;

  if not found then
    return;
  end if;

  for v_row in
    select
      a.payable_document_id,
      a.allocated_amount,
      d.code as payable_code,
      d.document_no
    from public.supplier_payment_allocations a
    join public.supplier_payable_documents d on d.id = a.payable_document_id
    where a.payment_batch_id = p_payment_batch_id
  loop
    perform app_private.upsert_project_document_link(
      'supplier_payable_document',
      v_row.payable_document_id::text,
      'supplier_payment_batch',
      v_batch.id::text,
      v_batch.project_id,
      'paid_by',
      v_batch.status,
      jsonb_build_object(
        'paymentBatchCode', v_batch.code,
        'payableCode', v_row.payable_code,
        'documentNo', v_row.document_no,
        'allocatedAmount', v_row.allocated_amount
      )
    );
  end loop;

  if v_batch.project_transaction_id is not null then
    perform app_private.upsert_project_document_link(
      'supplier_payment_batch',
      v_batch.id::text,
      'project_transaction',
      v_batch.project_transaction_id,
      v_batch.project_id,
      'cashflow',
      v_batch.status,
      jsonb_build_object(
        'paymentBatchCode', v_batch.code,
        'amount', v_batch.payment_amount
      )
    );
  end if;
end;
$$;


--
-- Name: sync_supplier_return_dependencies(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_supplier_return_dependencies() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request_id text;
  v_link_status text;
begin
  v_link_status := case
    when new.status = 'pending' then 'active'
    when new.status = 'cancelled' then 'cancelled'
    else 'reversed'
  end;

  insert into public.project_document_links(
    source_type, source_id, target_type, target_id, project_id,
    relation_type, status, metadata
  ) values (
    'purchase_order', new.purchase_order_id, 'supplier_return', new.id::text, new.project_id,
    'downstream', v_link_status, jsonb_build_object('transactionId', new.transaction_id, 'returnNo', new.return_no)
  )
  on conflict (source_type, source_id, target_type, target_id, relation_type)
  do update set status = excluded.status, metadata = excluded.metadata, updated_at = now();

  insert into public.project_document_links(
    source_type, source_id, target_type, target_id, project_id,
    relation_type, status, metadata
  ) values (
    'purchase_order', new.purchase_order_id, 'transaction', new.transaction_id, new.project_id,
    'downstream', v_link_status, jsonb_build_object('kind', 'supplier_return', 'supplierReturnId', new.id)
  )
  on conflict (source_type, source_id, target_type, target_id, relation_type)
  do update set status = excluded.status, metadata = excluded.metadata, updated_at = now();

  for v_request_id in
    select distinct porl.material_request_id
    from public.purchase_order_request_lines porl
    where porl.purchase_order_id = new.purchase_order_id
  loop
    insert into public.project_document_links(
      source_type, source_id, target_type, target_id, project_id,
      relation_type, status, metadata
    ) values (
      'material_request', v_request_id, 'supplier_return', new.id::text, new.project_id,
      'downstream', v_link_status, jsonb_build_object('purchaseOrderId', new.purchase_order_id, 'returnNo', new.return_no)
    )
    on conflict (source_type, source_id, target_type, target_id, relation_type)
    do update set status = excluded.status, metadata = excluded.metadata, updated_at = now();

    insert into public.project_document_links(
      source_type, source_id, target_type, target_id, project_id,
      relation_type, status, metadata
    ) values (
      'material_request', v_request_id, 'transaction', new.transaction_id, new.project_id,
      'downstream', v_link_status, jsonb_build_object('kind', 'supplier_return', 'supplierReturnId', new.id)
    )
    on conflict (source_type, source_id, target_type, target_id, relation_type)
    do update set status = excluded.status, metadata = excluded.metadata, updated_at = now();
  end loop;

  return new;
end;
$$;


--
-- Name: sync_user_account_status_compat(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_user_account_status_compat() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    if session_user = 'supabase_auth_admin' then
      -- Auth user metadata is identity/profile input, never authorization input.
      new.role := 'EMPLOYEE';
      new.assigned_warehouse_id := null;
      new.allowed_modules := '{}'::text[];
      new.admin_modules := '{}'::text[];
      new.allowed_sub_modules := '{}'::jsonb;
      new.admin_sub_modules := '{}'::jsonb;
    end if;

    -- During compatibility, either explicit disabled signal must win over defaults.
    if new.account_status = 'DISABLED' or new.is_active = false then
      new.account_status := 'DISABLED';
      new.is_active := false;
    else
      new.account_status := 'ACTIVE';
      new.is_active := true;
    end if;
    return new;
  end if;

  if session_user = 'supabase_auth_admin' then
    new.role := old.role;
    new.assigned_warehouse_id := old.assigned_warehouse_id;
    new.allowed_modules := old.allowed_modules;
    new.admin_modules := old.admin_modules;
    new.allowed_sub_modules := old.allowed_sub_modules;
    new.admin_sub_modules := old.admin_sub_modules;
    new.account_status := old.account_status;
    new.is_active := old.is_active;
    return new;
  end if;

  if old.account_status is distinct from new.account_status
    or old.is_active is distinct from new.is_active
  then
    if coalesce(current_setting('app.account_lifecycle_command', true), '') <> 'on' then
      raise exception 'Account status can only be changed by the account lifecycle command'
        using errcode = '42501';
    end if;

    if old.account_status is distinct from new.account_status then
      new.is_active := new.account_status = 'ACTIVE';
    else
      new.account_status := case when new.is_active then 'ACTIVE' else 'DISABLED' end;
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: sync_wms_transaction_to_inventory_ledger(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.sync_wms_transaction_to_inventory_ledger(p_transaction_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tx public.transactions%rowtype;
  v_existing_id uuid;
  v_inventory_transaction_id uuid;
  v_has_in boolean := false;
  v_has_out boolean := false;
  v_in_code text;
  v_out_code text;
  v_header_code text;
  v_header_type text;
  v_line jsonb;
  v_entry_no integer := 0;
  v_tx_date timestamptz;
  v_item_id text;
  v_qty numeric;
  v_price numeric;
  v_source_line_id text;
  v_metadata jsonb;
  v_event_type text;
  v_entry_type text;
  v_warehouse_id text;
  v_scope record;
  v_payload_project_id text;
  v_payload_site_id text;
  v_header_project_id text;
  v_header_site_id text;
begin
  select * into v_tx
  from public.transactions
  where id = p_transaction_id
  for update;
  if not found then raise exception 'transaction not found: %', p_transaction_id; end if;
  if v_tx.status::text <> 'COMPLETED' then return null; end if;

  select id into v_existing_id
  from public.inventory_transactions
  where source_type = 'wms_transaction' and source_id = v_tx.id
  limit 1;
  if v_existing_id is not null then return v_existing_id; end if;

  v_event_type := coalesce(
    v_tx.business_event_type,
    app_private.classify_wms_business_event(
      v_tx.type::text, v_tx.source_type, v_tx.related_request_id, v_tx.items
    )
  );
  if v_event_type is null then
    raise exception 'Phiếu kho hoàn tất phải có mục đích nghiệp vụ.';
  end if;
  v_tx_date := coalesce(nullif(v_tx.date::text, '')::timestamptz, now());
  v_has_in := (
    v_tx.type::text in ('IMPORT', 'TRANSFER')
    and exists (
      select 1 from jsonb_array_elements(coalesce(v_tx.items, '[]'::jsonb)) item(value)
      where coalesce(nullif(item.value->>'quantity', '')::numeric, 0) > 0
    )
  ) or exists (
    select 1 from jsonb_array_elements(coalesce(v_tx.items, '[]'::jsonb)) item(value)
    where v_tx.type::text = 'ADJUSTMENT'
      and coalesce(nullif(item.value->>'quantity', '')::numeric, 0) > 0
  );
  v_has_out := (
    v_tx.type::text in ('EXPORT', 'TRANSFER', 'LIQUIDATION')
    and exists (
      select 1 from jsonb_array_elements(coalesce(v_tx.items, '[]'::jsonb)) item(value)
      where coalesce(nullif(item.value->>'quantity', '')::numeric, 0) > 0
    )
  ) or exists (
    select 1 from jsonb_array_elements(coalesce(v_tx.items, '[]'::jsonb)) item(value)
    where v_tx.type::text = 'ADJUSTMENT'
      and coalesce(nullif(item.value->>'quantity', '')::numeric, 0) < 0
  );
  if not v_has_in and not v_has_out then return null; end if;

  if v_has_in then v_in_code := app_private.next_inventory_ledger_code('in'); end if;
  if v_has_out then v_out_code := app_private.next_inventory_ledger_code('out'); end if;
  v_header_code := coalesce(v_out_code, v_in_code);
  v_header_type := case
    when v_event_type = 'project_return_receipt' then 'project_return_receipt'
    when v_tx.type::text = 'TRANSFER' and v_has_out then 'transfer_issue'
    when v_tx.type::text = 'IMPORT' then 'purchase_receipt'
    when v_tx.type::text = 'EXPORT' then 'project_issue'
    when v_tx.type::text = 'LIQUIDATION' then 'loss_issue'
    when v_tx.type::text = 'ADJUSTMENT' and v_has_in then 'adjustment_in'
    else 'adjustment_out'
  end;

  v_metadata := jsonb_build_object(
    'wmsTransactionId', v_tx.id,
    'wmsType', v_tx.type::text,
    'wmsStatus', v_tx.status::text,
    'businessEventType', v_event_type,
    'businessEventReason', v_tx.business_event_reason,
    'sourceWarehouseId', v_tx.source_warehouse_id,
    'targetWarehouseId', v_tx.target_warehouse_id,
    'supplierId', v_tx.supplier_id,
    'items', coalesce(v_tx.items, '[]'::jsonb)
  );

  insert into public.inventory_transactions(
    code, transaction_type, status, transaction_date,
    source_type, source_id, source_code, related_request_id,
    project_id, construction_site_id, business_event_type,
    description, metadata, created_by, approved_by, posted_at
  ) values (
    v_header_code, v_header_type, 'posted', v_tx_date,
    'wms_transaction', v_tx.id, v_tx.id, v_tx.related_request_id,
    null, null, v_event_type,
    v_tx.note, v_metadata, v_tx.requester_id, v_tx.approver_id, now()
  ) returning id into v_inventory_transaction_id;

  for v_line in select value from jsonb_array_elements(coalesce(v_tx.items, '[]'::jsonb))
  loop
    v_item_id := v_line->>'itemId';
    v_qty := coalesce(nullif(v_line->>'quantity', '')::numeric, 0);
    v_price := coalesce(nullif(v_line->>'price', '')::numeric, 0);
    v_source_line_id := nullif(coalesce(
      v_line->>'requestLineId', v_line->>'materialIssueLineId', v_line->>'lineId'
    ), '');
    if v_item_id is null then raise exception 'invalid transaction item payload'; end if;
    if v_qty = 0 then continue; end if;

    if v_tx.type::text = 'IMPORT' then
      if v_qty < 0 then raise exception 'invalid import quantity'; end if;
      v_warehouse_id := v_tx.target_warehouse_id;
      v_entry_type := case when v_event_type = 'project_return_receipt'
        then 'project_return_receipt' else 'purchase_receipt' end;
      select * into v_scope from app_private.resolve_warehouse_project_scope(v_warehouse_id);
      v_payload_project_id := nullif(coalesce(v_line->>'projectId', v_line->>'project_id'), '');
      v_payload_site_id := nullif(coalesce(v_line->>'constructionSiteId', v_line->>'construction_site_id'), '');
      if (v_payload_project_id is not null and v_payload_project_id is distinct from v_scope.project_id)
         or (v_payload_site_id is not null and v_payload_site_id is distinct from v_scope.construction_site_id) then
        raise exception 'Scope chứng từ không khớp scope kho.';
      end if;
      v_entry_no := v_entry_no + 1;
      perform app_private.post_inventory_ledger_entry(
        v_inventory_transaction_id, v_entry_no, v_in_code, v_tx_date,
        v_entry_type, 'in', v_item_id, v_warehouse_id,
        v_scope.project_id, v_scope.construction_site_id,
        'wms_transaction', v_tx.id, v_tx.id, v_source_line_id, v_tx.related_request_id,
        v_qty, v_price, v_tx.note,
        v_line || jsonb_build_object('businessEventType', v_event_type),
        v_tx.requester_id, v_tx.approver_id
      );
    elsif v_tx.type::text = 'EXPORT' then
      if v_qty < 0 then raise exception 'invalid export quantity'; end if;
      v_warehouse_id := v_tx.source_warehouse_id;
      select * into v_scope from app_private.resolve_warehouse_project_scope(v_warehouse_id);
      v_entry_no := v_entry_no + 1;
      perform app_private.post_inventory_ledger_entry(
        v_inventory_transaction_id, v_entry_no, v_out_code, v_tx_date,
        'project_issue', 'out', v_item_id, v_warehouse_id,
        v_scope.project_id, v_scope.construction_site_id,
        'wms_transaction', v_tx.id, v_tx.id, v_source_line_id, v_tx.related_request_id,
        v_qty, v_price, v_tx.note,
        v_line || jsonb_build_object('businessEventType', v_event_type),
        v_tx.requester_id, v_tx.approver_id
      );
    elsif v_tx.type::text = 'TRANSFER' then
      if v_qty < 0 then raise exception 'invalid transfer quantity'; end if;
      select * into v_scope from app_private.resolve_warehouse_project_scope(v_tx.source_warehouse_id);
      v_entry_no := v_entry_no + 1;
      perform app_private.post_inventory_ledger_entry(
        v_inventory_transaction_id, v_entry_no, v_out_code, v_tx_date,
        'transfer_issue', 'out', v_item_id, v_tx.source_warehouse_id,
        v_scope.project_id, v_scope.construction_site_id,
        'wms_transaction', v_tx.id, v_tx.id, v_source_line_id, v_tx.related_request_id,
        v_qty, v_price, v_tx.note,
        v_line || jsonb_build_object('businessEventType', v_event_type),
        v_tx.requester_id, v_tx.approver_id
      );
      select * into v_scope from app_private.resolve_warehouse_project_scope(v_tx.target_warehouse_id);
      v_entry_no := v_entry_no + 1;
      perform app_private.post_inventory_ledger_entry(
        v_inventory_transaction_id, v_entry_no, v_in_code, v_tx_date,
        'transfer_receipt', 'in', v_item_id, v_tx.target_warehouse_id,
        v_scope.project_id, v_scope.construction_site_id,
        'wms_transaction', v_tx.id, v_tx.id, v_source_line_id, v_tx.related_request_id,
        v_qty, v_price, v_tx.note,
        v_line || jsonb_build_object('businessEventType', v_event_type),
        v_tx.requester_id, v_tx.approver_id
      );
    elsif v_tx.type::text = 'LIQUIDATION' then
      if v_qty < 0 then raise exception 'invalid liquidation quantity'; end if;
      select * into v_scope from app_private.resolve_warehouse_project_scope(v_tx.source_warehouse_id);
      v_entry_no := v_entry_no + 1;
      perform app_private.post_inventory_ledger_entry(
        v_inventory_transaction_id, v_entry_no, v_out_code, v_tx_date,
        'loss_issue', 'out', v_item_id, v_tx.source_warehouse_id,
        v_scope.project_id, v_scope.construction_site_id,
        'wms_transaction', v_tx.id, v_tx.id, v_source_line_id, v_tx.related_request_id,
        v_qty, v_price, v_tx.note,
        v_line || jsonb_build_object('businessEventType', v_event_type),
        v_tx.requester_id, v_tx.approver_id
      );
    elsif v_tx.type::text = 'ADJUSTMENT' then
      v_warehouse_id := coalesce(v_tx.target_warehouse_id, v_tx.source_warehouse_id);
      select * into v_scope from app_private.resolve_warehouse_project_scope(v_warehouse_id);
      v_entry_no := v_entry_no + 1;
      perform app_private.post_inventory_ledger_entry(
        v_inventory_transaction_id, v_entry_no,
        case when v_qty > 0 then v_in_code else v_out_code end,
        v_tx_date,
        case when v_qty > 0 then 'adjustment_in' else 'adjustment_out' end,
        case when v_qty > 0 then 'in' else 'out' end,
        v_item_id, v_warehouse_id, v_scope.project_id, v_scope.construction_site_id,
        'wms_transaction', v_tx.id, v_tx.id, v_source_line_id, v_tx.related_request_id,
        abs(v_qty), v_price, v_tx.note,
        v_line || jsonb_build_object('businessEventType', v_event_type),
        v_tx.requester_id, v_tx.approver_id
      );
    end if;
  end loop;

  if v_entry_no = 0 then
    delete from public.inventory_transactions where id = v_inventory_transaction_id;
    return null;
  end if;

  update public.inventory_ledger_entries
  set business_event_type = v_event_type
  where inventory_transaction_id = v_inventory_transaction_id;

  select
    case when count(distinct coalesce(entry.project_id, '<null>')) = 1
      then max(entry.project_id) else null end,
    case when count(distinct coalesce(entry.construction_site_id, '<null>')) = 1
      then max(entry.construction_site_id) else null end
  into v_header_project_id, v_header_site_id
  from public.inventory_ledger_entries entry
  where entry.inventory_transaction_id = v_inventory_transaction_id;

  update public.inventory_transactions set
    project_id = v_header_project_id,
    construction_site_id = v_header_site_id,
    business_event_type = v_event_type
  where id = v_inventory_transaction_id;

  return v_inventory_transaction_id;
end;
$$;


--
-- Name: touch_feedback_item_activity(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.touch_feedback_item_activity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_feedback_id uuid;
begin
  v_feedback_id := case when tg_op = 'DELETE' then old.feedback_id else new.feedback_id end;

  update public.feedback_items
  set last_activity_at = now(),
      updated_at = now()
  where id = v_feedback_id;

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$$;


--
-- Name: touch_safety_assignment_eligibility(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.touch_safety_assignment_eligibility() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    return old;
  end if;

  perform app_private.recompute_safety_assignment_eligibility(new.id);
  return new;
end;
$$;


--
-- Name: touch_safety_equipment_document_checklist(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.touch_safety_equipment_document_checklist() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    perform app_private.sync_safety_equipment_documents_status(old.equipment_id);
    return old;
  end if;

  perform app_private.sync_safety_equipment_documents_status(new.equipment_id);
  if tg_op = 'UPDATE' and old.equipment_id is distinct from new.equipment_id then
    perform app_private.sync_safety_equipment_documents_status(old.equipment_id);
  end if;
  return new;
end;
$$;


--
-- Name: touch_safety_worker_assignment_eligibility(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.touch_safety_worker_assignment_eligibility() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_new_worker_id uuid;
  v_old_worker_id uuid;
begin
  if tg_table_name = 'safety_worker_profiles' then
    v_new_worker_id := case when tg_op = 'DELETE' then null else new.id end;
    v_old_worker_id := case when tg_op = 'INSERT' then null else old.id end;
  else
    v_new_worker_id := case when tg_op = 'DELETE' then null else new.worker_id end;
    v_old_worker_id := case when tg_op = 'INSERT' then null else old.worker_id end;
  end if;

  if tg_op = 'DELETE' then
    perform app_private.recompute_safety_worker_assignments(v_old_worker_id);
    return old;
  end if;

  perform app_private.recompute_safety_worker_assignments(v_new_worker_id);
  if tg_op = 'UPDATE' and v_old_worker_id is distinct from v_new_worker_id then
    perform app_private.recompute_safety_worker_assignments(v_old_worker_id);
  end if;
  return new;
end;
$$;


