begin
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: trace_link_status(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.trace_link_status(p_status text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case lower(coalesce(p_status, 'active'))
    when 'cancelled' then 'cancelled'
    when 'canceled' then 'cancelled'
    when 'reversed' then 'reversed'
    when 'void' then 'void'
    when 'returned' then 'returned'
    else 'active'
  end;
$$;


--
-- Name: transaction_can_insert(text, uuid, uuid, text, text, text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.transaction_can_insert(p_type text, p_requester_id uuid, p_approver_id uuid, p_source_warehouse_id text, p_target_warehouse_id text, p_related_request_id text, p_items jsonb) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    app_private.wms_has_action(
      'wms.transaction.create',
      p_source_warehouse_id,
      p_target_warehouse_id,
      p_requester_id,
      p_approver_id
    )
    or exists (
      select 1
      from public.requests r
      where r.id = p_related_request_id
        and coalesce(r.request_origin, 'wms') = 'project'
        and r.submitted_to_user_id = public.current_app_user_id()::text
        and r.status::text in ('APPROVED', 'IN_TRANSIT')
        and exists (
          select 1
          from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) item
          where coalesce(item->>'materialRequestId', item->>'material_request_id') = r.id
        )
    );
$$;


--
-- Name: transfer_safety_worker_site(uuid, text, uuid, timestamp with time zone, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.transfer_safety_worker_site(p_assignment_id uuid, p_target_project_id text, p_target_construction_site_id uuid, p_started_at timestamp with time zone, p_subcontractor_id uuid DEFAULT NULL::uuid, p_team_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_assignment public.safety_project_assignments%rowtype;
  v_source_membership public.safety_worker_site_memberships%rowtype;
  v_target_membership public.safety_worker_site_memberships%rowtype;
  v_worker public.safety_worker_profiles%rowtype;
  v_target_assignment_id uuid;
begin
  perform app_private.safety_workforce_assert_scope(p_target_project_id, p_target_construction_site_id);
  if p_started_at is null then
    raise exception 'SAFETY_INVALID_RPC_PAYLOAD: transfer start time is required'
      using errcode = '22023';
  end if;

  select assignment.*
  into v_assignment
  from public.safety_project_assignments assignment
  where assignment.id = p_assignment_id;

  if v_assignment.id is null or v_assignment.assignment_status <> 'active' then
    raise exception 'SAFETY_SCOPE_MISMATCH: active source assignment not found'
      using errcode = '42501';
  end if;

  select worker.*
  into v_worker
  from public.safety_worker_profiles worker
  where worker.id = v_assignment.worker_id
  for update;

  select membership.*
  into v_source_membership
  from public.safety_worker_site_memberships membership
  where membership.id = v_assignment.membership_id;

  if v_actor is null
    or not app_private.safety_workforce_can_manage(v_source_membership.project_id, v_source_membership.construction_site_id)
    or not app_private.safety_workforce_can_manage(p_target_project_id, p_target_construction_site_id)
  then
    raise exception 'SAFETY_TRANSFER_PERMISSION_REQUIRED: manage permission is required on source and target sites'
      using errcode = '42501';
  end if;
  if p_started_at < v_assignment.started_at then
    raise exception 'SAFETY_INVALID_RPC_PAYLOAD: transfer time precedes assignment start'
      using errcode = '22023';
  end if;

  perform app_private.safety_workforce_assert_subcontractor_team(
    p_target_project_id,
    p_target_construction_site_id,
    p_subcontractor_id,
    p_team_id,
    v_worker.worker_kind
  );

  insert into public.safety_worker_site_memberships (
    worker_id, project_id, construction_site_id,
    default_subcontractor_id, default_team_id,
    status, first_joined_at, source, created_by, updated_by
  ) values (
    v_worker.id,
    p_target_project_id,
    p_target_construction_site_id,
    case when v_worker.worker_kind = 'company_staff' then null else p_subcontractor_id end,
    case when v_worker.worker_kind = 'company_staff' then null else p_team_id end,
    'candidate',
    p_started_at,
    'transfer',
    v_actor,
    v_actor
  )
  on conflict (worker_id, construction_site_id) do update
  set project_id = excluded.project_id,
      default_subcontractor_id = excluded.default_subcontractor_id,
      default_team_id = excluded.default_team_id,
      updated_by = excluded.updated_by,
      updated_at = now()
  returning * into v_target_membership;

  if v_source_membership.id = v_target_membership.id then
    raise exception 'SAFETY_SCOPE_MISMATCH: source and target memberships are identical'
      using errcode = '22023';
  end if;

  perform membership.id
  from public.safety_worker_site_memberships membership
  where membership.id in (v_source_membership.id, v_target_membership.id)
  order by membership.id for update;

  select assignment.*
  into v_assignment
  from public.safety_project_assignments assignment
  where assignment.id = p_assignment_id
  for update;

  if v_assignment.assignment_status <> 'active' then
    raise exception 'SAFETY_WORKER_ACTIVE_ELSEWHERE: source assignment changed during transfer'
      using errcode = '40001';
  end if;

  update public.safety_project_assignments assignment
  set assignment_status = 'ended',
      ended_at = p_started_at,
      end_date = (p_started_at at time zone 'Asia/Ho_Chi_Minh')::date,
      ended_by = v_actor,
      ended_reason = 'Transferred to another construction site',
      updated_at = now()
  where assignment.id = v_assignment.id;

  update public.safety_cards card
  set status = 'revoked',
      revoked_reason = 'Assignment transferred to another construction site',
      updated_at = now()
  where card.assignment_id = v_assignment.id
    and card.status = 'active';

  update public.safety_worker_site_memberships membership
  set status = 'inactive',
      last_left_at = p_started_at,
      updated_by = v_actor,
      updated_at = now()
  where membership.id = v_source_membership.id;

  update public.safety_worker_site_memberships membership
  set status = 'active',
      last_left_at = null,
      default_subcontractor_id = case when v_worker.worker_kind = 'company_staff' then null else p_subcontractor_id end,
      default_team_id = case when v_worker.worker_kind = 'company_staff' then null else p_team_id end,
      updated_by = v_actor,
      updated_at = now()
  where membership.id = v_target_membership.id;

  insert into public.safety_project_assignments (
    worker_id, project_id, construction_site_id, membership_id,
    assignment_status, started_at, start_date,
    subcontractor_id, team_id, role_name, work_type,
    site_training_status, commitment_status, ppe_status, toolbox_status,
    eligibility_status, source, created_by
  ) values (
    v_worker.id,
    p_target_project_id,
    p_target_construction_site_id::text,
    v_target_membership.id,
    'active',
    p_started_at,
    (p_started_at at time zone 'Asia/Ho_Chi_Minh')::date,
    case when v_worker.worker_kind = 'company_staff' then null else p_subcontractor_id end,
    case when v_worker.worker_kind = 'company_staff' then null else p_team_id end,
    v_assignment.role_name,
    v_assignment.work_type,
    'pending', 'pending', 'missing', 'pending',
    'missing_profile', 'transfer', v_actor::text
  )
  returning id into v_target_assignment_id;

  insert into public.safety_audit_logs (
    actor_user_id, action, target_type, target_id, project_id, construction_site_id, metadata
  ) values (
    v_actor::text,
    'assignment.transfer',
    'safety_project_assignments',
    v_target_assignment_id,
    p_target_project_id,
    p_target_construction_site_id::text,
    jsonb_build_object(
      'sourceAssignmentId', v_assignment.id,
      'sourceMembershipId', v_source_membership.id,
      'targetMembershipId', v_target_membership.id
    )
  );

  return app_private.safety_workforce_detail_for_membership(v_target_membership.id);
end;
$$;


--
-- Name: transition_project_gantt_delay_event_impl(uuid, text, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.transition_project_gantt_delay_event_impl(p_request_id uuid, p_project_id text, p_construction_site_id text, p_event_id text, p_status text, p_expected_updated_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid;
  v_site_id text := nullif(btrim(coalesce(p_construction_site_id, '')), '');
  v_replay jsonb;
  v_event public.project_delay_events%rowtype;
  v_result jsonb;
begin
  v_actor_user_id := app_private.assert_project_gantt_action(p_project_id, v_site_id, 'edit');
  v_replay := app_private.begin_project_gantt_command(
    v_actor_user_id, p_request_id, 'transition_project_gantt_delay_event',
    md5(jsonb_build_object('projectId', p_project_id, 'constructionSiteId', v_site_id,
      'eventId', p_event_id, 'status', p_status,
      'expectedUpdatedAt', p_expected_updated_at)::text)
  );
  if v_replay is not null then return v_replay; end if;

  select event.* into v_event
  from public.project_delay_events event
  where event.id = p_event_id
  for update;
  if not found or v_event.project_id is distinct from p_project_id
    or v_event.construction_site_id is distinct from v_site_id then
    raise exception 'GANTT_SCOPE_MISMATCH' using errcode = '23514';
  end if;
  if p_expected_updated_at is null or v_event.updated_at is distinct from p_expected_updated_at then
    raise exception 'GANTT_STALE_VERSION' using errcode = '40001';
  end if;
  if p_status not in ('accepted', 'resolved', 'void')
    or (p_status = 'accepted' and v_event.status <> 'reported')
    or (p_status in ('resolved', 'void') and v_event.status not in ('reported', 'accepted')) then
    raise exception 'GANTT_INVALID_TRANSITION' using errcode = '23514';
  end if;

  update public.project_delay_events event
  set status = p_status,
      accepted_by = case when p_status = 'accepted' then v_actor_user_id::text else event.accepted_by end,
      accepted_at = case when p_status = 'accepted' then now() else event.accepted_at end,
      resolved_at = case when p_status in ('resolved', 'void') then now() else null end
  where event.id = p_event_id
  returning * into v_event;

  v_result := jsonb_build_object(
    'ok', true, 'requestId', p_request_id, 'replayed', false,
    'delayEvent', to_jsonb(v_event)
  );
  return app_private.finish_project_gantt_command(v_actor_user_id, p_request_id, v_result);
end;
$$;


--
-- Name: transition_quality_checklist_impl(uuid, text, text, uuid, timestamp with time zone, text, jsonb, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.transition_quality_checklist_impl(p_request_id uuid, p_project_id text, p_construction_site_id text, p_checklist_id uuid, p_expected_updated_at timestamp with time zone, p_status text, p_submission_target jsonb DEFAULT NULL::jsonb, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_target uuid := nullif(p_submission_target ->> 'user_id', '')::uuid;
  v_old public.quality_checklists%rowtype;
  v_row public.quality_checklists%rowtype;
  v_replay jsonb;
  v_result jsonb;
  v_target_name text;
begin
  if p_status = 'submitted' then
    v_actor := app_private.assert_quality_action(p_project_id, p_construction_site_id, 'submit');
    perform app_private.assert_quality_action(p_project_id, p_construction_site_id, 'edit');
    perform app_private.assert_quality_recipient(v_target, p_project_id, p_construction_site_id);
    select user_row.name into v_target_name from public.users user_row where user_row.id = v_target;
  elsif p_status in ('approved', 'returned', 'cancelled', 'draft') then
    v_actor := app_private.assert_quality_action(p_project_id, p_construction_site_id, 'approve');
  else
    raise exception 'QUALITY_INVALID_TRANSITION' using errcode = '23514';
  end if;
  v_replay := app_private.begin_quality_command(v_actor, p_request_id,
    'transition_quality_checklist', md5(jsonb_build_object(
      'projectId', p_project_id, 'constructionSiteId', p_construction_site_id,
      'checklistId', p_checklist_id, 'expectedUpdatedAt', p_expected_updated_at,
      'status', p_status, 'submissionTarget', p_submission_target, 'reason', p_reason
    )::text));
  if v_replay is not null then return v_replay; end if;

  select * into v_old from public.quality_checklists item
  where item.id = p_checklist_id for update;
  if not found or v_old.project_id::text is distinct from p_project_id
    or v_old.construction_site_id::text is distinct from p_construction_site_id then
    raise exception 'QUALITY_SCOPE_MISMATCH' using errcode = '23514';
  end if;
  if v_old.updated_at is distinct from p_expected_updated_at then
    raise exception 'QUALITY_STALE_VERSION' using errcode = '40001';
  end if;
  if not (
    (p_status = 'submitted' and v_old.status in ('draft', 'returned'))
    or (p_status in ('approved', 'returned') and v_old.status = 'submitted')
    or (p_status = 'cancelled' and v_old.status <> 'cancelled')
    or (p_status = 'draft' and v_old.status = 'approved')
  ) then
    raise exception 'QUALITY_INVALID_TRANSITION' using errcode = '23514';
  end if;
  if p_status in ('returned', 'cancelled') and nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'QUALITY_INVALID_TRANSITION: reason is required' using errcode = '23514';
  end if;

  update public.quality_checklists item set
    status = p_status,
    submitted_by = case when p_status = 'submitted' then v_actor::text when p_status = 'draft' then null else item.submitted_by end,
    submitted_at = case when p_status = 'submitted' then now() when p_status = 'draft' then null else item.submitted_at end,
    submitted_to_user_id = case
      when p_status = 'submitted' then v_target::text
      when p_status = 'returned' then coalesce(item.submitted_by, item.created_by)
      else null end,
    submitted_to_name = case when p_status = 'submitted' then v_target_name else null end,
    submitted_to_permission = case when p_status = 'submitted' then 'approve'
      when p_status = 'returned' then 'edit' else null end,
    submission_note = case when p_status = 'submitted' then nullif(p_submission_target ->> 'note', '')
      when p_status = 'returned' then btrim(p_reason) else null end,
    approved_by = case when p_status = 'approved' then v_actor::text when p_status = 'draft' then null else item.approved_by end,
    approved_at = case when p_status = 'approved' then now() when p_status = 'draft' then null else item.approved_at end,
    returned_by = case when p_status = 'returned' then v_actor::text when p_status = 'draft' then null else item.returned_by end,
    returned_at = case when p_status = 'returned' then now() when p_status = 'draft' then null else item.returned_at end,
    return_reason = case when p_status = 'returned' then btrim(p_reason) when p_status = 'draft' then null else item.return_reason end,
    ever_submitted = item.ever_submitted or p_status = 'submitted',
    last_action_by = v_actor::text,
    last_action_at = now(),
    updated_at = now()
  where item.id = p_checklist_id
  returning * into v_row;

  if p_status = 'submitted' then
    insert into public.notifications (
      user_id, title, body, message, type, category, severity, module, link,
      source_type, source_id, construction_site_id, metadata
    ) values (
      v_target::text, 'Hồ sơ chất lượng ' || v_row.code || ' chờ duyệt',
      'Bạn được chọn phê duyệt hồ sơ chất lượng ' || v_row.title || '.',
      'Bạn được chọn phê duyệt hồ sơ chất lượng ' || v_row.title || '.',
      'info', 'quality', 'info', 'DA', '/da', 'quality_checklist', v_row.id::text,
      p_construction_site_id, jsonb_build_object(
        'projectId', p_project_id, 'constructionSiteId', p_construction_site_id,
        'submittedToUserId', v_target
      )
    );
  elsif p_status = 'returned' and coalesce(v_old.submitted_by, v_old.created_by) is not null then
    insert into public.notifications (
      user_id, title, body, message, type, category, severity, module, link,
      source_type, source_id, construction_site_id, metadata
    ) values (
      coalesce(v_old.submitted_by, v_old.created_by),
      'Hồ sơ chất lượng ' || v_row.code || ' được trả lại', btrim(p_reason),
      btrim(p_reason), 'warning', 'quality', 'warning', 'DA', '/da',
      'quality_checklist', v_row.id::text, p_construction_site_id,
      jsonb_build_object('projectId', p_project_id, 'constructionSiteId', p_construction_site_id)
    );
  end if;

  insert into public.audit_trail (
    table_name, record_id, action, old_data, new_data, user_id, user_name,
    module, description, context
  ) values (
    'quality_checklists', v_row.id::text, 'UPDATE', to_jsonb(v_old), to_jsonb(v_row),
    v_actor::text, v_actor::text, 'quality', 'Chuyển trạng thái hồ sơ chất lượng sang ' || p_status,
    jsonb_build_object('requestId', p_request_id, 'roomCode', 'quality', 'reason', p_reason)
  );
  v_result := jsonb_build_object('ok', true, 'requestId', p_request_id,
    'replayed', false, 'checklist', to_jsonb(v_row));
  return app_private.finish_quality_command(v_actor, p_request_id, v_result);
end;
$$;


--
-- Name: trg_post_purchase_receipt_finance_v2(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.trg_post_purchase_receipt_finance_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_flow_version integer;
begin
  select procurement_flow_version into v_flow_version
  from public.purchase_orders
  where id = new.purchase_order_id;
  if coalesce(v_flow_version, 2) = 2
    and new.status in ('received', 'received_short', 'received_over')
    and old.status is distinct from new.status
  then
    perform app_private.post_purchase_receipt_finance_v2(new.id, new.received_by);
  end if;
  return new;
end;
$$;


--
-- Name: trg_post_purchase_receipt_return_finance_v2(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.trg_post_purchase_receipt_return_finance_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.status = 'completed'
     and old.status is distinct from new.status then
    perform app_private.post_purchase_receipt_return_finance_v2(
      new.id,
      coalesce(new.completed_by, new.created_by)
    );
  end if;
  return new;
end;
$$;


