--

CREATE FUNCTION app_private.trg_sync_wms_transaction_inventory_ledger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.status::text = 'COMPLETED'
     and (tg_op = 'INSERT' or old.status is distinct from new.status)
     and not (
       new.source_type = 'po_delivery_batch'
       and exists (
         select 1
         from jsonb_array_elements(coalesce(new.items, '[]'::jsonb)) item(value)
         where item.value ->> 'fulfillmentMode' = 'DIRECT_CONSUMPTION'
       )
     ) then
    perform app_private.sync_wms_transaction_to_inventory_ledger(new.id);
  end if;
  return new;
end;
$$;


--
-- Name: unassign_hrm_employee_from_organization(uuid, date, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.unassign_hrm_employee_from_organization(p_employee_id uuid, p_effective_to date, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid;
  v_employee public.employees%rowtype;
  v_old_assignments jsonb;
  v_ended_count integer := 0;
begin
  if not app_private.current_user_has_hrm_template_permission('hrm.staffing.assign') then
    raise exception using errcode = '42501', message = 'HRM_STAFFING_ASSIGN_REQUIRED';
  end if;
  v_actor_id := public.current_app_user_id();
  if v_actor_id is null then
    raise exception using errcode = '42501', message = 'HRM_ACTIVE_ACTOR_REQUIRED';
  end if;
  if p_effective_to is null or p_effective_to > current_date then
    raise exception using errcode = '22023', message = 'HRM_UNASSIGN_FUTURE_DATE_NOT_ALLOWED';
  end if;

  select * into v_employee
  from public.employees
  where id = p_employee_id and status = 'Đang làm việc'
  for update;
  if v_employee.id is null then
    raise exception using errcode = '22023', message = 'HRM_ACTIVE_EMPLOYEE_NOT_FOUND';
  end if;

  select coalesce(jsonb_agg(to_jsonb(assignment)), '[]'::jsonb)
  into v_old_assignments
  from public.hrm_employee_slot_assignments assignment
  join public.hrm_org_position_slots slot on slot.id = assignment.slot_id
  where assignment.employee_id = p_employee_id
    and assignment.status = 'ACTIVE'
    and assignment.assignment_type = 'PRIMARY'
    and slot.source = 'workforce_plan';

  update public.hrm_employee_slot_assignments assignment
  set status = 'ENDED',
      effective_to = greatest(assignment.effective_from, p_effective_to),
      note = concat_ws(E'\n', nullif(assignment.note, ''), nullif(trim(p_note), '')),
      updated_by = v_actor_id,
      updated_at = now()
  from public.hrm_org_position_slots slot
  where assignment.slot_id = slot.id
    and assignment.employee_id = p_employee_id
    and assignment.status = 'ACTIVE'
    and assignment.assignment_type = 'PRIMARY'
    and slot.source = 'workforce_plan';
  get diagnostics v_ended_count = row_count;

  if v_ended_count = 0 then
    raise exception using errcode = '22023', message = 'HRM_OFFICIAL_ASSIGNMENT_NOT_FOUND';
  end if;

  -- Phase 1 deliberately preserves employee organization/position snapshots for
  -- compatibility with modules that have not migrated to official assignments yet.
  insert into public.audit_trail (
    table_name, record_id, action, old_data, new_data, user_id, module,
    description, record_label, entity_type, changed_fields, change_count,
    impact_level, context
  ) values (
    'hrm_employee_slot_assignments', p_employee_id::text, 'UPDATE',
    jsonb_build_object('assignments', v_old_assignments),
    jsonb_build_object('status', 'PENDING_ALLOCATION',
      'compatibility_snapshot_preserved', true),
    v_actor_id::text, 'HRM', 'Gỡ nhân sự khỏi cơ cấu tổ chức chính thức',
    v_employee.full_name, 'HRM_WORKFORCE_UNASSIGNMENT',
    array['status', 'effective_to'], 2, 'high',
    jsonb_build_object('note', nullif(trim(p_note), ''))
  );

  return jsonb_build_object(
    'employee_id', p_employee_id,
    'status', 'PENDING_ALLOCATION',
    'assignment_id', null,
    'slot_id', null,
    'org_unit_id', null,
    'org_unit_name', null,
    'position_id', null,
    'position_name', null,
    'level_code', null
  );
end;
$$;


--
-- Name: unassign_hrm_employee_from_organization(uuid, date, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.unassign_hrm_employee_from_organization(p_employee_id uuid, p_effective_to date, p_note text, p_source_reference text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_result jsonb;
begin
  perform app_private.assert_hrm_mutation_context(p_note, p_source_reference);
  v_result := app_private.unassign_hrm_employee_from_organization(
    p_employee_id, p_effective_to, p_note
  );
  perform app_private.annotate_hrm_workforce_audit('HRM_WORKFORCE_UNASSIGNMENT', p_source_reference);
  return v_result;
end;
$$;


--
-- Name: update_my_employee_profile_impl(jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.update_my_employee_profile_impl(p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid := public.current_app_user_id();
  v_employee public.employees%rowtype;
  v_gender text;
begin
  if v_user_id is null then
    raise exception 'employee profile actor not found for current auth session'
      using errcode = '28000';
  end if;

  p_patch := coalesce(p_patch, '{}'::jsonb);

  if p_patch ? 'gender' then
    v_gender := nullif(btrim(p_patch ->> 'gender'), '');
    if v_gender is not null and v_gender not in ('Nam', 'Nữ', 'Khác') then
      raise exception 'invalid employee gender: %', v_gender
        using errcode = '22023';
    end if;
  end if;

  update public.employees e
  set
    full_name = case
      when p_patch ? 'fullName' then coalesce(nullif(btrim(p_patch ->> 'fullName'), ''), e.full_name)
      else e.full_name
    end,
    gender = case
      when p_patch ? 'gender' then coalesce(v_gender, e.gender)
      else e.gender
    end,
    date_of_birth = case
      when p_patch ? 'dateOfBirth' then nullif(btrim(p_patch ->> 'dateOfBirth'), '')::date
      else e.date_of_birth
    end,
    marital_status = case
      when p_patch ? 'maritalStatus' then nullif(btrim(p_patch ->> 'maritalStatus'), '')
      else e.marital_status
    end,
    phone = case
      when p_patch ? 'phone' then nullif(btrim(p_patch ->> 'phone'), '')
      else e.phone
    end,
    email = case
      when p_patch ? 'email' then nullif(btrim(p_patch ->> 'email'), '')
      else e.email
    end,
    avatar_url = case
      when p_patch ? 'avatarUrl' then nullif(btrim(p_patch ->> 'avatarUrl'), '')
      else e.avatar_url
    end,
    updated_at = now()
  where e.user_id = v_user_id
  returning * into v_employee;

  if not found then
    raise exception 'employee profile not found for current user'
      using errcode = 'P0002';
  end if;

  update public.users u
  set
    name = case
      when p_patch ? 'fullName' then coalesce(nullif(btrim(p_patch ->> 'fullName'), ''), u.name)
      else u.name
    end,
    phone = case
      when p_patch ? 'phone' then nullif(btrim(p_patch ->> 'phone'), '')
      else u.phone
    end,
    avatar = case
      when p_patch ? 'avatarUrl' then nullif(btrim(p_patch ->> 'avatarUrl'), '')
      else u.avatar
    end
  where u.id = v_user_id;

  return to_jsonb(v_employee);
end;
$$;


--
-- Name: update_project(text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.update_project(p_project_id text, p_project jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_project public.projects%rowtype;
begin
  if not app_private.can_manage_project_master(p_project_id, 'project.master.edit') then
    raise exception 'Not allowed to update project'
      using errcode = '42501';
  end if;

  update public.projects
  set code = coalesce(nullif(p_project->>'code', ''), code),
      name = coalesce(nullif(p_project->>'name', ''), name),
      description = case when p_project ? 'description' then nullif(p_project->>'description', '') else description end,
      client_name = case when p_project ? 'client_name' then nullif(p_project->>'client_name', '') else client_name end,
      project_type = coalesce(nullif(p_project->>'project_type', ''), project_type),
      project_group_id = case when p_project ? 'project_group_id' then nullif(p_project->>'project_group_id', '')::uuid else project_group_id end,
      project_type_id = case when p_project ? 'project_type_id' then nullif(p_project->>'project_type_id', '')::uuid else project_type_id end,
      project_sector_id = case when p_project ? 'project_sector_id' then nullif(p_project->>'project_sector_id', '')::uuid else project_sector_id end,
      workflow_template_id = case when p_project ? 'workflow_template_id' then nullif(p_project->>'workflow_template_id', '')::uuid else workflow_template_id end,
      status = coalesce(nullif(p_project->>'status', ''), status),
      construction_site_id = case when p_project ? 'construction_site_id' then nullif(p_project->>'construction_site_id', '')::uuid else construction_site_id end,
      manager_id = case when p_project ? 'manager_id' then nullif(p_project->>'manager_id', '') else manager_id end,
      start_date = case when p_project ? 'start_date' then nullif(p_project->>'start_date', '')::date else start_date end,
      end_date = case when p_project ? 'end_date' then nullif(p_project->>'end_date', '')::date else end_date end,
      progress_calculation_mode = coalesce(nullif(p_project->>'progress_calculation_mode', ''), progress_calculation_mode),
      manual_progress_percent = case when p_project ? 'manual_progress_percent' then coalesce(nullif(p_project->>'manual_progress_percent', '')::numeric, 0) else manual_progress_percent end,
      is_pinned = case when p_project ? 'is_pinned' then coalesce((p_project->>'is_pinned')::boolean, false) else is_pinned end,
      pinned_at = case when p_project ? 'pinned_at' then nullif(p_project->>'pinned_at', '')::timestamptz else pinned_at end,
      pinned_by = case when p_project ? 'pinned_by' then nullif(p_project->>'pinned_by', '') else pinned_by end,
      is_hidden = case when p_project ? 'is_hidden' then coalesce((p_project->>'is_hidden')::boolean, false) else is_hidden end,
      hidden_at = case when p_project ? 'hidden_at' then nullif(p_project->>'hidden_at', '')::timestamptz else hidden_at end,
      hidden_by = case when p_project ? 'hidden_by' then nullif(p_project->>'hidden_by', '') else hidden_by end,
      hidden_reason = case when p_project ? 'hidden_reason' then nullif(p_project->>'hidden_reason', '') else hidden_reason end
  where id = p_project_id
  returning *
  into v_project;

  if v_project.id is null then
    raise exception 'Project not found: %', p_project_id
      using errcode = 'P0002';
  end if;

  return to_jsonb(v_project);
end;
$$;


--
-- Name: update_quality_checklist_impl(uuid, text, text, uuid, timestamp with time zone, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.update_quality_checklist_impl(p_request_id uuid, p_project_id text, p_construction_site_id text, p_checklist_id uuid, p_expected_updated_at timestamp with time zone, p_changes jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_old public.quality_checklists%rowtype;
  v_row public.quality_checklists%rowtype;
  v_replay jsonb;
  v_result jsonb;
begin
  v_actor := app_private.assert_quality_action(p_project_id, p_construction_site_id, 'edit');
  v_replay := app_private.begin_quality_command(v_actor, p_request_id,
    'update_quality_checklist', md5(jsonb_build_object(
      'projectId', p_project_id, 'constructionSiteId', p_construction_site_id,
      'checklistId', p_checklist_id, 'expectedUpdatedAt', p_expected_updated_at,
      'changes', p_changes
    )::text));
  if v_replay is not null then return v_replay; end if;

  select * into v_old from public.quality_checklists item
  where item.id = p_checklist_id for update;
  if not found or v_old.project_id::text is distinct from p_project_id
    or v_old.construction_site_id::text is distinct from p_construction_site_id then
    raise exception 'QUALITY_SCOPE_MISMATCH' using errcode = '23514';
  end if;
  if v_old.updated_at is distinct from p_expected_updated_at then
    raise exception 'QUALITY_STALE_VERSION' using errcode = '40001';
  end if;
  if v_old.status not in ('draft', 'returned') then
    raise exception 'QUALITY_INVALID_TRANSITION' using errcode = '23514';
  end if;

  update public.quality_checklists item set
    title = case when p_changes ? 'title' then btrim(p_changes ->> 'title') else item.title end,
    work_description = case when p_changes ? 'work_description' then nullif(p_changes ->> 'work_description', '') else item.work_description end,
    work_location = case when p_changes ? 'work_location' then nullif(p_changes ->> 'work_location', '') else item.work_location end,
    work_date = case when p_changes ? 'work_date' then nullif(p_changes ->> 'work_date', '')::date else item.work_date end,
    work_supervisor = case when p_changes ? 'work_supervisor' then nullif(p_changes ->> 'work_supervisor', '') else item.work_supervisor end,
    checklist_data = case when p_changes ? 'checklist_data' then coalesce(p_changes -> 'checklist_data', '[]'::jsonb) else item.checklist_data end,
    site_photos = case when p_changes ? 'site_photos' then coalesce(p_changes -> 'site_photos', '[]'::jsonb) else item.site_photos end,
    attachments = case when p_changes ? 'attachments' then coalesce(p_changes -> 'attachments', '[]'::jsonb) else item.attachments end,
    conclusion = case when p_changes ? 'conclusion' then nullif(p_changes ->> 'conclusion', '') else item.conclusion end,
    conclusion_result = case when p_changes ? 'conclusion_result' then nullif(p_changes ->> 'conclusion_result', '') else item.conclusion_result end,
    conditions = case when p_changes ? 'conditions' then nullif(p_changes ->> 'conditions', '') else item.conditions end,
    inspector_name = case when p_changes ? 'inspector_name' then nullif(p_changes ->> 'inspector_name', '') else item.inspector_name end,
    inspector_sign_url = case when p_changes ? 'inspector_sign_url' then nullif(p_changes ->> 'inspector_sign_url', '') else item.inspector_sign_url end,
    approver_name = case when p_changes ? 'approver_name' then nullif(p_changes ->> 'approver_name', '') else item.approver_name end,
    approver_sign_url = case when p_changes ? 'approver_sign_url' then nullif(p_changes ->> 'approver_sign_url', '') else item.approver_sign_url end,
    inspection_result = case when p_changes ? 'inspection_result' then nullif(p_changes ->> 'inspection_result', '') else item.inspection_result end,
    total_criteria = case when p_changes ? 'total_criteria' then coalesce((p_changes ->> 'total_criteria')::integer, 0) else item.total_criteria end,
    passed_criteria = case when p_changes ? 'passed_criteria' then coalesce((p_changes ->> 'passed_criteria')::integer, 0) else item.passed_criteria end,
    failed_criteria = case when p_changes ? 'failed_criteria' then coalesce((p_changes ->> 'failed_criteria')::integer, 0) else item.failed_criteria end,
    note = case when p_changes ? 'note' then nullif(p_changes ->> 'note', '') else item.note end,
    drawing_url = case when p_changes ? 'drawing_url' then nullif(p_changes ->> 'drawing_url', '') else item.drawing_url end,
    drawing_markers = case when p_changes ? 'drawing_markers' then coalesce(p_changes -> 'drawing_markers', '[]'::jsonb) else item.drawing_markers end,
    target_completion_date = case when p_changes ? 'target_completion_date' then nullif(p_changes ->> 'target_completion_date', '')::date else item.target_completion_date end,
    signers_data = case when p_changes ? 'signers_data' then coalesce(p_changes -> 'signers_data', '[]'::jsonb) else item.signers_data end,
    standard_reference = case when p_changes ? 'standard_reference' then nullif(p_changes ->> 'standard_reference', '') else item.standard_reference end,
    last_action_by = v_actor::text,
    last_action_at = now(),
    updated_at = now()
  where item.id = p_checklist_id
  returning * into v_row;

  if nullif(btrim(v_row.title), '') is null then
    raise exception 'QUALITY_INVALID_TRANSITION: title is required' using errcode = '22023';
  end if;
  insert into public.audit_trail (
    table_name, record_id, action, old_data, new_data, user_id, user_name,
    module, description, context
  ) values (
    'quality_checklists', v_row.id::text, 'UPDATE', to_jsonb(v_old), to_jsonb(v_row),
    v_actor::text, v_actor::text, 'quality', 'Cập nhật hồ sơ chất lượng',
    jsonb_build_object('requestId', p_request_id, 'roomCode', 'quality')
  );
  v_result := jsonb_build_object('ok', true, 'requestId', p_request_id,
    'replayed', false, 'checklist', to_jsonb(v_row));
  return app_private.finish_quality_command(v_actor, p_request_id, v_result);
end;
$$;


--
-- Name: update_safety_worker_assignment(uuid, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.update_safety_worker_assignment(p_assignment_id uuid, p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_assignment public.safety_project_assignments%rowtype;
  v_membership public.safety_worker_site_memberships%rowtype;
  v_worker public.safety_worker_profiles%rowtype;
  v_subcontractor_id uuid;
  v_team_id uuid;
begin
  if jsonb_typeof(coalesce(p_patch, 'null'::jsonb)) <> 'object' then
    raise exception 'SAFETY_INVALID_RPC_PAYLOAD: assignment patch must be an object'
      using errcode = '22023';
  end if;

  select assignment.*
  into v_assignment
  from public.safety_project_assignments assignment
  where assignment.id = p_assignment_id;

  select membership.*
  into v_membership
  from public.safety_worker_site_memberships membership
  where membership.id = v_assignment.membership_id;

  if v_assignment.id is null
    or v_membership.id is null
    or v_actor is null
    or not app_private.safety_workforce_can_manage(v_membership.project_id, v_membership.construction_site_id)
  then
    raise exception 'SAFETY_SCOPE_MISMATCH: actor cannot update assignment'
      using errcode = '42501';
  end if;

  select worker.*
  into v_worker
  from public.safety_worker_profiles worker
  where worker.id = v_assignment.worker_id
  for update;

  perform assignment.id
  from public.safety_project_assignments assignment
  where assignment.id = v_assignment.id
  for update;

  perform membership.id
  from public.safety_worker_site_memberships membership
  where membership.id = v_membership.id
  for update;

  v_subcontractor_id := case
    when p_patch ? 'subcontractorId' then nullif(p_patch ->> 'subcontractorId', '')::uuid
    else v_assignment.subcontractor_id
  end;
  v_team_id := case
    when p_patch ? 'teamId' then nullif(p_patch ->> 'teamId', '')::uuid
    else v_assignment.team_id
  end;

  perform app_private.safety_workforce_assert_subcontractor_team(
    v_membership.project_id,
    v_membership.construction_site_id,
    v_subcontractor_id,
    v_team_id,
    v_worker.worker_kind
  );

  update public.safety_project_assignments assignment
  set subcontractor_id = case when v_worker.worker_kind = 'company_staff' then null else v_subcontractor_id end,
      team_id = case when v_worker.worker_kind = 'company_staff' then null else v_team_id end,
      role_name = case when p_patch ? 'roleName' then nullif(trim(p_patch ->> 'roleName'), '') else assignment.role_name end,
      work_type = case when p_patch ? 'workType' then nullif(trim(p_patch ->> 'workType'), '') else assignment.work_type end,
      site_training_status = case when p_patch ? 'siteTrainingStatus' then p_patch ->> 'siteTrainingStatus' else assignment.site_training_status end,
      commitment_status = case when p_patch ? 'commitmentStatus' then p_patch ->> 'commitmentStatus' else assignment.commitment_status end,
      ppe_status = case when p_patch ? 'ppeStatus' then p_patch ->> 'ppeStatus' else assignment.ppe_status end,
      toolbox_status = case when p_patch ? 'toolboxStatus' then p_patch ->> 'toolboxStatus' else assignment.toolbox_status end,
      is_locked = case when p_patch ? 'isLocked' then (p_patch ->> 'isLocked')::boolean else assignment.is_locked end,
      lock_reason = case when p_patch ? 'lockReason' then nullif(trim(p_patch ->> 'lockReason'), '') else assignment.lock_reason end,
      updated_at = now()
  where assignment.id = v_assignment.id;

  update public.safety_worker_site_memberships membership
  set default_subcontractor_id = case when v_worker.worker_kind = 'company_staff' then null else v_subcontractor_id end,
      default_team_id = case when v_worker.worker_kind = 'company_staff' then null else v_team_id end,
      updated_by = v_actor,
      updated_at = now()
  where membership.id = v_membership.id;

  insert into public.safety_audit_logs (
    actor_user_id, action, target_type, target_id, project_id, construction_site_id, metadata
  ) values (
    v_actor::text,
    'assignment.update',
    'safety_project_assignments',
    v_assignment.id,
    v_membership.project_id,
    v_membership.construction_site_id::text,
    jsonb_build_object(
      'membershipId', v_membership.id,
      'fields', (select jsonb_agg(fields.field_name) from jsonb_object_keys(p_patch) as fields(field_name))
    )
  );

  return app_private.safety_workforce_detail_for_membership(v_membership.id);
end;
$$;


--
-- Name: update_safety_worker_profile_for_site(uuid, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.update_safety_worker_profile_for_site(p_membership_id uuid, p_profile jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_membership public.safety_worker_site_memberships%rowtype;
  v_worker public.safety_worker_profiles%rowtype;
begin
  if jsonb_typeof(coalesce(p_profile, 'null'::jsonb)) <> 'object' then
    raise exception 'SAFETY_INVALID_RPC_PAYLOAD: profile patch must be an object'
      using errcode = '22023';
  end if;

  select membership.*
  into v_membership
  from public.safety_worker_site_memberships membership
  where membership.id = p_membership_id;

  if v_membership.id is null
    or v_actor is null
    or not app_private.safety_workforce_can_manage(v_membership.project_id, v_membership.construction_site_id)
  then
    raise exception 'SAFETY_SCOPE_MISMATCH: actor cannot update worker profile'
      using errcode = '42501';
  end if;

  select worker.*
  into v_worker
  from public.safety_worker_profiles worker
  where worker.id = v_membership.worker_id
  for update;

  perform membership.id
  from public.safety_worker_site_memberships membership
  where membership.id = v_membership.id
  for update;

  if p_profile ? 'fullName' and nullif(trim(p_profile ->> 'fullName'), '') is null then
    raise exception 'SAFETY_INVALID_RPC_PAYLOAD: full name cannot be empty'
      using errcode = '22023';
  end if;
  if p_profile ? 'identityType' and (p_profile ->> 'identityType') not in ('cccd', 'passport', 'other') then
    raise exception 'SAFETY_INVALID_RPC_PAYLOAD: invalid identity type'
      using errcode = '22023';
  end if;

  update public.safety_worker_profiles worker
  set worker_code = case when p_profile ? 'workerCode' then nullif(trim(p_profile ->> 'workerCode'), '') else worker.worker_code end,
      full_name = case when p_profile ? 'fullName' then trim(p_profile ->> 'fullName') else worker.full_name end,
      phone = case when p_profile ? 'phone' then nullif(trim(p_profile ->> 'phone'), '') else worker.phone end,
      date_of_birth = case when p_profile ? 'dateOfBirth' then nullif(p_profile ->> 'dateOfBirth', '')::date else worker.date_of_birth end,
      identity_type = case when p_profile ? 'identityType' then p_profile ->> 'identityType' else worker.identity_type end,
      identity_number = case when p_profile ? 'identityNumber' then nullif(trim(p_profile ->> 'identityNumber'), '') else worker.identity_number end,
      identity_issue_date = case when p_profile ? 'identityIssueDate' then nullif(p_profile ->> 'identityIssueDate', '')::date else worker.identity_issue_date end,
      identity_issue_place = case when p_profile ? 'identityIssuePlace' then nullif(trim(p_profile ->> 'identityIssuePlace'), '') else worker.identity_issue_place end,
      permanent_address = case when p_profile ? 'permanentAddress' then nullif(trim(p_profile ->> 'permanentAddress'), '') else worker.permanent_address end,
      role_name = case when p_profile ? 'roleName' then nullif(trim(p_profile ->> 'roleName'), '') else worker.role_name end,
      photo_attachment = case when p_profile ? 'photoAttachment' then p_profile -> 'photoAttachment' else worker.photo_attachment end,
      updated_by = v_actor::text,
      updated_at = now()
  where worker.id = v_worker.id;

  insert into public.safety_audit_logs (
    actor_user_id, action, target_type, target_id, project_id, construction_site_id, metadata
  ) values (
    v_actor::text,
    'worker.profile.update',
    'safety_worker_profiles',
    v_worker.id,
    v_membership.project_id,
    v_membership.construction_site_id::text,
    jsonb_build_object(
      'membershipId', v_membership.id,
      'fields', (select jsonb_agg(fields.field_name) from jsonb_object_keys(p_profile) as fields(field_name))
    )
  );

  return app_private.safety_workforce_detail_for_membership(v_membership.id);
end;
$$;


--
-- Name: update_unreceived_delivery_batch_v2(uuid, text, text, uuid, text, text, text, numeric, text, date, text, uuid, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.update_unreceived_delivery_batch_v2(p_delivery_batch_id uuid, p_wms_transaction_id text, p_purchase_order_id text, p_idempotency_key uuid, p_supplier_id text, p_supplier_name text, p_fulfillment_mode text, p_vat_rate numeric, p_target_warehouse_id text, p_planned_delivery_date date, p_note text, p_actor_user_id uuid, p_lines jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_batch public.purchase_order_delivery_batches%rowtype;
  v_po public.purchase_orders%rowtype;
  v_tx public.transactions%rowtype;
  v_batch_purchase_order_id text;
  v_wms_items jsonb := '[]'::jsonb;
  v_line jsonb;
  v_existing_line public.purchase_order_delivery_lines%rowtype;
  v_seen_line_ids uuid[] := '{}'::uuid[];
  v_purchase_order_line_id text;
  v_item_id text;
  v_purchase_qty numeric;
  v_stock_qty numeric;
  v_purchase_unit text;
  v_stock_unit text;
  v_purchase_unit_price numeric;
  v_stock_unit_price numeric;
begin
  if p_actor_user_id is null then
    raise exception 'Nguoi thuc hien lenh khong hop le.' using errcode = '42501';
  end if;
  if public.current_app_user_id() is null or p_actor_user_id <> public.current_app_user_id() then
    raise exception 'Nguoi thuc hien lenh khong hop le.' using errcode = '42501';
  end if;
  if p_fulfillment_mode not in ('RECEIVE_TO_STOCK', 'DIRECT_CONSUMPTION') then
    raise exception 'Fulfillment mode khong hop le: %', p_fulfillment_mode using errcode = '22023';
  end if;
  if coalesce(p_vat_rate, 0) < 0 then
    raise exception 'VAT khong duoc am.' using errcode = '22023';
  end if;
  if nullif(trim(coalesce(p_target_warehouse_id, '')), '') is null then
    raise exception 'Kho nhan hang la bat buoc.' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_lines, '[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p_lines, '[]'::jsonb)) = 0 then
    raise exception 'Dot giao phai co it nhat mot dong vat tu.' using errcode = '22023';
  end if;

  select purchase_order_id into v_batch_purchase_order_id
  from public.purchase_order_delivery_batches
  where id = p_delivery_batch_id;
  if not found then
    raise exception 'Khong tim thay Dot giao %.', p_delivery_batch_id using errcode = '22023';
  end if;
  if v_batch_purchase_order_id <> p_purchase_order_id then
    raise exception 'Dot giao khong thuoc Goi mua hang yeu cau.' using errcode = '22023';
  end if;

  select * into v_po
  from public.purchase_orders
  where id = p_purchase_order_id
  for update;
  if not found then
    raise exception 'Khong tim thay Goi mua hang %.', p_purchase_order_id using errcode = '22023';
  end if;

  select * into v_batch
  from public.purchase_order_delivery_batches
  where id = p_delivery_batch_id
  for update;
  if not found then
    raise exception 'Khong tim thay Dot giao %.', p_delivery_batch_id using errcode = '22023';
  end if;
  if v_batch.status = 'quality_approved' then
    raise exception 'Dot da Duyet SL/CL va khong con duoc sua.';
  end if;
  if v_batch.status <> 'receiving' then
    raise exception 'Chi sua Dot giao chua nhan va dang cho WMS.' using errcode = '22023';
  end if;
  if v_batch.purchase_order_id <> p_purchase_order_id then
    raise exception 'Dot giao khong thuoc Goi mua hang yeu cau.' using errcode = '22023';
  end if;
  if v_batch.wms_transaction_id is distinct from p_wms_transaction_id then
    raise exception 'WMS transaction khong khop Dot giao.' using errcode = '22023';
  end if;
  if p_idempotency_key is not null and v_batch.idempotency_key is distinct from p_idempotency_key then
    raise exception 'Idempotency key khong khop Dot giao.' using errcode = '22023';
  end if;

  perform app_private.assert_project_permission_room_action(
    v_po.project_id,
    v_po.construction_site_id,
    'material_po',
    'submit',
    p_actor_user_id
  );

  select * into v_tx
  from public.transactions
  where id = p_wms_transaction_id
  for update;
  if not found then
    raise exception 'Khong tim thay WMS cua Dot giao.' using errcode = '22023';
  end if;
  if v_tx.source_type <> 'po_delivery_batch' or v_tx.source_id <> p_delivery_batch_id::text then
    raise exception 'WMS khong lien ket dung Dot giao.' using errcode = '22023';
  end if;
  if v_tx.status <> 'PENDING'::public.transaction_status then
    raise exception 'Chi sua Dot giao khi WMS con o trang thai cho duyet.' using errcode = '22023';
  end if;

  for v_line in
    select value from jsonb_array_elements(p_lines) as line(value)
  loop
    v_purchase_order_line_id := nullif(v_line ->> 'purchaseOrderLineId', '');
    v_item_id := nullif(v_line ->> 'itemId', '');
    v_purchase_qty := coalesce(nullif(v_line ->> 'purchaseQty', '')::numeric, 0);
    v_stock_qty := coalesce(nullif(v_line ->> 'stockQty', '')::numeric, 0);
    v_purchase_unit := coalesce(nullif(v_line ->> 'purchaseUnit', ''), 'DV mua');
    v_stock_unit := coalesce(nullif(v_line ->> 'stockUnit', ''), v_purchase_unit);
    v_purchase_unit_price := coalesce(nullif(v_line ->> 'purchaseUnitPrice', '')::numeric, 0);
    v_stock_unit_price := coalesce(nullif(v_line ->> 'stockUnitPrice', '')::numeric, 0);

    if v_purchase_order_line_id is null or v_item_id is null then
      raise exception 'Dong Dot giao thieu PO line hoac vat tu.' using errcode = '22023';
    end if;
    if v_purchase_qty <= 0 or v_stock_qty <= 0 then
      raise exception 'So luong Dot giao phai lon hon 0.' using errcode = '22023';
    end if;
    if v_purchase_unit_price < 0 or v_stock_unit_price < 0 then
      raise exception 'Don gia Dot giao khong duoc am.' using errcode = '22023';
    end if;

    select * into v_existing_line
    from public.purchase_order_delivery_lines
    where delivery_batch_id = p_delivery_batch_id
      and purchase_order_line_id = v_purchase_order_line_id
      and item_id = v_item_id
    for update;
    if not found then
      raise exception 'Khong duoc doi vat tu hoac PO line cua Dot giao.' using errcode = '22023';
    end if;
    if v_existing_line.id = any(v_seen_line_ids) then
      raise exception 'Dong Dot giao bi lap trong lenh cap nhat.' using errcode = '22023';
    end if;

    update public.purchase_order_delivery_lines
    set planned_qty = v_purchase_qty,
        unit = v_purchase_unit,
        delivery_unit_price = v_purchase_unit_price,
        stock_planned_qty = v_stock_qty,
        stock_unit = v_stock_unit,
        updated_at = now()
    where id = v_existing_line.id;

    v_seen_line_ids := array_append(v_seen_line_ids, v_existing_line.id);
    v_wms_items := v_wms_items || jsonb_build_array(jsonb_build_object(
      'itemId', v_item_id,
      'quantity', v_stock_qty,
      'orderedQty', v_stock_qty,
      'price', v_stock_unit_price,
      'accountingQty', v_purchase_qty,
      'accountingUnit', v_purchase_unit,
      'accountingPrice', v_purchase_unit_price,
      'purchaseOrderLineId', v_purchase_order_line_id,
      'purchaseOrderDeliveryBatchId', p_delivery_batch_id,
      'purchaseOrderDeliveryLineId', v_existing_line.id,
      'fulfillmentMode', p_fulfillment_mode
    ));
  end loop;

  if exists (
    select 1
    from public.purchase_order_delivery_lines line
    where line.delivery_batch_id = p_delivery_batch_id
      and not (line.id = any(v_seen_line_ids))
  ) then
    raise exception 'Khong duoc them hoac xoa dong vat tu cua Dot giao.' using errcode = '22023';
  end if;

  update public.purchase_order_delivery_batches
  set supplier_id = nullif(p_supplier_id, ''),
      supplier_name_snapshot = nullif(p_supplier_name, ''),
      fulfillment_mode = p_fulfillment_mode,
      vat_rate = coalesce(p_vat_rate, 0),
      planned_delivery_date = p_planned_delivery_date,
      note = nullif(p_note, ''),
      updated_at = now()
  where id = p_delivery_batch_id;

  update public.transactions
  set items = v_wms_items,
      target_warehouse_id = p_target_warehouse_id,
      supplier_id = nullif(p_supplier_id, ''),
      business_partner_id = null,
      business_partner_name_snapshot = nullif(p_supplier_name, ''),
      note = coalesce(v_po.po_number, v_po.id) || '-' || lpad(v_batch.delivery_no::text, 2, '0') || ' dang giao',
      updated_by = p_actor_user_id
  where id = p_wms_transaction_id;

  return app_private.purchase_delivery_command_result_v2(p_delivery_batch_id);
end;
$$;


--
-- Name: upsert_daily_log_responsibility_slot(jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.upsert_daily_log_responsibility_slot(p_slot jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_slot_id uuid := nullif(p_slot->>'id', '')::uuid;
  v_responsibility text := nullif(p_slot->>'responsibility', '');
  v_scope_type text := nullif(p_slot->>'scope_type', '');
  v_scope_id text := nullif(p_slot->>'scope_id', '');
  v_assignee_user_id uuid := nullif(p_slot->>'assignee_user_id', '')::uuid;
  v_permission_code text;
  v_actor_user_id uuid := public.current_app_user_id();
  v_result_id uuid;
  v_existing_slot public.app_responsibility_slots%rowtype;
  v_existing_scope_type text;
  v_existing_scope_id text;
  v_previous_slot jsonb;
  v_effective_status text;
begin
  if v_actor_user_id is null then
    raise exception 'Không xác định được người dùng đang thao tác.' using errcode = '42501';
  end if;

  if v_responsibility not in ('current_verifier', 'current_approver')
    or v_scope_type not in ('global', 'project', 'construction_site')
    or v_assignee_user_id is null then
    raise exception 'Responsibility slot Daily Log không hợp lệ.' using errcode = '22023';
  end if;

  if v_slot_id is not null then
    select *
    into v_existing_slot
    from public.app_responsibility_slots
    where id = v_slot_id
      and subject_type = 'daily_log'
    for update;

    if not found then
      raise exception 'Không tìm thấy Daily Log responsibility slot.' using errcode = 'P0002';
    end if;

    v_existing_scope_type := v_existing_slot.scope_type;
    v_existing_scope_id := v_existing_slot.scope_id;
    v_previous_slot := to_jsonb(v_existing_slot);

    if v_existing_scope_type = 'global' then
      if not (public.is_admin() or public.is_module_admin('DA')) then
        raise exception 'Chỉ quản trị viên dự án được sửa slot toàn cục.' using errcode = '42501';
      end if;
    elsif not app_private.can_manage_project_staff_assignment(
      case when v_existing_scope_type = 'project' then v_existing_scope_id else null end,
      case when v_existing_scope_type = 'construction_site' then v_existing_scope_id else null end
    ) then
      raise exception 'Bạn không có quyền sửa responsibility slot hiện tại.' using errcode = '42501';
    end if;
  end if;

  v_effective_status := coalesce(
    nullif(p_slot->>'status', ''),
    v_existing_slot.status,
    'active'
  );

  if v_effective_status not in ('active', 'inactive') then
    raise exception 'Trạng thái responsibility slot không hợp lệ.' using errcode = '22023';
  end if;

  if v_scope_type = 'global' then
    v_scope_id := '*';
    if not (public.is_admin() or public.is_module_admin('DA')) then
      raise exception 'Chỉ quản trị viên dự án được cấu hình slot toàn cục.' using errcode = '42501';
    end if;
  elsif nullif(v_scope_id, '') is null then
    raise exception 'Responsibility slot phải có phạm vi project hoặc construction site.' using errcode = '23502';
  elsif not app_private.can_manage_project_staff_assignment(
    case when v_scope_type = 'project' then v_scope_id else null end,
    case when v_scope_type = 'construction_site' then v_scope_id else null end
  ) then
    raise exception 'Bạn không có quyền cấu hình responsibility slot ở phạm vi này.' using errcode = '42501';
  end if;

  v_permission_code := case
    when v_responsibility = 'current_approver' then 'project.daily_log.approve'
    else 'project.daily_log.verify'
  end;

  if v_effective_status = 'active'
    and not app_private.daily_log_user_can_receive_assignment(
      case when v_scope_type = 'project' then v_scope_id else null end,
      case when v_scope_type = 'construction_site' then v_scope_id else null end,
      v_permission_code,
      v_assignee_user_id
    ) then
      raise exception 'Người được giao chưa có grant % còn hiệu lực trong phạm vi slot.', v_permission_code
        using errcode = '42501';
  end if;

  if v_slot_id is null then
    insert into public.app_responsibility_slots (
      subject_type, responsibility, scope_type, scope_id, assignee_user_id,
      permission_code, priority, status, starts_at, expires_at, metadata, created_by
    )
    values (
      'daily_log', v_responsibility, v_scope_type, v_scope_id, v_assignee_user_id,
      v_permission_code, coalesce((p_slot->>'priority')::integer, 100),
      v_effective_status,
      coalesce(nullif(p_slot->>'starts_at', '')::timestamptz, now()),
      nullif(p_slot->>'expires_at', '')::timestamptz,
      coalesce(p_slot->'metadata', '{}'::jsonb), v_actor_user_id
    )
    returning id into v_result_id;
  else
    update public.app_responsibility_slots
    set responsibility = v_responsibility,
        scope_type = v_scope_type,
        scope_id = v_scope_id,
        assignee_user_id = v_assignee_user_id,
        permission_code = v_permission_code,
        priority = coalesce((p_slot->>'priority')::integer, priority),
        status = v_effective_status,
        starts_at = coalesce(nullif(p_slot->>'starts_at', '')::timestamptz, starts_at),
        expires_at = case when p_slot ? 'expires_at' then nullif(p_slot->>'expires_at', '')::timestamptz else expires_at end,
        metadata = coalesce(p_slot->'metadata', metadata),
        updated_at = now()
    where id = v_slot_id
      and subject_type = 'daily_log'
    returning id into v_result_id;

  end if;

  insert into public.app_responsibility_slot_events (
    responsibility_slot_id,
    event_type,
    actor_user_id,
    before_data,
    after_data
  )
  select
    v_result_id,
    case when v_previous_slot is null then 'created' else 'updated' end,
    v_actor_user_id,
    v_previous_slot,
    to_jsonb(slot)
  from public.app_responsibility_slots slot
  where slot.id = v_result_id;

  return v_result_id;
end;
$$;


--
-- Name: upsert_project_category(text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.upsert_project_category(p_category_kind text, p_category jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_table text := app_private.project_category_table_name(p_category_kind);
  v_result jsonb;
  v_id text := nullif(p_category->>'id', '');
begin
  if v_table is null then
    raise exception 'Invalid project category kind: %', p_category_kind
      using errcode = '22023';
  end if;

  if not app_private.can_manage_project_master(null, 'project.master.manage_categories') then
    raise exception 'Not allowed to manage project categories'
      using errcode = '42501';
  end if;

  if v_id is null then
    if nullif(p_category->>'name', '') is null then
      raise exception 'Project category name is required'
        using errcode = '23502';
    end if;

    execute format(
      'insert into public.%I (code, name, description, sort_order, is_active)
       values ($1, $2, $3, $4, $5)
       returning to_jsonb(%I.*)',
      v_table,
      v_table
    )
    into v_result
    using
      nullif(p_category->>'code', ''),
      nullif(p_category->>'name', ''),
      nullif(p_category->>'description', ''),
      coalesce(nullif(p_category->>'sort_order', '')::int, 0),
      coalesce((p_category->>'is_active')::boolean, true);

    return v_result;
  end if;

  execute format(
    'update public.%I
     set code = case when $2 then $3 else code end,
         name = case when $4 then coalesce($5, name) else name end,
         description = case when $6 then $7 else description end,
         sort_order = case when $8 then coalesce($9, sort_order) else sort_order end,
         is_active = case when $10 then coalesce($11, is_active) else is_active end,
         updated_at = now()
     where id = $1::uuid
     returning to_jsonb(%I.*)',
    v_table,
    v_table
  )
  into v_result
  using
    v_id,
    p_category ? 'code',
    nullif(p_category->>'code', ''),
    p_category ? 'name',
    nullif(p_category->>'name', ''),
    p_category ? 'description',
    nullif(p_category->>'description', ''),
    p_category ? 'sort_order',
    nullif(p_category->>'sort_order', '')::int,
    p_category ? 'is_active',
    (p_category->>'is_active')::boolean;

  if v_result is null then
    raise exception 'Project category not found: % %', p_category_kind, v_id
      using errcode = 'P0002';
  end if;

  return v_result;
end;
$_$;


--
-- Name: upsert_project_document_link(text, text, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.upsert_project_document_link(p_source_type text, p_source_id text, p_target_type text, p_target_id text, p_project_id text DEFAULT NULL::text, p_relation_type text DEFAULT 'downstream'::text, p_status text DEFAULT 'active'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if nullif(trim(coalesce(p_source_type, '')), '') is null
    or nullif(trim(coalesce(p_source_id, '')), '') is null
    or nullif(trim(coalesce(p_target_type, '')), '') is null
    or nullif(trim(coalesce(p_target_id, '')), '') is null
  then
    return;
  end if;

  insert into public.project_document_links (
    source_type,
    source_id,
    target_type,
    target_id,
    project_id,
    relation_type,
    status,
    metadata
  )
  values (
    p_source_type,
    p_source_id,
    p_target_type,
    p_target_id,
    p_project_id,
    coalesce(nullif(p_relation_type, ''), 'downstream'),
    app_private.trace_link_status(p_status),
    coalesce(p_metadata, '{}'::jsonb)
  )
  on conflict (source_type, source_id, target_type, target_id, relation_type)
  do update set
    project_id = coalesce(excluded.project_id, public.project_document_links.project_id),
    status = excluded.status,
    metadata = coalesce(public.project_document_links.metadata, '{}'::jsonb) || excluded.metadata,
    updated_at = now();
end;
$$;


--
-- Name: upsert_project_progress_snapshot(text, text, text, date, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.upsert_project_progress_snapshot(p_scope_key text, p_project_id text, p_construction_site_id text, p_week_start date, p_snapshot jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_snapshot public.weekly_progress_snapshots%rowtype;
begin
  perform app_private.assert_project_progress_snapshot(p_snapshot);

  insert into public.weekly_progress_snapshots (
    scope_key,
    project_id,
    construction_site_id,
    week_label,
    week_start,
    progress_percent,
    progress_mode,
    supplied_value,
    contract_total_value,
    gantt_percent,
    construction_progress_percent,
    value_progress_percent,
    purchased_value,
    issued_value,
    recognized_value,
    calculated_at,
    updated_at
  ) values (
    p_scope_key,
    p_project_id,
    nullif(p_construction_site_id, ''),
    'W' || to_char(p_week_start, 'IW') || '/' || to_char(p_week_start, 'IYYY'),
    p_week_start,
    (p_snapshot ->> 'constructionProgressPercent')::numeric,
    btrim(p_snapshot ->> 'progressMode'),
    nullif(p_snapshot ->> 'suppliedValue', '')::numeric,
    nullif(p_snapshot ->> 'contractTotalValue', '')::numeric,
    nullif(p_snapshot ->> 'ganttPercent', '')::numeric,
    (p_snapshot ->> 'constructionProgressPercent')::numeric,
    (p_snapshot ->> 'valueProgressPercent')::numeric,
    coalesce(nullif(p_snapshot ->> 'purchasedValue', '')::numeric, 0),
    coalesce(nullif(p_snapshot ->> 'issuedValue', '')::numeric, 0),
    coalesce(nullif(p_snapshot ->> 'recognizedValue', '')::numeric, 0),
    coalesce(nullif(p_snapshot ->> 'calculatedAt', '')::timestamptz, now()),
    now()
  )
  on conflict (scope_key, week_start) do update
  set project_id = excluded.project_id,
      construction_site_id = excluded.construction_site_id,
      week_label = excluded.week_label,
      progress_percent = excluded.progress_percent,
      progress_mode = excluded.progress_mode,
      supplied_value = excluded.supplied_value,
      contract_total_value = excluded.contract_total_value,
      gantt_percent = excluded.gantt_percent,
      construction_progress_percent = excluded.construction_progress_percent,
      value_progress_percent = excluded.value_progress_percent,
      purchased_value = excluded.purchased_value,
      issued_value = excluded.issued_value,
      recognized_value = excluded.recognized_value,
      calculated_at = excluded.calculated_at,
      updated_at = now()
  returning * into v_snapshot;

  return jsonb_build_object(
    'id', v_snapshot.id,
    'scopeKey', v_snapshot.scope_key,
    'projectId', v_snapshot.project_id,
    'constructionSiteId', v_snapshot.construction_site_id,
    'weekLabel', v_snapshot.week_label,
    'weekStart', v_snapshot.week_start,
    'progressPercent', v_snapshot.progress_percent,
    'constructionProgressPercent', v_snapshot.construction_progress_percent,
    'valueProgressPercent', v_snapshot.value_progress_percent,
    'progressMode', v_snapshot.progress_mode,
    'suppliedValue', v_snapshot.supplied_value,
    'contractTotalValue', v_snapshot.contract_total_value,
    'purchasedValue', v_snapshot.purchased_value,
    'issuedValue', v_snapshot.issued_value,
    'recognizedValue', v_snapshot.recognized_value,
    'ganttPercent', v_snapshot.gantt_percent,
    'calculatedAt', v_snapshot.calculated_at,
    'createdAt', v_snapshot.created_at,
    'updatedAt', v_snapshot.updated_at
  );
end;
$$;


--
-- Name: upsert_project_staff_assignment(jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.upsert_project_staff_assignment(p_staff jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_staff public.project_staff%rowtype;
  v_result public.project_staff%rowtype;
  v_staff_id uuid := nullif(p_staff->>'id', '')::uuid;
  v_project_id text;
  v_construction_site_id text;
  v_user_id text;
  v_position_id uuid;
  v_start_date date;
  v_note text;
  v_sort_order int;
begin
  if v_staff_id is not null then
    select *
    into v_staff
    from public.project_staff
    where id = v_staff_id;

    if v_staff.id is null then
      raise exception 'Project staff row does not exist: %', v_staff_id
        using errcode = 'P0002';
    end if;
  end if;

  v_project_id := case when p_staff ? 'project_id' then nullif(p_staff->>'project_id', '') else v_staff.project_id end;
  v_construction_site_id := case when p_staff ? 'construction_site_id' then nullif(p_staff->>'construction_site_id', '') else v_staff.construction_site_id end;
  v_user_id := case when p_staff ? 'user_id' then nullif(p_staff->>'user_id', '') else v_staff.user_id end;
  v_position_id := case when p_staff ? 'position_id' then nullif(p_staff->>'position_id', '')::uuid else v_staff.position_id end;
  v_start_date := case when p_staff ? 'start_date' then nullif(p_staff->>'start_date', '')::date else coalesce(v_staff.start_date, current_date) end;
  v_note := case when p_staff ? 'note' then nullif(p_staff->>'note', '') else v_staff.note end;
  v_sort_order := case when p_staff ? 'sort_order' then coalesce(nullif(p_staff->>'sort_order', '')::int, 0) else coalesce(v_staff.sort_order, 0) end;

  if v_project_id is null and v_construction_site_id is null then
    raise exception 'Project staff assignment requires project_id or construction_site_id'
      using errcode = '23502';
  end if;

  if v_user_id is null then
    raise exception 'Project staff assignment requires user_id'
      using errcode = '23502';
  end if;

  if v_position_id is null then
    raise exception 'Project staff assignment requires position_id'
      using errcode = '23502';
  end if;

  if v_staff_id is not null and not app_private.can_manage_project_staff_assignment(v_staff.project_id, v_staff.construction_site_id) then
    raise exception 'Not allowed to update this project staff assignment'
      using errcode = '42501';
  end if;

  if not app_private.can_manage_project_staff_assignment(v_project_id, v_construction_site_id) then
    raise exception 'Not allowed to manage project staff assignments'
      using errcode = '42501';
  end if;

  if v_staff_id is null then
    insert into public.project_staff (
      project_id,
      construction_site_id,
      user_id,
      position_id,
      start_date,
      note,
      sort_order
    )
    values (
      v_project_id,
      v_construction_site_id,
      v_user_id,
      v_position_id,
      v_start_date,
      v_note,
      v_sort_order
    )
    returning *
    into v_result;
  else
    update public.project_staff
    set project_id = v_project_id,
        construction_site_id = v_construction_site_id,
        user_id = v_user_id,
        position_id = v_position_id,
        start_date = v_start_date,
        note = v_note,
        sort_order = v_sort_order,
        updated_at = now()
    where id = v_staff_id
    returning *
    into v_result;
  end if;

  insert into public.permission_audit_events (
    actor_user_id,
    target_user_id,
    event_type,
    metadata
  )
  values (
    public.current_app_user_id(),
    case when v_user_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then v_user_id::uuid else null end,
    'upsert_project_staff_assignment',
    jsonb_build_object(
      'staff_id', v_result.id,
      'project_id', v_project_id,
      'construction_site_id', v_construction_site_id
    )
  );

  return v_result.id;
end;
$_$;


--
-- Name: upsert_safety_worker_certificate_for_site(uuid, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.upsert_safety_worker_certificate_for_site(p_membership_id uuid, p_certificate jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_membership public.safety_worker_site_memberships%rowtype;
  v_certificate_id uuid := nullif(p_certificate ->> 'id', '')::uuid;
  v_certificate_type_id uuid := nullif(p_certificate ->> 'certificateTypeId', '')::uuid;
  v_existing public.safety_worker_certificates%rowtype;
  v_attachments jsonb := coalesce(p_certificate -> 'attachments', '[]'::jsonb);
  v_assignment_id uuid;
begin
  if jsonb_typeof(coalesce(p_certificate, 'null'::jsonb)) <> 'object'
    or v_certificate_type_id is null
    or jsonb_typeof(v_attachments) <> 'array'
    or jsonb_array_length(v_attachments) = 0
  then
    raise exception 'SAFETY_INVALID_RPC_PAYLOAD: certificate type and attachment are required' using errcode = '22023';
  end if;
  if nullif(p_certificate ->> 'issueDate', '') is not null
    and nullif(p_certificate ->> 'expiryDate', '') is not null
    and (p_certificate ->> 'expiryDate')::date < (p_certificate ->> 'issueDate')::date
  then
    raise exception 'SAFETY_INVALID_RPC_PAYLOAD: certificate expiry cannot precede issue date' using errcode = '22023';
  end if;

  select membership into v_membership
  from public.safety_worker_site_memberships membership
  where membership.id = p_membership_id
  for update;

  if v_membership.id is null or v_actor is null
    or not app_private.safety_workforce_can_manage(v_membership.project_id, v_membership.construction_site_id)
  then
    raise exception 'SAFETY_SCOPE_MISMATCH: actor cannot update worker certificate' using errcode = '42501';
  end if;

  perform certificate_type.id
  from public.safety_certificate_types certificate_type
  where certificate_type.id = v_certificate_type_id and certificate_type.is_active;
  if not found then
    raise exception 'SAFETY_INVALID_RPC_PAYLOAD: certificate type is inactive or missing' using errcode = '22023';
  end if;

  if v_certificate_id is not null then
    select certificate into v_existing
    from public.safety_worker_certificates certificate
    where certificate.id = v_certificate_id
    for update;
    if v_existing.id is null or v_existing.worker_id <> v_membership.worker_id then
      raise exception 'SAFETY_SCOPE_MISMATCH: certificate is outside worker profile' using errcode = '42501';
    end if;
    update public.safety_worker_certificates certificate
    set certificate_type_id = v_certificate_type_id,
        certificate_no = nullif(trim(p_certificate ->> 'certificateNo'), ''),
        issue_date = nullif(p_certificate ->> 'issueDate', '')::date,
        expiry_date = nullif(p_certificate ->> 'expiryDate', '')::date,
        attachments = v_attachments,
        status = 'approved',
        verified_by = v_actor::text,
        verified_at = now(),
        note = nullif(trim(p_certificate ->> 'note'), ''),
        updated_at = now()
    where certificate.id = v_certificate_id;
  else
    insert into public.safety_worker_certificates (
      worker_id, certificate_type_id, certificate_no, issue_date, expiry_date,
      attachments, status, verified_by, verified_at, note, created_by
    ) values (
      v_membership.worker_id, v_certificate_type_id,
      nullif(trim(p_certificate ->> 'certificateNo'), ''),
      nullif(p_certificate ->> 'issueDate', '')::date,
      nullif(p_certificate ->> 'expiryDate', '')::date,
      v_attachments, 'approved', v_actor::text, now(),
      nullif(trim(p_certificate ->> 'note'), ''), v_actor::text
    ) returning id into v_certificate_id;
  end if;

  for v_assignment_id in
    select assignment.id from public.safety_project_assignments assignment
    where assignment.worker_id = v_membership.worker_id
  loop
    perform app_private.recompute_safety_assignment_eligibility(v_assignment_id);
  end loop;

  insert into public.safety_audit_logs (
    actor_user_id, action, target_type, target_id, project_id, construction_site_id, metadata
  ) values (
    v_actor::text, 'worker.certificate.upsert', 'safety_worker_certificates', v_certificate_id,
    v_membership.project_id, v_membership.construction_site_id::text,
    jsonb_build_object('membershipId', v_membership.id, 'workerId', v_membership.worker_id, 'certificateTypeId', v_certificate_type_id)
  );

  return app_private.safety_workforce_detail_for_membership(v_membership.id);
end;
$$;


--
-- Name: upsert_safety_worker_documents_for_site(uuid, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.upsert_safety_worker_documents_for_site(p_membership_id uuid, p_documents jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_membership public.safety_worker_site_memberships%rowtype;
  v_document jsonb;
  v_document_id uuid;
begin
  if jsonb_typeof(coalesce(p_documents, 'null'::jsonb)) <> 'array' then
    raise exception 'SAFETY_INVALID_RPC_PAYLOAD: documents must be an array'
      using errcode = '22023';
  end if;

  select membership.*
  into v_membership
  from public.safety_worker_site_memberships membership
  where membership.id = p_membership_id
  for update;

  if v_membership.id is null
    or v_actor is null
    or not app_private.safety_workforce_can_view_sensitive(v_membership.project_id, v_membership.construction_site_id)
  then
    raise exception 'SAFETY_SCOPE_MISMATCH: actor cannot update worker documents'
      using errcode = '42501';
  end if;

  for v_document in select value from jsonb_array_elements(p_documents)
  loop
    if jsonb_typeof(v_document) <> 'object'
      or nullif(trim(v_document ->> 'documentType'), '') is null
      or nullif(trim(v_document ->> 'name'), '') is null
    then
      raise exception 'SAFETY_INVALID_RPC_PAYLOAD: document type and name are required'
        using errcode = '22023';
    end if;
    if jsonb_typeof(coalesce(v_document -> 'attachments', '[]'::jsonb)) <> 'array' then
      raise exception 'SAFETY_INVALID_RPC_PAYLOAD: attachments must be an array'
        using errcode = '22023';
    end if;

    v_document_id := nullif(v_document ->> 'id', '')::uuid;
    if v_document_id is null
      and (v_document ->> 'documentType') in ('identity_front', 'identity_back', 'health_check', 'insurance', 'safety_card')
    then
      select document.id
      into v_document_id
      from public.safety_worker_documents document
      where document.worker_id = v_membership.worker_id
        and document.document_type = v_document ->> 'documentType'
      order by document.created_at desc, document.id desc
      limit 1;
    end if;

    if v_document_id is not null then
      update public.safety_worker_documents document
      set document_type = v_document ->> 'documentType',
          name = trim(v_document ->> 'name'),
          issue_date = nullif(v_document ->> 'issueDate', '')::date,
          expiry_date = nullif(v_document ->> 'expiryDate', '')::date,
          attachments = coalesce(v_document -> 'attachments', '[]'::jsonb),
          status = coalesce(nullif(v_document ->> 'status', ''), document.status),
          is_required = coalesce((v_document ->> 'isRequired')::boolean, document.is_required),
          updated_at = now()
      where document.id = v_document_id
        and document.worker_id = v_membership.worker_id;

      if not found then
        raise exception 'SAFETY_SCOPE_MISMATCH: document is outside worker profile'
          using errcode = '42501';
      end if;
    else
      insert into public.safety_worker_documents (
        worker_id, document_type, name, issue_date, expiry_date,
        attachments, status, is_required, created_by
      ) values (
        v_membership.worker_id,
        v_document ->> 'documentType',
        trim(v_document ->> 'name'),
        nullif(v_document ->> 'issueDate', '')::date,
        nullif(v_document ->> 'expiryDate', '')::date,
        coalesce(v_document -> 'attachments', '[]'::jsonb),
        coalesce(nullif(v_document ->> 'status', ''), 'submitted'),
        coalesce((v_document ->> 'isRequired')::boolean, false),
        v_actor::text
      );
    end if;
  end loop;

  insert into public.safety_audit_logs (
    actor_user_id, action, target_type, target_id, project_id, construction_site_id, metadata
  ) values (
    v_actor::text,
    'worker.documents.upsert',
    'safety_worker_profiles',
    v_membership.worker_id,
    v_membership.project_id,
    v_membership.construction_site_id::text,
    jsonb_build_object('membershipId', v_membership.id, 'count', jsonb_array_length(p_documents))
  );

  return app_private.safety_workforce_detail_for_membership(v_membership.id);
end;
$$;


--
-- Name: upsert_work_group(jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.upsert_work_group(p_work_group jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_result jsonb;
  v_id text := nullif(p_work_group->>'id', '');
begin
  if not app_private.can_manage_work_groups() then
    raise exception 'Not allowed to manage work groups'
      using errcode = '42501';
  end if;

  if v_id is null then
    if nullif(p_work_group->>'name', '') is null then
      raise exception 'Work group name is required'
        using errcode = '23502';
    end if;

    insert into public.work_groups (code, name, description, sort_order, is_active)
    values (
      nullif(p_work_group->>'code', ''),
      nullif(p_work_group->>'name', ''),
      nullif(p_work_group->>'description', ''),
      coalesce(nullif(p_work_group->>'sort_order', '')::int, 0),
      coalesce((p_work_group->>'is_active')::boolean, true)
    )
    returning to_jsonb(public.work_groups.*)
    into v_result;

    return v_result;
  end if;

  update public.work_groups
  set code = case when p_work_group ? 'code' then nullif(p_work_group->>'code', '') else code end,
      name = case when p_work_group ? 'name' then coalesce(nullif(p_work_group->>'name', ''), name) else name end,
      description = case when p_work_group ? 'description' then nullif(p_work_group->>'description', '') else description end,
      sort_order = case when p_work_group ? 'sort_order' then coalesce(nullif(p_work_group->>'sort_order', '')::int, sort_order) else sort_order end,
      is_active = case when p_work_group ? 'is_active' then coalesce((p_work_group->>'is_active')::boolean, is_active) else is_active end,
      updated_at = now()
  where id = v_id::uuid
  returning to_jsonb(public.work_groups.*)
  into v_result;

  if v_result is null then
    raise exception 'Work group not found: %', v_id
      using errcode = 'P0002';
  end if;

  return v_result;
end;
$$;


--
-- Name: user_application_membership_is_effective(uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.user_application_membership_is_effective(p_user_id uuid, p_application_code text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.user_application_memberships membership_row
    join public.users user_row on user_row.id = membership_row.user_id
    join public.permission_applications application_row on application_row.code = membership_row.application_code
    where membership_row.user_id = p_user_id
      and membership_row.application_code = p_application_code
      and membership_row.status = 'ACTIVE'
      and user_row.is_active
      and user_row.account_status = 'ACTIVE'
      and user_row.role = 'EMPLOYEE'
      and application_row.is_active
      and application_row.member_assignable
  );
$$;


--
-- Name: user_permission_state_fingerprint(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.user_permission_state_fingerprint(p_user_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app_private.permission_state_fingerprint_for_values(
    jsonb_build_object(
      'allowedModules', to_jsonb(user_row.allowed_modules),
      'allowedSubModules', user_row.allowed_sub_modules,
      'adminModules', to_jsonb(user_row.admin_modules),
      'adminSubModules', user_row.admin_sub_modules
    ),
    app_private.direct_permission_state_for_user(user_row.id)
  )
  from public.users user_row
  where user_row.id = p_user_id;
$$;


--
-- Name: uuid_or_null(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.uuid_or_null(p_value text) RETURNS uuid
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
begin
  if nullif(btrim(coalesce(p_value, '')), '') is null then
    return null;
  end if;

  if p_value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return p_value::uuid;
  end if;

  return null;
end;
$_$;


--
-- Name: validate_enforced_site_warehouse_default(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.validate_enforced_site_warehouse_default() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_site_id uuid;
  v_site_name text;
  v_default_count integer;
begin
  for v_site_id in
    select distinct affected.site_id
    from (
      select case when tg_op <> 'INSERT' then old.construction_site_id end as site_id
      union all
      select case when tg_op <> 'DELETE' then new.construction_site_id end as site_id
    ) affected
    where affected.site_id is not null
  loop
    select site.name into v_site_name
    from public.hrm_construction_sites site
    where site.id = v_site_id
      and site.warehouse_binding_enforced;

    if not found then
      continue;
    end if;

    select count(*) into v_default_count
    from public.warehouses warehouse
    where warehouse.construction_site_id = v_site_id
      and warehouse.type = 'SITE'
      and not coalesce(warehouse.is_archived, false)
      and warehouse.is_default_for_site;

    if v_default_count <> 1 then
      raise exception 'Công trường % đã khóa kho và phải luôn có đúng một kho mặc định đang hoạt động.', v_site_name;
    end if;
  end loop;

  return null;
end;
$$;


--
-- Name: validate_project_permission_room_member_action(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.validate_project_permission_room_member_action() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_allowed_actions text[];
begin
  select room.allowed_actions
  into v_allowed_actions
  from public.project_permission_room_members member
  join public.project_permission_rooms room on room.code = member.room_code
  where member.id = new.room_member_id;

  if v_allowed_actions is null or not (new.action_code = any(v_allowed_actions)) then
    raise exception 'Action % is not allowed in this permission Room', new.action_code
      using errcode = '23514';
  end if;

  return new;
end;
$$;


--
-- Name: validate_site_warehouse_enforcement(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.validate_site_warehouse_enforcement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_eligible_count integer;
  v_default_count integer;
begin
  if not new.warehouse_binding_enforced
     or new.warehouse_binding_enforced is not distinct from old.warehouse_binding_enforced
  then
    return new;
  end if;

  select
    count(*) filter (
      where warehouse.type = 'SITE'
        and not coalesce(warehouse.is_archived, false)
    ),
    count(*) filter (
      where warehouse.type = 'SITE'
        and not coalesce(warehouse.is_archived, false)
        and warehouse.is_default_for_site
    )
  into v_eligible_count, v_default_count
  from public.warehouses warehouse
  where warehouse.construction_site_id = new.id;

  if v_eligible_count < 1 or v_default_count <> 1 then
    raise exception 'Công trường % phải có ít nhất một kho SITE đang hoạt động và đúng một kho mặc định trước khi bật khóa kho.', new.name;
  end if;

  return new;
end;
$$;


--
-- Name: validate_warehouse_project_scope(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.validate_warehouse_project_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_project_site uuid;
begin
  if new.type = 'SITE' and not coalesce(new.is_archived, false) then
    if new.project_id is null or new.construction_site_id is null then
      raise exception 'Kho công trường đang hoạt động phải gắn đủ dự án và công trường.';
    end if;
  end if;

  if new.project_id is not null then
    select project.construction_site_id into v_project_site
    from public.projects project
    where project.id = new.project_id;
    if not found then
      raise exception 'Không tìm thấy dự án %.', new.project_id;
    end if;
    if v_project_site is distinct from new.construction_site_id then
      raise exception 'Dự án và công trường của kho không cùng scope.';
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: vehicle_active_dispatcher_count(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.vehicle_active_dispatcher_count() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select count(distinct grant_row.user_id)::integer
  from public.user_permission_grants grant_row
  join public.users app_user on app_user.id = grant_row.user_id
  where grant_row.permission_code = 'booking.vehicle.dispatch'
    and grant_row.scope_type = 'global'
    and grant_row.scope_id = '*'
    and grant_row.is_active
    and grant_row.revoked_at is null
    and (grant_row.expires_at is null or grant_row.expires_at > now())
    and coalesce(app_user.is_active, true)
    and coalesce(app_user.account_status, 'ACTIVE') = 'ACTIVE';
$$;


--
-- Name: vehicle_assert_evidence_path(uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.vehicle_assert_evidence_path(p_booking_id uuid, p_path text, p_namespace text) RETURNS void
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if nullif(trim(p_path), '') is null then
    raise exception using errcode = 'P0001', message = 'ODOMETER_PHOTO_REQUIRED';
  end if;
  if p_path not like p_booking_id::text || '/' || p_namespace || '/%' then
    raise exception using errcode = 'P0001', message = 'INVALID_EVIDENCE_PATH';
  end if;
end;
$$;


--
-- Name: vehicle_assert_operator_eligible(uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.vehicle_assert_operator_eligible(p_operator_user_id uuid, p_authorization_type text, p_vehicle_type text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_authorization public.vehicle_driver_authorizations%rowtype;
begin
  if not exists (
    select 1
    from public.users app_user
    where app_user.id = p_operator_user_id
      and coalesce(app_user.is_active, true)
      and coalesce(app_user.account_status, 'ACTIVE') = 'ACTIVE'
  ) then
    raise exception using errcode = 'P0001', message = 'OPERATOR_UNAVAILABLE';
  end if;

  select *
  into v_authorization
  from public.vehicle_driver_authorizations authorization_row
  where authorization_row.user_id = p_operator_user_id
    and authorization_row.authorization_type = p_authorization_type;

  if not found or v_authorization.status <> 'ACTIVE' then
    raise exception using errcode = 'P0001', message = case
      when p_authorization_type = 'SELF_DRIVE' then 'SELF_DRIVER_NOT_AUTHORIZED'
      else 'DRIVER_NOT_AUTHORIZED'
    end;
  end if;

  if v_authorization.license_expiry < current_date then
    raise exception using errcode = 'P0001', message = 'DRIVER_LICENSE_EXPIRED';
  end if;

  if v_authorization.health_check_expiry_date is not null
     and v_authorization.health_check_expiry_date < current_date then
    raise exception using errcode = 'P0001', message = 'OPERATOR_UNAVAILABLE';
  end if;

  if v_authorization.allowed_vehicle_types is null
     or not (p_vehicle_type = any(v_authorization.allowed_vehicle_types)) then
    raise exception using errcode = 'P0001', message = 'DRIVER_VEHICLE_TYPE_MISMATCH';
  end if;
end;
$$;


--
-- Name: vehicle_driver_authorizations_eligible_rows(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.vehicle_driver_authorizations_eligible_rows(p_actor_user_id uuid) RETURNS TABLE(id uuid, user_id uuid, employee_id uuid, authorization_type text, license_class text, license_expiry date, allowed_vehicle_types text[], status text, is_eligible boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    vda.id,
    vda.user_id,
    vda.employee_id,
    vda.authorization_type,
    vda.license_class,
    vda.license_expiry,
    vda.allowed_vehicle_types,
    vda.status,
    (
      vda.status = 'ACTIVE'
      and vda.license_expiry >= current_date
      and (
        vda.health_check_expiry_date is null
        or vda.health_check_expiry_date >= current_date
      )
      and exists (
        select 1 from public.users u
        where u.id = vda.user_id
          and coalesce(u.is_active, true)
          and coalesce(u.account_status, 'ACTIVE') = 'ACTIVE'
      )
    ) as is_eligible
  from public.vehicle_driver_authorizations vda
  where vda.user_id = p_actor_user_id
     or app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.dispatch')
     or app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.manage_authorizations');
$$;


--
-- Name: vehicle_enqueue_dispatcher_notifications(uuid, text, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.vehicle_enqueue_dispatcher_notifications(p_booking_id uuid, p_event_type text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_recipient record;
  v_count integer := 0;
begin
  for v_recipient in
    select distinct grant_row.user_id
    from public.user_permission_grants grant_row
    join public.users app_user on app_user.id = grant_row.user_id
    where grant_row.permission_code = 'booking.vehicle.dispatch'
      and grant_row.scope_type = 'global'
      and grant_row.scope_id = '*'
      and grant_row.is_active
      and grant_row.revoked_at is null
      and (grant_row.expires_at is null or grant_row.expires_at > now())
      and coalesce(app_user.is_active, true)
      and coalesce(app_user.account_status, 'ACTIVE') = 'ACTIVE'
  loop
    perform app_private.vehicle_enqueue_notification(
      p_booking_id,
      p_event_type,
      v_recipient.user_id,
      p_payload
    );
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;


--
-- Name: vehicle_enqueue_notification(uuid, text, uuid, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.vehicle_enqueue_notification(p_booking_id uuid, p_event_type text, p_recipient_user_id uuid, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_event_type text := coalesce(nullif(trim(p_event_type), ''), 'BOOKING_UPDATED');
  v_assignment_id text := nullif(trim(coalesce(p_payload ->> 'assignment_id', '')), '');
  v_event_key text;
begin
  if p_recipient_user_id is null then
    return;
  end if;

  v_event_key := 'vehicle:' || p_booking_id::text || ':' || v_event_type || ':' || p_recipient_user_id::text;
  if v_assignment_id is not null then
    v_event_key := v_event_key || ':' || v_assignment_id;
  end if;

  insert into app_private.vehicle_booking_notification_outbox (
    event_key,
    recipient_user_id,
    event_type,
    payload
  ) values (
    v_event_key,
    p_recipient_user_id,
    v_event_type,
    coalesce(p_payload, '{}'::jsonb) || jsonb_build_object(
      'booking_id', p_booking_id,
      'event_type', v_event_type
    )
  ) on conflict (event_key, recipient_user_id) do nothing;
end;
$$;


--
-- Name: vehicle_normalize_assignment_version(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.vehicle_normalize_assignment_version() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_next_version integer;
begin
  select coalesce(max(assignment.version), 0) + 1
  into v_next_version
  from public.vehicle_booking_assignments assignment
  where assignment.booking_id = new.booking_id;

  new.version := greatest(coalesce(new.version, 1), v_next_version);
  return new;
end;
$$;


--
-- Name: vehicle_notification_title(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.vehicle_notification_title(p_event_type text) RETURNS text
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case p_event_type
    when 'BOOKING_SUBMITTED' then 'Yêu cầu đặt xe cần duyệt'
    when 'BOOKING_WAITING_DISPATCH' then 'Có yêu cầu đặt xe chờ điều phối'
    when 'BOOKING_MANAGER_REASSIGNED' then 'Bạn được giao duyệt yêu cầu đặt xe'
    when 'BOOKING_MANAGER_REASSIGNED_AWAY' then 'Yêu cầu đặt xe đã chuyển người duyệt'
    when 'BOOKING_REJECTED' then 'Yêu cầu đặt xe bị từ chối'
    when 'BOOKING_ASSIGNED' then 'Đã xếp phương án chuyến xe'
    when 'HANDOVER_ASSIGNED' then 'Bạn được giao bàn giao xe'
    when 'BOOKING_REASSIGNED' then 'Phương án chuyến xe đã thay đổi'
    when 'BOOKING_REASSIGNED_OLD_OPERATOR' then 'Bạn đã được gỡ khỏi chuyến xe'
    when 'BOOKING_REASSIGNED_NEW_OPERATOR' then 'Bạn được phân công chuyến xe'
    when 'ASSIGNMENT_DECLINED' then 'Người lái từ chối chuyến xe'
    when 'TRIP_COMPLETED' then 'Chuyến xe đã hoàn thành'
    when 'VEHICLE_RETURN_REQUIRED' then 'Cần nhận lại xe và chìa khóa'
    when 'BOOKING_CANCELLED' then 'Booking xe đã bị hủy'
    when 'BOOKING_NO_SHOW' then 'Booking xe được ghi nhận no-show'
    when 'FEEDBACK_AUTO_CLOSED' then 'Xác nhận sau chuyến đã tự đóng'
    when 'ISSUE_RESOLVED' then 'Phản ánh chuyến xe đã được xử lý'
    else 'Cập nhật booking xe'
  end;
$$;


--
-- Name: vehicle_raise_permission_denied(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.vehicle_raise_permission_denied(p_detail text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  raise exception using
    errcode = '42501',
    message = 'PERMISSION_DENIED',
    detail = p_detail;
end;
$$;


--
-- Name: vehicle_record_audit(uuid, uuid, text, jsonb, jsonb, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.vehicle_record_audit(p_actor_user_id uuid, p_booking_id uuid, p_event text, p_old_data jsonb DEFAULT '{}'::jsonb, p_new_data jsonb DEFAULT '{}'::jsonb, p_description text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.audit_trail (
    table_name,
    record_id,
    action,
    changes,
    old_data,
    new_data,
    user_id,
    user_name,
    module,
    description,
    record_label,
    entity_type,
    changed_fields,
    change_count,
    impact_level,
    context
  ) values (
    'vehicle_bookings',
    p_booking_id::text,
    'UPDATE',
    jsonb_build_object('event', p_event),
    coalesce(p_old_data, '{}'::jsonb),
    coalesce(p_new_data, '{}'::jsonb),
    p_actor_user_id::text,
    '',
    'VEHICLE_BOOKING',
    coalesce(p_description, p_event),
    p_booking_id::text,
    'vehicle_booking',
    array(select jsonb_object_keys(coalesce(p_new_data, '{}'::jsonb))),
    (
      select count(*)::integer
      from jsonb_object_keys(coalesce(p_new_data, '{}'::jsonb))
    ),
    case when p_event like '%OVERRIDE%' or p_event in ('NO_SHOW', 'CANCELLED') then 'high' else 'normal' end,
    jsonb_build_object('booking_id', p_booking_id, 'event', p_event)
  );
end;
$$;


--
-- Name: vehicle_release_declined_assignment(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.vehicle_release_declined_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.operator_confirmation_status = 'DECLINED'
     and old.operator_confirmation_status is distinct from 'DECLINED'
     and old.is_active then
    new.is_active := false;
    new.released_at := coalesce(new.released_at, now());

    update public.vehicle_bookings
    set status = 'WAITING_DISPATCH',
        updated_at = now()
    where id = new.booking_id
      and status = 'ASSIGNED';

    delete from public.vehicle_trip_logs
    where booking_id = new.booking_id
      and assignment_id = new.id
      and trip_status = 'NOT_STARTED';
  end if;

  return new;
end;
$$;


--
-- Name: vehicle_require_audit_scope(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.vehicle_require_audit_scope(p_actor_user_id uuid, p_department_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_department_id is null then
    if not app_private.vehicle_user_has_scoped_permission(
      p_actor_user_id,
      'booking.vehicle.view_audit',
      'global',
      '*'
    ) then
      perform app_private.vehicle_raise_permission_denied(
        'Global vehicle audit permission required'
      );
    end if;
  elsif not (
    app_private.vehicle_user_has_scoped_permission(
      p_actor_user_id,
      'booking.vehicle.view_audit',
      'global',
      '*'
    )
    or app_private.vehicle_user_has_scoped_permission(
      p_actor_user_id,
      'booking.vehicle.view_audit',
      'department',
      p_department_id::text
    )
  ) then
    perform app_private.vehicle_raise_permission_denied(
      'Department vehicle audit permission required'
    );
  end if;
end;
$$;


--
-- Name: vehicle_require_current_actor(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.vehicle_require_current_actor(p_actor_user_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_actor_user_id is distinct from public.current_app_user_id() then
    raise exception using
      errcode = '42501',
      message = 'VEHICLE_ACTOR_MISMATCH';
  end if;
end;
$$;


