--
-- Name: vehicle_snapshot_assignment_version(); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.vehicle_snapshot_assignment_version() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_assignment_version integer;
begin
  select assignment.version
  into v_assignment_version
  from public.vehicle_booking_assignments assignment
  where assignment.id = new.assignment_id
    and assignment.booking_id = new.booking_id;

  if v_assignment_version is null then
    raise exception using errcode = '23503', message = 'ASSIGNMENT_NOT_FOUND';
  end if;

  new.assignment_version_snapshot := v_assignment_version;
  return new;
end;
$$;


--
-- Name: vehicle_user_can_access_evidence(uuid, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.vehicle_user_can_access_evidence(p_user_id uuid, p_object_name text, p_operation text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_parts text[] := storage.foldername(p_object_name);
  v_booking_id uuid;
  v_subject_user_id uuid;
  v_namespace text;
begin
  if p_user_id is null or coalesce(array_length(v_parts, 1), 0) < 2 then
    return false;
  end if;

  v_namespace := v_parts[1];

  if v_namespace = 'licenses' then
    begin
      v_subject_user_id := v_parts[2]::uuid;
    exception when invalid_text_representation then
      return false;
    end;

    if p_operation = 'SELECT' then
      return p_user_id = v_subject_user_id
        or app_private.vehicle_user_has_permission(p_user_id, 'booking.vehicle.manage_authorizations');
    end if;

    return app_private.vehicle_user_has_permission(p_user_id, 'booking.vehicle.manage_authorizations');
  end if;

  if v_namespace = 'fleet' then
    return app_private.vehicle_user_has_permission(p_user_id, 'booking.vehicle.manage_fleet')
      or (
        p_operation = 'SELECT'
        and app_private.vehicle_user_has_permission(p_user_id, 'booking.vehicle.dispatch')
      );
  end if;

  begin
    v_booking_id := v_namespace::uuid;
  exception when invalid_text_representation then
    return false;
  end;

  if v_parts[2] not in ('trips', 'external') then
    return false;
  end if;

  if p_operation = 'SELECT' then
    return app_private.vehicle_user_can_view_booking(p_user_id, v_booking_id);
  end if;

  if v_parts[2] = 'external' then
    return exists (
      select 1
      from public.vehicle_bookings b
      where b.id = v_booking_id
        and (b.requester_user_id = p_user_id or b.trip_owner_user_id = p_user_id)
    ) or app_private.vehicle_user_has_permission(p_user_id, 'booking.vehicle.dispatch');
  end if;

  return exists (
    select 1
    from public.vehicle_booking_assignments a
    where a.booking_id = v_booking_id
      and a.is_active
      and (a.operator_user_id = p_user_id or a.handover_officer_user_id = p_user_id)
  ) or app_private.vehicle_user_has_permission(p_user_id, 'booking.vehicle.dispatch');
end;
$$;


--
-- Name: vehicle_user_can_manage_asset_images(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.vehicle_user_can_manage_asset_images(p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_user_id is not null and (
    exists (
      select 1
      from public.users app_user
      where app_user.id = p_user_id
        and app_user.role = 'ADMIN'
    )
    or app_private.vehicle_user_has_permission(
      p_user_id,
      'booking.vehicle.manage_fleet'
    )
    or app_private.asset_has_any_action(
      'asset.catalog.edit',
      p_user_id
    )
    or app_private.asset_has_any_action(
      'asset.catalog.create',
      p_user_id
    )
  );
$$;


--
-- Name: vehicle_user_can_view_booking(uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.vehicle_user_can_view_booking(p_user_id uuid, p_booking_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_user_id is not null
    and p_booking_id is not null
    and (
      app_private.vehicle_user_has_permission(p_user_id, 'booking.vehicle.dispatch')
      or app_private.vehicle_user_has_permission(p_user_id, 'booking.vehicle.manage_fleet')
      or app_private.vehicle_user_has_permission(p_user_id, 'booking.vehicle.view_reports')
      or exists (
        select 1
        from public.vehicle_bookings b
        where b.id = p_booking_id
          and p_user_id in (
            b.requester_user_id,
            coalesce(b.trip_owner_user_id, b.requester_user_id),
            coalesce(b.manager_user_id_snapshot, b.requester_user_id)
          )
      )
      or exists (
        select 1
        from public.vehicle_booking_participants participant
        where participant.booking_id = p_booking_id
          and participant.user_id = p_user_id
      )
      or exists (
        select 1
        from public.vehicle_booking_assignments assignment
        where assignment.booking_id = p_booking_id
          and assignment.is_active
          and p_user_id in (
            coalesce(assignment.operator_user_id, p_user_id),
            coalesce(assignment.handover_officer_user_id, p_user_id)
          )
          and (
            assignment.operator_user_id = p_user_id
            or assignment.handover_officer_user_id = p_user_id
          )
      )
    );
$$;


--
-- Name: vehicle_user_can_view_issue(uuid, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.vehicle_user_can_view_issue(p_user_id uuid, p_booking_id uuid, p_reporter_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_user_id is not null
    and (
      p_user_id = p_reporter_user_id
      or app_private.vehicle_user_has_permission(
        p_user_id,
        'booking.vehicle.view_sensitive_feedback'
      )
    );
$$;


--
-- Name: vehicle_user_has_permission(uuid, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.vehicle_user_has_permission(p_user_id uuid, p_permission_code text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app_private.vehicle_user_has_scoped_permission(
    p_user_id,
    p_permission_code,
    'global',
    '*'
  );
$$;


--
-- Name: vehicle_user_has_scoped_permission(uuid, text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.vehicle_user_has_scoped_permission(p_user_id uuid, p_permission_code text, p_scope_type text DEFAULT 'global'::text, p_scope_id text DEFAULT '*'::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_is_active boolean := false;
  v_role text;
begin
  if p_user_id is null or nullif(trim(p_permission_code), '') is null then
    return false;
  end if;

  select
    coalesce(app_user.is_active, true)
      and coalesce(app_user.account_status, 'ACTIVE') = 'ACTIVE',
    app_user.role::text
  into v_is_active, v_role
  from public.users app_user
  where app_user.id = p_user_id;

  if not coalesce(v_is_active, false) then
    return false;
  end if;

  if v_role = 'ADMIN' then
    return true;
  end if;

  if p_permission_code in ('booking.vehicle.create', 'booking.vehicle.view_own') then
    return true;
  end if;

  return exists (
    select 1
    from public.user_permission_grants grant_row
    where grant_row.user_id = p_user_id
      and grant_row.permission_code in (p_permission_code, 'booking.vehicle.admin')
      and coalesce(grant_row.is_active, false)
      and grant_row.revoked_at is null
      and (grant_row.expires_at is null or grant_row.expires_at > now())
      and (
        grant_row.scope_type = 'global'
        or (
          grant_row.scope_type = coalesce(p_scope_type, 'global')
          and (
            grant_row.scope_id = '*'
            or grant_row.scope_id = coalesce(p_scope_id, '*')
          )
        )
      )
  );
end;
$$;


--
-- Name: vehicle_validate_assignment(uuid, text, text, uuid, uuid, boolean, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.vehicle_validate_assignment(p_booking_id uuid, p_fulfillment_type text, p_vehicle_asset_id text, p_operator_user_id uuid, p_handover_officer_user_id uuid, p_allow_non_home_base_return boolean, p_non_home_base_return_reason text, p_external_service_type text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_booking public.vehicle_bookings%rowtype;
  v_vehicle public.fleet_vehicle_profiles%rowtype;
  v_buffer_minutes integer := 0;
  v_reserved_range tstzrange;
begin
  select * into v_booking
  from public.vehicle_bookings b
  where b.id = p_booking_id;

  if not found then
    raise exception using errcode = 'P0001', message = 'BOOKING_NOT_FOUND';
  end if;

  select coalesce(settings.booking_buffer_minutes, 0)
  into v_buffer_minutes
  from public.fleet_system_settings settings
  where settings.id = 1;

  v_reserved_range := tstzrange(
    v_booking.requested_pickup_at,
    v_booking.expected_return_at + make_interval(mins => coalesce(v_buffer_minutes, 0)),
    '[)'
  );

  if coalesce(p_allow_non_home_base_return, false)
     and nullif(trim(p_non_home_base_return_reason), '') is null then
    raise exception using errcode = 'P0001', message = 'NON_HOME_BASE_RETURN_REASON_REQUIRED';
  end if;

  if p_fulfillment_type = 'EXTERNAL_TRANSPORT' then
    if p_vehicle_asset_id is not null or p_operator_user_id is not null
       or p_handover_officer_user_id is not null then
      raise exception using errcode = 'P0001', message = 'INVALID_EXTERNAL_ASSIGNMENT';
    end if;
    if nullif(trim(p_external_service_type), '') is null then
      raise exception using errcode = 'P0001', message = 'EXTERNAL_SERVICE_TYPE_REQUIRED';
    end if;
    return;
  end if;

  if p_fulfillment_type not in ('INTERNAL_WITH_DRIVER', 'INTERNAL_SELF_DRIVE') then
    raise exception using errcode = 'P0001', message = 'INVALID_FULFILLMENT_TYPE';
  end if;

  if p_vehicle_asset_id is null then
    raise exception using errcode = 'P0001', message = 'VEHICLE_REQUIRED';
  end if;
  if p_operator_user_id is null then
    raise exception using errcode = 'P0001', message = 'OPERATOR_REQUIRED';
  end if;
  if p_fulfillment_type = 'INTERNAL_SELF_DRIVE' and p_handover_officer_user_id is null then
    raise exception using errcode = 'P0001', message = 'HANDOVER_OFFICER_REQUIRED';
  end if;

  select * into v_vehicle
  from public.fleet_vehicle_profiles profile
  where profile.asset_id = p_vehicle_asset_id
  for share;

  if not found or not v_vehicle.active
     or v_vehicle.availability_status <> 'AVAILABLE'
     or v_vehicle.home_base_id is null then
    raise exception using errcode = 'P0001', message = 'VEHICLE_UNAVAILABLE';
  end if;

  if v_vehicle.inspection_expiry_date is not null
     and v_vehicle.inspection_expiry_date < current_date then
    raise exception using errcode = 'P0001', message = 'VEHICLE_INSPECTION_EXPIRED';
  end if;
  if v_vehicle.insurance_expiry_date is not null
     and v_vehicle.insurance_expiry_date < current_date then
    raise exception using errcode = 'P0001', message = 'VEHICLE_INSURANCE_EXPIRED';
  end if;
  if p_fulfillment_type = 'INTERNAL_SELF_DRIVE' and not v_vehicle.allow_self_drive then
    raise exception using errcode = 'P0001', message = 'SELF_DRIVE_NOT_ALLOWED';
  end if;

  perform app_private.vehicle_assert_operator_eligible(
    p_operator_user_id,
    case when p_fulfillment_type = 'INTERNAL_SELF_DRIVE'
      then 'SELF_DRIVE' else 'PROFESSIONAL_DRIVER' end,
    v_vehicle.vehicle_type
  );

  if exists (
    select 1
    from public.vehicle_unavailability_periods unavailable
    where unavailable.vehicle_asset_id = p_vehicle_asset_id
      and unavailable.scheduled_range && v_reserved_range
  ) then
    raise exception using errcode = 'P0001', message = 'VEHICLE_UNAVAILABLE';
  end if;

  if exists (
    select 1
    from public.operator_unavailability_periods unavailable
    where unavailable.operator_user_id = p_operator_user_id
      and unavailable.scheduled_range && v_reserved_range
  ) then
    raise exception using errcode = 'P0001', message = 'OPERATOR_UNAVAILABLE';
  end if;
end;
$$;


--
-- Name: wms_has_action(text, text, text, uuid, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.wms_has_action(p_permission_code text, p_source_warehouse_id text DEFAULT NULL::text, p_target_warehouse_id text DEFAULT NULL::text, p_requester_id uuid DEFAULT NULL::uuid, p_assigned_user_id uuid DEFAULT NULL::uuid, p_user_id uuid DEFAULT public.current_app_user_id()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_permission_code like 'wms.%'
  and p_user_id is not null
  and (
    app_private.has_permission(p_user_id, p_permission_code, 'global', '*')
    or (
      p_source_warehouse_id is not null
      and app_private.has_permission(p_user_id, p_permission_code, 'warehouse', p_source_warehouse_id)
    )
    or (
      p_target_warehouse_id is not null
      and app_private.has_permission(p_user_id, p_permission_code, 'warehouse', p_target_warehouse_id)
    )
    or (
      p_requester_id = p_user_id
      and app_private.has_permission(p_user_id, p_permission_code, 'own', p_user_id::text)
    )
    or (
      p_assigned_user_id = p_user_id
      and app_private.has_permission(p_user_id, p_permission_code, 'assigned', p_user_id::text)
    )
    or public.is_module_admin('WMS')
    or app_private.current_user_is_global_wms_keeper()
    or app_private.current_user_is_wms_keeper_for(p_source_warehouse_id)
    or app_private.current_user_is_wms_keeper_for(p_target_warehouse_id)
  );
$$;


--
-- Name: wms_request_can_access(uuid, text, text, text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.wms_request_can_access(p_requester_id uuid, p_submitted_to_user_id text, p_source_warehouse_id text, p_site_warehouse_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    app_private.wms_has_action(
      'wms.request.view',
      p_source_warehouse_id,
      p_site_warehouse_id,
      p_requester_id,
      nullif(p_submitted_to_user_id, '')::uuid
    )
    or p_requester_id = public.current_app_user_id()
    or (
      p_submitted_to_user_id is not null
      and p_submitted_to_user_id = public.current_app_user_id()::text
    );
$$;


--
-- Name: wms_transaction_attachment_can_access(text); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.wms_transaction_attachment_can_access(p_object_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    public.is_admin()
    or public.is_module_admin('WMS')
    or app_private.current_user_is_global_wms_keeper()
    or exists (
      select 1
      from public.transactions tx
      where tx.id = split_part(p_object_name, '/', 1)
        and (
          app_private.current_user_is_wms_keeper_for(tx.target_warehouse_id)
          or app_private.current_user_is_wms_keeper_for(tx.source_warehouse_id)
          or tx.requester_id::text = public.current_app_user_id()::text
        )
    ),
    false
  );
$$;


--
-- Name: workflow_assignee_json(uuid, uuid[]); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.workflow_assignee_json(p_node_id uuid, p_assignee_user_ids uuid[]) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_node_id is null
      or p_assignee_user_ids is null
      or cardinality(p_assignee_user_ids) = 0
    then '{}'::jsonb
    else jsonb_build_object(
      p_node_id::text,
      to_jsonb(array(
        select distinct assignee.assignee_id::text
        from unnest(p_assignee_user_ids) as assignee(assignee_id)
        where assignee.assignee_id is not null
      ))
    )
  end;
$$;


--
-- Name: workflow_has_action(text, uuid, uuid, uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.workflow_has_action(p_permission_code text, p_owner_user_id uuid DEFAULT NULL::uuid, p_assigned_user_id uuid DEFAULT NULL::uuid, p_user_id uuid DEFAULT public.current_app_user_id()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select (p_permission_code like 'workflow.%' or p_permission_code like 'request.%')
  and p_user_id is not null
  and (
    app_private.has_permission(p_user_id, p_permission_code, 'global', '*')
    or (
      p_owner_user_id = p_user_id
      and app_private.has_permission(p_user_id, p_permission_code, 'own', p_user_id::text)
    )
    or (
      p_assigned_user_id = p_user_id
      and app_private.has_permission(p_user_id, p_permission_code, 'assigned', p_user_id::text)
    )
    or (
      p_permission_code like 'workflow.%'
      and public.is_module_admin('WF')
    )
    or (
      p_permission_code like 'request.%'
      and public.is_module_admin('RQ')
    )
  );
$$;


--
-- Name: workflow_instance_actor_can_select(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.workflow_instance_actor_can_select(p_instance_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.workflow_instances wi
    where wi.id = p_instance_id
      and app_private.project_workflow_instance_can_select(wi.id)
  );
$$;


--
-- Name: workflow_subject_can_mutate(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.workflow_subject_can_mutate(p_subject_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.workflow_subjects ws
    where ws.id = p_subject_id
      and (
        public.is_admin()
        or public.is_module_admin('WF')
        or ws.current_assignee_user_id = public.current_app_user_id()
      )
  );
$$;


--
-- Name: workflow_subject_can_select(uuid); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.workflow_subject_can_select(p_subject_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.workflow_subjects ws
    join public.requests r
      on ws.subject_type = 'material_request'
     and r.id = ws.subject_id
    where ws.id = p_subject_id
      and app_private.material_request_can_select(
        r.request_origin,
        r.project_id,
        r.requester_id,
        r.submitted_to_user_id,
        r.source_warehouse_id,
        r.site_warehouse_id
      )
  );
$$;


--
-- Name: write_project_progress_period_payload(uuid, text, text, text, text, date, jsonb, jsonb); Type: FUNCTION; Schema: app_private; Owner: -
--

CREATE FUNCTION app_private.write_project_progress_period_payload(p_actor_id uuid, p_scope_key text, p_project_id text, p_construction_site_id text, p_period_type text, p_period_start date, p_rows jsonb, p_snapshot jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_site_id text := nullif(p_construction_site_id, '');
  v_week_start date := case
    when p_period_type = 'weekly' then p_period_start
    else p_period_start - (extract(isodow from p_period_start)::integer - 1)
  end;
  v_week_state public.project_progress_period_states%rowtype;
  v_weekly_frozen boolean := false;
  v_parent_depth integer := 0;
  v_max_parent_depth integer := 0;
begin
  perform app_private.assert_project_progress_rows(
    p_project_id, v_site_id, p_period_type, p_rows
  );
  perform app_private.assert_project_progress_snapshot(p_snapshot);

  if p_period_type = 'daily' then
    insert into public.project_progress_period_states (
      scope_key, project_id, construction_site_id, period_type, period_start
    ) values (
      p_scope_key, p_project_id, v_site_id, 'weekly', v_week_start
    ) on conflict (scope_key, period_type, period_start) do nothing;

    select state.* into v_week_state
    from public.project_progress_period_states state
    where state.scope_key = p_scope_key
      and state.period_type = 'weekly'
      and state.period_start = v_week_start
    for update;

    v_weekly_frozen := v_week_state.is_locked;

    insert into public.project_daily_task_progress (
      scope_key, project_id, construction_site_id, task_id,
      progress_date, week_start, progress_percent, quantity_done,
      daily_quantity_done, note, attachments, source_daily_log_id,
      updated_by, updated_at
    )
    select
      p_scope_key,
      p_project_id,
      v_site_id,
      item.value ->> 'taskId',
      p_period_start,
      v_week_start,
      (item.value ->> 'progressPercent')::numeric,
      coalesce(nullif(item.value ->> 'quantityDone', '')::numeric, 0),
      coalesce(nullif(item.value ->> 'dailyQuantityDone', '')::numeric, 0),
      nullif(btrim(item.value ->> 'note'), ''),
      coalesce(item.value -> 'attachments', '[]'::jsonb),
      nullif(btrim(item.value ->> 'sourceDailyLogId'), ''),
      p_actor_id::text,
      now()
    from jsonb_array_elements(p_rows) item(value)
    on conflict (scope_key, task_id, progress_date) do update
    set project_id = excluded.project_id,
        construction_site_id = excluded.construction_site_id,
        week_start = excluded.week_start,
        progress_percent = excluded.progress_percent,
        quantity_done = excluded.quantity_done,
        daily_quantity_done = excluded.daily_quantity_done,
        note = excluded.note,
        attachments = excluded.attachments,
        source_daily_log_id = excluded.source_daily_log_id,
        updated_by = excluded.updated_by,
        updated_at = excluded.updated_at;

    if not v_weekly_frozen then
      insert into public.project_weekly_task_progress (
        scope_key, project_id, construction_site_id, task_id, week_start,
        progress_percent, quantity_done, note, attachments, updated_by, updated_at
      )
      select distinct on (daily.task_id)
        p_scope_key,
        p_project_id,
        v_site_id,
        daily.task_id,
        v_week_start,
        daily.progress_percent,
        daily.quantity_done,
        daily.note,
        daily.attachments,
        p_actor_id::text,
        now()
      from public.project_daily_task_progress daily
      where daily.scope_key = p_scope_key
        and daily.week_start = v_week_start
        and daily.task_id in (
          select item.value ->> 'taskId'
          from jsonb_array_elements(p_rows) item(value)
        )
      order by daily.task_id, daily.progress_date desc, daily.updated_at desc
      on conflict (scope_key, task_id, week_start) do update
      set project_id = excluded.project_id,
          construction_site_id = excluded.construction_site_id,
          progress_percent = excluded.progress_percent,
          quantity_done = excluded.quantity_done,
          note = excluded.note,
          attachments = excluded.attachments,
          updated_by = excluded.updated_by,
          updated_at = excluded.updated_at;

      perform app_private.upsert_project_progress_snapshot(
        p_scope_key, p_project_id, v_site_id, v_week_start, p_snapshot
      );
    end if;
  else
    insert into public.project_weekly_task_progress (
      scope_key, project_id, construction_site_id, task_id, week_start,
      progress_percent, quantity_done, note, attachments, updated_by, updated_at
    )
    select
      p_scope_key,
      p_project_id,
      v_site_id,
      item.value ->> 'taskId',
      p_period_start,
      (item.value ->> 'progressPercent')::numeric,
      coalesce(nullif(item.value ->> 'quantityDone', '')::numeric, 0),
      nullif(btrim(item.value ->> 'note'), ''),
      coalesce(item.value -> 'attachments', '[]'::jsonb),
      p_actor_id::text,
      now()
    from jsonb_array_elements(p_rows) item(value)
    on conflict (scope_key, task_id, week_start) do update
    set project_id = excluded.project_id,
        construction_site_id = excluded.construction_site_id,
        progress_percent = excluded.progress_percent,
        quantity_done = excluded.quantity_done,
        note = excluded.note,
        attachments = excluded.attachments,
        updated_by = excluded.updated_by,
        updated_at = excluded.updated_at;

    perform app_private.upsert_project_progress_snapshot(
      p_scope_key, p_project_id, v_site_id, p_period_start, p_snapshot
    );
  end if;

  with submitted_tasks as (
    select item.value ->> 'taskId' as task_id
    from jsonb_array_elements(p_rows) item(value)
  ), daily_ranked as (
    select
      daily.task_id,
      daily.progress_percent,
      daily.progress_date as effective_date,
      row_number() over (
        partition by daily.task_id
        order by daily.progress_date desc, daily.updated_at desc
      ) as recency_rank
    from public.project_daily_task_progress daily
    join submitted_tasks submitted on submitted.task_id = daily.task_id
    where p_period_type = 'daily'
      and daily.scope_key = p_scope_key
  ), authoritative_progress as (
    select ranked.task_id, ranked.progress_percent, ranked.effective_date
    from daily_ranked ranked
    where ranked.recency_rank = 1
    union all
    select weekly.task_id, weekly.progress_percent, weekly.week_start
    from public.project_weekly_task_progress weekly
    join submitted_tasks submitted on submitted.task_id = weekly.task_id
    where p_period_type = 'weekly'
      and weekly.scope_key = p_scope_key
      and weekly.week_start = p_period_start
  )
  update public.project_tasks task
  set progress = authoritative.progress_percent,
      progress_mode = 'weekly_report',
      actual_start_date = case
        when authoritative.progress_percent > 0
          then coalesce(task.actual_start_date, authoritative.effective_date)
        else task.actual_start_date
      end,
      actual_end_date = case
        when authoritative.progress_percent >= 100
          then coalesce(task.actual_end_date, authoritative.effective_date)
        else task.actual_end_date
      end,
      gate_status = case
        when authoritative.progress_percent >= 100 then 'approved'
        when task.gate_status in ('pending', 'approved') then 'none'
        else task.gate_status
      end,
      gate_approved_by = case
        when authoritative.progress_percent < 100
          and task.gate_status in ('pending', 'approved') then null
        else task.gate_approved_by
      end,
      gate_approved_at = case
        when authoritative.progress_percent < 100
          and task.gate_status in ('pending', 'approved') then null
        else task.gate_approved_at
      end
  from authoritative_progress authoritative
  where task.id = authoritative.task_id
    and task.project_id is not distinct from p_project_id
    and nullif(task.construction_site_id::text, '') is not distinct from v_site_id;

  -- Recompute changed tasks' ancestors from the bottom up, matching the
  -- existing children_auto rule: quantity-weighted when every child has a
  -- provisional quantity, otherwise a simple average. Parent progress is
  -- clamped to 0..100 even though leaf over-completion remains supported.
  with recursive ancestors(task_id, depth) as (
    select task.parent_id, 1
    from public.project_tasks task
    where task.id in (
      select item.value ->> 'taskId'
      from jsonb_array_elements(p_rows) item(value)
    )
      and task.project_id is not distinct from p_project_id
      and nullif(task.construction_site_id::text, '') is not distinct from v_site_id
      and task.parent_id is not null
    union all
    select parent.parent_id, ancestors.depth + 1
    from ancestors
    join public.project_tasks parent on parent.id = ancestors.task_id
    where parent.project_id is not distinct from p_project_id
      and nullif(parent.construction_site_id::text, '') is not distinct from v_site_id
      and parent.parent_id is not null
      and ancestors.depth < 100
  )
  select coalesce(max(ancestors.depth), 0)
  into v_max_parent_depth
  from ancestors;

  for v_parent_depth in 1..v_max_parent_depth loop
    with recursive ancestors(task_id, depth) as (
      select task.parent_id, 1
      from public.project_tasks task
      where task.id in (
        select item.value ->> 'taskId'
        from jsonb_array_elements(p_rows) item(value)
      )
        and task.project_id is not distinct from p_project_id
        and nullif(task.construction_site_id::text, '') is not distinct from v_site_id
        and task.parent_id is not null
      union all
      select parent.parent_id, ancestors.depth + 1
      from ancestors
      join public.project_tasks parent on parent.id = ancestors.task_id
      where parent.project_id is not distinct from p_project_id
        and nullif(parent.construction_site_id::text, '') is not distinct from v_site_id
        and parent.parent_id is not null
        and ancestors.depth < 100
    ), target_parent as (
      select distinct ancestors.task_id
      from ancestors
      where ancestors.depth = v_parent_depth
    ), derived as (
      select
        parent.id,
        least(100, greatest(0, case
          when bool_and(coalesce(child.provisional_quantity, 0) > 0)
            then round(
              sum(least(100, greatest(0, child.progress)) * child.provisional_quantity)
              / nullif(sum(child.provisional_quantity), 0)
            )
          else round(avg(least(100, greatest(0, child.progress))))
        end)) as progress
      from target_parent target
      join public.project_tasks parent on parent.id = target.task_id
      join public.project_tasks child on child.parent_id = parent.id
      where parent.project_id is not distinct from p_project_id
        and nullif(parent.construction_site_id::text, '') is not distinct from v_site_id
        and child.project_id is not distinct from p_project_id
        and nullif(child.construction_site_id::text, '') is not distinct from v_site_id
      group by parent.id
    )
    update public.project_tasks task
    set progress = derived.progress,
        progress_mode = 'children_auto',
        gate_status = case
          when derived.progress >= 100 then 'approved'
          when task.gate_status in ('pending', 'approved') then 'none'
          else task.gate_status
        end,
        gate_approved_by = case
          when derived.progress < 100 and task.gate_status in ('pending', 'approved') then null
          else task.gate_approved_by
        end,
        gate_approved_at = case
          when derived.progress < 100 and task.gate_status in ('pending', 'approved') then null
          else task.gate_approved_at
        end,
        actual_end_date = case
          when derived.progress >= 100 then coalesce(task.actual_end_date, p_period_start)
          else task.actual_end_date
        end
    from derived
    where task.id = derived.id;
  end loop;

  return v_weekly_frozen;
end;
$$;


--
-- Name: notify_web_push_on_notification(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.notify_web_push_on_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_url text;
  v_secret text;
begin
  if new.user_id is null or coalesce(new.push_enabled, true) is false then
    return new;
  end if;

  select decrypted_secret
    into v_url
  from vault.decrypted_secrets
  where name = 'send_web_push_url'
  limit 1;

  select decrypted_secret
    into v_secret
  from vault.decrypted_secrets
  where name = 'send_web_push_secret'
  limit 1;

  if coalesce(v_url, '') = '' or coalesce(v_secret, '') = '' then
    return new;
  end if;

  perform net.http_post(
    url := v_url,
    body := jsonb_build_object('notificationId', new.id),
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-web-push-secret', v_secret
    ),
    timeout_milliseconds := 5000
  );

  return new;
end;
$$;


--
-- Name: accrue_leave_balances(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accrue_leave_balances() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ DECLARE v_current_month INTEGER := EXTRACT(MONTH FROM NOW())::INTEGER; v_current_year INTEGER := EXTRACT(YEAR FROM NOW())::INTEGER; v_months_missing INTEGER; v_new_accrued NUMERIC; BEGIN IF NEW.year <> v_current_year THEN RETURN NEW; END IF; IF NEW.last_accrual_month >= v_current_month THEN RETURN NEW; END IF; v_months_missing := v_current_month - COALESCE(NEW.last_accrual_month, 0); v_new_accrued := COALESCE(NEW.accrued_days, 0) + COALESCE(NEW.monthly_accrual, 1.5) * v_months_missing; NEW.accrued_days := v_new_accrued; NEW.last_accrual_month := v_current_month; RETURN NEW; END; $$;


