--
-- Name: workflow_subjects; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workflow_subjects (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workflow_instance_id uuid,
    subject_type text NOT NULL,
    subject_id text NOT NULL,
    project_id text,
    construction_site_id text,
    current_assignee_user_id uuid,
    current_node_id uuid,
    status text DEFAULT 'RUNNING'::text NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    return_to_node_id uuid,
    return_to_assignee_user_id uuid,
    returned_by_user_id uuid,
    returned_at timestamp with time zone,
    template_version_id uuid,
    current_instance_node_id uuid,
    current_assignee_user_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    return_to_assignee_user_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    return_to_instance_node_id uuid,
    last_action_instance_node_id uuid,
    CONSTRAINT workflow_subjects_status_check CHECK ((status = ANY (ARRAY['RUNNING'::text, 'RETURNED'::text, 'COMPLETED'::text, 'REJECTED'::text, 'CANCELLED'::text]))),
    CONSTRAINT workflow_subjects_subject_type_check CHECK ((subject_type = ANY (ARRAY['material_request'::text, 'custom_material_request'::text, 'request'::text])))
);


--
-- Name: advance_project_workflow(text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advance_project_workflow(p_subject_type text, p_subject_id text, p_next_assignee_user_id uuid DEFAULT NULL::uuid, p_comment text DEFAULT ''::text) RETURNS public.workflow_subjects
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.advance_project_workflow_v2(
    p_subject_type, p_subject_id,
    case when p_next_assignee_user_id is null then '{}'::uuid[] else array[p_next_assignee_user_id] end,
    p_comment
  );
$$;


--
-- Name: advance_project_workflow_v2(text, text, uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advance_project_workflow_v2(p_subject_type text, p_subject_id text, p_next_assignee_user_ids uuid[] DEFAULT '{}'::uuid[], p_comment text DEFAULT ''::text) RETURNS public.workflow_subjects
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_request public.requests%rowtype;
  v_subject public.workflow_subjects%rowtype;
  v_next_node public.workflow_instance_nodes%rowtype;
  v_result public.workflow_subjects%rowtype;
  v_recipient_action text;
  v_previous_context text := current_setting('app.material_request_workflow_context', true);
begin
  select * into v_request from public.requests where id = p_subject_id;
  select * into v_subject from public.workflow_subjects
    where subject_type = p_subject_type and subject_id = p_subject_id;
  if v_request.id is null or v_subject.id is null then raise exception 'workflow subject not found'; end if;
  if not public.is_admin() and not app_private.project_workflow_actor_can_act(v_subject.id, v_actor) then
    raise exception 'user is not assigned to current workflow step' using errcode = '42501';
  end if;
  if not app_private.project_actor_has_effective_room_action(
    v_actor, v_request.project_id, v_request.construction_site_id, 'material_request', 'approve'
  ) then raise exception 'Room approve permission required' using errcode = '42501'; end if;
  select target.* into v_next_node
  from public.workflow_instance_edges edge
  join public.workflow_instance_nodes target on target.id = edge.target_instance_node_id
  where edge.workflow_instance_id = v_subject.workflow_instance_id
    and edge.source_instance_node_id = v_subject.current_instance_node_id
  order by edge.sort_order, target.position_y, target.position_x limit 1;
  v_recipient_action := case when v_next_node.type = 'END'::public.workflow_node_type
    then 'confirm' else 'approve' end;
  perform app_private.assert_material_request_room_recipients(
    p_subject_id, p_next_assignee_user_ids, v_recipient_action
  );
  perform set_config('app.material_request_workflow_context', 'on', true);
  v_result := public.advance_project_workflow_v2_room_authoritative_legacy(
    p_subject_type, p_subject_id, p_next_assignee_user_ids, p_comment
  );
  perform set_config('app.material_request_workflow_context', coalesce(v_previous_context, ''), true);
  return v_result;
exception when others then
  perform set_config('app.material_request_workflow_context', coalesce(v_previous_context, ''), true);
  raise;
end;
$$;


--
-- Name: advance_project_workflow_v2_room_authoritative_legacy(text, text, uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advance_project_workflow_v2_room_authoritative_legacy(p_subject_type text, p_subject_id text, p_next_assignee_user_ids uuid[] DEFAULT '{}'::uuid[], p_comment text DEFAULT ''::text) RETURNS public.workflow_subjects
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_subject public.workflow_subjects%rowtype;
  v_request public.requests%rowtype;
  v_current_node public.workflow_instance_nodes%rowtype;
  v_next_node public.workflow_instance_nodes%rowtype;
  v_next_assignee_ids uuid[] := app_private.project_workflow_distinct_uuid_array(p_next_assignee_user_ids);
  v_handoff_assignee uuid;
  v_first_next_assignee uuid;
  v_next_assignee_name text;
  v_sla_hours integer;
  v_due_at timestamptz;
  v_to_step text;
begin
  if v_actor is null then raise exception 'authentication required'; end if;
  if p_subject_type <> 'material_request' then
    raise exception 'unsupported project workflow subject type: %', p_subject_type;
  end if;

  select * into v_subject
  from public.workflow_subjects ws
  where ws.subject_type = p_subject_type and ws.subject_id = p_subject_id
  for update;
  if not found then raise exception 'workflow subject not found'; end if;

  select * into v_request from public.requests r where r.id = p_subject_id for update;
  if not found then raise exception 'material request not found: %', p_subject_id; end if;
  if v_subject.status <> 'RUNNING' then raise exception 'workflow subject is not running'; end if;
  if not app_private.project_workflow_actor_can_act(v_subject.id, v_actor) then
    raise exception 'user is not assigned to current workflow step';
  end if;

  select * into v_current_node
  from public.workflow_instance_nodes win
  where win.id = v_subject.current_instance_node_id
    and win.workflow_instance_id = v_subject.workflow_instance_id;
  if not found then raise exception 'current runtime workflow node not found'; end if;

  select target_node.* into v_next_node
  from public.workflow_instance_edges wie
  join public.workflow_instance_nodes target_node on target_node.id = wie.target_instance_node_id
  where wie.workflow_instance_id = v_subject.workflow_instance_id
    and wie.source_instance_node_id = v_subject.current_instance_node_id
  order by wie.sort_order, target_node.position_y, target_node.position_x
  limit 1;
  if not found then raise exception 'next runtime workflow node not found'; end if;

  if v_next_node.type = 'END'::public.workflow_node_type then
    if coalesce(array_length(v_next_assignee_ids, 1), 0) <> 1 then
      raise exception 'exactly one batch planning assignee is required';
    end if;
    foreach v_handoff_assignee in array v_next_assignee_ids loop
      if not app_private.project_material_request_handoff_assignee_is_eligible(
        p_subject_id,
        v_handoff_assignee
      ) then
        raise exception 'batch planning assignee must be active project staff with approve permission';
      end if;
    end loop;
  elsif not app_private.project_workflow_runtime_assignees_are_eligible(
    p_subject_type, p_subject_id, v_next_node.id, v_next_assignee_ids
  ) then
    raise exception 'next assignee pool is not eligible for this runtime workflow step';
  end if;

  update public.workflow_step_assignments
  set status = 'APPROVED', acted_at = now(),
      action_comment = nullif(coalesce(p_comment, ''), ''),
      metadata = coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object('approvedByUserId', v_actor, 'approvalPolicy', 'ANY_ONE')
  where workflow_subject_id = v_subject.id
    and workflow_instance_id = v_subject.workflow_instance_id
    and instance_node_id = v_subject.current_instance_node_id
    and assignee_user_id = v_actor
    and status = 'PENDING';

  update public.workflow_step_assignments
  set status = 'SKIPPED', acted_at = now(),
      action_comment = 'Skipped because another assignee approved this step',
      metadata = coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object('skippedByPolicy', 'ANY_ONE', 'approvedByUserId', v_actor)
  where workflow_subject_id = v_subject.id
    and workflow_instance_id = v_subject.workflow_instance_id
    and instance_node_id = v_subject.current_instance_node_id
    and status = 'PENDING';

  insert into public.workflow_instance_logs(instance_id, node_id, action, acted_by, comment)
  values (v_subject.workflow_instance_id, v_current_node.template_node_id,
    'APPROVED'::public.workflow_instance_action, v_actor, coalesce(p_comment, ''));

  if v_next_node.type = 'END'::public.workflow_node_type then
    v_first_next_assignee := v_next_assignee_ids[1];
    v_next_assignee_name := app_private.project_workflow_first_assignee_name(v_next_assignee_ids);
    v_sla_hours := 48;
    v_due_at := now() + make_interval(hours => v_sla_hours);

    update public.workflow_instances
    set current_node_id = v_next_node.template_node_id,
        current_instance_node_id = v_next_node.id,
        status = 'COMPLETED'::public.workflow_instance_status,
        updated_at = now()
    where id = v_subject.workflow_instance_id;

    update public.workflow_subjects
    set current_assignee_user_id = null,
        current_assignee_user_ids = '{}'::uuid[],
        current_node_id = v_next_node.template_node_id,
        current_instance_node_id = v_next_node.id,
        last_action_instance_node_id = v_current_node.id,
        status = 'COMPLETED',
        updated_at = now()
    where id = v_subject.id
    returning * into v_subject;

    update public.requests
    set status = 'APPROVED'::public.request_status,
        submitted_to_user_id = v_first_next_assignee::text,
        submitted_to_name = v_next_assignee_name,
        submitted_to_permission = 'approve',
        submission_note = nullif(coalesce(p_comment, ''), ''),
        last_action_by = v_actor, last_action_at = now(),
        workflow_step = 'batch_planning', workflow_step_started_at = now(),
        workflow_step_due_at = v_due_at, workflow_step_sla_hours = v_sla_hours,
        workflow_step_actor_user_id = v_actor::text
    where id = p_subject_id;

    insert into public.material_request_events(
      request_id, project_id, from_step, to_step, action, actor_user_id,
      target_user_id, target_permission, note, sla_hours, due_at, metadata
    )
    values (
      p_subject_id, v_request.project_id, coalesce(v_request.workflow_step, 'material_department_review'),
      'batch_planning', 'APPROVED', v_actor::text,
      v_first_next_assignee::text, 'approve', nullif(coalesce(p_comment, ''), ''),
      v_sla_hours, v_due_at,
      jsonb_build_object(
        'workflowInstanceId', v_subject.workflow_instance_id,
        'workflowSubjectId', v_subject.id,
        'fromInstanceNodeId', v_current_node.id,
        'toInstanceNodeId', v_next_node.id,
        'handoffAssigneeUserId', v_first_next_assignee
      )
    );
    return v_subject;
  end if;

  perform app_private.project_workflow_insert_assignment_pool(
    v_subject.id, v_subject.workflow_instance_id, v_next_node.template_node_id, v_next_node.id,
    v_next_assignee_ids, v_actor, p_comment,
    jsonb_build_object('approvedFromInstanceNodeId', v_current_node.id, 'approvalPolicy', 'ANY_ONE'),
    'transition'
  );

  v_first_next_assignee := v_next_assignee_ids[1];
  v_next_assignee_name := app_private.project_workflow_first_assignee_name(v_next_assignee_ids);
  v_sla_hours := app_private.project_workflow_runtime_sla_hours(v_next_node.id);
  v_due_at := app_private.project_workflow_runtime_sla_due_at(v_next_node.id);
  v_to_step := app_private.project_workflow_runtime_to_coarse_step(v_subject.workflow_instance_id, v_next_node.id);

  update public.workflow_instances
  set current_node_id = v_next_node.template_node_id,
      current_instance_node_id = v_next_node.id,
      step_assignees = coalesce(step_assignees, '{}'::jsonb)
        || app_private.project_workflow_step_assignees_json(v_next_node.template_node_id, v_next_assignee_ids),
      updated_at = now()
  where id = v_subject.workflow_instance_id;

  update public.workflow_subjects
  set current_assignee_user_id = v_first_next_assignee,
      current_assignee_user_ids = v_next_assignee_ids,
      current_node_id = v_next_node.template_node_id,
      current_instance_node_id = v_next_node.id,
      last_action_instance_node_id = v_current_node.id,
      status = 'RUNNING', updated_at = now()
  where id = v_subject.id
  returning * into v_subject;

  update public.requests
  set status = 'PENDING'::public.request_status,
      submitted_to_user_id = v_first_next_assignee::text,
      submitted_to_name = v_next_assignee_name,
      submitted_to_permission = app_private.project_workflow_runtime_primary_permission(v_next_node.id),
      submission_note = nullif(coalesce(p_comment, ''), ''),
      last_action_by = v_actor, last_action_at = now(),
      workflow_step = v_to_step, workflow_step_started_at = now(),
      workflow_step_due_at = v_due_at, workflow_step_sla_hours = v_sla_hours,
      workflow_step_actor_user_id = v_actor::text
  where id = p_subject_id;

  insert into public.material_request_events(
    request_id, project_id, from_step, to_step, action, actor_user_id,
    target_user_id, target_permission, note, sla_hours, due_at, metadata
  )
  values (
    p_subject_id, v_request.project_id, coalesce(v_request.workflow_step, 'material_department_review'),
    v_to_step, 'APPROVED', v_actor::text, v_first_next_assignee::text,
    app_private.project_workflow_runtime_primary_permission(v_next_node.id),
    nullif(coalesce(p_comment, ''), ''), v_sla_hours, v_due_at,
    jsonb_build_object(
      'workflowInstanceId', v_subject.workflow_instance_id,
      'workflowSubjectId', v_subject.id,
      'fromInstanceNodeId', v_current_node.id,
      'toInstanceNodeId', v_next_node.id,
      'assigneeUserIds', v_next_assignee_ids
    )
  );
  return v_subject;
end;
$$;


--
-- Name: ai_database_catalog(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_database_catalog() RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'table', table_name,
        'columns', columns
      )
      order by table_name
    ),
    '[]'::jsonb
  )
  from (
    select
      c.table_name,
      jsonb_agg(
        jsonb_build_object(
          'name', c.column_name,
          'type', c.data_type,
          'nullable', c.is_nullable = 'YES'
        )
        order by c.ordinal_position
      ) as columns
    from information_schema.columns c
    where c.table_schema = 'public'
      and c.table_name not like 'pg_%'
      and c.table_name not in ('app_code_counters')
    group by c.table_name
  ) s;
$$;


--
-- Name: ai_search_knowledge(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_search_knowledge(p_query text, p_limit integer DEFAULT 8) RETURNS TABLE(document_id text, title text, file_name text, content text, rank real)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $_$
declare
  v_content_column text;
  v_limit integer := least(greatest(coalesce(p_limit, 8), 1), 20);
begin
  if to_regclass('public.rag_chunks') is null or to_regclass('public.rag_documents') is null then
    return;
  end if;

  select column_name
    into v_content_column
  from information_schema.columns
  where table_schema = 'public'
    and table_name = 'rag_chunks'
    and column_name in ('content', 'chunk_text', 'text')
  order by case column_name when 'content' then 1 when 'chunk_text' then 2 else 3 end
  limit 1;

  if v_content_column is null then
    return;
  end if;

  return query execute format(
    'select
       c.document_id::text,
       d.title::text,
       d.file_name::text,
       left(c.%1$I::text, 1800) as content,
       ts_rank_cd(to_tsvector(''simple'', coalesce(c.%1$I::text, '''')), plainto_tsquery(''simple'', $1))::real as rank
     from public.rag_chunks c
     join public.rag_documents d on d.id = c.document_id
     where coalesce(d.status, ''ready'') = ''ready''
       and to_tsvector(''simple'', coalesce(c.%1$I::text, '''')) @@ plainto_tsquery(''simple'', $1)
     order by rank desc
     limit $2',
    v_content_column
  )
  using p_query, v_limit;
end;
$_$;


--
-- Name: ai_tool_attendance_report(date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_tool_attendance_report(p_date date DEFAULT CURRENT_DATE, p_site_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_result jsonb;
begin
  select jsonb_build_object(
    'date', p_date, 'total_records', count(*),
    'checked_in', count(*) filter (where a."checkIn" is not null and a."checkIn" != ''),
    'checked_out', count(*) filter (where a."checkOut" is not null and a."checkOut" != ''),
    'absent', count(*) filter (where a.status = 'absent'),
    'late', count(*) filter (where a.status = 'late'),
    'on_time', count(*) filter (where a.status = 'on_time' or a.status = 'present'),
    'site_filter', coalesce(p_site_id, 'all'),
    'records', coalesce(jsonb_agg(jsonb_build_object(
      'employee_name', coalesce((select emp.full_name from employees emp where emp.id = a."employeeId" limit 1), a."employeeId"::text),
      'check_in', a."checkIn", 'check_out', a."checkOut", 'status', a.status
    ) order by a."checkIn" asc nulls last) filter (where a.id is not null), '[]'::jsonb)
  ) into v_result
  from (select * from hrm_attendance where date = p_date::text and (p_site_id is null or "constructionSiteId" = p_site_id) limit 50) a;
  return v_result;
end; $$;


--
-- Name: ai_tool_cost_template_summary(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_tool_cost_template_summary(p_project_type text DEFAULT NULL::text, p_keyword text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  v_kw text := '%' || lower(trim(coalesce(p_keyword, ''))) || '%';
  v_result jsonb;
begin
  with filtered as (
    select t.*
    from public.cost_templates t
    where t.status <> 'archived'
      and (p_project_type is null or lower(coalesce(t.project_type, '')) = lower(p_project_type))
      and (
        p_keyword is null
        or lower(t.code) like v_kw
        or lower(t.name) like v_kw
        or lower(coalesce(t.description, '')) like v_kw
      )
    order by case when t.status = 'active' then 0 else 1 end, t.effective_from desc, t.name
    limit 20
  )
  select jsonb_build_object(
    'total', count(*),
    'project_type_filter', p_project_type,
    'keyword', p_keyword,
    'templates', coalesce(jsonb_agg(
      jsonb_build_object(
        'id', f.id,
        'code', f.code,
        'name', f.name,
        'project_type', f.project_type,
        'status', f.status,
        'version_no', f.version_no,
        'effective_from', f.effective_from,
        'effective_to', f.effective_to,
        'assumptions', f.assumptions,
        'parameters', (
          select coalesce(jsonb_agg(jsonb_build_object(
            'code', p.code,
            'label', p.label,
            'data_type', p.data_type,
            'unit', p.unit,
            'is_required', p.is_required,
            'default_value', p.default_value,
            'options', p.options,
            'validation_rules', p.validation_rules
          ) order by p.sort_order), '[]'::jsonb)
          from public.cost_template_parameters p
          where p.template_id = f.id
        ),
        'sections', (
          select coalesce(jsonb_agg(jsonb_build_object(
            'code', s.code,
            'name', s.name,
            'sort_order', s.sort_order
          ) order by s.sort_order), '[]'::jsonb)
          from public.cost_template_sections s
          where s.template_id = f.id
        ),
        'sample_items', (
          select coalesce(jsonb_agg(jsonb_build_object(
            'code', i.code,
            'name', i.name,
            'item_type', i.item_type,
            'unit', i.unit,
            'quantity_formula', i.quantity_formula,
            'work_code', i.work_code,
            'norm_group_code', i.norm_group_code
          ) order by i.sort_order), '[]'::jsonb)
          from (
            select *
            from public.cost_template_items i
            where i.template_id = f.id
            order by i.sort_order
            limit 30
          ) i
        )
      )
    ), '[]'::jsonb)
  )
  into v_result
  from filtered f;

  return v_result;
end;
$$;


--
-- Name: ai_tool_daily_log_summary(text, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_tool_daily_log_summary(p_project_id text, p_from_date date DEFAULT NULL::date, p_to_date date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_result jsonb;
  v_total bigint;
  v_breakdown jsonb;
  v_recent jsonb;
begin
  select count(*) into v_total from daily_logs dl
  where dl.construction_site_id = p_project_id
    and (p_from_date is null or dl.log_date::date >= p_from_date)
    and (p_to_date is null or dl.log_date::date <= p_to_date);

  select coalesce(jsonb_object_agg(status, cnt), '{}'::jsonb) into v_breakdown
  from (
    select dl.status, count(*) as cnt from daily_logs dl
    where dl.construction_site_id = p_project_id
      and (p_from_date is null or dl.log_date::date >= p_from_date)
      and (p_to_date is null or dl.log_date::date <= p_to_date)
    group by dl.status
  ) sb;

  select coalesce(jsonb_agg(
    jsonb_build_object('id', dl2.id, 'log_date', dl2.log_date, 'status', dl2.status, 'weather', dl2.weather, 'created_at', dl2.created_at)
    order by dl2.log_date desc
  ), '[]'::jsonb) into v_recent
  from daily_logs dl2
  where dl2.construction_site_id = p_project_id
    and (p_from_date is null or dl2.log_date::date >= p_from_date)
    and (p_to_date is null or dl2.log_date::date <= p_to_date)
  limit 10;

  return jsonb_build_object('project_id', p_project_id, 'total_logs', v_total, 'status_breakdown', v_breakdown, 'recent_logs', v_recent);
end;
$$;


--
-- Name: ai_tool_employee_search(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_tool_employee_search(p_keyword text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_result jsonb;
  v_kw text := '%' || lower(trim(coalesce(p_keyword, ''))) || '%';
  v_kw_unaccent text := '%' || lower(unaccent(trim(coalesce(p_keyword, '')))) || '%';
begin
  select jsonb_build_object(
    'keyword', trim(coalesce(p_keyword, '')),
    'total_found', count(*),
    'employees', coalesce(jsonb_agg(
      jsonb_build_object(
        'id', e.id,
        'employee_code', e.employee_code,
        'full_name', e.full_name,
        'title', e.title,
        'gender', e.gender,
        'phone', e.phone,
        'email', e.email,
        'date_of_birth', e.date_of_birth,
        'start_date', e.start_date,
        'official_date', e.official_date,
        'status', coalesce(e.status, 'active'),
        'marital_status', e.marital_status,
        'avatar_url', e.avatar_url,
        'department_name', ou.name,
        'position_name', hp.name,
        'site_name', hcs.name
      )
      order by e.full_name
    ), '[]'::jsonb)
  )
  into v_result
  from (
    select emp.*
    from employees emp
    where lower(emp.full_name) like v_kw
       or lower(unaccent(coalesce(emp.full_name, ''))) like v_kw_unaccent
       or lower(emp.employee_code) like v_kw
    limit 20
  ) e
  left join org_units ou on ou.id = e.org_unit_id
  left join hrm_positions hp on hp.id = e.position_id
  left join hrm_construction_sites hcs on hcs.id = e.construction_site_id;

  return v_result;
end;
$$;


--
-- Name: ai_tool_employee_summary(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_tool_employee_summary(p_department_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_result jsonb;
begin
  select jsonb_build_object(
    'total_employees', count(*),
    'active', count(*) filter (where e.status = 'active' or e.status is null),
    'inactive', count(*) filter (where e.status = 'inactive'),
    'resigned', count(*) filter (where e.status = 'resigned'),
    'by_department', (select coalesce(jsonb_agg(jsonb_build_object('department', coalesce(ou.name, 'Chua phan phong'), 'count', d.cnt) order by d.cnt desc), '[]'::jsonb) from (select e2.org_unit_id, count(*) as cnt from employees e2 where (p_department_id is null or e2.org_unit_id::text = p_department_id) group by e2.org_unit_id) d left join org_units ou on ou.id = d.org_unit_id),
    'recent_employees', coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'employee_code', e.employee_code, 'full_name', e.full_name, 'status', coalesce(e.status, 'active'), 'org_unit_id', e.org_unit_id) order by e.created_at desc nulls last) filter (where e.id is not null), '[]'::jsonb)
  ) into v_result from (select * from employees where (p_department_id is null or org_unit_id::text = p_department_id) limit 50) e;
  return v_result;
end; $$;


--
-- Name: ai_tool_estimate_module_blueprint(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_tool_estimate_module_blueprint() RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
begin
  return jsonb_build_object(
    'module', 'Đơn giá nội bộ & AI dự toán nhanh',
    'business_architecture', jsonb_build_array(
      'Chuẩn hóa metadata loại công trình/hạng mục để tái sử dụng cho chào thầu nhà xưởng.',
      'Dự toán được sinh từ template + định mức nội bộ + đơn giá nội bộ, luôn ở trạng thái draft trước khi người dùng review.',
      'Khi chốt có thể export báo giá; khi trúng thầu có thể chuyển estimate thành Contract BOQ / Work BOQ / Material Plan.'
    ),
    'data_model', jsonb_build_object(
      'templates', jsonb_build_array('cost_templates', 'cost_template_sections', 'cost_template_items', 'cost_template_parameters'),
      'pricing_and_norms', jsonb_build_array('internal_price_book', 'internal_norms'),
      'estimates', jsonb_build_array('estimate_scenarios', 'estimate_items', 'estimate_adjustments', 'estimate_versions')
    ),
    'versioning', jsonb_build_array(
      'Template, định mức và đơn giá đều có version_no, effective_from, effective_to, status.',
      'Không sửa đè dữ liệu đã dùng để chốt; tạo version mới khi thay đổi giá/định mức/template.',
      'Estimate lưu template_snapshot, price_book_snapshot, norms_snapshot và calculation_snapshot.'
    ),
    'supported_parameters', jsonb_build_array(
      'floor_area', 'height', 'span', 'foundation_type', 'roof_type',
