$$;


--
-- Name: ai_tool_estimate_scenario_summary(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_tool_estimate_scenario_summary(p_project_id text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_keyword text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  v_kw text := '%' || lower(trim(coalesce(p_keyword, ''))) || '%';
  v_result jsonb;
begin
  with filtered as (
    select es.*
    from public.estimate_scenarios es
    where (p_project_id is null or es.project_id = p_project_id or es.construction_site_id = p_project_id)
      and (p_status is null or es.status = p_status)
      and (
        p_keyword is null
        or lower(coalesce(es.code, '')) like v_kw
        or lower(es.name) like v_kw
        or lower(coalesce(es.customer_name, '')) like v_kw
        or lower(coalesce(es.project_type, '')) like v_kw
      )
    order by es.created_at desc
    limit 30
  )
  select jsonb_build_object(
    'total', count(*),
    'filters', jsonb_build_object(
      'project_id', p_project_id,
      'status', p_status,
      'keyword', p_keyword
    ),
    'summary', jsonb_build_object(
      'draft', count(*) filter (where status = 'draft'),
      'reviewed', count(*) filter (where status = 'reviewed'),
      'finalized', count(*) filter (where status = 'finalized'),
      'converted', count(*) filter (where status = 'converted'),
      'total_quote_amount', coalesce(sum(quote_amount), 0)
    ),
    'scenarios', coalesce(jsonb_agg(
      jsonb_build_object(
        'id', f.id,
        'code', f.code,
        'name', f.name,
        'project_id', f.project_id,
        'construction_site_id', f.construction_site_id,
        'customer_name', f.customer_name,
        'project_type', f.project_type,
        'status', f.status,
        'template_id', f.template_id,
        'template_version_no', f.template_version_no,
        'missing_parameters', f.missing_parameters,
        'assumptions', f.assumptions,
        'risk_warnings', f.risk_warnings,
        'confidence_score', f.confidence_score,
        'quote_amount', f.quote_amount,
        'currency', f.currency,
        'converted_project_id', f.converted_project_id,
        'converted_contract_id', f.converted_contract_id,
        'created_at', f.created_at,
        'updated_at', f.updated_at,
        'item_count', (
          select count(*)
          from public.estimate_items ei
          where ei.estimate_id = f.id
        )
      )
      order by f.created_at desc
    ), '[]'::jsonb)
  )
  into v_result
  from filtered f;

  return v_result;
end;
$$;


--
-- Name: ai_tool_executive_dashboard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_tool_executive_dashboard() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_inv jsonb; v_proj jsonb; v_hr jsonb; v_mr jsonb; v_po jsonb; v_fin jsonb;
begin
  select jsonb_build_object('total_items', count(*), 'total_stock', coalesce(sum((select sum(val.value::numeric) from jsonb_each_text(coalesce(i.stock_by_warehouse, '{}'::jsonb)) as val)), 0), 'low_stock_count', count(*) filter (where (select sum(val.value::numeric) from jsonb_each_text(coalesce(i.stock_by_warehouse, '{}'::jsonb)) val) < coalesce(i.min_stock, 0) and coalesce(i.min_stock, 0) > 0))
  into v_inv from items i;

  select jsonb_build_object('total_projects', count(*))
  into v_proj from hrm_construction_sites;

  select jsonb_build_object('total_employees', count(*), 'active_employees', count(*) filter (where e.status = 'active' or e.status is null or e.status = E'\u0110ang l\u00e0m vi\u1ec7c'))
  into v_hr from employees e;

  select jsonb_build_object('total_mr', count(*), 'pending_mr', count(*) filter (where mr.status in ('pending', 'submitted', 'draft')))
  into v_mr from project_material_requests mr;

  select jsonb_build_object('total_po', count(*), 'pending_po', count(*) filter (where po.status in ('pending', 'submitted', 'draft')), 'total_po_value', coalesce(sum(po.total_amount), 0))
  into v_po from purchase_orders po;

  select jsonb_build_object('income_this_month', coalesce(sum(case when pt.type = 'income' then pt.amount else 0 end), 0), 'expense_this_month', coalesce(sum(case when pt.type = 'expense' then pt.amount else 0 end), 0))
  into v_fin from project_transactions pt where pt.date::date >= date_trunc('month', current_date)::date;

  return jsonb_build_object('generated_at', now(), 'inventory', v_inv, 'projects', v_proj, 'employees', v_hr, 'material_requests', v_mr, 'purchase_orders', v_po, 'finance_this_month', v_fin);
end; $$;


--
-- Name: ai_tool_internal_norms_lookup(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_tool_internal_norms_lookup(p_keyword text, p_region text DEFAULT NULL::text, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  v_kw text := '%' || lower(trim(coalesce(p_keyword, ''))) || '%';
  v_limit integer := least(greatest(coalesce(p_limit, 20), 1), 50);
  v_result jsonb;
begin
  select jsonb_build_object(
    'keyword', trim(coalesce(p_keyword, '')),
    'region_filter', p_region,
    'security_note', 'Định mức nội bộ chỉ là căn cứ dự toán draft, cần người có quyền review.',
    'total_found', count(*),
    'norms', coalesce(jsonb_agg(
      jsonb_build_object(
        'id', s.id,
        'norm_code', s.norm_code,
        'work_code', s.work_code,
        'resource_code', s.resource_code,
        'resource_name', s.resource_name,
        'resource_type', s.resource_type,
        'unit', s.unit,
        'norm_quantity', s.norm_quantity,
        'waste_percent', s.waste_percent,
        'formula', s.formula,
        'applicable_parameters', s.applicable_parameters,
        'region', s.region,
        'version_no', s.version_no,
        'effective_from', s.effective_from,
        'effective_to', s.effective_to,
        'confidence_score', s.confidence_score
      )
      order by s.norm_code, s.region, s.effective_from desc
    ), '[]'::jsonb)
  )
  into v_result
  from (
    select *
    from public.internal_norms n
    where n.status = 'active'
      and (n.effective_from <= current_date)
      and (n.effective_to is null or n.effective_to >= current_date)
      and (p_region is null or lower(n.region) in ('all', lower(p_region)))
      and (
        lower(n.norm_code) like v_kw
        or lower(coalesce(n.work_code, '')) like v_kw
        or lower(coalesce(n.resource_code, '')) like v_kw
        or lower(n.resource_name) like v_kw
      )
    order by n.norm_code, n.region, n.effective_from desc
    limit v_limit
  ) s;

  return v_result;
end;
$$;


--
-- Name: ai_tool_internal_price_book_lookup(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_tool_internal_price_book_lookup(p_keyword text, p_region text DEFAULT NULL::text, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  v_kw text := '%' || lower(trim(coalesce(p_keyword, ''))) || '%';
  v_limit integer := least(greatest(coalesce(p_limit, 20), 1), 50);
  v_result jsonb;
begin
  select jsonb_build_object(
    'keyword', trim(coalesce(p_keyword, '')),
    'region_filter', p_region,
    'security_note', 'Đơn giá nội bộ là dữ liệu nhạy cảm; chỉ trả qua Edge Function sau khi xác nhận quyền.',
    'total_found', count(*),
    'prices', coalesce(jsonb_agg(
      jsonb_build_object(
        'id', s.id,
        'item_code', s.item_code,
        'item_name', s.item_name,
        'item_type', s.item_type,
        'category', s.category,
        'spec', s.spec,
        'unit', s.unit,
        'region', s.region,
        'brand', s.brand,
        'currency', s.currency,
        'unit_price', s.unit_price,
        'version_no', s.version_no,
        'effective_from', s.effective_from,
        'effective_to', s.effective_to,
        'status', s.status,
        'sensitivity_level', s.sensitivity_level
      )
      order by s.item_name, s.region, s.effective_from desc
    ), '[]'::jsonb)
  )
  into v_result
  from (
    select *
    from public.internal_price_book ipb
    where ipb.status = 'active'
      and (ipb.effective_from <= current_date)
      and (ipb.effective_to is null or ipb.effective_to >= current_date)
      and (p_region is null or lower(ipb.region) in ('all', lower(p_region)))
      and (
        lower(ipb.item_code) like v_kw
        or lower(ipb.item_name) like v_kw
        or lower(coalesce(ipb.category, '')) like v_kw
        or lower(coalesce(ipb.spec, '')) like v_kw
      )
    order by ipb.item_name, ipb.region, ipb.effective_from desc
    limit v_limit
  ) s;

  return v_result;
end;
$$;


--
-- Name: ai_tool_inventory_summary(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_tool_inventory_summary(p_warehouse_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_result jsonb;
begin
  with item_stocks as (
    select i.id, i.min_stock, i.price_in,
      case when p_warehouse_id is not null then coalesce((i.stock_by_warehouse ->> p_warehouse_id)::numeric, 0)
      else coalesce((select sum(val.value::numeric) from jsonb_each_text(coalesce(i.stock_by_warehouse, '{}'::jsonb)) as val), 0)
      end as total_stock
    from items i
  )
  select jsonb_build_object(
    'total_items', count(*),
    'total_stock', coalesce(sum(total_stock), 0),
    'low_stock_items', count(*) filter (where total_stock < coalesce(min_stock, 0) and coalesce(min_stock, 0) > 0),
    'total_value', round(coalesce(sum(coalesce(price_in, 0) * total_stock), 0), 0),
    'warehouse_filter', coalesce(p_warehouse_id, 'all'),
    'warehouses', (select coalesce(jsonb_agg(jsonb_build_object('id', w.id, 'name', w.name) order by w.name), '[]'::jsonb) from warehouses w)
  )
  into v_result from item_stocks;
  return v_result;
end;
$$;


--
-- Name: ai_tool_material_request_status(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_tool_material_request_status(p_project_id text DEFAULT NULL::text, p_status text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_total bigint;
  v_breakdown jsonb;
  v_recent jsonb;
begin
  select count(*) into v_total from project_material_requests mr
  where (p_project_id is null or mr.construction_site_id = p_project_id)
    and (p_status is null or mr.status = p_status);

  select coalesce(jsonb_object_agg(status, cnt), '{}'::jsonb) into v_breakdown
  from (select mr.status, count(*) as cnt from project_material_requests mr
    where (p_project_id is null or mr.construction_site_id = p_project_id)
      and (p_status is null or mr.status = p_status)
    group by mr.status) sb;

  select coalesce(jsonb_agg(
    jsonb_build_object('id', mr2.id, 'code', mr2.code, 'status', mr2.status,
      'requester', coalesce((select u.name from users u where u.id = mr2.created_by::text limit 1), mr2.created_by::text),
      'created_at', mr2.created_at, 'item_count', coalesce(jsonb_array_length(mr2.items), 0))
    order by mr2.created_at desc
  ), '[]'::jsonb) into v_recent
  from (select * from project_material_requests mr2
    where (p_project_id is null or mr2.construction_site_id = p_project_id)
      and (p_status is null or mr2.status = p_status)
    order by mr2.created_at desc limit 20) mr2;

  return jsonb_build_object('total', v_total, 'status_breakdown', v_breakdown, 'recent_requests', v_recent);
end;
$$;


--
-- Name: ai_tool_material_search(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_tool_material_search(p_keyword text, p_warehouse_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_result jsonb;
  v_kw text := '%' || lower(trim(coalesce(p_keyword, ''))) || '%';
begin
  select jsonb_build_object(
    'keyword', trim(coalesce(p_keyword, '')),
    'total_found', count(*),
    'items', coalesce(jsonb_agg(
      jsonb_build_object('id', s.id, 'sku', s.sku, 'name', s.name, 'category', s.category, 'unit', s.unit, 'price_in', s.price_in, 'price_out', s.price_out, 'total_stock', s.total_stock, 'min_stock', s.min_stock, 'supplier_id', s.supplier_id)
      order by s.name
    ), '[]'::jsonb)
  )
  into v_result
  from (
    select i.id, i.sku, i.name, i.category, i.unit, i.price_in, i.price_out, i.min_stock, i.supplier_id,
      case when p_warehouse_id is not null then coalesce((i.stock_by_warehouse ->> p_warehouse_id)::numeric, 0)
      else coalesce((select sum(val.value::numeric) from jsonb_each_text(coalesce(i.stock_by_warehouse, '{}'::jsonb)) as val), 0)
      end as total_stock
    from items i
    where lower(coalesce(i.name, '')) like v_kw or lower(coalesce(i.sku, '')) like v_kw
    limit 30
  ) s;
  return v_result;
end;
$$;


--
-- Name: ai_tool_project_finance(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_tool_project_finance(p_project_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_result jsonb;
begin
  select jsonb_build_object(
    'project_id', p_project_id,
    'project_name', coalesce((select h.name from hrm_construction_sites h where h.id = p_project_id limit 1), 'N/A'),
    'budget', jsonb_build_object('contract_value', coalesce(pf."contractValue", 0), 'budget_materials', coalesce(pf."budgetMaterials", 0), 'budget_labor', coalesce(pf."budgetLabor", 0), 'revenue_received', coalesce(pf."revenueReceived", 0), 'progress_percent', coalesce(pf."progressPercent", 0)),
    'transactions_summary', (select jsonb_build_object('total_income', coalesce(sum(case when pt.type = 'income' then pt.amount else 0 end), 0), 'total_expense', coalesce(sum(case when pt.type = 'expense' then pt.amount else 0 end), 0), 'net', coalesce(sum(case when pt.type = 'income' then pt.amount else 0 end) - sum(case when pt.type = 'expense' then pt.amount else 0 end), 0), 'transaction_count', count(*)) from project_transactions pt where pt."constructionSiteId" = p_project_id)
  ) into v_result from project_finances pf where pf."constructionSiteId" = p_project_id limit 1;
  if v_result is null then return jsonb_build_object('project_id', p_project_id, 'error', 'Chua co du lieu tai chinh cho du an nay.'); end if;
  return v_result;
end; $$;


--
-- Name: ai_tool_project_list(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_tool_project_list(p_status text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_result jsonb;
begin
  select jsonb_build_object(
    'total', count(*),
    'projects', coalesce(jsonb_agg(
      jsonb_build_object('id', s.id, 'name', s.name, 'address', s.address)
      order by s.created_at desc
    ) filter (where s.id is not null), '[]'::jsonb)
  )
  into v_result
  from (select h.id, h.name, h.address, h.created_at from hrm_construction_sites h limit 50) s;
  return v_result;
end; $$;


--
-- Name: ai_tool_project_progress(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_tool_project_progress(p_project_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_result jsonb;
begin
  select jsonb_build_object(
    'project_id', p_project_id,
    'total_tasks', count(*),
    'avg_progress', round(coalesce(avg(t.progress), 0), 1),
    'completed', count(*) filter (where t.progress >= 100),
    'in_progress', count(*) filter (where t.progress > 0 and t.progress < 100),
    'not_started', count(*) filter (where t.progress = 0 or t.progress is null),
    'tasks', coalesce(jsonb_agg(
      jsonb_build_object('id', t.id, 'name', t.name, 'progress', coalesce(t.progress, 0), 'gate_status', t.gate_status, 'start_date', t.start_date, 'end_date', t.end_date, 'parent_id', t.parent_id)
      order by t.start_date asc nulls last
    ) filter (where t.id is not null), '[]'::jsonb)
  )
  into v_result
  from project_tasks t where t.construction_site_id = p_project_id;
  return v_result;
end;
$$;


--
-- Name: ai_tool_project_summary(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_tool_project_summary(p_project_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_site jsonb; v_finance jsonb; v_task_summary jsonb;
begin
  select jsonb_build_object('id', h.id, 'name', h.name, 'address', h.address)
  into v_site from hrm_construction_sites h where h.id = p_project_id;
  if v_site is null then return jsonb_build_object('error', 'Khong tim thay du an voi ID: ' || coalesce(p_project_id, 'null')); end if;
  select jsonb_build_object('contract_value', coalesce(pf."contractValue", 0), 'progress_percent', coalesce(pf."progressPercent", 0), 'budget_materials', coalesce(pf."budgetMaterials", 0), 'budget_labor', coalesce(pf."budgetLabor", 0), 'revenue_received', coalesce(pf."revenueReceived", 0), 'finance_status', coalesce(pf.status, 'N/A'))
  into v_finance from project_finances pf where pf."constructionSiteId" = p_project_id limit 1;
  select jsonb_build_object('total_tasks', count(*), 'completed_tasks', count(*) filter (where pt.progress >= 100), 'in_progress_tasks', count(*) filter (where pt.progress > 0 and pt.progress < 100), 'not_started_tasks', count(*) filter (where pt.progress = 0 or pt.progress is null), 'avg_progress', round(coalesce(avg(pt.progress), 0), 1))
  into v_task_summary from project_tasks pt where pt.construction_site_id = p_project_id;
  return jsonb_build_object('site', v_site, 'finance', coalesce(v_finance, '{}'::jsonb), 'tasks', coalesce(v_task_summary, '{}'::jsonb));
end; $$;


--
-- Name: ai_tool_purchase_order_summary(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_tool_purchase_order_summary(p_project_id text DEFAULT NULL::text, p_status text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_total bigint;
  v_total_val numeric;
  v_breakdown jsonb;
  v_recent jsonb;
begin
  select count(*), coalesce(sum(po.total_amount), 0) into v_total, v_total_val
  from purchase_orders po
  where (p_project_id is null or po.construction_site_id = p_project_id)
    and (p_status is null or po.status = p_status);

  select coalesce(jsonb_object_agg(status, cnt), '{}'::jsonb) into v_breakdown
  from (select po.status, count(*) as cnt from purchase_orders po
    where (p_project_id is null or po.construction_site_id = p_project_id)
      and (p_status is null or po.status = p_status)
    group by po.status) sb;

  select coalesce(jsonb_agg(
    jsonb_build_object('id', po3.id, 'code', po3.code, 'status', po3.status,
      'total_amount', coalesce(po3.total_amount, 0),
      'vendor', coalesce((select pv.name from project_vendors pv where pv.id = po3.vendor_id limit 1), 'N/A'),
      'created_at', po3.created_at)
    order by po3.created_at desc
  ), '[]'::jsonb) into v_recent
  from (select * from purchase_orders po3
    where (p_project_id is null or po3.construction_site_id = p_project_id)
      and (p_status is null or po3.status = p_status)
    order by po3.created_at desc limit 20) po3;

  return jsonb_build_object('total', v_total, 'total_value', v_total_val, 'status_breakdown', v_breakdown, 'recent_orders', v_recent);
end;
$$;


--
-- Name: apply_hrm_import_batch(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_hrm_import_batch(p_batch_id uuid, p_reason text, p_expected_fingerprint text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_batch public.hrm_import_batches%rowtype := app_private.assert_hrm_import_owner(p_batch_id);
  v_row public.hrm_import_staging_rows%rowtype;
  v_employee public.employees%rowtype;
  v_private public.hrm_employee_private_profiles%rowtype;
  v_payload jsonb;
  v_applied integer := 0;
  v_contract_id uuid;
  v_org_unit_id uuid;
  v_position_id uuid;
begin
  perform app_private.assert_hrm_mutation_context(p_reason, 'profile-import');
  if v_batch.status = 'APPLIED' then
    return jsonb_build_object('batchId', p_batch_id, 'status', 'APPLIED', 'appliedRows', v_batch.valid_rows, 'idempotentReplay', true);
  end if;
  if v_batch.status <> 'VALIDATED' or v_batch.error_rows <> 0 then
    raise exception using errcode = '55000', message = 'HRM_IMPORT_VALIDATION_REQUIRED';
  end if;
  if v_batch.fingerprint is distinct from p_expected_fingerprint then
    raise exception using errcode = '40001', message = 'HRM_IMPORT_STALE_FINGERPRINT';
  end if;

  for v_row in
    select * from public.hrm_import_staging_rows
    where batch_id = p_batch_id and validation_status = 'VALID'
    order by sheet_code, row_number for update
  loop
    select employee.* into strict v_employee
    from public.employees employee where employee.employee_code = v_row.employee_code;
    v_payload := v_row.typed_payload;
    case v_row.record_type
      when 'EMPLOYEE_CORE' then
        perform public.update_hrm_employee_core_profile(
          v_employee.id, coalesce(nullif(v_payload ->> 'fullName', ''), v_employee.full_name),
          coalesce(v_payload ->> 'gender', v_employee.gender),
          coalesce(v_payload ->> 'phone', v_employee.phone), coalesce(v_payload ->> 'email', v_employee.email),
          coalesce(nullif(v_payload ->> 'dateOfBirth', '')::date, v_employee.date_of_birth),
          coalesce(nullif(v_payload ->> 'startDate', '')::date, v_employee.start_date),
          coalesce(nullif(v_payload ->> 'officialDate', '')::date, v_employee.official_date),
          coalesce(nullif(v_payload ->> 'status', ''), v_employee.status), v_employee.user_id,
          v_employee.area_id, v_employee.office_id, v_employee.employee_type_id,
          v_employee.work_schedule_id, coalesce(v_payload ->> 'maritalStatus', v_employee.marital_status),
          coalesce(v_payload ->> 'avatarUrl', v_employee.avatar_url), p_reason
        );
      when 'PERSONAL_CONTACT' then
        perform public.update_hrm_employee_personal_contact(
          v_employee.id, v_payload ->> 'personalPhone', v_payload ->> 'personalEmail',
          null, null, null, p_reason
        );
      when 'ADDRESS' then
        select profile.* into v_private from public.hrm_employee_private_profiles profile where profile.employee_id = v_employee.id;
        perform public.update_hrm_employee_personal_contact(
          v_employee.id, v_private.personal_phone, v_private.personal_email,
          v_row.record_code, v_payload ->> 'addressType', v_payload ->> 'addressLine', p_reason
        );
      when 'EMERGENCY_CONTACT' then
        perform public.upsert_hrm_employee_emergency_contact(
          v_employee.id, v_row.record_code, v_payload ->> 'fullName',
          v_payload ->> 'relationshipCode', v_payload ->> 'phone', v_payload ->> 'email',
          v_payload ->> 'address', coalesce((v_payload ->> 'isPrimary')::boolean, false), p_reason
        );
      when 'CONTRACT' then
        select contract.id into v_contract_id
        from public.hrm_labor_contracts contract
        where contract.employee_id = v_employee.id
          and contract.contract_number = coalesce(v_payload ->> 'contractNumber', v_row.record_code)
        order by contract.created_at desc limit 1;
        perform public.upsert_hrm_employee_contract(
          v_contract_id, v_employee.id, coalesce(v_payload ->> 'contractNumber', v_row.record_code),
          v_payload ->> 'type', coalesce(v_payload ->> 'status', 'active'),
          (v_payload ->> 'effectiveFrom')::date, nullif(v_payload ->> 'effectiveTo', '')::date,
          v_payload ->> 'signedBy', v_payload ->> 'note',
          nullif(v_payload ->> 'baseSalary', '')::numeric,
          nullif(v_payload ->> 'allowancePosition', '')::numeric,
          nullif(v_payload ->> 'allowanceOther', '')::numeric, p_reason
        );
      when 'EMPLOYMENT_EVENT' then
        select unit.id into v_org_unit_id from public.org_units unit where unit.code = v_payload ->> 'orgUnitCode';
        select position.id into v_position_id from public.hrm_positions position where position.code = v_payload ->> 'positionCode';
        perform public.upsert_hrm_employee_employment_event(
          v_employee.id, v_row.record_code, v_payload ->> 'eventTypeCode',
          (v_payload ->> 'eventDate')::date, v_org_unit_id, v_position_id, v_payload ->> 'titleSnapshot',
          v_payload ->> 'eventReason', v_payload ->> 'sourceReference', p_reason
        );
      when 'IDENTITY_DOCUMENT' then
        perform public.upsert_hrm_employee_identity_document(
          v_employee.id, v_row.record_code, v_payload ->> 'documentTypeCode',
          v_payload ->> 'documentNumber', nullif(v_payload ->> 'issuedDate', '')::date,
          v_payload ->> 'issuedPlace', nullif(v_payload ->> 'expiryDate', '')::date,
          coalesce((v_payload ->> 'isPrimary')::boolean, false), p_reason
        );
      when 'INSURANCE' then
        perform public.upsert_hrm_employee_insurance_profile(
          v_employee.id, v_payload ->> 'socialInsuranceNumber', v_payload ->> 'healthInsuranceNumber',
          v_payload ->> 'registeredClinicCode', v_payload ->> 'participationStatusCode',
          nullif(v_payload ->> 'effectiveFrom', '')::date, nullif(v_payload ->> 'effectiveTo', '')::date, p_reason
        );
      when 'DEPENDENT' then
        perform public.upsert_hrm_employee_dependent(
          v_employee.id, v_row.record_code, v_payload ->> 'fullName',
          v_payload ->> 'relationshipCode', nullif(v_payload ->> 'dateOfBirth', '')::date,
          v_payload ->> 'taxCode', nullif(v_payload ->> 'deductionFrom', '')::date,
          nullif(v_payload ->> 'deductionTo', '')::date, p_reason
        );
      when 'BANK_ACCOUNT' then
        if not app_private.has_hrm_template_permission(public.current_app_user_id(), 'hrm.compensation.manage') then
          raise exception using errcode = '42501', message = 'HRM_IMPORT_C4_MANAGE_REQUIRED';
        end if;
        perform public.upsert_hrm_employee_bank_account(
          v_employee.id, v_row.record_code, v_payload ->> 'bankCode', v_payload ->> 'branchName',
          v_payload ->> 'accountNumber', v_payload ->> 'accountHolder',
          coalesce((v_payload ->> 'isPayrollAccount')::boolean, false), p_reason
        );
      when 'TAX_PROFILE' then
        if not app_private.has_hrm_template_permission(public.current_app_user_id(), 'hrm.compensation.manage') then
          raise exception using errcode = '42501', message = 'HRM_IMPORT_C4_MANAGE_REQUIRED';
        end if;
        perform public.upsert_hrm_employee_tax_profile(
          v_employee.id, v_payload ->> 'taxCode', v_payload ->> 'taxResidencyCode',
          nullif(v_payload ->> 'registrationDate', '')::date, p_reason
        );
      when 'QUALIFICATION' then
        perform public.upsert_hrm_employee_qualification(
          v_employee.id, v_row.record_code, v_payload ->> 'educationLevelCode',
          v_payload ->> 'institutionName', v_payload ->> 'majorName', v_payload ->> 'degreeName',
          nullif(v_payload ->> 'graduationYear', '')::integer, nullif(v_payload ->> 'startDate', '')::date,
          nullif(v_payload ->> 'endDate', '')::date, p_reason
        );
      when 'CERTIFICATION' then
        perform public.upsert_hrm_employee_certification(
          v_employee.id, v_row.record_code, v_payload ->> 'certificationTypeCode',
          v_payload ->> 'certificationName', v_payload ->> 'certificateNumber',
          v_payload ->> 'issuerName', nullif(v_payload ->> 'issuedDate', '')::date,
          nullif(v_payload ->> 'expiryDate', '')::date, p_reason
        );
      else
        raise exception using errcode = '22023', message = 'HRM_IMPORT_RECORD_TYPE_UNSUPPORTED';
    end case;
    update public.hrm_import_staging_rows set validation_status = 'APPLIED', updated_at = now() where id = v_row.id;
    v_applied := v_applied + 1;
  end loop;
  update public.hrm_import_batches set status = 'APPLIED', applied_at = now(), updated_at = now()
  where id = p_batch_id;
  perform app_private.audit_hrm_profile_command(
    public.current_app_user_id(), 'HRM_PROFILE_IMPORT', p_batch_id::text, 'INSERT', p_reason,
    array['batch_id','source_file_hash','manifest','applied_rows']
  );
  return jsonb_build_object('batchId', p_batch_id, 'status', 'APPLIED', 'appliedRows', v_applied, 'idempotentReplay', false);
end;
$$;


