CREATE FUNCTION public.approve_single_material_po(p_purchase_order_id text, p_actor_user_id uuid DEFAULT NULL::uuid, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := coalesce(p_actor_user_id, public.current_app_user_id());
