-- Name: can_manage_ai_learning(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_manage_ai_learning() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.users u
    where u.id = public.current_app_user_id()
      and coalesce(u.is_active, true)
      and (
        u.role = 'ADMIN'
        or 'SETTINGS' = any(coalesce(u.admin_modules, '{}'::text[]))
        or (
          coalesce(u.admin_sub_modules, '{}'::jsonb) ? 'SETTINGS'
          and coalesce(u.admin_sub_modules -> 'SETTINGS', '[]'::jsonb) ? '/settings/ai-learning'
        )
      )
  );
$$;


