--
-- Name: create_hrm_employee_core(uuid, text, text, text, text, text, date, date, date, text, uuid, uuid, uuid, uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_hrm_employee_core(p_employee_id uuid, p_employee_code text, p_full_name text, p_gender text, p_phone text, p_email text, p_date_of_birth date, p_start_date date, p_official_date date, p_status text, p_linked_user_id uuid, p_area_id uuid, p_office_id uuid, p_employee_type_id uuid, p_work_schedule_id uuid, p_marital_status text, p_avatar_url text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := public.current_app_user_id();
  v_employee public.employees%rowtype;
begin
  if not app_private.has_hrm_template_permission(v_actor_id, 'hrm.employee.edit_profile') then
    raise exception using errcode = '42501', message = 'HRM_PROFILE_EDIT_REQUIRED';
  end if;
  perform app_private.assert_hrm_mutation_context(p_reason, 'employee-create');
  if length(trim(coalesce(p_employee_code, ''))) = 0 or length(trim(coalesce(p_full_name, ''))) = 0 then
    raise exception using errcode = '22023', message = 'HRM_EMPLOYEE_CORE_REQUIRED';
  end if;
  insert into public.employees(
    id, employee_code, full_name, gender, phone, email, date_of_birth,
    start_date, official_date, status, user_id, area_id, office_id,
    employee_type_id, work_schedule_id, marital_status, avatar_url
  ) values (
    coalesce(p_employee_id, gen_random_uuid()), trim(p_employee_code), trim(p_full_name),
    nullif(trim(p_gender), ''), nullif(trim(p_phone), ''), nullif(trim(p_email), ''),
    p_date_of_birth, p_start_date, p_official_date,
    coalesce(nullif(trim(p_status), ''), 'Đang làm việc'), p_linked_user_id,
    p_area_id, p_office_id, p_employee_type_id, p_work_schedule_id,
    nullif(trim(p_marital_status), ''), nullif(trim(p_avatar_url), '')
  ) returning * into v_employee;
  perform app_private.audit_hrm_profile_command(
    v_employee.id, 'HRM_EMPLOYEE_PROFILE', v_employee.id::text, 'INSERT', p_reason,
    array['employee_code','full_name','profile_fields']
  );
  return to_jsonb(v_employee);
end;
$$;


--
-- Name: create_hrm_import_batch(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_hrm_import_batch(p_source_file_path text, p_source_file_hash text, p_manifest jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_actor_id uuid := public.current_app_user_id();
  v_batch public.hrm_import_batches%rowtype;
begin
  if not app_private.has_hrm_template_permission(v_actor_id, 'hrm.employee.import') then
    raise exception using errcode = '42501', message = 'HRM_EMPLOYEE_IMPORT_REQUIRED';
  end if;
  if p_source_file_path not like v_actor_id::text || '/%'
    or lower(trim(coalesce(p_source_file_hash, ''))) !~ '^[0-9a-f]{64}$'
    or jsonb_typeof(coalesce(p_manifest, '{}'::jsonb)) <> 'object'
    or coalesce((p_manifest ->> 'formatVersion')::integer, 0) <> 1
    or coalesce((p_manifest ->> 'dataSheetCount')::integer, 0) <> 8
    or not exists (
      select 1 from storage.objects object_row
      where object_row.bucket_id = 'hrm-private-imports' and object_row.name = p_source_file_path
    )
  then raise exception using errcode = '22023', message = 'HRM_IMPORT_MANIFEST_INVALID';
  end if;
  insert into public.hrm_import_batches(
    source_file_path, source_file_hash, manifest, created_by
  ) values (
    trim(p_source_file_path), lower(trim(p_source_file_hash)), coalesce(p_manifest, '{}'::jsonb), v_actor_id
  ) returning * into v_batch;
  return jsonb_build_object(
    'batchId', v_batch.id, 'status', v_batch.status,
    'expiresAt', v_batch.expires_at, 'sourceFileHash', v_batch.source_file_hash
  );
end;
$_$;


--
-- Name: create_material_issue_order(text, text, text, text, text, text, uuid, text, text, text, date, text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_material_issue_order(p_project_id text, p_construction_site_id text, p_source_warehouse_id text, p_recipient_type text, p_recipient_id text, p_recipient_name text, p_responsible_user_id uuid, p_subcontractor_contract_id text, p_material_request_id text, p_work_boq_item_id text, p_needed_date date, p_note text, p_lines jsonb, p_recipient_source_type text DEFAULT NULL::text, p_recipient_source_id text DEFAULT NULL::text) RETURNS public.material_issue_orders
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_order public.material_issue_orders%rowtype;
  v_order_id uuid := gen_random_uuid();
  v_issue_no text;
  v_line jsonb;
  v_item public.items%rowtype;
  v_qty numeric;
begin
  if v_actor is null then raise exception 'authentication required'; end if;
  if not (
    app_private.material_issue_can_manage_project(p_project_id, p_construction_site_id)
    or app_private.current_user_is_wms_keeper_for(p_source_warehouse_id)
  ) then
    raise exception 'Bạn không có quyền tạo phiếu xuất cấp cho dự án/công trường này.';
  end if;
  if coalesce(p_source_warehouse_id, '') = '' then raise exception 'Chưa chọn kho xuất.'; end if;
  if p_recipient_type not in ('employee', 'work_group', 'subcontractor', 'partner', 'manual') then
    raise exception 'Loại bên nhận không hợp lệ.';
  end if;
  if coalesce(trim(p_recipient_name), '') = '' then raise exception 'Chưa nhập tên bên nhận.'; end if;
  if p_recipient_source_type is not null
     and p_recipient_source_type not in ('supplier_contract', 'business_partner') then
    raise exception 'Nguồn bên nhận không hợp lệ.';
  end if;
  if (p_recipient_source_type is null)
     <> (nullif(trim(coalesce(p_recipient_source_id, '')), '') is null) then
    raise exception 'Nguồn bên nhận phải có đủ loại và mã tham chiếu.';
  end if;
  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'Phiếu xuất cấp chưa có dòng vật tư.';
  end if;

  v_issue_no := 'MI-' || to_char(now(), 'YYYYMMDD') || '-' || upper(substr(replace(v_order_id::text, '-', ''), 1, 6));

  insert into public.material_issue_orders(
    id, issue_no, project_id, construction_site_id, source_warehouse_id,
    recipient_type, recipient_id, recipient_name, recipient_source_type, recipient_source_id,
    responsible_user_id, subcontractor_contract_id, material_request_id, work_boq_item_id,
    needed_date, status, note, created_by
  ) values (
    v_order_id, v_issue_no, nullif(p_project_id, ''), nullif(p_construction_site_id, ''), p_source_warehouse_id,
    p_recipient_type, nullif(p_recipient_id, ''), trim(p_recipient_name),
    p_recipient_source_type, nullif(trim(coalesce(p_recipient_source_id, '')), ''),
    p_responsible_user_id, nullif(p_subcontractor_contract_id, ''), nullif(p_material_request_id, ''), nullif(p_work_boq_item_id, ''),
    p_needed_date, 'draft', nullif(trim(coalesce(p_note, '')), ''), v_actor
  )
  returning * into v_order;

  for v_line in select value from jsonb_array_elements(p_lines)
  loop
    v_qty := coalesce(nullif(v_line ->> 'quantity', '')::numeric, 0);
    if coalesce(v_line ->> 'itemId', '') = '' or v_qty <= 0 then
      raise exception 'Dòng vật tư không hợp lệ.';
    end if;

    select * into v_item from public.items where id = v_line ->> 'itemId';
    if not found then raise exception 'Không tìm thấy vật tư %.', v_line ->> 'itemId'; end if;

    insert into public.material_issue_lines(
      issue_order_id, item_id, sku_snapshot, item_name_snapshot, unit,
      requested_qty, approved_qty, unit_price,
      material_budget_item_id, material_request_line_id, work_boq_item_id,
      subcontractor_contract_id, note
    ) values (
      v_order_id, v_item.id, v_item.sku, v_item.name, coalesce(nullif(v_line ->> 'unit', ''), v_item.unit),
      v_qty, v_qty, coalesce(nullif(v_line ->> 'unitPrice', '')::numeric, coalesce(v_item.price_in, 0)),
      nullif(v_line ->> 'materialBudgetItemId', ''),
      nullif(v_line ->> 'materialRequestLineId', ''),
      coalesce(nullif(v_line ->> 'workBoqItemId', ''), nullif(p_work_boq_item_id, '')),
      coalesce(nullif(v_line ->> 'subcontractorContractId', ''), nullif(p_subcontractor_contract_id, '')),
      nullif(trim(coalesce(v_line ->> 'note', '')), '')
    );
  end loop;

  return v_order;
end;
$$;


--
-- Name: material_issue_returns; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.material_issue_returns (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    issue_order_id uuid NOT NULL,
    return_no text NOT NULL,
    target_warehouse_id text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    transaction_id text NOT NULL,
    reason text NOT NULL,
    note text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_by uuid,
    completed_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT material_issue_returns_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'completed'::text, 'cancelled'::text])))
);


--
-- Name: create_material_issue_return(uuid, text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_material_issue_return(p_order_id uuid, p_target_warehouse_id text, p_lines jsonb, p_reason text, p_note text DEFAULT NULL::text) RETURNS public.material_issue_returns
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_order public.material_issue_orders%rowtype;
  v_return public.material_issue_returns%rowtype;
  v_return_id uuid := gen_random_uuid();
  v_transaction_id text := 'tx-material-return-' || replace(gen_random_uuid()::text, '-', '');
  v_return_no text;
  v_items jsonb := '[]'::jsonb;
  v_return_lines jsonb := '[]'::jsonb;
  v_line jsonb;
  v_issue_line public.material_issue_lines%rowtype;
  v_qty numeric;
  v_available numeric;
begin
  if v_actor is null then raise exception 'authentication required'; end if;
  if coalesce(trim(p_reason), '') = '' then raise exception 'Bắt buộc nhập lý do hoàn trả.'; end if;

  select * into v_order from public.material_issue_orders where id = p_order_id for update;
  if not found then raise exception 'Không tìm thấy phiếu xuất cấp.'; end if;

  if v_order.status not in ('issued', 'partially_received', 'received', 'settling', 'partially_returned') then
    raise exception 'Phiếu chưa sẵn sàng hoàn trả.';
  end if;

  if not app_private.material_issue_can_process(v_order.source_warehouse_id, v_order.created_by, v_order.responsible_user_id, v_order.recipient_type, v_order.recipient_id) then
    raise exception 'Bạn không có quyền tạo phiếu hoàn trả.';
  end if;

  v_return_no := 'MRET-' || to_char(now(), 'YYYYMMDD') || '-' || upper(substr(replace(v_return_id::text, '-', ''), 1, 6));

  for v_line in select value from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb))
  loop
    v_qty := coalesce(nullif(v_line ->> 'returnQty', '')::numeric, 0);
    if v_qty <= 0 then raise exception 'Số lượng hoàn trả phải lớn hơn 0.'; end if;

    select * into v_issue_line
    from public.material_issue_lines
    where id = (v_line ->> 'issueLineId')::uuid
      and issue_order_id = p_order_id
    for update;
    if not found then raise exception 'Không tìm thấy dòng phiếu xuất cấp.'; end if;

    v_available := greatest(v_issue_line.issued_qty - v_issue_line.returned_qty - v_issue_line.consumed_qty - v_issue_line.lost_qty, 0);
    if v_qty > v_available then raise exception 'Số lượng hoàn trả vượt số lượng còn quyết toán.'; end if;

    v_items := v_items || jsonb_build_array(jsonb_build_object(
      'itemId', v_issue_line.item_id,
      'quantity', v_qty,
      'price', v_issue_line.unit_price,
      'materialIssueOrderId', p_order_id,
      'materialIssueLineId', v_issue_line.id,
      'materialIssueReturnId', v_return_id,
      'recipientType', v_order.recipient_type,
      'recipientNameSnapshot', v_order.recipient_name
    ));

    v_return_lines := v_return_lines || jsonb_build_array(jsonb_build_object(
      'issueLineId', v_issue_line.id,
      'itemId', v_issue_line.item_id,
      'returnQty', v_qty,
      'unit', v_issue_line.unit,
      'reason', nullif(trim(coalesce(v_line ->> 'reason', '')), '')
    ));
  end loop;

  if jsonb_array_length(v_items) = 0 then raise exception 'Phiếu hoàn trả chưa có dòng vật tư.'; end if;

  insert into public.transactions(
    id, type, date, items, source_warehouse_id, target_warehouse_id,
    requester_id, approver_id, status, note, related_request_id, pending_items
  ) values (
    v_transaction_id, 'IMPORT', now(), v_items, null, p_target_warehouse_id,
    v_actor, null, 'PENDING',
    'Hoàn trả vật tư từ ' || v_order.recipient_name || ' theo phiếu ' || v_order.issue_no,
    v_order.material_request_id, '[]'::jsonb
  );

  insert into public.material_issue_returns(
    id, issue_order_id, return_no, target_warehouse_id, status,
    transaction_id, reason, note, created_by
  ) values (
    v_return_id, p_order_id, v_return_no, p_target_warehouse_id, 'pending',
    v_transaction_id, trim(p_reason), nullif(trim(coalesce(p_note, '')), ''), v_actor
  )
  returning * into v_return;

  for v_line in select value from jsonb_array_elements(v_return_lines)
  loop
    insert into public.material_issue_return_lines(
      issue_return_id, issue_line_id, item_id, return_qty, unit, reason
    ) values (
      v_return_id,
      (v_line ->> 'issueLineId')::uuid,
      v_line ->> 'itemId',
      coalesce(nullif(v_line ->> 'returnQty', '')::numeric, 0),
      nullif(v_line ->> 'unit', ''),
      nullif(v_line ->> 'reason', '')
    );
  end loop;

  if to_regclass('public.project_document_links') is not null then
    insert into public.project_document_links(source_type, source_id, target_type, target_id, project_id, relation_type, status, metadata)
    values ('material_issue_order', v_order.id::text, 'material_issue_return', v_return_id::text, v_order.project_id, 'downstream', 'active', jsonb_build_object('returnNo', v_return_no, 'transactionId', v_transaction_id))
    on conflict (source_type, source_id, target_type, target_id, relation_type)
    do update set status = excluded.status, metadata = excluded.metadata, updated_at = now();

    insert into public.project_document_links(source_type, source_id, target_type, target_id, project_id, relation_type, status, metadata)
    values ('material_issue_order', v_order.id::text, 'transaction', v_transaction_id, v_order.project_id, 'downstream', 'active', jsonb_build_object('kind', 'material_issue_return', 'returnId', v_return_id))
    on conflict (source_type, source_id, target_type, target_id, relation_type)
    do update set status = excluded.status, metadata = excluded.metadata, updated_at = now();
  end if;

  return v_return;
end;
$$;


