-- Name: purchase_order_supplier_returns; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.purchase_order_supplier_returns (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    return_no text NOT NULL,
    purchase_order_id text NOT NULL,
    project_id text,
    construction_site_id text,
    vendor_id text,
