--
-- Name: warehouses; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.warehouses (
    id text NOT NULL,
    name text NOT NULL,
    address text NOT NULL,
    type text DEFAULT 'SITE'::text NOT NULL,
    is_archived boolean DEFAULT false,
    created_at timestamp with time zone DEFAULT now(),
    construction_site_id uuid,
    is_default_for_site boolean DEFAULT false NOT NULL,
    project_id text,
    CONSTRAINT warehouses_default_for_site_check CHECK (((NOT is_default_for_site) OR ((construction_site_id IS NOT NULL) AND (type = 'SITE'::text) AND (NOT COALESCE(is_archived, false)))))
);


--
-- Name: COLUMN warehouses.construction_site_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.warehouses.construction_site_id IS 'Công trường sở hữu kho. Một kho chỉ được liên kết với tối đa một công trường.';


--
-- Name: COLUMN warehouses.is_default_for_site; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.warehouses.is_default_for_site IS 'Kho SITE active được tự chọn khi tạo phiếu giao HĐ NCC tại công trường.';


--
-- Name: COLUMN warehouses.project_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.warehouses.project_id IS 'Dự án sở hữu kho SITE. Backend dùng trường này làm scope authoritative khi post WMS.';


--
-- Name: create_warehouse_with_site_binding(text, text, text, text, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_warehouse_with_site_binding(p_warehouse_id text, p_name text, p_address text, p_type text, p_project_id text DEFAULT NULL::text, p_construction_site_id uuid DEFAULT NULL::uuid, p_is_default_for_site boolean DEFAULT false) RETURNS public.warehouses
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_warehouse public.warehouses%rowtype;
begin
  if not app_private.can_manage_warehouse_site_bindings() then
    raise exception 'Bạn không có quyền tạo và gán kho vào dự án.';
  end if;
  if nullif(btrim(p_warehouse_id), '') is null
     or nullif(btrim(p_name), '') is null
     or nullif(btrim(p_type), '') is null then
    raise exception 'Kho mới phải có mã, tên và loại kho.';
  end if;
  if p_type = 'SITE' and (p_project_id is null or p_construction_site_id is null) then
    raise exception 'Kho SITE phải chọn dự án và công trường.';
  end if;
  if coalesce(p_is_default_for_site, false)
     and (p_project_id is null or p_construction_site_id is null or p_type <> 'SITE') then
    raise exception 'Kho mặc định phải là kho SITE đã gắn dự án/công trường.';
  end if;
  if exists (select 1 from public.warehouses where id = p_warehouse_id) then
    raise exception 'Mã kho % đã tồn tại.', p_warehouse_id;
  end if;
  if coalesce(p_is_default_for_site, false) then
    update public.warehouses set is_default_for_site = false
    where construction_site_id = p_construction_site_id and is_default_for_site;
  end if;
  insert into public.warehouses(
    id, name, address, type, is_archived, project_id,
    construction_site_id, is_default_for_site
  ) values (
    p_warehouse_id, btrim(p_name), coalesce(p_address, ''), btrim(p_type), false,
    nullif(p_project_id, ''), p_construction_site_id, coalesce(p_is_default_for_site, false)
  ) returning * into v_warehouse;
  return v_warehouse;
end;
$$;


--
-- Name: daily_log_user_has_project_permission(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.daily_log_user_has_project_permission(p_user_id text, p_project_id text, p_construction_site_id text, p_permission_code text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.users u
    where u.id::text = p_user_id
      and u.role = 'ADMIN'
      and coalesce(u.is_active, true)
  )
  or not app_private.daily_log_scope_has_staff(p_project_id, p_construction_site_id)
  or exists (
    select 1
    from public.project_staff ps
    join public.project_staff_permissions psp
      on psp.staff_id = ps.id
     and coalesce(psp.is_active, true)
    join public.project_permission_types ppt
      on ppt.id = psp.permission_type_id
     and ppt.code = p_permission_code
     and coalesce(ppt.is_active, true)
    where ps.user_id::text = p_user_id
      and ps.end_date is null
      and (
        (p_project_id is not null and ps.project_id::text = p_project_id)
        or (p_construction_site_id is not null and ps.construction_site_id::text = p_construction_site_id)
      )
  );
$$;


