--
-- Name: dispose_asset(text, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispose_asset(p_asset_id text, p_disposal_date text DEFAULT NULL::text, p_disposal_value numeric DEFAULT NULL::numeric, p_disposal_note text DEFAULT NULL::text) RETURNS public.assets
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_asset public.assets%rowtype;
begin
  select * into v_asset
  from public.assets
  where id = p_asset_id
  for update;

  if not found then
    raise exception 'asset not found' using errcode = 'P0002';
  end if;

  if not app_private.asset_has_action('asset.catalog.dispose',
    v_asset.warehouse_id,
    v_asset.managing_dept_id,
    app_private.uuid_or_null(v_asset.assigned_to_user_id)
  ) then
    raise exception 'insufficient privilege to dispose asset' using errcode = '42501';
  end if;

  update public.assets
  set status = 'DISPOSED'::public.asset_status,
      disposal_date = coalesce(nullif(p_disposal_date, ''), now()::date::text),
      disposal_value = p_disposal_value,
      disposal_note = nullif(p_disposal_note, ''),
      updated_at = now()
  where id = p_asset_id
  returning * into v_asset;

  return v_asset;
end;
$$;


