--
-- Name: execute_ai_query(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.execute_ai_query(query_text text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result JSON;
  upper_query TEXT;
  clean_query TEXT;
BEGIN
  -- Strip trailing semicolons and whitespace
  clean_query := RTRIM(TRIM(query_text), ';');
  clean_query := TRIM(clean_query);

  -- Safety check: only allow SELECT and WITH (CTE)
  upper_query := UPPER(clean_query);
  IF NOT (upper_query LIKE 'SELECT%' OR upper_query LIKE 'WITH%') THEN
    RETURN json_build_object('error', 'Only SELECT queries are allowed');
  END IF;

  -- Block dangerous keywords using word-boundary regex
  IF upper_query ~ '\y(INSERT|UPDATE|DELETE|DROP|ALTER|CREATE|TRUNCATE|GRANT|REVOKE|EXEC|EXECUTE)\y' THEN
    RETURN json_build_object('error', 'Dangerous keywords detected');
  END IF;

  -- Block multiple statements (prevent SQL injection via semicolons)
  IF clean_query LIKE '%;%' THEN
    RETURN json_build_object('error', 'Multiple statements are not allowed');
  END IF;

  -- Execute and return as JSON
  EXECUTE 'SELECT json_agg(row_to_json(t)) FROM (' || clean_query || ') t' INTO result;

  -- Handle null result (no rows)
  IF result IS NULL THEN
    result := '[]'::json;
  END IF;

  RETURN result;
EXCEPTION
  WHEN OTHERS THEN
    RETURN json_build_object('error', SQLERRM);
END;
$$;


--
-- Name: execute_ai_readonly_query(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.execute_ai_readonly_query(p_query text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare
  v_sql text := trim(coalesce(p_query, ''));
  v_lower text;
  v_rows jsonb;
  v_row_count integer;
begin
  v_sql := regexp_replace(v_sql, ';\s*$', '');
  v_lower := lower(v_sql);

  if v_sql = '' or v_lower !~ '^\s*(select|with)\s' then
    raise exception 'AI query must be SELECT-only';
  end if;

  if v_sql like '%;%' then
    raise exception 'AI query must contain a single statement';
  end if;

  if v_sql ~ '(--|/\*)' then
    raise exception 'AI query comments are not allowed';
  end if;

  if v_lower ~ '(^|[^a-z_])(insert|update|delete|drop|alter|truncate|grant|revoke|create|replace|merge|call|copy|do|execute|notify|listen|vacuum|analyze|set|reset|refresh)([^a-z_]|$)' then
    raise exception 'AI query contains a blocked keyword';
  end if;

  if v_lower ~ '(^|[^a-z_])(auth|storage|vault|net|extensions|pg_catalog|information_schema)\s*\.' then
    raise exception 'AI query references a blocked schema';
  end if;

  perform set_config('statement_timeout', '5000', true);

  execute format(
    'select coalesce(jsonb_agg(to_jsonb(ai_limited)), ''[]''::jsonb)
       from (select * from (%s) ai_source limit 500) ai_limited',
    v_sql
  )
  into v_rows;

  v_row_count := coalesce(jsonb_array_length(v_rows), 0);
  return jsonb_build_object(
    'rows', v_rows,
    'rowCount', v_row_count,
    'limited', v_row_count >= 500
  );
end;
$_$;


--
-- Name: execute_readonly_query(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.execute_readonly_query(query_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result jsonb;
BEGIN
  -- Only allow SELECT statements
  IF NOT (lower(trim(query_text)) LIKE 'select%' OR lower(trim(query_text)) LIKE 'with%') THEN
    RAISE EXCEPTION 'Only SELECT queries are allowed';
  END IF;

  -- Block dangerous keywords
  IF query_text ~* '\b(insert|update|delete|drop|alter|truncate|create|grant|revoke)\b' THEN
    RAISE EXCEPTION 'Write operations are not allowed';
  END IF;

  EXECUTE 'SELECT jsonb_agg(row_to_json(t)) FROM (' || query_text || ') t' INTO result;
  RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


--
-- Name: export_hrm_employee_profiles(uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.export_hrm_employee_profiles(p_employee_ids uuid[], p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := public.current_app_user_id();
  v_employee_id uuid;
  v_rows jsonb := '[]'::jsonb;
  v_result jsonb;
begin
  if not app_private.has_hrm_template_permission(v_actor_id, 'hrm.employee.export')
    or not app_private.has_hrm_template_permission(v_actor_id, 'hrm.compensation.manage')
  then raise exception using errcode = '42501', message = 'HRM_EMPLOYEE_EXPORT_REQUIRED';
  end if;
  perform app_private.assert_hrm_mutation_context(p_reason, 'profile-export');
  if cardinality(p_employee_ids) is null or cardinality(p_employee_ids) = 0 or cardinality(p_employee_ids) > 1000 then
    raise exception using errcode = '22023', message = 'HRM_EXPORT_EMPLOYEE_SELECTION_INVALID';
  end if;
  foreach v_employee_id in array p_employee_ids
  loop
    v_rows := v_rows || jsonb_build_object(
      'overview', app_private.get_hrm_employee_overview(v_employee_id),
      'personalContact', app_private.get_hrm_employee_personal_contact(v_employee_id),
      'workOrganization', app_private.get_hrm_employee_work_organization(v_employee_id),
      'attendanceLeave', app_private.get_hrm_employee_attendance_leave(v_employee_id),
      'contractsEmployment', app_private.get_hrm_employee_contract_employment(v_employee_id),
      'legalInsurance', app_private.get_hrm_employee_legal_insurance(v_employee_id),
      'compensationTaxBank', app_private.get_hrm_employee_compensation_tax_bank(v_employee_id),
      'qualificationsDocuments', app_private.get_hrm_employee_qualifications_documents(v_employee_id)
    );
    perform app_private.audit_hrm_profile_command(
      v_employee_id, 'HRM_PROFILE_EXPORT', v_employee_id::text, 'INSERT', p_reason,
      array['C1','C2','C3','C4']
    );
  end loop;
  v_result := jsonb_build_object(
    'manifestVersion', 1, 'generatedAt', now(), 'exportedBy', v_actor_id,
    'watermark', 'VIOO HRM - Dữ liệu mật - ' || to_char(now(), 'YYYY-MM-DD HH24:MI:SS OF'),
    'reason', p_reason, 'employeeCount', cardinality(p_employee_ids), 'employees', v_rows
  );
  return v_result || jsonb_build_object('manifestHash', md5(v_result::text));
end;
$$;


