--

CREATE FUNCTION public.is_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.users u
    where u.id = public.current_app_user_id()
      and u.role = 'ADMIN'
      and coalesce(u.is_active, true)
  );
$$;


--
-- Name: is_module_admin(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_module_admin(p_module text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.users
    where auth_id = (select auth.uid())
      and (
        role = 'ADMIN'
        or p_module = any(coalesce(admin_modules, '{}'::text[]))
        or coalesce(admin_sub_modules, '{}'::jsonb) ? p_module
      )
  );
$$;


