--
-- Name: match_ai_memories(public.vector, integer, double precision, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_ai_memories(query_embedding public.vector, match_count integer DEFAULT 10, match_threshold double precision DEFAULT 0.3, filter_user_id text DEFAULT NULL::text) RETURNS TABLE(id uuid, content text, category text, topics text[], importance integer, similarity double precision)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    m.id,
    m.content,
    m.category,
    m.topics,
    m.importance,
    1 - (m.embedding <=> query_embedding) AS similarity
  FROM ai_memory m
  WHERE m.embedding IS NOT NULL
    AND 1 - (m.embedding <=> query_embedding) > match_threshold
    AND (filter_user_id IS NULL OR m.user_id = filter_user_id OR m.user_id = 'system')
  ORDER BY m.importance DESC, similarity DESC
  LIMIT match_count;
END;
$$;


--
-- Name: match_query_cache(public.vector, integer, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_query_cache(query_embedding public.vector, match_count integer DEFAULT 3, match_threshold double precision DEFAULT 0.85) RETURNS TABLE(id uuid, question text, sql_query text, answer text, hit_count integer, score double precision, similarity double precision)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    c.id,
    c.question,
    c.sql_query,
    c.answer,
    c.hit_count,
    c.score,
    1 - (c.embedding <=> query_embedding) AS similarity
  FROM ai_query_cache c
  WHERE c.embedding IS NOT NULL
    AND c.score > 0
    AND 1 - (c.embedding <=> query_embedding) > match_threshold
  ORDER BY similarity DESC
  LIMIT match_count;
END;
$$;


--
-- Name: match_rag_chunks(public.vector, integer, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_rag_chunks(query_embedding public.vector, match_count integer DEFAULT 5, match_threshold double precision DEFAULT 0.3) RETURNS TABLE(id uuid, document_id uuid, content text, metadata jsonb, similarity double precision)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    rc.id, rc.document_id, rc.content, rc.metadata,
    1 - (rc.embedding <=> query_embedding) as similarity
  FROM rag_chunks rc
  JOIN rag_documents rd ON rc.document_id = rd.id
  WHERE rd.status = 'ready'
    AND 1 - (rc.embedding <=> query_embedding) > match_threshold
  ORDER BY rc.embedding <=> query_embedding
  LIMIT match_count;
$$;


