--
-- Name: preview_user_hr_business_role(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_user_hr_business_role(p_target_user_id uuid, p_target_role_code text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select app_private.preview_user_hr_business_role_impl(
    p_target_user_id,
    p_target_role_code,
    p_expires_at
  );
$$;


