CREATE TABLE public.supplier_payable_documents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    code text NOT NULL,
    source_type text NOT NULL,
    source_id text NOT NULL,
    project_id text,
    construction_site_id text,
    supplier_id text,
    supplier_name_snapshot text NOT NULL,
    document_no text NOT NULL,
    document_date date NOT NULL,
    due_date date,
    currency text DEFAULT 'VND'::text NOT NULL,
    committed_amount numeric(18,2) DEFAULT 0 NOT NULL,
    recognized_amount numeric(18,2) DEFAULT 0 NOT NULL,
    credit_amount numeric(18,2) DEFAULT 0 NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    qr_token text,
    invoice_number text,
    invoice_date date,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    supplier_contract_id text,
    supplier_contract_code text,
    CONSTRAINT supplier_payable_documents_check CHECK (((project_id IS NOT NULL) OR (construction_site_id IS NOT NULL))),
    CONSTRAINT supplier_payable_documents_committed_amount_check CHECK ((committed_amount >= (0)::numeric)),
    CONSTRAINT supplier_payable_documents_credit_amount_check CHECK ((credit_amount >= (0)::numeric)),
    CONSTRAINT supplier_payable_documents_recognized_amount_check CHECK ((recognized_amount >= (0)::numeric)),
    CONSTRAINT supplier_payable_documents_source_type_check CHECK ((source_type = ANY (ARRAY['purchase_order'::text, 'purchase_delivery_receipt'::text, 'supplier_invoice_adjustment'::text, 'site_direct_purchase'::text, 'supplier_delivery_statement'::text, 'supplier_return_credit'::text, 'opening_balance'::text, 'manual_adjustment'::text]))),
    CONSTRAINT supplier_payable_documents_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'open'::text, 'partial'::text, 'paid'::text, 'cancelled'::text, 'reversed'::text])))
);


--
-- Name: record_site_direct_purchase_payable_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_site_direct_purchase_payable_v1(p_direct_purchase_id uuid) RETURNS public.supplier_payable_documents
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_purchase public.site_direct_purchases%rowtype;
  v_document public.supplier_payable_documents%rowtype;
begin
  select * into v_purchase
  from public.site_direct_purchases
  where id = p_direct_purchase_id
  for update;

  if not found then
    raise exception 'Không tìm thấy phiếu mua nóng %. ', p_direct_purchase_id;
  end if;

  if not app_private.ap_scope_can_mutate(v_purchase.project_id, v_purchase.construction_site_id)
    or not app_private.material_flow_has_action_or_legacy(v_purchase.project_id, v_purchase.construction_site_id, 'project.material_direct_purchase.record_ap') then
    raise exception 'Bạn không có quyền xác nhận công nợ phiếu mua nóng này.';
  end if;

  if v_purchase.status not in ('purchased', 'received', 'finance_review') then
    raise exception 'Chỉ xác nhận công nợ sau khi phiếu đã mua và sẵn sàng đối chiếu.';
  end if;

  if exists (
    select 1 from public.site_direct_purchase_lines line
    where line.direct_purchase_id = v_purchase.id
      and line.status in ('accepted', 'adjusted')
  ) is not true then
    raise exception 'Phiếu chưa có dòng hàng hợp lệ để xác nhận công nợ.';
  end if;

  perform set_config('app.direct_purchase_recording', 'on', true);

  if exists (
    select 1 from public.site_direct_purchase_lines line
    where line.direct_purchase_id = v_purchase.id
      and line.line_type = 'small_tool'
      and line.status in ('accepted', 'adjusted')
  ) then
    perform public.sync_site_small_tools_from_site_direct_purchase(v_purchase.id);
  end if;

  select * into v_document
  from public.sync_supplier_payable_from_site_direct_purchase(v_purchase.id);

  update public.site_direct_purchases purchase
  set
    status = 'reconciled',
    last_action_by = auth.uid(),
    last_action_at = now(),
    updated_at = now()
  where purchase.id = v_purchase.id;

  return v_document;
end;
$$;


