--
-- Name: COLUMN hrm_construction_sites.warehouse_binding_enforced; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.hrm_construction_sites.warehouse_binding_enforced IS 'Khi bật, phiếu giao HĐ NCC chỉ nhận kho SITE active thuộc công trường này.';


--
-- Name: set_construction_site_warehouse_enforcement(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_construction_site_warehouse_enforcement(p_construction_site_id uuid, p_enforced boolean) RETURNS public.hrm_construction_sites
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_site public.hrm_construction_sites%rowtype;
begin
  if not app_private.can_manage_warehouse_site_bindings() then
    raise exception 'Bạn không có quyền bật/tắt khóa kho cho công trường.';
  end if;

  update public.hrm_construction_sites
  set warehouse_binding_enforced = coalesce(p_enforced, false)
  where id = p_construction_site_id
  returning * into v_site;

  if not found then
    raise exception 'Không tìm thấy công trường %. ', p_construction_site_id;
  end if;

  return v_site;
end;
$$;


