--
-- Name: submit_material_issue_order(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_material_issue_order(p_order_id uuid, p_override_reason text DEFAULT NULL::text) RETURNS public.material_issue_orders
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := public.current_app_user_id();
  v_order public.material_issue_orders%rowtype;
  v_transaction_id text := 'tx-material-issue-' || replace(gen_random_uuid()::text, '-', '');
  v_items jsonb := '[]'::jsonb;
  v_line record;
begin
  if v_actor is null then raise exception 'authentication required'; end if;
  select * into v_order from public.material_issue_orders where id = p_order_id for update;
  if not found then raise exception 'Không tìm thấy phiếu xuất cấp.'; end if;
  if v_order.status not in ('draft', 'submitted') then raise exception 'Chỉ gửi duyệt phiếu ở trạng thái nháp.'; end if;
  if not (
    public.is_admin()
    or public.is_module_admin('WMS')
    or v_order.created_by = v_actor
    or app_private.material_issue_can_manage_project(v_order.project_id, v_order.construction_site_id)
  ) then
    raise exception 'Bạn không có quyền gửi phiếu xuất cấp này.';
  end if;

  for v_line in
    select * from public.material_issue_lines where issue_order_id = p_order_id order by created_at
  loop
    if v_line.approved_qty <= 0 then raise exception 'Phiếu có dòng số lượng không hợp lệ.'; end if;
    v_items := v_items || jsonb_build_array(jsonb_build_object(
      'itemId', v_line.item_id,
      'quantity', v_line.approved_qty,
      'price', v_line.unit_price,
      'materialIssueOrderId', v_order.id,
      'materialIssueLineId', v_line.id,
      'recipientType', v_order.recipient_type,
      'recipientNameSnapshot', v_order.recipient_name
    ));
  end loop;

  if jsonb_array_length(v_items) = 0 then raise exception 'Phiếu xuất cấp chưa có dòng vật tư.'; end if;

  insert into public.transactions(
    id, type, date, items, source_warehouse_id, target_warehouse_id,
    requester_id, approver_id, status, note, related_request_id, pending_items
  ) values (
    v_transaction_id, 'EXPORT', now(), v_items, v_order.source_warehouse_id, null,
    v_actor, null, 'PENDING',
    coalesce(
      nullif(trim(v_order.note), ''),
      'Xuất cấp thi công ' || v_order.issue_no || ' cho ' || v_order.recipient_name
    ),
    v_order.material_request_id, '[]'::jsonb
  );

  update public.material_issue_orders
  set status = 'wms_pending',
      transaction_id = v_transaction_id,
      submitted_by = v_actor,
      submitted_at = now(),
      override_reason = nullif(trim(coalesce(p_override_reason, '')), '')
  where id = p_order_id
  returning * into v_order;

  if to_regclass('public.project_document_links') is not null then
    if v_order.material_request_id is not null then
      insert into public.project_document_links(source_type, source_id, target_type, target_id, project_id, relation_type, status, metadata)
      values ('material_request', v_order.material_request_id, 'material_issue_order', v_order.id::text, v_order.project_id, 'downstream', 'active', jsonb_build_object('issueNo', v_order.issue_no, 'transactionId', v_transaction_id))
      on conflict (source_type, source_id, target_type, target_id, relation_type)
      do update set status = excluded.status, metadata = excluded.metadata, updated_at = now();
    end if;

    insert into public.project_document_links(source_type, source_id, target_type, target_id, project_id, relation_type, status, metadata)
    values ('material_issue_order', v_order.id::text, 'transaction', v_transaction_id, v_order.project_id, 'downstream', 'active', jsonb_build_object('kind', 'external_issue'))
    on conflict (source_type, source_id, target_type, target_id, relation_type)
    do update set status = excluded.status, metadata = excluded.metadata, updated_at = now();

    if v_order.subcontractor_contract_id is not null then
      insert into public.project_document_links(source_type, source_id, target_type, target_id, project_id, relation_type, status, metadata)
      values ('subcontractor_contract', v_order.subcontractor_contract_id, 'material_issue_order', v_order.id::text, v_order.project_id, 'downstream', 'active', jsonb_build_object('issueNo', v_order.issue_no))
      on conflict (source_type, source_id, target_type, target_id, relation_type)
      do update set status = excluded.status, metadata = excluded.metadata, updated_at = now();
    end if;
  end if;

  return v_order;
end;
$$;


--
-- Name: submit_material_issue_order_with_date(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_material_issue_order_with_date(p_order_id uuid, p_override_reason text DEFAULT NULL::text, p_transaction_date timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS public.material_issue_orders
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_order public.material_issue_orders%rowtype;
begin
  select * into v_order
  from public.submit_material_issue_order(p_order_id, p_override_reason);

  if p_transaction_date is not null then
    update public.material_issue_orders
    set voucher_date = p_transaction_date::date
    where id = v_order.id
    returning * into v_order;

    update public.transactions
    set date = p_transaction_date
    where id = v_order.transaction_id;
  end if;

  return v_order;
end;
$$;


--
-- Name: submit_material_po_batch(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_material_po_batch(p_delivery_batch_id uuid, p_approver_user_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := coalesce(p_actor_user_id, public.current_app_user_id());
begin
  if public.current_app_user_id() is null or v_actor <> public.current_app_user_id() then
    raise exception 'Người thực hiện lệnh không hợp lệ.' using errcode = '42501';
  end if;
  return app_private.submit_material_po_batch(
    p_delivery_batch_id,
    p_approver_user_id,
    v_actor
  );
end;
$$;


--
-- Name: submit_purchase_order_delivery_batch_approval_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_purchase_order_delivery_batch_approval_v1(p_delivery_batch_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := coalesce(p_actor_user_id, public.current_app_user_id());
  v_batch public.purchase_order_delivery_batches%rowtype;
  v_po public.purchase_orders%rowtype;
begin
  if public.current_app_user_id() is null or v_actor <> public.current_app_user_id() then
    raise exception 'Người thực hiện lệnh không hợp lệ.' using errcode = '42501';
  end if;
  select * into v_batch from public.purchase_order_delivery_batches where id = p_delivery_batch_id for update;
  if not found then raise exception 'Không tìm thấy đợt giao.' using errcode = '22023'; end if;
  select * into v_po from public.purchase_orders where id = v_batch.purchase_order_id for update;
  if coalesce(v_po.source_mode, '') <> 'from_request' or coalesce(v_po.purchase_mode, '') <> 'multiple' then
    raise exception 'Chỉ áp dụng duyệt đợt cho PO MR chia nhiều đợt.' using errcode = '22023';
  end if;
  perform app_private.assert_project_permission_room_action(v_po.project_id, v_po.construction_site_id, 'material_po', 'submit', v_actor);
  if v_batch.status <> 'planned' or v_batch.wms_transaction_id is not null or v_batch.qr_token is not null then
    raise exception 'Chỉ gửi duyệt đợt nháp chưa tạo WMS/QR.' using errcode = '22023';
  end if;
  if coalesce(v_batch.approval_status, 'draft') not in ('draft', 'revision_requested', 'rejected') then
    raise exception 'Đợt giao đang chờ duyệt hoặc đã duyệt.' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.purchase_order_delivery_lines
    where delivery_batch_id = v_batch.id and planned_qty > 0 and stock_planned_qty > 0 and delivery_unit_price >= 0
  ) then
    raise exception 'Đợt giao phải có SL yêu cầu và SL mua lớn hơn 0.' using errcode = '22023';
  end if;
  perform app_private.assert_multiple_delivery_batch_overage_reason_v1(v_po.id, v_batch.id);

  update public.purchase_order_delivery_batches
  set approval_status = 'pending_approval', approval_requested_by = v_actor, approval_requested_at = now(),
      approval_decided_by = null, approval_decided_at = null, approval_decision_note = null, updated_at = now()
  where id = v_batch.id;
  return jsonb_build_object('deliveryBatchId', v_batch.id, 'approvalStatus', 'pending_approval');
end;
$$;


