--
-- Name: update_purchase_order_delivery_group_v1(uuid, timestamp with time zone, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_purchase_order_delivery_group_v1(p_delivery_group_id uuid, p_planned_date timestamp with time zone, p_note text, p_lines jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_delivery_group_id is null then
    raise exception 'Không tìm thấy đợt giao cần sửa.';
  end if;

  perform 1
  from public.transactions transaction_row
  where transaction_row.id::text in (
    select batch.transaction_id::text
    from public.material_request_fulfillment_batches batch
    where batch.po_delivery_group_id = p_delivery_group_id
      and batch.transaction_id is not null
  )
  order by transaction_row.id
  for update;

  return app_private.project_po_update_delivery_group_impl_v1(
    p_delivery_group_id,
    p_planned_date,
    p_note,
    p_lines
  );
end;
$$;


