--
-- Name: update_transaction_items_for_receipt(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_transaction_items_for_receipt(p_transaction_id text, p_items jsonb) RETURNS public.transactions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_tx public.transactions%rowtype;
  v_user public.users%rowtype;
  v_item_count integer;
  v_idx integer;
  v_old_item jsonb;
  v_new_item jsonb;
  v_old_qty numeric;
  v_new_qty numeric;
  v_ordered_qty numeric;
  v_is_fulfillment_transfer boolean := false;
  v_can_adjust boolean := false;
begin
  select * into v_tx
  from public.transactions
  where id = p_transaction_id
  for update;
  if not found then
    raise exception 'transaction not found: %', p_transaction_id;
  end if;

  select * into v_user from public.users where id = public.current_app_user_id();
  if v_user.id is null then
    raise exception 'authentication required';
  end if;

  if v_tx.status not in ('PENDING'::public.transaction_status, 'APPROVED'::public.transaction_status) then
    raise exception 'Chỉ được điều chỉnh số lượng ở bước chờ duyệt hoặc chờ xác nhận nhập.';
  end if;

  if jsonb_typeof(p_items) <> 'array' then
    raise exception 'invalid transaction items payload';
  end if;

  v_item_count := jsonb_array_length(coalesce(v_tx.items, '[]'::jsonb));
  if v_item_count = 0 then
    raise exception 'Phiếu kho không có dòng vật tư để điều chỉnh.';
  end if;
  if jsonb_array_length(p_items) <> v_item_count then
    raise exception 'Không được thêm/xóa dòng vật tư khi duyệt phiếu kho.';
  end if;

  select exists (
    select 1
    from jsonb_array_elements(coalesce(v_tx.items, '[]'::jsonb)) line(value)
    where nullif(line.value->>'fulfillmentBatchId', '') is not null
  )
  into v_is_fulfillment_transfer;

  v_is_fulfillment_transfer := v_is_fulfillment_transfer
    and v_tx.type = 'TRANSFER'::public.transaction_type
    and nullif(v_tx.target_warehouse_id, '') is not null;

  v_can_adjust :=
    public.is_module_admin('WMS')
    or (
      v_user.role = 'WAREHOUSE_KEEPER'
      and (
        v_user.assigned_warehouse_id is null
        or (v_tx.type = 'IMPORT'::public.transaction_type and v_user.assigned_warehouse_id is not distinct from v_tx.target_warehouse_id)
        or (v_is_fulfillment_transfer and v_user.assigned_warehouse_id is not distinct from v_tx.target_warehouse_id)
        or (
          v_tx.status = 'APPROVED'::public.transaction_status
          and v_tx.type = 'TRANSFER'::public.transaction_type
          and v_user.assigned_warehouse_id is not distinct from v_tx.target_warehouse_id
        )
      )
    );

  if not v_can_adjust then
    raise exception 'insufficient privilege to adjust transaction quantities';
  end if;

  for v_idx in 0..(v_item_count - 1) loop
    v_old_item := v_tx.items -> v_idx;
    v_new_item := p_items -> v_idx;

    if v_old_item is null or v_new_item is null then
      raise exception 'invalid transaction items payload';
    end if;

    if coalesce(v_old_item->>'itemId', '') is distinct from coalesce(v_new_item->>'itemId', '')
       or coalesce(v_old_item->>'requestLineId', '') is distinct from coalesce(v_new_item->>'requestLineId', '')
       or coalesce(v_old_item->>'fulfillmentBatchId', '') is distinct from coalesce(v_new_item->>'fulfillmentBatchId', '') then
      raise exception 'Không được đổi vật tư/dòng đề xuất khi duyệt phiếu kho.';
    end if;

    v_old_qty := coalesce(nullif(v_old_item->>'quantity', '')::numeric, 0);
    v_new_qty := coalesce(nullif(v_new_item->>'quantity', '')::numeric, 0);
    v_ordered_qty := coalesce(
      nullif(v_new_item->>'orderedQty', '')::numeric,
      nullif(v_new_item->>'ordered_qty', '')::numeric,
      v_old_qty
    );

    if v_new_qty < 0 then
      raise exception 'Số lượng thực nhận không được âm.';
    end if;
    if v_ordered_qty < 0 then
      raise exception 'Số lượng đặt không được âm.';
    end if;
    if v_new_qty is distinct from v_ordered_qty
       and nullif(trim(coalesce(v_new_item->>'varianceReason', '')), '') is null
       and nullif(trim(coalesce(v_new_item->>'variance_reason', '')), '') is null then
      raise exception 'Phải nhập lý do khi số lượng thực nhận lệch số lượng trên phiếu.';
    end if;
  end loop;

  update public.transactions
  set items = p_items
  where id = p_transaction_id
  returning * into v_tx;

  return v_tx;
end;
$$;


--
-- Name: update_transaction_voucher_metadata(text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_transaction_voucher_metadata(p_transaction_id text, p_date timestamp with time zone, p_note text DEFAULT NULL::text) RETURNS public.transactions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tx public.transactions%rowtype;
  v_user public.users%rowtype;
  v_can_approve boolean;
begin
  select * into v_tx
  from public.transactions
  where id = p_transaction_id
  for update;
  if not found then
    raise exception 'transaction not found: %', p_transaction_id;
  end if;

  select * into v_user
  from public.users
  where id = public.current_app_user_id();
  if v_user.id is null then
    raise exception 'authentication required';
  end if;

  if v_tx.status <> 'PENDING'::public.transaction_status then
    raise exception 'only pending transactions can have voucher metadata edited'
      using errcode = '55000';
  end if;

  v_can_approve := app_private.wms_has_action(
    'wms.transaction.approve',
    v_tx.source_warehouse_id,
    v_tx.target_warehouse_id,
    v_tx.requester_id,
    v_tx.approver_id,
    v_user.id
  );

  if v_tx.requester_id is distinct from v_user.id and not v_can_approve then
    raise exception 'insufficient privilege to edit voucher metadata'
      using errcode = '42501';
  end if;

  if p_date is null then
    raise exception 'voucher date is required';
  end if;

  update public.transactions
  set date = p_date,
      note = nullif(trim(coalesce(p_note, '')), ''),
      updated_by = v_user.id
  where id = v_tx.id
  returning * into v_tx;

  return v_tx;
end;
$$;


--
-- Name: update_unreceived_delivery_batch_v2(uuid, text, text, uuid, text, text, text, numeric, text, date, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_unreceived_delivery_batch_v2(p_delivery_batch_id uuid, p_wms_transaction_id text, p_purchase_order_id text, p_idempotency_key uuid, p_supplier_id text, p_supplier_name text, p_fulfillment_mode text, p_vat_rate numeric, p_target_warehouse_id text, p_planned_delivery_date date DEFAULT NULL::date, p_note text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid, p_lines jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := coalesce(p_actor_user_id, public.current_app_user_id());
  v_previous_context text;
  v_result jsonb;
begin
  if public.current_app_user_id() is null or v_actor <> public.current_app_user_id() then
    raise exception 'Người thực hiện lệnh không hợp lệ.' using errcode = '42501';
  end if;
  v_previous_context := current_setting('app.material_po_logistics_context', true);
  perform set_config('app.material_po_logistics_context', 'confirm', true);
  v_result := app_private.update_unreceived_delivery_batch_v2(
    p_delivery_batch_id, p_wms_transaction_id, p_purchase_order_id,
    p_idempotency_key, p_supplier_id, p_supplier_name, p_fulfillment_mode,
    p_vat_rate, p_target_warehouse_id, p_planned_delivery_date, p_note,
    v_actor, p_lines
  );
  perform set_config('app.material_po_logistics_context', coalesce(v_previous_context, ''), true);
  return v_result;
exception when others then
  perform set_config('app.material_po_logistics_context', coalesce(v_previous_context, ''), true);
  raise;
end;
$$;


