--
-- Name: upsert_hrm_document_metadata(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_hrm_document_metadata(p_document jsonb, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := public.current_app_user_id();
  v_id uuid;
  v_row public.hrm_documents%rowtype;
  v_subject_employee_id uuid;
begin
  if not app_private.has_hrm_template_permission(v_actor_id, 'hrm.document.manage') then
    raise exception using errcode = '42501', message = 'HRM_DOCUMENT_MANAGE_REQUIRED';
  end if;
  perform app_private.assert_hrm_mutation_context(p_reason, 'document-command');
  v_id := coalesce(nullif(p_document->>'id','')::uuid, gen_random_uuid());
  insert into public.hrm_documents(
    id,doc_type,doc_category,employee_id,title,doc_number,description,sender,receiver,
    signed_by,assigned_to,doc_date,deadline,status,file_name,file_type,file_size,
    storage_path,tags,uploaded_by
  ) values (
    v_id,p_document->>'docType',p_document->>'docCategory',nullif(p_document->>'employeeId',''),
    p_document->>'title',nullif(p_document->>'docNumber',''),nullif(p_document->>'description',''),
    nullif(p_document->>'sender',''),nullif(p_document->>'receiver',''),nullif(p_document->>'signedBy',''),
    nullif(p_document->>'assignedTo',''),nullif(p_document->>'docDate','')::date,
    nullif(p_document->>'deadline','')::date,coalesce(nullif(p_document->>'status',''),'active'),
    p_document->>'fileName',p_document->>'fileType',coalesce((p_document->>'fileSize')::bigint,0),
    p_document->>'storagePath',coalesce(array(select jsonb_array_elements_text(coalesce(p_document->'tags','[]'::jsonb))),array[]::text[]),
    nullif(p_document->>'uploadedBy','')
  ) on conflict (id) do update set
    status=excluded.status,title=excluded.title,doc_number=excluded.doc_number,
    description=excluded.description,deadline=excluded.deadline,tags=excluded.tags,updated_at=now()
  returning * into v_row;
  select employee.id into v_subject_employee_id
  from public.employees employee
  where employee.id::text = v_row.employee_id;
  perform app_private.audit_hrm_profile_command(
    coalesce(v_subject_employee_id, v_actor_id), 'HRM_DOCUMENT', v_id::text,
    'UPSERT', p_reason, array['document_metadata','storage_path']
  );
  return to_jsonb(v_row);
end;
$$;


--
-- Name: upsert_hrm_employee_bank_account(uuid, text, text, text, text, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_hrm_employee_bank_account(p_employee_id uuid, p_record_code text, p_bank_code text, p_branch_name text, p_account_number text, p_account_holder text, p_is_payroll_account boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_actor_id uuid := public.current_app_user_id();
begin
  if not app_private.has_hrm_template_permission(v_actor_id, 'hrm.compensation.manage') then
    raise exception using errcode = '42501', message = 'HRM_COMPENSATION_MANAGE_REQUIRED';
  end if;
  perform app_private.assert_hrm_mutation_context(p_reason, 'profile-command');
  if p_is_payroll_account then
    update public.hrm_employee_bank_accounts set is_payroll_account = false,
      updated_by = v_actor_id, updated_at = now()
    where employee_id = p_employee_id and is_payroll_account;
  end if;
  insert into public.hrm_employee_bank_accounts(
    employee_id, record_code, bank_code, branch_name, account_number,
    account_holder, is_payroll_account, created_by, updated_by
  ) values (
    p_employee_id, trim(p_record_code), trim(p_bank_code), nullif(trim(p_branch_name), ''),
    trim(p_account_number), trim(p_account_holder), p_is_payroll_account,
    v_actor_id, v_actor_id
  ) on conflict (employee_id, record_code) do update set
    bank_code = excluded.bank_code, branch_name = excluded.branch_name,
    account_number = excluded.account_number, account_holder = excluded.account_holder,
    is_payroll_account = excluded.is_payroll_account, status = 'ACTIVE',
    updated_by = v_actor_id, updated_at = now();
  perform app_private.audit_hrm_profile_command(
    p_employee_id, 'HRM_BANK_ACCOUNT', trim(p_record_code), 'UPSERT', p_reason,
    array['bank_code','branch_name','account_number','account_holder','is_payroll_account']
  );
  return app_private.get_hrm_employee_compensation_tax_bank(p_employee_id);
end;
$$;


--
-- Name: upsert_hrm_employee_certification(uuid, text, text, text, text, text, date, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_hrm_employee_certification(p_employee_id uuid, p_record_code text, p_certification_type_code text, p_certification_name text, p_certificate_number text, p_issuer_name text, p_issued_date date, p_expiry_date date, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_actor_id uuid := public.current_app_user_id();
begin
  if not app_private.has_hrm_template_permission(v_actor_id, 'hrm.document.manage') then
    raise exception using errcode = '42501', message = 'HRM_DOCUMENT_MANAGE_REQUIRED';
  end if;
  perform app_private.assert_hrm_mutation_context(p_reason, 'profile-command');
  if length(trim(coalesce(p_record_code, ''))) = 0
    or length(trim(coalesce(p_certification_name, ''))) = 0
  then raise exception using errcode = '22023', message = 'HRM_CERTIFICATION_INPUT_INVALID';
  end if;
  insert into public.hrm_employee_certifications(
    employee_id, record_code, certification_type_code, certification_name,
    certificate_number, issuer_name, issued_date, expiry_date, created_by, updated_by
  ) values (
    p_employee_id, trim(p_record_code), nullif(trim(p_certification_type_code), ''),
