--
-- Name: app_responsibility_slots; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.app_responsibility_slots (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    subject_type text NOT NULL,
    responsibility text NOT NULL,
    scope_type text NOT NULL,
    scope_id text NOT NULL,
    assignee_user_id uuid NOT NULL,
    permission_code text NOT NULL,
    priority integer DEFAULT 100 NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    starts_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT app_responsibility_slots_effective_range_check CHECK (((expires_at IS NULL) OR (expires_at > starts_at))),
    CONSTRAINT app_responsibility_slots_permission_check CHECK ((((responsibility = 'current_verifier'::text) AND (permission_code = 'project.daily_log.verify'::text)) OR ((responsibility = 'current_approver'::text) AND (permission_code = 'project.daily_log.approve'::text)))),
    CONSTRAINT app_responsibility_slots_permission_code_check CHECK ((permission_code = ANY (ARRAY['project.daily_log.verify'::text, 'project.daily_log.approve'::text]))),
    CONSTRAINT app_responsibility_slots_responsibility_check CHECK ((responsibility = ANY (ARRAY['current_verifier'::text, 'current_approver'::text]))),
    CONSTRAINT app_responsibility_slots_scope_check CHECK ((((scope_type = 'global'::text) AND (scope_id = '*'::text)) OR ((scope_type = ANY (ARRAY['project'::text, 'construction_site'::text])) AND (NULLIF(btrim(scope_id), ''::text) IS NOT NULL)))),
    CONSTRAINT app_responsibility_slots_scope_type_check CHECK ((scope_type = ANY (ARRAY['global'::text, 'project'::text, 'construction_site'::text]))),
    CONSTRAINT app_responsibility_slots_status_check CHECK ((status = ANY (ARRAY['active'::text, 'inactive'::text]))),
    CONSTRAINT app_responsibility_slots_subject_type_check CHECK ((subject_type = 'daily_log'::text))
);


