    CONSTRAINT authorization_override_events_check CHECK ((expires_at > starts_at)),
    CONSTRAINT authorization_override_events_reason_check CHECK ((char_length(btrim(reason)) >= 10)),
    CONSTRAINT authorization_override_events_scope_type_check CHECK ((scope_type = ANY (ARRAY['global'::text, 'own'::text, 'assigned'::text, 'project'::text, 'construction_site'::text, 'warehouse'::text, 'department'::text]))),
