);


--
-- Name: authorization_sod_rules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.authorization_sod_rules (
    rule_code text NOT NULL,
    name text NOT NULL,
    description text NOT NULL,
    rule_type text NOT NULL,
    effect text NOT NULL,
    left_permission_code text,
    right_permission_code text,
    operation_code text,
    subject_type text,
    overridable boolean DEFAULT false NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT authorization_sod_rules_check CHECK (((effect <> 'DENY'::text) OR (NOT overridable))),
    CONSTRAINT authorization_sod_rules_check1 CHECK (((effect <> 'REQUIRE_OVERRIDE'::text) OR overridable)),
    CONSTRAINT authorization_sod_rules_check2 CHECK (((rule_type <> 'PERMISSION_PAIR'::text) OR ((left_permission_code IS NOT NULL) AND (right_permission_code IS NOT NULL)))),
    CONSTRAINT authorization_sod_rules_check3 CHECK (((rule_type <> 'SUBJECT_RELATION'::text) OR ((operation_code IS NOT NULL) AND (subject_type IS NOT NULL)))),
    CONSTRAINT authorization_sod_rules_effect_check CHECK ((effect = ANY (ARRAY['DENY'::text, 'WARN'::text, 'REQUIRE_OVERRIDE'::text]))),
    CONSTRAINT authorization_sod_rules_rule_type_check CHECK ((rule_type = ANY (ARRAY['SELF_GRANT'::text, 'PERMISSION_PAIR'::text, 'SUBJECT_RELATION'::text])))
);


