    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT internal_norms_confidence_score_check CHECK (((confidence_score IS NULL) OR ((confidence_score >= (0)::numeric) AND (confidence_score <= (1)::numeric)))),
    CONSTRAINT internal_norms_effective_range_chk CHECK (((effective_to IS NULL) OR (effective_to >= effective_from))),
    CONSTRAINT internal_norms_norm_quantity_check CHECK ((norm_quantity >= (0)::numeric)),
    CONSTRAINT internal_norms_resource_type_check CHECK ((resource_type = ANY (ARRAY['material'::text, 'labor'::text, 'machine'::text, 'subcontract'::text, 'overhead'::text, 'other'::text]))),
    CONSTRAINT internal_norms_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'archived'::text]))),
    CONSTRAINT internal_norms_version_no_check CHECK ((version_no > 0)),
    CONSTRAINT internal_norms_waste_percent_check CHECK ((waste_percent >= (0)::numeric))
);


