 SELECT id,
    operator_user_id,
    start_at,
    end_at,
    created_at
   FROM app_private.operator_unavailability_calendar_rows(public.current_app_user_id()) operator_unavailability_calendar_rows(id, operator_user_id, start_at, end_at, created_at);


