    CONSTRAINT project_opening_balances_contract_value_check CHECK ((contract_value >= (0)::numeric)),
    CONSTRAINT project_opening_balances_issued_value_check CHECK ((issued_value >= (0)::numeric)),
    CONSTRAINT project_opening_balances_progress_snapshot_status_check CHECK ((progress_snapshot_status = ANY (ARRAY['pending'::text, 'synced'::text]))),
    CONSTRAINT project_opening_balances_purchased_value_check CHECK ((purchased_value >= (0)::numeric)),
