    CONSTRAINT project_opening_balances_scope_check CHECK (((project_id IS NOT NULL) OR (construction_site_id IS NOT NULL))),
    CONSTRAINT project_opening_balances_stock_transaction_ids_check CHECK ((jsonb_typeof(stock_transaction_ids) = 'array'::text)),
    CONSTRAINT project_opening_balances_used_value_check CHECK ((used_value >= (0)::numeric))
);


