--
-- Name: purchase_package_v2_anomalies; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.purchase_package_v2_anomalies WITH (security_invoker='true') AS
 SELECT 'completed_wms_batch_not_received'::text AS anomaly_type,
    batch.purchase_order_id,
    batch.id AS delivery_batch_id,
    tx.id AS wms_transaction_id,
    po.project_id,
    po.construction_site_id,
    jsonb_build_object('deliveryStatus', batch.status, 'wmsStatus', tx.status, 'deliveryNo', batch.delivery_no) AS details,
    now() AS detected_at
   FROM ((public.purchase_order_delivery_batches batch
     JOIN public.purchase_orders po ON ((po.id = batch.purchase_order_id)))
     JOIN public.transactions tx ON ((tx.id = batch.wms_transaction_id)))
  WHERE ((tx.source_type = 'po_delivery_batch'::text) AND (tx.source_id = (batch.id)::text) AND (tx.status = 'COMPLETED'::public.transaction_status) AND (batch.status <> ALL (ARRAY['received'::text, 'received_short'::text, 'received_over'::text, 'cancelled'::text])) AND app_private.ap_scope_can_view(po.project_id, po.construction_site_id))
UNION ALL
 SELECT 'received_batch_wms_not_completed'::text AS anomaly_type,
    batch.purchase_order_id,
    batch.id AS delivery_batch_id,
    tx.id AS wms_transaction_id,
    po.project_id,
    po.construction_site_id,
    jsonb_build_object('deliveryStatus', batch.status, 'wmsStatus', tx.status, 'deliveryNo', batch.delivery_no) AS details,
    now() AS detected_at
   FROM ((public.purchase_order_delivery_batches batch
     JOIN public.purchase_orders po ON ((po.id = batch.purchase_order_id)))
     LEFT JOIN public.transactions tx ON ((tx.id = batch.wms_transaction_id)))
  WHERE ((batch.status = ANY (ARRAY['received'::text, 'received_short'::text, 'received_over'::text])) AND ((tx.id IS NULL) OR (tx.status <> 'COMPLETED'::public.transaction_status)) AND app_private.ap_scope_can_view(po.project_id, po.construction_site_id))
UNION ALL
 SELECT 'multiple_active_wms_for_batch'::text AS anomaly_type,
    batch.purchase_order_id,
    batch.id AS delivery_batch_id,
    NULL::text AS wms_transaction_id,
    po.project_id,
    po.construction_site_id,
    jsonb_build_object('activeWmsCount', count(tx.id), 'wmsTransactionIds', jsonb_agg(tx.id ORDER BY tx.id)) AS details,
    now() AS detected_at
   FROM ((public.purchase_order_delivery_batches batch
     JOIN public.purchase_orders po ON ((po.id = batch.purchase_order_id)))
     JOIN public.transactions tx ON (((tx.source_type = 'po_delivery_batch'::text) AND (tx.source_id = (batch.id)::text) AND (tx.status <> 'CANCELLED'::public.transaction_status))))
  WHERE app_private.ap_scope_can_view(po.project_id, po.construction_site_id)
  GROUP BY batch.purchase_order_id, batch.id, po.project_id, po.construction_site_id
 HAVING (count(tx.id) > 1)
UNION ALL
 SELECT 'po_received_without_payable'::text AS anomaly_type,
    batch.purchase_order_id,
    batch.id AS delivery_batch_id,
    batch.wms_transaction_id,
    po.project_id,
    po.construction_site_id,
    jsonb_build_object('deliveryStatus', batch.status, 'expectedSourceType', 'purchase_delivery_receipt') AS details,
    now() AS detected_at
   FROM (public.purchase_order_delivery_batches batch
     JOIN public.purchase_orders po ON ((po.id = batch.purchase_order_id)))
  WHERE ((batch.status = ANY (ARRAY['received'::text, 'received_short'::text, 'received_over'::text])) AND (NOT (EXISTS ( SELECT 1
           FROM public.supplier_payable_documents ap
          WHERE ((ap.source_type = 'purchase_delivery_receipt'::text) AND (ap.source_id = (batch.id)::text) AND (ap.status <> ALL (ARRAY['cancelled'::text, 'reversed'::text])))))) AND app_private.ap_scope_can_view(po.project_id, po.construction_site_id))
UNION ALL
 SELECT 'po_received_without_cost'::text AS anomaly_type,
    batch.purchase_order_id,
    batch.id AS delivery_batch_id,
    batch.wms_transaction_id,
    po.project_id,
    po.construction_site_id,
    jsonb_build_object('deliveryStatus', batch.status, 'expectedSourceRef', ('purchase_receipt:'::text || (batch.id)::text)) AS details,
    now() AS detected_at
   FROM (public.purchase_order_delivery_batches batch
     JOIN public.purchase_orders po ON ((po.id = batch.purchase_order_id)))
  WHERE ((batch.status = ANY (ARRAY['received'::text, 'received_short'::text, 'received_over'::text])) AND (NOT (EXISTS ( SELECT 1
           FROM public.project_transactions pt
          WHERE (pt.source_ref = ('purchase_receipt:'::text || (batch.id)::text))))) AND app_private.ap_scope_can_view(po.project_id, po.construction_site_id))
UNION ALL
 SELECT 'payment_expense_duplicate_risk'::text AS anomaly_type,
    NULL::text AS purchase_order_id,
    NULL::uuid AS delivery_batch_id,
    NULL::text AS wms_transaction_id,
    pt.project_id,
    pt.construction_site_id,
    jsonb_build_object('projectTransactionId', pt.id, 'sourceRef', pt.source_ref, 'amount', pt.amount, 'description', pt.description) AS details,
    now() AS detected_at
   FROM public.project_transactions pt
  WHERE ((pt.type = 'expense'::text) AND ((pt.source_ref ~~* 'supplier_payment:%'::text) OR (pt.description ~~* '%thanh toán%ncc%'::text) OR (pt.description ~~* '%payment% supplier%'::text)) AND app_private.ap_scope_can_view(pt.project_id, pt.construction_site_id))
UNION ALL
 SELECT 'purchase_stock_unit_mismatch'::text AS anomaly_type,
    batch.purchase_order_id,
    batch.id AS delivery_batch_id,
    batch.wms_transaction_id,
    po.project_id,
    po.construction_site_id,
    jsonb_build_object('deliveryLineId', line.id, 'purchaseOrderLineId', line.purchase_order_line_id, 'plannedQty', line.planned_qty, 'stockPlannedQty', line.stock_planned_qty, 'purchaseUnit', line.unit, 'stockUnit', line.stock_unit) AS details,
    now() AS detected_at
   FROM ((public.purchase_order_delivery_lines line
     JOIN public.purchase_order_delivery_batches batch ON ((batch.id = line.delivery_batch_id)))
     JOIN public.purchase_orders po ON ((po.id = batch.purchase_order_id)))
  WHERE ((COALESCE(line.planned_qty, (0)::numeric) > (0)::numeric) AND (COALESCE(line.stock_planned_qty, (0)::numeric) <= (0)::numeric) AND (COALESCE(line.unit, ''::text) <> COALESCE(line.stock_unit, ''::text)) AND app_private.ap_scope_can_view(po.project_id, po.construction_site_id))
UNION ALL
 SELECT 'legacy_delivery_group_only'::text AS anomaly_type,
    grp.purchase_order_id,
    NULL::uuid AS delivery_batch_id,
    mrf.transaction_id AS wms_transaction_id,
    po.project_id,
    po.construction_site_id,
    jsonb_build_object('fulfillmentBatchId', mrf.id, 'poDeliveryGroupId', mrf.po_delivery_group_id, 'poDeliveryBatchId', mrf.po_delivery_batch_id, 'batchNo', mrf.batch_no) AS details,
    now() AS detected_at
   FROM ((public.material_request_fulfillment_batches mrf
     JOIN public.purchase_order_delivery_groups grp ON ((grp.id = mrf.po_delivery_group_id)))
     JOIN public.purchase_orders po ON ((po.id = grp.purchase_order_id)))
  WHERE ((mrf.po_delivery_group_id IS NOT NULL) AND (mrf.po_delivery_batch_id IS NULL) AND (po.source_mode = 'from_request'::text) AND app_private.ap_scope_can_view(po.project_id, po.construction_site_id));


