    allow_non_home_base_return boolean DEFAULT false NOT NULL,
    non_home_base_return_reason text,
    external_service_type text,
    external_provider_name text,
    external_driver_name text,
    external_driver_phone text,
    external_vehicle_plate text,
    external_estimated_cost numeric(12,2),
    external_actual_cost numeric(12,2),
    external_currency text DEFAULT 'VND'::text NOT NULL,
    external_receipt_path text,
    dispatch_reason_code text,
    operator_confirmation_status text DEFAULT 'PENDING'::text,
    operator_confirmed_at timestamp with time zone,
    operator_decline_reason text,
    assigned_by_user_id uuid NOT NULL,
    assigned_at timestamp with time zone DEFAULT now() NOT NULL,
    assignment_note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    scheduled_range tstzrange GENERATED ALWAYS AS (tstzrange(reserved_start_at, reserved_end_at, '[)'::text)) STORED,
    CONSTRAINT check_assignment_reserved_time_valid CHECK ((reserved_end_at > reserved_start_at)),
    CONSTRAINT vehicle_assignment_fulfillment_shape_check CHECK ((((fulfillment_type = 'INTERNAL_WITH_DRIVER'::text) AND (vehicle_asset_id IS NOT NULL) AND (operator_user_id IS NOT NULL) AND (operator_type = 'PROFESSIONAL_DRIVER'::text) AND (external_service_type IS NULL)) OR ((fulfillment_type = 'INTERNAL_SELF_DRIVE'::text) AND (vehicle_asset_id IS NOT NULL) AND (operator_user_id IS NOT NULL) AND (operator_type = 'SELF_DRIVER'::text) AND (handover_officer_user_id IS NOT NULL) AND (external_service_type IS NULL)) OR ((fulfillment_type = 'EXTERNAL_TRANSPORT'::text) AND (vehicle_asset_id IS NULL) AND (operator_user_id IS NULL) AND (operator_type IS NULL) AND (handover_officer_user_id IS NULL) AND (NULLIF(TRIM(BOTH FROM external_service_type), ''::text) IS NOT NULL)))),
    CONSTRAINT vehicle_assignment_non_home_base_reason_check CHECK (((NOT allow_non_home_base_return) OR (NULLIF(TRIM(BOTH FROM non_home_base_return_reason), ''::text) IS NOT NULL))),
    CONSTRAINT vehicle_booking_assignments_external_actual_cost_check CHECK ((external_actual_cost >= (0)::numeric)),
    CONSTRAINT vehicle_booking_assignments_external_estimated_cost_check CHECK ((external_estimated_cost >= (0)::numeric)),
    CONSTRAINT vehicle_booking_assignments_fulfillment_type_check CHECK ((fulfillment_type = ANY (ARRAY['INTERNAL_WITH_DRIVER'::text, 'INTERNAL_SELF_DRIVE'::text, 'EXTERNAL_TRANSPORT'::text]))),
    CONSTRAINT vehicle_booking_assignments_operator_confirmation_status_check CHECK ((operator_confirmation_status = ANY (ARRAY['PENDING'::text, 'CONFIRMED'::text, 'DECLINED'::text]))),
    CONSTRAINT vehicle_booking_assignments_operator_type_check CHECK ((operator_type = ANY (ARRAY['PROFESSIONAL_DRIVER'::text, 'SELF_DRIVER'::text])))
);


