--
-- Name: vehicle_bookings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.vehicle_bookings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    booking_code text NOT NULL,
    requester_user_id uuid NOT NULL,
    trip_owner_user_id uuid,
    requester_employee_id_snapshot uuid,
    department_id_snapshot uuid,
    manager_user_id_snapshot uuid,
    manager_resolution_status text DEFAULT 'NORMAL'::text,
    requested_pickup_at timestamp with time zone NOT NULL,
    expected_return_at timestamp with time zone NOT NULL,
    trip_type text NOT NULL,
    pickup_location_text text NOT NULL,
    destination_text text NOT NULL,
    route_stops jsonb DEFAULT '[]'::jsonb NOT NULL,
    purpose text NOT NULL,
    passenger_count integer NOT NULL,
    requested_mode text NOT NULL,
    preferred_vehicle_asset_id text,
    preferred_driver_user_id uuid,
    note text,
    status text DEFAULT 'DRAFT'::text NOT NULL,
    submitted_at timestamp with time zone,
    approved_by_user_id uuid,
    approved_at timestamp with time zone,
    approval_source text,
    approval_note text,
    cancelled_by_user_id uuid,
    cancelled_at timestamp with time zone,
    close_reason text,
    close_note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    manager_approval_route text,
    manager_bypass_confirmed_by_user_id uuid,
    manager_bypass_confirmed_at timestamp with time zone,
    CONSTRAINT check_booking_time_valid CHECK ((expected_return_at > requested_pickup_at)),
    CONSTRAINT vehicle_bookings_approval_source_check CHECK ((approval_source = ANY (ARRAY['MANAGER'::text, 'DISPATCH_OVERRIDE'::text]))),
    CONSTRAINT vehicle_bookings_close_reason_check CHECK ((close_reason = ANY (ARRAY['REJECTED_BY_MANAGER'::text, 'CANCELLED_BY_REQUESTER'::text, 'LATE_CANCELLED'::text, 'CANCELLED_BY_DISPATCHER'::text, 'NO_SHOW'::text, 'OTHER'::text]))),
    CONSTRAINT vehicle_bookings_manager_approval_route_check CHECK (((manager_approval_route IS NULL) OR (manager_approval_route = ANY (ARRAY['MANAGER'::text, 'CONFIG_DISABLED'::text, 'MISSING_MANAGER_BYPASS'::text, 'LEGACY'::text])))),
    CONSTRAINT vehicle_bookings_manager_resolution_status_check CHECK ((manager_resolution_status = ANY (ARRAY['NORMAL'::text, 'MISSING'::text, 'OVERRIDDEN'::text]))),
    CONSTRAINT vehicle_bookings_passenger_count_check CHECK ((passenger_count > 0)),
    CONSTRAINT vehicle_bookings_requested_mode_check CHECK ((requested_mode = ANY (ARRAY['WITH_DRIVER'::text, 'SELF_DRIVE'::text, 'FLEXIBLE'::text]))),
    CONSTRAINT vehicle_bookings_status_check CHECK ((status = ANY (ARRAY['DRAFT'::text, 'PENDING_APPROVAL'::text, 'WAITING_DISPATCH'::text, 'ASSIGNED'::text, 'IN_PROGRESS'::text, 'COMPLETED'::text, 'CANCELLED'::text]))),
    CONSTRAINT vehicle_bookings_trip_type_check CHECK ((trip_type = ANY (ARRAY['ONE_WAY'::text, 'ROUND_TRIP'::text, 'MULTI_STOP'::text, 'MULTI_DAY'::text])))
);


