-- Name: vehicle_driver_authorizations_eligible_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vehicle_driver_authorizations_eligible_v WITH (security_invoker='true', security_barrier='true') AS
 SELECT id,
    user_id,
    employee_id,
    authorization_type,
    license_class,
    license_expiry,
    allowed_vehicle_types,
    status,
    is_eligible
   FROM app_private.vehicle_driver_authorizations_eligible_rows(public.current_app_user_id()) vehicle_driver_authorizations_eligible_rows(id, user_id, employee_id, authorization_type, license_class, license_expiry, allowed_vehicle_types, status, is_eligible);


