--
-- Name: vehicle_trip_logs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.vehicle_trip_logs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    booking_id uuid NOT NULL,
    assignment_id uuid NOT NULL,
    assignment_version_snapshot integer NOT NULL,
    vehicle_asset_id_snapshot text,
    operator_user_id_snapshot uuid,
    trip_status text DEFAULT 'NOT_STARTED'::text NOT NULL,
    started_by_user_id uuid,
    departed_home_base_at timestamp with time zone,
    actual_pickup_at timestamp with time zone,
    start_odometer numeric(12,1),
    start_photo_path text,
    start_latitude numeric(10,7),
    start_longitude numeric(10,7),
    start_accuracy_m numeric(8,2),
    start_location_capture_failed boolean DEFAULT false NOT NULL,
    start_location_failure_reason text,
    finished_by_user_id uuid,
    actual_return_at timestamp with time zone,
    end_odometer numeric(12,1),
    end_photo_path text,
    end_latitude numeric(10,7),
    end_longitude numeric(10,7),
    end_accuracy_m numeric(8,2),
    end_location_capture_failed boolean DEFAULT false NOT NULL,
    end_location_failure_reason text,
    distance_km numeric(12,1),
    vehicle_condition_end text,
    issue_note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT check_odometer_range CHECK (((end_odometer IS NULL) OR (start_odometer IS NULL) OR (end_odometer >= start_odometer))),
    CONSTRAINT vehicle_trip_finish_evidence_check CHECK (((trip_status <> 'FINISHED'::text) OR ((end_odometer IS NOT NULL) AND (NULLIF(TRIM(BOTH FROM end_photo_path), ''::text) IS NOT NULL) AND (vehicle_condition_end IS NOT NULL) AND ((vehicle_condition_end <> 'ISSUE'::text) OR (NULLIF(TRIM(BOTH FROM issue_note), ''::text) IS NOT NULL)) AND (((NOT end_location_capture_failed) AND (end_latitude IS NOT NULL) AND (end_longitude IS NOT NULL)) OR (end_location_capture_failed AND (NULLIF(TRIM(BOTH FROM end_location_failure_reason), ''::text) IS NOT NULL)))))),
    CONSTRAINT vehicle_trip_logs_distance_km_check CHECK ((distance_km >= (0)::numeric)),
    CONSTRAINT vehicle_trip_logs_end_latitude_check CHECK (((end_latitude >= ('-90'::integer)::numeric) AND (end_latitude <= (90)::numeric))),
    CONSTRAINT vehicle_trip_logs_end_longitude_check CHECK (((end_longitude >= ('-180'::integer)::numeric) AND (end_longitude <= (180)::numeric))),
    CONSTRAINT vehicle_trip_logs_end_odometer_check CHECK ((end_odometer >= (0)::numeric)),
    CONSTRAINT vehicle_trip_logs_start_latitude_check CHECK (((start_latitude >= ('-90'::integer)::numeric) AND (start_latitude <= (90)::numeric))),
    CONSTRAINT vehicle_trip_logs_start_longitude_check CHECK (((start_longitude >= ('-180'::integer)::numeric) AND (start_longitude <= (180)::numeric))),
    CONSTRAINT vehicle_trip_logs_start_odometer_check CHECK ((start_odometer >= (0)::numeric)),
    CONSTRAINT vehicle_trip_logs_trip_status_check CHECK ((trip_status = ANY (ARRAY['NOT_STARTED'::text, 'IN_PROGRESS'::text, 'FINISHED'::text]))),
    CONSTRAINT vehicle_trip_logs_vehicle_condition_end_check CHECK ((vehicle_condition_end = ANY (ARRAY['NORMAL'::text, 'ISSUE'::text]))),
    CONSTRAINT vehicle_trip_start_evidence_check CHECK (((trip_status = 'NOT_STARTED'::text) OR ((start_odometer IS NOT NULL) AND (NULLIF(TRIM(BOTH FROM start_photo_path), ''::text) IS NOT NULL) AND (((NOT start_location_capture_failed) AND (start_latitude IS NOT NULL) AND (start_longitude IS NOT NULL)) OR (start_location_capture_failed AND (NULLIF(TRIM(BOTH FROM start_location_failure_reason), ''::text) IS NOT NULL))))))
);


