    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    mentions jsonb DEFAULT '[]'::jsonb NOT NULL,
    CONSTRAINT workflow_instance_comments_content_check CHECK (
CASE
    WHEN (jsonb_typeof(attachments) = 'array'::text) THEN ((jsonb_array_length(attachments) <= 5) AND (length(body) <= 4000) AND ((length(TRIM(BOTH FROM body)) > 0) OR (jsonb_array_length(attachments) > 0)))
    ELSE false
END),
    CONSTRAINT workflow_instance_comments_mentions_check CHECK (((jsonb_typeof(mentions) = 'array'::text) AND (jsonb_array_length(mentions) <= 20)))
);


