--

CREATE TABLE public.workflow_subject_comments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workflow_subject_id uuid NOT NULL,
    workflow_instance_id uuid,
    subject_type text NOT NULL,
    subject_id text NOT NULL,
    project_id text,
    construction_site_id text,
    author_user_id uuid NOT NULL,
    body text DEFAULT ''::text NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    attachments jsonb DEFAULT '[]'::jsonb NOT NULL,
    CONSTRAINT workflow_subject_comments_content_check CHECK (((jsonb_typeof(attachments) = 'array'::text) AND (length(body) <= 4000) AND ((length(TRIM(BOTH FROM body)) > 0) OR (jsonb_array_length(attachments) > 0))))
);


--
-- Name: workflow_template_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workflow_template_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    template_id uuid NOT NULL,
    version_number integer NOT NULL,
    name text NOT NULL,
    description text,
    custom_fields jsonb DEFAULT '[]'::jsonb NOT NULL,
    managers text[] DEFAULT '{}'::text[] NOT NULL,
    default_watchers text[] DEFAULT '{}'::text[] NOT NULL,
    snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
