-- Name: asset_assignments asset_assignments_delete_action; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY asset_assignments_delete_action ON public.asset_assignments FOR DELETE TO authenticated USING (false);


--
-- Name: asset_assignments asset_assignments_insert_action; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY asset_assignments_insert_action ON public.asset_assignments FOR INSERT TO authenticated WITH CHECK (
CASE
    WHEN (type = 'assign'::public.asset_assignment_type) THEN app_private.asset_record_has_action('asset.assignment.assign'::text, asset_id, NULL::text, user_id)
    WHEN (type = 'return'::public.asset_assignment_type) THEN app_private.asset_record_has_action('asset.assignment.return'::text, asset_id, NULL::text, COALESCE(from_user_id, user_id))
    WHEN (type = 'transfer'::public.asset_assignment_type) THEN (app_private.asset_record_has_action('asset.assignment.transfer'::text, asset_id, NULL::text, COALESCE(from_user_id, user_id)) AND app_private.asset_record_has_action('asset.assignment.transfer'::text, asset_id, NULL::text, user_id))
    ELSE false
END);


