-- Name: asset_assignments asset_assignments_select_action; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY asset_assignments_select_action ON public.asset_assignments FOR SELECT TO authenticated USING ((app_private.asset_record_has_action('asset.assignment.view'::text, asset_id, NULL::text, user_id) OR app_private.asset_record_has_action('asset.assignment.view'::text, asset_id, NULL::text, from_user_id)));


