--
-- Name: workflow_instances wf_inst_delete; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY wf_inst_delete ON public.workflow_instances FOR DELETE TO authenticated USING (((NOT (EXISTS ( SELECT 1
   FROM public.workflow_subjects ws
  WHERE (ws.workflow_instance_id = workflow_instances.id)))) AND (public.is_admin() OR (created_by = public.current_app_user_id()))));


--
-- Name: workflow_instances wf_inst_select; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY wf_inst_select ON public.workflow_instances FOR SELECT TO authenticated USING (app_private.project_workflow_instance_can_select(id));


--
-- Name: workflow_instances wf_inst_update; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY wf_inst_update ON public.workflow_instances FOR UPDATE TO authenticated USING ((public.is_module_admin('WF'::text) OR (created_by = public.current_app_user_id()) OR (EXISTS ( SELECT 1
   FROM public.workflow_templates wt
  WHERE ((wt.id = workflow_instances.template_id) AND ((public.current_app_user_id())::text = ANY (COALESCE(wt.managers, '{}'::text[])))))) OR (EXISTS ( SELECT 1
   FROM (public.workflow_nodes wn
     LEFT JOIN public.users u ON ((u.id = public.current_app_user_id())))
  WHERE ((wn.id = workflow_instances.current_node_id) AND ((COALESCE((workflow_instances.step_assignees ->> (workflow_instances.current_node_id)::text), ''::text) = (public.current_app_user_id())::text) OR (COALESCE((wn.config ->> 'assigneeUserId'::text), ''::text) = (public.current_app_user_id())::text) OR ((u.id IS NOT NULL) AND (COALESCE((wn.config ->> 'assigneeRole'::text), ''::text) = (u.role)::text)))))))) WITH CHECK ((public.is_module_admin('WF'::text) OR (created_by = public.current_app_user_id()) OR (EXISTS ( SELECT 1
   FROM public.workflow_templates wt
  WHERE ((wt.id = workflow_instances.template_id) AND ((public.current_app_user_id())::text = ANY (COALESCE(wt.managers, '{}'::text[])))))) OR (EXISTS ( SELECT 1
   FROM (public.workflow_nodes wn
     LEFT JOIN public.users u ON ((u.id = public.current_app_user_id())))
  WHERE ((wn.id = workflow_instances.current_node_id) AND ((COALESCE((workflow_instances.step_assignees ->> (workflow_instances.current_node_id)::text), ''::text) = (public.current_app_user_id())::text) OR (COALESCE((wn.config ->> 'assigneeUserId'::text), ''::text) = (public.current_app_user_id())::text) OR ((u.id IS NOT NULL) AND (COALESCE((wn.config ->> 'assigneeRole'::text), ''::text) = (u.role)::text))))))));


