CREATE POLICY wf_logs_delete ON public.workflow_instance_logs FOR DELETE TO authenticated USING ((public.is_module_admin('WF'::text) OR (EXISTS ( SELECT 1
   FROM (public.workflow_instances wi
     LEFT JOIN public.workflow_templates wt ON ((wt.id = wi.template_id)))
  WHERE ((wi.id = workflow_instance_logs.instance_id) AND ((wi.created_by = public.current_app_user_id()) OR ((public.current_app_user_id())::text = ANY (COALESCE(wt.managers, '{}'::text[])))))))));


